export const hdnkSentences: Sentence[] = [
  {"id":"s_work_hdnk_1_1","chapterId":"ch_work_hdnk_1","text":"上古天真論篇第一","sortOrder":1},
  {"id":"s_work_hdnk_1_2","chapterId":"ch_work_hdnk_1","text":"昔在黃帝，生而神靈，弱而能言，幼而徇齊，長而敦敏，成而登天。","sortOrder":2},
  {"id":"s_work_hdnk_1_3","chapterId":"ch_work_hdnk_1","text":"乃問於天師曰：餘聞上古之人，春秋皆度百歲，而動作不衰；今時之人，年半百而動作皆衰者。時世異耶人將失之耶？","sortOrder":3},
  {"id":"s_work_hdnk_1_4","chapterId":"ch_work_hdnk_1","text":"岐伯對曰：上古之人？其知道者，法於陰陽，和於術數，食飲有節，起居有常，不妄作勞，故能形與神俱，而盡終其天年，度百歲乃去。","sortOrder":4},
  {"id":"s_work_hdnk_1_5","chapterId":"ch_work_hdnk_1","text":"今時之人不然也，以酒為漿，以妄為常，醉以入房，以欲竭其精，以耗散其真，不知持滿，不時御神，務快其心，逆於生樂，起居無節，故半百而衰也。","sortOrder":5},
  {"id":"s_work_hdnk_1_6","chapterId":"ch_work_hdnk_1","text":"夫上古聖人之教下也，皆謂之虛邪賊風避之有時，恬惔虛無，真氣從之，精神內守，病安從來。","sortOrder":6},
  {"id":"s_work_hdnk_1_7","chapterId":"ch_work_hdnk_1","text":"是以志閑而少欲，心安而不懼，形勞而不倦，氣從以順，各從其欲，皆得所願。故美其食，任其服，樂其俗，高下不相慕，其民故曰樸。","sortOrder":7},
  {"id":"s_work_hdnk_1_8","chapterId":"ch_work_hdnk_1","text":"是以嗜欲不能勞其目，淫邪不能惑其心，愚智賢不肖，不懼於物，故合於道。","sortOrder":8},
  {"id":"s_work_hdnk_1_9","chapterId":"ch_work_hdnk_1","text":"所以能年皆度百歲而動作不衰者，以其德全不危也。","sortOrder":9},
  {"id":"s_work_hdnk_1_10","chapterId":"ch_work_hdnk_1","text":"帝曰：人年老而無子者，材力盡邪？將天數然也？","sortOrder":10},
  {"id":"s_work_hdnk_1_11","chapterId":"ch_work_hdnk_1","text":"岐伯曰：女子七歲腎氣盛，齒更髮長。","sortOrder":11},
  {"id":"s_work_hdnk_1_12","chapterId":"ch_work_hdnk_1","text":"二七而天癸至，任脈通，太沖脈盛，月事以時下，故有子。","sortOrder":12},
  {"id":"s_work_hdnk_1_13","chapterId":"ch_work_hdnk_1","text":"三七腎氣平均，故真牙生而長極。","sortOrder":13},
  {"id":"s_work_hdnk_1_14","chapterId":"ch_work_hdnk_1","text":"四七筋骨堅，髮長極，身體盛壯。","sortOrder":14},
  {"id":"s_work_hdnk_1_15","chapterId":"ch_work_hdnk_1","text":"五七陽明脈衰，面始焦，髮始墮。","sortOrder":15},
  {"id":"s_work_hdnk_1_16","chapterId":"ch_work_hdnk_1","text":"六七三陽脈衰於上，面皆焦，髮始白。","sortOrder":16},
  {"id":"s_work_hdnk_1_17","chapterId":"ch_work_hdnk_1","text":"七七任脈虛，太沖脈衰少，天癸竭，地道不通，故形壞而無子也。","sortOrder":17},
  {"id":"s_work_hdnk_1_18","chapterId":"ch_work_hdnk_1","text":"丈夫八歲腎氣實，髮長齒更。","sortOrder":18},
  {"id":"s_work_hdnk_1_19","chapterId":"ch_work_hdnk_1","text":"二八腎氣盛，天癸至，精氣溢瀉，陰陽和，故能有子。","sortOrder":19},
  {"id":"s_work_hdnk_1_20","chapterId":"ch_work_hdnk_1","text":"三八腎氣平均，筋骨勁強，故真牙生而長極。","sortOrder":20},
  {"id":"s_work_hdnk_1_21","chapterId":"ch_work_hdnk_1","text":"四八筋骨隆盛，肌肉滿壯。","sortOrder":21},
  {"id":"s_work_hdnk_1_22","chapterId":"ch_work_hdnk_1","text":"五八腎氣衰，髮墮齒槁。","sortOrder":22},
  {"id":"s_work_hdnk_1_23","chapterId":"ch_work_hdnk_1","text":"六八陽氣衰竭於上，面焦，髮鬢頒白。","sortOrder":23},
  {"id":"s_work_hdnk_1_24","chapterId":"ch_work_hdnk_1","text":"七八肝氣衰，筋不能動，天癸竭，精少，腎臟衰，形體皆極。","sortOrder":24},
  {"id":"s_work_hdnk_1_25","chapterId":"ch_work_hdnk_1","text":"八八則齒髮去。","sortOrder":25},
  {"id":"s_work_hdnk_1_26","chapterId":"ch_work_hdnk_1","text":"腎者主水，受五臟六腑之精而藏之，故五臟盛，乃能瀉。","sortOrder":26},
  {"id":"s_work_hdnk_1_27","chapterId":"ch_work_hdnk_1","text":"今五臟皆衰，筋骨解墮，天癸盡矣，故髮鬢白，身體重，行步不正，而無子耳。","sortOrder":27},
  {"id":"s_work_hdnk_1_28","chapterId":"ch_work_hdnk_1","text":"帝曰：有其年已老，而有子者：何也？岐伯曰：此其天壽過度，氣脈常通，而腎氣有餘也。此雖有子，男子不過盡八八，女子不過盡七七，而天地之精氣皆竭矣。","sortOrder":28},
  {"id":"s_work_hdnk_1_29","chapterId":"ch_work_hdnk_1","text":"帝曰：夫道者年皆百歲，能有子乎？岐伯曰：夫道者能卻老而全形，身年雖壽，能生子也。","sortOrder":29},
  {"id":"s_work_hdnk_1_30","chapterId":"ch_work_hdnk_1","text":"黃帝曰：餘聞上古有真人者，提挈天地，把握陰陽，呼吸精氣，獨立守神，肌肉若一，故能壽敝天地，無有終時，此其道生。","sortOrder":30},
  {"id":"s_work_hdnk_1_31","chapterId":"ch_work_hdnk_1","text":"中古之時，有至人者，淳德全道，和於陰陽，調於四時，去世離俗，積精全神，遊行天地之間，視聽八遠之外，此蓋益其壽命而強者也。亦歸於真人。","sortOrder":31},
  {"id":"s_work_hdnk_1_32","chapterId":"ch_work_hdnk_1","text":"其次有聖人者，處天地之和，從八風之理，適嗜欲於世俗之間，無恚嗔之心，行不欲離於世，被服章，舉不欲觀於俗，外不勞形於事，內無思想之患，以恬愉為務，以自得為功，形體不敝，精神不散，亦可以百數。","sortOrder":32},
  {"id":"s_work_hdnk_1_33","chapterId":"ch_work_hdnk_1","text":"其次有賢人者，法則天地，象似日月，辨列星辰，逆從陰陽，分別四時，將從上古合同於道，亦可使益壽而有極時。","sortOrder":33},
  {"id":"s_work_hdnk_2_1","chapterId":"ch_work_hdnk_2","text":"四氣調神大論篇第二","sortOrder":1},
  {"id":"s_work_hdnk_2_2","chapterId":"ch_work_hdnk_2","text":"春三月，此為發陳。天地俱生，萬物以榮，夜臥早起，廣步於庭，被髮緩形，以使志生，生而勿殺，予而勿奪，賞而勿罰，此春氣之應，養生之道也；逆之則傷肝，夏為實寒變，奉長者少。","sortOrder":2},
  {"id":"s_work_hdnk_2_3","chapterId":"ch_work_hdnk_2","text":"夏三月，此為蕃秀。天地氣交，萬物華實，夜臥早起，無厭於日，使志勿怒，使華英成秀，使氣得泄，若所愛在外，此夏氣之應，養長之道也；逆之則傷心，秋為痎瘧，奉收者少，冬至重病。","sortOrder":3},
  {"id":"s_work_hdnk_2_4","chapterId":"ch_work_hdnk_2","text":"秋三月，此謂容平，天氣以急，地氣以明，早臥早起，與雞俱興，使志安寧，以緩秋刑，收斂神氣，使秋氣平，無外其志，使肺氣清，此秋氣之應，養收之道也；逆之則傷肺，冬為飧泄，奉藏者少。","sortOrder":4},
  {"id":"s_work_hdnk_2_5","chapterId":"ch_work_hdnk_2","text":"冬三月，此為閉藏。水冰地坼，勿擾乎陽，早臥晚起，必待日光，使志若伏若匿，若有私意，若已有得，去寒就溫，無泄皮膚，使氣極奪。此冬氣之應，養藏之道也；逆之則傷腎，春為痿厥，奉生者少。","sortOrder":5},
  {"id":"s_work_hdnk_2_6","chapterId":"ch_work_hdnk_2","text":"天氣清淨，光明者也，藏德不止，故不下也。","sortOrder":6},
  {"id":"s_work_hdnk_2_7","chapterId":"ch_work_hdnk_2","text":"天明則日月不明，邪害空竅。陽氣者閉塞，地氣者冒明，雲霧不精，則上應白露不下。","sortOrder":7},
  {"id":"s_work_hdnk_2_8","chapterId":"ch_work_hdnk_2","text":"交通不表，萬物命故不施，不施則名木多死。惡氣不發，風雨不節，白露不下，則菀藁不榮。賊風數至，暴雨數起，天地四時不相保，與道相失，則未央絕滅。","sortOrder":8},
  {"id":"s_work_hdnk_2_9","chapterId":"ch_work_hdnk_2","text":"唯聖人從之，故身無奇病，萬物不失，生氣不竭。","sortOrder":9},
  {"id":"s_work_hdnk_2_10","chapterId":"ch_work_hdnk_2","text":"逆春氣則少陽不生，肝氣內變。","sortOrder":10},
  {"id":"s_work_hdnk_2_11","chapterId":"ch_work_hdnk_2","text":"逆夏氣則太陽不長，心氣內洞。","sortOrder":11},
  {"id":"s_work_hdnk_2_12","chapterId":"ch_work_hdnk_2","text":"逆秋氣則太陰不收，肺氣焦滿。","sortOrder":12},
  {"id":"s_work_hdnk_2_13","chapterId":"ch_work_hdnk_2","text":"逆冬氣則少陰不藏，腎氣獨沉。","sortOrder":13},
  {"id":"s_work_hdnk_2_14","chapterId":"ch_work_hdnk_2","text":"夫四時陰陽者，萬物之根本也。所以聖人春夏養陽，秋冬養陰，以從其根；故與萬物沉浮於生長之門，逆其根則伐其本，壞其真矣。故陰陽四時者，萬物之終始也；生死之本也；逆之則災害生，從之則苛疾不起，是謂得道。道者聖人行之，愚者佩之。從陰陽則生，逆之則死；從之則治，逆之則亂。反順為逆，是謂內格。","sortOrder":14},
  {"id":"s_work_hdnk_2_15","chapterId":"ch_work_hdnk_2","text":"是故聖人不治己病，治未病不治己亂、治未亂，此之謂也。夫病已成而後藥之，亂己成而後治之，譬猶渴而穿井，鬥而鑄錐，不亦晚乎？","sortOrder":15},
  {"id":"s_work_hdnk_3_1","chapterId":"ch_work_hdnk_3","text":"生氣通天論篇第三","sortOrder":1},
  {"id":"s_work_hdnk_3_2","chapterId":"ch_work_hdnk_3","text":"黃帝曰：夫自古通天者，生之本，本於陰陽。","sortOrder":2},
  {"id":"s_work_hdnk_3_3","chapterId":"ch_work_hdnk_3","text":"天地之間，六合之內，其氣九州、九竅、五臟十二節，皆通乎天氣。","sortOrder":3},
  {"id":"s_work_hdnk_3_4","chapterId":"ch_work_hdnk_3","text":"其生五，其氣三，數犯此者，則邪氣傷人，此壽命之本也。","sortOrder":4},
  {"id":"s_work_hdnk_3_5","chapterId":"ch_work_hdnk_3","text":"蒼天之氣，清靜則志意治，順之則陽氣固，雖有賊邪，弗能害也，此因時之序。","sortOrder":5},
  {"id":"s_work_hdnk_3_6","chapterId":"ch_work_hdnk_3","text":"故聖人傳精神，服天氣而通神明。失之則內閉九竅，外壅肌肉，衛氣解散，此謂自傷，氣之削也。","sortOrder":6},
  {"id":"s_work_hdnk_3_7","chapterId":"ch_work_hdnk_3","text":"陽氣者，若天與日，失其所，則折壽而不彰。故天運當以日光明。是故陽因而上，衛外者也。","sortOrder":7},
  {"id":"s_work_hdnk_3_8","chapterId":"ch_work_hdnk_3","text":"因於寒，欲如運樞，起居如驚，神氣乃浮。","sortOrder":8},
  {"id":"s_work_hdnk_3_9","chapterId":"ch_work_hdnk_3","text":"因於暑汗，煩則喘喝，靜則多言。","sortOrder":9},
  {"id":"s_work_hdnk_3_10","chapterId":"ch_work_hdnk_3","text":"體若燔炭，汗出而散。","sortOrder":10},
  {"id":"s_work_hdnk_3_11","chapterId":"ch_work_hdnk_3","text":"因於濕，首如裹。濕熱不攘，大筋轜短，小筋馳長。轜短為拘，馳長為痿。","sortOrder":11},
  {"id":"s_work_hdnk_3_12","chapterId":"ch_work_hdnk_3","text":"因於氣，為腫。四維相代，陽氣乃竭。","sortOrder":12},
  {"id":"s_work_hdnk_3_13","chapterId":"ch_work_hdnk_3","text":"陽氣者，煩勞則張，精絕，辟積於夏，使人煎厥；目盲不可以視，耳閉不可以聽，潰潰乎若壞都，汨汨乎不可止。","sortOrder":13},
  {"id":"s_work_hdnk_3_14","chapterId":"ch_work_hdnk_3","text":"陽氣者，大怒則形氣絕而血菀於上，使人薄厥。","sortOrder":14},
  {"id":"s_work_hdnk_3_15","chapterId":"ch_work_hdnk_3","text":"有傷於筋，縱，其若不容。","sortOrder":15},
  {"id":"s_work_hdnk_3_16","chapterId":"ch_work_hdnk_3","text":"汗出偏沮，使人偏枯。","sortOrder":16},
  {"id":"s_work_hdnk_3_17","chapterId":"ch_work_hdnk_3","text":"汗出見濕，乃生痤疿。","sortOrder":17},
  {"id":"s_work_hdnk_3_18","chapterId":"ch_work_hdnk_3","text":"高梁之變，足生大丁受如持虛。","sortOrder":18},
  {"id":"s_work_hdnk_3_19","chapterId":"ch_work_hdnk_3","text":"勞汗當風，寒薄為皶，鬱乃痤。","sortOrder":19},
  {"id":"s_work_hdnk_3_20","chapterId":"ch_work_hdnk_3","text":"陽氣者，精則養神，柔則養筋。","sortOrder":20},
  {"id":"s_work_hdnk_3_21","chapterId":"ch_work_hdnk_3","text":"開闔不得，寒氣從之，乃生大僂。","sortOrder":21},
  {"id":"s_work_hdnk_3_22","chapterId":"ch_work_hdnk_3","text":"陷脈為瘻，留連肉腠。","sortOrder":22},
  {"id":"s_work_hdnk_3_23","chapterId":"ch_work_hdnk_3","text":"俞氣化薄，傳為善畏，及為驚駭。","sortOrder":23},
  {"id":"s_work_hdnk_3_24","chapterId":"ch_work_hdnk_3","text":"營氣不從，逆於肉理，乃生癰腫。","sortOrder":24},
  {"id":"s_work_hdnk_3_25","chapterId":"ch_work_hdnk_3","text":"魄汗未盡，形弱而氣爍，穴俞以閉，發為風瘧。","sortOrder":25},
  {"id":"s_work_hdnk_3_26","chapterId":"ch_work_hdnk_3","text":"故風者，百病之始也，清靜則肉腠閉拒，雖有大風苛毒，弗之能害，此因時之序也。","sortOrder":26},
  {"id":"s_work_hdnk_3_27","chapterId":"ch_work_hdnk_3","text":"故病久則傳化，上下不併，良醫弗為。","sortOrder":27},
  {"id":"s_work_hdnk_3_28","chapterId":"ch_work_hdnk_3","text":"故陽畜積病死，而陽氣當隔。隔者當瀉，不亟正治，粗乃敗之。","sortOrder":28},
  {"id":"s_work_hdnk_3_29","chapterId":"ch_work_hdnk_3","text":"故陽氣者，一日而主外。平旦人氣生，日中而陽氣隆，日西而陽氣已虛，氣門乃閉。是故暮而收拒，無擾筋骨，無見霧露，反此三時，形乃困薄。","sortOrder":29},
  {"id":"s_work_hdnk_3_30","chapterId":"ch_work_hdnk_3","text":"岐伯曰：陰者藏精而起極也，陽者衛外而為固也。陰不勝其陽，則脈流薄疾，併乃狂。陽不勝其陰，則五臟氣爭，九竅不通。","sortOrder":30},
  {"id":"s_work_hdnk_3_31","chapterId":"ch_work_hdnk_3","text":"是以聖人陳陰陽，筋脈和同，骨髓堅固，氣血皆從。如是則內外調和，邪不能害，耳目聰明，氣立如故。","sortOrder":31},
  {"id":"s_work_hdnk_3_32","chapterId":"ch_work_hdnk_3","text":"風客淫氣，精乃亡，邪傷肝也。","sortOrder":32},
  {"id":"s_work_hdnk_3_33","chapterId":"ch_work_hdnk_3","text":"因而飽食，筋脈橫解，腸澼為痔。","sortOrder":33},
  {"id":"s_work_hdnk_3_34","chapterId":"ch_work_hdnk_3","text":"因而大飲，則氣逆。","sortOrder":34},
  {"id":"s_work_hdnk_3_35","chapterId":"ch_work_hdnk_3","text":"因而強力，腎氣乃傷，高骨乃壞。","sortOrder":35},
  {"id":"s_work_hdnk_3_36","chapterId":"ch_work_hdnk_3","text":"凡陰陽之要，陽密乃固，兩者不和，若春無秋，若冬無夏。因而和之，是謂聖度。","sortOrder":36},
  {"id":"s_work_hdnk_3_37","chapterId":"ch_work_hdnk_3","text":"故陽強不能密，陰氣乃絕。","sortOrder":37},
  {"id":"s_work_hdnk_3_38","chapterId":"ch_work_hdnk_3","text":"陰平陽秘，精神乃治；陰陽離決，精氣乃絕。","sortOrder":38},
  {"id":"s_work_hdnk_3_39","chapterId":"ch_work_hdnk_3","text":"因於露風，乃生寒熱。","sortOrder":39},
  {"id":"s_work_hdnk_3_40","chapterId":"ch_work_hdnk_3","text":"是以春傷於風，邪氣留連，乃為洞泄。","sortOrder":40},
  {"id":"s_work_hdnk_3_41","chapterId":"ch_work_hdnk_3","text":"夏傷於暑，秋為痎瘧。","sortOrder":41},
  {"id":"s_work_hdnk_3_42","chapterId":"ch_work_hdnk_3","text":"秋傷於濕，上逆而咳，發為痿厥。","sortOrder":42},
  {"id":"s_work_hdnk_3_43","chapterId":"ch_work_hdnk_3","text":"冬傷於寒，春必溫病。","sortOrder":43},
  {"id":"s_work_hdnk_3_44","chapterId":"ch_work_hdnk_3","text":"四時之氣，更傷五臟。","sortOrder":44},
  {"id":"s_work_hdnk_3_45","chapterId":"ch_work_hdnk_3","text":"陰之所生，本在五味；陰之五宮，傷在五味。","sortOrder":45},
  {"id":"s_work_hdnk_3_46","chapterId":"ch_work_hdnk_3","text":"是故味過於酸，肝氣以津，脾氣乃絕。","sortOrder":46},
  {"id":"s_work_hdnk_3_47","chapterId":"ch_work_hdnk_3","text":"味過於鹹，大骨氣勞，短肌，心氣抑。","sortOrder":47},
  {"id":"s_work_hdnk_3_48","chapterId":"ch_work_hdnk_3","text":"味過於甘，心氣喘滿，色黑，腎氣不衡。","sortOrder":48},
  {"id":"s_work_hdnk_3_49","chapterId":"ch_work_hdnk_3","text":"味過於苦，脾氣不濡，胃氣乃厚。","sortOrder":49},
  {"id":"s_work_hdnk_3_50","chapterId":"ch_work_hdnk_3","text":"味過於辛，筋脈沮弛，精神乃央。","sortOrder":50},
  {"id":"s_work_hdnk_3_51","chapterId":"ch_work_hdnk_3","text":"是故謹和五味，骨正筋柔，氣血以流，腠理以密，如是則骨氣以精。謹道如法，長有天命。","sortOrder":51},
  {"id":"s_work_hdnk_4_1","chapterId":"ch_work_hdnk_4","text":"金匱真言論篇第四","sortOrder":1},
  {"id":"s_work_hdnk_4_2","chapterId":"ch_work_hdnk_4","text":"黃帝問曰：天有八風，經有五風，何謂？","sortOrder":2},
  {"id":"s_work_hdnk_4_3","chapterId":"ch_work_hdnk_4","text":"岐伯對曰：八風發邪以為經風，觸五臟，邪氣發病。","sortOrder":3},
  {"id":"s_work_hdnk_4_4","chapterId":"ch_work_hdnk_4","text":"所謂得四時之勝者，春勝長夏，長夏勝冬，冬勝夏，夏勝秋，秋勝春，所謂四時之勝也。","sortOrder":4},
  {"id":"s_work_hdnk_4_5","chapterId":"ch_work_hdnk_4","text":"東風生於春，病在肝，俞在頸項；南風生於夏，病在心，俞在胸肋；西風生於秋，病在肺，俞在肩背；北風生於冬，病在腎，俞在腰股，中央為土，病在脾，俞在脊。","sortOrder":5},
  {"id":"s_work_hdnk_4_6","chapterId":"ch_work_hdnk_4","text":"故春氣者，病在頭；夏氣者，病在臟；秋氣者，病在肩背；冬氣者，病在四肢。","sortOrder":6},
  {"id":"s_work_hdnk_4_7","chapterId":"ch_work_hdnk_4","text":"故春善病鼽衄，仲夏善病胸脅，長夏善病洞泄寒中，秋善病風瘧，冬善痺厥。","sortOrder":7},
  {"id":"s_work_hdnk_4_8","chapterId":"ch_work_hdnk_4","text":"故冬不按蹻，春不鼽衄；春不病頸項，仲夏不病胸肋；長夏不病洞泄寒中，秋不病風瘧，冬不病痺厥，飧泄而汗出也。","sortOrder":8},
  {"id":"s_work_hdnk_4_9","chapterId":"ch_work_hdnk_4","text":"夫精者，身之本也。故藏於精者，春不病溫。夏暑汗不出者，秋成風瘧，此平人脈法也。","sortOrder":9},
  {"id":"s_work_hdnk_4_10","chapterId":"ch_work_hdnk_4","text":"故曰：陰中有陰，陽中有陽。平旦至日中，天之陽，陽中之陽也；日中至黃昏，天之陽，陽中之陰也；合夜至雞鳴，天之陰，陰中之陰也；雞鳴至平旦，天之陰，陰中之陽也。","sortOrder":10},
  {"id":"s_work_hdnk_4_11","chapterId":"ch_work_hdnk_4","text":"故人亦應之，夫言人之陰陽，則外為陽，內為陰。言人身之陰陽，則背為陽，腹為陰。言人身之臟腑中陰陽，則臟者為陰，腑者為陽。肝心脾肺腎五臟皆為陰，膽胃大腸小腸膀胱三焦六腑皆為陽。","sortOrder":11},
  {"id":"s_work_hdnk_4_12","chapterId":"ch_work_hdnk_4","text":"所以欲知陰中之陰，陽中之陽者，何也？為冬病在陰，夏病在陽，春病在陰，秋病在陽，皆視其所在，為施針石也。","sortOrder":12},
  {"id":"s_work_hdnk_4_13","chapterId":"ch_work_hdnk_4","text":"故背為陽，陽中之陽心也；背為陽，陽中之陰肺也；腹為陰，陰中之陰腎也，陰中之陽肝也；腹為陰，陰中之至陰脾也。","sortOrder":13},
  {"id":"s_work_hdnk_4_14","chapterId":"ch_work_hdnk_4","text":"此皆陰陽表裏，內外雌雄，相輸應也。故以應天之陰陽也。","sortOrder":14},
  {"id":"s_work_hdnk_4_15","chapterId":"ch_work_hdnk_4","text":"帝曰：五臟應四時，各有收受乎？","sortOrder":15},
  {"id":"s_work_hdnk_4_16","chapterId":"ch_work_hdnk_4","text":"岐伯曰：有。東方青色，入通於肝，開竅於目，藏精於肝。其病發驚駭，其味酸，其類草木，其畜雞，其穀麥，其應四時，上為歲星，是以春氣在頭也。其音角，其數八，是以知病之在筋也。其臭臊。","sortOrder":16},
  {"id":"s_work_hdnk_4_17","chapterId":"ch_work_hdnk_4","text":"南方赤色入通於心，開竅於耳，藏於心，故病在五臟。其味苦，其類火，其畜羊，其穀黍，其應四時，上為熒惑星。是以知病之在脈也。其音征，其數七，其臭焦。","sortOrder":17},
  {"id":"s_work_hdnk_4_18","chapterId":"ch_work_hdnk_4","text":"中央黃色入通於脾，開竅於口，藏精於脾，故病在舌本。其味甘，其類土，其畜牛，其穀稷，其應四時，上為鎮星。是以知病之在肉也。其音宮，其數五，其臭香。","sortOrder":18},
  {"id":"s_work_hdnk_4_19","chapterId":"ch_work_hdnk_4","text":"西方白色，入通於肺，開竅於鼻，藏精於肺，故病背。其味辛，其類金，其畜馬，其穀稻，其應四時，上為太白星。是以知病之在皮毛也。其音商，其數九，其臭腥。","sortOrder":19},
  {"id":"s_work_hdnk_4_20","chapterId":"ch_work_hdnk_4","text":"北方黑色，入通於腎，開竅於二陰，藏精於腎，故病在谿。其味鹹，其類水，其畜彘，其穀豆，其應四時，上為辰星。是以知病之在骨也。其音羽，其數六，其臭腐。","sortOrder":20},
  {"id":"s_work_hdnk_4_21","chapterId":"ch_work_hdnk_4","text":"故善為脈者，謹察五臟六腑，一逆一從，陰陽表裏雌雄之紀，藏之心意，合心於精，非其人勿教，非其真勿授，是謂得道。","sortOrder":21},
  {"id":"s_work_hdnk_5_1","chapterId":"ch_work_hdnk_5","text":"陰陽應象大論篇第五","sortOrder":1},
  {"id":"s_work_hdnk_5_2","chapterId":"ch_work_hdnk_5","text":"黃帝曰：陰陽者天地之道也，萬物之綱紀也，變化之父母，生殺之本始，神明之府也。","sortOrder":2},
  {"id":"s_work_hdnk_5_3","chapterId":"ch_work_hdnk_5","text":"治病必求於本。","sortOrder":3},
  {"id":"s_work_hdnk_5_4","chapterId":"ch_work_hdnk_5","text":"故積陽為天，積陰為地。陰靜陽燥，陽生陰長，陽殺陰藏，陽化氣，陰成形。","sortOrder":4},
  {"id":"s_work_hdnk_5_5","chapterId":"ch_work_hdnk_5","text":"寒極生熱，熱極生寒，寒氣生濁，熱氣生清。清氣在下，則生飧泄；濁氣在上，則生〈月真〉脹。此陰陽反作，病之逆從也。","sortOrder":5},
  {"id":"s_work_hdnk_5_6","chapterId":"ch_work_hdnk_5","text":"故清陽為天，濁陰為地；地氣上為雲，天氣下為雨；雨出地氣，雲出天氣。","sortOrder":6},
  {"id":"s_work_hdnk_5_7","chapterId":"ch_work_hdnk_5","text":"故清陽出上竅，濁陰出下竅；清陽發腠理，濁陰走五臟；清陽實四肢，濁陰歸六腑。","sortOrder":7},
  {"id":"s_work_hdnk_5_8","chapterId":"ch_work_hdnk_5","text":"水為陰，火為陽；陽為氣，陰為味。","sortOrder":8},
  {"id":"s_work_hdnk_5_9","chapterId":"ch_work_hdnk_5","text":"味歸形，形歸氣，氣歸精，精歸化，精食氣，形食味，化生精，氣生形。","sortOrder":9},
  {"id":"s_work_hdnk_5_10","chapterId":"ch_work_hdnk_5","text":"味傷形，氣傷精；精化為氣，氣傷於味。","sortOrder":10},
  {"id":"s_work_hdnk_5_11","chapterId":"ch_work_hdnk_5","text":"陰味出下竅；陽氣出上竅。","sortOrder":11},
  {"id":"s_work_hdnk_5_12","chapterId":"ch_work_hdnk_5","text":"味厚者為陰，薄為陰之陽。氣厚者為陽，薄為陽之陰。","sortOrder":12},
  {"id":"s_work_hdnk_5_13","chapterId":"ch_work_hdnk_5","text":"味厚則泄，薄則通。氣薄則發泄，厚則發熱。","sortOrder":13},
  {"id":"s_work_hdnk_5_14","chapterId":"ch_work_hdnk_5","text":"壯火之氣衰，少火之氣壯。壯火食氣，氣食少火。壯火散氣，少火生氣。","sortOrder":14},
  {"id":"s_work_hdnk_5_15","chapterId":"ch_work_hdnk_5","text":"氣味，辛甘發散為陽，酸苦涌泄為陰。","sortOrder":15},
  {"id":"s_work_hdnk_5_16","chapterId":"ch_work_hdnk_5","text":"陰勝則陽病，陽勝則陰病。陽勝則熱，陰勝則寒。重寒則熱，重熱則寒。","sortOrder":16},
  {"id":"s_work_hdnk_5_17","chapterId":"ch_work_hdnk_5","text":"寒傷形，熱傷氣。氣傷痛，形傷腫。故先痛而後腫者氣傷形也，先腫而後痛者形傷氣也。","sortOrder":17},
  {"id":"s_work_hdnk_5_18","chapterId":"ch_work_hdnk_5","text":"風勝則動，熱勝則腫。燥勝則乾，寒勝則浮，濕勝則濡瀉。","sortOrder":18},
  {"id":"s_work_hdnk_5_19","chapterId":"ch_work_hdnk_5","text":"天有四時五行以生長收藏，以生寒暑燥濕風。人有五臟化五氣，以生喜怒悲憂恐。","sortOrder":19},
  {"id":"s_work_hdnk_5_20","chapterId":"ch_work_hdnk_5","text":"故喜怒傷氣，寒暑傷形。","sortOrder":20},
  {"id":"s_work_hdnk_5_21","chapterId":"ch_work_hdnk_5","text":"暴怒傷陰，暴喜傷陽。","sortOrder":21},
  {"id":"s_work_hdnk_5_22","chapterId":"ch_work_hdnk_5","text":"厥氣上行，滿脈去形。","sortOrder":22},
  {"id":"s_work_hdnk_5_23","chapterId":"ch_work_hdnk_5","text":"喜怒不節，寒暑過度，生乃不固。","sortOrder":23},
  {"id":"s_work_hdnk_5_24","chapterId":"ch_work_hdnk_5","text":"故重陰必陽，重陽必陰。","sortOrder":24},
  {"id":"s_work_hdnk_5_25","chapterId":"ch_work_hdnk_5","text":"故曰：冬傷於寒，春必溫病，春傷於風，夏生飧泄，夏傷於暑，秋必痎瘧；秋傷於濕，冬生咳嗽。","sortOrder":25},
  {"id":"s_work_hdnk_5_26","chapterId":"ch_work_hdnk_5","text":"帝曰：餘聞上古聖人，論理人形，列別臟腑，端絡經脈，會通六合，各從其經，氣穴所發，各有處名，谿穀屬骨，皆有所起。分部逆從，各有條理。四時陰陽，盡有經紀。外內之應，皆有表裏，其信然乎。","sortOrder":26},
  {"id":"s_work_hdnk_5_27","chapterId":"ch_work_hdnk_5","text":"岐伯對曰：東方生風，風生木，木生酸，酸生肝，肝生筋，筋生心，肝主目。其在天為玄，在人為道，在地為化。化生五味，道生智，玄生神，神在天為風，在地為木，在體為筋，在臟為肝。在色為蒼，在音為角，在聲為呼，在變動為握，在竅為目，在味為酸，在志為怒。怒傷肝，悲勝怒，風傷筋，燥勝風，酸傷筋，辛勝酸。","sortOrder":27},
  {"id":"s_work_hdnk_5_28","chapterId":"ch_work_hdnk_5","text":"南方生熱，熱生火，火生苦，苦生心。心生血，血生脾。心主舌。其在天為熱，在地為火，在體為脈，在臟為心，在色為赤，在音為徵，在聲為笑，在變動為憂，在竅為舌，在味為苦，在志為喜。喜傷心，恐勝喜。熱傷氣，寒勝熱。苦傷氣，鹹勝苦。","sortOrder":28},
  {"id":"s_work_hdnk_5_29","chapterId":"ch_work_hdnk_5","text":"中央生濕，濕生土，土生甘，甘生脾，脾生肉，肉生肺脾主口。其在天為濕，在地為土，在體為肉，在臟為脾，在色為黃，在音為宮，在聲為歌，在變動為噦，在竅為口，在味為甘，在志為思。思傷脾，怒勝思，濕傷肉，風勝濕，甘傷肉，酸勝甘。","sortOrder":29},
  {"id":"s_work_hdnk_5_30","chapterId":"ch_work_hdnk_5","text":"西方生燥，燥生金，金生辛，辛生肺，肺生皮毛，皮毛在腎，肺主鼻。其在天為燥，在地為金，在體為皮毛，在臟為肺，在色為白，在音為商，在聲為哭，在變動為咳，在竅為鼻，在味為辛，在志為憂。憂傷肺，喜勝憂，熱傷皮毛，寒勝熱，辛傷皮毛，苦勝辛。","sortOrder":30},
  {"id":"s_work_hdnk_5_31","chapterId":"ch_work_hdnk_5","text":"北方生寒，寒生水，水生鹹，鹹生腎，腎生骨髓，髓生肝，腎主耳。其在天為寒，在地為水，在體為骨，在臟為腎，在色為黑，在音為羽，在聲為呻，在變動為慄，在竅為耳，在味為鹹，在志為恐。恐傷腎，思勝恐，寒傷血，燥勝寒，鹹傷血，甘勝鹹。","sortOrder":31},
  {"id":"s_work_hdnk_5_32","chapterId":"ch_work_hdnk_5","text":"故曰：天地者，萬物之上下也；陰陽者，血氣之男女也；左右者，陰陽之道路也；水火者，陰陽之徵兆也；陰陽者，萬物之能始也。故曰：陰在內，陽之守也，陽在外，陰之使也。","sortOrder":32},
  {"id":"s_work_hdnk_5_33","chapterId":"ch_work_hdnk_5","text":"帝曰：法陰陽奈何？","sortOrder":33},
  {"id":"s_work_hdnk_5_34","chapterId":"ch_work_hdnk_5","text":"岐伯曰：陽盛則身熱，腠理閉，喘麤為之俛抑，汗不出而熱，齒乾，以煩冤腹滿死，能冬不能夏。","sortOrder":34},
  {"id":"s_work_hdnk_5_35","chapterId":"ch_work_hdnk_5","text":"陰勝則身寒，汗出身長清，數慄而寒，寒則厥，厥則腹滿死，能夏不能冬。此陰陽更勝之變，病之形能也。","sortOrder":35},
  {"id":"s_work_hdnk_5_36","chapterId":"ch_work_hdnk_5","text":"帝曰：調此二者，奈何？岐伯曰：能知七損八益，則二者可調，不知用此，則早衰之節也。","sortOrder":36},
  {"id":"s_work_hdnk_5_37","chapterId":"ch_work_hdnk_5","text":"年四十而陰氣自半也，起居衰矣。年五十體重，耳目不聰明矣。年六十，陰痿，氣大衰，九竅不利，下虛上實，涕泣俱出矣。","sortOrder":37},
  {"id":"s_work_hdnk_5_38","chapterId":"ch_work_hdnk_5","text":"故曰：知之則強，不知則老，故同出而名異耳。智者察同，愚者察異，愚者不足，智者有餘，有餘而耳目聰明，身體強健，老者復壯，壯者益治。","sortOrder":38},
  {"id":"s_work_hdnk_5_39","chapterId":"ch_work_hdnk_5","text":"是以聖人為無為之事，樂恬憺之能，從欲快志於虛無之守，故壽命無窮，與天地終，此聖人之治身也。","sortOrder":39},
  {"id":"s_work_hdnk_5_40","chapterId":"ch_work_hdnk_5","text":"天不足西北，故西北方陰也，而人右耳目不如左明也。地不滿東南，故東南方陽也，而人左手足不如右強也。","sortOrder":40},
  {"id":"s_work_hdnk_5_41","chapterId":"ch_work_hdnk_5","text":"帝曰：何以然？岐伯曰：東方陽也，陽者其精並於上，並於上則上明而下虛，故使耳目聰明而手足不便。西方陰也，陰者其精並於下，並於下則下盛而上虛，故其耳目不聰明而手足便也。故俱感於邪，其在上則右甚，在下則左甚，此天地陰陽所不能全也，故邪居之。","sortOrder":41},
  {"id":"s_work_hdnk_5_42","chapterId":"ch_work_hdnk_5","text":"故天有精，地有形，天有八紀，地有五理，故能為萬物之父母。","sortOrder":42},
  {"id":"s_work_hdnk_5_43","chapterId":"ch_work_hdnk_5","text":"清陽上天，濁陰歸地，是故天地之動靜，神明為之綱紀，故能以生長收藏，終而復始。","sortOrder":43},
  {"id":"s_work_hdnk_5_44","chapterId":"ch_work_hdnk_5","text":"惟賢人上配天以養頭，下象地以養足，中傍人事以養五臟。","sortOrder":44},
  {"id":"s_work_hdnk_5_45","chapterId":"ch_work_hdnk_5","text":"天地通於肺，地氣通於嗌，風氣通於肝，雷氣通於心，穀氣通於脾，雨氣通於腎。","sortOrder":45},
  {"id":"s_work_hdnk_5_46","chapterId":"ch_work_hdnk_5","text":"六經為川，腸胃為海，九竅為水註之氣。","sortOrder":46},
  {"id":"s_work_hdnk_5_47","chapterId":"ch_work_hdnk_5","text":"以天地為之陰陽，陽之汗以天地之雨右之；陽之氣以天地之疾風名之。暴氣象雷，逆氣象陽。","sortOrder":47},
  {"id":"s_work_hdnk_5_48","chapterId":"ch_work_hdnk_5","text":"故治不法天之紀，不用地之理，則災害至矣。","sortOrder":48},
  {"id":"s_work_hdnk_5_49","chapterId":"ch_work_hdnk_5","text":"故邪風之至，疾如風雨，故善治者，治皮毛，其次治肌膚，其次治筋脈，其次治六腑，其次治五臟。治五臟者，半死半生也。","sortOrder":49},
  {"id":"s_work_hdnk_5_50","chapterId":"ch_work_hdnk_5","text":"故天之邪氣感，則害人五臟；水穀之寒熱感，則害於六腑；地之濕氣感，則害皮肉筋脈。","sortOrder":50},
  {"id":"s_work_hdnk_5_51","chapterId":"ch_work_hdnk_5","text":"故善用針者，從陰引陽，從陽引陰，以右治左，以左治右，以我知彼，以表知裏，以觀過與不及之理，見微得過，用之不殆。","sortOrder":51},
  {"id":"s_work_hdnk_5_52","chapterId":"ch_work_hdnk_5","text":"善診者，察色按脈，先別陰陽，審清濁而知部分；視喘息，聽音聲，而知所苦；觀權衡規矩，而知病所主；按尺寸，觀浮沈滑澀而知病所生以治。無過以診則不失矣。","sortOrder":52},
  {"id":"s_work_hdnk_5_53","chapterId":"ch_work_hdnk_5","text":"故曰：病之始起也，可刺而已；其盛，可待衰而已。","sortOrder":53},
  {"id":"s_work_hdnk_5_54","chapterId":"ch_work_hdnk_5","text":"故因其輕而揚之，因其重而減之，因其衰而彰之。","sortOrder":54},
  {"id":"s_work_hdnk_5_55","chapterId":"ch_work_hdnk_5","text":"形不足者，溫之以氣；精不足，補之以味。","sortOrder":55},
  {"id":"s_work_hdnk_5_56","chapterId":"ch_work_hdnk_5","text":"其高者，因而越之；其下者，引而竭之；中滿者瀉之於內。","sortOrder":56},
  {"id":"s_work_hdnk_5_57","chapterId":"ch_work_hdnk_5","text":"其有邪者，漬形以為汗；其在皮者，汗而發之；其慄悍者，按而收之，其實者散而瀉之。","sortOrder":57},
  {"id":"s_work_hdnk_5_58","chapterId":"ch_work_hdnk_5","text":"審其陰陽，以別柔剛。","sortOrder":58},
  {"id":"s_work_hdnk_5_59","chapterId":"ch_work_hdnk_5","text":"陽病治陰，陰病治陽。","sortOrder":59},
  {"id":"s_work_hdnk_5_60","chapterId":"ch_work_hdnk_5","text":"定其血氣，各守其鄉。","sortOrder":60},
  {"id":"s_work_hdnk_5_61","chapterId":"ch_work_hdnk_5","text":"血實宜決之，氣虛宜掣引之。","sortOrder":61},
  {"id":"s_work_hdnk_6_1","chapterId":"ch_work_hdnk_6","text":"陰陽離合篇第六","sortOrder":1},
  {"id":"s_work_hdnk_6_2","chapterId":"ch_work_hdnk_6","text":"黃帝問曰：餘聞天為陽，地為陰，日為陽，月為陰。大小月三百六十日成一歲，人亦應之。今三陰三陽不應陰陽；其故何也？","sortOrder":2},
  {"id":"s_work_hdnk_6_3","chapterId":"ch_work_hdnk_6","text":"岐伯對曰：陰陽者數之可十，推之可百，數之可千，推之可萬，萬之大不可勝數，然其要一也。","sortOrder":3},
  {"id":"s_work_hdnk_6_4","chapterId":"ch_work_hdnk_6","text":"天覆地載，萬物方生。未出地者，命曰陰處，名曰陰中之陰；則出地者，命曰陰中之陽。","sortOrder":4},
  {"id":"s_work_hdnk_6_5","chapterId":"ch_work_hdnk_6","text":"陽予之正，陰為之主。故生因春，長因夏，收因秋，藏因冬。夫常則天地四塞。陰陽之變，其在人者，亦數之可數。","sortOrder":5},
  {"id":"s_work_hdnk_6_6","chapterId":"ch_work_hdnk_6","text":"帝曰：願聞三陰三陽之離合也。岐伯曰：聖人南面而立，前曰廣明，後曰太沖。太沖之地，名曰少陰、少陰之上，名曰太陽。太陽根起於至陰，結於命門，名曰陰中之陽。","sortOrder":6},
  {"id":"s_work_hdnk_6_7","chapterId":"ch_work_hdnk_6","text":"中身而上名曰廣明。廣明之下名曰太陰，太陰之前，名曰陽明。陽明根起於厲兌，名曰陰中之陽。","sortOrder":7},
  {"id":"s_work_hdnk_6_8","chapterId":"ch_work_hdnk_6","text":"厥陰之表，名曰少陽。少陽根起於竅陰，名曰陰中之少陽。","sortOrder":8},
  {"id":"s_work_hdnk_6_9","chapterId":"ch_work_hdnk_6","text":"是故三陽之離合也：太陽為開，陽明為闔，少陽為樞。三經者不得相失也，搏而勿浮，命曰一陽。","sortOrder":9},
  {"id":"s_work_hdnk_6_10","chapterId":"ch_work_hdnk_6","text":"帝曰：願聞三陰？岐伯曰：外者為陽。內者為陰。然則中為陰，其沖在下，名曰太陰，太陰根起於隱白，名曰陰中之陰。","sortOrder":10},
  {"id":"s_work_hdnk_6_11","chapterId":"ch_work_hdnk_6","text":"太陰之後，名曰少陰，少陰根起於涌泉，名曰陰中之少陰。","sortOrder":11},
  {"id":"s_work_hdnk_6_12","chapterId":"ch_work_hdnk_6","text":"少陰之前，名曰厥陰，厥陰根起於大敦，陰之絕陽，名曰陰之絕陰。","sortOrder":12},
  {"id":"s_work_hdnk_6_13","chapterId":"ch_work_hdnk_6","text":"是故三陰之離合也，太陰為開，厥陰為闔，少陰為樞。三經者不得相失也，搏而勿沉，名曰一陰。","sortOrder":13},
  {"id":"s_work_hdnk_6_14","chapterId":"ch_work_hdnk_6","text":"陰陽衝衝，積傳為一周，氣裏形表，而為相成也。","sortOrder":14},
  {"id":"s_work_hdnk_7_1","chapterId":"ch_work_hdnk_7","text":"陰陽別論篇第七","sortOrder":1},
  {"id":"s_work_hdnk_7_2","chapterId":"ch_work_hdnk_7","text":"黃帝問曰：人有四經，十二從，何謂？岐伯對曰：四經，應四時；十二從，應十二月；十二月應十二脈。","sortOrder":2},
  {"id":"s_work_hdnk_7_3","chapterId":"ch_work_hdnk_7","text":"脈有陰陽，知陽者知陰，知陰者知陽。","sortOrder":3},
  {"id":"s_work_hdnk_7_4","chapterId":"ch_work_hdnk_7","text":"凡陽有五，五五二十五陽。","sortOrder":4},
  {"id":"s_work_hdnk_7_5","chapterId":"ch_work_hdnk_7","text":"所謂陰者，真臟也。見則為敗，敗必死也。","sortOrder":5},
  {"id":"s_work_hdnk_7_6","chapterId":"ch_work_hdnk_7","text":"所謂陽者，胃脘之陽也。","sortOrder":6},
  {"id":"s_work_hdnk_7_7","chapterId":"ch_work_hdnk_7","text":"別於陽者，知病處也，別於陰者，知生死之期。","sortOrder":7},
  {"id":"s_work_hdnk_7_8","chapterId":"ch_work_hdnk_7","text":"三陽在頭，三陰在手，所謂一也。","sortOrder":8},
  {"id":"s_work_hdnk_7_9","chapterId":"ch_work_hdnk_7","text":"別於陽者，知病忌時，別於陰者，知死生之期。","sortOrder":9},
  {"id":"s_work_hdnk_7_10","chapterId":"ch_work_hdnk_7","text":"謹熟陰陽，無與眾謀。","sortOrder":10},
  {"id":"s_work_hdnk_7_11","chapterId":"ch_work_hdnk_7","text":"所謂陰陽者，去者為陰，至者為陽，靜者為陰，動者為陽，遲者為陰，數者為陽。","sortOrder":11},
  {"id":"s_work_hdnk_7_12","chapterId":"ch_work_hdnk_7","text":"凡持真脈之藏脈者，肝主懸絕急，十八日死；心至懸絕，九日死；肺至懸絕，十二日死；腎至懸絕，七日死；脾至懸絕，四日死。","sortOrder":12},
  {"id":"s_work_hdnk_7_13","chapterId":"ch_work_hdnk_7","text":"曰：二陽之病發心脾，有不得隱曲，女子不月；其傳為風消，其傳為息賁者，死不治。","sortOrder":13},
  {"id":"s_work_hdnk_7_14","chapterId":"ch_work_hdnk_7","text":"曰：三陽為病，發寒熱，下為癰腫，及為痿厥，腨〈疒肙〉；其傳為索澤，其傳為〈疒頽〉疝。","sortOrder":14},
  {"id":"s_work_hdnk_7_15","chapterId":"ch_work_hdnk_7","text":"曰：一陽發病，少氣，善咳，善泄；其傳為心掣，其傳為隔。","sortOrder":15},
  {"id":"s_work_hdnk_7_16","chapterId":"ch_work_hdnk_7","text":"二陽一陰發病，主驚駭、背痛、善噫、善欠，名曰風厥。","sortOrder":16},
  {"id":"s_work_hdnk_7_17","chapterId":"ch_work_hdnk_7","text":"二陰一陽發病，善脹、心滿善氣。","sortOrder":17},
  {"id":"s_work_hdnk_7_18","chapterId":"ch_work_hdnk_7","text":"三陰三陽發病，為偏枯萎易，四肢不舉。","sortOrder":18},
  {"id":"s_work_hdnk_7_19","chapterId":"ch_work_hdnk_7","text":"鼓一陽曰鉤，鼓一陰曰毛，鼓陽勝急曰絃，鼓陽至而絕曰石，陰陽相過曰溜。","sortOrder":19},
  {"id":"s_work_hdnk_7_20","chapterId":"ch_work_hdnk_7","text":"陰爭於內，陽擾於外，魄汗未藏，四逆而起，起則熏肺，使人喘嗚。","sortOrder":20},
  {"id":"s_work_hdnk_7_21","chapterId":"ch_work_hdnk_7","text":"陰之所生，和本曰和。","sortOrder":21},
  {"id":"s_work_hdnk_7_22","chapterId":"ch_work_hdnk_7","text":"是故剛與剛，陽氣破散，陰氣乃消亡。","sortOrder":22},
  {"id":"s_work_hdnk_7_23","chapterId":"ch_work_hdnk_7","text":"淖則剛柔不和，經氣乃絕。","sortOrder":23},
  {"id":"s_work_hdnk_7_24","chapterId":"ch_work_hdnk_7","text":"死陰之屬，不過三日而死，生陽之屬，不過四日而死。","sortOrder":24},
  {"id":"s_work_hdnk_7_25","chapterId":"ch_work_hdnk_7","text":"所謂生陽死陰者，肝之心謂之生陽，心之肺謂之死陰，肺之腎謂之重陰，腎之脾謂之辟陰，死不治。","sortOrder":25},
  {"id":"s_work_hdnk_7_26","chapterId":"ch_work_hdnk_7","text":"結陽者，腫四支。","sortOrder":26},
  {"id":"s_work_hdnk_7_27","chapterId":"ch_work_hdnk_7","text":"結陰者，便血一升，再結二升，三結三升。","sortOrder":27},
  {"id":"s_work_hdnk_7_28","chapterId":"ch_work_hdnk_7","text":"陰陽結斜，多陰少陽曰石水，少腹腫。","sortOrder":28},
  {"id":"s_work_hdnk_7_29","chapterId":"ch_work_hdnk_7","text":"二陽結，謂之消。","sortOrder":29},
  {"id":"s_work_hdnk_7_30","chapterId":"ch_work_hdnk_7","text":"三陽結，謂之隔。","sortOrder":30},
  {"id":"s_work_hdnk_7_31","chapterId":"ch_work_hdnk_7","text":"三陰結，謂之水。","sortOrder":31},
  {"id":"s_work_hdnk_7_32","chapterId":"ch_work_hdnk_7","text":"一陰一陽結，謂之喉痺。","sortOrder":32},
  {"id":"s_work_hdnk_7_33","chapterId":"ch_work_hdnk_7","text":"陰搏陽別，謂之有子。","sortOrder":33},
  {"id":"s_work_hdnk_7_34","chapterId":"ch_work_hdnk_7","text":"陰陽虛，腸澼死。","sortOrder":34},
  {"id":"s_work_hdnk_7_35","chapterId":"ch_work_hdnk_7","text":"陽加於陰，謂之汗。","sortOrder":35},
  {"id":"s_work_hdnk_7_36","chapterId":"ch_work_hdnk_7","text":"陰虛陽搏，謂之崩。","sortOrder":36},
  {"id":"s_work_hdnk_7_37","chapterId":"ch_work_hdnk_7","text":"三陰俱搏，二十日夜半死；二陰俱搏，十三日夕時死；一陰俱搏，十日死；三陽搏且鼓，三日死；三陰三陽俱搏，心腹滿，發盡不得隱曲，五日死；二陽俱搏，其病溫，死不治，不過十日死。","sortOrder":37},
  {"id":"s_work_hdnk_8_1","chapterId":"ch_work_hdnk_8","text":"靈蘭秘典論篇第八","sortOrder":1},
  {"id":"s_work_hdnk_8_2","chapterId":"ch_work_hdnk_8","text":"黃帝問曰：願聞十二臟之相使，貴賤何如？","sortOrder":2},
  {"id":"s_work_hdnk_8_3","chapterId":"ch_work_hdnk_8","text":"岐伯對曰：悉乎哉問也。請遂言之！心者，君主之官也，神明出焉。","sortOrder":3},
  {"id":"s_work_hdnk_8_4","chapterId":"ch_work_hdnk_8","text":"肺者，相傅之官，治節出焉。","sortOrder":4},
  {"id":"s_work_hdnk_8_5","chapterId":"ch_work_hdnk_8","text":"肝者，將軍之官，謀慮出焉。","sortOrder":5},
  {"id":"s_work_hdnk_8_6","chapterId":"ch_work_hdnk_8","text":"膽者中正之官，決斷出焉。","sortOrder":6},
  {"id":"s_work_hdnk_8_7","chapterId":"ch_work_hdnk_8","text":"膻中者，臣使之官，喜樂出焉。","sortOrder":7},
  {"id":"s_work_hdnk_8_8","chapterId":"ch_work_hdnk_8","text":"脾胃者，食廩之官，五味出焉。","sortOrder":8},
  {"id":"s_work_hdnk_8_9","chapterId":"ch_work_hdnk_8","text":"大腸者，傳道之官，變化出焉。","sortOrder":9},
  {"id":"s_work_hdnk_8_10","chapterId":"ch_work_hdnk_8","text":"小腸者，受盛之官，化物出焉。","sortOrder":10},
  {"id":"s_work_hdnk_8_11","chapterId":"ch_work_hdnk_8","text":"腎者，作強之官，伎巧出焉。","sortOrder":11},
  {"id":"s_work_hdnk_8_12","chapterId":"ch_work_hdnk_8","text":"三焦者，決瀆之官，水道出焉。","sortOrder":12},
  {"id":"s_work_hdnk_8_13","chapterId":"ch_work_hdnk_8","text":"膀胱者，州都之官，津液藏焉，氣化則能出矣。","sortOrder":13},
  {"id":"s_work_hdnk_8_14","chapterId":"ch_work_hdnk_8","text":"凡此十二官者，不得相失也。故主明則下安，以此養生則壽，沒世不殆，以為天下則大昌。主不明則十二官危，使道閉塞而不通，形乃大傷，以此養生則殃，以為天下者，其宗大危，戒之戒之。","sortOrder":14},
  {"id":"s_work_hdnk_8_15","chapterId":"ch_work_hdnk_8","text":"至道在微，變化無窮，孰知其原。","sortOrder":15},
  {"id":"s_work_hdnk_8_16","chapterId":"ch_work_hdnk_8","text":"窘乎哉，消者瞿瞿，孰知其要。閔閔之當，孰者為良。","sortOrder":16},
  {"id":"s_work_hdnk_8_17","chapterId":"ch_work_hdnk_8","text":"恍惚之數，生於毫釐，毫釐之數，起於度量，千之萬之，可以益大，推之大之，其形乃製。","sortOrder":17},
  {"id":"s_work_hdnk_8_18","chapterId":"ch_work_hdnk_8","text":"黃帝曰：善哉，餘聞精光之道，大聖之業，而宣明大道，非齊戒擇吉日不敢受也。黃帝乃擇吉日良兆，而藏靈蘭之室，以傳保焉。","sortOrder":18},
  {"id":"s_work_hdnk_9_1","chapterId":"ch_work_hdnk_9","text":"六節藏象論篇第九","sortOrder":1},
  {"id":"s_work_hdnk_9_2","chapterId":"ch_work_hdnk_9","text":"黃帝問焉：餘聞以六六之節，以成一歲，人以九九製會，計人亦有三百六十五節，以為天地，久矣。不知其所謂也？","sortOrder":2},
  {"id":"s_work_hdnk_9_3","chapterId":"ch_work_hdnk_9","text":"岐伯對曰：昭乎哉問也，請遂言之！夫六六之節，九九製會者，所以正天之度，氣之數也。天度者，所以製日月之行也，氣數者，所以紀化生之用也。","sortOrder":3},
  {"id":"s_work_hdnk_9_4","chapterId":"ch_work_hdnk_9","text":"天為陽，地為陰；日為陽，月為陰；行有分紀，周有道理。日行一度，月行十三度而有奇焉。故大小月三百六十五日而成歲、積氣餘而盈閏矣。","sortOrder":4},
  {"id":"s_work_hdnk_9_5","chapterId":"ch_work_hdnk_9","text":"立端於始，表正於中，推餘於終，而天度畢矣。","sortOrder":5},
  {"id":"s_work_hdnk_9_6","chapterId":"ch_work_hdnk_9","text":"帝曰：餘已聞天度矣。願聞氣數，何以合之？岐伯曰：天以六六為節，地以九九製會，天有十日，日六竟而周甲，甲六覆而終歲，三百六十日法也。","sortOrder":6},
  {"id":"s_work_hdnk_9_7","chapterId":"ch_work_hdnk_9","text":"夫自古通天者，生之本，本於陰陽。其氣九州九竅，皆通乎天氣。","sortOrder":7},
  {"id":"s_work_hdnk_9_8","chapterId":"ch_work_hdnk_9","text":"故其生五，其氣三。","sortOrder":8},
  {"id":"s_work_hdnk_9_9","chapterId":"ch_work_hdnk_9","text":"三而成天，三而成地，三而成人，三而三之，合則為九。九分為九野，九野為九臟；故形臟四，神臟五，合為九臟以應之也。","sortOrder":9},
  {"id":"s_work_hdnk_9_10","chapterId":"ch_work_hdnk_9","text":"帝曰：餘已聞六六九九之會也，夫子言積氣盈闊，願聞何謂氣？請夫子發蒙解惑焉。岐伯曰：此上帝所秘，先師傳之也。帝曰：請遂聞之。岐伯曰：五日謂之候，三候謂之氣，六氣謂之時，四時謂之歲，而各從其主治焉。五運相襲而皆治之，終期之日，周而復始，時立氣佈，如環無端，候亦同法。故曰不知年之所加，氣之盛衰，虛實之所起，不可以為工矣。","sortOrder":10},
  {"id":"s_work_hdnk_9_11","chapterId":"ch_work_hdnk_9","text":"帝曰：五運之始，如環無端，其太過不及如何？岐伯曰：五氣更立，各有所勝，盛虛之變，此其常也。","sortOrder":11},
  {"id":"s_work_hdnk_9_12","chapterId":"ch_work_hdnk_9","text":"帝曰：平氣何如？岐伯曰，無過者也。","sortOrder":12},
  {"id":"s_work_hdnk_9_13","chapterId":"ch_work_hdnk_9","text":"帝曰：太過不及奈何？岐伯曰：在經有也。","sortOrder":13},
  {"id":"s_work_hdnk_9_14","chapterId":"ch_work_hdnk_9","text":"帝曰：何謂所勝？岐伯曰：春勝長夏，長夏勝冬，冬勝夏，夏勝秋，秋勝春，所謂得五行時之勝，各以氣命其臟。","sortOrder":14},
  {"id":"s_work_hdnk_9_15","chapterId":"ch_work_hdnk_9","text":"帝曰：何以知其勝？岐伯曰：求其至也，皆歸始春，未至而至，此謂太過，則薄所不勝，而乘所勝也。命曰氣淫不分，邪僻內生，工不能禁。至而不至，此謂不及，則所勝妄行，而所生受病，所不勝薄之也，命曰氣迫。所謂求其至者，氣至之時也。謹候其時，氣可與期，失時反候，五治不分，邪僻內生，工不能禁也。","sortOrder":15},
  {"id":"s_work_hdnk_9_16","chapterId":"ch_work_hdnk_9","text":"帝曰：有不襲乎？岐伯曰：蒼天之氣，不得無常也。氣之不襲是謂非常，非常則變矣。","sortOrder":16},
  {"id":"s_work_hdnk_9_17","chapterId":"ch_work_hdnk_9","text":"帝曰：非常而變奈何？岐伯曰：變至則病，所勝則微，所不勝則甚。因而重感於邪則死矣，故非其時則微，當其時則甚也。","sortOrder":17},
  {"id":"s_work_hdnk_9_18","chapterId":"ch_work_hdnk_9","text":"帝曰：善。餘聞氣合而有形，因變以正名。天地之運，陰陽之化，其於萬物孰少孰多，可得聞乎？","sortOrder":18},
  {"id":"s_work_hdnk_9_19","chapterId":"ch_work_hdnk_9","text":"岐伯曰：悉哉問也，天至廣，不可度，地至大，不可量。大神靈問，請陳其方。草生五色，五色之變，不可勝視，草生五味，五味之美不可勝極，嗜欲不同，各有所通。天食人以五氣，地食人以五味。五氣入鼻，藏於心肺，上使五色修明，音聲能彰；五味入口，藏於腸胃，味有所藏，以養五氣，氣和而生，津液相成，神乃自生。","sortOrder":19},
  {"id":"s_work_hdnk_9_20","chapterId":"ch_work_hdnk_9","text":"帝曰：臟象何如？","sortOrder":20},
  {"id":"s_work_hdnk_9_21","chapterId":"ch_work_hdnk_9","text":"岐伯曰：心者生之本，神之變也；其華在面，其充在血脈，為陽中之太陽，通於夏氣。","sortOrder":21},
  {"id":"s_work_hdnk_9_22","chapterId":"ch_work_hdnk_9","text":"肺者，氣之本，魄之處也；其華在毛，其充在皮，為陽中之太陰，通於秋氣。","sortOrder":22},
  {"id":"s_work_hdnk_9_23","chapterId":"ch_work_hdnk_9","text":"腎者主蟄，封藏之本，精之處也；其華在髮，其充在骨，為陰中之少陰。通於冬氣。","sortOrder":23},
  {"id":"s_work_hdnk_9_24","chapterId":"ch_work_hdnk_9","text":"肝者，罷極之本，魂之居也；其華在爪，其充在筋，以生血氣，其味酸，其色蒼，此為陽中之少陽。通於春氣。","sortOrder":24},
  {"id":"s_work_hdnk_9_25","chapterId":"ch_work_hdnk_9","text":"脾、胃、大腸、小腸、三焦、膀胱者、食廩之本，營之居也，名曰器，能化糟粕，轉味而入出者也，其華在唇四白，其充在肌，其味甘，其色黃，此至陰之類，通於土氣。","sortOrder":25},
  {"id":"s_work_hdnk_9_26","chapterId":"ch_work_hdnk_9","text":"凡十一臟，取決於膽也。","sortOrder":26},
  {"id":"s_work_hdnk_9_27","chapterId":"ch_work_hdnk_9","text":"故人迎一盛病在少陽、二盛病在太陽、三盛病在陽明、四盛以上為格陽。","sortOrder":27},
  {"id":"s_work_hdnk_9_28","chapterId":"ch_work_hdnk_9","text":"寸口一盛病在厥陰、二盛病在少陰、三盛病在太陰、四盛已上為關陰。","sortOrder":28},
  {"id":"s_work_hdnk_9_29","chapterId":"ch_work_hdnk_9","text":"人迎與寸口俱盛四倍以上為關格。關格之脈，贏不能極於天地之精氣則死矣。","sortOrder":29},
  {"id":"s_work_hdnk_10_1","chapterId":"ch_work_hdnk_10","text":"五藏生成篇第十","sortOrder":1},
  {"id":"s_work_hdnk_10_2","chapterId":"ch_work_hdnk_10","text":"心之合脈也，其榮色也，其主腎也。","sortOrder":2},
  {"id":"s_work_hdnk_10_3","chapterId":"ch_work_hdnk_10","text":"肺之合皮也，其榮毛也，其主心也。","sortOrder":3},
  {"id":"s_work_hdnk_10_4","chapterId":"ch_work_hdnk_10","text":"肝之合筋也，其榮爪也，其主肺也。","sortOrder":4},
  {"id":"s_work_hdnk_10_5","chapterId":"ch_work_hdnk_10","text":"脾之合肉也，其榮唇也，其主肝也。","sortOrder":5},
  {"id":"s_work_hdnk_10_6","chapterId":"ch_work_hdnk_10","text":"腎之合骨也，其榮髮也，其主脾也。","sortOrder":6},
  {"id":"s_work_hdnk_10_7","chapterId":"ch_work_hdnk_10","text":"是故多食鹹，則脈凝泣而變色；多食苦，則皮稿而毛拔；多食辛，則筋急而爪枯；多食酸，則肉胝〈月芻〉而唇揭；多食甘，則骨痛而髮落，此五味之所傷也。故心欲苦，肺欲辛，肝欲酸，脾欲甘，腎欲鹹，此五味之所合也。","sortOrder":7},
  {"id":"s_work_hdnk_10_8","chapterId":"ch_work_hdnk_10","text":"五臟之氣，故色見青如草茲者死，黃如枳實者死，黑如炲者死，赤如衄血者死，白如枯骨者死，此五色之見死也。青如翠羽者生，赤如雞冠者生，黃如蟹腹者生，白如豕膏者生，黑如烏羽者生，此五色之見生也。生於心，如以縞裹朱。生於肺，如以縞裹紅。生於肝，如以縞裹紺。生於脾，如以縞裹括蔞實。生於腎，如以縞裹紫。此五臟所生之外榮也。","sortOrder":8},
  {"id":"s_work_hdnk_10_9","chapterId":"ch_work_hdnk_10","text":"色味當五臟，白當肺辛，赤當辛苦，青當肝酸，黃當脾甘，黑當腎鹼。故白當皮，赤當脈，青當筋，黃當肉，黑當骨。","sortOrder":9},
  {"id":"s_work_hdnk_10_10","chapterId":"ch_work_hdnk_10","text":"諸脈者，皆屬於目；諸髓者，皆屬於腦；諸筋者，皆屬於節；諸血者，皆屬於心；諸氣者，皆屬於肺，此四肢八谿之朝夕也。故人臥血歸於肝，肝受血而能視，足受血而能步，掌受血而能握，指受血而能攝。臥出而風吹之，血凝於膚者為痺，凝於脈者為泣、凝於足者為厥。此三者，血行而不得反其空，故為痺厥也。人有大穀十二分，小溪三百五十四名，少十二俞，此皆衛氣所留止，邪氣之所客也，針石緣而去之。","sortOrder":10},
  {"id":"s_work_hdnk_10_11","chapterId":"ch_work_hdnk_10","text":"診病之始，五決為紀。欲知其始，先建其母。所謂五決者，五脈也。","sortOrder":11},
  {"id":"s_work_hdnk_10_12","chapterId":"ch_work_hdnk_10","text":"是以頭痛巔疾，下虛上實，過在足少陰巨陽，甚則入腎。徇蒙招尤，目冥耳聾，下實上虛，過在足少陽厥陰，甚則入肝。腹滿〈月真〉脹，支膈胠脅、下厥上冒，過在足太陰陽明。咳嗽上氣，厥在胸中，過在手陽明太陰。心煩頭痛，病在膈中，過在手巨陽少陰。","sortOrder":12},
  {"id":"s_work_hdnk_10_13","chapterId":"ch_work_hdnk_10","text":"夫脈之小大，滑澀浮沈，可以指別。五臟之象，可以類推。五臟相音，可以意識。五色微診，可以目察。能合脈色，可以萬全。","sortOrder":13},
  {"id":"s_work_hdnk_10_14","chapterId":"ch_work_hdnk_10","text":"赤脈之至也，喘而堅。診曰：有積氣在中，時害於食名曰心痺。得之外疾，思慮而心虛，故邪從之。","sortOrder":14},
  {"id":"s_work_hdnk_10_15","chapterId":"ch_work_hdnk_10","text":"白脈之至也，喘而浮。上虛下實，驚，有積氣在胸中，喘而虛。名曰肺痺。寒熱，得之醉而使內也。","sortOrder":15},
  {"id":"s_work_hdnk_10_16","chapterId":"ch_work_hdnk_10","text":"青脈之至也。長而左右彈。有積氣在心下，肢胠。名曰肝痺。得之寒濕，與疝同法。腰痛足清頭痛。","sortOrder":16},
  {"id":"s_work_hdnk_10_17","chapterId":"ch_work_hdnk_10","text":"黃脈之至也，大而虛。有積氣在腹中，有厥氣，名曰厥疝。女子同法，得之疾使四肢，汗出當風。","sortOrder":17},
  {"id":"s_work_hdnk_10_18","chapterId":"ch_work_hdnk_10","text":"黑脈之至也，上堅而大。有積氣在小腹與陰，名曰腎痺。得之沐浴，清水而臥。","sortOrder":18},
  {"id":"s_work_hdnk_10_19","chapterId":"ch_work_hdnk_10","text":"凡相五色之奇脈，面黃目青，面黃目赤，面黃目白，面黃目黑者，皆不死也。面青目赤，面赤目白，面青目黑，面黑目白，面赤目青，皆死也。","sortOrder":19},
  {"id":"s_work_hdnk_11_1","chapterId":"ch_work_hdnk_11","text":"五藏別論篇第十一","sortOrder":1},
  {"id":"s_work_hdnk_11_2","chapterId":"ch_work_hdnk_11","text":"黃帝問曰：餘聞方士，或以腦髓為臟，或以腸胃為臟，或以為腑。敢問更相反，皆自謂是，不知其道，願聞其說。","sortOrder":2},
  {"id":"s_work_hdnk_11_3","chapterId":"ch_work_hdnk_11","text":"岐伯對曰：腦、髓、骨、脈、膽、女子胞此六者，地氣之所生也。皆臟於陰而象於地，故藏而不瀉，名曰奇恒之府。","sortOrder":3},
  {"id":"s_work_hdnk_11_4","chapterId":"ch_work_hdnk_11","text":"夫胃大腸、小腸、三焦、膀胱此五者天氣之所生也，其氣象天，故瀉而不藏。此受五藏濁氣，名曰傳化之府，此不能久留，輸瀉者也。","sortOrder":4},
  {"id":"s_work_hdnk_11_5","chapterId":"ch_work_hdnk_11","text":"魄門亦為五臟使，水穀不得久藏。","sortOrder":5},
  {"id":"s_work_hdnk_11_6","chapterId":"ch_work_hdnk_11","text":"所謂五臟者，藏精氣而不瀉也，故滿而不能實。","sortOrder":6},
  {"id":"s_work_hdnk_11_7","chapterId":"ch_work_hdnk_11","text":"六腑者，傳化物而不藏，故實而不能滿也。所以然者，水穀入口則胃實而腸虛，食下則腸實而胃虛。","sortOrder":7},
  {"id":"s_work_hdnk_11_8","chapterId":"ch_work_hdnk_11","text":"故曰實而不滿，滿而不實也。","sortOrder":8},
  {"id":"s_work_hdnk_11_9","chapterId":"ch_work_hdnk_11","text":"帝曰：氣口何以獨為五臟之主？岐伯說：胃者水穀之海，六腑之大源也。五味入口，藏於胃以養五臟氣，氣口亦太陰也，是以五臟六腑之氣味，皆出於胃，變見於氣口。故五氣入鼻，藏於心肺，心肺有病，而鼻為之不利也。","sortOrder":9},
  {"id":"s_work_hdnk_11_10","chapterId":"ch_work_hdnk_11","text":"凡治病必察其下，適其脈，觀其志意，與其病也。","sortOrder":10},
  {"id":"s_work_hdnk_11_11","chapterId":"ch_work_hdnk_11","text":"拘於鬼神者，不可與言至德；惡於針石者，不可與言至巧。病不許治者，病必不治，治之無功矣。","sortOrder":11},
  {"id":"s_work_hdnk_12_1","chapterId":"ch_work_hdnk_12","text":"異法方宜論篇第十二","sortOrder":1},
  {"id":"s_work_hdnk_12_2","chapterId":"ch_work_hdnk_12","text":"黃帝問曰：醫之治病也，一病而治各不同，皆愈何也？岐伯對曰：地勢使然也。","sortOrder":2},
  {"id":"s_work_hdnk_12_3","chapterId":"ch_work_hdnk_12","text":"故東方之域，天地之所始生也。魚鹽之地，海濱傍水，其民食魚而嗜鹹，皆安其處，美其食。魚者使人熱中，鹽者勝血，故其民皆黑色疏理。其病皆為癰瘍，其治宜砭石。故砭石者，亦從東方來。","sortOrder":3},
  {"id":"s_work_hdnk_12_4","chapterId":"ch_work_hdnk_12","text":"西方者金玉之域，沙石之處，天地之所收引也。其民陵居而多風，水土剛強，其民不衣而褐荐，其民華食而脂肥，故邪不能傷其形體，其病生於內，其治宜毒藥。故毒藥者亦從西方來。","sortOrder":4},
  {"id":"s_work_hdnk_12_5","chapterId":"ch_work_hdnk_12","text":"北方者，天地所閉藏之域也。其地高陵居，風寒冰冽，其民樂野處而乳食，臟寒生滿病，其治宜灸炳。故灸炳者，亦從北方來。","sortOrder":5},
  {"id":"s_work_hdnk_12_6","chapterId":"ch_work_hdnk_12","text":"南方者，天地所長養，陽之所盛處也。其地下，水土弱，霧露之所聚也。其民嗜酸而食胕，故其民皆致理而赤色，其病攣痺，其治宜微針。故九針者，亦從南方來。","sortOrder":6},
  {"id":"s_work_hdnk_12_7","chapterId":"ch_work_hdnk_12","text":"中央者，其地平以濕，天地所以生萬物也眾。其民食雜而不勞，故其病多痿厥寒熱。其治宜導引按蹻，故導引按蹻者，亦從中央出也。","sortOrder":7},
  {"id":"s_work_hdnk_12_8","chapterId":"ch_work_hdnk_12","text":"故聖人雜合以治，各得其所宜，故治所以異而病皆愈者，得病之情，知治之大體也。","sortOrder":8},
  {"id":"s_work_hdnk_13_1","chapterId":"ch_work_hdnk_13","text":"移精變氣論篇第十三","sortOrder":1},
  {"id":"s_work_hdnk_13_2","chapterId":"ch_work_hdnk_13","text":"黃帝問曰：餘聞古之治病，惟其移精變氣，可祝由而己。今世治病，毒藥治其內，針石治其外，或愈或不愈，何也？","sortOrder":2},
  {"id":"s_work_hdnk_13_3","chapterId":"ch_work_hdnk_13","text":"岐伯對曰：往古人居禽獸之間，動作以避寒，陰居以避暑，內無眷暮之累，外無伸官之形，此恬淡之世，邪不能深入也。故毒藥不能治其內，針石不能治其外，故可移精祝由而己。","sortOrder":3},
  {"id":"s_work_hdnk_13_4","chapterId":"ch_work_hdnk_13","text":"當今之世不然，憂患緣其內，苦形傷其外，又失四時之從，逆寒暑之宜。賊風數至，虛邪朝夕，內至五臟骨髓，外傷空竅肌膚，所以小病必甚，大病必死。故祝由不能己也。","sortOrder":4},
  {"id":"s_work_hdnk_13_5","chapterId":"ch_work_hdnk_13","text":"帝曰：善。餘欲臨病人，觀死生，決嫌疑，欲知其要，如日月光，可得聞乎？岐伯曰：色脈者，上帝之所貴也，先師之所傳也。","sortOrder":5},
  {"id":"s_work_hdnk_13_6","chapterId":"ch_work_hdnk_13","text":"上古使僦貸季理色脈而通神明，合之金木水火土，四時八風六合，不離其常，變化相移，以觀其妙，以知其要，欲知其要，則色脈是矣。","sortOrder":6},
  {"id":"s_work_hdnk_13_7","chapterId":"ch_work_hdnk_13","text":"色以應日，脈以應月，常求其要，則其要也。夫色之變化以應四時之脈，此上帝之所貴，以合於神明也。所以遠死而近生，生道以長，命曰聖王。","sortOrder":7},
  {"id":"s_work_hdnk_13_8","chapterId":"ch_work_hdnk_13","text":"中古之治病，至而治之，湯液十日，以去八風五痺之病。十日不已，治以草蘇草荄之枝，本末為助，標本已得，邪氣乃服。","sortOrder":8},
  {"id":"s_work_hdnk_13_9","chapterId":"ch_work_hdnk_13","text":"暮世之病也，則不然，治不本四時，不知日月，不審逆從，病形已成，乃慾微針其外，湯液治其內，粗工兇兇以為可攻，故病未已，新病復起。","sortOrder":9},
  {"id":"s_work_hdnk_13_10","chapterId":"ch_work_hdnk_13","text":"帝曰：願聞要道。岐伯曰：治之要極，無夫色脈，用之不惑，治之大則。逆從到行，標本不得，亡神失國。去故就新，乃得真人。","sortOrder":10},
  {"id":"s_work_hdnk_13_11","chapterId":"ch_work_hdnk_13","text":"帝曰：餘聞其要於夫子矣，夫子言不離色脈，此餘之所知也。岐伯曰：治之極於一。帝曰：何謂一？岐伯曰：一者因得之。帝曰：奈何？岐伯曰：閉戶塞牖，系之病者，數問其情，以從其意，得神者昌，失神者亡。帝曰：善。","sortOrder":11},
  {"id":"s_work_hdnk_14_1","chapterId":"ch_work_hdnk_14","text":"湯液醪醴論篇第十四","sortOrder":1},
  {"id":"s_work_hdnk_14_2","chapterId":"ch_work_hdnk_14","text":"黃帝問曰：為五穀湯液及醪醴奈何？岐伯對曰：必以稻米，炊之稻薪，稻米者完，稻薪者堅。帝曰：何以然？岐伯曰：此得天地之和，高下之宜，故能至完：伐取得時，故能至堅也。","sortOrder":2},
  {"id":"s_work_hdnk_14_3","chapterId":"ch_work_hdnk_14","text":"帝曰：上古聖人作湯液醪醴，為而不用何也？岐伯曰：自古聖人之作湯液醪醴者，以為備耳！夫上古作湯液，故為而弗服也。","sortOrder":3},
  {"id":"s_work_hdnk_14_4","chapterId":"ch_work_hdnk_14","text":"中古之世，道德稍衰，邪氣時至，服之萬全。","sortOrder":4},
  {"id":"s_work_hdnk_14_5","chapterId":"ch_work_hdnk_14","text":"帝曰：今之世不必已何也。岐伯曰：當今之世，必齊毒藥攻其中，鑱石針艾治其外也。","sortOrder":5},
  {"id":"s_work_hdnk_14_6","chapterId":"ch_work_hdnk_14","text":"帝曰：形弊血盡而功不應者何？岐伯曰：神不使也。帝曰：何謂神不使？岐伯曰：針石道也。精神不進，志意不治，故病不可愈。今精壞神去，營衛不可復收。何者？嗜欲無窮，而憂患不止，精氣弛壞，營泣衛除，故神去之而病不愈也。","sortOrder":6},
  {"id":"s_work_hdnk_14_7","chapterId":"ch_work_hdnk_14","text":"帝曰：夫病之始生也，極微極精，必先入結於皮膚。今良工皆稱曰病成，名曰逆，則針石不能治，良藥不能及也。今良工皆得其法，守其數，親戚兄弟遠近音聲日聞於耳，五色日見於目，而病不愈者，亦何暇不早乎？","sortOrder":7},
  {"id":"s_work_hdnk_14_8","chapterId":"ch_work_hdnk_14","text":"岐伯曰：病為本，工為標，標本不得，邪氣不服，此之謂也。","sortOrder":8},
  {"id":"s_work_hdnk_14_9","chapterId":"ch_work_hdnk_14","text":"帝曰：其有不從毫毛而生，五臟陽以竭也，津液充郭，其魄獨居，孤精於內，氣耗於外，形不可與衣相保，此四極急而動中，是氣拒於內而形施於外，治之奈何？","sortOrder":9},
  {"id":"s_work_hdnk_14_10","chapterId":"ch_work_hdnk_14","text":"岐伯曰：平治於權衡，去宛陳莝，微動四極，溫衣繆剌其處，以復其形。開鬼門，潔淨府，精以時服；五陽已布，疏滌五臟，故精自生，形自盛，骨肉相保，巨氣乃平。帝曰：善。","sortOrder":10},
  {"id":"s_work_hdnk_15_1","chapterId":"ch_work_hdnk_15","text":"玉版論要篇第十五","sortOrder":1},
  {"id":"s_work_hdnk_15_2","chapterId":"ch_work_hdnk_15","text":"黃帝問曰：餘聞揆度奇恒，所指不同，用之奈何？岐伯對曰：揆度者，度病之淺深也；奇恒者，言奇病也。請言道之至數，五色脈變，揆度奇恒，道在於一。","sortOrder":2},
  {"id":"s_work_hdnk_15_3","chapterId":"ch_work_hdnk_15","text":"神轉不回，回則不轉，乃失其機。至數之要，迫近以微，著之玉版，命曰合玉機。","sortOrder":3},
  {"id":"s_work_hdnk_15_4","chapterId":"ch_work_hdnk_15","text":"容色見上下左右，各在其要。其色見淺者，湯液主治，十日已。其見深者，必齊主治，二十一日已。其見大深者，醪酒主治，百日已。色夭面脫不治，百日盡已。","sortOrder":4},
  {"id":"s_work_hdnk_15_5","chapterId":"ch_work_hdnk_15","text":"脈短氣絕死，病溫虛甚死。","sortOrder":5},
  {"id":"s_work_hdnk_15_6","chapterId":"ch_work_hdnk_15","text":"色見上下左右，各在其要。上為逆，下為從；女子右為逆，左為從；男子左為逆，右為從。易，重陽死，重陰死。","sortOrder":6},
  {"id":"s_work_hdnk_15_7","chapterId":"ch_work_hdnk_15","text":"陰陽反他，治在權衡相奪，奇恒事也，揆度事也。","sortOrder":7},
  {"id":"s_work_hdnk_15_8","chapterId":"ch_work_hdnk_15","text":"搏脈痺躄，寒熱之交。脈孤為消氣，虛泄為奪血。孤為逆，虛為從。","sortOrder":8},
  {"id":"s_work_hdnk_15_9","chapterId":"ch_work_hdnk_15","text":"行奇恒之法，以太陰始。行所不勝曰逆勝，逆則死。行所勝曰從，從則活。八風四時之勝，終而復始，逆行一過，不可復數，論要畢矣。","sortOrder":9},
  {"id":"s_work_hdnk_16_1","chapterId":"ch_work_hdnk_16","text":"診要經終論篇第十六","sortOrder":1},
  {"id":"s_work_hdnk_16_2","chapterId":"ch_work_hdnk_16","text":"黃帝問曰：診要何如？岐伯對曰：正月二月，天氣始方，地氣始發，人氣在肝。","sortOrder":2},
  {"id":"s_work_hdnk_16_3","chapterId":"ch_work_hdnk_16","text":"三月四月天氣正方，地氣定發，人氣在脾。","sortOrder":3},
  {"id":"s_work_hdnk_16_4","chapterId":"ch_work_hdnk_16","text":"五月六月天氣盛，地氣高，人氣在頭。","sortOrder":4},
  {"id":"s_work_hdnk_16_5","chapterId":"ch_work_hdnk_16","text":"七月八月陰氣始殺，人氣在肺。","sortOrder":5},
  {"id":"s_work_hdnk_16_6","chapterId":"ch_work_hdnk_16","text":"九月十月陰氣始冰，地氣始閉，人氣在心。","sortOrder":6},
  {"id":"s_work_hdnk_16_7","chapterId":"ch_work_hdnk_16","text":"十一月十二月冰複，地氣合，人氣在腎。","sortOrder":7},
  {"id":"s_work_hdnk_16_8","chapterId":"ch_work_hdnk_16","text":"故春刺散俞，及與分理，血出而止。甚者傳氣，間者環也。","sortOrder":8},
  {"id":"s_work_hdnk_16_9","chapterId":"ch_work_hdnk_16","text":"夏刺絡俞，見血而止。盡氣閉環，痛病必下。","sortOrder":9},
  {"id":"s_work_hdnk_16_10","chapterId":"ch_work_hdnk_16","text":"秋刺皮膚循理，上下同法，神變而止。","sortOrder":10},
  {"id":"s_work_hdnk_16_11","chapterId":"ch_work_hdnk_16","text":"冬刺俞竅於分理，甚者直下，間者散下。","sortOrder":11},
  {"id":"s_work_hdnk_16_12","chapterId":"ch_work_hdnk_16","text":"春夏秋冬，各有所刺，法其所在。春刺夏分，脈亂氣微，入淫骨髓，病不能愈，令人不嗜食，又且少氣。","sortOrder":12},
  {"id":"s_work_hdnk_16_13","chapterId":"ch_work_hdnk_16","text":"春刺秋分，筋攣逆氣環為咳嗽，病不愈，令人時驚，又且哭。","sortOrder":13},
  {"id":"s_work_hdnk_16_14","chapterId":"ch_work_hdnk_16","text":"春刺冬分，邪氣著藏，令人脹，病不愈，又且欲言語。","sortOrder":14},
  {"id":"s_work_hdnk_16_15","chapterId":"ch_work_hdnk_16","text":"夏刺春分，病不愈，令人解墮。","sortOrder":15},
  {"id":"s_work_hdnk_16_16","chapterId":"ch_work_hdnk_16","text":"夏刺秋分，病不愈，令人心中欲無言，惕惕如人將捕之。","sortOrder":16},
  {"id":"s_work_hdnk_16_17","chapterId":"ch_work_hdnk_16","text":"夏刺冬分，病不愈，令人少氣，時欲怒。","sortOrder":17},
  {"id":"s_work_hdnk_16_18","chapterId":"ch_work_hdnk_16","text":"秋刺春分，病不已，令人惕然，欲有所為，起而忘之。","sortOrder":18},
  {"id":"s_work_hdnk_16_19","chapterId":"ch_work_hdnk_16","text":"秋刺夏分，病不已，令人益嗜臥，且又善夢。","sortOrder":19},
  {"id":"s_work_hdnk_16_20","chapterId":"ch_work_hdnk_16","text":"秋刺冬分，病不已，令人洒洒時寒。","sortOrder":20},
  {"id":"s_work_hdnk_16_21","chapterId":"ch_work_hdnk_16","text":"冬刺春分，病不已，令人欲臥不能眠，眠而有見。","sortOrder":21},
  {"id":"s_work_hdnk_16_22","chapterId":"ch_work_hdnk_16","text":"冬刺夏分，病不愈，氣上發為諸痺。","sortOrder":22},
  {"id":"s_work_hdnk_16_23","chapterId":"ch_work_hdnk_16","text":"冬刺秋分，病不已，令人善渴。","sortOrder":23},
  {"id":"s_work_hdnk_16_24","chapterId":"ch_work_hdnk_16","text":"凡刺胸腹者，必避五臟。中心者環死，中脾者五日死，中腎者七日死，中肺者五日死。中膈者，皆為傷中，其病雖愈，不過一歲必死。","sortOrder":24},
  {"id":"s_work_hdnk_16_25","chapterId":"ch_work_hdnk_16","text":"刺避五臟者，知逆從也。所謂從者，膈與脾腎之處，不知者反之。刺胸腹者，必以布憿著之，乃從單布上刺，刺之不愈復刺。","sortOrder":25},
  {"id":"s_work_hdnk_16_26","chapterId":"ch_work_hdnk_16","text":"刺針必肅，刺腫搖針，經刺勿搖，此刺之道也。","sortOrder":26},
  {"id":"s_work_hdnk_16_27","chapterId":"ch_work_hdnk_16","text":"帝曰：願聞十二經脈之終奈何？岐伯曰：太陽之脈，其終也戴眼，反折瘈瘲，其色白，絕汗乃出，出則死矣。","sortOrder":27},
  {"id":"s_work_hdnk_16_28","chapterId":"ch_work_hdnk_16","text":"少陽終者，耳聾、百節皆縱，目寰絕系。絕系一日半死，其死也色先青，白乃死矣。","sortOrder":28},
  {"id":"s_work_hdnk_16_29","chapterId":"ch_work_hdnk_16","text":"陽明終者，口目動作，善驚、妄言、色黃。其上下經盛，不仁則終矣。","sortOrder":29},
  {"id":"s_work_hdnk_16_30","chapterId":"ch_work_hdnk_16","text":"少陰終者，面黑齒長而垢，腹脹閉，上下不通而終矣。","sortOrder":30},
  {"id":"s_work_hdnk_16_31","chapterId":"ch_work_hdnk_16","text":"太陰終者，腹脹閉，不得息，善噫善嘔，嘔則逆，逆則面赤，不逆則上下不通，不通則面黑，皮毛焦而終矣。","sortOrder":31},
  {"id":"s_work_hdnk_16_32","chapterId":"ch_work_hdnk_16","text":"厥陰終者，中熱溢乾，善溺、心煩、甚則舌卷，卵上縮而終矣。此十二經之所敗也。","sortOrder":32},
  {"id":"s_work_hdnk_17_1","chapterId":"ch_work_hdnk_17","text":"脈要精微論篇第十七","sortOrder":1},
  {"id":"s_work_hdnk_17_2","chapterId":"ch_work_hdnk_17","text":"黃帝問曰：診法何如？岐伯對曰：診法常以平旦，陰氣未動，陽氣未散，飲食未進，經脈未盛，絡脈調勻，氣血未亂，故乃可診有過之脈。","sortOrder":2},
  {"id":"s_work_hdnk_17_3","chapterId":"ch_work_hdnk_17","text":"切脈動靜而視精明，察五色，觀五臟有餘不足，六腑強弱，形之盛衰，以此參伍，決死生之分。","sortOrder":3},
  {"id":"s_work_hdnk_17_4","chapterId":"ch_work_hdnk_17","text":"夫脈者血之府也。長則氣治，短則氣病，數則煩心，大則病進。","sortOrder":4},
  {"id":"s_work_hdnk_17_5","chapterId":"ch_work_hdnk_17","text":"上盛則氣急、下盛則氣脹、代則氣衰、細則氣少、澀則心痛。","sortOrder":5},
  {"id":"s_work_hdnk_17_6","chapterId":"ch_work_hdnk_17","text":"渾渾革至如湧泉，病進而色弊；綿綿其去如絃絕死。","sortOrder":6},
  {"id":"s_work_hdnk_17_7","chapterId":"ch_work_hdnk_17","text":"夫精明五色者，氣之華也。赤欲如白裹朱，不欲如赭；白欲如鵝羽，不欲如鹽；青欲如蒼璧之澤，不欲如藍；黃欲如羅裹雄黃，不欲如黃土；黑欲如重漆色，不欲如地蒼。五色精微象見矣，其壽不久也。","sortOrder":7},
  {"id":"s_work_hdnk_17_8","chapterId":"ch_work_hdnk_17","text":"夫精明者，所以視萬物別白黑，審短長，以長為短，以白為黑。如是則精衰矣。","sortOrder":8},
  {"id":"s_work_hdnk_17_9","chapterId":"ch_work_hdnk_17","text":"五臟者中之守也。中盛臟滿氣盛傷恐者，聲如從室中言，是中氣之濕也。言而微，終日乃復言者，此奪氣也。衣被不歛，言語善惡，不避親疏者，此神明之亂也。倉廩不藏者，是門戶不要也，水泉不止者，是膀胱不藏也。得守者生，失守者死。","sortOrder":9},
  {"id":"s_work_hdnk_17_10","chapterId":"ch_work_hdnk_17","text":"夫五臟者身之強也。頭者精明之府，頭傾視深精神將奪矣。背者胸中之府，背曲肩隨，府將壞矣。腰者腎之府，轉搖不能，腎將憊矣。膝者筋之府，屈伸不能，行則僂附，筋將憊矣。骨者髓之府，不能久立，行則振掉，骨將憊矣。得強則生，失強則死。","sortOrder":10},
  {"id":"s_work_hdnk_17_11","chapterId":"ch_work_hdnk_17","text":"岐伯曰：反四時者，有餘為精，不足為消。應太過不足為精，應不足有餘為消。陰陽不相應，病名曰關格。","sortOrder":11},
  {"id":"s_work_hdnk_17_12","chapterId":"ch_work_hdnk_17","text":"帝曰：脈其四時動奈何？知病之所在奈何？知病之所變奈何？知病乍在內奈何？知病乍在外奈何？請問此五者，可得聞乎。","sortOrder":12},
  {"id":"s_work_hdnk_17_13","chapterId":"ch_work_hdnk_17","text":"岐伯曰：請言其與天運轉大也。萬物之外，六合之內，天地之變，陰陽之應，彼春之暖，為夏之暑，彼秋之忿，為冬之怒，四變之動脈與之上下，以春應中規，夏應中矩，秋應中衡，冬應中權。","sortOrder":13},
  {"id":"s_work_hdnk_17_14","chapterId":"ch_work_hdnk_17","text":"是故冬至四十五日陽氣微上，陰氣微下；夏至四十五日陰氣微上陽氣微下，陰陽有時，與脈為期，期而相失，知脈所分。分之有期，故知死時。微妙在脈，不可不察，察之有紀，從陰陽始，始之有經，從五行生，生之有度，四時為宜。補瀉勿失，與天地如一，得一之情，以知死生。","sortOrder":14},
  {"id":"s_work_hdnk_17_15","chapterId":"ch_work_hdnk_17","text":"是故聲合五音，色合五行，脈合陰陽。","sortOrder":15},
  {"id":"s_work_hdnk_17_16","chapterId":"ch_work_hdnk_17","text":"是知陰盛則夢涉大水恐懼，陽盛則夢大火燔灼。","sortOrder":16},
  {"id":"s_work_hdnk_17_17","chapterId":"ch_work_hdnk_17","text":"陰陽俱盛，則夢相殺毀傷。","sortOrder":17},
  {"id":"s_work_hdnk_17_18","chapterId":"ch_work_hdnk_17","text":"上盛則夢飛，下盛則夢墮，甚飽則夢予，甚飢則夢取；肝氣盛則夢怒，肺氣盛則夢哭。","sortOrder":18},
  {"id":"s_work_hdnk_17_19","chapterId":"ch_work_hdnk_17","text":"短蟲多則夢聚眾，長蟲多則夢相擊毀傷。","sortOrder":19},
  {"id":"s_work_hdnk_17_20","chapterId":"ch_work_hdnk_17","text":"是故持脈有道，虛靜為保。春日浮，如魚之遊在波；夏日在膚，泛泛乎萬物有餘；秋日下膚，蟄蟲將去；冬日在骨，蟄蟲周密，君子居室。故曰：知內者按而紀之，知外者終而始之，此六者持脈之大法。","sortOrder":20},
  {"id":"s_work_hdnk_17_21","chapterId":"ch_work_hdnk_17","text":"心脈搏堅而長，當病舌卷不能言；其軟而散者，當消環自己。","sortOrder":21},
  {"id":"s_work_hdnk_17_22","chapterId":"ch_work_hdnk_17","text":"肺脈搏堅而長，當病唾血；其軟而散者，當病灌汗，至今不復散發也。","sortOrder":22},
  {"id":"s_work_hdnk_17_23","chapterId":"ch_work_hdnk_17","text":"肝脈搏堅而長，色不青，當病墜若搏，因血在脅下，令人喘逆；其軟而散色澤者，當病溢飲，溢飲者，渴暴多飲，而易入肌皮腸胃之外也。","sortOrder":23},
  {"id":"s_work_hdnk_17_24","chapterId":"ch_work_hdnk_17","text":"胃脈搏堅而長，其色赤，當病折髀，其軟而散者，當病食痺。","sortOrder":24},
  {"id":"s_work_hdnk_17_25","chapterId":"ch_work_hdnk_17","text":"脾脈搏堅而長，其色黃，當病少氣；其軟而散色不澤者，當病足〈骨行〉腫，若水狀也。","sortOrder":25},
  {"id":"s_work_hdnk_17_26","chapterId":"ch_work_hdnk_17","text":"腎脈搏堅而長，其色黃而赤者，當病折腰；其軟而散者，當病少血至今不復也。","sortOrder":26},
  {"id":"s_work_hdnk_17_27","chapterId":"ch_work_hdnk_17","text":"帝曰：診得心脈而急，此為何病，病形何如？岐伯曰：病名心疝，少腹當有形也。帝曰：何以言之？岐伯曰：心為牡臟，小腸為之使，故曰少腹當有形也。","sortOrder":27},
  {"id":"s_work_hdnk_17_28","chapterId":"ch_work_hdnk_17","text":"帝曰：診得胃脈，病形何如？岐伯曰：胃脈實則脹，虛則泄。","sortOrder":28},
  {"id":"s_work_hdnk_17_29","chapterId":"ch_work_hdnk_17","text":"帝曰：病成而變何謂？岐伯曰：風成為寒熱，癉成為消中，厥成為巔疾，久風為飧泄，脈風成為癘。病之變化，不可勝數。","sortOrder":29},
  {"id":"s_work_hdnk_17_30","chapterId":"ch_work_hdnk_17","text":"帝曰：諸癰腫筋攣骨痛，此皆安生？岐伯曰：此寒氣之腫，八風之變也。帝曰：治之奈何？岐伯曰：比四時之病，以其勝治之愈也。","sortOrder":30},
  {"id":"s_work_hdnk_17_31","chapterId":"ch_work_hdnk_17","text":"帝曰：有故病五臟發動，因傷脈色，各何以知其久暴至之病乎？岐伯曰：悉乎哉問也，徵其脈小色不奪者，新病也；徵其脈不奪其色奪者，此久病也；徵其脈與五色俱奪者此久病也；徵其脈與五色俱不奪者新病也。肝與腎脈並至，其色蒼赤，當病毀傷不見血，已見血濕若中水也。","sortOrder":31},
  {"id":"s_work_hdnk_17_32","chapterId":"ch_work_hdnk_17","text":"尺內兩旁則季脅也，尺外以候腎，尺裏以候腹中。附上左外以候肝，內以候鬲，右外以候胃，內以候脾。上附上右外以候肺，內以候胸中，左外以候心，內以候膻中。前以候前，後以候後。上竟上者，胸喉中事也。下竟下者，少腹腰股膝脛足中事也。","sortOrder":32},
  {"id":"s_work_hdnk_17_33","chapterId":"ch_work_hdnk_17","text":"粗大者，陰不足陽有餘，為熱中也。來疾去徐，上實下虛，為厥巔疾。來徐去疾，上虛下實，為惡風也。故中惡風者，陽氣受也。","sortOrder":33},
  {"id":"s_work_hdnk_17_34","chapterId":"ch_work_hdnk_17","text":"有脈俱沉細數者，少陰厥也；沉細數散者，寒熱也；浮而散者為朐仆。諸浮不躁者，皆在陽，則為熱；其有躁者在手，諸細而沉者，皆在陰，則為骨痛；其有靜者在足。數動一代者，病在陽之脈也。泄及便膿血。","sortOrder":34},
  {"id":"s_work_hdnk_17_35","chapterId":"ch_work_hdnk_17","text":"諸過者切之，澀者陽氣有餘也，滑者陰氣有餘也；陽氣有餘為身熱無汗，陰氣有餘為多汗身寒，陰陽有餘則無汗而寒。","sortOrder":35},
  {"id":"s_work_hdnk_17_36","chapterId":"ch_work_hdnk_17","text":"推而外之，內而不外，有心腹積也。推而內之，外而不內，身有熱也。推而上之，上而不下，腰足清也。推而下之，下而不上，頭項痛也。按之至骨，脈氣少者，腰脊痛而身有痺也。","sortOrder":36},
  {"id":"s_work_hdnk_18_1","chapterId":"ch_work_hdnk_18","text":"平人氣象論篇第十八","sortOrder":1},
  {"id":"s_work_hdnk_18_2","chapterId":"ch_work_hdnk_18","text":"黃帝問曰：平人何如？","sortOrder":2},
  {"id":"s_work_hdnk_18_3","chapterId":"ch_work_hdnk_18","text":"岐伯對曰：人一呼脈再動，一吸脈亦再動，呼吸定息，脈五動，閏以太息，命日平人。平人者不病也。","sortOrder":3},
  {"id":"s_work_hdnk_18_4","chapterId":"ch_work_hdnk_18","text":"常以不病調病人，醫不病，故為病人平息以調之為法。","sortOrder":4},
  {"id":"s_work_hdnk_18_5","chapterId":"ch_work_hdnk_18","text":"人一呼脈一動，一吸脈一動，日少氣。","sortOrder":5},
  {"id":"s_work_hdnk_18_6","chapterId":"ch_work_hdnk_18","text":"人一呼脈三動，一吸脈三動而躁，尺熱曰病溫，尺不熱脈滑曰病風，脈澀曰痺。","sortOrder":6},
  {"id":"s_work_hdnk_18_7","chapterId":"ch_work_hdnk_18","text":"人一呼脈四動以上曰死，脈絕不至曰死，乍疏乍數曰死。","sortOrder":7},
  {"id":"s_work_hdnk_18_8","chapterId":"ch_work_hdnk_18","text":"平人之常氣稟於胃，胃者平人之常氣也，人無胃氣曰逆，逆者死。","sortOrder":8},
  {"id":"s_work_hdnk_18_9","chapterId":"ch_work_hdnk_18","text":"春胃微絃曰平，絃多胃少曰肝病，但絃無胃曰死。胃而有毛曰秋病，毛甚曰今病。臟真散於肝，肝臟筋膜之氣也。","sortOrder":9},
  {"id":"s_work_hdnk_18_10","chapterId":"ch_work_hdnk_18","text":"長夏胃微軟弱曰平，弱多胃少曰脾病，但代無胃曰死，軟弱有石曰冬病，弱甚曰今病。臟真濡於脾，脾藏肌肉之氣也。","sortOrder":10},
  {"id":"s_work_hdnk_18_11","chapterId":"ch_work_hdnk_18","text":"夏胃微鉤曰平，鉤多胃少曰心病，但鉤旡胃曰死，胃而有石曰冬病，石甚曰今病。臟真通於心，心藏血脈之氣也。","sortOrder":11},
  {"id":"s_work_hdnk_18_12","chapterId":"ch_work_hdnk_18","text":"秋胃微毛曰平，毛多胃少曰肺病，但毛無胃曰死，毛而有絃曰春病，絃甚曰今病。臟真高於肺，以行營衛陰陽也。","sortOrder":12},
  {"id":"s_work_hdnk_18_13","chapterId":"ch_work_hdnk_18","text":"冬胃微石曰平，石多胃少曰腎病，但石無胃曰死，石而有鉤曰夏病，鉤甚曰今病。臟真下於腎，腎藏骨髓之氣也。","sortOrder":13},
  {"id":"s_work_hdnk_18_14","chapterId":"ch_work_hdnk_18","text":"胃之大絡。名曰虛里，貫鬲絡肺，出於左乳下，其動應衣，脈宗氣也。","sortOrder":14},
  {"id":"s_work_hdnk_18_15","chapterId":"ch_work_hdnk_18","text":"盛喘數絕者，則在病中，結而橫有積矣。絕不至曰死，乳之下其動應衣，宗氣泄也。","sortOrder":15},
  {"id":"s_work_hdnk_18_16","chapterId":"ch_work_hdnk_18","text":"欲知寸口太過與不及，寸口之脈中手短者，曰頭痛；寸口脈中手長者，曰足脛痛；寸口脈中手促上擊者，曰肩脊痛；寸口脈沉而堅者，曰病在中；寸口脈浮而盛者，曰病在外；寸口脈沉而弱，曰寒熱及疝瘕少腹痛；寸口脈沉而橫，曰脅下有積，腹中有橫積痛：寸口脈沉而澀，曰寒熱。","sortOrder":16},
  {"id":"s_work_hdnk_18_17","chapterId":"ch_work_hdnk_18","text":"脈盛滑堅者，曰病在外；脈小實而堅者，病在內。","sortOrder":17},
  {"id":"s_work_hdnk_18_18","chapterId":"ch_work_hdnk_18","text":"脈小弱以澀，謂之久病；脈滑浮而疾者，謂之新病。","sortOrder":18},
  {"id":"s_work_hdnk_18_19","chapterId":"ch_work_hdnk_18","text":"脈急者，曰疝瘕少腹痛。脈滑曰風，脈澀曰痺，緩而滑曰熱中，盛而堅曰脹。","sortOrder":19},
  {"id":"s_work_hdnk_18_20","chapterId":"ch_work_hdnk_18","text":"脈從陰陽，病易已；脈逆陰陽，病難已；脈得四時之順，曰病無他；脈反四時及不間臟曰難已。","sortOrder":20},
  {"id":"s_work_hdnk_18_21","chapterId":"ch_work_hdnk_18","text":"臂多青脈曰脫血，尺脈緩澀，謂之解〈亻亦〉，安臥脈盛謂之脫血，尺澀脈滑謂之多汗，尺寒脈細謂之後泄，脈尺粗常熱者謂之熱中。","sortOrder":21},
  {"id":"s_work_hdnk_18_22","chapterId":"ch_work_hdnk_18","text":"肝見庚辛死，心見壬癸死，脾見甲乙死，肺見丙丁死，腎見戊己死。是為真臟見，皆死。","sortOrder":22},
  {"id":"s_work_hdnk_18_23","chapterId":"ch_work_hdnk_18","text":"頸脈動喘疾咳曰水，目裹微腫如臥蠶起之狀曰水。","sortOrder":23},
  {"id":"s_work_hdnk_18_24","chapterId":"ch_work_hdnk_18","text":"溺黃赤安臥者，黃疸。已食如飢者，胃疸。","sortOrder":24},
  {"id":"s_work_hdnk_18_25","chapterId":"ch_work_hdnk_18","text":"面腫曰風。足脛腫曰水。目黃者曰黃疸。","sortOrder":25},
  {"id":"s_work_hdnk_18_26","chapterId":"ch_work_hdnk_18","text":"婦人手少陰脈動甚者，妊子也。","sortOrder":26},
  {"id":"s_work_hdnk_18_27","chapterId":"ch_work_hdnk_18","text":"脈有逆從四時，未有臟形。春夏而脈瘦，秋冬而脈浮大，命曰逆四時也。","sortOrder":27},
  {"id":"s_work_hdnk_18_28","chapterId":"ch_work_hdnk_18","text":"風熱而脈靜，泄而脫血脈實，病在中脈虛，病在外脈堅澀者，皆難治，命曰反四時也。","sortOrder":28},
  {"id":"s_work_hdnk_18_29","chapterId":"ch_work_hdnk_18","text":"人以水穀為本，故人絕水穀則死，脈無胃氣亦死。所謂無胃氣者，但得真臟脈不得胃氣也。所謂脈不得胃氣者，肝不絃，腎不石也。","sortOrder":29},
  {"id":"s_work_hdnk_18_30","chapterId":"ch_work_hdnk_18","text":"太陽脈至，洪大以長；少陽脈至，乍數乍疏，乍短乍長；陽明脈至，浮大而短。","sortOrder":30},
  {"id":"s_work_hdnk_18_31","chapterId":"ch_work_hdnk_18","text":"夫平心脈來，累累如連珠，如循琅玕曰心平。復以胃氣為本。病心脈來，喘喘連屬，其中微曲曰心病。死心脈來，前曲後居，如操帶鉤曰心死。","sortOrder":31},
  {"id":"s_work_hdnk_18_32","chapterId":"ch_work_hdnk_18","text":"平肺脈來，厭厭聶聶，如落榆莢，曰肺平。秋以胃氣為本。病肺脈來，不上不下，如循雞羽，曰肺病。死肺脈來，如物之浮，如風吹毛，曰肺死。","sortOrder":32},
  {"id":"s_work_hdnk_18_33","chapterId":"ch_work_hdnk_18","text":"平肝脈來，軟弱招招，如揭長竿末梢曰肝平。春以胃氣為本。病肝脈來，盈實而滑，如循長竿，曰肝病。死肝脈來，急益勁如新張弓絃，曰肝死。","sortOrder":33},
  {"id":"s_work_hdnk_18_34","chapterId":"ch_work_hdnk_18","text":"平脾脈來，和柔相離，如雞踐地，曰脾平。長夏以胃氣為本。病脾病來，實而盈數，如雞舉足，曰脾病。死脾脈來，銳堅如鳥之喙，如鳥之距，如屋之漏，如水之流，曰脾死。","sortOrder":34},
  {"id":"s_work_hdnk_18_35","chapterId":"ch_work_hdnk_18","text":"平腎脈來，喘喘累累如鉤，按之而堅曰腎平。冬以胃氣為本。病腎脈來如引葛，按之益堅，曰腎病。死腎脈來發如奪索，辟辟石彈石，曰腎死。","sortOrder":35},
  {"id":"s_work_hdnk_19_1","chapterId":"ch_work_hdnk_19","text":"玉機真藏論篇第十九","sortOrder":1},
  {"id":"s_work_hdnk_19_2","chapterId":"ch_work_hdnk_19","text":"黃帝問曰：春脈如絃，何如而絃？","sortOrder":2},
  {"id":"s_work_hdnk_19_3","chapterId":"ch_work_hdnk_19","text":"岐伯對曰：春脈者，肝也，東方木也，萬物之所以始生也，故其氣來軟弱，輕虛而滑，端直以長，故曰絃，反此者病。","sortOrder":3},
  {"id":"s_work_hdnk_19_4","chapterId":"ch_work_hdnk_19","text":"帝曰：何如而反？岐伯曰：其氣來實而強，此謂太過，病在外。其氣來不實而微，此謂不及，病在中。帝曰：春脈太過與不及，其病皆何如？岐伯曰：太過則令人善忘，忽忽眩冒而巔疾；其不及，則令人胸痛引背，下則兩脅胠滿。","sortOrder":4},
  {"id":"s_work_hdnk_19_5","chapterId":"ch_work_hdnk_19","text":"帝曰：善。夏脈如鉤，何如而鉤？岐伯曰：夏脈者心也，南方火也，萬物之所以盛長也，故其氣來盛去衰，故曰鉤，反此者病。","sortOrder":5},
  {"id":"s_work_hdnk_19_6","chapterId":"ch_work_hdnk_19","text":"帝曰：何如而反？岐伯曰：其氣來盛去亦盛，此謂太過，病在外，其氣來不盛去反盛，此謂不及，病在中。帝曰：夏脈太過與不及，其病皆何如？岐伯曰：太過則令人身熱而膚痛，為浸淫；其不及則令人煩心，上見咳唾，下為氣泄。","sortOrder":6},
  {"id":"s_work_hdnk_19_7","chapterId":"ch_work_hdnk_19","text":"帝曰：善。秋脈如浮，何如而浮？岐伯曰：秋脈者，肺也，西方金也，萬物之所以收成也。故其氣來輕虛以浮，來急去散，故曰浮，反此者病。","sortOrder":7},
  {"id":"s_work_hdnk_19_8","chapterId":"ch_work_hdnk_19","text":"帝曰：何如而反？岐伯曰：其氣來毛而中央堅，兩傍虛，此謂太過，病在外；其氣來毛而微，此謂不及，病在中。帝曰：秋脈太過與不及，其病皆何如？岐伯曰：太過則令人逆氣而背痛。慍慍然，其不及則令人喘，呼吸少氣而咳，上氣見血，下聞病音。","sortOrder":8},
  {"id":"s_work_hdnk_19_9","chapterId":"ch_work_hdnk_19","text":"帝曰：善。冬脈如營，何如而營？岐伯曰：冬脈者，腎也。北方水也，萬物之所以含藏也。故其氣來沈以搏，故曰營，反此者病。","sortOrder":9},
  {"id":"s_work_hdnk_19_10","chapterId":"ch_work_hdnk_19","text":"帝曰：何如而反？岐伯曰：其氣來如彈石者，此謂太過，病在外；其去如數者，此謂不及，病在中。帝曰：冬脈太過與不及，其病皆何如？岐伯曰：太過則令人解〈亻亦〉，脊脈痛，而少氣不欲言；其不及則令人心懸，如病飢，〈月少〉中清，脊中痛，少腹滿，小便變。","sortOrder":10},
  {"id":"s_work_hdnk_19_11","chapterId":"ch_work_hdnk_19","text":"帝曰：善。帝曰：四時之序，逆從之變異也，然脾脈獨何主。岐伯曰：脾脈者土也，孤臟，以灌四傍者也。","sortOrder":11},
  {"id":"s_work_hdnk_19_12","chapterId":"ch_work_hdnk_19","text":"帝曰：然而脾善惡可得見之乎？岐伯曰：善者不可得見，惡者可見。帝曰：惡者何如可見？岐伯曰：其來如水之流者，此謂太過，病在外。如鳥之喙者，此謂不及，病在中。帝曰：夫子言脾為孤臟，中央以灌四傍，其太過與不及，其病皆何如？岐伯曰：太過則令人四支不舉，其不及則令人九竅不通，名曰重強。","sortOrder":12},
  {"id":"s_work_hdnk_19_13","chapterId":"ch_work_hdnk_19","text":"帝瞿然而起，再拜而稽首曰：善。吾得脈之大要，天下至數，五色脈變，揆度奇恒，道在於一，神轉不迴，迴則不轉，乃失其機，至數之要，迫近以微，著之玉版，藏之臟腑，每旦讀之，名曰玉機。","sortOrder":13},
  {"id":"s_work_hdnk_19_14","chapterId":"ch_work_hdnk_19","text":"五臟受氣於其所生，傳之於其所勝，氣舍於其所生，死於其所不勝。病之且死，必先傳行，至其所不勝，病乃死。此言氣之逆行也，故死。","sortOrder":14},
  {"id":"s_work_hdnk_19_15","chapterId":"ch_work_hdnk_19","text":"肝受氣於心，傳之於脾，氣舍於腎，至肺而死。心受氣於脾，傳之於肺，氣舍於肝，至腎而死。脾受氣於肺，傳之於腎，氣舍於心，至肝而死。肺受氣於腎，傳之於肝，氣舍於脾，至心而死。腎受氣於肝，傳之於心，氣舍於肺，至脾而死。此皆逆死也，一日一夜，五分之，此所以占死生之早暮也。","sortOrder":15},
  {"id":"s_work_hdnk_19_16","chapterId":"ch_work_hdnk_19","text":"黃帝曰：五臟相通，移皆有次。五臟有病，則各傳其所勝，不治。法三月，若六月，若三日，若六日。傳五臟而當死，是順傳其所勝之次。","sortOrder":16},
  {"id":"s_work_hdnk_19_17","chapterId":"ch_work_hdnk_19","text":"故曰：別於陽者，知病從來；別於陰者，知死生之期。言知至其所困而死。","sortOrder":17},
  {"id":"s_work_hdnk_19_18","chapterId":"ch_work_hdnk_19","text":"是故風者，百病之長也。","sortOrder":18},
  {"id":"s_work_hdnk_19_19","chapterId":"ch_work_hdnk_19","text":"今風寒客於人，使人毫毛畢直，皮膚閉而為熱。當是之時，可汗而發也。盛痺不仁腫病，當是之時，可湯熨及火灸刺而去之。弗治，病入舍於肺，名曰肺痺，發咳上氣弗治，肺即傳而行之肝，病名曰肝痺，一名曰厥，脅痛出食。當是之時，可按若刺耳。弗治，肝傳之脾，病名曰脾風，發痺，腹中熱，煩心，出黃。當此之時，可按、可藥、可浴。弗治，脾傳之腎，病名曰疝瘕，少腹寃熱而痛，出白，一名曰蠱。當此之時，可按、可藥。弗治，腎傳之心，病筋脈相引而急，病名曰瘈。當此之時，可灸、可藥。弗治，滿十日，法當死。腎因傳之心，心即復反傳而行之肺，發寒熱，法當三歲死，此病之次也。","sortOrder":19},
  {"id":"s_work_hdnk_19_20","chapterId":"ch_work_hdnk_19","text":"然其卒發者，不必治於傳，或其傳化有不以次，不以次入者，憂恐悲喜怒，令不得以其次，故令人有大病矣。","sortOrder":20},
  {"id":"s_work_hdnk_19_21","chapterId":"ch_work_hdnk_19","text":"因而喜，大虛則腎氣乘矣，怒則肝氣乘矣，悲則肺氣乘矣，恐則脾氣乘矣，憂則心氣乘矣，此其道也。故病有五，五五二十五變及其傳化。傳，乘之名也。","sortOrder":21},
  {"id":"s_work_hdnk_19_22","chapterId":"ch_work_hdnk_19","text":"大骨枯槁，大肉陷下，胸中氣滿，喘息不便，其氣動形，期六月死，真臟脈見，乃予之期日。","sortOrder":22},
  {"id":"s_work_hdnk_19_23","chapterId":"ch_work_hdnk_19","text":"大骨枯槁，大肉陷下，胸中氣滿，喘息不便，內痛引肩頸，期一月死。真臟見，乃予之期日。","sortOrder":23},
  {"id":"s_work_hdnk_19_24","chapterId":"ch_work_hdnk_19","text":"大骨枯槁，大肉陷下，胸中氣滿，喘息不便，內痛引肩項，身熱、脫肉破胭。真臟見，十月之內死。","sortOrder":24},
  {"id":"s_work_hdnk_19_25","chapterId":"ch_work_hdnk_19","text":"大骨枯槁，大肉陷下，肩髓內消，動作益衰。真臟來見，期一歲死，見其真臟，乃予之期日。","sortOrder":25},
  {"id":"s_work_hdnk_19_26","chapterId":"ch_work_hdnk_19","text":"大骨枯槁，大肉陷下，胸中氣滿，腹內痛，心中不便，肩項身熱，破胭脫肉，目眶陷。真臟見，目不見人，立死；其見人者，至其所不勝之時則死。","sortOrder":26},
  {"id":"s_work_hdnk_19_27","chapterId":"ch_work_hdnk_19","text":"急虛身中卒至，五臟絕閉，脈道不通，氣不往來，譬如墮溺，不可為期。其脈絕不來，若人一息五、六至，其形肉不脫，真臟雖不見，猶死也。","sortOrder":27},
  {"id":"s_work_hdnk_19_28","chapterId":"ch_work_hdnk_19","text":"真肝脈至，中外急，如循刀刃，責責然如按琴瑟絃，色青白不澤，毛折，乃死。真心脈至，堅而搏，如循薏苡子，累累然，色赤黑不澤，毛折，乃死。真肺脈至，大而虛，如以毛羽中人膚，色白赤不澤，毛折，乃死。真腎脈至，搏而絕，如指彈石，辟辟然，色黑黃不澤，毛折，乃死，真脾脈至，弱而乍數乍疏，色黃青不澤，毛折，乃死。諸真臟脈者，皆死不治也。","sortOrder":28},
  {"id":"s_work_hdnk_19_29","chapterId":"ch_work_hdnk_19","text":"黃帝曰：見真臟曰死，何也？岐伯曰：五臟者，皆稟氣於胃，胃者五臟之本也；臟氣者，不能自致於手太陰，必因於胃氣，乃至於手太陰也。故五臟各以其時，自為而至於手太陰也。故邪氣勝者，精氣衰也。故病甚者，胃氣不能與之俱至於手太陰，故真臟之氣獨見，獨見者，病勝臟也，故曰死。帝曰：善。","sortOrder":29},
  {"id":"s_work_hdnk_19_30","chapterId":"ch_work_hdnk_19","text":"黃帝曰：凡治病察其形氣色澤，脈之盛衰，病之新故，乃治之無後其時。","sortOrder":30},
  {"id":"s_work_hdnk_19_31","chapterId":"ch_work_hdnk_19","text":"形氣相得，謂之可治，色澤以浮，謂之易已；脈從四時，謂之可治；脈弱以滑，是有胃氣，命曰易治，取之以時；形氣相失，謂之難治；色夭不澤，謂之難已；脈實以堅，謂之益甚；脈逆四時，為不可治，必察四難，而明告之。","sortOrder":31},
  {"id":"s_work_hdnk_19_32","chapterId":"ch_work_hdnk_19","text":"所謂逆四時者，春得肺脈，夏得腎脈，秋得心脈，冬得脾脈；其至皆懸絕沈澀者，命曰逆四時。","sortOrder":32},
  {"id":"s_work_hdnk_19_33","chapterId":"ch_work_hdnk_19","text":"未有臟形，於春夏而脈沈澀，秋冬而脈浮大，名曰逆四時也。","sortOrder":33},
  {"id":"s_work_hdnk_19_34","chapterId":"ch_work_hdnk_19","text":"病熱脈靜；泄而脈大；脫血而脈實；病在中，脈實堅，病在外，脈不實堅者；皆難治。","sortOrder":34},
  {"id":"s_work_hdnk_19_35","chapterId":"ch_work_hdnk_19","text":"黃帝曰：餘聞虛實以決死生，願聞其情？岐伯曰：五實死，五虛死。帝曰：願聞五實五虛？岐伯曰：脈盛，皮熱，腹脹，前後不通，悶瞀，此謂五實。脈細，皮寒，氣少，泄利前後，飲食不入，此謂五虛。帝曰：其時有生者何也？岐伯曰：漿粥入胃，泄註止，則虛者活；身汗得後利，則實者活。此其候也。","sortOrder":35},
  {"id":"s_work_hdnk_20_1","chapterId":"ch_work_hdnk_20","text":"三部九候論篇第二十","sortOrder":1},
  {"id":"s_work_hdnk_20_2","chapterId":"ch_work_hdnk_20","text":"黃帝問曰：餘聞九針於夫子，眾多博大，不可勝數。餘願聞要道，以屬子孫，傳之後世，著之骨髓，藏之肝肺，歃血而受，不敢妄泄。令合天道，必有終始。上應天光星辰歷紀，下副四時五行，貴賤更互，冬陽夏陰，以人應之奈何，願聞其方？岐伯對曰：妙乎哉問也！此天地之至數。","sortOrder":2},
  {"id":"s_work_hdnk_20_3","chapterId":"ch_work_hdnk_20","text":"帝曰：願聞天地之至數，合於人形血氣，通決死生，為之奈何？岐伯曰：天地之至數始於一，終於九焉。","sortOrder":3},
  {"id":"s_work_hdnk_20_4","chapterId":"ch_work_hdnk_20","text":"一者天，二者地，三者人，因而三之，三三者九，以應九野。","sortOrder":4},
  {"id":"s_work_hdnk_20_5","chapterId":"ch_work_hdnk_20","text":"故人有三部，部有三候，以決死生，以處百病，以調虛實，而除邪疾。","sortOrder":5},
  {"id":"s_work_hdnk_20_6","chapterId":"ch_work_hdnk_20","text":"帝曰：何謂三部？岐伯曰：有下部、有中部、有上部，部各有三候。三候者，有天、有地、有人也。必指而導之，乃以為真。","sortOrder":6},
  {"id":"s_work_hdnk_20_7","chapterId":"ch_work_hdnk_20","text":"上部天，兩額之動脈；上部地，兩頰之動脈；上部人，耳前之動脈。","sortOrder":7},
  {"id":"s_work_hdnk_20_8","chapterId":"ch_work_hdnk_20","text":"中部天，手太陰也；中部地，手陽明也；中部人，手少陰也。","sortOrder":8},
  {"id":"s_work_hdnk_20_9","chapterId":"ch_work_hdnk_20","text":"下部天，足厥陰也；下部地，足少陰也；下部人，足太陰也。","sortOrder":9},
  {"id":"s_work_hdnk_20_10","chapterId":"ch_work_hdnk_20","text":"故下部之天以候肝，地以候腎，人以候脾胃之氣。","sortOrder":10},
  {"id":"s_work_hdnk_20_11","chapterId":"ch_work_hdnk_20","text":"帝曰：中部之候奈何？岐伯曰：亦有天，亦有地，亦有人，天以候肺，地以候胸中之氣，人以候心。","sortOrder":11},
  {"id":"s_work_hdnk_20_12","chapterId":"ch_work_hdnk_20","text":"帝曰：上部以何候之？岐伯曰：亦有天，亦有地，亦有人。天以候頭角之氣，地以候口齒之氣，人以候耳目之氣。","sortOrder":12},
  {"id":"s_work_hdnk_20_13","chapterId":"ch_work_hdnk_20","text":"三部者，各有天，各有地，各有人。三而成天，三而成地，三而成人。三而三之，合則為九，九分為九野，九野為九臟。故神臟五，形臟四，合為九臟。五臟已敗，其色必夭，夭必死矣。","sortOrder":13},
  {"id":"s_work_hdnk_20_14","chapterId":"ch_work_hdnk_20","text":"帝曰：以候奈何？岐伯曰：必先度其形之肥瘦，以調其氣之虛實，實則瀉之，虛則補之。必先去其血脈而後調之，無問其病，以平為期。","sortOrder":14},
  {"id":"s_work_hdnk_20_15","chapterId":"ch_work_hdnk_20","text":"帝曰：決死生奈何？岐伯曰：形盛脈細，少氣不足以息者危。形瘦脈大，胸中多氣者死。形氣相得者生。參伍不調者病。三部九候皆相失者死。上下左右之脈相應如參舂者病甚，上下左右相失不可數者死。中部之候雖獨調，與眾臟相失者死。中部之候相減者死，目內陷者死。","sortOrder":15},
  {"id":"s_work_hdnk_20_16","chapterId":"ch_work_hdnk_20","text":"帝曰：何以知病之所在？岐伯曰：察九候獨小者病，獨大者病，獨疾者病，獨遲者病，獨熱者病，獨寒者病，獨陷下者病。","sortOrder":16},
  {"id":"s_work_hdnk_20_17","chapterId":"ch_work_hdnk_20","text":"以左手足上，上去踝五寸按之，庶右手足當踝而彈之，其應過五寸以上蠕蠕然者不病，其應疾中手渾渾然者病，中手徐徐然者病。其應上不能至五寸，彈之不應者死。","sortOrder":17},
  {"id":"s_work_hdnk_20_18","chapterId":"ch_work_hdnk_20","text":"是以脫肉身不去者死。中部乍疏乍數者死。其脈代而鉤者，病在絡脈。","sortOrder":18},
  {"id":"s_work_hdnk_20_19","chapterId":"ch_work_hdnk_20","text":"九候之相應也，上下若一，不得相失。一候後則病，二候後則病甚，三候後則病危。所謂後者，應不俱也。察其腑臟，以知死生之期，必先知經脈，然後知病脈。真藏脈見者勝死。足太陽氣絕者，其足不可屈伸，死必戴眼。","sortOrder":19},
  {"id":"s_work_hdnk_20_20","chapterId":"ch_work_hdnk_20","text":"帝曰：冬陰夏陽奈何？岐伯曰：九候之脈皆沈細旋絕者為陰，主冬，故以夜半死。盛躁喘數者為陽，主夏，故以日中死。","sortOrder":20},
  {"id":"s_work_hdnk_20_21","chapterId":"ch_work_hdnk_20","text":"是故寒熱病者以平旦死。熱中及熱病者以日中死。病風者以日夕死。病水者以夜半死。其脈乍疏乍數，乍遲乍疾者，日乘四季死。","sortOrder":21},
  {"id":"s_work_hdnk_20_22","chapterId":"ch_work_hdnk_20","text":"形肉已脫，九候雖調猶死。七診雖見，九候皆從者不死。所言不死者，風氣之病，及經月之病，似七診之病而非也，故言不死。若有七診之病，其脈候亦敗者死矣。必發噦噫。","sortOrder":22},
  {"id":"s_work_hdnk_20_23","chapterId":"ch_work_hdnk_20","text":"必審問其所始病，與今之所方病，而後各切循其脈，視其經絡浮沈，以上下逆從循之。其脈疾者不病，其脈遲者病；脈不往來者死，皮膚著者死。","sortOrder":23},
  {"id":"s_work_hdnk_20_24","chapterId":"ch_work_hdnk_20","text":"帝曰：其可治奈何？岐伯曰：經病者治其經，孫絡病者治其孫絡血。血病身有痛者治其經絡。其病者在奇邪，奇邪之脈則繆刺之，留瘦不移節而刺之。上實下虛切而從之，索其結絡脈，刺出其血以見通之。瞳子高者太陽不足，戴眼者太陽已絕，此決死生之要，不可不察也。手指及手外踝上，五指留針。","sortOrder":24},
  {"id":"s_work_hdnk_21_1","chapterId":"ch_work_hdnk_21","text":"經脈別論篇第二十一","sortOrder":1},
  {"id":"s_work_hdnk_21_2","chapterId":"ch_work_hdnk_21","text":"黃帝問曰：人之居處動靜勇怯，脈亦為之變乎？岐伯對曰：凡人之驚恐恚勞動靜，皆為變也。","sortOrder":2},
  {"id":"s_work_hdnk_21_3","chapterId":"ch_work_hdnk_21","text":"是以夜行則喘出於腎，淫氣病肺。","sortOrder":3},
  {"id":"s_work_hdnk_21_4","chapterId":"ch_work_hdnk_21","text":"有所墮恐，喘出於肝，淫氣害脾。","sortOrder":4},
  {"id":"s_work_hdnk_21_5","chapterId":"ch_work_hdnk_21","text":"有所驚恐，喘出於肺，淫氣傷心。","sortOrder":5},
  {"id":"s_work_hdnk_21_6","chapterId":"ch_work_hdnk_21","text":"渡水跌仆，喘出於腎與骨。","sortOrder":6},
  {"id":"s_work_hdnk_21_7","chapterId":"ch_work_hdnk_21","text":"當是之時，勇者氣行則已，怯者則著而為病也。","sortOrder":7},
  {"id":"s_work_hdnk_21_8","chapterId":"ch_work_hdnk_21","text":"故曰：診病之道，觀人勇怯，骨肉皮膚，能知其情，以為診法也。","sortOrder":8},
  {"id":"s_work_hdnk_21_9","chapterId":"ch_work_hdnk_21","text":"故飲食飽甚，汗出於胃。驚而奪精，汗出於心。持重遠行，汗出於腎。疾走恐懼，汗出於肝。搖體勞苦，汗出於脾。","sortOrder":9},
  {"id":"s_work_hdnk_21_10","chapterId":"ch_work_hdnk_21","text":"故春秋冬夏，四時陰陽，生病起於過用，此為常也。","sortOrder":10},
  {"id":"s_work_hdnk_21_11","chapterId":"ch_work_hdnk_21","text":"食氣入胃，散精於肝，淫氣於筋。","sortOrder":11},
  {"id":"s_work_hdnk_21_12","chapterId":"ch_work_hdnk_21","text":"食氣入胃，濁氣歸心，淫精於脈。","sortOrder":12},
  {"id":"s_work_hdnk_21_13","chapterId":"ch_work_hdnk_21","text":"脈氣流經，經氣歸於肺，肺朝百脈，輸精於皮毛。","sortOrder":13},
  {"id":"s_work_hdnk_21_14","chapterId":"ch_work_hdnk_21","text":"毛脈合精，行氣於腑，腑精神明，留於四藏。","sortOrder":14},
  {"id":"s_work_hdnk_21_15","chapterId":"ch_work_hdnk_21","text":"氣歸於權衡，權衡以平，氣口成寸，以決死生。","sortOrder":15},
  {"id":"s_work_hdnk_21_16","chapterId":"ch_work_hdnk_21","text":"飲入於胃，遊溢精氣上輸於脾，脾氣散精，上歸於肺，通調水道，下輸膀胱，水精四佈，五經併行。合於四時，五臟陰陽，揆度以為常也。","sortOrder":16},
  {"id":"s_work_hdnk_21_17","chapterId":"ch_work_hdnk_21","text":"太陽臟獨至，厥喘虛氣逆，是陰不足陽有餘也。表裏當俱瀉，取之下俞。","sortOrder":17},
  {"id":"s_work_hdnk_21_18","chapterId":"ch_work_hdnk_21","text":"陽明臟獨至，是陽氣重併也。當瀉陽補陰，取之下俞。","sortOrder":18},
  {"id":"s_work_hdnk_21_19","chapterId":"ch_work_hdnk_21","text":"少陽臟獨至，是厥氣也。蹻前卒大，取之下俞。","sortOrder":19},
  {"id":"s_work_hdnk_21_20","chapterId":"ch_work_hdnk_21","text":"少陽獨至者，一陽之過也。","sortOrder":20},
  {"id":"s_work_hdnk_21_21","chapterId":"ch_work_hdnk_21","text":"太陰臟搏者，用心省真，五脈氣少，胃氣不平，三陰也。宜治其下俞，補陽瀉陰。","sortOrder":21},
  {"id":"s_work_hdnk_21_22","chapterId":"ch_work_hdnk_21","text":"一陽獨嘯，少陽厥也。陽併於上，四脈爭張，氣歸於腎。宜治其經絡；瀉陽補陰。","sortOrder":22},
  {"id":"s_work_hdnk_21_23","chapterId":"ch_work_hdnk_21","text":"一陰至，厥陰之治也。真虛〈疒肙〉心，厥氣留薄，發為白汗，調食和藥，治在下俞。","sortOrder":23},
  {"id":"s_work_hdnk_21_24","chapterId":"ch_work_hdnk_21","text":"帝曰：太陽臟何象？岐伯曰：象三陽而浮也。帝曰：少陽臟何象？岐伯曰：象一陽也，一陽臟者，滑而不實也。帝曰：陽明臟何象？岐伯曰：象大浮也。太陰臟搏，言伏鼓也。二陰搏至，腎沈不浮也。","sortOrder":24},
  {"id":"s_work_hdnk_22_1","chapterId":"ch_work_hdnk_22","text":"藏氣法時論篇第二十二","sortOrder":1},
  {"id":"s_work_hdnk_22_2","chapterId":"ch_work_hdnk_22","text":"黃帝問曰：合人形以法四時五行而治，何如而從，何如而逆？得失之意，願聞其事。","sortOrder":2},
  {"id":"s_work_hdnk_22_3","chapterId":"ch_work_hdnk_22","text":"岐伯對曰：五行者，金木水火土也。更貴更賤，以知死生，以決成敗，而定五臟之氣，間甚之時，死生之期也。","sortOrder":3},
  {"id":"s_work_hdnk_22_4","chapterId":"ch_work_hdnk_22","text":"帝曰：願卒聞之。岐伯曰：肝主春，足厥陰少陽主治。其日甲乙。肝苦急，急食甘以緩之。","sortOrder":4},
  {"id":"s_work_hdnk_22_5","chapterId":"ch_work_hdnk_22","text":"心主夏，手少陰太陽主治。其日丙丁。心苦緩，急食酸以收之。","sortOrder":5},
  {"id":"s_work_hdnk_22_6","chapterId":"ch_work_hdnk_22","text":"脾主長夏，足太陰陽明主治。其日戊己。脾苦濕，急食苦以燥之。","sortOrder":6},
  {"id":"s_work_hdnk_22_7","chapterId":"ch_work_hdnk_22","text":"肺主秋，手太陰陽明主治。其日庚辛。肺苦氣上逆，急食苦以泄之。","sortOrder":7},
  {"id":"s_work_hdnk_22_8","chapterId":"ch_work_hdnk_22","text":"腎主冬，足少陰太陽主治。其日壬癸。腎苦燥，急食辛以潤之，開腠理，致津液通氣也。","sortOrder":8},
  {"id":"s_work_hdnk_22_9","chapterId":"ch_work_hdnk_22","text":"病在肝，愈於夏，夏不愈，甚於秋，秋不死，持於冬，起於春。禁當風。","sortOrder":9},
  {"id":"s_work_hdnk_22_10","chapterId":"ch_work_hdnk_22","text":"肝病者，愈在丙丁，丙丁不愈，加於庚辛，庚辛不死，持於壬癸，起於甲乙。","sortOrder":10},
  {"id":"s_work_hdnk_22_11","chapterId":"ch_work_hdnk_22","text":"肝病者，平旦慧，下晡甚，夜半靜。","sortOrder":11},
  {"id":"s_work_hdnk_22_12","chapterId":"ch_work_hdnk_22","text":"肝欲散，急食辛以散之，用辛補之，酸瀉之。","sortOrder":12},
  {"id":"s_work_hdnk_22_13","chapterId":"ch_work_hdnk_22","text":"病在心，愈在長夏，長夏不愈，甚於冬，冬不死，持於春，起於夏。禁溫食熱衣。","sortOrder":13},
  {"id":"s_work_hdnk_22_14","chapterId":"ch_work_hdnk_22","text":"心病者，愈在戊己，戊己不愈，加於壬癸，壬癸不死，持於甲乙，起於丙丁。","sortOrder":14},
  {"id":"s_work_hdnk_22_15","chapterId":"ch_work_hdnk_22","text":"心病者，日中慧，夜半甚，平旦靜。","sortOrder":15},
  {"id":"s_work_hdnk_22_16","chapterId":"ch_work_hdnk_22","text":"心欲軟，急食鹹以軟之；用鹹補之，甘瀉之。","sortOrder":16},
  {"id":"s_work_hdnk_22_17","chapterId":"ch_work_hdnk_22","text":"病在脾，愈在秋，秋不愈；甚於春，春不死，持於夏，起於長夏。禁溫食飽食，濕地濡衣。","sortOrder":17},
  {"id":"s_work_hdnk_22_18","chapterId":"ch_work_hdnk_22","text":"脾病者癒在庚辛，庚辛不愈，加於甲乙，甲乙不死，持於丙丁，起於戊己。","sortOrder":18},
  {"id":"s_work_hdnk_22_19","chapterId":"ch_work_hdnk_22","text":"脾病者，日昳慧，日出甚，下晡靜。","sortOrder":19},
  {"id":"s_work_hdnk_22_20","chapterId":"ch_work_hdnk_22","text":"脾欲緩，急食甘以緩之，用苦瀉之，甘補之。","sortOrder":20},
  {"id":"s_work_hdnk_22_21","chapterId":"ch_work_hdnk_22","text":"病在肺，愈於冬。冬不愈，甚於夏，夏不死，持於長夏，起於秋。禁寒飲食，寒衣。","sortOrder":21},
  {"id":"s_work_hdnk_22_22","chapterId":"ch_work_hdnk_22","text":"肺病者，愈在壬癸，壬癸不愈，加於丙丁，丙丁不死，持於戊己，起於庚辛。","sortOrder":22},
  {"id":"s_work_hdnk_22_23","chapterId":"ch_work_hdnk_22","text":"肺病者，下晡慧，日中甚，夜半靜。","sortOrder":23},
  {"id":"s_work_hdnk_22_24","chapterId":"ch_work_hdnk_22","text":"肺欲收，急食酸以收之，用酸補之，辛瀉之。","sortOrder":24},
  {"id":"s_work_hdnk_22_25","chapterId":"ch_work_hdnk_22","text":"病在腎，愈在春，春不愈，甚於長夏，長夏不死，持於秋，起於冬，禁犯焠〈火矣〉熱食，溫炙衣。","sortOrder":25},
  {"id":"s_work_hdnk_22_26","chapterId":"ch_work_hdnk_22","text":"腎病者，愈在甲乙，甲乙不愈，甚於戊己，戊己不死，持於庚辛，起於壬癸。","sortOrder":26},
  {"id":"s_work_hdnk_22_27","chapterId":"ch_work_hdnk_22","text":"腎病者，夜半慧，四季甚，下晡靜。","sortOrder":27},
  {"id":"s_work_hdnk_22_28","chapterId":"ch_work_hdnk_22","text":"腎欲堅，急食苦以堅之，用苦補之，鹹瀉之。","sortOrder":28},
  {"id":"s_work_hdnk_22_29","chapterId":"ch_work_hdnk_22","text":"夫邪氣之客於身也。以勝相加，至其所生而愈，至其所不勝而甚，至於所生而持，自得其位而起；必先定五臟之脈，乃可言間甚之時，死生之期也。","sortOrder":29},
  {"id":"s_work_hdnk_22_30","chapterId":"ch_work_hdnk_22","text":"肝病者，兩脅下痛引少腹，令人善怒。虛則目〈流，氵改目〉〈流，氵改目〉無所見，耳無所聞，善恐，如人將補之。","sortOrder":30},
  {"id":"s_work_hdnk_22_31","chapterId":"ch_work_hdnk_22","text":"取其經厥陰與少陽，氣逆則頭痛。耳聾不聰、頰腫、取血者。","sortOrder":31},
  {"id":"s_work_hdnk_22_32","chapterId":"ch_work_hdnk_22","text":"心病者，胸中痛，脅支滿，脅下痛，膺背肩胛間痛，兩臂內痛。虛則胸腹大，脅下與腰相引而痛。","sortOrder":32},
  {"id":"s_work_hdnk_22_33","chapterId":"ch_work_hdnk_22","text":"取其經，少陰太陽舌下血者，其變病刺郗中血者。","sortOrder":33},
  {"id":"s_work_hdnk_22_34","chapterId":"ch_work_hdnk_22","text":"脾病者，身重，善飢肉痿，足不收行，善瘈，腳下痛。虛則腹滿，腸鳴飧泄，食不化。","sortOrder":34},
  {"id":"s_work_hdnk_22_35","chapterId":"ch_work_hdnk_22","text":"取其經太陰、陽明、少陰血者。","sortOrder":35},
  {"id":"s_work_hdnk_22_36","chapterId":"ch_work_hdnk_22","text":"肺病者，喘咳逆氣，肩背痛，汗出，尻陰股膝髀腨胻足皆痛。虛則少氣，不能報息，耳聾嗌乾。","sortOrder":36},
  {"id":"s_work_hdnk_22_37","chapterId":"ch_work_hdnk_22","text":"取其經，太陰足太陽之外，厥陰內血者。","sortOrder":37},
  {"id":"s_work_hdnk_22_38","chapterId":"ch_work_hdnk_22","text":"腎病者，腹大、脛腫、喘咳身重，寢汗出、憎風。虛則胸中痛，大腹、小腹痛，清厥意不樂。","sortOrder":38},
  {"id":"s_work_hdnk_22_39","chapterId":"ch_work_hdnk_22","text":"取其經少陰太陽血者。","sortOrder":39},
  {"id":"s_work_hdnk_22_40","chapterId":"ch_work_hdnk_22","text":"肝色青，宜食甘。粳米、牛肉、棗、葵皆甘。","sortOrder":40},
  {"id":"s_work_hdnk_22_41","chapterId":"ch_work_hdnk_22","text":"心色赤，宜食酸。小豆、犬肉、李、韭皆酸。","sortOrder":41},
  {"id":"s_work_hdnk_22_42","chapterId":"ch_work_hdnk_22","text":"肺色白，宜食苦。麥、羊肉、杏、薤皆苦。","sortOrder":42},
  {"id":"s_work_hdnk_22_43","chapterId":"ch_work_hdnk_22","text":"脾色黃，宜食鹹。大豆、豬肉、栗、藿皆鹹。","sortOrder":43},
  {"id":"s_work_hdnk_22_44","chapterId":"ch_work_hdnk_22","text":"腎色黑，宜食辛。黃黍、雞肉、桃、蔥皆辛。","sortOrder":44},
  {"id":"s_work_hdnk_22_45","chapterId":"ch_work_hdnk_22","text":"辛散、酸收、甘緩、苦堅、鹹軟。毒藥攻邪。","sortOrder":45},
  {"id":"s_work_hdnk_22_46","chapterId":"ch_work_hdnk_22","text":"五穀為食。五果為助。五畜為益。五菜為充。","sortOrder":46},
  {"id":"s_work_hdnk_22_47","chapterId":"ch_work_hdnk_22","text":"氣味合而服之，以補精益氣。","sortOrder":47},
  {"id":"s_work_hdnk_22_48","chapterId":"ch_work_hdnk_22","text":"此五者，有辛、酸、甘、苦、鹹，各有所利，或散，或收、或緩、或急、或堅、或軟。四時五臟，病隨五味所宜也。","sortOrder":48},
  {"id":"s_work_hdnk_23_1","chapterId":"ch_work_hdnk_23","text":"宣明五氣篇第二十三","sortOrder":1},
  {"id":"s_work_hdnk_23_2","chapterId":"ch_work_hdnk_23","text":"五味所入：酸入肝、辛入肺、苦入心、鹹入腎、甘入脾，是為五入。","sortOrder":2},
  {"id":"s_work_hdnk_23_3","chapterId":"ch_work_hdnk_23","text":"五氣所病：心為噫、肺為咳、肝為語、脾為吞、腎為欠，為嚏，胃為氣逆為噦，為恐，大腸小腸為泄，下焦溢為水，膀胱不利為癃，不約為遺弱，膽為怒，是為五病。","sortOrder":3},
  {"id":"s_work_hdnk_23_4","chapterId":"ch_work_hdnk_23","text":"五精所並：精氣並於心則善，並於肺則悲，並於肝則憂，並於脾則畏，並於腎則恐，是謂五並，虛而相並者也。","sortOrder":4},
  {"id":"s_work_hdnk_23_5","chapterId":"ch_work_hdnk_23","text":"五臟所惡：心惡熱、肺惡寒、肝惡風、脾惡濕、腎惡燥。是謂五惡。","sortOrder":5},
  {"id":"s_work_hdnk_23_6","chapterId":"ch_work_hdnk_23","text":"五臟化液：心為汗、肺為涕、肝為淚、脾為涎、腎為唾。是為五液。","sortOrder":6},
  {"id":"s_work_hdnk_23_7","chapterId":"ch_work_hdnk_23","text":"五味所禁：辛走氣、氣病無多食辛；鹹走血，血病無多食鹹；苦走骨，骨病無多食苦，甘走肉，肉病無多食甘；酸走筋，筋病無多食酸。是謂五禁，無令多食。","sortOrder":7},
  {"id":"s_work_hdnk_23_8","chapterId":"ch_work_hdnk_23","text":"五病所發：陰病發於骨，陽病發於血，陰病發於肉，陽病發於冬；陰病發於夏。是謂五發。","sortOrder":8},
  {"id":"s_work_hdnk_23_9","chapterId":"ch_work_hdnk_23","text":"五邪所亂：邪入於陽則狂，邪入於陰則痺；搏陽則為巔疾，搏陰則為瘖；陽入之陰則靜，陰出之陽則怒。是為五亂。","sortOrder":9},
  {"id":"s_work_hdnk_23_10","chapterId":"ch_work_hdnk_23","text":"五邪所見：春得秋脈，夏得冬脈，長夏得春脈，秋得夏脈，冬得長夏脈，名曰陰出之陽，病善怒不治。是謂五邪，皆同命死不治。","sortOrder":10},
  {"id":"s_work_hdnk_23_11","chapterId":"ch_work_hdnk_23","text":"五臟所藏：心藏神、肺藏魄、肝藏魂、脾藏意、腎藏志。是謂五臟所藏。","sortOrder":11},
  {"id":"s_work_hdnk_23_12","chapterId":"ch_work_hdnk_23","text":"五臟所主：心主脈、肺主皮、肝主筋、脾主肉、腎主骨。是為五臟所主。","sortOrder":12},
  {"id":"s_work_hdnk_23_13","chapterId":"ch_work_hdnk_23","text":"五勞所傷：久視傷血、久臥傷氣、久坐傷肉、久立傷骨、久行傷筋。是謂五勞所傷。","sortOrder":13},
  {"id":"s_work_hdnk_23_14","chapterId":"ch_work_hdnk_23","text":"五脈應象：肝脈絃、心脈鉤、脾脈代、肺脈毛、腎脈石。是謂五臟之脈。","sortOrder":14},
  {"id":"s_work_hdnk_24_1","chapterId":"ch_work_hdnk_24","text":"血氣形志篇第二十四","sortOrder":1},
  {"id":"s_work_hdnk_24_2","chapterId":"ch_work_hdnk_24","text":"夫人之常數，太陽常多血少氣，少陽常少血多氣，陽明常多氣多血，少陰常少血多氣，厥陰常多血少氣，太陰常多氣少血。此天之常數。","sortOrder":2},
  {"id":"s_work_hdnk_24_3","chapterId":"ch_work_hdnk_24","text":"足太陽與少陰為表裏，少陽與厥陰為表裏，陽明與太陰為表裏，是為足陰陽也。手太陽與少陰為表裏，少陽與心主為表裏，陽明與太陰為表裏，是為手之陰陽也。","sortOrder":3},
  {"id":"s_work_hdnk_24_4","chapterId":"ch_work_hdnk_24","text":"今知手足陰陽所苦，凡治病必先去其血，乃去其所苦，伺之所欲，然後瀉有餘，補不足。","sortOrder":4},
  {"id":"s_work_hdnk_24_5","chapterId":"ch_work_hdnk_24","text":"欲知背俞，先度其兩乳間，中折之，更以他草度去半已，即以兩隅相拄也，乃舉以度其背，令其一隅居上，齊脊大柱，兩隅在下，當其下隅者，肺之俞也。","sortOrder":5},
  {"id":"s_work_hdnk_24_6","chapterId":"ch_work_hdnk_24","text":"復下一度，心之俞也。復下一度，左角肝之俞也。右角脾之俞也，復下一度，腎之俞也，是為五臟之俞，灸刺之度也。","sortOrder":6},
  {"id":"s_work_hdnk_24_7","chapterId":"ch_work_hdnk_24","text":"形樂志苦，病生於脈，治之以灸刺。","sortOrder":7},
  {"id":"s_work_hdnk_24_8","chapterId":"ch_work_hdnk_24","text":"形樂志樂，病生於肉，治之以針石。","sortOrder":8},
  {"id":"s_work_hdnk_24_9","chapterId":"ch_work_hdnk_24","text":"形苦志樂，病生於筋，治之以熨引。","sortOrder":9},
  {"id":"s_work_hdnk_24_10","chapterId":"ch_work_hdnk_24","text":"形苦志苦，病生於咽嗌，治之以百藥。","sortOrder":10},
  {"id":"s_work_hdnk_24_11","chapterId":"ch_work_hdnk_24","text":"形數驚恐，經絡不通，病生於不仁，治之以按摩醪藥。","sortOrder":11},
  {"id":"s_work_hdnk_24_12","chapterId":"ch_work_hdnk_24","text":"是謂五形志也。","sortOrder":12},
  {"id":"s_work_hdnk_24_13","chapterId":"ch_work_hdnk_24","text":"刺陽明出血氣，刺太陽出血惡氣，刺少陽出氣惡血，刺太陰出氣惡血，刺少陰出氣惡血，刺厥陰出血惡氣也。","sortOrder":13},
  {"id":"s_work_hdnk_25_1","chapterId":"ch_work_hdnk_25","text":"寶命全形論篇第二十五","sortOrder":1},
  {"id":"s_work_hdnk_25_2","chapterId":"ch_work_hdnk_25","text":"黃帝問曰：天復地載，萬物悉備，莫貴於人。人以天地之氣生，四時之法成。君王眾庶，盡欲全形。形之疾病，莫知其情，留淫日深，著於骨髓，心私慮之。餘欲針除其疾病，為之奈何？","sortOrder":2},
  {"id":"s_work_hdnk_25_3","chapterId":"ch_work_hdnk_25","text":"岐伯對曰：夫鹽之味鹹者，其氣令器津泄；絃絕者，其音嘶敗；木敷者，其葉發，病深者，其聲噦。人有此三者，是謂壞府，毒藥無治，短針無取，此皆絕皮傷內，血氣爭黑。","sortOrder":3},
  {"id":"s_work_hdnk_25_4","chapterId":"ch_work_hdnk_25","text":"帝曰：餘念其痛，心為之亂惑反甚。其病不可更代，百姓聞之，以為殘賊，為之奈何。","sortOrder":4},
  {"id":"s_work_hdnk_25_5","chapterId":"ch_work_hdnk_25","text":"岐伯曰：夫人生於地，懸命於天；天地合氣，命之曰人。人能應四時者，天地為之父母；知萬物者，謂之天子。天有陰陽，人有十二節。天有寒暑，人有虛實。能經天地陰陽之化者，不失四時。知十二節之理者，聖智不能欺也，能存八動之變，五勝更立，能達虛實之數者獨出獨入，呿吟至微，秋毫在目。","sortOrder":5},
  {"id":"s_work_hdnk_25_6","chapterId":"ch_work_hdnk_25","text":"帝曰：人生有形，不離陰陽。天地合氣，別為九野，分為四時，月有大小，日有短長。萬物並至，不可勝量。虛實呿吟，敢問其方？","sortOrder":6},
  {"id":"s_work_hdnk_25_7","chapterId":"ch_work_hdnk_25","text":"岐伯曰：木得金而伐，火得水而滅，土得木而達，金得火而缺，水得土而絕，萬物盡然，不可勝竭。故針有懸布天下者五：黔首共餘食，莫知之也。一曰治神，二曰知養身，三曰知毒藥為真，四曰製砭石大小，五曰知腑臟血氣之診。五法俱立，各有所先。今末世之刺也，虛者實之，滿者泄之，此皆眾工所共知也。若夫法天則地，隨應而動，和之者若響，隨之者若影，道無鬼神，獨來獨往。","sortOrder":7},
  {"id":"s_work_hdnk_25_8","chapterId":"ch_work_hdnk_25","text":"帝曰：願聞其道。岐伯曰：凡刺之真，必先治神，五臟已定，九候已備，後乃存針，眾脈不見，眾凶弗聞，外內相得，無以形先，可玩往來，乃施於人。人有虛實，五虛勿近，五實勿遠，至其當發，間不容瞚。手動若務，針耀而勻。靜意視義，觀適之變，是謂冥冥，莫知其形。見其烏烏，見其稷稷，從見其飛，不知其誰。伏如橫弩，起如發機。","sortOrder":8},
  {"id":"s_work_hdnk_25_9","chapterId":"ch_work_hdnk_25","text":"帝曰：何如而虛？何如而實？岐伯曰：刺虛者須其實，刺實者須其虛。經氣已至，慎守勿失，深淺在志，遠近若一，如臨深淵，手如握虎，神無營於眾物。","sortOrder":9},
  {"id":"s_work_hdnk_26_1","chapterId":"ch_work_hdnk_26","text":"八正神明論篇第二十六","sortOrder":1},
  {"id":"s_work_hdnk_26_2","chapterId":"ch_work_hdnk_26","text":"黃帝問曰：用針之服，必有法則焉，今何法何則？岐伯對曰：法天則地，合以天光。","sortOrder":2},
  {"id":"s_work_hdnk_26_3","chapterId":"ch_work_hdnk_26","text":"帝曰：願卒聞之。岐伯曰：凡刺之法，必候日月星辰，四時八正之氣，氣定乃刺之。","sortOrder":3},
  {"id":"s_work_hdnk_26_4","chapterId":"ch_work_hdnk_26","text":"是故天溫日月，則人血淖液而衛氣浮，故血易瀉，氣易行；天寒日陰，則人血凝泣而衛氣沉。月始生則血氣始精，衛氣始行；月郭滿則血氣實，肌肉堅，月郭空，則肌肉減，經絡虛，衛氣去，形獨居，是以因天時而調血氣也。","sortOrder":4},
  {"id":"s_work_hdnk_26_5","chapterId":"ch_work_hdnk_26","text":"是以天寒無刺，天溫無疑；月生無瀉，月滿無補；月郭空無治。是謂得時而調之。因天之序，盛虛之時，移光定位，正立而待之。","sortOrder":5},
  {"id":"s_work_hdnk_26_6","chapterId":"ch_work_hdnk_26","text":"故日月生而瀉，是謂臟虛；月滿而補，血氣揚溢；絡有留血，命曰重實；月郭空而治，是謂亂經。陰陽相錯，真邪不別，沈以留止，外虛內亂，淫邪乃起。","sortOrder":6},
  {"id":"s_work_hdnk_26_7","chapterId":"ch_work_hdnk_26","text":"帝曰：星辰八正何候？岐伯曰：星辰者，所以製日月之行也。八正者，所以八風之虛邪以時至者也。四時者所以春秋冬夏之氣所在，以時調之也。八正之虛邪而避之勿犯也。以身之虛而逢天之虛，兩虛相感，其氣至骨，入則傷五臟，工候救之，弗能傷也。故曰：天忌不可不知也。","sortOrder":7},
  {"id":"s_work_hdnk_26_8","chapterId":"ch_work_hdnk_26","text":"帝曰：善。其法星辰者，餘聞之矣，願聞法往古者。岐伯曰：法往古者，先知針經也，驗於來今者，先知日之寒溫，月之虛盛，以候氣之浮沈，而調之於身，觀其立有驗也。","sortOrder":8},
  {"id":"s_work_hdnk_26_9","chapterId":"ch_work_hdnk_26","text":"觀其冥冥者，言形氣榮衛之不形於外，而工獨知之。以日之寒溫，月之虛盛，四時氣之浮沈，參伍相合而調之，工常先見之。然而不形於外，故曰觀於冥冥焉！通於無窮者，可以傳於後世也。是故工之所以異也。然而不形見於外，故俱不能見也。視之無形，嘗之無味，故謂冥冥，若神髣彿。","sortOrder":9},
  {"id":"s_work_hdnk_26_10","chapterId":"ch_work_hdnk_26","text":"虛邪者，八正之虛邪氣也；正邪者，身形若用力汗出，腠理開，逢虛風，其中人也微。故莫知其情，莫見其形。","sortOrder":10},
  {"id":"s_work_hdnk_26_11","chapterId":"ch_work_hdnk_26","text":"上工救其萌牙，必先見三部九候之氣，盡調不敗而救之，故曰上工。下工救其已成，救其已敗，救其已成者，言不知三部九候之相失，因病而敗之也，知其所在者，知診三部九候之病脈處而治之，故曰守其門戶焉。莫知其情，而見邪形也。","sortOrder":11},
  {"id":"s_work_hdnk_26_12","chapterId":"ch_work_hdnk_26","text":"帝曰：餘聞補瀉，未得其意。岐伯曰：瀉必用方，方者以氣方盛也。以月方滿也，以日方溫也，以身方定也，以息方吸而內針，乃復候其方吸而轉針，乃復候其方呼而徐引針，故曰瀉必用方，其氣而行焉。","sortOrder":12},
  {"id":"s_work_hdnk_26_13","chapterId":"ch_work_hdnk_26","text":"補必用員，員者行也。行者，移也。刺必中其榮，復以吸排針也。故員與方，非針也。","sortOrder":13},
  {"id":"s_work_hdnk_26_14","chapterId":"ch_work_hdnk_26","text":"故養神者，必知形之肥瘦，榮衛血氣之盛衰。血氣者，人之神，不可不謹養。","sortOrder":14},
  {"id":"s_work_hdnk_26_15","chapterId":"ch_work_hdnk_26","text":"帝曰：妙乎哉論也，合人形於陰陽四時，虛實之應，冥冥之期，其非夫子孰能通之。然夫子數言形與神，何謂形？何謂神？願卒聞之。","sortOrder":15},
  {"id":"s_work_hdnk_26_16","chapterId":"ch_work_hdnk_26","text":"岐伯曰：請言形，形乎形，目冥冥，問其所病，索之於經，慧然在前，按之不得，不知其情，故曰形。","sortOrder":16},
  {"id":"s_work_hdnk_26_17","chapterId":"ch_work_hdnk_26","text":"帝曰：何謂神？岐伯曰：請言神，神乎神，耳不聞，目明，心開而志先，慧然獨悟，口弗能言，俱視獨見，適若昏，昭然獨明，若風吹雲，故曰神。三部九候為之原，九針之論，不必存也。","sortOrder":17},
  {"id":"s_work_hdnk_27_1","chapterId":"ch_work_hdnk_27","text":"離合真邪論篇第二十七","sortOrder":1},
  {"id":"s_work_hdnk_27_2","chapterId":"ch_work_hdnk_27","text":"黃帝問曰：餘聞九針九篇，夫子乃因而九之，九九八十一篇餘盡通其意矣。經言氣之盛衰，左右傾移。以上調下，以左調右。有餘不足，補瀉於榮輸，餘知之矣。此皆榮衛之傾移，虛實之所生，非邪氣從外入於經也。餘願聞邪氣之在經也，其病人何如？取之奈何？","sortOrder":2},
  {"id":"s_work_hdnk_27_3","chapterId":"ch_work_hdnk_27","text":"岐伯對曰：夫聖人之起度數，必應於天地；故天有宿度，地有經水，人有經脈。","sortOrder":3},
  {"id":"s_work_hdnk_27_4","chapterId":"ch_work_hdnk_27","text":"天地溫和，則經水安靜；天寒地凍，則經水凝泣；天暑地熱，則經水沸溢，卒風暴起，則經水波涌而隴起。","sortOrder":4},
  {"id":"s_work_hdnk_27_5","chapterId":"ch_work_hdnk_27","text":"夫邪之入於脈也，寒則血凝泣，暑則氣淖澤，虛邪因而入客，亦如經水之得風也，經之動脈，其至也，亦時隴起，其行於脈中，循循然。","sortOrder":5},
  {"id":"s_work_hdnk_27_6","chapterId":"ch_work_hdnk_27","text":"其至寸口中手也，時大時小，大則邪至，小則平。其行無常處，在陰與陽，不可為度。從而察之，三部九候。卒然逢之，早遏其路。","sortOrder":6},
  {"id":"s_work_hdnk_27_7","chapterId":"ch_work_hdnk_27","text":"吸則內針，無令氣忤。靜以久留，無令邪布。吸則轉針，以得氣為故。候呼引針，呼盡乃去，大氣皆出，故命曰瀉。","sortOrder":7},
  {"id":"s_work_hdnk_27_8","chapterId":"ch_work_hdnk_27","text":"帝曰：不足者補之，奈何？岐伯曰：必先捫而循之，切而散之，推而按之，彈而怒之，抓而下之，通而取之，外引其門，以閉其神。呼盡內針，靜以久留，以氣至為故，如待所貴，不知日暮。其氣以至，適而自護，候吸引針，氣不得出，各在其處，推闔其門，令神氣存，大氣留止，故命曰補。","sortOrder":8},
  {"id":"s_work_hdnk_27_9","chapterId":"ch_work_hdnk_27","text":"帝曰：候氣奈何？岐伯曰：夫邪去絡，入於經也，舍於血脈之中，其寒溫未相得，如涌波之起也，時來時去，故不常在。","sortOrder":9},
  {"id":"s_work_hdnk_27_10","chapterId":"ch_work_hdnk_27","text":"故曰：方其來也，必按而止之，止而取之，無逢其沖而瀉之。","sortOrder":10},
  {"id":"s_work_hdnk_27_11","chapterId":"ch_work_hdnk_27","text":"真氣者，經氣也，經氣太虛，故曰其來不可逢，此之謂也。","sortOrder":11},
  {"id":"s_work_hdnk_27_12","chapterId":"ch_work_hdnk_27","text":"故曰：候邪不審，大氣已過，瀉之則真氣脫，脫則不復，邪氣復至，而病益蓄。故曰其往不可追，此之謂也。","sortOrder":12},
  {"id":"s_work_hdnk_27_13","chapterId":"ch_work_hdnk_27","text":"不可掛以髮者，待邪之至時而發針瀉矣。若先若後者，血氣已盡，其病不可下。故曰：知其可取如發機，不知其取如扣椎。故曰：知機道者不可掛以發，不知機者扣之不發，此之謂也。","sortOrder":13},
  {"id":"s_work_hdnk_27_14","chapterId":"ch_work_hdnk_27","text":"帝曰：補瀉奈何？岐伯曰：此攻邪也。疾出以去盛血，而復其真氣。","sortOrder":14},
  {"id":"s_work_hdnk_27_15","chapterId":"ch_work_hdnk_27","text":"此邪新客溶溶未有定處也。推之則前，引之則止，逆而刺之，溫血也。刺出其血，其病立已。","sortOrder":15},
  {"id":"s_work_hdnk_27_16","chapterId":"ch_work_hdnk_27","text":"帝曰：善。然真邪以合，波隴不起，候之奈何？岐伯曰：審捫循三部九候之盛虛而調之。察其左右，上下相失，及相減者，審其病臟以期之。","sortOrder":16},
  {"id":"s_work_hdnk_27_17","chapterId":"ch_work_hdnk_27","text":"不知三部者，陰陽不別，天地不分；地以候地，天以候天，人以候人。調之中府，以定三部，故曰刺不知三部九候病脈之處，雖有大過且至，工不能禁也。","sortOrder":17},
  {"id":"s_work_hdnk_27_18","chapterId":"ch_work_hdnk_27","text":"誅罰無過，命曰大惑，反亂大經，真不可復，用實為虛，以邪為真，用針無義，反為氣賊。奪人正氣，以從為為逆，榮衛散亂，真氣已失。邪獨內著，絕人長命，予人天殃，不知三部九候，故不能久長。","sortOrder":18},
  {"id":"s_work_hdnk_27_19","chapterId":"ch_work_hdnk_27","text":"因不知合之四時五行，因加相勝，釋邪攻正，絕人長命。","sortOrder":19},
  {"id":"s_work_hdnk_27_20","chapterId":"ch_work_hdnk_27","text":"邪之新客來也未有定處，推之則前，引之則止，逢而瀉之，其病立已。","sortOrder":20},
  {"id":"s_work_hdnk_28_1","chapterId":"ch_work_hdnk_28","text":"通評虛實論篇第二十八","sortOrder":1},
  {"id":"s_work_hdnk_28_2","chapterId":"ch_work_hdnk_28","text":"黃帝問曰：何謂虛實？岐伯對曰：邪氣盛則實，精氣奪則虛。","sortOrder":2},
  {"id":"s_work_hdnk_28_3","chapterId":"ch_work_hdnk_28","text":"帝曰：虛實何如？岐伯曰：氣虛者，肺虛也。氣逆者，足寒也。非其時則生，當其時則死。餘臟皆如此。","sortOrder":3},
  {"id":"s_work_hdnk_28_4","chapterId":"ch_work_hdnk_28","text":"帝曰：何謂重實？岐伯曰：所謂重實者，言大熱病，氣熱脈滿，是謂重實。","sortOrder":4},
  {"id":"s_work_hdnk_28_5","chapterId":"ch_work_hdnk_28","text":"帝曰：經絡俱實何如？何以治人？岐伯曰：經絡皆實，是寸脈急而尺緩也，皆當治之。故曰滑則從，澀則逆也。夫虛實者，皆從其物類始，故五臟骨肉滑利，可以長久也。","sortOrder":5},
  {"id":"s_work_hdnk_28_6","chapterId":"ch_work_hdnk_28","text":"帝曰：經氣不足，經氣有餘，如何？岐伯曰：絡氣不足，經氣有餘者，脈口熱而尺寒也。秋冬為逆，春夏為從，治主病者。","sortOrder":6},
  {"id":"s_work_hdnk_28_7","chapterId":"ch_work_hdnk_28","text":"帝曰：經虛絡滿何如？岐伯曰：經虛絡滿者，尺熱滿，脈口寒澀也。此春夏死，秋冬生也。帝曰：治此者奈何？岐伯曰：絡滿經虛，灸陰刺陽，經滿絡虛，刺陰灸陽。","sortOrder":7},
  {"id":"s_work_hdnk_28_8","chapterId":"ch_work_hdnk_28","text":"帝曰：何謂重虛？岐伯曰：脈氣上虛尺虛，是謂重虛。","sortOrder":8},
  {"id":"s_work_hdnk_28_9","chapterId":"ch_work_hdnk_28","text":"帝曰：何以治之？岐伯曰：所謂氣虛者，言無常也。尺虛者，行步恇然。脈虛者，不像陰也。如此者。滑則生，澀則死也。","sortOrder":9},
  {"id":"s_work_hdnk_28_10","chapterId":"ch_work_hdnk_28","text":"帝曰：寒氣暴上，脈滿而實何如？岐伯曰：實而滑則生，實而逆則死。","sortOrder":10},
  {"id":"s_work_hdnk_28_11","chapterId":"ch_work_hdnk_28","text":"帝曰：脈實滿，手足寒，頭熱，何如？岐伯曰：春秋則生，冬夏則死。脈浮而澀，澀而身有熱者死。","sortOrder":11},
  {"id":"s_work_hdnk_28_12","chapterId":"ch_work_hdnk_28","text":"帝曰：其形盡滿何如？岐伯曰：其形盡滿者，脈急大堅，尺澀而不應也。如是者，故從則生，逆則死。","sortOrder":12},
  {"id":"s_work_hdnk_28_13","chapterId":"ch_work_hdnk_28","text":"帝曰：何謂從則生，逆則死？岐伯曰：所謂從者，手足溫也。所謂逆者，手足寒也。","sortOrder":13},
  {"id":"s_work_hdnk_28_14","chapterId":"ch_work_hdnk_28","text":"帝曰：乳子而病熱，脈懸小者何如？岐伯曰：手足溫則生，寒則死。","sortOrder":14},
  {"id":"s_work_hdnk_28_15","chapterId":"ch_work_hdnk_28","text":"帝曰：乳子中風熱喘嗚肩息者，脈何如？岐伯曰：喘嗚肩息者，脈實大地。緩則生，急則死。","sortOrder":15},
  {"id":"s_work_hdnk_28_16","chapterId":"ch_work_hdnk_28","text":"帝曰：腸澼便血何如？岐伯曰：身熱則死，寒則生。","sortOrder":16},
  {"id":"s_work_hdnk_28_17","chapterId":"ch_work_hdnk_28","text":"帝曰：腸澼下白沫何如？岐伯曰：脈沈則生，脈浮則死。","sortOrder":17},
  {"id":"s_work_hdnk_28_18","chapterId":"ch_work_hdnk_28","text":"帝曰：腸澼下膿血何如？岐伯曰：脈懸絕則死，滑大則生。","sortOrder":18},
  {"id":"s_work_hdnk_28_19","chapterId":"ch_work_hdnk_28","text":"帝曰：腸澼之屬，身不熱，脈不懸絕何如？岐伯曰：滑大者曰生，懸澀者曰死，以臟期之。","sortOrder":19},
  {"id":"s_work_hdnk_28_20","chapterId":"ch_work_hdnk_28","text":"帝曰：癲疾何如？岐伯曰：脈搏大滑久自己，脈小堅急，死不治。","sortOrder":20},
  {"id":"s_work_hdnk_28_21","chapterId":"ch_work_hdnk_28","text":"帝曰：癲疾之脈，虛實何如？岐伯曰：虛則可治，實則死。","sortOrder":21},
  {"id":"s_work_hdnk_28_22","chapterId":"ch_work_hdnk_28","text":"帝曰：消癉虛實何如？岐伯曰：脈實大，病久可治，脈懸小堅，病久不可治。","sortOrder":22},
  {"id":"s_work_hdnk_28_23","chapterId":"ch_work_hdnk_28","text":"帝曰：形度、骨度、脈度、筋度、何以知其度也？","sortOrder":23},
  {"id":"s_work_hdnk_28_24","chapterId":"ch_work_hdnk_28","text":"帝曰：春極治經絡，夏極治經俞，秋極治六腑。冬則閉塞者，閉塞者，用藥而少針石也。所謂少針石者，非癰疽之謂也。癰疽不待頃時回。","sortOrder":24},
  {"id":"s_work_hdnk_28_25","chapterId":"ch_work_hdnk_28","text":"癰不知所，按之不應手，乍來乍己，刺手大陰傍三痏與纓脈各二。","sortOrder":25},
  {"id":"s_work_hdnk_28_26","chapterId":"ch_work_hdnk_28","text":"掖癰大熱，刺足少陽五。刺而熱不止，刺手心主三，刺手大陰經絡者，大骨之會各三。","sortOrder":26},
  {"id":"s_work_hdnk_28_27","chapterId":"ch_work_hdnk_28","text":"暴癰筋繻，隨分而痛，魄汗不盡，胞氣不足，治在經俞。","sortOrder":27},
  {"id":"s_work_hdnk_28_28","chapterId":"ch_work_hdnk_28","text":"腹暴滿，按之不下，取手太陽經絡者，胃也募也。少陰俞去脊椎三寸傍五，用圓利針。","sortOrder":28},
  {"id":"s_work_hdnk_28_29","chapterId":"ch_work_hdnk_28","text":"霍亂，刺俞傍五，足陽明及上傍三。","sortOrder":29},
  {"id":"s_work_hdnk_28_30","chapterId":"ch_work_hdnk_28","text":"刺癎驚脈五：針手太陰各五，刺經太陽五，刺手少陰經絡傍者一，足陽明一，上踝五寸刺三針。","sortOrder":30},
  {"id":"s_work_hdnk_28_31","chapterId":"ch_work_hdnk_28","text":"凡治消癉、仆擊、偏枯、痿厥、氣滿發逆，肥貴人，則高梁之疾也。隔塞閉絕，上下不通，則暴憂之病也。暴厥而聾偏塞閉不通，內氣暴薄也。不從內外中風之病，故瘦留著也。跖跛，寒風濕之病也。","sortOrder":31},
  {"id":"s_work_hdnk_28_32","chapterId":"ch_work_hdnk_28","text":"黃帝曰：黃疸、暴痛、癲狂、厥狂、久逆之所生也。五臟不平，六腑閉塞之所生也。頭痛耳嗚，九竅不利，腸胃之所生也。","sortOrder":32},
  {"id":"s_work_hdnk_29_1","chapterId":"ch_work_hdnk_29","text":"太陰陽明論篇第二十九","sortOrder":1},
  {"id":"s_work_hdnk_29_2","chapterId":"ch_work_hdnk_29","text":"黃帝問曰：太陰陽明為表裏，脾胃脈也。生病而異者何也？","sortOrder":2},
  {"id":"s_work_hdnk_29_3","chapterId":"ch_work_hdnk_29","text":"岐伯對曰：陰陽異位，更虛更實，更逆更從，或從內或從外，所從不同，故病異名也。","sortOrder":3},
  {"id":"s_work_hdnk_29_4","chapterId":"ch_work_hdnk_29","text":"帝曰：願聞其異狀也。岐伯曰：陽者天氣也，主外；陰者地氣也，主內。故陽道實，陰道虛。故犯賊風虛邪者陽受之，食飲不節，起居不時者，陰受之。陽受之則入六腑，陰受之則入五臟。入六腑則身熱不時臥，上為喘呼；入五臟則瞋滿閉塞，下為飧泄，久為腸澼。故喉主天氣，咽主地氣。故陽受風氣，陰受濕氣。","sortOrder":4},
  {"id":"s_work_hdnk_29_5","chapterId":"ch_work_hdnk_29","text":"故陰氣從足上行至頭，而下行循臂至指端；陽氣從手上行至頭，而下行至足。故曰陽病者上行極而下，陰病者下行極而上。故傷於風者上先受之，傷於濕者，下先受之。","sortOrder":5},
  {"id":"s_work_hdnk_29_6","chapterId":"ch_work_hdnk_29","text":"帝曰：脾病而四肢不用何也？岐伯曰：四肢皆稟氣於胃而不得至經，必因於脾乃得稟也。今脾病不能為胃行其津液，四肢不得稟水穀氣，氣日以衰，脈道不利，筋骨肌內，皆無氣以生，故不用焉。","sortOrder":6},
  {"id":"s_work_hdnk_29_7","chapterId":"ch_work_hdnk_29","text":"帝曰：脾不主時何也？岐伯曰：脾者土也。治中央，常以四時長四臟，各十八日寄治，不得獨主於時也。脾臟者常著胃土之精也。土者生萬物而法天地，故上下至頭足不得主時也。","sortOrder":7},
  {"id":"s_work_hdnk_29_8","chapterId":"ch_work_hdnk_29","text":"帝曰：脾與腎以膜相連耳，而能為之行其津液何也？岐伯曰：足太陰者三陰也，其脈貫胃，屬脾，絡溢，故太陰為之行氣於三陰。陽明者表也，五臟六腑之海也，亦為之行氣於三陽。臟腑各因其經而受氣於陽明，故為胃行其津液。四肢不得稟水穀氣，日以益衰，陰道不利，筋骨肌肉，無氣以生，故不用焉。","sortOrder":8},
  {"id":"s_work_hdnk_30_1","chapterId":"ch_work_hdnk_30","text":"陽明脈解篇第三十","sortOrder":1},
  {"id":"s_work_hdnk_30_2","chapterId":"ch_work_hdnk_30","text":"黃帝問曰：足陽明之脈病，惡人與火，聞木音則惕然而驚，鐘鼓不為動，聞木音而驚何也？願聞其故。岐伯對曰：陽明者，胃脈也，胃者土也，故聞木音而驚者，土惡木也。","sortOrder":2},
  {"id":"s_work_hdnk_30_3","chapterId":"ch_work_hdnk_30","text":"帝曰：善。其惡火何也？岐伯曰：陽明主肉，其脈血氣盛，邪客之則熱，熱甚則惡火。","sortOrder":3},
  {"id":"s_work_hdnk_30_4","chapterId":"ch_work_hdnk_30","text":"帝曰：其惡人何也？岐伯曰：陽明厥則喘而惋，惋則惡人。","sortOrder":4},
  {"id":"s_work_hdnk_30_5","chapterId":"ch_work_hdnk_30","text":"帝曰：或喘而死者，或喘而生者，何也？岐伯曰：厥逆連臟則死，連經則生。","sortOrder":5},
  {"id":"s_work_hdnk_30_6","chapterId":"ch_work_hdnk_30","text":"帝曰：善。病甚則棄衣而走，登高而歌，或至不食數日，逾垣上屋，所上之處，皆非其素所能也，病反能者何也？岐伯曰：四肢者諸陽之本也。陽盛則四肢實，實則能登高也。帝曰：其棄衣而走者何也？岐伯曰：熱盛於身，故棄衣欲走也。帝曰：其妄言罵詈，不避親疏而歌者何也？岐伯曰：陽盛則使人妄言罵詈，不避親疏而欲食，不欲食故妄走也。","sortOrder":6},
  {"id":"s_work_hdnk_31_1","chapterId":"ch_work_hdnk_31","text":"熱論篇第三十一","sortOrder":1},
  {"id":"s_work_hdnk_31_2","chapterId":"ch_work_hdnk_31","text":"黃帝問曰：今夫熱病者，皆傷寒之類也，或愈或死，其死皆以六七日之間，其愈皆以十日以上者，何也？不知其解，願聞其故。","sortOrder":2},
  {"id":"s_work_hdnk_31_3","chapterId":"ch_work_hdnk_31","text":"岐伯對曰：巨陽者，諸陽之屬也。其脈連於風府，故為諸陽主氣也。人之傷於寒也，則為病熱，熱雖甚不死，其兩感於寒而病者，必不免於死。","sortOrder":3},
  {"id":"s_work_hdnk_31_4","chapterId":"ch_work_hdnk_31","text":"帝曰：願聞其狀。岐伯曰：傷寒一日，巨陽受之，故頭項痛，腰脊強。","sortOrder":4},
  {"id":"s_work_hdnk_31_5","chapterId":"ch_work_hdnk_31","text":"二日陽明受之。陽明主肉，其脈俠鼻，絡於目，故身熱目痛而鼻乾，不得臥也。","sortOrder":5},
  {"id":"s_work_hdnk_31_6","chapterId":"ch_work_hdnk_31","text":"三日少陽受之，少陽主膽，其脈循脅絡於耳，故胸脅痛而耳聾。三陽經絡，皆受其病，而未入於臟者，故可汗而已。","sortOrder":6},
  {"id":"s_work_hdnk_31_7","chapterId":"ch_work_hdnk_31","text":"四日太陰受之太陰脈布胃中，絡於嗌，故腹滿而溢乾。","sortOrder":7},
  {"id":"s_work_hdnk_31_8","chapterId":"ch_work_hdnk_31","text":"五日少陰受之。少陰脈貫腎，絡於肺，系舌本，故口燥舌乾而渴。","sortOrder":8},
  {"id":"s_work_hdnk_31_9","chapterId":"ch_work_hdnk_31","text":"六日厥陰受之。厥陰脈循陰器而絡於肝，故煩滿而囊縮。","sortOrder":9},
  {"id":"s_work_hdnk_31_10","chapterId":"ch_work_hdnk_31","text":"三陰三陽，五臟六腑皆受病，榮衛不行，五臟不通，則死矣。","sortOrder":10},
  {"id":"s_work_hdnk_31_11","chapterId":"ch_work_hdnk_31","text":"其不兩感於寒者，七日巨陽病衰，頭痛少愈；八日陽明病衰，身熱少愈；九日少陽病衰，耳聾微聞；十日太陰病衰，腹減如故，則思飲食，十一日少陰病衰，渴止不滿，一古乾已而嚏，十二日厥陰病衰，囊縱，少腹微下，大氣皆去，病日已矣。","sortOrder":11},
  {"id":"s_work_hdnk_31_12","chapterId":"ch_work_hdnk_31","text":"帝曰：治之奈何？岐伯曰：治之各通其臟脈，病日衰已矣。其未滿三日者，可汗而已；其滿三日者，可泄而已。","sortOrder":12},
  {"id":"s_work_hdnk_31_13","chapterId":"ch_work_hdnk_31","text":"帝曰：熱病可愈，時有所遺者，何也？岐伯曰：諸遺者，熱甚而強食之，故有所遺也。若此者，皆病已衰而熱有所藏，因其穀氣相薄，兩熱相合，故有所遺也。帝曰：善。治遺奈何？岐伯曰：視其虛實，調其逆從，可使必已矣。","sortOrder":13},
  {"id":"s_work_hdnk_31_14","chapterId":"ch_work_hdnk_31","text":"帝曰：病熱當何治之？岐伯曰：病熱少愈，食肉則復，多食則遺，此其禁也。","sortOrder":14},
  {"id":"s_work_hdnk_31_15","chapterId":"ch_work_hdnk_31","text":"帝曰：其病兩感於寒者，其脈應與其病形何如？岐伯曰：兩感於寒者，病一日則巨陽與少陰俱病，則頭痛口乾而煩滿；二日則陽明與太陰俱病，則腹滿身熱，不欲食譫言，三日則少陽與厥陰俱病，則耳聾囊縮而厥。水漿不入，不知人，六日死。","sortOrder":15},
  {"id":"s_work_hdnk_31_16","chapterId":"ch_work_hdnk_31","text":"帝曰：五臟已傷，六腑不通，榮衛不行，如是之後，三日乃死，何也？岐伯曰：陽明者，十二經脈之長也，其血氣盛，故不知人，三日其氣乃盡，故死矣。","sortOrder":16},
  {"id":"s_work_hdnk_31_17","chapterId":"ch_work_hdnk_31","text":"凡病傷寒而成溫者，先夏至日者，為病溫，後夏至日者，為病暑。暑當與汗皆出，勿止。","sortOrder":17},
  {"id":"s_work_hdnk_32_1","chapterId":"ch_work_hdnk_32","text":"刺熱論篇第三十二","sortOrder":1},
  {"id":"s_work_hdnk_32_2","chapterId":"ch_work_hdnk_32","text":"肝熱病者，小便先黃，腹痛多臥，身熱。熱爭則狂言及驚，脅滿痛，手足躁，不得安臥。庚辛甚，甲乙大汗。氣逆則庚辛死。刺足厥陰少陽，其逆則頭痛員員，脈引沖頭也。","sortOrder":2},
  {"id":"s_work_hdnk_32_3","chapterId":"ch_work_hdnk_32","text":"心熱病者，先不樂，數日乃熱，熱爭則卒心痛，煩悶善嘔，頭痛面赤，無汗。壬癸甚，丙丁大汗。氣逆則壬癸死，刺手少陰太陽。","sortOrder":3},
  {"id":"s_work_hdnk_32_4","chapterId":"ch_work_hdnk_32","text":"脾熱病者，先頭重、頰痛、煩心、顏青、欲嘔、身熱。熱爭則腰痛，不可用俯仰，腹滿泄，兩頷痛。甲乙甚，戊己大汗；氣逆則甲乙死，刺足太陰陽明。","sortOrder":4},
  {"id":"s_work_hdnk_32_5","chapterId":"ch_work_hdnk_32","text":"肺熱病者，先淅然厥起毫毛，惡風寒，舌上黃身熱。熱爭則喘咳，痛走胸膺背，不得大息，頭痛不堪，汗出而寒。丙丁甚，庚辛大汗。氣逆則丙丁死。刺手太陰陽明，出血如大豆，立已。","sortOrder":5},
  {"id":"s_work_hdnk_32_6","chapterId":"ch_work_hdnk_32","text":"腎熱病者，先腰痛胻痠，苦渴數飲身熱。熱爭則項痛而強，胻寒且痠，足下熱，不欲言。其逆則項痛，員員淡淡然。戊己甚，壬癸大汗。氣逆則戊己死。刺足少陰太陽，諸汗者，至其所勝日汗出也。","sortOrder":6},
  {"id":"s_work_hdnk_32_7","chapterId":"ch_work_hdnk_32","text":"肝熱病者，左頰先赤；心熱病者，顏先赤；脾熱病者，鼻先赤；肺熱病者，右頰先赤；腎熱病，頤先赤。","sortOrder":7},
  {"id":"s_work_hdnk_32_8","chapterId":"ch_work_hdnk_32","text":"病雖未發，見赤色者刺之，名曰治未病。","sortOrder":8},
  {"id":"s_work_hdnk_32_9","chapterId":"ch_work_hdnk_32","text":"熱病從部所起者，至期而已，其刺之反者，三周而已。重逆則死。諸當汗者，至其所勝日，汗大出也。","sortOrder":9},
  {"id":"s_work_hdnk_32_10","chapterId":"ch_work_hdnk_32","text":"諸治熱病，以飲之寒水乃刺之，必寒應之，居止寒處，身寒而止也。","sortOrder":10},
  {"id":"s_work_hdnk_32_11","chapterId":"ch_work_hdnk_32","text":"熱病先胸脅痛，手足躁，刺足少陽，補足太陰。病甚者為五十九刺。","sortOrder":11},
  {"id":"s_work_hdnk_32_12","chapterId":"ch_work_hdnk_32","text":"熱病始手臂病者，刺手陽明太陰而汗出止。","sortOrder":12},
  {"id":"s_work_hdnk_32_13","chapterId":"ch_work_hdnk_32","text":"熱病始於頭首者，刺項太陽而汗出止。","sortOrder":13},
  {"id":"s_work_hdnk_32_14","chapterId":"ch_work_hdnk_32","text":"熱病先身重骨痛、耳聾、好瞑、刺足少陰，病甚為五十九刺。","sortOrder":14},
  {"id":"s_work_hdnk_32_15","chapterId":"ch_work_hdnk_32","text":"熱病先眩冒而熱，胸脅滿，刺足少陰少陽。","sortOrder":15},
  {"id":"s_work_hdnk_32_16","chapterId":"ch_work_hdnk_32","text":"太陽之脈色榮顴骨，熱病也。榮未交，曰今且得汗，待時而已。與厥陰脈爭見者，死期不過三日。","sortOrder":16},
  {"id":"s_work_hdnk_32_17","chapterId":"ch_work_hdnk_32","text":"其熱病內連腎，少陽之脈色也。少陽之脈色榮頰前，熱病也。榮未交，曰今且得汗，待時而已。與少陰脈爭見者，死期不過三日。","sortOrder":17},
  {"id":"s_work_hdnk_32_18","chapterId":"ch_work_hdnk_32","text":"熱病氣穴，三椎下間主胸中熱，四椎下間主膈中熱，五椎下間主肝熱，六椎下間主脾熱，七椎下間主腎熱。榮在骶也，項上三椎陷者中也。","sortOrder":18},
  {"id":"s_work_hdnk_32_19","chapterId":"ch_work_hdnk_32","text":"頰下逆顴為大瘕；下牙車為腹滿；顴後為脅痛；頰上者膈上也。","sortOrder":19},
  {"id":"s_work_hdnk_33_1","chapterId":"ch_work_hdnk_33","text":"評熱病論篇第三十三","sortOrder":1},
  {"id":"s_work_hdnk_33_2","chapterId":"ch_work_hdnk_33","text":"黃帝問曰：有病溫者，汗出輒復熱而脈躁疾，不為汗衰，狂言不能食，病名為何？岐伯對曰：病名陰陽交，交者死也。","sortOrder":2},
  {"id":"s_work_hdnk_33_3","chapterId":"ch_work_hdnk_33","text":"帝曰：願聞其說，岐伯曰：人所以汗出者，皆生於穀，穀生於精，今邪氣交爭於骨肉而得汗者，是邪卻而精勝也。精勝則當能食而不復熱；復熱者邪氣也，汗者精氣也，今汗出而輒復熱者，是邪勝也，不能食者，精無俾也。病而留者，其壽可立而傾也。且夫熱論曰：汗出而脈尚躁盛者死。今脈不與汗相應，此不勝其病也，其死明矣。狂言者是失志，失志者死，今見三死，不見一生，雖愈必死也。","sortOrder":3},
  {"id":"s_work_hdnk_33_4","chapterId":"ch_work_hdnk_33","text":"帝曰：有病身熱汗出煩滿，煩滿不為汗解，此為何病？岐伯曰：汗出而身熱者風也，汗出而煩滿不解者厥也，病名曰風厥。帝曰：願卒聞之，岐伯曰：巨陽主氣，故先受邪，少陰與其為表裏也，得熱則上從之，從之則厥也。帝曰：治之奈何？岐伯曰：表裏刺之，飲之服湯。","sortOrder":4},
  {"id":"s_work_hdnk_33_5","chapterId":"ch_work_hdnk_33","text":"帝曰：勞風為病何如？岐伯曰：勞風法在肺下，其為病也，使人強上，瞑視，唾出若涕，惡風而振寒，此為勞風之病。帝曰：治之奈何？岐伯曰：以救俯仰。巨陽引精者三日，中年者五日，不精者七日，咳出青黃涕，其狀如膿，大如彈丸，從口中若鼻中出，不出則傷肺，傷肺則死也。","sortOrder":5},
  {"id":"s_work_hdnk_33_6","chapterId":"ch_work_hdnk_33","text":"帝曰：有病腎風者，面胕龐然，壅害於言，可刺不？岐伯曰：虛不當刺，不當刺而刺，後五日其氣必至。帝曰：其至何如？岐伯曰：至必少氣時熱，時熱從胸背上至頭，汗出，手熱、口乾、苦渴、小便黃、目下腫、腹中嗚、身重難以行，月事不來，煩而不能食，不能正偃，正偃則咳，病名曰風水，論在刺法中。","sortOrder":6},
  {"id":"s_work_hdnk_33_7","chapterId":"ch_work_hdnk_33","text":"帝曰：願聞其說。岐伯曰：邪之所湊，其氣必虛；陰虛者，陽必湊之。故少氣時熱而汗出也。小便黃者，少腹中有熱也。不能正偃者，胃中不和也。正偃則咳甚，上迫肺也。諸有水氣者，微腫先見於目下也。","sortOrder":7},
  {"id":"s_work_hdnk_33_8","chapterId":"ch_work_hdnk_33","text":"帝曰：何以言？岐伯曰：水者陰也，目下亦陰也，腹者至陰之所居。故水在腹者，必使目下腫也。真氣上逆，故口苦舌乾，臥不得正偃，正偃則咳出清水也。諸水病者，故不得臥，臥則驚，驚則咳甚也，腹中嗚者，病本於胃也。薄脾則煩，不能食。食不下者，胃脘隔也。身重難以行者，胃脈在足也。月事不來者，胞脈閉也，胞脈者屬心，而絡於胞中，今氣上迫肺，心氣不得下通，故月事不來也。","sortOrder":8},
  {"id":"s_work_hdnk_34_1","chapterId":"ch_work_hdnk_34","text":"逆調論篇第三十四","sortOrder":1},
  {"id":"s_work_hdnk_34_2","chapterId":"ch_work_hdnk_34","text":"黃帝問曰：人身非常溫也，非常熱也，為之熱而煩滿者何也？岐伯對曰：陰氣少而陽氣勝也，故熱而煩滿也。","sortOrder":2},
  {"id":"s_work_hdnk_34_3","chapterId":"ch_work_hdnk_34","text":"帝曰：人身非衣寒也，中非有寒氣也，寒從中生者何？岐伯曰：是人多痺氣也，陽氣少陰氣多，故身寒如從水中出。","sortOrder":3},
  {"id":"s_work_hdnk_34_4","chapterId":"ch_work_hdnk_34","text":"帝曰：人有四肢熱，逢風寒如炙如火者何也？岐伯曰：是人者陰氣虛，陽氣盛，四肢者陽也，兩陽相得而陰氣虛少，少水不能滅盛火，而陽獨治。獨治者不能生長也，獨勝而止耳。逢風而如炙如火者，是人當肉爍也。","sortOrder":4},
  {"id":"s_work_hdnk_34_5","chapterId":"ch_work_hdnk_34","text":"帝曰：人有身寒，陽火不能熱，厚衣不能溫，然不凍慄，是為何病？岐伯曰：是人者，素腎氣勝，以水為事，太陽氣衰，腎脂枯木不長，一水不能勝兩火。腎者水也，而生於骨，腎不生，則髓不能滿，故寒甚至骨也。所以不能凍慄者，肝一陽也，心二陽也，腎孤臟也，一水不能勝二火，故不能凍慄，病名曰骨痺，是人當攣節也。","sortOrder":5},
  {"id":"s_work_hdnk_34_6","chapterId":"ch_work_hdnk_34","text":"帝曰：人之肉苛者，雖近亦絮，猶尚苛也，是謂何疾？岐伯曰：榮氣虛，衛氣實也，榮氣虛則不仁，衛氣虛則不用，榮衛俱虛，則不仁且不用，肉如故也。人與志不相有，曰死。","sortOrder":6},
  {"id":"s_work_hdnk_34_7","chapterId":"ch_work_hdnk_34","text":"帝曰：人有逆氣不得臥而息有音者，有不得臥而息無音者，有起居如故息有音者，有得臥行而喘者，有不得得臥不能行而喘者，有不得臥臥而喘者，皆何臟使然？願聞其故。","sortOrder":7},
  {"id":"s_work_hdnk_34_8","chapterId":"ch_work_hdnk_34","text":"岐伯曰：不得臥而息有音者，是陽明之逆也，足三陽者下行，今逆而上行，故息有音也。陽明者，胃脈也，胃者，六腑之海，其氣亦下行。陽明逆，不得從其道？故不得臥也。下經曰：胃不和，則臥不安，此之謂也。","sortOrder":8},
  {"id":"s_work_hdnk_34_9","chapterId":"ch_work_hdnk_34","text":"夫起居如故而息有音者，此肺之絡脈逆也，絡脈不得隨經上下，故留經而不行，絡脈之病人也微，故起居如故而息有音也。","sortOrder":9},
  {"id":"s_work_hdnk_34_10","chapterId":"ch_work_hdnk_34","text":"夫不得臥，臥則喘者，是水氣之客也。夫水者，循津液而流也，腎者水臟主津液，主臥與喘也。帝曰：善。","sortOrder":10},
  {"id":"s_work_hdnk_35_1","chapterId":"ch_work_hdnk_35","text":"瘧論篇第三十五","sortOrder":1},
  {"id":"s_work_hdnk_35_2","chapterId":"ch_work_hdnk_35","text":"黃帝問曰：夫痎瘧皆生於風，其蓋作有時者何也？岐伯對曰：瘧之始發也，先起於毫毛，伸欠乃作，寒慄鼓頷，腰脊俱痛，寒去則內外皆熱，頭疼如破，渴欲冷飲。","sortOrder":2},
  {"id":"s_work_hdnk_35_3","chapterId":"ch_work_hdnk_35","text":"帝曰：何氣使然？願聞其道。岐伯曰：陰陽上下交爭，虛實更作，陰陽相移也。","sortOrder":3},
  {"id":"s_work_hdnk_35_4","chapterId":"ch_work_hdnk_35","text":"陽並於陰，則陰實而陽虛，陽明虛則寒慄鼓頷也；巨陽虛則腰背頭項疼；三陽俱虛則陰氣勝，陰氣勝則骨寒而痛；寒生於內，故中外皆寒；陽盛則外熱，陰虛則內熱，則喘而渴，故欲冷飲也。","sortOrder":4},
  {"id":"s_work_hdnk_35_5","chapterId":"ch_work_hdnk_35","text":"此皆得之夏傷於暑，熱氣盛，藏於皮膚之內，腸胃之外，皆榮氣之所食也。","sortOrder":5},
  {"id":"s_work_hdnk_35_6","chapterId":"ch_work_hdnk_35","text":"此令人汗空疏，腠理開，因得秋氣；汗出遇風，及得之以浴，水氣舍於皮膚之內，與衛氣並居。衛氣者晝日行於陽，夜行於陰，此氣得陽而外出，得陰而內薄，內外相薄，是以曰作。","sortOrder":6},
  {"id":"s_work_hdnk_35_7","chapterId":"ch_work_hdnk_35","text":"帝曰：其間日而作者何也？岐伯曰：其氣之舍深，內薄於陰，陽氣獨發，陰邪內著，陰與陽爭不得出，是以間日而作也。","sortOrder":7},
  {"id":"s_work_hdnk_35_8","chapterId":"ch_work_hdnk_35","text":"帝曰：善。其作日晏與其日早者何氣使然？岐伯曰：邪氣客於風府，循膂而下，衛氣一日一夜大會於風府，其明日日下一節，故其作也晏。此先客於脊背也，每至於風府，則腠理開，腠理開，則邪氣入，邪氣入，則病作，以此日作稍益晏也；其出於風府日下一節，二十五日下至骶骨，二十六日入於脊內，註於伏膂之脈，其氣上行，九日出於缺盆之中，其氣日高，故作日益早也。","sortOrder":8},
  {"id":"s_work_hdnk_35_9","chapterId":"ch_work_hdnk_35","text":"其間日發者，由邪氣內薄於五臟，橫連募原也。其道遠，其氣深，其行遲，不能與衛氣俱行，不得皆出。故間日乃作也。","sortOrder":9},
  {"id":"s_work_hdnk_35_10","chapterId":"ch_work_hdnk_35","text":"帝曰：夫子言衛氣每至於風府，腠理乃發，發則邪氣入，入則病作，今衛氣日下一節，其氣之發也，不當風府，其日作者奈何？","sortOrder":10},
  {"id":"s_work_hdnk_35_11","chapterId":"ch_work_hdnk_35","text":"岐伯曰：此邪氣客於頭項，循膂而下者也。故虛實不同，邪中異所，則不得當其風府也。故邪中於頭項者，氣至頭項而病；中於背者，氣至背而病；中於腰脊者，氣至腰脊而病；中於手足者，氣至手足而病。衛氣之所在與邪氣相合，則病作。故風無常府，衛氣之所發必開其腠理，邪氣之所合，則其府也。","sortOrder":11},
  {"id":"s_work_hdnk_35_12","chapterId":"ch_work_hdnk_35","text":"帝曰：善。夫風之與瘧也，相似同類，而風獨常在，瘧得有時而休者何也？岐伯曰：風氣留其處，故常在，瘧氣隨經絡，沈以內薄，故衛氣應乃作。","sortOrder":12},
  {"id":"s_work_hdnk_35_13","chapterId":"ch_work_hdnk_35","text":"帝曰：瘧先寒而後熱者何也？岐伯曰：夏傷於大暑，其汗大出，腠理開發，因遇夏氣淒滄之水寒，藏於腠理皮膚之中，秋傷於風，則病成矣。夫寒者，陰氣也，風者，陽氣也，先傷於寒而後傷於風，故先寒而後熱也。病以時作，名曰寒瘧。","sortOrder":13},
  {"id":"s_work_hdnk_35_14","chapterId":"ch_work_hdnk_35","text":"帝曰：先熱而後寒者何也？岐伯曰：此先傷於風，而後傷於寒。故先熱而後寒也。亦以時作，名曰溫瘧。","sortOrder":14},
  {"id":"s_work_hdnk_35_15","chapterId":"ch_work_hdnk_35","text":"其但熱而不寒者，陰氣先絕，陽氣獨發，則少氣煩冤，手足熱而欲嘔，名曰癉瘧。","sortOrder":15},
  {"id":"s_work_hdnk_35_16","chapterId":"ch_work_hdnk_35","text":"帝曰：夫經言有餘者瀉之，不足者補之，今熱為有餘，寒為不足。夫瘧者之寒，湯火不能溫也，及其熱，冰水不能寒也，此皆有餘不足之類。當此之時，良工不能止，必須其自衰，乃刺之，其故何也？願聞其說。岐伯曰：經言無刺熇熇之熱，無刺渾渾之脈，無刺漉漉之汗，故為其病逆未可治也。","sortOrder":16},
  {"id":"s_work_hdnk_35_17","chapterId":"ch_work_hdnk_35","text":"夫瘧之始發也，陽氣並於陰，當是之時，陽虛而陰盛，外無氣故先寒慄也。陰氣逆極則復出之陽，陽與陰復並於外，則陰虛而陽實，故先熱而渴。","sortOrder":17},
  {"id":"s_work_hdnk_35_18","chapterId":"ch_work_hdnk_35","text":"夫瘧氣者，並於陽則陽勝，並於陰則陰勝？陰勝則寒，陽勝則熱。瘧者，風寒之氣不常也。病極則復。","sortOrder":18},
  {"id":"s_work_hdnk_35_19","chapterId":"ch_work_hdnk_35","text":"至病之發也，如火之熱，如風雨不可當也。故經言曰：方其盛時，必毀，因其衰也，事必大昌，此之謂也。","sortOrder":19},
  {"id":"s_work_hdnk_35_20","chapterId":"ch_work_hdnk_35","text":"夫瘧之未發也，陰未並陽，陽未並陰，因而調之，真氣得安，邪氣乃亡。故工不能治其已發為其氣逆也。","sortOrder":20},
  {"id":"s_work_hdnk_35_21","chapterId":"ch_work_hdnk_35","text":"帝曰：善。攻之奈何？早晏何如？岐伯曰：瘧之且發也，陰陽之且移也，必從四末始也。陽已傷，陰從之，故先其時緊束其處，令邪氣不得入，陰氣不得出，審候見之在孫絡盛堅而血者，皆取之，此真往而未得並者也。","sortOrder":21},
  {"id":"s_work_hdnk_35_22","chapterId":"ch_work_hdnk_35","text":"帝曰：瘧不發其應何如？岐伯曰：瘧氣者，必更盛更虛，當氣之所在也。病在陽則熱而脈躁，在陰則寒而脈靜，極則陰陽俱衰，衛氣相離，故病得休，衛氣集則復病也。","sortOrder":22},
  {"id":"s_work_hdnk_35_23","chapterId":"ch_work_hdnk_35","text":"帝曰：時有間二日或至數日發，或渴或不渴，其故何也？岐伯曰：其間日者邪氣與衛氣客於六腑，而有時相失不能相得，故休數日乃作也。瘧者陰陽更勝也，或甚或不甚，故或渴或不渴。","sortOrder":23},
  {"id":"s_work_hdnk_35_24","chapterId":"ch_work_hdnk_35","text":"帝曰：論言夏傷於暑，秋必病瘧，今瘧不必應者何也？岐伯曰：此應四時者也。其病異形者，反四時也。其以秋病者寒甚，以冬病者寒不甚，以春病者惡風，以夏病者多汗。","sortOrder":24},
  {"id":"s_work_hdnk_35_25","chapterId":"ch_work_hdnk_35","text":"帝曰：夫病溫瘧與寒瘧，而皆安舍，舍於何臟？","sortOrder":25},
  {"id":"s_work_hdnk_35_26","chapterId":"ch_work_hdnk_35","text":"岐伯曰：溫瘧者，得之冬中於風，寒氣藏於骨髓之中，至春則陽氣大發，邪氣不能自出，因遇大暑，腦髓爍，肌肉消，腠理發泄，或有所用力，邪氣與汗皆出，此病藏於腎，其氣先從內出之於外也。如是者，陰虛而陽盛，陽盛則熱矣。衰則氣復反入，入則陽虛，陽虛則寒矣。故先熱而後寒，名曰溫瘧。","sortOrder":26},
  {"id":"s_work_hdnk_35_27","chapterId":"ch_work_hdnk_35","text":"帝曰：癉瘧何如？岐伯曰：癉瘧者肺素有熱，氣盛於身，厥逆上沖，中氣實而不外泄，因有所用力，腠理開，風寒舍於皮膚之內，分肉之間而發，發則陽氣盛，陽氣盛而不衰則病矣。其氣不及於陰，故但熱而不寒，氣內藏於心而外舍於分肉之間，令人消爍脫肉，故命曰癉瘧。帝曰：善。","sortOrder":27},
  {"id":"s_work_hdnk_36_1","chapterId":"ch_work_hdnk_36","text":"刺瘧篇第三十六","sortOrder":1},
  {"id":"s_work_hdnk_36_2","chapterId":"ch_work_hdnk_36","text":"足太陽之瘧，令人腰痛頭重，寒從背起，先寒後熱，熇熇暍暍然，熱止汗出難已，刺郄中出血。","sortOrder":2},
  {"id":"s_work_hdnk_36_3","chapterId":"ch_work_hdnk_36","text":"足少陽之瘧，令人身體解肌，寒不甚，熱不甚，惡見人，見人心惕惕然，熱多汗出甚，刺足少陽。","sortOrder":3},
  {"id":"s_work_hdnk_36_4","chapterId":"ch_work_hdnk_36","text":"足陽明之瘧，令人先寒洒淅、洒淅寒甚，久乃熱，熱去汗出，喜見日月光火氣，乃快然。刺足陽明趾上趺。","sortOrder":4},
  {"id":"s_work_hdnk_36_5","chapterId":"ch_work_hdnk_36","text":"足太陰之瘧，令人不樂，好太息，不嗜食，多寒熱汗出，病至則善嘔，嘔已乃衰，即取之。","sortOrder":5},
  {"id":"s_work_hdnk_36_6","chapterId":"ch_work_hdnk_36","text":"足太陰之瘧，令人嘔吐甚，多寒熱，熱多寒少，欲閉戶牖而處，其病難已。","sortOrder":6},
  {"id":"s_work_hdnk_36_7","chapterId":"ch_work_hdnk_36","text":"足厥陰之瘧，令人腰痛，少腹滿、小便不利、如癃狀，非癃也。數便，意恐懼，氣不足，腹中悒悒，刺足厥陰。","sortOrder":7},
  {"id":"s_work_hdnk_36_8","chapterId":"ch_work_hdnk_36","text":"肺瘧者，令人心寒，寒甚熱，熱間善驚，如有所見者，刺手太陰陽明。","sortOrder":8},
  {"id":"s_work_hdnk_36_9","chapterId":"ch_work_hdnk_36","text":"心瘧者，令人煩心甚，欲得清水，反寒多，不甚熱，刺手少陰。","sortOrder":9},
  {"id":"s_work_hdnk_36_10","chapterId":"ch_work_hdnk_36","text":"肝瘧者，令人色蒼蒼然太息，其狀若死者，刺足厥陰見血。","sortOrder":10},
  {"id":"s_work_hdnk_36_11","chapterId":"ch_work_hdnk_36","text":"脾瘧者，令人寒，腹中痛。熱則腸中鳴，鳴已汗出，刺足太陰。","sortOrder":11},
  {"id":"s_work_hdnk_36_12","chapterId":"ch_work_hdnk_36","text":"腎瘧者，令人洒洒然，腰脊痛，婉轉大便難，目眴眴然，手足寒。刺足太陽少陰。","sortOrder":12},
  {"id":"s_work_hdnk_36_13","chapterId":"ch_work_hdnk_36","text":"胃瘧者，令人且病也，善飢而不能食，食而支滿腹大。刺足陽明太陰橫脈出血。","sortOrder":13},
  {"id":"s_work_hdnk_36_14","chapterId":"ch_work_hdnk_36","text":"瘧發身方熱，刺趾上動脈，開其空，出其血，立寒。","sortOrder":14},
  {"id":"s_work_hdnk_36_15","chapterId":"ch_work_hdnk_36","text":"瘧方欲寒，刺手陽明太陰，足陽明太陰。","sortOrder":15},
  {"id":"s_work_hdnk_36_16","chapterId":"ch_work_hdnk_36","text":"瘧脈滿大急，刺背俞，用中針傍五胠俞各一，適肥瘦出其血也。","sortOrder":16},
  {"id":"s_work_hdnk_36_17","chapterId":"ch_work_hdnk_36","text":"瘧脈小實急，灸脛少陰，刺指井。","sortOrder":17},
  {"id":"s_work_hdnk_36_18","chapterId":"ch_work_hdnk_36","text":"瘧脈滿大急，刺背俞，用五胠俞、背俞各一，適行至於血也。","sortOrder":18},
  {"id":"s_work_hdnk_36_19","chapterId":"ch_work_hdnk_36","text":"瘧脈緩大虛，便宜用藥，不宜用針。","sortOrder":19},
  {"id":"s_work_hdnk_36_20","chapterId":"ch_work_hdnk_36","text":"凡治瘧，先發如食頃，乃可以治，過之，則失時也。","sortOrder":20},
  {"id":"s_work_hdnk_36_21","chapterId":"ch_work_hdnk_36","text":"諸瘧而脈不見，刺十指間出血，血去必已。先視身之赤如小豆者，儘取之。","sortOrder":21},
  {"id":"s_work_hdnk_36_22","chapterId":"ch_work_hdnk_36","text":"十二瘧者，其發各不同時，察其病形，以知其何脈之病也。先其發時，如食頃而刺之，一刺則衰，二刺則知，三刺則已，不已刺舌下兩脈出血，不已刺郄中盛經出血，又刺項已下挾脊者必已。舌下兩脈者，廉泉也。","sortOrder":22},
  {"id":"s_work_hdnk_36_23","chapterId":"ch_work_hdnk_36","text":"刺瘧者，必先問其病之所先發者，先刺之，先頭痛及重者，先刺頭上及兩額兩眉之間；先腰脊痛者，先刺郄中出血；先手臂痛者，先刺手少陰陽明十指間；先足脛酸痛者，先刺足陽明十指間出血。","sortOrder":23},
  {"id":"s_work_hdnk_36_24","chapterId":"ch_work_hdnk_36","text":"風瘧、瘧發則汗出惡風。刺三陽經背俞之血者。","sortOrder":24},
  {"id":"s_work_hdnk_36_25","chapterId":"ch_work_hdnk_36","text":"〈骨行〉痠痛甚，按之不可，名曰胕髓病。以鑱針，針絕骨出血，立已。","sortOrder":25},
  {"id":"s_work_hdnk_36_26","chapterId":"ch_work_hdnk_36","text":"身體小痛，刺至陰。","sortOrder":26},
  {"id":"s_work_hdnk_36_27","chapterId":"ch_work_hdnk_36","text":"諸陰之井無出血，間日一刺。","sortOrder":27},
  {"id":"s_work_hdnk_36_28","chapterId":"ch_work_hdnk_36","text":"瘧不渴，間日而作，刺足太陽。渴而間日作，刺足少陽。","sortOrder":28},
  {"id":"s_work_hdnk_36_29","chapterId":"ch_work_hdnk_36","text":"濕瘧汗不出，為五十九刺。","sortOrder":29},
  {"id":"s_work_hdnk_37_1","chapterId":"ch_work_hdnk_37","text":"氣厥論篇第三十七","sortOrder":1},
  {"id":"s_work_hdnk_37_2","chapterId":"ch_work_hdnk_37","text":"黃帝問曰：五臟六腑寒熱相移者何？","sortOrder":2},
  {"id":"s_work_hdnk_37_3","chapterId":"ch_work_hdnk_37","text":"岐伯曰：腎移寒於肝，癰腫少氣。","sortOrder":3},
  {"id":"s_work_hdnk_37_4","chapterId":"ch_work_hdnk_37","text":"脾移寒於肝，癰腫筋攣。","sortOrder":4},
  {"id":"s_work_hdnk_37_5","chapterId":"ch_work_hdnk_37","text":"肝移寒於心，狂隔中。","sortOrder":5},
  {"id":"s_work_hdnk_37_6","chapterId":"ch_work_hdnk_37","text":"心移寒於肺，肺消。肺消者飲一溲二，死不治。","sortOrder":6},
  {"id":"s_work_hdnk_37_7","chapterId":"ch_work_hdnk_37","text":"肺移寒於腎，為涌水。涌水者，按腹不堅，水氣客於大腸，疾行則嗚濯濯，如囊裏漿水之病也。","sortOrder":7},
  {"id":"s_work_hdnk_37_8","chapterId":"ch_work_hdnk_37","text":"脾移熱於肝，則為驚衄。","sortOrder":8},
  {"id":"s_work_hdnk_37_9","chapterId":"ch_work_hdnk_37","text":"肝移熱於心，則死。","sortOrder":9},
  {"id":"s_work_hdnk_37_10","chapterId":"ch_work_hdnk_37","text":"心移熱於肺，傳為膈消。","sortOrder":10},
  {"id":"s_work_hdnk_37_11","chapterId":"ch_work_hdnk_37","text":"肺移熱於腎，傳為柔痊。","sortOrder":11},
  {"id":"s_work_hdnk_37_12","chapterId":"ch_work_hdnk_37","text":"腎移熱於脾，傳為虛，腸澼，死不可治。","sortOrder":12},
  {"id":"s_work_hdnk_37_13","chapterId":"ch_work_hdnk_37","text":"胞移熱於膀胱，則癃溺血。","sortOrder":13},
  {"id":"s_work_hdnk_37_14","chapterId":"ch_work_hdnk_37","text":"膀胱移熱於小腸，膈腸不便，上為口糜。","sortOrder":14},
  {"id":"s_work_hdnk_37_15","chapterId":"ch_work_hdnk_37","text":"小腸移熱於大腸，為虙瘕，為沉。","sortOrder":15},
  {"id":"s_work_hdnk_37_16","chapterId":"ch_work_hdnk_37","text":"大腸移熱於胃，善食而瘦入，謂之食亦。","sortOrder":16},
  {"id":"s_work_hdnk_37_17","chapterId":"ch_work_hdnk_37","text":"胃移熱於膽，亦曰食亦。","sortOrder":17},
  {"id":"s_work_hdnk_37_18","chapterId":"ch_work_hdnk_37","text":"膽移熱於腦，則辛頞鼻淵。鼻淵者，濁涕不下止也，傳為衄蔑、瞑目。故得之氣厥也。","sortOrder":18},
  {"id":"s_work_hdnk_38_1","chapterId":"ch_work_hdnk_38","text":"欬論篇第三十八","sortOrder":1},
  {"id":"s_work_hdnk_38_2","chapterId":"ch_work_hdnk_38","text":"黃帝問曰：肺之令人咳何也？岐伯對曰：五臟六腑皆令人咳，非獨肺也。","sortOrder":2},
  {"id":"s_work_hdnk_38_3","chapterId":"ch_work_hdnk_38","text":"帝曰：願聞其狀？岐伯曰：皮毛者肺之合也。皮毛先受邪氣，邪氣以從其合也。其寒飲食人胃，從肺脈上至於肺，則肺寒，肺寒則外內合，邪因而客之，則為肺咳。","sortOrder":3},
  {"id":"s_work_hdnk_38_4","chapterId":"ch_work_hdnk_38","text":"五臟各以其時受病，非其時各傳以與之。","sortOrder":4},
  {"id":"s_work_hdnk_38_5","chapterId":"ch_work_hdnk_38","text":"人與天地相參，故五臟各以治時，感於寒則受病，微則為咳，甚者為泄為痛。","sortOrder":5},
  {"id":"s_work_hdnk_38_6","chapterId":"ch_work_hdnk_38","text":"乘秋則肺先受邪，乘春則肝先受之，乘夏則心先受之，乘至陰則脾先受之，乘冬則腎先受之。","sortOrder":6},
  {"id":"s_work_hdnk_38_7","chapterId":"ch_work_hdnk_38","text":"帝曰：何以異之？","sortOrder":7},
  {"id":"s_work_hdnk_38_8","chapterId":"ch_work_hdnk_38","text":"岐伯曰：肺咳之狀，咳而喘息有音，甚則唾血。","sortOrder":8},
  {"id":"s_work_hdnk_38_9","chapterId":"ch_work_hdnk_38","text":"心咳之狀，咳則心痛，喉中介介如梗狀，甚則咽腫，喉痺。","sortOrder":9},
  {"id":"s_work_hdnk_38_10","chapterId":"ch_work_hdnk_38","text":"肝咳之狀，咳則兩脅下痛，甚則不可以轉，轉則兩胠下滿。","sortOrder":10},
  {"id":"s_work_hdnk_38_11","chapterId":"ch_work_hdnk_38","text":"脾咳之狀，咳則右脅下痛，陰陰引肩背，甚則不可以動，動則咳劇。","sortOrder":11},
  {"id":"s_work_hdnk_38_12","chapterId":"ch_work_hdnk_38","text":"腎咳之狀，咳則腰背相引而痛，甚則咳涎。","sortOrder":12},
  {"id":"s_work_hdnk_38_13","chapterId":"ch_work_hdnk_38","text":"帝曰：六腑之咳奈何？安所受病？岐伯曰：五臟之久咳，乃移於六腑。","sortOrder":13},
  {"id":"s_work_hdnk_38_14","chapterId":"ch_work_hdnk_38","text":"脾咳不已，則胃受之。胃咳之狀，咳而嘔，嘔甚則長蟲出。","sortOrder":14},
  {"id":"s_work_hdnk_38_15","chapterId":"ch_work_hdnk_38","text":"肝咳不已則膽受之，膽咳之狀，咳嘔膽汁。","sortOrder":15},
  {"id":"s_work_hdnk_38_16","chapterId":"ch_work_hdnk_38","text":"肺咳不已則大腸變之，大腸咳狀，咳而遺失。","sortOrder":16},
  {"id":"s_work_hdnk_38_17","chapterId":"ch_work_hdnk_38","text":"心咳不已則小腸受之，小腸咳狀，咳而失氣，氣與咳俱失。","sortOrder":17},
  {"id":"s_work_hdnk_38_18","chapterId":"ch_work_hdnk_38","text":"腎咳不已則膀胱受之，膀胱咳狀，咳而遺溺。","sortOrder":18},
  {"id":"s_work_hdnk_38_19","chapterId":"ch_work_hdnk_38","text":"久咳不已則三焦受之，三焦咳狀，咳而腹滿不欲食飲。","sortOrder":19},
  {"id":"s_work_hdnk_38_20","chapterId":"ch_work_hdnk_38","text":"此皆緊於胃關於肺，使人多涕唾而面浮腫氣逆也。","sortOrder":20},
  {"id":"s_work_hdnk_38_21","chapterId":"ch_work_hdnk_38","text":"帝曰：治之奈何？岐伯曰：治臟者治其俞，治腑者治其合，浮腫者治其經。帝曰：善。","sortOrder":21},
  {"id":"s_work_hdnk_39_1","chapterId":"ch_work_hdnk_39","text":"舉痛論篇第三十九","sortOrder":1},
  {"id":"s_work_hdnk_39_2","chapterId":"ch_work_hdnk_39","text":"黃帝問曰：餘聞善言天者，必有驗於人，善言古者，必有合於今；善言人者，必有厭於已。如此則道不惑而要數極，所謂明也。","sortOrder":2},
  {"id":"s_work_hdnk_39_3","chapterId":"ch_work_hdnk_39","text":"今餘問於夫子，令言而可知，視而可見，捫而可得，令驗於己而發蒙解惑，可得而聞乎？","sortOrder":3},
  {"id":"s_work_hdnk_39_4","chapterId":"ch_work_hdnk_39","text":"岐伯再拜稽首曰：何道之問也？帝曰：願聞人之五臟卒痛，何氣使然？岐伯對曰：經脈流行不止，環周不休，寒氣入經而稽遲。泣而不行，客於脈外，則血少，客於脈中則氣不通，故卒然而痛。","sortOrder":4},
  {"id":"s_work_hdnk_39_5","chapterId":"ch_work_hdnk_39","text":"帝曰：其痛或卒然而止者；或痛甚不休者；或痛甚不可按者；或按之而痛止者；或按之無益者；或喘動應手者；或心與背相引而痛者；或脅肋與少腹相引而痛者；或腹痛引陰股者；或痛宿昔而成積者；或卒然痛死不知人，有少間復生者；或痛而嘔者；或腹痛而後泄者；或痛而閉不通者。凡此諸痛，各不同形，別之奈何？","sortOrder":5},
  {"id":"s_work_hdnk_39_6","chapterId":"ch_work_hdnk_39","text":"岐伯曰：寒氣客於脈外，則脈寒，脈寒則縮踡，縮踡則脈絀急，則外引小絡，故卒然而痛。得炅則痛立止，因重中於寒，則痛久矣。","sortOrder":6},
  {"id":"s_work_hdnk_39_7","chapterId":"ch_work_hdnk_39","text":"寒氣客於經脈之中，與炅氣相薄，則脈滿，滿則痛而不可按也。寒氣稽留，炅氣從上，則脈充大而血氣亂，故痛甚不可按也。","sortOrder":7},
  {"id":"s_work_hdnk_39_8","chapterId":"ch_work_hdnk_39","text":"寒氣客於腸胃之間，膜原之下，血不得散，小絡急引故痛。按之則血氣散，故按之痛止。","sortOrder":8},
  {"id":"s_work_hdnk_39_9","chapterId":"ch_work_hdnk_39","text":"寒氣客於挾脊之脈則深，按之不能及，故按之無益也。","sortOrder":9},
  {"id":"s_work_hdnk_39_10","chapterId":"ch_work_hdnk_39","text":"寒氣客於沖脈，沖脈起於關元，隨腹直上，寒氣客則脈不通，脈不通則氣因之，故喘氣應手矣。","sortOrder":10},
  {"id":"s_work_hdnk_39_11","chapterId":"ch_work_hdnk_39","text":"寒氣客於背俞之脈，則脈泣，脈泣則血虛，血虛則痛。其俞註於心，故相引而痛。按之則熱氣至，熱氣至則痛上矣。","sortOrder":11},
  {"id":"s_work_hdnk_39_12","chapterId":"ch_work_hdnk_39","text":"寒氣客於厥陰之脈，厥陰之脈者，絡陰器，繫於肝。寒氣客於脈中，則血泣脈急，故脅肋與少腹相引痛矣。","sortOrder":12},
  {"id":"s_work_hdnk_39_13","chapterId":"ch_work_hdnk_39","text":"厥氣客於陰股，寒氣上及少腹，血泣在下相引，故腹痛引陰股。","sortOrder":13},
  {"id":"s_work_hdnk_39_14","chapterId":"ch_work_hdnk_39","text":"寒氣客於小腸膜原之間，絡血之中，血泣不得註入大經，血氣稽留不得行，故宿昔而成積矣。","sortOrder":14},
  {"id":"s_work_hdnk_39_15","chapterId":"ch_work_hdnk_39","text":"寒氣客於五臟，厥逆上泄，陰氣竭，陽氣未入，故卒然痛死不知人，氣復反則生矣。","sortOrder":15},
  {"id":"s_work_hdnk_39_16","chapterId":"ch_work_hdnk_39","text":"寒氣客於腸胃，厥逆上出，故痛而嘔也。","sortOrder":16},
  {"id":"s_work_hdnk_39_17","chapterId":"ch_work_hdnk_39","text":"熱氣留於小腸，腸中痛，癉熱焦渴，則堅乾不得出，故痛而閉不通矣。","sortOrder":17},
  {"id":"s_work_hdnk_39_18","chapterId":"ch_work_hdnk_39","text":"帝曰：所謂言而可知者也，視而可見奈何？","sortOrder":18},
  {"id":"s_work_hdnk_39_19","chapterId":"ch_work_hdnk_39","text":"岐伯曰：五臟六腑固盡有部，視其五色，黃赤為熱，白為寒，青黑為痛，此所謂視而可見者也。","sortOrder":19},
  {"id":"s_work_hdnk_39_20","chapterId":"ch_work_hdnk_39","text":"帝曰：捫而可得奈何？岐伯曰：視其主病之脈堅，而血及陷下者，皆可捫而得也。","sortOrder":20},
  {"id":"s_work_hdnk_39_21","chapterId":"ch_work_hdnk_39","text":"帝曰：善。餘知百病生於氣也，怒則氣上，喜則氣緩，悲則氣消，恐則氣下，寒則氣收，炅則氣泄，驚則氣亂，勞則氣耗，思則氣結。九氣不同，何病之生？","sortOrder":21},
  {"id":"s_work_hdnk_39_22","chapterId":"ch_work_hdnk_39","text":"岐伯曰：怒則氣逆，甚則嘔血及飧泄，故氣上矣。","sortOrder":22},
  {"id":"s_work_hdnk_39_23","chapterId":"ch_work_hdnk_39","text":"喜則氣和志達，榮衛通利，故氣緩矣。","sortOrder":23},
  {"id":"s_work_hdnk_39_24","chapterId":"ch_work_hdnk_39","text":"悲則心系急，肺布葉舉，而上焦不通，榮衛不散，熱氣在中，故氣消矣。","sortOrder":24},
  {"id":"s_work_hdnk_39_25","chapterId":"ch_work_hdnk_39","text":"恐則精卻，卻則上焦閉，閉則氣還，還則下焦脹，故氣不行矣。","sortOrder":25},
  {"id":"s_work_hdnk_39_26","chapterId":"ch_work_hdnk_39","text":"寒則腠理閉，氣不行，故氣收矣。","sortOrder":26},
  {"id":"s_work_hdnk_39_27","chapterId":"ch_work_hdnk_39","text":"炅則腠理開，榮衛通，汗大泄，故氣泄。","sortOrder":27},
  {"id":"s_work_hdnk_39_28","chapterId":"ch_work_hdnk_39","text":"驚則心無所依，神無所歸，慮無所定，故氣亂矣。","sortOrder":28},
  {"id":"s_work_hdnk_39_29","chapterId":"ch_work_hdnk_39","text":"勞則喘息汗出，外內皆越，故氣耗矣。","sortOrder":29},
  {"id":"s_work_hdnk_39_30","chapterId":"ch_work_hdnk_39","text":"思則心有所存，神有所歸，正氣留而不行，故氣結矣。","sortOrder":30},
  {"id":"s_work_hdnk_40_1","chapterId":"ch_work_hdnk_40","text":"腹中論篇第四十","sortOrder":1},
  {"id":"s_work_hdnk_40_2","chapterId":"ch_work_hdnk_40","text":"黃帝問曰：有病心腹滿，旦食則不能暮食，此為何病？岐伯對曰：名為鼓脹。","sortOrder":2},
  {"id":"s_work_hdnk_40_3","chapterId":"ch_work_hdnk_40","text":"帝曰：治之奈何？岐伯曰：治之以雞矢醴，一劑知，二劑已。","sortOrder":3},
  {"id":"s_work_hdnk_40_4","chapterId":"ch_work_hdnk_40","text":"帝曰：其時有復發者，何也？岐伯曰：此飲食不節，故時有病也。雖然其病也已時，故當病氣聚於腹也。","sortOrder":4},
  {"id":"s_work_hdnk_40_5","chapterId":"ch_work_hdnk_40","text":"帝曰：有病胸脅支滿者，妨於食，病至則先聞腥臊臭，出清液，先唾血，四支清，目眩，時時前後血，病名為何，何以得之？","sortOrder":5},
  {"id":"s_work_hdnk_40_6","chapterId":"ch_work_hdnk_40","text":"岐伯曰：病名血枯，此得之年少時，有所大脫血。若醉入房，中氣竭，肝傷，故月事衰少不來也。","sortOrder":6},
  {"id":"s_work_hdnk_40_7","chapterId":"ch_work_hdnk_40","text":"帝曰：治之奈何？復以何術？岐伯曰：以四烏鰂骨，一蘆茹，二物併合之，丸以雀卵，大小如豆，以五丸為後飯，飲以鮑魚汁，利腸中，及傷肝也。","sortOrder":7},
  {"id":"s_work_hdnk_40_8","chapterId":"ch_work_hdnk_40","text":"帝曰：病有少腹盛，上下左右皆有根，此為何病？可治不？","sortOrder":8},
  {"id":"s_work_hdnk_40_9","chapterId":"ch_work_hdnk_40","text":"岐伯曰：病名曰伏梁。","sortOrder":9},
  {"id":"s_work_hdnk_40_10","chapterId":"ch_work_hdnk_40","text":"帝曰：伏梁何因而得之？岐伯曰：裹大膿血，居腸胃之外，不可治，治之每切按之致死。","sortOrder":10},
  {"id":"s_work_hdnk_40_11","chapterId":"ch_work_hdnk_40","text":"帝曰：何以然？岐伯曰：此下則因陰，必下膿血，上則迫胃脘，生膈俠胃脘內癰，此久病也，難治。居臍上為逆，居臍下為從，勿動亟奪，論在刺法中。","sortOrder":11},
  {"id":"s_work_hdnk_40_12","chapterId":"ch_work_hdnk_40","text":"帝曰：人有身體髀股〈骨行〉皆腫，環臍而痛，是為何病？岐伯曰：病名伏梁，此風根也。其氣溢於大腸而著於肓，肓之原在臍下，故環臍而痛也。不可動之，動之為水溺澀之病。","sortOrder":12},
  {"id":"s_work_hdnk_40_13","chapterId":"ch_work_hdnk_40","text":"帝曰：夫子數言熱中，消中，不可服高梁芳草石藥。石藥發瘨，芳草發狂。夫熱中消中者，皆富貴人也，今禁高梁，是不合其心，禁芳草石藥，是病不愈，願聞其說。","sortOrder":13},
  {"id":"s_work_hdnk_40_14","chapterId":"ch_work_hdnk_40","text":"岐伯曰：夫芳草之氣美，石藥之氣悍，二者其氣急疾堅勁，故非緩心和人，不可以服此二者。","sortOrder":14},
  {"id":"s_work_hdnk_40_15","chapterId":"ch_work_hdnk_40","text":"帝曰：不可以服此二者，何以然？岐伯曰：夫熱氣慓悍，藥氣亦然，二者相遇，恐內傷脾，脾者土也，而惡木，服此藥者，至甲乙日更論。","sortOrder":15},
  {"id":"s_work_hdnk_40_16","chapterId":"ch_work_hdnk_40","text":"帝曰：善。有病膺腫，頭痛胸滿腹脹，此為何病？何以得之？岐伯曰：名厥逆。","sortOrder":16},
  {"id":"s_work_hdnk_40_17","chapterId":"ch_work_hdnk_40","text":"帝曰：治之奈何？岐伯曰：灸之則瘖，石之則狂，須其氣並，乃可治也。","sortOrder":17},
  {"id":"s_work_hdnk_40_18","chapterId":"ch_work_hdnk_40","text":"帝曰：何以然？岐伯曰：陰氣重上，有餘於上，灸之則陽氣入陰，入則瘖，石之則陽氣虛，虛則狂，須其氣並而治之，可使全也。","sortOrder":18},
  {"id":"s_work_hdnk_40_19","chapterId":"ch_work_hdnk_40","text":"帝曰：善。何以知懷子之且生也？岐伯曰：身有病而無邪脈也。","sortOrder":19},
  {"id":"s_work_hdnk_40_20","chapterId":"ch_work_hdnk_40","text":"帝曰：病熱而有所痛者何也？岐伯曰：病熱者陽脈也，以三陽之動也。人迎一盛少陽，二盛太陽，三盛陽明，入陰也。夫陽入於陰，故病在頭與腹，乃〈月真〉脹而頭痛也。帝曰：善。","sortOrder":20},
  {"id":"s_work_hdnk_41_1","chapterId":"ch_work_hdnk_41","text":"刺腰論痛篇第四十一","sortOrder":1},
  {"id":"s_work_hdnk_41_2","chapterId":"ch_work_hdnk_41","text":"足太陽脈，令人腰痛引項脊尻背如重狀，刺其郄中，太陽正經出血，春無見血。","sortOrder":2},
  {"id":"s_work_hdnk_41_3","chapterId":"ch_work_hdnk_41","text":"少陽令人腰痛，如以針刺其皮中，循循然不可以俛仰，不可以顧。刺少陽成骨之端出血，成骨在膝外廉之骨獨起者，夏無出血。","sortOrder":3},
  {"id":"s_work_hdnk_41_4","chapterId":"ch_work_hdnk_41","text":"陽明令人腰痛，不可以顧，顧如有見者，善悲。刺陽明於〈骨行〉前三痏，上下和之出血，秋無見血。","sortOrder":4},
  {"id":"s_work_hdnk_41_5","chapterId":"ch_work_hdnk_41","text":"足少陰令人腰痛，痛引脊內廉。刺少陰於內踝上二痏。春無見血，出血太多，不可復也。","sortOrder":5},
  {"id":"s_work_hdnk_41_6","chapterId":"ch_work_hdnk_41","text":"厥陰之脈令人腰痛，腰中如張弓弩絃。刺厥陰之脈，在腨踵魚腹之外，循之累累然，乃刺之。其病令人善言默默然不慧，刺之三痏。","sortOrder":6},
  {"id":"s_work_hdnk_41_7","chapterId":"ch_work_hdnk_41","text":"解脈令人腰痛，痛引肩，目疏疏然，時遺溲。刺解脈在膝筋肉分間郄外廉之橫脈出血，血變而止。","sortOrder":7},
  {"id":"s_work_hdnk_41_8","chapterId":"ch_work_hdnk_41","text":"解脈令人腰痛如引帶，常如折腰狀，善恐。刺解脈在郄中結絡如黍米，刺之血射，以黑見赤血而已。","sortOrder":8},
  {"id":"s_work_hdnk_41_9","chapterId":"ch_work_hdnk_41","text":"同陰之脈令人腰痛，痛如小錘居其中，怫然腫。刺同陰之脈在外踝上絕骨之端，為三痏。","sortOrder":9},
  {"id":"s_work_hdnk_41_10","chapterId":"ch_work_hdnk_41","text":"陽維之脈令人腰痛，痛上怫然腫。刺陽維之脈，脈與太陽合端下間，去地一尺所。","sortOrder":10},
  {"id":"s_work_hdnk_41_11","chapterId":"ch_work_hdnk_41","text":"衡絡之脈，令人腰痛，不可以俛仰，仰則恐仆，得之舉重傷腰，衡絡絕，惡血歸之。刺之在郄陽筋之間，上郄數寸，衡居為二痏出血。","sortOrder":11},
  {"id":"s_work_hdnk_41_12","chapterId":"ch_work_hdnk_41","text":"會陰之脈，令人腰痛，痛上漯漯然汗出。汗乾令人欲飲，飲已欲走。刺直腸之脈上三痏，在蹻上郄下五寸橫居，視其盛者出血。","sortOrder":12},
  {"id":"s_work_hdnk_41_13","chapterId":"ch_work_hdnk_41","text":"飛陽之脈令人腰痛，痛上怫怫然，甚則悲以恐，刺飛陽之脈，在內踝上五寸，少陽之前與陰維之會。","sortOrder":13},
  {"id":"s_work_hdnk_41_14","chapterId":"ch_work_hdnk_41","text":"昌陽之脈令人腰痛，痛引膺，目〈流，氵改目〉〈流，氵改目〉然，甚則反折，舌卷不能言。刺內筋為二痏。在內踝上大筋前太陰後，上踝二寸所。","sortOrder":14},
  {"id":"s_work_hdnk_41_15","chapterId":"ch_work_hdnk_41","text":"散脈令人腰痛而熱，熱甚生煩，腰下如有橫木居其中，甚則遺溲。刺散脈在膝前骨肉分間，絡外廉，束脈為三痏。","sortOrder":15},
  {"id":"s_work_hdnk_41_16","chapterId":"ch_work_hdnk_41","text":"肉裏之脈令人腰痛，不可以咳，咳則筋縮急。刺肉裏之脈，為二痏，在太陽之外，少陽絕骨之後。","sortOrder":16},
  {"id":"s_work_hdnk_41_17","chapterId":"ch_work_hdnk_41","text":"腰痛挾脊而痛至頭，幾幾然，目〈流，氵改目〉〈流，氵改目〉然僵仆，刺足太陽郄中出血。","sortOrder":17},
  {"id":"s_work_hdnk_41_18","chapterId":"ch_work_hdnk_41","text":"腰痛上寒，刺足太陽陽明；上熱刺足厥陰；不可以俛仰，刺足少陽；中熱而喘，刺足少陰，刺郄中出血。","sortOrder":18},
  {"id":"s_work_hdnk_41_19","chapterId":"ch_work_hdnk_41","text":"腰痛上寒不可顧，刺足陽明；上熱刺足太陰；中熱而喘，刺足少陰。","sortOrder":19},
  {"id":"s_work_hdnk_41_20","chapterId":"ch_work_hdnk_41","text":"大便難，刺足少陰；少腹滿，刺足厥陰。如折不可以俛仰，不可舉，刺足太陽；引脊內廉，刺足少陰。","sortOrder":20},
  {"id":"s_work_hdnk_41_21","chapterId":"ch_work_hdnk_41","text":"腰痛引少腹控〈月少〉，不可以仰；刺腰尻交者，兩髁胛上，以月生死為痏數，發針立已，左取右，右取左。","sortOrder":21},
  {"id":"s_work_hdnk_42_1","chapterId":"ch_work_hdnk_42","text":"風論篇第四十二","sortOrder":1},
  {"id":"s_work_hdnk_42_2","chapterId":"ch_work_hdnk_42","text":"黃帝問曰：風之傷人也，或為寒熱，或為熱中，或為寒中，或為癘風，或為偏枯，或為風也，其病各異，其名不同。或內至五臟六腑，不知其解，願聞其說。","sortOrder":2},
  {"id":"s_work_hdnk_42_3","chapterId":"ch_work_hdnk_42","text":"岐伯對曰：風氣藏在皮膚之間，內不得通，外不得泄。","sortOrder":3},
  {"id":"s_work_hdnk_42_4","chapterId":"ch_work_hdnk_42","text":"風者，善行而數變，腠理開，則洒然寒，閉則熱而悶。其寒也，則衰食飲；其熱也，則消肌肉。故使人怢栗而不能食，名曰寒熱。","sortOrder":4},
  {"id":"s_work_hdnk_42_5","chapterId":"ch_work_hdnk_42","text":"風氣與陽明入胃，循脈而上至目內眥，其人肥，則風氣不得外泄，則為熱中而目黃；人瘦則外泄而寒，則為寒中而泣出。","sortOrder":5},
  {"id":"s_work_hdnk_42_6","chapterId":"ch_work_hdnk_42","text":"風氣與太陽俱入，行諸脈俞，散於分肉之間，與衛氣相幹，其道不利。故使肌肉憤〈月真〉而有瘍，衛氣有所凝而不行，故其肉有不仁也。","sortOrder":6},
  {"id":"s_work_hdnk_42_7","chapterId":"ch_work_hdnk_42","text":"癘者，有榮氣熱腑，其氣不清，故使其鼻柱壞而色敗，皮膚瘍潰。風寒客於脈而不去，名曰癘風，或名曰寒熱。","sortOrder":7},
  {"id":"s_work_hdnk_42_8","chapterId":"ch_work_hdnk_42","text":"以春甲乙傷於風者為肝風，以夏丙丁傷於風者為心風，以季夏戊己傷於邪者為脾風，以秋庚辛中於邪者為肺風，以冬壬癸中於邪者為腎風。","sortOrder":8},
  {"id":"s_work_hdnk_42_9","chapterId":"ch_work_hdnk_42","text":"風中五臟六腑之俞，亦為臟腑之風，各入其門戶，所中則為偏風。","sortOrder":9},
  {"id":"s_work_hdnk_42_10","chapterId":"ch_work_hdnk_42","text":"風氣循風府而上，則為胸風，風入系頭，則為目風，眼寒。","sortOrder":10},
  {"id":"s_work_hdnk_42_11","chapterId":"ch_work_hdnk_42","text":"飲酒中風，則為漏風。","sortOrder":11},
  {"id":"s_work_hdnk_42_12","chapterId":"ch_work_hdnk_42","text":"入房汗出中風，則為內風。","sortOrder":12},
  {"id":"s_work_hdnk_42_13","chapterId":"ch_work_hdnk_42","text":"新沐中風，則為首風。","sortOrder":13},
  {"id":"s_work_hdnk_42_14","chapterId":"ch_work_hdnk_42","text":"久風入中，則為腸風，飧泄。","sortOrder":14},
  {"id":"s_work_hdnk_42_15","chapterId":"ch_work_hdnk_42","text":"外在腠理，則為泄風。","sortOrder":15},
  {"id":"s_work_hdnk_42_16","chapterId":"ch_work_hdnk_42","text":"故風者，百病之長也，至其變化，乃為他病也，無常方，然致有風氣也。","sortOrder":16},
  {"id":"s_work_hdnk_42_17","chapterId":"ch_work_hdnk_42","text":"帝曰：五臟風之形狀不同者何？願聞其診，及其病能。","sortOrder":17},
  {"id":"s_work_hdnk_42_18","chapterId":"ch_work_hdnk_42","text":"岐伯曰：肺風之狀，多汗惡風，色皏然白，時咳短氣，晝日則差，暮則甚，診在眉上，其色白。","sortOrder":18},
  {"id":"s_work_hdnk_42_19","chapterId":"ch_work_hdnk_42","text":"心風之狀，多汗惡風，焦絕善怒嚇，赤色，病甚則言不可快，診在口，其色赤。","sortOrder":19},
  {"id":"s_work_hdnk_42_20","chapterId":"ch_work_hdnk_42","text":"肝風之狀，多汗惡風，善悲，色微蒼，噎乾善怒，時憎女子，診在目下，其色青。","sortOrder":20},
  {"id":"s_work_hdnk_42_21","chapterId":"ch_work_hdnk_42","text":"脾風之狀，多汗惡風，身體怠墮，四支不欲動，色薄微黃，不嗜食，診在鼻上，其色黃。","sortOrder":21},
  {"id":"s_work_hdnk_42_22","chapterId":"ch_work_hdnk_42","text":"腎風之狀，多汗惡風，面龐然浮腫，脊痛不能正立，其色炲，隱曲不利，診在肌上，其色黑。","sortOrder":22},
  {"id":"s_work_hdnk_42_23","chapterId":"ch_work_hdnk_42","text":"胃風之狀，頸多汗，惡風，食飲不下，膈塞不通，腹善脹，失衣則〈月真〉脹，食寒則泄，診形瘦而腹大。","sortOrder":23},
  {"id":"s_work_hdnk_42_24","chapterId":"ch_work_hdnk_42","text":"首風之狀，頭面多汗，惡風、當先風一日，則病甚，頭痛不可以出內，至其風日，則病少愈。","sortOrder":24},
  {"id":"s_work_hdnk_42_25","chapterId":"ch_work_hdnk_42","text":"漏風之狀，或多汗，常不可單衣，食則汗出，甚則身汗，喘息惡風，衣常濡，口乾善渴，不能勞事。","sortOrder":25},
  {"id":"s_work_hdnk_42_26","chapterId":"ch_work_hdnk_42","text":"泄風之狀，多汗，汗出泄衣上，口中乾，上漬其風，不能勞事，身體盡痛，則寒。帝曰：善。","sortOrder":26},
  {"id":"s_work_hdnk_43_1","chapterId":"ch_work_hdnk_43","text":"痺論篇第四十三","sortOrder":1},
  {"id":"s_work_hdnk_43_2","chapterId":"ch_work_hdnk_43","text":"黃帝問曰：痺之安生？岐伯對曰：風寒濕三氣雜至合而為痺也。","sortOrder":2},
  {"id":"s_work_hdnk_43_3","chapterId":"ch_work_hdnk_43","text":"其風氣勝者為行痺，寒氣勝者為痛痺，濕氣勝者為著痺也。","sortOrder":3},
  {"id":"s_work_hdnk_43_4","chapterId":"ch_work_hdnk_43","text":"帝曰：其有五者何也？岐伯曰：以冬遇此者為骨痺，以春遇此者為筋痺；以夏遇此者為脈痺；以至陰遇此著為筋痺；以秋遇此者為皮痺。","sortOrder":4},
  {"id":"s_work_hdnk_43_5","chapterId":"ch_work_hdnk_43","text":"帝曰：內舍五臟六腑，何氣使然？岐伯曰：五臟皆有合，病久而不去者，內舍於其合也。故骨痺不已，復感於邪，內會於腎；筋痺不已，復感於邪，內會於肝；脈痺不已，復感於邪，內會於心；肌痺不已，復感於邪，內舍於脾；皮痺不已，復感於邪，內舍於肺；所謂痺者，各以其時重感於風寒濕之氣也。","sortOrder":5},
  {"id":"s_work_hdnk_43_6","chapterId":"ch_work_hdnk_43","text":"凡痺之客五臟者，肺痺者，煩滿喘而嘔。","sortOrder":6},
  {"id":"s_work_hdnk_43_7","chapterId":"ch_work_hdnk_43","text":"心痺者，脈不通，煩則心下鼓，暴上氣而喘，噎乾善噫，厥氣上則恐。","sortOrder":7},
  {"id":"s_work_hdnk_43_8","chapterId":"ch_work_hdnk_43","text":"肝痺者，夜臥則驚，多飲，數小便，上為引如懷。","sortOrder":8},
  {"id":"s_work_hdnk_43_9","chapterId":"ch_work_hdnk_43","text":"腎痺者，善脹，尻以代踵，脊以代頭。","sortOrder":9},
  {"id":"s_work_hdnk_43_10","chapterId":"ch_work_hdnk_43","text":"脾痺者，四支解墮，發咳嘔汁，上為大塞。","sortOrder":10},
  {"id":"s_work_hdnk_43_11","chapterId":"ch_work_hdnk_43","text":"腸痺者，數飲而出不得，中氣喘爭，時發飧泄。","sortOrder":11},
  {"id":"s_work_hdnk_43_12","chapterId":"ch_work_hdnk_43","text":"胞痺者，少腹膀胱按之內痛，若沃以湯，澀於小便，上為清涕。","sortOrder":12},
  {"id":"s_work_hdnk_43_13","chapterId":"ch_work_hdnk_43","text":"陰氣者，靜則神藏，躁則消亡。","sortOrder":13},
  {"id":"s_work_hdnk_43_14","chapterId":"ch_work_hdnk_43","text":"飲食自倍，腸胃乃傷。","sortOrder":14},
  {"id":"s_work_hdnk_43_15","chapterId":"ch_work_hdnk_43","text":"淫氣喘息，痺聚在肺；淫氣憂思，痺聚在心；淫氣遺溺，痺聚在腎；淫氣乏竭，痺聚在肝；淫氣肌絕，痺聚在脾。諸痺不已，亦益內也。其風氣勝者，其人易已也。","sortOrder":15},
  {"id":"s_work_hdnk_43_16","chapterId":"ch_work_hdnk_43","text":"帝曰：痺，其時有死者，或疼久者，或易已者，其何故也？岐伯曰：其入臟者死，其留連筋骨問者疼久，其留皮膚間者易已。","sortOrder":16},
  {"id":"s_work_hdnk_43_17","chapterId":"ch_work_hdnk_43","text":"帝曰：其客於六腑者何也？岐伯曰：此亦其食飲居處，為其病本也。六腑亦各有俞，風寒濕氣中其俞，而食飲應之，循俞而入，各舍其腑也。","sortOrder":17},
  {"id":"s_work_hdnk_43_18","chapterId":"ch_work_hdnk_43","text":"帝曰：以針治之奈何？岐伯曰：五臟有俞，六腑有合，循脈之分，各有所發，各隨其過，則病瘳也。","sortOrder":18},
  {"id":"s_work_hdnk_43_19","chapterId":"ch_work_hdnk_43","text":"帝曰：榮衛之氣，亦令人痺乎？岐伯曰：榮者水穀之精氣也，和調於五臟，洒陳於六腑，乃能入於脈也。故循脈上下貫五臟，絡六腑也。衛者水穀之悍氣也。其氣慓疾滑利，不能入於脈也。故循皮膚之中，分肉之間，熏於肓膜，散於胸腹，逆其氣則病，從其氣則癒，不與風寒濕氣合，故不為痺。","sortOrder":19},
  {"id":"s_work_hdnk_43_20","chapterId":"ch_work_hdnk_43","text":"帝曰：善。痺或痛、或不仁、或寒、或熱、或燥、或濕，其故何也？","sortOrder":20},
  {"id":"s_work_hdnk_43_21","chapterId":"ch_work_hdnk_43","text":"岐伯曰：痛者寒氣多也，有寒故痛也。","sortOrder":21},
  {"id":"s_work_hdnk_43_22","chapterId":"ch_work_hdnk_43","text":"其不痛不仁者，病久入深，榮衛之行澀，經絡時疏，故不通，皮膚不營，故為不仁。","sortOrder":22},
  {"id":"s_work_hdnk_43_23","chapterId":"ch_work_hdnk_43","text":"其寒者，陽氣少，陰氣多，與病相益，故寒也。","sortOrder":23},
  {"id":"s_work_hdnk_43_24","chapterId":"ch_work_hdnk_43","text":"其熱者，陽氣多，陰氣少，病氣勝，陽遭陰，故為痺熱。","sortOrder":24},
  {"id":"s_work_hdnk_43_25","chapterId":"ch_work_hdnk_43","text":"其多汗而濡者，此其逢濕甚也。陽氣少，陰氣盛，兩氣相盛，故汗出而濡也。","sortOrder":25},
  {"id":"s_work_hdnk_43_26","chapterId":"ch_work_hdnk_43","text":"帝曰：夫痺之為病，不痛何也？岐伯曰：痺在於骨則重；在於脈則血凝而不流；在於筋則屈不伸；在於肉則不仁；在於皮則寒。故具此五者，則不痛也。","sortOrder":26},
  {"id":"s_work_hdnk_43_27","chapterId":"ch_work_hdnk_43","text":"凡痺之類，逢寒則蟲，逢熱則縱。帝曰：善。","sortOrder":27},
  {"id":"s_work_hdnk_44_1","chapterId":"ch_work_hdnk_44","text":"痿論篇第四十四","sortOrder":1},
  {"id":"s_work_hdnk_44_2","chapterId":"ch_work_hdnk_44","text":"黃帝問曰：五臟使人痿何也？","sortOrder":2},
  {"id":"s_work_hdnk_44_3","chapterId":"ch_work_hdnk_44","text":"岐伯對曰：肺主身之皮毛，心主身之血脈，肝主身之筋膜，脾主身之肌肉，腎主身之骨髓。","sortOrder":3},
  {"id":"s_work_hdnk_44_4","chapterId":"ch_work_hdnk_44","text":"故肺熱葉焦，則皮毛虛弱，急薄，著則生痿躄也。","sortOrder":4},
  {"id":"s_work_hdnk_44_5","chapterId":"ch_work_hdnk_44","text":"心氣熱，則下脈厥而上，上則下脈虛，虛則生脈痿，樞析挈，脛縱而不任地也。","sortOrder":5},
  {"id":"s_work_hdnk_44_6","chapterId":"ch_work_hdnk_44","text":"肝氣熱，則膽泄口苦，筋膜幹，筋膜幹則筋急而攣，發為筋痿。","sortOrder":6},
  {"id":"s_work_hdnk_44_7","chapterId":"ch_work_hdnk_44","text":"脾氣熱，則胃乾而渴，肌肉不仁，發為肉痿。","sortOrder":7},
  {"id":"s_work_hdnk_44_8","chapterId":"ch_work_hdnk_44","text":"腎氣熱，則腰脊不舉，骨枯而髓減，發為骨痿。","sortOrder":8},
  {"id":"s_work_hdnk_44_9","chapterId":"ch_work_hdnk_44","text":"帝曰：何以得之？岐伯曰：肺者臟之長也，為心之蓋也，有所失亡，所求不得，則發肺嗚，嗚則肺熱葉焦，故曰：五臟因肺熱葉焦，發為痿躄，此之謂也。","sortOrder":9},
  {"id":"s_work_hdnk_44_10","chapterId":"ch_work_hdnk_44","text":"悲哀太甚，則胞絡絕，胞絡絕，則陽氣內動，發則心下崩數溲血也。故本病曰：大經空虛，發為肌痺，傳為脈痿。","sortOrder":10},
  {"id":"s_work_hdnk_44_11","chapterId":"ch_work_hdnk_44","text":"思想無窮，所願不得，意淫於外，入房太甚，宗筋弛縱，發為筋痿，及為白淫。故下經曰：筋痿者生於肝使內也。","sortOrder":11},
  {"id":"s_work_hdnk_44_12","chapterId":"ch_work_hdnk_44","text":"有漸於濕，以水為事，若有所留，居處相濕，肌肉濡漬，痺而不仁，發為肉痿。故下經曰：肉痿者，得之濕地也。","sortOrder":12},
  {"id":"s_work_hdnk_44_13","chapterId":"ch_work_hdnk_44","text":"有所遠行勞倦，逢大熱而渴，渴則陽氣內伐，內伐則熱合於腎，腎者水臟也；今水不勝火，則骨枯而髓虛。故足不任身，發為骨痿。故下經曰：骨痿者，生於大熱也。","sortOrder":13},
  {"id":"s_work_hdnk_44_14","chapterId":"ch_work_hdnk_44","text":"帝曰：何以別之？岐伯曰：肺熱者色白而毛敗；心熱者色赤而絡脈溢；肝熱者色蒼而爪枯；脾熱者色黃而肉蠕動；腎熱者色黑而齒槁。","sortOrder":14},
  {"id":"s_work_hdnk_44_15","chapterId":"ch_work_hdnk_44","text":"帝曰：如夫子言可矣。論言治痿者，獨取陽明何也？","sortOrder":15},
  {"id":"s_work_hdnk_44_16","chapterId":"ch_work_hdnk_44","text":"岐伯曰：陽明者五臟六腑之海，主潤宗筋，宗筋主束骨而利機關也。沖脈者，經脈之海也，主滲灌溪穀，與陽明合於宗筋，陰陽揔宗筋之會，合於氣街，而陽明為之長，皆屬於帶脈，而絡於督脈。故陽明虛，則宗筋縱，帶脈不引，故足痿不用也。","sortOrder":16},
  {"id":"s_work_hdnk_44_17","chapterId":"ch_work_hdnk_44","text":"帝曰：治之奈何？岐伯曰：各補其滎而通其俞，調其虛實，和其逆順，筋脈骨肉，各以其時受月，則病已矣。帝曰：善。","sortOrder":17},
  {"id":"s_work_hdnk_45_1","chapterId":"ch_work_hdnk_45","text":"厥論篇第四十五","sortOrder":1},
  {"id":"s_work_hdnk_45_2","chapterId":"ch_work_hdnk_45","text":"黃帝問曰：厥之寒熱者，何也？岐伯對曰：陽氣衰於下則為寒厥，陰氣衰於下則為熱厥。","sortOrder":2},
  {"id":"s_work_hdnk_45_3","chapterId":"ch_work_hdnk_45","text":"帝曰：熱厥之為熱也，必數於足下者何也？岐伯曰：陽氣起於足五指之表。陰脈者，集於足下而聚於足心，故陽氣勝則足下熱也。","sortOrder":3},
  {"id":"s_work_hdnk_45_4","chapterId":"ch_work_hdnk_45","text":"帝曰：寒厥之為寒也，必從五指而上於膝者，何也？岐伯曰：陰氣起於足五指之裏，集於膝下而聚於膝上故陰氣勝，則從五趾至膝上寒，其寒也不從外，皆從內，故陰氣勝，則從五趾至膝上寒，其寒也不從外，皆從內。","sortOrder":4},
  {"id":"s_work_hdnk_45_5","chapterId":"ch_work_hdnk_45","text":"帝曰：寒厥何失而然也？岐伯曰：前陰者，宗筋之所聚，太陰陽明之所合也。春夏則陽氣多而陰氣少，然冬則陰氣盛而陽氣衰；此人者質壯，以秋冬奪於所用，下氣上爭，不能復，精氣溢下，邪氣因從之而上也。氣因於中，陽氣衰，不能滲營其經絡，陽氣日損，陰氣獨在，故手足為之寒也。","sortOrder":5},
  {"id":"s_work_hdnk_45_6","chapterId":"ch_work_hdnk_45","text":"帝曰：熱厥何如而然也？岐伯曰：酒入於胃，則絡脈滿而經脈虛，脾主為胃行其津液者也。陰氣虛則陽氣入，陽氣入則胃不和，胃不和，則精氣竭，精氣竭，則不營其四肢也。此人必數醉若飽，以入房，氣聚於脾中不得散，酒氣與穀氣相薄，熱盛於中，故熱遍於身，內熱而溺赤也。夫酒氣盛而慓悍，腎氣有衰，陽氣獨勝，故手足為之熱也。","sortOrder":6},
  {"id":"s_work_hdnk_45_7","chapterId":"ch_work_hdnk_45","text":"帝曰：厥或令人腹滿，或令人暴不和人，或至半日遠至一日，乃知人者何也？岐伯曰：陰氣盛於上則下虛，下虛則腹脹滿，陽氣盛於上，則下氣重上，而邪氣逆，逆則陽氣亂，陽氣亂，則不知人也。","sortOrder":7},
  {"id":"s_work_hdnk_45_8","chapterId":"ch_work_hdnk_45","text":"帝曰：善。願聞六經脈之厥狀病能也。岐伯曰：巨陽之厥，則腫有頭重，足不能行，發為眴仆。","sortOrder":8},
  {"id":"s_work_hdnk_45_9","chapterId":"ch_work_hdnk_45","text":"陽明之厥，則癲疾欲走呼，腹滿不得臥，面赤而熱，妄見而妄言。","sortOrder":9},
  {"id":"s_work_hdnk_45_10","chapterId":"ch_work_hdnk_45","text":"少陽之厥，則暴聾頰腫而熱，脅痛，〈骨行〉不可以運。","sortOrder":10},
  {"id":"s_work_hdnk_45_11","chapterId":"ch_work_hdnk_45","text":"太陰之厥，則腹滿〈月真〉脹，後不利，不欲食，食則嘔，不得臥。","sortOrder":11},
  {"id":"s_work_hdnk_45_12","chapterId":"ch_work_hdnk_45","text":"少陰之厥，則口乾溺赤，腹滿心痛。","sortOrder":12},
  {"id":"s_work_hdnk_45_13","chapterId":"ch_work_hdnk_45","text":"厥陰之厥，則少腹腫痛，腹痛，涇溲不利，好臥，屈膝、陰縮腫，〈骨行〉內熱。","sortOrder":13},
  {"id":"s_work_hdnk_45_14","chapterId":"ch_work_hdnk_45","text":"盛則瀉之；虛則補之；不盛不虛，以經取之。","sortOrder":14},
  {"id":"s_work_hdnk_45_15","chapterId":"ch_work_hdnk_45","text":"太陰厥逆，〈骨行〉急攣，心痛引腹，治主病者。","sortOrder":15},
  {"id":"s_work_hdnk_45_16","chapterId":"ch_work_hdnk_45","text":"少陰厥逆，虛滿嘔變，下泄清，治主病者。","sortOrder":16},
  {"id":"s_work_hdnk_45_17","chapterId":"ch_work_hdnk_45","text":"厥陰厥逆，攣腰痛虛滿，前閉譫言，治主病者。","sortOrder":17},
  {"id":"s_work_hdnk_45_18","chapterId":"ch_work_hdnk_45","text":"三陰俱逆，不得前後，使人手足寒，三日死。","sortOrder":18},
  {"id":"s_work_hdnk_45_19","chapterId":"ch_work_hdnk_45","text":"太陽厥逆，僵仆、嘔血、善衄、治主病者。","sortOrder":19},
  {"id":"s_work_hdnk_45_20","chapterId":"ch_work_hdnk_45","text":"少陽厥逆，機關不利，機關不利者，腰不可以行，項不可以顧，發腸癰不可治，驚者死。","sortOrder":20},
  {"id":"s_work_hdnk_45_21","chapterId":"ch_work_hdnk_45","text":"陽明厥逆，喘咳身熱，善驚、衄、嘔血。","sortOrder":21},
  {"id":"s_work_hdnk_45_22","chapterId":"ch_work_hdnk_45","text":"手太陰厥逆，虛滿而咳，善嘔沫，治主病者。","sortOrder":22},
  {"id":"s_work_hdnk_45_23","chapterId":"ch_work_hdnk_45","text":"手心主少陰厥逆，心痛引喉，身熱死，不可治。","sortOrder":23},
  {"id":"s_work_hdnk_45_24","chapterId":"ch_work_hdnk_45","text":"手太陽厥逆，耳聾泣出，項不可以顧，腰不可以俛仰。治主病者。","sortOrder":24},
  {"id":"s_work_hdnk_45_25","chapterId":"ch_work_hdnk_45","text":"手陽明少陽厥逆，發喉痺、噎腫、痙、治主病者。","sortOrder":25},
  {"id":"s_work_hdnk_46_1","chapterId":"ch_work_hdnk_46","text":"病能論篇第四十六","sortOrder":1},
  {"id":"s_work_hdnk_46_2","chapterId":"ch_work_hdnk_46","text":"黃帝問曰：人病胃脘癰者，診當何如？岐伯對曰：診此者，當候胃脈，其脈當沉細，沉細者氣逆，逆者，人迎甚盛，甚盛則熱；人迎者，胃脈也，逆而盛，則熱聚於胃口而不行，故胃胱為癰也。","sortOrder":2},
  {"id":"s_work_hdnk_46_3","chapterId":"ch_work_hdnk_46","text":"帝曰：善。人有臥而有所不安者，何也？岐伯曰：臟有所傷，及精有所之寄則安，故人不能懸其病也。","sortOrder":3},
  {"id":"s_work_hdnk_46_4","chapterId":"ch_work_hdnk_46","text":"帝曰：人之不得偃臥者，何也？岐伯曰：肺者臟之蓋也，肺氣盛則脈大，脈大則不得偃臥，論在奇恒陰陽中。","sortOrder":4},
  {"id":"s_work_hdnk_46_5","chapterId":"ch_work_hdnk_46","text":"帝曰：有病厥者，診右脈沉而緊，左脈浮而遲，不然病主安在？岐伯曰：冬診之，右脈固為沉緊，此應四時，左脈浮而遲，此逆四時，在左當主病在腎，頗關在肺，當腰痛也。","sortOrder":5},
  {"id":"s_work_hdnk_46_6","chapterId":"ch_work_hdnk_46","text":"帝曰：何以言之？岐伯曰：少陰脈貫腎絡肺，今得肺脈，腎為之病，故腎為腰痛之病也。","sortOrder":6},
  {"id":"s_work_hdnk_46_7","chapterId":"ch_work_hdnk_46","text":"帝曰：善。有病頸癰者，或石治之，或針灸治之，而皆已。其真安在？岐伯曰：此同名異等者也。夫癰氣之息者，宜以針開除去之。夫氣盛血聚者，宜石而瀉之，此所謂同病異治也。","sortOrder":7},
  {"id":"s_work_hdnk_46_8","chapterId":"ch_work_hdnk_46","text":"帝曰：有病怒狂者，此病安生？岐伯曰：生於陽也。帝曰：陽何以使人狂？岐伯曰：陽氣者，因暴折而難決，故善怒也，病名曰陽厥。帝曰：何以知之？岐伯曰：陽明者常動，巨陽少陽不動，不動而動，大疾，此其候也。帝曰：治之奈何？岐伯曰：奪其食即已。夫食入於陰，長氣於陽，故奪其食即已。使之服以生鐵絡為飲，夫生鐵絡者，下氣疾也。","sortOrder":8},
  {"id":"s_work_hdnk_46_9","chapterId":"ch_work_hdnk_46","text":"帝曰：善。有病身熱解墮，汗出如浴。惡風少氣，此為何病？岐伯曰：病名曰酒風。帝曰：治之奈何？岐伯曰：以澤瀉，朮各十分，麋銜五分，合以三指撮為後飯。","sortOrder":9},
  {"id":"s_work_hdnk_46_10","chapterId":"ch_work_hdnk_46","text":"所謂深之細者，其中手如針也。摩之切之，聚者，堅也，博者，大也。","sortOrder":10},
  {"id":"s_work_hdnk_46_11","chapterId":"ch_work_hdnk_46","text":"上經者，言氣之通天也。下經者，言病之變化也。金匱者，決死生也。撥度者，切度之也。奇恒者，言奇病也。所謂奇者，使奇病不得以四時死也。恒者，得以四時死也。","sortOrder":11},
  {"id":"s_work_hdnk_46_12","chapterId":"ch_work_hdnk_46","text":"所謂揆者，方切求之也，言切求其脈理也。度者，得其病處，以四時度之也。","sortOrder":12},
  {"id":"s_work_hdnk_47_1","chapterId":"ch_work_hdnk_47","text":"奇病論篇第四十七","sortOrder":1},
  {"id":"s_work_hdnk_47_2","chapterId":"ch_work_hdnk_47","text":"黃帝問曰：人有重身，九月而喑，此為何也？岐伯對曰：胞之絡脈絕也。","sortOrder":2},
  {"id":"s_work_hdnk_47_3","chapterId":"ch_work_hdnk_47","text":"帝曰：何以言之？岐伯曰：胞絡者，系於腎，少陰之脈貫腎，系舌本，故不能言。","sortOrder":3},
  {"id":"s_work_hdnk_47_4","chapterId":"ch_work_hdnk_47","text":"帝曰：治之奈何？岐伯曰：無治也，當十月復。","sortOrder":4},
  {"id":"s_work_hdnk_47_5","chapterId":"ch_work_hdnk_47","text":"刺法曰：無損不足，益有餘，以成其疹。","sortOrder":5},
  {"id":"s_work_hdnk_47_6","chapterId":"ch_work_hdnk_47","text":"然後調之。","sortOrder":6},
  {"id":"s_work_hdnk_47_7","chapterId":"ch_work_hdnk_47","text":"所謂無損不足者，身贏瘦，無用鑱石也；無益其有餘者，腹中有形而泄之，泄之則精出而病獨擅中，故曰疹成也。","sortOrder":7},
  {"id":"s_work_hdnk_47_8","chapterId":"ch_work_hdnk_47","text":"帝曰：病脅下滿氣逆，二三歲不已，是為何病？岐伯曰：病名曰息積，此不妨於食，不可灸刺，積為導引服藥，藥不能獨治也。","sortOrder":8},
  {"id":"s_work_hdnk_47_9","chapterId":"ch_work_hdnk_47","text":"帝曰：人有身體髀股〈骨行〉皆腫，環臍而痛，是為何病？岐伯曰：病名曰伏梁，此風根也。其氣溢於大腸而著於肓，肓之原在臍下，故環臍而痛也。不可動之，動之為水溺澀之病也。","sortOrder":9},
  {"id":"s_work_hdnk_47_10","chapterId":"ch_work_hdnk_47","text":"帝曰：人有尺脈數甚，筋急而見，此為何病？岐伯曰：此所謂疹筋，是人腹必急，白色黑色見，則病甚。","sortOrder":10},
  {"id":"s_work_hdnk_47_11","chapterId":"ch_work_hdnk_47","text":"帝曰：人有病頭痛，以數歲不已，此安得之，名為何病？岐伯曰：當有所犯大寒，內至骨髓，髓者，以腦為主，腦逆，故令頭痛，齒亦痛，病名厥逆。帝曰：善。","sortOrder":11},
  {"id":"s_work_hdnk_47_12","chapterId":"ch_work_hdnk_47","text":"帝曰：有病口甘者，病名為何？何以得之？岐伯曰：此五氣之溢也，名曰脾痺。夫五味入口，藏於胃，脾為之行其精氣津液在脾，故令人口甘也，此肥美之所發也，此人必數食甘美而多肥也。肥者，令人內熱，甘者令人中滿，故其氣上溢，轉為消渴。治之以蘭，除陳氣也。","sortOrder":12},
  {"id":"s_work_hdnk_47_13","chapterId":"ch_work_hdnk_47","text":"帝曰：有病口苦，取陽陵泉。口苦者，病名為何？何以得之？岐伯曰：病名曰膽癉。夫肝者，中之將也，取決於膽，咽為之使，此人者數謀慮不決，故膽虛，氣上逆而口為之苦。治之以膽募俞，治在陰陽十二官相使中。","sortOrder":13},
  {"id":"s_work_hdnk_47_14","chapterId":"ch_work_hdnk_47","text":"帝曰：有癃者，一日數十溲，此不足也。身熱如炭，頸膺如格，人迎躁盛，喘息氣逆，此有餘也。太陰脈微細如發者，此不足也。其病安在？名為何病？岐伯曰：病在太陰，其盛在胃，頗在肺，病名曰厥，死不治。此所謂得五有餘，二不足也。","sortOrder":14},
  {"id":"s_work_hdnk_47_15","chapterId":"ch_work_hdnk_47","text":"帝曰：何謂五有餘？二不足？岐伯曰：所謂五有餘者，五病之氣有餘也，二不足者，亦病氣之不足也。今外得五有餘，內得二不足，此其身不表不裏，亦正死明矣！","sortOrder":15},
  {"id":"s_work_hdnk_47_16","chapterId":"ch_work_hdnk_47","text":"帝曰：人生而有病癲疾者，病名曰何？安所得之？岐伯曰：病名為胎病，此得之在母腹中時，其母有所大驚、氣上而不下，精氣並居，故令子發為癲疾也。","sortOrder":16},
  {"id":"s_work_hdnk_47_17","chapterId":"ch_work_hdnk_47","text":"帝曰：有病龐然有水狀，切其脈大緊，身無痛者，形不瘦，不能食，食少，名為何病？岐伯曰：病生在腎，名為腎風，腎風而不能食，善驚，驚已，心氣痿者死。帝曰：善。","sortOrder":17},
  {"id":"s_work_hdnk_48_1","chapterId":"ch_work_hdnk_48","text":"大奇論篇第四十八","sortOrder":1},
  {"id":"s_work_hdnk_48_2","chapterId":"ch_work_hdnk_48","text":"肝滿、腎滿、肺滿皆實，即為腫。","sortOrder":2},
  {"id":"s_work_hdnk_48_3","chapterId":"ch_work_hdnk_48","text":"肺之雍，喘而兩胠滿；肝雍兩胠滿，臥則驚，不得小便；腎雍腳下至少腹滿，脛有大小，髀〈骨行〉大，跛易偏枯。","sortOrder":3},
  {"id":"s_work_hdnk_48_4","chapterId":"ch_work_hdnk_48","text":"心脈滿大，癎瘈筋攣；肝脈小急，癎瘈筋攣；肝脈驚暴，有所驚駭，脈不至若暗，不治自己。","sortOrder":4},
  {"id":"s_work_hdnk_48_5","chapterId":"ch_work_hdnk_48","text":"腎脈小急，肝脈小急，心脈小急，不鼓皆為瘕。","sortOrder":5},
  {"id":"s_work_hdnk_48_6","chapterId":"ch_work_hdnk_48","text":"肝腎並沉為石水，並浮為風水，並虛為死，並小絃欲驚。","sortOrder":6},
  {"id":"s_work_hdnk_48_7","chapterId":"ch_work_hdnk_48","text":"腎脈大急沉，肝脈大急沉，皆為疝。","sortOrder":7},
  {"id":"s_work_hdnk_48_8","chapterId":"ch_work_hdnk_48","text":"心脈搏滑急為心疝。肺脈沉搏為肺疝。","sortOrder":8},
  {"id":"s_work_hdnk_48_9","chapterId":"ch_work_hdnk_48","text":"三陽急為瘕，三陰急為疝。二陰急為癎厥，二陽急為驚。","sortOrder":9},
  {"id":"s_work_hdnk_48_10","chapterId":"ch_work_hdnk_48","text":"脾脈外鼓沉為腸澼，久自已。肝脈小緩為腸澼，易治。腎脈小搏沉，為腸澼下血，血溫身熱者死。心肝澼亦下血，二臟同病者可治。其脈小沉澀為腸澼，其身熱者死，熱見七日死。","sortOrder":10},
  {"id":"s_work_hdnk_48_11","chapterId":"ch_work_hdnk_48","text":"胃脈沉鼓澀，胃外鼓大；心脈小堅急，皆膈偏枯。男子發左、女子發右，不暗舌轉可治，三十日起。其從者暗三歲起，年不滿二十者三歲死。","sortOrder":11},
  {"id":"s_work_hdnk_48_12","chapterId":"ch_work_hdnk_48","text":"脈至而搏，血衄身熱者死。脈來懸鉤浮為常脈。脈至如喘，名曰暴厥，暴厥者不知與人言。脈至如數，使人暴驚，三四日自已。","sortOrder":12},
  {"id":"s_work_hdnk_48_13","chapterId":"ch_work_hdnk_48","text":"脈至浮合，浮合如數，一息十至以上，是經氣予不足也，微見九十日死。","sortOrder":13},
  {"id":"s_work_hdnk_48_14","chapterId":"ch_work_hdnk_48","text":"脈至如火薪然，是心精之予奪也，草乾而死。","sortOrder":14},
  {"id":"s_work_hdnk_48_15","chapterId":"ch_work_hdnk_48","text":"脈至如散葉，是肝氣予虛也，木葉落而死。","sortOrder":15},
  {"id":"s_work_hdnk_48_16","chapterId":"ch_work_hdnk_48","text":"脈至如省客，省客者，脈寒而鼓，是腎氣予不足也，懸去棗華而死。","sortOrder":16},
  {"id":"s_work_hdnk_48_17","chapterId":"ch_work_hdnk_48","text":"脈至如丸泥，是胃精予不足也，榆莢落而死。","sortOrder":17},
  {"id":"s_work_hdnk_48_18","chapterId":"ch_work_hdnk_48","text":"脈至如橫格，是膽氣予不足也，禾熟而死。","sortOrder":18},
  {"id":"s_work_hdnk_48_19","chapterId":"ch_work_hdnk_48","text":"脈至如絃縷，是胞精予不足也，病善言，下霜而死，不言可治。","sortOrder":19},
  {"id":"s_work_hdnk_48_20","chapterId":"ch_work_hdnk_48","text":"脈至如交漆，交漆者，左右傍至也，微見三十日死。","sortOrder":20},
  {"id":"s_work_hdnk_48_21","chapterId":"ch_work_hdnk_48","text":"脈至如湧泉，浮鼓肌中，太陽氣予不足也。少氣味，韭英而死。","sortOrder":21},
  {"id":"s_work_hdnk_48_22","chapterId":"ch_work_hdnk_48","text":"脈至如頹土之狀，按之不得，是肌氣予不足也。五色先見黑，白壘發死。","sortOrder":22},
  {"id":"s_work_hdnk_48_23","chapterId":"ch_work_hdnk_48","text":"脈至如懸雍，懸雍者，浮揣切之益大，是十二俞之予不足也。水凝而死。","sortOrder":23},
  {"id":"s_work_hdnk_48_24","chapterId":"ch_work_hdnk_48","text":"脈至如偃刀，偃刀者，浮之小急，按之堅大急，五臟菀熱，寒熱獨並於腎也，如此其人不得坐，立春而死。","sortOrder":24},
  {"id":"s_work_hdnk_48_25","chapterId":"ch_work_hdnk_48","text":"脈至如丸滑，不直手，不直手者，按之不可得也。是大腸氣予不足也。棗葉生而死。","sortOrder":25},
  {"id":"s_work_hdnk_48_26","chapterId":"ch_work_hdnk_48","text":"脈至如華者令人善恐，不欲坐臥，行立常聽，是小腸氣予不足也。季秋而死。","sortOrder":26},
  {"id":"s_work_hdnk_49_1","chapterId":"ch_work_hdnk_49","text":"脈解篇第四十九","sortOrder":1},
  {"id":"s_work_hdnk_49_2","chapterId":"ch_work_hdnk_49","text":"太陽所謂腫，腰脽痛者，正月太陽寅，寅太陽也。正月陽氣出，在上而陰氣盛，陽未得自次也，故腫，腰脽痛也。","sortOrder":2},
  {"id":"s_work_hdnk_49_3","chapterId":"ch_work_hdnk_49","text":"病偏虛為跛者，正月陽氣凍解，地氣而出也。所謂偏虛者，冬寒頗有不足者，故偏虛為跛也。","sortOrder":3},
  {"id":"s_work_hdnk_49_4","chapterId":"ch_work_hdnk_49","text":"所謂強上引背者，陽氣大上而爭，故強上也。","sortOrder":4},
  {"id":"s_work_hdnk_49_5","chapterId":"ch_work_hdnk_49","text":"所謂耳嗚者，陽氣萬物盛上而躍，故耳嗚也。","sortOrder":5},
  {"id":"s_work_hdnk_49_6","chapterId":"ch_work_hdnk_49","text":"所謂甚則狂巔疾者，陽盡在上而陰氣從下，下虛上實，故狂巔疾也。","sortOrder":6},
  {"id":"s_work_hdnk_49_7","chapterId":"ch_work_hdnk_49","text":"所謂浮為聾者，皆在氣也。","sortOrder":7},
  {"id":"s_work_hdnk_49_8","chapterId":"ch_work_hdnk_49","text":"所謂入中為喑者，陽盛已衰故為喑也。","sortOrder":8},
  {"id":"s_work_hdnk_49_9","chapterId":"ch_work_hdnk_49","text":"內奪而厥，則為喑俳，此腎虛也，少陰不至者厥也。","sortOrder":9},
  {"id":"s_work_hdnk_49_10","chapterId":"ch_work_hdnk_49","text":"少陽所謂心脅痛者，言少陽盛也。盛者心之所表也，九月陽氣盡而陰氣盛，故心脅痛也。","sortOrder":10},
  {"id":"s_work_hdnk_49_11","chapterId":"ch_work_hdnk_49","text":"所謂不可反側者，陰氣藏物也，物藏則不動，故不可反側也。","sortOrder":11},
  {"id":"s_work_hdnk_49_12","chapterId":"ch_work_hdnk_49","text":"所謂甚則躍者，九月萬物盡衰，草木華落而墮，則氣去陽而之陰，氣盛而陽之下長，故謂躍。","sortOrder":12},
  {"id":"s_work_hdnk_49_13","chapterId":"ch_work_hdnk_49","text":"陽明所謂洒洒振寒者，陽明者午也，五月盛陽之陰也，陽盛而陰氣加之，故洒洒振寒也。","sortOrder":13},
  {"id":"s_work_hdnk_49_14","chapterId":"ch_work_hdnk_49","text":"所謂脛腫而股不收者，是五月盛陽之陰也。陽者衰於五月，而一陰氣上，與陽始爭，故脛腫而股不收也。","sortOrder":14},
  {"id":"s_work_hdnk_49_15","chapterId":"ch_work_hdnk_49","text":"所謂上喘而為水者，陰氣下而復上，上則邪客於臟腑間，故為水也。","sortOrder":15},
  {"id":"s_work_hdnk_49_16","chapterId":"ch_work_hdnk_49","text":"所謂胸痛少氣者，水氣在臟腑也；水者陰氣也，陰氣在中，故胸痛少氣也。","sortOrder":16},
  {"id":"s_work_hdnk_49_17","chapterId":"ch_work_hdnk_49","text":"所謂甚則厥，惡人與火，聞木音則惕然而驚者，陽氣與陰氣相薄，水火相惡，故惕然而驚也。所謂欲獨閉戶牖而處者，陰陽相薄也，陽盡而陰盛，故欲獨閉戶牖而居。","sortOrder":17},
  {"id":"s_work_hdnk_49_18","chapterId":"ch_work_hdnk_49","text":"所謂病至則欲乘高而歌，棄衣而走者，陰陽復爭而外併於陽，故使之棄衣而走也。","sortOrder":18},
  {"id":"s_work_hdnk_49_19","chapterId":"ch_work_hdnk_49","text":"所謂客孫脈，則頭痛鼻鼽腹腫者，陽明併於上，上者則其孫絡太陰也，故頭痛鼻鼽腹腫也。","sortOrder":19},
  {"id":"s_work_hdnk_49_20","chapterId":"ch_work_hdnk_49","text":"太陰所謂病脹者，太陰子也，十一月萬物氣皆藏於中，故曰病脹。","sortOrder":20},
  {"id":"s_work_hdnk_49_21","chapterId":"ch_work_hdnk_49","text":"所謂上走心為噫者，陰盛而上走於陽明，陽明絡屬心，故曰上走心為噫也。","sortOrder":21},
  {"id":"s_work_hdnk_49_22","chapterId":"ch_work_hdnk_49","text":"所謂食則嘔者，物盛滿而上溢，故嘔也。","sortOrder":22},
  {"id":"s_work_hdnk_49_23","chapterId":"ch_work_hdnk_49","text":"所謂得後與氣則快然如衰者，十二月陰氣下衰而陽氣且出，故曰：得後與氣則快然如衰也。","sortOrder":23},
  {"id":"s_work_hdnk_50_1","chapterId":"ch_work_hdnk_50","text":"刺要論篇第五十","sortOrder":1},
  {"id":"s_work_hdnk_50_2","chapterId":"ch_work_hdnk_50","text":"黃帝問曰：願聞刺要？","sortOrder":2},
  {"id":"s_work_hdnk_50_3","chapterId":"ch_work_hdnk_50","text":"岐伯對曰：病有浮沉，刺有淺深，各至其理，無過其道，過之則內傷，不及則生外壅，壅則邪從之。淺深不得，反為大賊，內動五臟，後生大病。","sortOrder":3},
  {"id":"s_work_hdnk_50_4","chapterId":"ch_work_hdnk_50","text":"故曰：病有在毫毛腠理者，有在皮膚者，有在肌肉者，有在脈者，有在筋者，有在骨者，有在髓者。","sortOrder":4},
  {"id":"s_work_hdnk_50_5","chapterId":"ch_work_hdnk_50","text":"是故刺毫毛腠理無傷皮，皮傷則內動肺，肺動則秋病溫瘧，泝泝然寒慄。","sortOrder":5},
  {"id":"s_work_hdnk_50_6","chapterId":"ch_work_hdnk_50","text":"刺皮無傷肉，肉傷則內動脾，脾動則七十二日四季之月，病腹脹煩不嗜食。","sortOrder":6},
  {"id":"s_work_hdnk_50_7","chapterId":"ch_work_hdnk_50","text":"刺肉無傷脈，脈傷則內動心，心動則夏病心痛。","sortOrder":7},
  {"id":"s_work_hdnk_50_8","chapterId":"ch_work_hdnk_50","text":"刺脈無傷筋，筋傷則內動肝，肝動則春病熱而筋弛。","sortOrder":8},
  {"id":"s_work_hdnk_50_9","chapterId":"ch_work_hdnk_50","text":"刺筋無傷骨，骨傷則內動腎，腎動則冬病脹，腰痛。","sortOrder":9},
  {"id":"s_work_hdnk_50_10","chapterId":"ch_work_hdnk_50","text":"刺骨無傷髓，髓傷則銷鑠胻痠，體解〈亻亦〉然不去矣。","sortOrder":10},
  {"id":"s_work_hdnk_51_1","chapterId":"ch_work_hdnk_51","text":"刺齊論篇第五十一","sortOrder":1},
  {"id":"s_work_hdnk_51_2","chapterId":"ch_work_hdnk_51","text":"黃帝問曰：願聞刺淺深之分。岐伯對曰：刺骨者無傷筋，刺筋者勿傷肉，刺肉者無傷脈，刺脈者無傷皮，刺皮者無傷肉，刺肉者無傷筋，刺筋者無傷骨。","sortOrder":2},
  {"id":"s_work_hdnk_51_3","chapterId":"ch_work_hdnk_51","text":"帝曰：餘未知其所謂，願聞其解。岐伯曰：刺骨無傷筋者，針至筋而去，不及骨也。刺筋無傷肉者，至肉而去，不及筋也。刺肉無傷脈者，至脈而去，不及肉也。刺脈無傷皮者，至皮而去，不及脈也。所謂刺皮無傷肉者，病在皮中，針入皮中無傷肉也。刺肉無傷筋者，過肉中筋也，刺筋無傷骨者，過筋中骨也。此之謂反也。","sortOrder":3},
  {"id":"s_work_hdnk_52_1","chapterId":"ch_work_hdnk_52","text":"刺禁論篇第五十二","sortOrder":1},
  {"id":"s_work_hdnk_52_2","chapterId":"ch_work_hdnk_52","text":"黃帝問曰：願聞禁數？","sortOrder":2},
  {"id":"s_work_hdnk_52_3","chapterId":"ch_work_hdnk_52","text":"岐伯對曰：臟有要害，不可不察。肝生於左，肺藏於右，心部於表，腎治於衳，脾為之使，胃為之市。","sortOrder":3},
  {"id":"s_work_hdnk_52_4","chapterId":"ch_work_hdnk_52","text":"膈肓之上，中有父母，七節之傍，中有小心，從之有福，逆之有咎。","sortOrder":4},
  {"id":"s_work_hdnk_52_5","chapterId":"ch_work_hdnk_52","text":"刺中心，一日死。其動為噫。","sortOrder":5},
  {"id":"s_work_hdnk_52_6","chapterId":"ch_work_hdnk_52","text":"刺中肝，五日死。其動為語。","sortOrder":6},
  {"id":"s_work_hdnk_52_7","chapterId":"ch_work_hdnk_52","text":"刺中腎，六日死。其動為嚏。","sortOrder":7},
  {"id":"s_work_hdnk_52_8","chapterId":"ch_work_hdnk_52","text":"刺中肺，三日死。其動為咳。","sortOrder":8},
  {"id":"s_work_hdnk_52_9","chapterId":"ch_work_hdnk_52","text":"刺中脾，十日死。其動為吞。","sortOrder":9},
  {"id":"s_work_hdnk_52_10","chapterId":"ch_work_hdnk_52","text":"刺中膽，一日半死。其動為嘔。","sortOrder":10},
  {"id":"s_work_hdnk_52_11","chapterId":"ch_work_hdnk_52","text":"刺跗上中大脈血出不止死。","sortOrder":11},
  {"id":"s_work_hdnk_52_12","chapterId":"ch_work_hdnk_52","text":"刺面中溜脈，不幸為盲。","sortOrder":12},
  {"id":"s_work_hdnk_52_13","chapterId":"ch_work_hdnk_52","text":"刺頭中腦戶，入腦立死。","sortOrder":13},
  {"id":"s_work_hdnk_52_14","chapterId":"ch_work_hdnk_52","text":"刺舌下中脈太過，血出不止為喑。","sortOrder":14},
  {"id":"s_work_hdnk_52_15","chapterId":"ch_work_hdnk_52","text":"刺足下佈絡中脈，血不出為腫。","sortOrder":15},
  {"id":"s_work_hdnk_52_16","chapterId":"ch_work_hdnk_52","text":"刺郗中大脈，令人仆脫色。","sortOrder":16},
  {"id":"s_work_hdnk_52_17","chapterId":"ch_work_hdnk_52","text":"刺氣街中脈，血不出，為腫鼠仆。","sortOrder":17},
  {"id":"s_work_hdnk_52_18","chapterId":"ch_work_hdnk_52","text":"刺脊間中髓為傴。","sortOrder":18},
  {"id":"s_work_hdnk_52_19","chapterId":"ch_work_hdnk_52","text":"刺乳上，中乳房，為腫根蝕。","sortOrder":19},
  {"id":"s_work_hdnk_52_20","chapterId":"ch_work_hdnk_52","text":"刺缺盆中內陷氣泄，令人喘咳逆。","sortOrder":20},
  {"id":"s_work_hdnk_52_21","chapterId":"ch_work_hdnk_52","text":"刺手魚腹內陷為腫。","sortOrder":21},
  {"id":"s_work_hdnk_52_22","chapterId":"ch_work_hdnk_52","text":"無刺大醉，令人氣亂；無刺大怒，令人氣逆：無刺大勞人；無刺新飽人；無刺大飢人；無刺大渴人；無刺大驚人。","sortOrder":22},
  {"id":"s_work_hdnk_52_23","chapterId":"ch_work_hdnk_52","text":"刺陰股中大脈，血出不止，死。","sortOrder":23},
  {"id":"s_work_hdnk_52_24","chapterId":"ch_work_hdnk_52","text":"刺客主人內陷中脈，為內漏為聾。","sortOrder":24},
  {"id":"s_work_hdnk_52_25","chapterId":"ch_work_hdnk_52","text":"刺膝臏出液為跛。","sortOrder":25},
  {"id":"s_work_hdnk_52_26","chapterId":"ch_work_hdnk_52","text":"刺臂太陰脈，出血多，立死。","sortOrder":26},
  {"id":"s_work_hdnk_52_27","chapterId":"ch_work_hdnk_52","text":"刺足少陰脈，重虛出血，為舌難以言。","sortOrder":27},
  {"id":"s_work_hdnk_52_28","chapterId":"ch_work_hdnk_52","text":"刺膺中陷中，肺為喘逆仰息。","sortOrder":28},
  {"id":"s_work_hdnk_52_29","chapterId":"ch_work_hdnk_52","text":"刺肘中內陷氣歸之，為之不屈伸。","sortOrder":29},
  {"id":"s_work_hdnk_52_30","chapterId":"ch_work_hdnk_52","text":"刺陰股下三寸內陷，令人遺溺。","sortOrder":30},
  {"id":"s_work_hdnk_52_31","chapterId":"ch_work_hdnk_52","text":"刺腋下脅間內陷，令人咳。","sortOrder":31},
  {"id":"s_work_hdnk_52_32","chapterId":"ch_work_hdnk_52","text":"刺少腹中膀胱溺出，令人少腹滿。","sortOrder":32},
  {"id":"s_work_hdnk_52_33","chapterId":"ch_work_hdnk_52","text":"刺腨腸內陷為腫。","sortOrder":33},
  {"id":"s_work_hdnk_52_34","chapterId":"ch_work_hdnk_52","text":"刺眶上陷骨中脈，為漏為盲。","sortOrder":34},
  {"id":"s_work_hdnk_52_35","chapterId":"ch_work_hdnk_52","text":"刺關節中液出，不得屈伸。","sortOrder":35},
  {"id":"s_work_hdnk_53_1","chapterId":"ch_work_hdnk_53","text":"刺志論篇第五十三","sortOrder":1},
  {"id":"s_work_hdnk_53_2","chapterId":"ch_work_hdnk_53","text":"黃帝問曰：願聞虛實之要？岐伯對曰：氣實形實，氣虛形虛，此其常也，反此者病。穀盛氣盛，穀虛氣虛此其常也，反此者病。脈實血實，脈虛血虛，此其常也，反此者病。","sortOrder":2},
  {"id":"s_work_hdnk_53_3","chapterId":"ch_work_hdnk_53","text":"帝曰：如何而反？岐伯曰：氣虛身熱，此謂反也。穀入多而氣少，此謂反也。穀不入而氣多，此謂反也。脈盛血少，此謂反也。脈少血多，此謂反也。","sortOrder":3},
  {"id":"s_work_hdnk_53_4","chapterId":"ch_work_hdnk_53","text":"氣盛身寒，得之傷寒，氣虛身熱，得之傷暑。","sortOrder":4},
  {"id":"s_work_hdnk_53_5","chapterId":"ch_work_hdnk_53","text":"穀入多而氣少者，得之有所脫血，濕居下也。","sortOrder":5},
  {"id":"s_work_hdnk_53_6","chapterId":"ch_work_hdnk_53","text":"穀入少而氣多者，邪在胃及與肺也。","sortOrder":6},
  {"id":"s_work_hdnk_53_7","chapterId":"ch_work_hdnk_53","text":"脈小血多者，飲中熱也；脈大血少者，脈有風氣，水漿不入，此之謂也。","sortOrder":7},
  {"id":"s_work_hdnk_53_8","chapterId":"ch_work_hdnk_53","text":"夫實者，氣入也；虛者，氣出也。氣實者，熱也；氣虛者，寒也。","sortOrder":8},
  {"id":"s_work_hdnk_53_9","chapterId":"ch_work_hdnk_53","text":"入實者，左手開針空也；入虛者，左手閉針空也。","sortOrder":9},
  {"id":"s_work_hdnk_54_1","chapterId":"ch_work_hdnk_54","text":"鍼解篇第五十四","sortOrder":1},
  {"id":"s_work_hdnk_54_2","chapterId":"ch_work_hdnk_54","text":"黃帝問曰：願聞九針之解，虛實之道。岐伯對曰：刺虛則實之者，針下熱也。氣實乃熱也。滿而泄之者，針下寒也，氣虛乃寒也。菀陳則除之者，出惡血也。","sortOrder":2},
  {"id":"s_work_hdnk_54_3","chapterId":"ch_work_hdnk_54","text":"邪勝則虛之者，出針勿按。","sortOrder":3},
  {"id":"s_work_hdnk_54_4","chapterId":"ch_work_hdnk_54","text":"徐而疾則實者，徐出針而疾按之；疾而徐則虛者，疾出針而徐按之。","sortOrder":4},
  {"id":"s_work_hdnk_54_5","chapterId":"ch_work_hdnk_54","text":"言實與虛者，寒溫氣多少也。","sortOrder":5},
  {"id":"s_work_hdnk_54_6","chapterId":"ch_work_hdnk_54","text":"若無若有者，疾不可知也。","sortOrder":6},
  {"id":"s_work_hdnk_54_7","chapterId":"ch_work_hdnk_54","text":"察後與先者，知病先後也。","sortOrder":7},
  {"id":"s_work_hdnk_54_8","chapterId":"ch_work_hdnk_54","text":"為虛與實者，工勿失其法。若得若失者，離其法也。","sortOrder":8},
  {"id":"s_work_hdnk_54_9","chapterId":"ch_work_hdnk_54","text":"虛實之要，九針最妙者，為其各有所宜也。","sortOrder":9},
  {"id":"s_work_hdnk_54_10","chapterId":"ch_work_hdnk_54","text":"補瀉之時者，與氣開闔相合也。","sortOrder":10},
  {"id":"s_work_hdnk_54_11","chapterId":"ch_work_hdnk_54","text":"九針之名，各不同形者，針窮其所當補瀉也。","sortOrder":11},
  {"id":"s_work_hdnk_54_12","chapterId":"ch_work_hdnk_54","text":"刺實須其虛者留針，陰氣隆至，乃去針也；刺虛須其實者，陽氣隆至，針下熱，乃去針也。","sortOrder":12},
  {"id":"s_work_hdnk_54_13","chapterId":"ch_work_hdnk_54","text":"經氣已至，慎守勿失者，勿變更也。","sortOrder":13},
  {"id":"s_work_hdnk_54_14","chapterId":"ch_work_hdnk_54","text":"深淺在志者，知病之內外也。","sortOrder":14},
  {"id":"s_work_hdnk_54_15","chapterId":"ch_work_hdnk_54","text":"遠近如一者，深淺其候等也。","sortOrder":15},
  {"id":"s_work_hdnk_54_16","chapterId":"ch_work_hdnk_54","text":"如臨深淵者，不敢墮也。","sortOrder":16},
  {"id":"s_work_hdnk_54_17","chapterId":"ch_work_hdnk_54","text":"手如握虎者，欲其壯也。","sortOrder":17},
  {"id":"s_work_hdnk_54_18","chapterId":"ch_work_hdnk_54","text":"神無營於眾物者，靜志觀病人，無左右視也。","sortOrder":18},
  {"id":"s_work_hdnk_54_19","chapterId":"ch_work_hdnk_54","text":"義無邪下者，欲端以正也。","sortOrder":19},
  {"id":"s_work_hdnk_54_20","chapterId":"ch_work_hdnk_54","text":"必正其神者，欲膽病人目，製其神，令氣易行也。","sortOrder":20},
  {"id":"s_work_hdnk_54_21","chapterId":"ch_work_hdnk_54","text":"所謂三里者，下膝三寸也。所謂跗之者，舉膝分易見也。巨虛者，矯足〈骨行〉獨陷者。下廉者陷下者也。","sortOrder":21},
  {"id":"s_work_hdnk_54_22","chapterId":"ch_work_hdnk_54","text":"帝曰：餘聞九針上應天地四時陰陽，願聞其方，令可傳於後世以為常也。岐伯曰：夫一天、二地、三人、四時、五音、六律、七星、八風、九野，身形亦應之，針各有所宜，故曰九針。","sortOrder":22},
  {"id":"s_work_hdnk_54_23","chapterId":"ch_work_hdnk_54","text":"人皮應天，人肉應地，人脈應人，人筋應時，人聲應音，人陰陽合氣應律，人齒面目應星，人出入氣應風，人九竅三百六十五絡應野。","sortOrder":23},
  {"id":"s_work_hdnk_54_24","chapterId":"ch_work_hdnk_54","text":"故一針皮、二針肉、三針脈、四針筋、五針骨、六針調陰陽、七針益精、八針除風、九針通九竅、除三百六十五節氣。此之謂各有所主也。","sortOrder":24},
  {"id":"s_work_hdnk_54_25","chapterId":"ch_work_hdnk_54","text":"人心意應八風；人氣應天；人髮齒耳目五聲，應五音六律；人陰陽脈血氣應地。","sortOrder":25},
  {"id":"s_work_hdnk_54_26","chapterId":"ch_work_hdnk_54","text":"人肝目應之九竅三百六十五人一以觀動靜天二以候五色七星應之以候發母澤五音一以候宮商角徵羽六律有餘不足應之二地一以候高下有餘九野一節俞應之以候閉節三人變一分人候齒泄多血少十分角之變五分以候緩急六分不足三分寒關節第九分四時人寒溫燥濕四時一應之以候相反一四方各作解。","sortOrder":26},
  {"id":"s_work_hdnk_55_1","chapterId":"ch_work_hdnk_55","text":"長刺節論篇第五十五","sortOrder":1},
  {"id":"s_work_hdnk_55_2","chapterId":"ch_work_hdnk_55","text":"刺家不診，聽病者言，在頭頭疾痛，為藏針之。刺至骨病已，上無傷骨肉及皮，皮者道也。","sortOrder":2},
  {"id":"s_work_hdnk_55_3","chapterId":"ch_work_hdnk_55","text":"陰刺入一，傍四處，治寒熱。","sortOrder":3},
  {"id":"s_work_hdnk_55_4","chapterId":"ch_work_hdnk_55","text":"深專者刺大臟，迫臟刺背，背俞也。刺之迫臟，臟會，腹中寒熱去而止。與刺之要，發針而淺出血。","sortOrder":4},
  {"id":"s_work_hdnk_55_5","chapterId":"ch_work_hdnk_55","text":"治腐腫者，刺腐上，視癰小大深淺刺。刺大者多血，小者深之，必端內針為故止。","sortOrder":5},
  {"id":"s_work_hdnk_55_6","chapterId":"ch_work_hdnk_55","text":"病在少腹有積，刺皮膚以下，至少腹而止。刺俠脊兩旁四椎間，刺兩髂髎季脅肋間，導腹中氣熱下已。","sortOrder":6},
  {"id":"s_work_hdnk_55_7","chapterId":"ch_work_hdnk_55","text":"病在少腹，腹痛不得大小便，病名曰疝，得之寒。刺少腹兩股間，刺腰髁骨間，刺而多之，盡靈病已。","sortOrder":7},
  {"id":"s_work_hdnk_55_8","chapterId":"ch_work_hdnk_55","text":"病在筋，筋攣節痛，不可以行，名曰筋痺。刺筋上為故，刺分肉間，不可中骨也。病起筋靈病已止。","sortOrder":8},
  {"id":"s_work_hdnk_55_9","chapterId":"ch_work_hdnk_55","text":"病在肌膚，肌膚盡痛，名曰肌痺，傷於寒濕。刺大分小分，多發針而深之，以熱為故，無傷筋骨，傷筋骨，癰發若變。諸分盡熱病已止。","sortOrder":9},
  {"id":"s_work_hdnk_55_10","chapterId":"ch_work_hdnk_55","text":"病在骨，骨重不可舉，骨髓酸痛，寒氣至，名曰骨痺。深者刺無傷脈肉為故。其道大分小分，骨熱病已止。","sortOrder":10},
  {"id":"s_work_hdnk_55_11","chapterId":"ch_work_hdnk_55","text":"病在諸陽脈且寒且熱，諸分且寒且熱，名曰狂。刺之虛脈，視分盡熱病已止。","sortOrder":11},
  {"id":"s_work_hdnk_55_12","chapterId":"ch_work_hdnk_55","text":"病初發歲一發，不治月一發，不治月四五發，名曰癲病。刺諸分諸脈。其無寒者，以針調之病止。","sortOrder":12},
  {"id":"s_work_hdnk_55_13","chapterId":"ch_work_hdnk_55","text":"病風且寒且熱，靈汗出，一日數過，先刺諸分理絡脈，汗出且寒且熱，三日一刺，百日而已。","sortOrder":13},
  {"id":"s_work_hdnk_55_14","chapterId":"ch_work_hdnk_55","text":"病大風骨節重，鬚眉墮，名曰大風，刺肌肉為故。汗出百日，刺骨髓汗出百日，凡二百日鬚眉生而止針。","sortOrder":14},
  {"id":"s_work_hdnk_56_1","chapterId":"ch_work_hdnk_56","text":"皮部論篇第五十六","sortOrder":1},
  {"id":"s_work_hdnk_56_2","chapterId":"ch_work_hdnk_56","text":"黃帝問曰：餘聞皮有分部，脈有經紀，筋有結絡，骨有度量，其所生病各異。別其分部，左右上下，陰陽所在，病之始終，願聞其道。","sortOrder":2},
  {"id":"s_work_hdnk_56_3","chapterId":"ch_work_hdnk_56","text":"岐伯對曰：欲知皮部以經脈為紀者，諸經皆然。","sortOrder":3},
  {"id":"s_work_hdnk_56_4","chapterId":"ch_work_hdnk_56","text":"陽明之陽，名曰害蜚，上下同法，視其部中有浮絡者，皆陽明之絡也。其色多青則痛，多里則痺，黃赤則熱，多白則寒，五色皆見，則寒熱也。絡盛則入客於經。陽主外，陰主內。","sortOrder":4},
  {"id":"s_work_hdnk_56_5","chapterId":"ch_work_hdnk_56","text":"少陽之陽，名曰樞持。上下同法，視其部中，有浮絡者，皆少陽之絡也。絡盛則入客於經，故在陽者主內，在陰者主出，以滲於內，諸經皆然。","sortOrder":5},
  {"id":"s_work_hdnk_56_6","chapterId":"ch_work_hdnk_56","text":"太陽之陽，名曰關樞。上下同法，視其部中，有浮絡者，皆太陽之絡也。絡盛則入客於經。","sortOrder":6},
  {"id":"s_work_hdnk_56_7","chapterId":"ch_work_hdnk_56","text":"少陰之陰，名曰樞儒。上下同法，視其部中，有浮絡者，皆少陰之絡也。絡盛則入客於經，其入經也，從陽部註於經，其出者，從陰內註於骨。","sortOrder":7},
  {"id":"s_work_hdnk_56_8","chapterId":"ch_work_hdnk_56","text":"心主之陰，名曰害肩，上下同法，視其部中，有浮絡者，皆心主之絡也。絡盛則入客於經。","sortOrder":8},
  {"id":"s_work_hdnk_56_9","chapterId":"ch_work_hdnk_56","text":"太陰之陰，名曰關蟄。上下同法，視其部中，有浮絡者，皆太陰之絡也。絡盛則入客於經。","sortOrder":9},
  {"id":"s_work_hdnk_56_10","chapterId":"ch_work_hdnk_56","text":"凡十二經絡脈者，皮之部也。","sortOrder":10},
  {"id":"s_work_hdnk_56_11","chapterId":"ch_work_hdnk_56","text":"是故百病之始生也，必先於皮毛。邪中之，則腠理開，開則入客於絡脈，留而不去，傳入於經，留而不去，傳入於腑，廩於腸胃。","sortOrder":11},
  {"id":"s_work_hdnk_56_12","chapterId":"ch_work_hdnk_56","text":"邪之始入於皮也，泝然起毫毛，開腠理，其入於絡也，則絡脈盛色變；其入客於經也，則感虛，乃陷下，其留於筋骨之間。寒多則筋攣骨痛；熱多則筋弛骨消，肉爍〈月困〉破毛直而敗。","sortOrder":12},
  {"id":"s_work_hdnk_56_13","chapterId":"ch_work_hdnk_56","text":"帝曰：夫子言皮之十二部，其生病皆何如。","sortOrder":13},
  {"id":"s_work_hdnk_56_14","chapterId":"ch_work_hdnk_56","text":"岐伯曰：皮者，脈之部也。邪客於皮，則腠理開，開則邪入客於絡脈，絡脈滿，則註於經脈，經脈滿，則入舍於腑臟也。故皮者有分部不與而生大病也。帝曰：善。","sortOrder":14},
  {"id":"s_work_hdnk_57_1","chapterId":"ch_work_hdnk_57","text":"經絡論篇第五十七","sortOrder":1},
  {"id":"s_work_hdnk_57_2","chapterId":"ch_work_hdnk_57","text":"黃帝問曰：夫絡脈之見也，其五色各異，青黃赤白黑不同，其故何也？","sortOrder":2},
  {"id":"s_work_hdnk_57_3","chapterId":"ch_work_hdnk_57","text":"岐伯對曰：經有常色，而絡無常變也。","sortOrder":3},
  {"id":"s_work_hdnk_57_4","chapterId":"ch_work_hdnk_57","text":"帝曰：經之常色何如？岐伯曰：心赤、肺白、肝青、脾黃、腎黑，皆亦應其經脈之色也。","sortOrder":4},
  {"id":"s_work_hdnk_57_5","chapterId":"ch_work_hdnk_57","text":"帝曰：絡之陰陽，亦應其經乎？","sortOrder":5},
  {"id":"s_work_hdnk_57_6","chapterId":"ch_work_hdnk_57","text":"岐伯曰：陰絡之色應其經，陽絡之色變無常，隨四時而行也。","sortOrder":6},
  {"id":"s_work_hdnk_57_7","chapterId":"ch_work_hdnk_57","text":"寒多則凝泣，凝泣則青黑；熱多則淖澤，淖澤則黃赤。此皆常色，謂之無病。五色具見者，謂之寒熱。帝曰：善。","sortOrder":7},
  {"id":"s_work_hdnk_58_1","chapterId":"ch_work_hdnk_58","text":"氣穴論篇第五十八","sortOrder":1},
  {"id":"s_work_hdnk_58_2","chapterId":"ch_work_hdnk_58","text":"黃帝問曰：餘聞氣穴三百六十五以應一歲，未知其所，願卒聞之。","sortOrder":2},
  {"id":"s_work_hdnk_58_3","chapterId":"ch_work_hdnk_58","text":"岐伯稽首再拜對曰：窘乎哉問也？其非精帝，孰能窮其道焉，因請溢意盡言其處。","sortOrder":3},
  {"id":"s_work_hdnk_58_4","chapterId":"ch_work_hdnk_58","text":"帝捧手逡巡而卻曰：夫子之開餘道也，目未見其處，耳未聞其數，而目已明，耳以聰矣。","sortOrder":4},
  {"id":"s_work_hdnk_58_5","chapterId":"ch_work_hdnk_58","text":"岐伯曰：此所謂精人易語，良馬易御也。","sortOrder":5},
  {"id":"s_work_hdnk_58_6","chapterId":"ch_work_hdnk_58","text":"帝曰：餘非精人之易語也，世言真數開人意，今餘所訪問者真數，發蒙解惑，未足以論也。然餘願聞夫子溢志盡言其處，令解其意，請藏之金匱，不敢復出。","sortOrder":6},
  {"id":"s_work_hdnk_58_7","chapterId":"ch_work_hdnk_58","text":"岐伯再拜而起曰：臣請言之，背與心相控而痛，所治天突與十椎及上紀。上紀者胃脘也，下紀者關元也。","sortOrder":7},
  {"id":"s_work_hdnk_58_8","chapterId":"ch_work_hdnk_58","text":"背胸邪繫陰陽左右如此，其病前後痛澀，胸脅痛而不得息，不得臥、上氣、短氣、偏痛、脈滿起，斜出尻脈，絡胸脅，支心貫膈，上肩加天突，斜下肩，交十椎下。","sortOrder":8},
  {"id":"s_work_hdnk_58_9","chapterId":"ch_work_hdnk_58","text":"臟俞五十穴。","sortOrder":9},
  {"id":"s_work_hdnk_58_10","chapterId":"ch_work_hdnk_58","text":"腑俞七十二穴","sortOrder":10},
  {"id":"s_work_hdnk_58_11","chapterId":"ch_work_hdnk_58","text":"熱俞五十九穴","sortOrder":11},
  {"id":"s_work_hdnk_58_12","chapterId":"ch_work_hdnk_58","text":"水俞五十七穴","sortOrder":12},
  {"id":"s_work_hdnk_58_13","chapterId":"ch_work_hdnk_58","text":"頭上五行，行五，五五二十五穴。","sortOrder":13},
  {"id":"s_work_hdnk_58_14","chapterId":"ch_work_hdnk_58","text":"中〈月呂〉兩傍各五，凡十穴。","sortOrder":14},
  {"id":"s_work_hdnk_58_15","chapterId":"ch_work_hdnk_58","text":"大椎上兩傍各一，凡二穴。","sortOrder":15},
  {"id":"s_work_hdnk_58_16","chapterId":"ch_work_hdnk_58","text":"目瞳子浮白二穴。","sortOrder":16},
  {"id":"s_work_hdnk_58_17","chapterId":"ch_work_hdnk_58","text":"兩髀厭分中二穴。","sortOrder":17},
  {"id":"s_work_hdnk_58_18","chapterId":"ch_work_hdnk_58","text":"犢鼻二穴。","sortOrder":18},
  {"id":"s_work_hdnk_58_19","chapterId":"ch_work_hdnk_58","text":"耳中多所聞二穴。","sortOrder":19},
  {"id":"s_work_hdnk_58_20","chapterId":"ch_work_hdnk_58","text":"眉本二穴。","sortOrder":20},
  {"id":"s_work_hdnk_58_21","chapterId":"ch_work_hdnk_58","text":"完骨二穴。","sortOrder":21},
  {"id":"s_work_hdnk_58_22","chapterId":"ch_work_hdnk_58","text":"頂中央一穴。","sortOrder":22},
  {"id":"s_work_hdnk_58_23","chapterId":"ch_work_hdnk_58","text":"枕骨二穴。","sortOrder":23},
  {"id":"s_work_hdnk_58_24","chapterId":"ch_work_hdnk_58","text":"上關二穴。","sortOrder":24},
  {"id":"s_work_hdnk_58_25","chapterId":"ch_work_hdnk_58","text":"大迎二穴。","sortOrder":25},
  {"id":"s_work_hdnk_58_26","chapterId":"ch_work_hdnk_58","text":"下關二穴。","sortOrder":26},
  {"id":"s_work_hdnk_58_27","chapterId":"ch_work_hdnk_58","text":"天柱二穴。","sortOrder":27},
  {"id":"s_work_hdnk_58_28","chapterId":"ch_work_hdnk_58","text":"巨虛上下廉四穴。","sortOrder":28},
  {"id":"s_work_hdnk_58_29","chapterId":"ch_work_hdnk_58","text":"曲牙二穴。","sortOrder":29},
  {"id":"s_work_hdnk_58_30","chapterId":"ch_work_hdnk_58","text":"天突一穴。","sortOrder":30},
  {"id":"s_work_hdnk_58_31","chapterId":"ch_work_hdnk_58","text":"天府二穴。","sortOrder":31},
  {"id":"s_work_hdnk_58_32","chapterId":"ch_work_hdnk_58","text":"天牖二穴。","sortOrder":32},
  {"id":"s_work_hdnk_58_33","chapterId":"ch_work_hdnk_58","text":"扶突二穴。","sortOrder":33},
  {"id":"s_work_hdnk_58_34","chapterId":"ch_work_hdnk_58","text":"天窗二穴。","sortOrder":34},
  {"id":"s_work_hdnk_58_35","chapterId":"ch_work_hdnk_58","text":"肩解二穴。","sortOrder":35},
  {"id":"s_work_hdnk_58_36","chapterId":"ch_work_hdnk_58","text":"關元一穴。","sortOrder":36},
  {"id":"s_work_hdnk_58_37","chapterId":"ch_work_hdnk_58","text":"委陽二穴。","sortOrder":37},
  {"id":"s_work_hdnk_58_38","chapterId":"ch_work_hdnk_58","text":"肩貞二穴。","sortOrder":38},
  {"id":"s_work_hdnk_58_39","chapterId":"ch_work_hdnk_58","text":"喑門一穴。","sortOrder":39},
  {"id":"s_work_hdnk_58_40","chapterId":"ch_work_hdnk_58","text":"齊一穴。","sortOrder":40},
  {"id":"s_work_hdnk_58_41","chapterId":"ch_work_hdnk_58","text":"胸俞十二穴。","sortOrder":41},
  {"id":"s_work_hdnk_58_42","chapterId":"ch_work_hdnk_58","text":"背俞二穴。","sortOrder":42},
  {"id":"s_work_hdnk_58_43","chapterId":"ch_work_hdnk_58","text":"膺俞十二穴。","sortOrder":43},
  {"id":"s_work_hdnk_58_44","chapterId":"ch_work_hdnk_58","text":"分肉二穴。","sortOrder":44},
  {"id":"s_work_hdnk_58_45","chapterId":"ch_work_hdnk_58","text":"踝上橫二穴。","sortOrder":45},
  {"id":"s_work_hdnk_58_46","chapterId":"ch_work_hdnk_58","text":"陰陽蹻四穴。","sortOrder":46},
  {"id":"s_work_hdnk_58_47","chapterId":"ch_work_hdnk_58","text":"水俞在諸分，熱俞在氣穴，寒熱俞在兩骸厭中二穴。","sortOrder":47},
  {"id":"s_work_hdnk_58_48","chapterId":"ch_work_hdnk_58","text":"大禁二十五在天府下五寸。","sortOrder":48},
  {"id":"s_work_hdnk_58_49","chapterId":"ch_work_hdnk_58","text":"凡三百六十五穴，針之所由行也。","sortOrder":49},
  {"id":"s_work_hdnk_58_50","chapterId":"ch_work_hdnk_58","text":"帝曰：餘已知氣穴之處，遊針之居，願聞孫絡溪穀，亦有所應乎？","sortOrder":50},
  {"id":"s_work_hdnk_58_51","chapterId":"ch_work_hdnk_58","text":"岐伯曰：孫絡三百六十五穴會，亦以應一歲，以溢奇邪，以通榮衛。榮衛稽留，衛散榮溢，氣竭血著。外為發熱，內為少氣。疾瀉無怠，以通榮衛，見而瀉之，無問所會。","sortOrder":51},
  {"id":"s_work_hdnk_58_52","chapterId":"ch_work_hdnk_58","text":"帝曰：善。願聞溪穀之會也。","sortOrder":52},
  {"id":"s_work_hdnk_58_53","chapterId":"ch_work_hdnk_58","text":"岐伯曰：肉之大會為穀，肉之小會為溪，肉分之間，溪穀之會。以行榮衛，以會大氣。邪盛氣壅，脈熱肉敗，榮衛不行，必將為膿，內銷骨髓，外破大膕。留於節湊，必將為敗。積寒留舍，榮衛不居，捲肉縮筋，肋肘不得伸。內為骨痹，外為不仁，命曰不足，大寒留於溪穀也。溪穀三百六十五穴會。亦應一歲。其小痹淫溢，循脈往來，微針所及，與法相同。","sortOrder":53},
  {"id":"s_work_hdnk_58_54","chapterId":"ch_work_hdnk_58","text":"帝乃避左右而起，再拜曰：今日發蒙解惑，藏之金匱，不敢復出。乃藏之金蘭之室，署曰氣穴所在。岐伯曰：孫絡之脈別經者，其血盛而當瀉者，亦三百六十五脈，並註於絡，傳註十二絡脈，非獨十四絡脈也，內解瀉於中者十脈。","sortOrder":54},
  {"id":"s_work_hdnk_59_1","chapterId":"ch_work_hdnk_59","text":"氣府論篇第五十九","sortOrder":1},
  {"id":"s_work_hdnk_59_2","chapterId":"ch_work_hdnk_59","text":"足太陽脈氣所發者，七十八穴。","sortOrder":2},
  {"id":"s_work_hdnk_59_3","chapterId":"ch_work_hdnk_59","text":"兩眉頭各一。","sortOrder":3},
  {"id":"s_work_hdnk_59_4","chapterId":"ch_work_hdnk_59","text":"入髮至項三寸半傍五，相去三寸。","sortOrder":4},
  {"id":"s_work_hdnk_59_5","chapterId":"ch_work_hdnk_59","text":"其浮氣在皮中者，凡五行，行五，五五二十五。","sortOrder":5},
  {"id":"s_work_hdnk_59_6","chapterId":"ch_work_hdnk_59","text":"項中大筋兩旁，各一。","sortOrder":6},
  {"id":"s_work_hdnk_59_7","chapterId":"ch_work_hdnk_59","text":"風府兩旁，各一。","sortOrder":7},
  {"id":"s_work_hdnk_59_8","chapterId":"ch_work_hdnk_59","text":"俠背以下至尻尾二十一節，十五間各一，五臟之俞各五，六腑之俞各六。","sortOrder":8},
  {"id":"s_work_hdnk_59_9","chapterId":"ch_work_hdnk_59","text":"委中以下至足小趾旁，各六俞。","sortOrder":9},
  {"id":"s_work_hdnk_59_10","chapterId":"ch_work_hdnk_59","text":"足少陽脈氣所發者，六十二穴，兩角上各二。","sortOrder":10},
  {"id":"s_work_hdnk_59_11","chapterId":"ch_work_hdnk_59","text":"直目上髮際內各五。","sortOrder":11},
  {"id":"s_work_hdnk_59_12","chapterId":"ch_work_hdnk_59","text":"耳前角上各一。","sortOrder":12},
  {"id":"s_work_hdnk_59_13","chapterId":"ch_work_hdnk_59","text":"耳前角下各一。","sortOrder":13},
  {"id":"s_work_hdnk_59_14","chapterId":"ch_work_hdnk_59","text":"銳髮下，各一。","sortOrder":14},
  {"id":"s_work_hdnk_59_15","chapterId":"ch_work_hdnk_59","text":"客主人，各一。","sortOrder":15},
  {"id":"s_work_hdnk_59_16","chapterId":"ch_work_hdnk_59","text":"耳後陷中，各一。","sortOrder":16},
  {"id":"s_work_hdnk_59_17","chapterId":"ch_work_hdnk_59","text":"下關各一。","sortOrder":17},
  {"id":"s_work_hdnk_59_18","chapterId":"ch_work_hdnk_59","text":"耳下牙車之後，各一。","sortOrder":18},
  {"id":"s_work_hdnk_59_19","chapterId":"ch_work_hdnk_59","text":"缺盆各一。","sortOrder":19},
  {"id":"s_work_hdnk_59_20","chapterId":"ch_work_hdnk_59","text":"掖下三寸，脅下至胠，八間各一。","sortOrder":20},
  {"id":"s_work_hdnk_59_21","chapterId":"ch_work_hdnk_59","text":"髀樞中傍，各一。","sortOrder":21},
  {"id":"s_work_hdnk_59_22","chapterId":"ch_work_hdnk_59","text":"膝以下至足小趾次趾各六俞。","sortOrder":22},
  {"id":"s_work_hdnk_59_23","chapterId":"ch_work_hdnk_59","text":"足陽明脈氣血所發者，六十八穴，額顱髮際旁各三。","sortOrder":23},
  {"id":"s_work_hdnk_59_24","chapterId":"ch_work_hdnk_59","text":"面鼽骨空各一。","sortOrder":24},
  {"id":"s_work_hdnk_59_25","chapterId":"ch_work_hdnk_59","text":"大迎之骨空各一。","sortOrder":25},
  {"id":"s_work_hdnk_59_26","chapterId":"ch_work_hdnk_59","text":"人迎各一。","sortOrder":26},
  {"id":"s_work_hdnk_59_27","chapterId":"ch_work_hdnk_59","text":"缺盆外骨空各一。","sortOrder":27},
  {"id":"s_work_hdnk_59_28","chapterId":"ch_work_hdnk_59","text":"膺中骨間各一。","sortOrder":28},
  {"id":"s_work_hdnk_59_29","chapterId":"ch_work_hdnk_59","text":"俠鳩尾之外，當乳下三寸，俠胃脘各五。","sortOrder":29},
  {"id":"s_work_hdnk_59_30","chapterId":"ch_work_hdnk_59","text":"俠臍廣三寸，各三。","sortOrder":30},
  {"id":"s_work_hdnk_59_31","chapterId":"ch_work_hdnk_59","text":"下齊二寸，俠之各三。","sortOrder":31},
  {"id":"s_work_hdnk_59_32","chapterId":"ch_work_hdnk_59","text":"氣街動脈各一。","sortOrder":32},
  {"id":"s_work_hdnk_59_33","chapterId":"ch_work_hdnk_59","text":"伏兔上各一。","sortOrder":33},
  {"id":"s_work_hdnk_59_34","chapterId":"ch_work_hdnk_59","text":"三里以下至足中趾各八俞，分之所在穴空。","sortOrder":34},
  {"id":"s_work_hdnk_59_35","chapterId":"ch_work_hdnk_59","text":"手太陽脈氣所發者，三十六穴，目內眥各一。","sortOrder":35},
  {"id":"s_work_hdnk_59_36","chapterId":"ch_work_hdnk_59","text":"目外各一。","sortOrder":36},
  {"id":"s_work_hdnk_59_37","chapterId":"ch_work_hdnk_59","text":"鼽骨下各一。","sortOrder":37},
  {"id":"s_work_hdnk_59_38","chapterId":"ch_work_hdnk_59","text":"耳郭上各一。","sortOrder":38},
  {"id":"s_work_hdnk_59_39","chapterId":"ch_work_hdnk_59","text":"耳中各一。","sortOrder":39},
  {"id":"s_work_hdnk_59_40","chapterId":"ch_work_hdnk_59","text":"巨骨穴各一。","sortOrder":40},
  {"id":"s_work_hdnk_59_41","chapterId":"ch_work_hdnk_59","text":"曲掖上骨穴各一。","sortOrder":41},
  {"id":"s_work_hdnk_59_42","chapterId":"ch_work_hdnk_59","text":"柱骨上陷者各一。","sortOrder":42},
  {"id":"s_work_hdnk_59_43","chapterId":"ch_work_hdnk_59","text":"上天窗四寸，各一。","sortOrder":43},
  {"id":"s_work_hdnk_59_44","chapterId":"ch_work_hdnk_59","text":"肩解各一。","sortOrder":44},
  {"id":"s_work_hdnk_59_45","chapterId":"ch_work_hdnk_59","text":"肩解下三寸，各一。","sortOrder":45},
  {"id":"s_work_hdnk_59_46","chapterId":"ch_work_hdnk_59","text":"肘以下至手小指本各六俞。","sortOrder":46},
  {"id":"s_work_hdnk_59_47","chapterId":"ch_work_hdnk_59","text":"手陽明脈氣所發者，二十二穴。鼻空外廉項上，各二。","sortOrder":47},
  {"id":"s_work_hdnk_59_48","chapterId":"ch_work_hdnk_59","text":"大迎骨空各一。","sortOrder":48},
  {"id":"s_work_hdnk_59_49","chapterId":"ch_work_hdnk_59","text":"柱骨之會各一。","sortOrder":49},
  {"id":"s_work_hdnk_59_50","chapterId":"ch_work_hdnk_59","text":"髃骨之會各一。","sortOrder":50},
  {"id":"s_work_hdnk_59_51","chapterId":"ch_work_hdnk_59","text":"肘以下至手大指次指本各六俞。","sortOrder":51},
  {"id":"s_work_hdnk_59_52","chapterId":"ch_work_hdnk_59","text":"手少陽脈氣所發者三十二穴，鼽骨下各一。","sortOrder":52},
  {"id":"s_work_hdnk_59_53","chapterId":"ch_work_hdnk_59","text":"眉後各一。","sortOrder":53},
  {"id":"s_work_hdnk_59_54","chapterId":"ch_work_hdnk_59","text":"角上各一。","sortOrder":54},
  {"id":"s_work_hdnk_59_55","chapterId":"ch_work_hdnk_59","text":"下完骨後各一。","sortOrder":55},
  {"id":"s_work_hdnk_59_56","chapterId":"ch_work_hdnk_59","text":"項中足太陽之前各一。","sortOrder":56},
  {"id":"s_work_hdnk_59_57","chapterId":"ch_work_hdnk_59","text":"俠扶突各一。","sortOrder":57},
  {"id":"s_work_hdnk_59_58","chapterId":"ch_work_hdnk_59","text":"肩貞各一。","sortOrder":58},
  {"id":"s_work_hdnk_59_59","chapterId":"ch_work_hdnk_59","text":"肩貞下三寸分間各一。","sortOrder":59},
  {"id":"s_work_hdnk_59_60","chapterId":"ch_work_hdnk_59","text":"肘以下至手小指次指本各六俞。","sortOrder":60},
  {"id":"s_work_hdnk_59_61","chapterId":"ch_work_hdnk_59","text":"督脈氣所發者，二十八穴。","sortOrder":61},
  {"id":"s_work_hdnk_59_62","chapterId":"ch_work_hdnk_59","text":"項中央二。","sortOrder":62},
  {"id":"s_work_hdnk_59_63","chapterId":"ch_work_hdnk_59","text":"髮際後中八。","sortOrder":63},
  {"id":"s_work_hdnk_59_64","chapterId":"ch_work_hdnk_59","text":"面中三。","sortOrder":64},
  {"id":"s_work_hdnk_59_65","chapterId":"ch_work_hdnk_59","text":"大椎以下至尻尾及旁十五穴。","sortOrder":65},
  {"id":"s_work_hdnk_59_66","chapterId":"ch_work_hdnk_59","text":"至骶下凡二十一節脊椎法也。","sortOrder":66},
  {"id":"s_work_hdnk_59_67","chapterId":"ch_work_hdnk_59","text":"任脈之氣所發者，二十八穴，喉中央二。","sortOrder":67},
  {"id":"s_work_hdnk_59_68","chapterId":"ch_work_hdnk_59","text":"膺中骨陷中各一。","sortOrder":68},
  {"id":"s_work_hdnk_59_69","chapterId":"ch_work_hdnk_59","text":"鳩尾下三寸，胃脘五寸，胃脘以下至橫骨六寸半一，腹脈法也。","sortOrder":69},
  {"id":"s_work_hdnk_59_70","chapterId":"ch_work_hdnk_59","text":"下陰別一。","sortOrder":70},
  {"id":"s_work_hdnk_59_71","chapterId":"ch_work_hdnk_59","text":"目下各一。","sortOrder":71},
  {"id":"s_work_hdnk_59_72","chapterId":"ch_work_hdnk_59","text":"下唇一。","sortOrder":72},
  {"id":"s_work_hdnk_59_73","chapterId":"ch_work_hdnk_59","text":"斷交一。","sortOrder":73},
  {"id":"s_work_hdnk_59_74","chapterId":"ch_work_hdnk_59","text":"沖脈氣所發者，二十二穴。俠鳩尾外各半寸，至齊寸一。","sortOrder":74},
  {"id":"s_work_hdnk_59_75","chapterId":"ch_work_hdnk_59","text":"俠齊下旁各五分，至橫骨寸一，腹脈法也。","sortOrder":75},
  {"id":"s_work_hdnk_59_76","chapterId":"ch_work_hdnk_59","text":"足少陰舌下。","sortOrder":76},
  {"id":"s_work_hdnk_59_77","chapterId":"ch_work_hdnk_59","text":"厥陰毛中急脈各一。","sortOrder":77},
  {"id":"s_work_hdnk_59_78","chapterId":"ch_work_hdnk_59","text":"手少陰各一。","sortOrder":78},
  {"id":"s_work_hdnk_59_79","chapterId":"ch_work_hdnk_59","text":"陰陽蹻各一。","sortOrder":79},
  {"id":"s_work_hdnk_59_80","chapterId":"ch_work_hdnk_59","text":"手足諸魚際脈氣所發者。","sortOrder":80},
  {"id":"s_work_hdnk_59_81","chapterId":"ch_work_hdnk_59","text":"凡三百六十五穴也。","sortOrder":81},
  {"id":"s_work_hdnk_60_1","chapterId":"ch_work_hdnk_60","text":"骨空論篇第六十","sortOrder":1},
  {"id":"s_work_hdnk_60_2","chapterId":"ch_work_hdnk_60","text":"黃帝問曰：餘聞風者，百病之始也。以針治之奈何？","sortOrder":2},
  {"id":"s_work_hdnk_60_3","chapterId":"ch_work_hdnk_60","text":"岐伯對曰：風從外入，令人振寒汗出，頭痛、身重、惡寒。治在風府，調其陰陽，不足則補，有餘則瀉。","sortOrder":3},
  {"id":"s_work_hdnk_60_4","chapterId":"ch_work_hdnk_60","text":"大風頸項痛，刺風府，風府在上椎。","sortOrder":4},
  {"id":"s_work_hdnk_60_5","chapterId":"ch_work_hdnk_60","text":"大風汗出，灸譩譆，譩譆在背下俠脊傍三寸所，壓之令病人呼譩譆，譩譆應手。","sortOrder":5},
  {"id":"s_work_hdnk_60_6","chapterId":"ch_work_hdnk_60","text":"從風憎風，刺眉頭。","sortOrder":6},
  {"id":"s_work_hdnk_60_7","chapterId":"ch_work_hdnk_60","text":"失枕在肩，上橫骨間。","sortOrder":7},
  {"id":"s_work_hdnk_60_8","chapterId":"ch_work_hdnk_60","text":"折使榆臂齊肘正灸脊中。","sortOrder":8},
  {"id":"s_work_hdnk_60_9","chapterId":"ch_work_hdnk_60","text":"〈月少〉絡季脅引少腹而痛脹，刺譩譆。","sortOrder":9},
  {"id":"s_work_hdnk_60_10","chapterId":"ch_work_hdnk_60","text":"腰痛不可以轉搖，急引陰卵，刺八髎與痛上，八髎在腰尻分間。","sortOrder":10},
  {"id":"s_work_hdnk_60_11","chapterId":"ch_work_hdnk_60","text":"鼠瘻寒熱，還刺寒府。寒府在附膝外解營。取膝上外者，使之拜；取足心者，使之跪。","sortOrder":11},
  {"id":"s_work_hdnk_60_12","chapterId":"ch_work_hdnk_60","text":"任脈者，起於中極之下，以上毛際，循腹裏，上關元，至咽喉，上頤循面入目。","sortOrder":12},
  {"id":"s_work_hdnk_60_13","chapterId":"ch_work_hdnk_60","text":"沖脈者，起於氣街，並少陰之經，俠臍上行，至胸中而散。","sortOrder":13},
  {"id":"s_work_hdnk_60_14","chapterId":"ch_work_hdnk_60","text":"任脈為病，男子內結七疝，女子帶下瘕聚。","sortOrder":14},
  {"id":"s_work_hdnk_60_15","chapterId":"ch_work_hdnk_60","text":"沖脈為病，逆氣裏急。","sortOrder":15},
  {"id":"s_work_hdnk_60_16","chapterId":"ch_work_hdnk_60","text":"督脈為病，脊強反折。","sortOrder":16},
  {"id":"s_work_hdnk_60_17","chapterId":"ch_work_hdnk_60","text":"督脈者，起於少腹以下骨中央。女子入係廷孔，其孔溺孔之端也。其絡循陰器，合篡間，繞篡後，別繞臀，至少陰與巨陽中絡者合，少陰上股內後廉貫脊屬腎。","sortOrder":17},
  {"id":"s_work_hdnk_60_18","chapterId":"ch_work_hdnk_60","text":"與太陽起於目內眥，上額交巔，上入絡腦，還出別下項，循肩髆內。俠脊抵腰中，入循膂絡腎。","sortOrder":18},
  {"id":"s_work_hdnk_60_19","chapterId":"ch_work_hdnk_60","text":"其男子循莖下至篡，與女子等，其少腹直上者，貫臍中央，上貫心，入喉上頤，環唇上系兩目之下中央。","sortOrder":19},
  {"id":"s_work_hdnk_60_20","chapterId":"ch_work_hdnk_60","text":"此生病，從少腹上沖心而痛，不得前後，為沖疝，其女子不孕，癃痔、遺溺、溢幹；督脈生病治督脈，治在骨上，甚者在臍下營。","sortOrder":20},
  {"id":"s_work_hdnk_60_21","chapterId":"ch_work_hdnk_60","text":"其上氣有音者，治其喉中央，在缺盆中者。","sortOrder":21},
  {"id":"s_work_hdnk_60_22","chapterId":"ch_work_hdnk_60","text":"其病上沖喉者，治其漸，漸者，上俠頤也。","sortOrder":22},
  {"id":"s_work_hdnk_60_23","chapterId":"ch_work_hdnk_60","text":"蹇膝伸不屈，治其楗；坐而膝痛，治其機；立而暑解治其骸關；膝痛，痛及姆指，治其膕；坐而膝痛如物隱者，治其關；膝痛不可屈伸，治其背內；連〈骨行〉若折，活陽明中俞髎。若別治巨陽少陰滎，淫濼脛酸不能久立，治少陽之維，在外上五寸。","sortOrder":23},
  {"id":"s_work_hdnk_60_24","chapterId":"ch_work_hdnk_60","text":"輔骨上橫骨下為為楗，俠髖為機，膝解為骸關，俠膝之骨為連骸，骸下為輔，輔上為膕，膕上為關，頭橫骨為枕。","sortOrder":24},
  {"id":"s_work_hdnk_60_25","chapterId":"ch_work_hdnk_60","text":"水俞五十七穴，尻上五行，行五，伏菟上兩行，行五，左右各一行，行五，踝上各一行，行六穴。","sortOrder":25},
  {"id":"s_work_hdnk_60_26","chapterId":"ch_work_hdnk_60","text":"髓空：在腦後三分，在顱際銳骨之下，一在齦基下；一在項後中復骨下；一在脊骨上空，在風府上。脊骨下空，在尻骨下空；數髓空，在面俠鼻；或骨空在口下，當兩肩。兩髆肩空，在髆中之陽。臂骨空，在臂陽去踝四寸兩骨空門間。股骨上空，在股陽出上膝四寸。〈骨行〉骨空，在輔骨之上端。股際骨空，在毛中動下。尻骨空，在髀骨之後，相去四寸。扁骨有滲理湊無髓孔，易髓無空。","sortOrder":26},
  {"id":"s_work_hdnk_60_27","chapterId":"ch_work_hdnk_60","text":"灸寒熱之法，先灸項大椎，以年為壯數；次灸橛骨。以年為壯數。","sortOrder":27},
  {"id":"s_work_hdnk_60_28","chapterId":"ch_work_hdnk_60","text":"視背俞陷者灸之，舉臂肩上陷者灸之，兩季脅之間灸之，外踝上絕骨之端灸之，足小指次指間灸之，腨下陷脈灸之，外踝後灸之。","sortOrder":28},
  {"id":"s_work_hdnk_60_29","chapterId":"ch_work_hdnk_60","text":"缺盆骨上切之堅痛如筋者灸之，膺中陷骨間灸之，掌束骨下灸之，臍下關元三寸灸之，毛際動脈灸之，膝下三寸分間灸之，足陽明跗上動脈灸之，巔上一灸之。","sortOrder":29},
  {"id":"s_work_hdnk_60_30","chapterId":"ch_work_hdnk_60","text":"犬所嚙之處灸之，三壯，即以犬傷病法灸之。","sortOrder":30},
  {"id":"s_work_hdnk_60_31","chapterId":"ch_work_hdnk_60","text":"凡當灸二十九處。","sortOrder":31},
  {"id":"s_work_hdnk_60_32","chapterId":"ch_work_hdnk_60","text":"傷食灸之，不已者，必視其經之過於陽者，數刺其俞而藥之。","sortOrder":32},
  {"id":"s_work_hdnk_61_1","chapterId":"ch_work_hdnk_61","text":"水熱穴論篇第六十一","sortOrder":1},
  {"id":"s_work_hdnk_61_2","chapterId":"ch_work_hdnk_61","text":"黃帝問曰：少陰何以主腎，腎何以主水？岐伯對曰：腎者至陰也。至陰者，盛水也，肺者太陰也，少陰者冬脈也。故其本在腎，其末在肺，皆積水也。","sortOrder":2},
  {"id":"s_work_hdnk_61_3","chapterId":"ch_work_hdnk_61","text":"帝曰：腎何以能聚水而生病？岐伯曰：腎者胃之關也。關門不利，故聚水而從其類也。上下溢於皮膚，故為胕腫。胕腫者，聚水而生病也。","sortOrder":3},
  {"id":"s_work_hdnk_61_4","chapterId":"ch_work_hdnk_61","text":"帝曰：諸水皆生於腎乎？岐伯曰：腎者牝藏也，地氣上者，屬於腎，而生水液也。故曰：至陰勇而勞甚，則腎汗出，腎汗出逢於風，內不得入於臟腑，外不得越於皮膚，客於玄府，行於皮裏，傳為胕腫，本之於腎，名曰風水。所謂玄府者，汗空也。","sortOrder":4},
  {"id":"s_work_hdnk_61_5","chapterId":"ch_work_hdnk_61","text":"帝曰：水俞五十七處者，是何主也？岐伯曰：腎俞五十七穴，積陰之所聚也，水所從出入也。尻上五行行五者，此腎俞。故水病下為胕腫、大腹，上為喘呼、不得臥者，標本俱病，故肺為喘呼，腎為水腫，肺為逆不得臥，分為相輸俱受者，水氣之所留也。","sortOrder":5},
  {"id":"s_work_hdnk_61_6","chapterId":"ch_work_hdnk_61","text":"伏菟上各二行，行五者，此腎之街也。三陰之所交結於腳也。踝上各一行，行六者，此腎脈之下行也，名曰太沖。凡五十七穴者，皆臟之陰絡，水之所客也。","sortOrder":6},
  {"id":"s_work_hdnk_61_7","chapterId":"ch_work_hdnk_61","text":"帝曰：春取絡脈分肉何也？岐伯曰：春者木始治，肝氣始生，肝氣急，其風疾。經脈常深，其氣少，不能深入，故取絡脈分肉間。","sortOrder":7},
  {"id":"s_work_hdnk_61_8","chapterId":"ch_work_hdnk_61","text":"帝曰：夏取盛經分腠何也？岐伯曰：夏者火始治，心氣始長，脈瘦氣弱，陽氣留溢，熱熏分腠，內至於經。故取盛經分腠，絕膚而病去者，邪居淺也。所謂盛經者，陽脈也。","sortOrder":8},
  {"id":"s_work_hdnk_61_9","chapterId":"ch_work_hdnk_61","text":"帝曰：秋取經俞何也？岐伯曰：秋者金始治，肺將收殺，金將勝火，陽氣在合，陰氣初勝，濕氣及體陰氣未盛，未能深入，故取俞以瀉陰邪，取合以虛陽邪，陽氣始衰，故取於合。","sortOrder":9},
  {"id":"s_work_hdnk_61_10","chapterId":"ch_work_hdnk_61","text":"帝曰：冬取井滎何也？岐伯曰：冬者水始治，腎方閉，陽氣衰少，陰氣堅盛，巨陽伏沉，陽脈乃去，故取井以下陰逆，取滎以實陽氣。故曰：冬取井滎，春不鼽衄。","sortOrder":10},
  {"id":"s_work_hdnk_61_11","chapterId":"ch_work_hdnk_61","text":"帝曰：夫子言治熱病五十九俞，餘論其意，未能領別其處，願聞其處，因聞其意。岐伯曰：頭上五行行五者，以越諸陽之熱逆也，大杼、膺俞、缺盆、背俞，此八者，以瀉胸中之熱也。氣街、三里、巨虛上下廉，此八者，以瀉胃中之熱也。雲門、髃骨、委中、髓空，此八者，以瀉四肢之熱也。五臟俞傍五，此十者，以瀉五臟之熱也。凡此五十九穴者，皆熱之左右也。","sortOrder":11},
  {"id":"s_work_hdnk_61_12","chapterId":"ch_work_hdnk_61","text":"帝曰：人傷於寒，而傳為熱，何也？岐伯曰：夫寒盛則生熱也。","sortOrder":12},
  {"id":"s_work_hdnk_62_1","chapterId":"ch_work_hdnk_62","text":"調經論篇第六十二","sortOrder":1},
  {"id":"s_work_hdnk_62_2","chapterId":"ch_work_hdnk_62","text":"黃帝問曰：餘聞刺法言，有餘瀉之，不足補之，何謂有餘，何謂不足？岐伯對曰：有餘有五，不足亦有五，常欲何問？帝曰：願盡聞之。岐伯曰：神有餘，有不足；氣有餘，有不足；血有餘，有不足；形有餘，有不足；志有餘，有不足。凡此十者，其氣不等也。","sortOrder":2},
  {"id":"s_work_hdnk_62_3","chapterId":"ch_work_hdnk_62","text":"帝曰：人有精氣、津液、四肢、九竅、五臟十六部，三百六十五節，乃生百病，百病之生，皆有虛實。今夫子乃言有餘有五，不足亦有五，何以生之乎？","sortOrder":3},
  {"id":"s_work_hdnk_62_4","chapterId":"ch_work_hdnk_62","text":"岐伯曰：皆生於五臟也。夫心藏神，肺藏氣，肝藏血，脾藏肉，腎藏志，而此成形。志意通，內連骨髓而成身形五臟。五臟之道，皆出於經隧，以行血氣。血氣不和，百病乃變化而生，是故守經隧焉。","sortOrder":4},
  {"id":"s_work_hdnk_62_5","chapterId":"ch_work_hdnk_62","text":"帝曰：神有餘不足何如？岐伯曰：神有餘則笑不休，神不足則悲。血氣未並，五臟安定，邪客於形，洒淅起於毫毛，未入於經絡也。故命曰神之微。","sortOrder":5},
  {"id":"s_work_hdnk_62_6","chapterId":"ch_work_hdnk_62","text":"帝曰：補瀉奈何？岐伯曰：神有餘則瀉其小絡之血，出血勿之深斥；無中其大經，神氣乃平。神不足者，視其虛絡，按而致之，刺而利之，無出其血，無泄其氣，以通其經，神氣乃平。","sortOrder":6},
  {"id":"s_work_hdnk_62_7","chapterId":"ch_work_hdnk_62","text":"帝曰：刺微奈何？岐伯曰：按摩勿釋，著針勿斥，移氣於不足，神氣乃得復。","sortOrder":7},
  {"id":"s_work_hdnk_62_8","chapterId":"ch_work_hdnk_62","text":"帝曰：善。（氣）有餘不足奈何？岐伯曰：氣有餘則喘咳上氣，不足則息利少氣。血氣未併，五臟安定，皮膚微病，命曰白氣微泄。","sortOrder":8},
  {"id":"s_work_hdnk_62_9","chapterId":"ch_work_hdnk_62","text":"帝曰：補瀉奈何？岐伯曰：氣有餘則瀉其經隧，無傷其經，無出其血，無泄其氣。不足則補其經隧，無出其氣。","sortOrder":9},
  {"id":"s_work_hdnk_62_10","chapterId":"ch_work_hdnk_62","text":"帝曰：刺微奈何？岐伯曰：按摩勿釋，出針視之曰，我將深之，適人必革，精氣自伏，邪氣散亂，無所休息，氣泄腠理，真氣乃相得。","sortOrder":10},
  {"id":"s_work_hdnk_62_11","chapterId":"ch_work_hdnk_62","text":"帝曰：善。血有餘不足奈何？岐伯曰：血有餘則怒，不足則恐，血氣未併，五臟安定，孫絡水溢，則經有留血。","sortOrder":11},
  {"id":"s_work_hdnk_62_12","chapterId":"ch_work_hdnk_62","text":"帝曰：補瀉奈何？岐伯曰：血有餘則瀉其盛經，出其血；不足則視其虛經，內針其脈中，久留而視，脈大疾出其針，無令血泄。","sortOrder":12},
  {"id":"s_work_hdnk_62_13","chapterId":"ch_work_hdnk_62","text":"帝曰：刺留血奈何？岐伯曰：視其血絡，刺出其血，無令惡血得入於經，以成其疾。","sortOrder":13},
  {"id":"s_work_hdnk_62_14","chapterId":"ch_work_hdnk_62","text":"帝曰：善。形有餘不足奈何？岐伯曰：形有餘則腹脹，逕溲不利。不足則四肢不用，血氣未併，五臟安定。肌肉蠕動，命曰微風。","sortOrder":14},
  {"id":"s_work_hdnk_62_15","chapterId":"ch_work_hdnk_62","text":"帝曰：補瀉奈何？岐伯曰：形有餘則瀉其陽經，不足則補其陽絡。","sortOrder":15},
  {"id":"s_work_hdnk_62_16","chapterId":"ch_work_hdnk_62","text":"帝曰：刺微奈何？岐伯曰：取分肉間，無中其經，無傷其絡，衛氣得復，邪氣乃索。","sortOrder":16},
  {"id":"s_work_hdnk_62_17","chapterId":"ch_work_hdnk_62","text":"帝曰：善。志有餘不足奈何？岐伯曰：志有餘則腹脹飧泄，不足則厥。血氣未併，五臟安定，骨節有動。","sortOrder":17},
  {"id":"s_work_hdnk_62_18","chapterId":"ch_work_hdnk_62","text":"帝曰：補瀉奈何？岐伯曰：志有餘則瀉然筋血者，不足則補其復溜。","sortOrder":18},
  {"id":"s_work_hdnk_62_19","chapterId":"ch_work_hdnk_62","text":"帝曰：刺未併奈何？岐伯曰：即取之無中其經，邪所乃能立虛。","sortOrder":19},
  {"id":"s_work_hdnk_62_20","chapterId":"ch_work_hdnk_62","text":"帝曰：善。餘已聞虛實之形，不知其何以生？岐伯曰：氣血以併，陰陽相傾，氣亂於衛，血逆於經，血氣離居，一實一虛。血併於陰，氣併於陽，故為驚狂。血併於陽，氣併於陰，乃為炅中。血併於上，氣併於下，心煩惋善怒。血併於下，氣併於上，亂而喜忘。","sortOrder":20},
  {"id":"s_work_hdnk_62_21","chapterId":"ch_work_hdnk_62","text":"帝曰：血併於陰，氣併於陽，如是血氣離居，何者為實？何者為虛？岐伯曰：血氣者喜溫而惡寒，寒則泣不能流，溫則消而去之，是故氣之所併為血虛，血之所併為氣虛。","sortOrder":21},
  {"id":"s_work_hdnk_62_22","chapterId":"ch_work_hdnk_62","text":"帝曰：人之所有者血與氣耳。今夫子乃言血併為虛，氣併為虛，是無實乎？岐伯曰：有者為實，無者為虛，故氣併則無血，血併則無氣。今血與氣相失，故為虛焉。絡之與孫絡俱輸於經，血與氣併則為實焉。血之與氣併走於上，則為大厥，厥則暴死，氣復反則生，不反則死。","sortOrder":22},
  {"id":"s_work_hdnk_62_23","chapterId":"ch_work_hdnk_62","text":"帝曰：實者何道從來？虛者何道從去？虛實之要。願聞其故。岐伯曰：夫陰與陽皆有俞會。陽註於陰，陰滿之外，陰陽均平，以充其形，九候若一，命曰平人。夫邪之生也，或生於陰，或生於陽。其生於陽者，得之風雨寒暑；其生於陰者，得之飲食居處，陰陽喜怒。","sortOrder":23},
  {"id":"s_work_hdnk_62_24","chapterId":"ch_work_hdnk_62","text":"帝曰：風雨之傷人奈何？岐伯曰：風雨之傷人也，先客於皮膚，傳入於孫脈，孫脈滿則傳入於絡脈，絡脈滿則輸於大經脈，血氣與邪併，客於分腠之間，其脈堅大，故曰實。實者，外堅充滿不可按之，按之則痛。","sortOrder":24},
  {"id":"s_work_hdnk_62_25","chapterId":"ch_work_hdnk_62","text":"帝曰：寒濕之傷人，奈何？岐伯曰：寒濕之中人也，皮膚不收，肌肉堅緊，榮血泣，衛氣去，故曰虛。虛者，聶辟氣不足，按之則氣足以溫之，故快然而不痛。","sortOrder":25},
  {"id":"s_work_hdnk_62_26","chapterId":"ch_work_hdnk_62","text":"帝曰：善。陰之生實奈何？岐伯曰：喜怒不節，則陰氣上逆，上逆則下虛，下虛則陽氣走之。故曰實矣。","sortOrder":26},
  {"id":"s_work_hdnk_62_27","chapterId":"ch_work_hdnk_62","text":"帝曰：陰之生虛奈何？岐伯曰：喜則氣下，悲則氣消，消則脈虛空。因寒飲食，寒氣熏滿，則血泣氣去，故曰虛矣。","sortOrder":27},
  {"id":"s_work_hdnk_62_28","chapterId":"ch_work_hdnk_62","text":"帝曰：經言陽虛則外寒，陰虛則內熱，陽盛則外熱，陰盛則內寒，餘已聞之矣，不知其所由然也。岐伯曰：陽受氣於上焦，以溫皮膚分肉之間，令寒氣在外，則上焦不通，上焦不通，則寒氣獨留於外，故寒慄。","sortOrder":28},
  {"id":"s_work_hdnk_62_29","chapterId":"ch_work_hdnk_62","text":"帝曰：陰虛生內熱奈何？岐伯曰：有所勞倦，形氣衰少，穀氣不盛，上焦不行，下脘不通，胃氣熱，熱氣熏胸中，故內熱。","sortOrder":29},
  {"id":"s_work_hdnk_62_30","chapterId":"ch_work_hdnk_62","text":"帝曰：陽盛生外熱奈何？岐伯曰：上焦不通利，則皮膚致密，腠理閉塞，玄府不通，衛氣不得泄越，故外熱。","sortOrder":30},
  {"id":"s_work_hdnk_62_31","chapterId":"ch_work_hdnk_62","text":"帝曰：陰盛生內寒奈何？岐伯曰：厥氣上逆，寒氣積於胸中而不瀉，不瀉則溫氣去寒獨留，則血凝泣，凝則脈不通，其脈盛大以澀，故中寒。","sortOrder":31},
  {"id":"s_work_hdnk_62_32","chapterId":"ch_work_hdnk_62","text":"帝曰：陰與陽併，血氣以併，病形以成，刺之奈何？岐伯曰：刺此者取之經隧。取血於營，取氣於衛。用形哉，因四時多少高下。","sortOrder":32},
  {"id":"s_work_hdnk_62_33","chapterId":"ch_work_hdnk_62","text":"帝曰：血氣以併，病形以成，陰陽相傾，補瀉奈何？岐伯曰：瀉實者，氣盛乃內針，針與氣俱內，以開其門，如利其戶，針與氣俱出，精氣不傷，邪氣乃下，外門不閉，以出其疾，搖大其道，如利其路，是謂大瀉，必切而出，大氣乃屈。","sortOrder":33},
  {"id":"s_work_hdnk_62_34","chapterId":"ch_work_hdnk_62","text":"帝曰：補虛奈何？岐伯曰：持針勿置，以定其意，候呼內針，氣出針入，針空四塞，精無從去，方實而疾針，氣入針出，熱不能還，閉塞其門，邪氣布散，精氣乃得存，動氣候時，近氣不失，遠氣乃來，是謂追之。","sortOrder":34},
  {"id":"s_work_hdnk_62_35","chapterId":"ch_work_hdnk_62","text":"帝曰：夫子言虛實者有十，生於五臟，五臟五脈耳。夫十二經脈皆生其病，今夫子獨言五臟。夫十二經脈者，皆絡三百六十五節，節有病必被經脈，經脈之病，皆有虛實，何以合之？岐伯曰：五臟者故得六腑與為表裏，經絡支節，各生虛實，其病所居，隨而謂之。","sortOrder":35},
  {"id":"s_work_hdnk_62_36","chapterId":"ch_work_hdnk_62","text":"病在脈，調之血；病在血，調之絡；病在氣，調之衛；病在肉，調之分肉；病在筋，調之筋；病在骨，調之骨。燔針動刺其下及與急者。病在骨焠針藥熨。病不知所痛，兩蹻為上。身形有痛，九候莫病，則繆刺之痛在於左而右脈病者巨刺之。必謹察其九候，針道備矣。","sortOrder":36},
  {"id":"s_work_hdnk_63_1","chapterId":"ch_work_hdnk_63","text":"繆刺論篇第六十三","sortOrder":1},
  {"id":"s_work_hdnk_63_2","chapterId":"ch_work_hdnk_63","text":"黃帝問曰：餘聞繆刺，未得其意，何謂繆刺？","sortOrder":2},
  {"id":"s_work_hdnk_63_3","chapterId":"ch_work_hdnk_63","text":"岐伯對曰：夫邪之客於形也，必先舍於皮毛，留而不去，入舍於孫脈，留而不去，入舍於絡脈，留而不去，入舍於經脈，內連五臟，散於腸胃，陰陽俱感，五臟乃傷，此邪之從皮毛而入，極於五臟之次也。如此則治其經焉。今邪客於皮毛，入舍於孫絡，留而不去，閉塞不通，不得入於經，流溢於大絡，而生奇病也。夫邪客大絡者，左註右，右註左，上下左右與經相幹，而佈於四末，其氣無常處，不入於經俞，命曰繆刺。","sortOrder":3},
  {"id":"s_work_hdnk_63_4","chapterId":"ch_work_hdnk_63","text":"帝曰：願聞繆刺，以左取右，以右取左，奈何？其與巨刺何以別之？岐伯曰：邪客於經，左盛則右病，右盛則左病，亦有移易者，左痛未已，而右脈先病，如此者，必巨刺之，必中其經，非絡脈也。故絡病者，其痛與經脈繆處，故命曰繆刺。","sortOrder":4},
  {"id":"s_work_hdnk_63_5","chapterId":"ch_work_hdnk_63","text":"帝曰：願聞繆刺奈何？取之何如？岐伯曰：邪客於足少陰之絡，令人卒心痛、暴脹、胸脅肢滿、無積者，刺然骨之前出血，如食頃而已，不已左取右，右取左。病新發者，取五日已。","sortOrder":5},
  {"id":"s_work_hdnk_63_6","chapterId":"ch_work_hdnk_63","text":"邪客於手少陽之絡，令人喉痺，舌倦口乾，心煩，臂外廉痛，手不及頭，刺手中指次指爪甲上，去端如韭葉，各一痏，壯者立已，老者有頃已，左取右，右取左，此新病數日已。","sortOrder":6},
  {"id":"s_work_hdnk_63_7","chapterId":"ch_work_hdnk_63","text":"邪客於足厥陰之絡，令人卒疝暴痛。刺足大指爪甲上與肉交者，各一痏，男子立已，女子有頃已，左取右，右取左。","sortOrder":7},
  {"id":"s_work_hdnk_63_8","chapterId":"ch_work_hdnk_63","text":"邪客於足太陽之絡，令人頭項肩痛。刺足小指爪甲上與肉交者，各一痏，立已。不已，刺外踝下三痏，左取右，右取左，如食頃已。","sortOrder":8},
  {"id":"s_work_hdnk_63_9","chapterId":"ch_work_hdnk_63","text":"邪客於手陽明之絡，令人氣滿胸中，喘息而肢胠，胸中熱。刺手大指次指爪甲上，去端如韭葉，各一痏，左取右，右取左，如食頃已。","sortOrder":9},
  {"id":"s_work_hdnk_63_10","chapterId":"ch_work_hdnk_63","text":"邪客於臂掌之間，不可得屈。刺其踝後，先以指按之痛，乃刺之。以月死生為數，月生一日一痏，二日二痏，十五日十五痏，十六日十四痏。","sortOrder":10},
  {"id":"s_work_hdnk_63_11","chapterId":"ch_work_hdnk_63","text":"邪客於足陽蹻之脈，令人目痛，從內眥始。刺外踝之下半寸所各二痏，左刺右，右刺左，如行十里頃而已。","sortOrder":11},
  {"id":"s_work_hdnk_63_12","chapterId":"ch_work_hdnk_63","text":"人有所墮墜，惡血留內，腹中滿脹，不得前後。先飲利藥，此上傷厥陰之脈，下傷少陰之絡。刺足內踝之下，然骨之前，血脈出血，刺足跗上動脈。不已，刺三毛上各一痏，見血立已，左刺右，右刺左，善悲驚不樂，刺如右方。","sortOrder":12},
  {"id":"s_work_hdnk_63_13","chapterId":"ch_work_hdnk_63","text":"邪客於手陽明之絡，令人耳聾，時不聞音。刺手大指次指爪甲上去端如韭葉各一痏，立聞。不已，刺中指爪甲上與肉交者，立聞。其不時聞者，不可刺也。耳中生風者，亦刺之如此數，左刺右，右刺左。","sortOrder":13},
  {"id":"s_work_hdnk_63_14","chapterId":"ch_work_hdnk_63","text":"凡痺往來，行無常處者，在分肉間痛而刺之，以月死生為數，用針者，隨氣盛衰，以為痏數，針過其日數則脫氣，不及日數則氣不瀉，左刺右，右刺左，病已止，不已復刺之如法，月生一日一痏，二日二痏，漸多之，十五日十五痏，十六日，十四痏，漸少之。","sortOrder":14},
  {"id":"s_work_hdnk_63_15","chapterId":"ch_work_hdnk_63","text":"邪客於足陽明之經，令人鼽衄，上齒寒。刺足中指次指爪甲上與肉交者，各一痏，左刺右，右刺左。","sortOrder":15},
  {"id":"s_work_hdnk_63_16","chapterId":"ch_work_hdnk_63","text":"邪客於足少陽之絡，令人脅痛，不得息，咳而汗出。刺足小指次指爪甲上與肉交者，各一痏，不得息立已，汗出立止，咳者溫衣飲食，一日已。左刺右，右刺左，病立已，不已，覆刺如法。","sortOrder":16},
  {"id":"s_work_hdnk_63_17","chapterId":"ch_work_hdnk_63","text":"邪客於足少陰之絡，令人嗌痛，不可內食，無故善怒，氣上走賁上。刺足下中央之脈，各三痏，凡六刺，立已。左刺右，右刺左，嗌中腫，不能內唾，時不能出唾者，刺然骨之前，出血立已，左刺右，右刺左。","sortOrder":17},
  {"id":"s_work_hdnk_63_18","chapterId":"ch_work_hdnk_63","text":"邪客於足太陰之絡，令人腰痛，引少腹控眇，不可以抑息，刺腰尻之解，兩胛之上，是腰俞，以月死生為痏數，發針立已，左刺右，右刺左。","sortOrder":18},
  {"id":"s_work_hdnk_63_19","chapterId":"ch_work_hdnk_63","text":"邪客於足太陽之絡，令人拘攣、背急、引脅而痛，刺之從項始，數脊椎俠脊，按疾之應手如痛，刺之傍三痏，立已。","sortOrder":19},
  {"id":"s_work_hdnk_63_20","chapterId":"ch_work_hdnk_63","text":"邪客於足少陽之絡，令人留於樞中痛，髀不可舉，刺樞中，以毫針，寒則久留。針以月死生為數，立已。","sortOrder":20},
  {"id":"s_work_hdnk_63_21","chapterId":"ch_work_hdnk_63","text":"治諸經刺之，所過者不病，則繆刺之。","sortOrder":21},
  {"id":"s_work_hdnk_63_22","chapterId":"ch_work_hdnk_63","text":"耳聾、刺手陽明，不已，刺其通脈，出耳前者。","sortOrder":22},
  {"id":"s_work_hdnk_63_23","chapterId":"ch_work_hdnk_63","text":"齒齲，刺手陽明。不已，刺其脈，入齒中，立已。","sortOrder":23},
  {"id":"s_work_hdnk_63_24","chapterId":"ch_work_hdnk_63","text":"邪客於五臟之間，其病也，脈引而痛，時來時止，視其病繆刺之於手足爪甲上，視其脈，出其血，間日一刺，一刺不已，五刺已。","sortOrder":24},
  {"id":"s_work_hdnk_63_25","chapterId":"ch_work_hdnk_63","text":"繆傳引上齒，齒唇寒痛，視其手背脈血者，去之，足陽明中指爪甲上一痏，手大指次指爪甲上各一痏，立已，左取右，右取左。","sortOrder":25},
  {"id":"s_work_hdnk_63_26","chapterId":"ch_work_hdnk_63","text":"邪客於手足少陰太陰足陽明之絡，此五絡皆會於耳中，上絡左角，五絡俱竭，令人身脈皆動，而形無知也，其狀若屍，或曰屍厥。","sortOrder":26},
  {"id":"s_work_hdnk_63_27","chapterId":"ch_work_hdnk_63","text":"刺其足大指內側爪甲上，去端如韭葉，後刺足心，後刺足中指爪甲上各一痏，後刺手大指內側，去端如韭葉，後刺手心主，少陰銳骨之端，各一痏，立已。不已，以竹管吹其兩耳，鬄其左角之髮，方一寸燔治，飲以美酒一杯，不能飲者，灌之，立已。","sortOrder":27},
  {"id":"s_work_hdnk_63_28","chapterId":"ch_work_hdnk_63","text":"凡刺之數，無視其經脈，切而從之，審其虛實而調之。不調者，經刺之；有痛而經不病者，繆刺之。因視其皮部有血絡者，盡取之，此繆刺之數也。","sortOrder":28},
  {"id":"s_work_hdnk_64_1","chapterId":"ch_work_hdnk_64","text":"四時刺逆從論篇第六十四","sortOrder":1},
  {"id":"s_work_hdnk_64_2","chapterId":"ch_work_hdnk_64","text":"厥陰有餘病陰痺；不足病生熱痺；滑則病狐疝風；澀則病少腹積氣。","sortOrder":2},
  {"id":"s_work_hdnk_64_3","chapterId":"ch_work_hdnk_64","text":"少陰有餘皮痺隱軫；不足病肺痺；滑則病肺風疝；澀則病積溲血。","sortOrder":3},
  {"id":"s_work_hdnk_64_4","chapterId":"ch_work_hdnk_64","text":"太陰有餘，病肉痺，寒中；不足病脾痺；滑則病脾風疝；澀則病積，心腹時滿。","sortOrder":4},
  {"id":"s_work_hdnk_64_5","chapterId":"ch_work_hdnk_64","text":"陽明有餘，病脈痺身時熱；不足病心痺；滑則病心風疝；澀則病積，時善驚。","sortOrder":5},
  {"id":"s_work_hdnk_64_6","chapterId":"ch_work_hdnk_64","text":"太陽有餘病骨痺，身重；不足病腎痺；滑則病腎風疝；澀則病積，善時巔疾。","sortOrder":6},
  {"id":"s_work_hdnk_64_7","chapterId":"ch_work_hdnk_64","text":"少陽有餘病筋痺、脅滿；不足病肝痺，滑則病肝風疝；澀則病積，時筋急目痛。","sortOrder":7},
  {"id":"s_work_hdnk_64_8","chapterId":"ch_work_hdnk_64","text":"是故春氣在經脈，夏氣在孫絡；長夏氣在肌肉，秋氣在皮膚，冬氣在骨髓中。","sortOrder":8},
  {"id":"s_work_hdnk_64_9","chapterId":"ch_work_hdnk_64","text":"帝曰：餘願聞其故。岐伯曰：春者天氣始開，地氣始泄，凍解冰釋，水行經通，故人氣在脈。夏者經滿氣溢，入孫絡受血，皮膚充實。長夏者，經絡皆盛，內溢肌中。秋者天氣始收，腠理閉塞，皮膚引急。冬者，蓋藏血氣在中。內著骨髓，通於五臟。是故邪氣者，常隨四時之氣血而入客也。至其變化，不可為度，然必從其經氣，辟除其邪，除其邪則亂氣不生。","sortOrder":9},
  {"id":"s_work_hdnk_64_10","chapterId":"ch_work_hdnk_64","text":"帝曰：逆四時而生亂氣奈何？岐伯曰：春刺絡脈，血氣外溢，令人少氣；春刺肌肉，血氣環逆，令人上氣；春刺筋骨，血氣內著，令人腹脹。","sortOrder":10},
  {"id":"s_work_hdnk_64_11","chapterId":"ch_work_hdnk_64","text":"夏刺經脈，血氣乃竭，令人解〈亻亦〉；夏刺肌肉，血氣內卻，令人善恐；夏刺筋骨，血氣上逆，令人善怒。","sortOrder":11},
  {"id":"s_work_hdnk_64_12","chapterId":"ch_work_hdnk_64","text":"秋刺經脈，血氣上逆，令人善忘，秋刺絡脈，氣不外行，令人臥，不欲動；秋刺筋骨，血氣內散，令人寒慄。","sortOrder":12},
  {"id":"s_work_hdnk_64_13","chapterId":"ch_work_hdnk_64","text":"冬刺經脈，氣血皆脫，令人目不明；冬刺絡脈，內氣外泄，留為大痺，冬刺肌肉，陽氣竭絕，令人善忘。","sortOrder":13},
  {"id":"s_work_hdnk_64_14","chapterId":"ch_work_hdnk_64","text":"凡此四時刺者，大逆之病，不可不從也，反之則生亂氣相淫病焉。故刺不知四時之經，病之所生，以從為逆，正氣內亂，與精相薄，必審九候，正氣不亂，精氣不轉。","sortOrder":14},
  {"id":"s_work_hdnk_64_15","chapterId":"ch_work_hdnk_64","text":"帝曰：善。刺五臟中心一曰死，其動為噫。中肝五日死，其動為語。中肺三日死，其動為咳。中腎六日死，其動為嚏欠。中脾十日死，其動為吞。刺傷人五臟必死，其動則依其藏之所變候，知其死也。","sortOrder":15},
  {"id":"s_work_hdnk_65_1","chapterId":"ch_work_hdnk_65","text":"標本病傳論篇第六十五","sortOrder":1},
  {"id":"s_work_hdnk_65_2","chapterId":"ch_work_hdnk_65","text":"黃帝問曰：病有標本，刺有逆從奈何？","sortOrder":2},
  {"id":"s_work_hdnk_65_3","chapterId":"ch_work_hdnk_65","text":"岐伯對曰：凡刺之方，必別陰陽，前後相應，逆從得施，標本相移，故曰有其在標而求之於標，有其在本而求之於本，有其在本而求之於標，有其在標而求之於本。故治有取標而得者，有取本而得者，有逆取而得者，有從取而得者。故知逆與從，正行無問，知標本者，萬舉萬當，不知標本，是謂妄行。","sortOrder":3},
  {"id":"s_work_hdnk_65_4","chapterId":"ch_work_hdnk_65","text":"夫陰陽逆從，標本之為道也，小而大，言一而知百病之害，少而多，淺而博，可以言一而知百也。以淺而知深，察近而知遠，言標與本，易而勿及。","sortOrder":4},
  {"id":"s_work_hdnk_65_5","chapterId":"ch_work_hdnk_65","text":"治反為逆，治得為從。","sortOrder":5},
  {"id":"s_work_hdnk_65_6","chapterId":"ch_work_hdnk_65","text":"先病而後逆者，治其本；先逆而後病者，治其本。","sortOrder":6},
  {"id":"s_work_hdnk_65_7","chapterId":"ch_work_hdnk_65","text":"先寒而後生病者，治其本；先病而後生寒者，治其本。","sortOrder":7},
  {"id":"s_work_hdnk_65_8","chapterId":"ch_work_hdnk_65","text":"先熱而後生病者，治其本；先熱而後生中滿者，治其標。","sortOrder":8},
  {"id":"s_work_hdnk_65_9","chapterId":"ch_work_hdnk_65","text":"先病而後泄者，治其本；先泄而後生他病者，治其本。必先調之，乃治其他病。","sortOrder":9},
  {"id":"s_work_hdnk_65_10","chapterId":"ch_work_hdnk_65","text":"先病而後先中滿者，治其標；先中滿而後煩心者，治其本。","sortOrder":10},
  {"id":"s_work_hdnk_65_11","chapterId":"ch_work_hdnk_65","text":"人有客氣有同氣。","sortOrder":11},
  {"id":"s_work_hdnk_65_12","chapterId":"ch_work_hdnk_65","text":"小大不利，治其標；小大利，治其本。","sortOrder":12},
  {"id":"s_work_hdnk_65_13","chapterId":"ch_work_hdnk_65","text":"病發而有餘，本而標之，先治其本，後治其標。病發而不足，標而本之，先治其標，後治其本。","sortOrder":13},
  {"id":"s_work_hdnk_65_14","chapterId":"ch_work_hdnk_65","text":"謹察間甚，以意調之；間者並行，甚者獨行，先以小大不利而後生病者，治其本。","sortOrder":14},
  {"id":"s_work_hdnk_65_15","chapterId":"ch_work_hdnk_65","text":"夫病傳者心病，先心痛，一日而咳，三日脅肢痛，五日閉塞不通，身痛體重，三日不已死。冬夜半，夏日中。","sortOrder":15},
  {"id":"s_work_hdnk_65_16","chapterId":"ch_work_hdnk_65","text":"肺病喘咳，三日而脅肢滿痛，一日身重體痛，五日而脹，十日不已死。冬日入，夏日出。","sortOrder":16},
  {"id":"s_work_hdnk_65_17","chapterId":"ch_work_hdnk_65","text":"肝病頭目眩脅肢滿，三日體重身痛，五日而脹，三日腰脊少腹痛脛酸，三日不已死。冬日入，夏早食。","sortOrder":17},
  {"id":"s_work_hdnk_65_18","chapterId":"ch_work_hdnk_65","text":"脾病身痛體重，一日而脹，二日少腹腰脊痛，脛痠，三日背〈月呂〉筋痛，小便閉，十日不已死。冬入定，夏晏食。","sortOrder":18},
  {"id":"s_work_hdnk_65_19","chapterId":"ch_work_hdnk_65","text":"腎病少腹腰脊痛、濁痠，三日背〈月呂〉筋痛，小便閉，三日腹脹，三日兩脅肢痛，三日不已死。冬大晨，夏晏晡。","sortOrder":19},
  {"id":"s_work_hdnk_65_20","chapterId":"ch_work_hdnk_65","text":"胃病脹滿，五日少腹腰脊痛、〈骨行〉痠，三日背〈月呂〉筋痛，小便閉，五日身體重，六日不已死。冬夜半後，夏日眣。","sortOrder":20},
  {"id":"s_work_hdnk_65_21","chapterId":"ch_work_hdnk_65","text":"膀胱病，小便閉，五日少腹脹，腰脊痛，〈骨行〉痠，一日腹脹，一日身體痛，二日不已死。冬雞鳴，夏下晡。","sortOrder":21},
  {"id":"s_work_hdnk_65_22","chapterId":"ch_work_hdnk_65","text":"諸病以次是相傳，如是者，皆有死期，不可刺。間一臟止及至三四臟者，乃可刺也。","sortOrder":22},
  {"id":"s_work_hdnk_66_1","chapterId":"ch_work_hdnk_66","text":"天元紀大論篇第六十六","sortOrder":1},
  {"id":"s_work_hdnk_66_2","chapterId":"ch_work_hdnk_66","text":"黃帝問曰：天有五行御五位，以生寒暑燥濕風。人有五臟化五氣，以生喜怒思憂恐。論言五運相襲，而皆治之，終期之日，周而復始，餘已知之矣。願聞其與三陰三陽之候奈何合之？","sortOrder":2},
  {"id":"s_work_hdnk_66_3","chapterId":"ch_work_hdnk_66","text":"鬼臾區稽首再拜對曰：昭乎哉問也。夫五運陰陽者，天地之道也，萬物之綱紀，變化之父母，生殺之本始，神明之府也，可不通乎。","sortOrder":3},
  {"id":"s_work_hdnk_66_4","chapterId":"ch_work_hdnk_66","text":"故物生謂之化，物極謂之變；陰陽不測謂之神；神用無方，謂之聖。","sortOrder":4},
  {"id":"s_work_hdnk_66_5","chapterId":"ch_work_hdnk_66","text":"夫變化之為用也，在天為玄，在人為道，在地為化，化生五味，道生智，玄生神。","sortOrder":5},
  {"id":"s_work_hdnk_66_6","chapterId":"ch_work_hdnk_66","text":"神在天為風，在地為木；在天為熱，在地為火；在天為濕，在地為土；在天為燥，在地為金；在天為寒，在地為水。故在天為氣，在地成形，形氣相感，而化生萬物矣。","sortOrder":6},
  {"id":"s_work_hdnk_66_7","chapterId":"ch_work_hdnk_66","text":"然天地者，萬物之上下也。左右者，陰陽之道路也。水火者，陰陽之徵兆也。金木者，生長之終始也。氣有多少，形有盛衰，上下相召，而損益彰矣。","sortOrder":7},
  {"id":"s_work_hdnk_66_8","chapterId":"ch_work_hdnk_66","text":"帝曰：願聞五運之主時也如何？鬼臾區曰：五氣運行，各終期日，非獨主時也。","sortOrder":8},
  {"id":"s_work_hdnk_66_9","chapterId":"ch_work_hdnk_66","text":"帝曰：請問其所謂也。鬼臾區曰：臣稽考太始天元冊文曰：太虛廖廓，肇基化元，萬物資始，五運終天，布氣真靈，總統坤元，九星懸朗，七曜周旋。曰陰曰陽，曰柔曰剛，幽顯既位，寒暑弛張，生生化化，品物鹹章，臣斯十世，此之謂也。","sortOrder":9},
  {"id":"s_work_hdnk_66_10","chapterId":"ch_work_hdnk_66","text":"帝曰：善。何謂氣有多少，形有盛衰？鬼臾區曰：陰陽之氣，各有多少，故曰三陰三陽也。形有盛衰，謂五行之治，各有太過不及也。故其始也，有餘而往，不足隨之；不足而往，有餘從之。知迎知隨，氣可與期。應天為天符，承歲為歲直，三合為治。","sortOrder":10},
  {"id":"s_work_hdnk_66_11","chapterId":"ch_work_hdnk_66","text":"帝曰：上下相召奈何？鬼臾區曰：寒暑燥濕風火，天之陰陽也，三陰三陽上奉之。木火土金水，地之陰陽也，生長化收藏下應之。","sortOrder":11},
  {"id":"s_work_hdnk_66_12","chapterId":"ch_work_hdnk_66","text":"天以陽生陰長，地以陽殺陰藏。","sortOrder":12},
  {"id":"s_work_hdnk_66_13","chapterId":"ch_work_hdnk_66","text":"天有陰陽，地亦有陰陽。木火土金水火，地之陰陽也，生長化收藏，故陽中有陰，陰中有陽。所以欲知天地之陰陽者，應天之氣，動而不息，故五歲而右遷；應地之氣，靜而守位，故六期而環會。動靜相召，上下相臨，陰陽相錯，而變由生也。","sortOrder":13},
  {"id":"s_work_hdnk_66_14","chapterId":"ch_work_hdnk_66","text":"帝曰：上下周紀，其有數乎？鬼臾區曰：天以六為節，地以五為製。周天氣者，六期為一備；終地紀者，五歲為一周。君火以明，相火以位。五六相合，而七百二十氣為一紀，凡三十歲，千四百四十氣，凡六十歲，而為一周，不及太過，斯皆見矣。","sortOrder":14},
  {"id":"s_work_hdnk_66_15","chapterId":"ch_work_hdnk_66","text":"帝曰：夫子之言，上終天氣，下畢地紀，可謂悉矣。餘願聞而藏之，上以治民，下以治身，使百姓昭著，上下和親，德澤下流，子孫無憂，傳之後世，無有終時，可得聞乎？","sortOrder":15},
  {"id":"s_work_hdnk_66_16","chapterId":"ch_work_hdnk_66","text":"鬼臾區曰：至數之機，迫迮以微，其來可見，其往可追，敬之者昌，慢之者亡，無道行弘，必得天殃。謹奉天道，請言真要。","sortOrder":16},
  {"id":"s_work_hdnk_66_17","chapterId":"ch_work_hdnk_66","text":"帝曰：善言始者，必會於終，善言近者，必知其遠，是則至數極而道不惑，所謂明矣。願夫子推而次之，令有條理，簡而不匱，久而不絕，易用難忘，為之綱紀。至數之要，願盡聞之。","sortOrder":17},
  {"id":"s_work_hdnk_66_18","chapterId":"ch_work_hdnk_66","text":"鬼臾區曰：昭乎哉問？明乎哉道！如鼓之應桴，響之應聲也。臣聞之，甲乙之歲，土運統之；乙庚之歲，金運統之；丙辛之歲，水運統之；丁壬之歲，木運統之；戊癸之歲，火運統之。","sortOrder":18},
  {"id":"s_work_hdnk_66_19","chapterId":"ch_work_hdnk_66","text":"帝曰：其於三陰三陽合之奈何？鬼臾區曰：子午之歲，上見少陰；丑未之歲，上見太陰；寅申之歲，上見少陽；卯酉之歲，上見陽明；辰戊之歲，上見太陽；已亥之歲，上見厥陰。少陰所謂標也，厥陰所謂終也。","sortOrder":19},
  {"id":"s_work_hdnk_66_20","chapterId":"ch_work_hdnk_66","text":"厥陰之上，風氣主之；少陰之上，熱氣主之；太陰之上，濕氣主之；少陽之上，相火主之；陽明之上，燥氣主之；太陽之上，寒氣主之。所謂本也，是謂六元。","sortOrder":20},
  {"id":"s_work_hdnk_66_21","chapterId":"ch_work_hdnk_66","text":"帝曰：光乎哉道，明乎哉論！請著之玉版、藏之金匱，署曰天元紀。","sortOrder":21},
  {"id":"s_work_hdnk_67_1","chapterId":"ch_work_hdnk_67","text":"五運行大論篇第六十七","sortOrder":1},
  {"id":"s_work_hdnk_67_2","chapterId":"ch_work_hdnk_67","text":"黃帝坐明堂，始正天綱，臨觀八極，考建五常。","sortOrder":2},
  {"id":"s_work_hdnk_67_3","chapterId":"ch_work_hdnk_67","text":"請天師而問之曰：論言天地之動靜，神明為之紀；陰陽之升降，寒暑彰其兆。","sortOrder":3},
  {"id":"s_work_hdnk_67_4","chapterId":"ch_work_hdnk_67","text":"餘聞五運之數於夫子，夫子之所言，正五氣之各主歲爾，首甲定運，餘因論之。鬼臾區曰：土主甲己，金主乙庚，水主丙辛，木主丁壬，火主戊癸。子午之上，少陰主之；丑未之上，太陰主之，寅申之上，少陽主之；卯酉之上，陽明主之；辰戌之上，太陽主之；已亥之上，厥陰主之。不合陰陽，其故何也？","sortOrder":4},
  {"id":"s_work_hdnk_67_5","chapterId":"ch_work_hdnk_67","text":"岐伯曰：是明道也，此天地之陰陽也。","sortOrder":5},
  {"id":"s_work_hdnk_67_6","chapterId":"ch_work_hdnk_67","text":"夫數之可數者，人中之陰陽也。然所合，數之可得者也。夫陰陽者，數之可十，推之可白，數之可千，推之可萬，天地陰陽者，不以數推以象之謂也。","sortOrder":6},
  {"id":"s_work_hdnk_67_7","chapterId":"ch_work_hdnk_67","text":"帝曰：願聞其所始也。岐伯曰：昭乎哉！問也。臣覽太始天元冊文，丹天之氣，經於牛女戊分；黅天之氣，經於心尾己分；蒼天之氣，經於危室柳鬼；素天之氣，經於亢氐昂畢；玄天之氣，經於張翼婁胃；所謂戊己分者，奎璧角軫，則天地之門戶也。","sortOrder":7},
  {"id":"s_work_hdnk_67_8","chapterId":"ch_work_hdnk_67","text":"夫候之所始，道之所生，不可不通也。","sortOrder":8},
  {"id":"s_work_hdnk_67_9","chapterId":"ch_work_hdnk_67","text":"帝曰：善。論言天地者，萬物之上下；左右者，陰陽之道路；未知其所謂也？","sortOrder":9},
  {"id":"s_work_hdnk_67_10","chapterId":"ch_work_hdnk_67","text":"岐伯曰：所謂上下者，歲上下見陰陽之所在也。左右者，諸上見厥陰，左少陰，右太陽；見少陰，左太陰，右厥陰；見太陰，左少陽，右少陰；見少陽，左陽明，右太陰；見陽明，左太陽，右少陽；見太陽，左厥陰，右陽明；所謂面北而命其位，言其見也。","sortOrder":10},
  {"id":"s_work_hdnk_67_11","chapterId":"ch_work_hdnk_67","text":"帝曰：何謂下？岐伯曰：厥陰在上，則少陽在下，左陽明，右太陰；少陰在上，則陽明在下，左太陽，右少陽；太陰在上，則太陽在下，左厥陰，右陽明；少陽在上，則厥陰在下，左少陰，右太陽；陽明在上，則少陰在下，左太陰，右厥陰；太陽在上，則太陰在下，左少陽，右少陰；所謂面南而命其位，言其見也。","sortOrder":11},
  {"id":"s_work_hdnk_67_12","chapterId":"ch_work_hdnk_67","text":"上下相遘，寒暑相臨，氣相得則和，不相得則病。","sortOrder":12},
  {"id":"s_work_hdnk_67_13","chapterId":"ch_work_hdnk_67","text":"帝曰：氣相得而病者，何也？岐伯曰：以下臨上，不當位也。","sortOrder":13},
  {"id":"s_work_hdnk_67_14","chapterId":"ch_work_hdnk_67","text":"帝曰：動靜何如？岐伯曰：上者右行，下者左行，左右周天，餘而覆會也。","sortOrder":14},
  {"id":"s_work_hdnk_67_15","chapterId":"ch_work_hdnk_67","text":"帝曰：餘聞鬼臾區曰：應地者靜，今夫子乃言下者左行，不知其所謂也？願聞何以生之乎？","sortOrder":15},
  {"id":"s_work_hdnk_67_16","chapterId":"ch_work_hdnk_67","text":"岐伯曰：天地動靜，五行遷復，雖鬼臾區其上候而已，猶不能遍明。","sortOrder":16},
  {"id":"s_work_hdnk_67_17","chapterId":"ch_work_hdnk_67","text":"夫變化之用，天垂象，地成形，七曜緯虛，五行麗地；地者，所以載生成之形類也。虛者，所以列應天之精氣也。形精之動，猶根本之與枝葉也，仰觀其象，雖遠可知也。","sortOrder":17},
  {"id":"s_work_hdnk_67_18","chapterId":"ch_work_hdnk_67","text":"帝曰：地之為下否乎？岐伯曰：地為人之下，太虛之中者也。","sortOrder":18},
  {"id":"s_work_hdnk_67_19","chapterId":"ch_work_hdnk_67","text":"帝曰：憑乎？岐伯曰：大氣舉之也。","sortOrder":19},
  {"id":"s_work_hdnk_67_20","chapterId":"ch_work_hdnk_67","text":"燥以乾之，暑以蒸之，風以動之，濕以潤之，寒以堅之，火以溫之。","sortOrder":20},
  {"id":"s_work_hdnk_67_21","chapterId":"ch_work_hdnk_67","text":"故風寒在下，燥熱在上，濕氣在中，火遊行其間，寒暑六入，故令虛而生化也。","sortOrder":21},
  {"id":"s_work_hdnk_67_22","chapterId":"ch_work_hdnk_67","text":"故燥勝則地乾，暑勝則地熱，風勝則地動，濕勝則地泥，寒勝則地裂，火勝則地固矣。","sortOrder":22},
  {"id":"s_work_hdnk_67_23","chapterId":"ch_work_hdnk_67","text":"帝曰：天地之氣，何以候之？岐伯曰：天地之氣，勝復之作，不形於診也。脈法曰：天地之變，無以脈診，此之謂也。","sortOrder":23},
  {"id":"s_work_hdnk_67_24","chapterId":"ch_work_hdnk_67","text":"帝曰：間氣何如？岐伯曰：隨氣所在，期於左右。","sortOrder":24},
  {"id":"s_work_hdnk_67_25","chapterId":"ch_work_hdnk_67","text":"帝曰：期之奈何？岐伯曰：從其氣則和，違其氣則病。","sortOrder":25},
  {"id":"s_work_hdnk_67_26","chapterId":"ch_work_hdnk_67","text":"不當其位者病，迭移其位者病，失守其位者危，尺寸白者死，陰陽交者死。先立其年，以知其氣，左右應見，然後乃可以言死生之逆順。","sortOrder":26},
  {"id":"s_work_hdnk_67_27","chapterId":"ch_work_hdnk_67","text":"帝曰：寒暑燥濕風火，在人合之奈何？其於萬物何以生化？","sortOrder":27},
  {"id":"s_work_hdnk_67_28","chapterId":"ch_work_hdnk_67","text":"岐伯曰：東方生風，風生木，木生酸，酸生肝，肝生筋，筋生心。","sortOrder":28},
  {"id":"s_work_hdnk_67_29","chapterId":"ch_work_hdnk_67","text":"其在天為玄，在人為道，在地為化；化生五味，道生智，玄生神，化生氣。","sortOrder":29},
  {"id":"s_work_hdnk_67_30","chapterId":"ch_work_hdnk_67","text":"神在天為風，在地為木，在體為筋，在氣為柔，在臟為肝。","sortOrder":30},
  {"id":"s_work_hdnk_67_31","chapterId":"ch_work_hdnk_67","text":"其性為喧，其德為和，其用為動，其色為蒼，其化為榮，其蟲毛，其政為散，其令宣發，其變摧拉，其眚為隕，其味為酸，其志為怒。","sortOrder":31},
  {"id":"s_work_hdnk_67_32","chapterId":"ch_work_hdnk_67","text":"怒傷肝，悲勝怒，風傷肝，燥勝風，酸傷筋，辛勝酸。","sortOrder":32},
  {"id":"s_work_hdnk_67_33","chapterId":"ch_work_hdnk_67","text":"南方生熱，熱生火，火生苦，苦生心，心生血，血生脾。","sortOrder":33},
  {"id":"s_work_hdnk_67_34","chapterId":"ch_work_hdnk_67","text":"其在天為熱，在地為火，在體為脈，在氣為息，在臟為心。","sortOrder":34},
  {"id":"s_work_hdnk_67_35","chapterId":"ch_work_hdnk_67","text":"其性為暑，其德為濕，其用為燥，其色為赤，其化為茂，其蟲羽，其政為明，其令鬱蒸，其變炎爍，其眚燔〈火苪〉，其味為苦，其志為喜。","sortOrder":35},
  {"id":"s_work_hdnk_67_36","chapterId":"ch_work_hdnk_67","text":"喜傷心，恐勝喜；熱傷氣，寒勝熱；苦傷氣，鹹勝苦。","sortOrder":36},
  {"id":"s_work_hdnk_67_37","chapterId":"ch_work_hdnk_67","text":"中央生濕，濕生土，土生甘，甘生脾，脾生肉，肉生肺。","sortOrder":37},
  {"id":"s_work_hdnk_67_38","chapterId":"ch_work_hdnk_67","text":"其在天為濕，在地為土，在體為肉，在氣為充，在臟為脾。","sortOrder":38},
  {"id":"s_work_hdnk_67_39","chapterId":"ch_work_hdnk_67","text":"其性靜兼，其德為濡，其用為化，其色為黃，其化為盈，其蟲倮，其政為謐，其令雲雨，其變動註，其眚淫潰，其味為甘，其志為思。","sortOrder":39},
  {"id":"s_work_hdnk_67_40","chapterId":"ch_work_hdnk_67","text":"思傷脾，怒勝思；濕傷肉，風勝濕；甘傷脾，酸勝甘。","sortOrder":40},
  {"id":"s_work_hdnk_67_41","chapterId":"ch_work_hdnk_67","text":"西方生燥，燥生金，金生辛，辛生肺，肺生皮毛，皮毛生腎。","sortOrder":41},
  {"id":"s_work_hdnk_67_42","chapterId":"ch_work_hdnk_67","text":"其在天為燥，在地為金，在體為皮毛，在氣為成，在臟為肺。","sortOrder":42},
  {"id":"s_work_hdnk_67_43","chapterId":"ch_work_hdnk_67","text":"其性為涼，其德為清，其用為固，其色為白，其化為歛，其蟲介，其政為勁，其令霧露，其變肅殺，其眚蒼落，其味為辛，其志為憂。","sortOrder":43},
  {"id":"s_work_hdnk_67_44","chapterId":"ch_work_hdnk_67","text":"憂傷肺，喜勝憂；熱傷皮毛，寒勝熱；辛傷皮毛，苦勝辛。","sortOrder":44},
  {"id":"s_work_hdnk_67_45","chapterId":"ch_work_hdnk_67","text":"北方生寒，寒生水，水生鹹，鹹生腎，腎生骨髓，髓生肝。","sortOrder":45},
  {"id":"s_work_hdnk_67_46","chapterId":"ch_work_hdnk_67","text":"其在天為寒，在地為水，在體為骨，在氣為堅，在臟為腎。","sortOrder":46},
  {"id":"s_work_hdnk_67_47","chapterId":"ch_work_hdnk_67","text":"其性為凜，其德為寒，其用為（闕一字），其色為黑，其化為肅，其蟲鱗，其政為靜，其令（闕二字），其變凝冽，其眚冰雹，其味為鹹，其志為恐。","sortOrder":47},
  {"id":"s_work_hdnk_67_48","chapterId":"ch_work_hdnk_67","text":"恐傷腎，思勝恐；寒傷血，燥勝寒；鹹傷血，甘勝鹹。","sortOrder":48},
  {"id":"s_work_hdnk_67_49","chapterId":"ch_work_hdnk_67","text":"五氣更立，各有所先，非其位則邪，當其位則正。","sortOrder":49},
  {"id":"s_work_hdnk_67_50","chapterId":"ch_work_hdnk_67","text":"帝曰：病生之變何如？岐伯曰：氣相得則微，不相得則甚。","sortOrder":50},
  {"id":"s_work_hdnk_67_51","chapterId":"ch_work_hdnk_67","text":"帝曰：主歲何如？岐伯曰：氣有餘，則製己所勝而侮所不勝；其不及，則己所不勝，侮而乘之，己所勝，輕而侮之。侮反受邪，侮而受邪，寡於畏也。帝曰：善。","sortOrder":51},
  {"id":"s_work_hdnk_68_1","chapterId":"ch_work_hdnk_68","text":"六微旨大論篇第六十八","sortOrder":1},
  {"id":"s_work_hdnk_68_2","chapterId":"ch_work_hdnk_68","text":"黃帝問曰：嗚呼，遠哉！天之道也，如迎浮雲，若視深淵尚可測，迎浮雲莫知其極。夫子數言謹奉天道，餘聞而藏之，心私異之，不知其所謂也？願夫子溢志盡言其事，令終不滅，久而不絕，天之道，可得聞乎？","sortOrder":2},
  {"id":"s_work_hdnk_68_3","chapterId":"ch_work_hdnk_68","text":"岐伯稽首再拜對曰：明乎哉問！天之道也，此因天之序，盛衰之時也。","sortOrder":3},
  {"id":"s_work_hdnk_68_4","chapterId":"ch_work_hdnk_68","text":"帝曰：願聞天道六六之節，盛衰何也？","sortOrder":4},
  {"id":"s_work_hdnk_68_5","chapterId":"ch_work_hdnk_68","text":"岐伯曰：上下有位，左右有紀。故少陽之右，陽明治之；陽明之右，太陽治之；太陽之右，厥陰治之；厥陰之右，少陰治之；少陰之右，太陰治之；太陰之右，少陽治之；此所謂氣之標，蓋南面而待也。故曰：因天之序，盛衰之時，移光定位，正立而待之，此之謂也。","sortOrder":5},
  {"id":"s_work_hdnk_68_6","chapterId":"ch_work_hdnk_68","text":"少陽之上，火氣治之，中見厥陰。","sortOrder":6},
  {"id":"s_work_hdnk_68_7","chapterId":"ch_work_hdnk_68","text":"陽明之上，燥氣治之，中見太陰。","sortOrder":7},
  {"id":"s_work_hdnk_68_8","chapterId":"ch_work_hdnk_68","text":"太陽之上，寒氣治之，中見少陰。","sortOrder":8},
  {"id":"s_work_hdnk_68_9","chapterId":"ch_work_hdnk_68","text":"厥陰之上，風氣治之，中見少陽。","sortOrder":9},
  {"id":"s_work_hdnk_68_10","chapterId":"ch_work_hdnk_68","text":"少陰之上，熱氣治之，中見太陽。","sortOrder":10},
  {"id":"s_work_hdnk_68_11","chapterId":"ch_work_hdnk_68","text":"太陰之上，濕氣治之，中見陽明。","sortOrder":11},
  {"id":"s_work_hdnk_68_12","chapterId":"ch_work_hdnk_68","text":"本標不同，氣應異象。","sortOrder":12},
  {"id":"s_work_hdnk_68_13","chapterId":"ch_work_hdnk_68","text":"帝曰：其有至而至，有至而不至，有至而太過，何也？","sortOrder":13},
  {"id":"s_work_hdnk_68_14","chapterId":"ch_work_hdnk_68","text":"岐伯曰：至而至者和；至而不至，來氣不及也；未至而至，來氣有餘也。","sortOrder":14},
  {"id":"s_work_hdnk_68_15","chapterId":"ch_work_hdnk_68","text":"帝曰：至而不至，未至而至，如何？岐伯曰：應則順，否則逆，逆則變生，變則病。","sortOrder":15},
  {"id":"s_work_hdnk_68_16","chapterId":"ch_work_hdnk_68","text":"帝曰：善。請言其應。岐伯曰：物生其應也，氣脈其應也。","sortOrder":16},
  {"id":"s_work_hdnk_68_17","chapterId":"ch_work_hdnk_68","text":"帝曰：善。願聞地理之應六節，氣位，何如？岐伯曰：顯明之右，君火之位也。君火之右，退行一步，相火治之，復行一步，土氣治之。復行一步，金氣治之。復行一步，水氣治之。復行一步，木氣治之。復行一步，君火治之。","sortOrder":17},
  {"id":"s_work_hdnk_68_18","chapterId":"ch_work_hdnk_68","text":"相火之下，水氣承之；水位之下，土氣承之；土位之下，風氣承之；風位之下，金氣承之；金位之下，火氣承之；君火之下，陰情承之。","sortOrder":18},
  {"id":"s_work_hdnk_68_19","chapterId":"ch_work_hdnk_68","text":"帝曰：何也？岐伯曰：亢則害，承乃製。製則生化，外列盛衰；害則敗亂，生化大病。","sortOrder":19},
  {"id":"s_work_hdnk_68_20","chapterId":"ch_work_hdnk_68","text":"帝曰：盛衰何如？岐伯曰：非其位則邪，當其位則正，邪則變甚，正則微。","sortOrder":20},
  {"id":"s_work_hdnk_68_21","chapterId":"ch_work_hdnk_68","text":"帝曰：何謂當位？岐伯曰：木運臨卯，火運臨午，土運臨四季，金運臨酉，水運臨子，所謂歲會，氣之平也。帝曰：非位何如？岐伯曰：歲不與會也。","sortOrder":21},
  {"id":"s_work_hdnk_68_22","chapterId":"ch_work_hdnk_68","text":"帝曰：土運之歲，上見太陰；火運之歲，上見少陽，少陰；金運之歲，上見陽明；木運之歲，上見厥陰；水運之歲，上見太陽；奈何？岐伯曰：天之與會也，故天元冊曰天符。","sortOrder":22},
  {"id":"s_work_hdnk_68_23","chapterId":"ch_work_hdnk_68","text":"天符歲會何如？岐伯曰：太一天符之會也。","sortOrder":23},
  {"id":"s_work_hdnk_68_24","chapterId":"ch_work_hdnk_68","text":"帝曰：其貴賤何如？岐伯曰：天符為執法，歲位為行令，太一天符為貴人。","sortOrder":24},
  {"id":"s_work_hdnk_68_25","chapterId":"ch_work_hdnk_68","text":"帝曰：邪之中也奈何？岐伯曰：中執法者，其病速而危；中行令者，其病徐而持；中貴人者，其病暴而死。","sortOrder":25},
  {"id":"s_work_hdnk_68_26","chapterId":"ch_work_hdnk_68","text":"帝曰：位之易也，何如？岐伯曰：君位臣則順，臣位君則逆。逆則其病近，其害速；順則其病遠，其害微；所謂二火也。","sortOrder":26},
  {"id":"s_work_hdnk_68_27","chapterId":"ch_work_hdnk_68","text":"帝曰：善。願聞其步何如？岐伯曰：所謂步者，六十度而有奇。故二十四步積盈百刻而成曰也。","sortOrder":27},
  {"id":"s_work_hdnk_68_28","chapterId":"ch_work_hdnk_68","text":"帝曰：六氣應五行之變何如？岐伯曰：位有終始，氣有初中，上下不同，求之亦異也。","sortOrder":28},
  {"id":"s_work_hdnk_68_29","chapterId":"ch_work_hdnk_68","text":"帝曰：求之奈何？岐伯曰：天氣始於甲，地氣始於子，子甲相合，命日歲立，謹候其時，氣可與期。","sortOrder":29},
  {"id":"s_work_hdnk_68_30","chapterId":"ch_work_hdnk_68","text":"帝曰：願聞其歲六氣，始終早晏何如？岐伯曰：明乎哉問也。甲子之歲，初之氣，天數始於水下一刻，終於八十七刻半。二之氣，始於八十七刻六分，終於七十五刻。三之氣，始於七十六刻，終於六十二刻半。四之氣，始於六十二刻六分，終於五十刻。五之氣，始於五十一刻，終於三十七刻半。六之氣，始於三十七刻六分，終於二十五刻。所謂初六天之數也。","sortOrder":30},
  {"id":"s_work_hdnk_68_31","chapterId":"ch_work_hdnk_68","text":"乙丑歲，初之氣，天數始於二十六刻，終於一十二刻半。二之氣，始於一十二刻六分，終於水下百刻。三之氣，始於一刻，終於八十七刻半。四之氣，始於八十七刻六分，終於七十五刻。五之氣，始於七十六刻，終於六十二刻半。六之氣，始於六十二刻六分，終於五十刻。所謂六二天之數也。","sortOrder":31},
  {"id":"s_work_hdnk_68_32","chapterId":"ch_work_hdnk_68","text":"丙寅歲，初之氣，天數始於五十一刻，終於三十七刻半。二之氣，始於三十七刻六分，終於二十五刻。三之氣，始於二十六刻，終於一十二刻半。四之氣，始於一十二刻六分，終於水下百刻。五之氣，始於一刻，終於八十七刻半。六之氣，始於八十七刻六分，終於七十五刻。所謂六三天之數也。","sortOrder":32},
  {"id":"s_work_hdnk_68_33","chapterId":"ch_work_hdnk_68","text":"丁卯歲，初之氣，天數始於七十六刻，終於六十二刻半。二之氣，始於六十二刻六分，終於五十刻。三之氣，始於五十一刻，終於三十七刻半。四之氣，始於三十七刻六分，終於二十五刻。五之氣，始於二十六刻，終於一十二刻半。六之氣，始於一十二刻六分，刻於下水百刻。所謂六四天之數也。次戊辰歲初之氣復，始於一刻，常如是無已，周而復始。","sortOrder":33},
  {"id":"s_work_hdnk_68_34","chapterId":"ch_work_hdnk_68","text":"帝曰：願聞其歲候何如？岐伯曰：悉乎哉問也。日行一周，天氣始於一刻。日行再周，天氣始於二十六刻。日行三周，天氣始於五十一刻。日行四周，天氣始於七十六刻。日行五周，天氣復始於一刻，所謂一紀也。","sortOrder":34},
  {"id":"s_work_hdnk_68_35","chapterId":"ch_work_hdnk_68","text":"是故寅午戌歲氣會同，卯未亥歲氣會同，辰申子歲氣會同，已酉丑歲氣會同，終而復始。","sortOrder":35},
  {"id":"s_work_hdnk_68_36","chapterId":"ch_work_hdnk_68","text":"帝曰：願聞其用也。岐伯曰：言天者求之本，言地者求之位，言人者求之氣交。","sortOrder":36},
  {"id":"s_work_hdnk_68_37","chapterId":"ch_work_hdnk_68","text":"帝曰：何謂氣交？岐伯曰：上下之位，氣交之中，人之居也。","sortOrder":37},
  {"id":"s_work_hdnk_68_38","chapterId":"ch_work_hdnk_68","text":"故曰：天樞之上，天氣主之；天樞之下，地氣主之；氣交之分，人氣從之，萬物由之，此之謂也。","sortOrder":38},
  {"id":"s_work_hdnk_68_39","chapterId":"ch_work_hdnk_68","text":"帝曰：何謂初中？岐伯曰：初凡三十度而有奇？中氣同法。","sortOrder":39},
  {"id":"s_work_hdnk_68_40","chapterId":"ch_work_hdnk_68","text":"帝曰：初中何也？岐伯曰：所以分天地也。","sortOrder":40},
  {"id":"s_work_hdnk_68_41","chapterId":"ch_work_hdnk_68","text":"帝曰：願卒聞之？岐伯曰：初者地氣也，中者天氣也。","sortOrder":41},
  {"id":"s_work_hdnk_68_42","chapterId":"ch_work_hdnk_68","text":"帝曰：其升降何如？岐伯曰：氣之升降，天地之更用也。","sortOrder":42},
  {"id":"s_work_hdnk_68_43","chapterId":"ch_work_hdnk_68","text":"帝曰：願聞其用何如？岐伯曰：升已而降，降者謂天；降已而升，升者謂地。","sortOrder":43},
  {"id":"s_work_hdnk_68_44","chapterId":"ch_work_hdnk_68","text":"天氣下降，氣流於地，地氣上升，氣騰於天，故高下相召，升降相因，而變作矣。","sortOrder":44},
  {"id":"s_work_hdnk_68_45","chapterId":"ch_work_hdnk_68","text":"帝曰：善。寒濕相遘，燥熱相臨，風火相值，其有聞手？","sortOrder":45},
  {"id":"s_work_hdnk_68_46","chapterId":"ch_work_hdnk_68","text":"岐伯曰：氣有勝復，勝復之作，有德有化，有用有變，變則邪氣居之。","sortOrder":46},
  {"id":"s_work_hdnk_68_47","chapterId":"ch_work_hdnk_68","text":"帝曰：何謂邪乎？岐伯曰：夫物之生，從於化，物之極，由乎變，變化之相薄，成敗之所由也。","sortOrder":47},
  {"id":"s_work_hdnk_68_48","chapterId":"ch_work_hdnk_68","text":"故氣有往復，用有遲速，四者之有，而化而變，風之來也。","sortOrder":48},
  {"id":"s_work_hdnk_68_49","chapterId":"ch_work_hdnk_68","text":"帝曰：遲速往復，風所由生，而化而變，故因盛衰之變耳。成敗倚伏遊乎中，何也？","sortOrder":49},
  {"id":"s_work_hdnk_68_50","chapterId":"ch_work_hdnk_68","text":"岐伯曰：成敗倚伏，生乎動，動而不已，則變作矣。","sortOrder":50},
  {"id":"s_work_hdnk_68_51","chapterId":"ch_work_hdnk_68","text":"帝曰：有期乎？岐伯曰：不生不化，靜之期也。","sortOrder":51},
  {"id":"s_work_hdnk_68_52","chapterId":"ch_work_hdnk_68","text":"帝曰：不生化乎？岐伯曰：出入廢，則神機化滅；升降息，則氣立孤危。","sortOrder":52},
  {"id":"s_work_hdnk_68_53","chapterId":"ch_work_hdnk_68","text":"故非出入，則無以生、長、壯、老、已；非升降，則無以生、長、化、收、藏。","sortOrder":53},
  {"id":"s_work_hdnk_68_54","chapterId":"ch_work_hdnk_68","text":"故器者，生化之宇，器散則分之，生化息矣。故無不出入，無不升降。","sortOrder":54},
  {"id":"s_work_hdnk_68_55","chapterId":"ch_work_hdnk_68","text":"化有小大，期有近遠。","sortOrder":55},
  {"id":"s_work_hdnk_68_56","chapterId":"ch_work_hdnk_68","text":"四者之有而貴常守，反常則災害至矣。","sortOrder":56},
  {"id":"s_work_hdnk_68_57","chapterId":"ch_work_hdnk_68","text":"故曰：無形無患，此之謂也。","sortOrder":57},
  {"id":"s_work_hdnk_68_58","chapterId":"ch_work_hdnk_68","text":"帝曰：善。有不生不化乎？岐伯曰：悉乎哉問也？與道合同，惟真人也。帝曰：善。","sortOrder":58},
  {"id":"s_work_hdnk_69_1","chapterId":"ch_work_hdnk_69","text":"氣交變大論篇第六十九","sortOrder":1},
  {"id":"s_work_hdnk_69_2","chapterId":"ch_work_hdnk_69","text":"黃帝問曰：五運更治，上應天期，陰陽往復，寒暑迎隨，真邪相薄，內外分離，六經波蕩，五氣傾移，太過不及，專勝兼並，願言其始，而有常名，可得聞乎？","sortOrder":2},
  {"id":"s_work_hdnk_69_3","chapterId":"ch_work_hdnk_69","text":"岐伯稽首再拜對曰：昭乎哉問也！是明道也。此上帝所貴，先師傳之，臣雖不敏，往聞其旨。","sortOrder":3},
  {"id":"s_work_hdnk_69_4","chapterId":"ch_work_hdnk_69","text":"帝曰：餘聞得其人不教，是謂失道，傳非其人，慢泄天寶。餘誠菲德，未足以受至道；然而眾子哀其不終，願夫子保於無窮，流於無極，餘司其事，則而行之，奈何？","sortOrder":4},
  {"id":"s_work_hdnk_69_5","chapterId":"ch_work_hdnk_69","text":"岐伯曰：請遂言之也。上經曰：夫道者，上知天文，下知地理，中知人事，可以長久，此之謂也。","sortOrder":5},
  {"id":"s_work_hdnk_69_6","chapterId":"ch_work_hdnk_69","text":"帝曰：何謂也？岐伯曰：本氣位也。位天者，天文也。地位者，地理也。通於人氣之變化者，人事也。故太過者先天，不及者後天，所謂治化而人應之也。","sortOrder":6},
  {"id":"s_work_hdnk_69_7","chapterId":"ch_work_hdnk_69","text":"帝曰：五運之化，太過何如？","sortOrder":7},
  {"id":"s_work_hdnk_69_8","chapterId":"ch_work_hdnk_69","text":"岐伯曰：歲木太過，風氣流行，脾土受邪。民病飧泄，食減體重，煩冤、腸嗚、腹支滿，上應歲星。甚則忽忽善怒，眩冒巔疾，化氣不政，生氣獨治，雲物飛動，草木不寧，甚而搖落，反脅痛而吐甚，沖陽絕者，死不治，上應太白星。","sortOrder":8},
  {"id":"s_work_hdnk_69_9","chapterId":"ch_work_hdnk_69","text":"歲火太過，炎暑流行，金肺受邪。民病瘧，少氣、咳喘、血嗌、血泄、註下、溢燥、耳聾、中熱、肩背熱，上應熒惑星。甚則胸中痛，脅支滿，脅痛、膺背肩胛間痛，兩臂內痛，身熱骨痛而為浸淫。收氣不行，長氣獨明，雨水霜寒，上應辰星。上臨少陰少陽，火燔〈火苪〉，冰（水？）泉涸，物焦槁，病反譫妄狂越，咳喘息嗚，下甚，血溢泄不已，太淵絕者，死不治，上應熒惑星。","sortOrder":9},
  {"id":"s_work_hdnk_69_10","chapterId":"ch_work_hdnk_69","text":"歲土太過，雨濕流行，腎水受邪。民病腹痛，清厥、意不樂、體重煩冤、上應鎮星。甚則肌肉痿，足痿不收行，善瘈，腳下痛、飲發中滿、食減、四肢不舉。變生得位，藏氣伏化，氣獨治之，泉湧河衍，涸澤生魚，風雨大至，土崩潰，鱗見於陸，病腹滿溏泄，腸嗚，反下甚，而太谿絕者，死不治。上應歲星。","sortOrder":10},
  {"id":"s_work_hdnk_69_11","chapterId":"ch_work_hdnk_69","text":"歲金太過，燥氣流行，肝木受邪。民病兩脅下，少腹痛，目赤痛、眥瘍、耳無所聞。肅殺而甚，則體重煩冤，胸痛引背，兩脅滿且痛引少腹，上應太白星。甚則喘咳逆氣，肩背痛；尻陰股膝髀腨胻足皆病，上應熒惑星。收氣峻，生氣下，草木歛，蒼乾雕隕，病反暴痛，胠脅不可反側，咳逆甚而血溢，太沖絕者，死不治。上應太白星。","sortOrder":11},
  {"id":"s_work_hdnk_69_12","chapterId":"ch_work_hdnk_69","text":"歲水太過，寒氣流行，邪害心火。民病身熱煩心，躁悸、陰厥、上下中寒、譫妄心痛、寒氣早至，上應辰星。甚則腹大脛腫，喘咳寢汗出，憎風，大雨至，埃霧朦鬱，上應鎮星。上臨太陽，雨冰雪霜不時降，濕氣變物，病反腹滿腸嗚溏泄，食不化，渴而妄冒，神門絕者，死不治，上應熒惑辰星。","sortOrder":12},
  {"id":"s_work_hdnk_69_13","chapterId":"ch_work_hdnk_69","text":"帝曰：善。其不及何如？","sortOrder":13},
  {"id":"s_work_hdnk_69_14","chapterId":"ch_work_hdnk_69","text":"岐伯曰：悉乎哉問也！歲木不及，燥乃大行，生氣失應，草木晚榮，肅殺而甚，則剛木辟者，悉萎蒼乾，上應太白星。民病中清，胠脅痛，少腹痛，腸嗚、溏泄。涼雨時至，上應太白星，其穀蒼。上臨陽明，生氣失政，草木再榮，化氣乃急，上應太白鎮星，其主蒼早。復則炎暑流火，濕性燥，柔脆草木焦槁，下體再生，華實齊化，病寒熱瘡瘍痱胗癰痤，上應熒惑太白，其穀白堅。白露早降，收殺氣行，寒雨害物，蟲食甘黃，脾土受邪，赤氣後化，心氣晚治，上勝肺金，白氣乃屈，其穀不成，咳而鼽，上應熒惑太白星。","sortOrder":14},
  {"id":"s_work_hdnk_69_15","chapterId":"ch_work_hdnk_69","text":"歲火不及，寒乃大行，長政不用，物榮而下。凝慘而甚，則陽氣不化，乃折榮美，上應辰星。民病胸中痛、脅支滿，兩脅痛，膺背肩胛間及兩臂內痛，鬱冒蒙眛，心痛暴喑，胸復大，脅下與腰背相引而痛，甚則屈不能伸，髖髀如別，上應熒惑辰星，其穀丹。復則埃鬱，大雨且至，黑氣乃辱，病騖溏腹滿食飲不下寒中，腸嗚泄註，腹痛暴攣痿痺，足不任身，上應鎮星辰星，玄穀不成。","sortOrder":15},
  {"id":"s_work_hdnk_69_16","chapterId":"ch_work_hdnk_69","text":"歲土不及，風乃大行，化氣不令，草木茂榮。飄揚而甚，秀而不實，上應歲星。民病飧泄霍亂，體重腹痛，筋骨繇復，肌肉瞤酸，善怒，臟氣舉事，蟄蟲早附，鹹病寒中，上應歲星鎮星，其穀黅。復則收政嚴峻，名木蒼雕，胸脅暴痛，下引少腹，善太息，蟲食甘黃，氣客於脾，黅穀乃減，民食少失味，蒼穀乃損，上應太白歲星。上臨厥陰，流水不冰，蟄蟲來見，臟氣不用，白乃不復，上應歲星，民乃康。","sortOrder":16},
  {"id":"s_work_hdnk_69_17","chapterId":"ch_work_hdnk_69","text":"歲金不及，炎火乃行，生氣乃用，長氣專勝，庶物以茂，燥爍以行，上應熒惑星。民病肩背瞀重，鼽嚏、血便註下，收氣乃後，上應太白星，其穀堅芒。復則寒雨暴至乃零，冰雹霜雪殺物，陰厥且格，陽反上行，頭腦戶痛，延及窗頂，發熱，上應辰星，丹穀不成，民病口瘡，甚則心痛。","sortOrder":17},
  {"id":"s_work_hdnk_69_18","chapterId":"ch_work_hdnk_69","text":"歲水不及，濕乃大行，長氣反用，其化乃速，暑雨數至，上應鎮星。民病腹滿，身重濡泄，寒瘍流水，腰股痛發，膕腨股膝不便，煩冤、足痿清厥，腳下痛，甚則胕腫，藏氣不政，腎氣不衡，上應辰星，其穀秬。上臨太陰，則大寒數舉，蟄蟲早藏，地積堅冰，陽光不治，民病寒疾於下，甚則腹滿浮腫，上應鎮星，其主黅穀。復則大風暴發，草偃木零，生長不鮮，面色時變，筋骨並辟，肉瞤瘈，目視〈流，氵改目〉〈流，氵改目〉，物疏璺，肌肉胗發，氣並膈中，痛於心腹，黃氣乃損，其穀不登，上應歲星。","sortOrder":18},
  {"id":"s_work_hdnk_69_19","chapterId":"ch_work_hdnk_69","text":"帝曰：善。願聞其時也。","sortOrder":19},
  {"id":"s_work_hdnk_69_20","chapterId":"ch_work_hdnk_69","text":"岐伯曰：悉哉問也？木不及，春有鳴條律暢之化，則秋有霧露清涼之政。春有慘淒殘賤之勝，則夏有炎暑燔爍之復。其眚東，其臟肝，其病內舍胠脅，外在關節。","sortOrder":20},
  {"id":"s_work_hdnk_69_21","chapterId":"ch_work_hdnk_69","text":"火不及，夏有炳明光顯之化，則冬有嚴肅霜寒之政。夏有慘淒凝冽之勝，則不時有埃昏大雨之復。其眚南，其臟心，其病內舍膺脅，外在經絡。","sortOrder":21},
  {"id":"s_work_hdnk_69_22","chapterId":"ch_work_hdnk_69","text":"土不及，四維有埃雲潤澤之化，則春有鳴條鼓拆之政。四維發振拉飄騰之變，則秋有肅殺霖霪之復。其眚四維，其臟脾，其病內舍心腹，外在肌肉四肢。","sortOrder":22},
  {"id":"s_work_hdnk_69_23","chapterId":"ch_work_hdnk_69","text":"金不及，夏有光顯鬱蒸之令，則冬有嚴凝整肅之應，夏有炎爍燔燎之變，則秋有冰雹霜雪之復。其眚西，其臟肺，其病內舍膺脅肩背，外在皮毛。","sortOrder":23},
  {"id":"s_work_hdnk_69_24","chapterId":"ch_work_hdnk_69","text":"水不及，四維有湍潤埃雲之化，則不時有和風生發之應。四維發埃昏驟註之變，則不時有飄蕩振拉之復。其眚北，其臟腎，其病內舍腰脊骨髓，外在溪穀踹膝。","sortOrder":24},
  {"id":"s_work_hdnk_69_25","chapterId":"ch_work_hdnk_69","text":"夫五運之政，猶權衡也，高者抑之，下者舉之，化者應之，變者復之，此生長化成收藏之理，氣之常也，失常則天地四塞矣。故曰天地之動靜，神明為之紀，陰陽之往復，寒暑彰其兆，此之謂也。","sortOrder":25},
  {"id":"s_work_hdnk_69_26","chapterId":"ch_work_hdnk_69","text":"帝曰：夫子之言五氣之變，四時之應，可謂悉矣，夫氣之動亂，觸遇而作，發無常會，卒然災合，何以期之？","sortOrder":26},
  {"id":"s_work_hdnk_69_27","chapterId":"ch_work_hdnk_69","text":"岐伯曰：天氣之動變，固不常在，而德化政令災變，不同其候也。","sortOrder":27},
  {"id":"s_work_hdnk_69_28","chapterId":"ch_work_hdnk_69","text":"帝曰：何謂也？岐伯曰：東方生風，風生木，其德敷和，其化生榮，其政舒啟，其令風，其變振發，其災散落。","sortOrder":28},
  {"id":"s_work_hdnk_69_29","chapterId":"ch_work_hdnk_69","text":"南方生熱，熱生火，其德彰顯，其化蕃茂，其政明耀，其令熱，其變銷爍，其災燔〈火苪〉。","sortOrder":29},
  {"id":"s_work_hdnk_69_30","chapterId":"ch_work_hdnk_69","text":"中央生濕，濕生土，其德溽蒸，其化豐備，其政安靜，其令濕，其變驟註，其災霖潰。","sortOrder":30},
  {"id":"s_work_hdnk_69_31","chapterId":"ch_work_hdnk_69","text":"西方生燥，燥生金，其德清潔，其化緊歛，其政勁切，其令燥，其變肅殺，其災蒼隕。","sortOrder":31},
  {"id":"s_work_hdnk_69_32","chapterId":"ch_work_hdnk_69","text":"北方生寒，寒生水，其德淒滄，其化清謐，其政凝肅，其令寒，其變慄冽，其災冰雪霜雹。","sortOrder":32},
  {"id":"s_work_hdnk_69_33","chapterId":"ch_work_hdnk_69","text":"是以察其動色，有德，有化、有政、有令、有變、有災，而物由之，而人應之也。","sortOrder":33},
  {"id":"s_work_hdnk_69_34","chapterId":"ch_work_hdnk_69","text":"帝曰：夫子之言歲候不及，其太過而上應五星，今夫德化政令災眚變易非常而有也，卒然而動，其亦為之變乎？","sortOrder":34},
  {"id":"s_work_hdnk_69_35","chapterId":"ch_work_hdnk_69","text":"岐伯曰：承天而行之，故無妄動，無不應也。卒然而動者，氣之交變也，其不應焉。故曰應常不應卒，此之謂也。","sortOrder":35},
  {"id":"s_work_hdnk_69_36","chapterId":"ch_work_hdnk_69","text":"黃帝曰：其應奈何？岐伯曰：各從其氣化也。","sortOrder":36},
  {"id":"s_work_hdnk_69_37","chapterId":"ch_work_hdnk_69","text":"黃帝曰：其行之徐疾逆順何如？","sortOrder":37},
  {"id":"s_work_hdnk_69_38","chapterId":"ch_work_hdnk_69","text":"岐伯曰：以道留久，逆守而小，是謂省下。","sortOrder":38},
  {"id":"s_work_hdnk_69_39","chapterId":"ch_work_hdnk_69","text":"以道而去，去而速來，曲而過之，是謂省遺過也。","sortOrder":39},
  {"id":"s_work_hdnk_69_40","chapterId":"ch_work_hdnk_69","text":"久留而環，或離或附，是謂議災，與其德也。","sortOrder":40},
  {"id":"s_work_hdnk_69_41","chapterId":"ch_work_hdnk_69","text":"應近則小，應遠則大。","sortOrder":41},
  {"id":"s_work_hdnk_69_42","chapterId":"ch_work_hdnk_69","text":"芒而大，倍常之一，其化甚，大常之二，其眚即也；小常之一，其化減；小常之二，是謂臨視，省下之過與其德也，德者福之，過者伐之。","sortOrder":42},
  {"id":"s_work_hdnk_69_43","chapterId":"ch_work_hdnk_69","text":"是以象之見也，高而遠則小，下而近則大，故大則喜怒邇，小則禍福遠。","sortOrder":43},
  {"id":"s_work_hdnk_69_44","chapterId":"ch_work_hdnk_69","text":"歲運太過，則運星北越。運氣相得，則各行以道。","sortOrder":44},
  {"id":"s_work_hdnk_69_45","chapterId":"ch_work_hdnk_69","text":"故歲運太過，畏星失色，而兼其母；不及則色兼其所不勝。","sortOrder":45},
  {"id":"s_work_hdnk_69_46","chapterId":"ch_work_hdnk_69","text":"肖者瞿瞿，莫知其妙，閔閔之當，孰者為良，妄行無徵，示畏侯王。","sortOrder":46},
  {"id":"s_work_hdnk_69_47","chapterId":"ch_work_hdnk_69","text":"帝曰：其災應何如？岐伯曰：亦各從其化也，故時至有盛衰，凌犯有逆順，留守有多少，形見有善惡，宿屬有勝負，徵應有吉凶矣。","sortOrder":47},
  {"id":"s_work_hdnk_69_48","chapterId":"ch_work_hdnk_69","text":"帝曰：其善惡何謂也？岐伯曰：有喜有怒，有憂有喪，有澤有燥，此象之常也，必謹察之。","sortOrder":48},
  {"id":"s_work_hdnk_69_49","chapterId":"ch_work_hdnk_69","text":"帝曰：六者高下異乎？岐伯曰：象見高下，其應一也，故人亦應之。","sortOrder":49},
  {"id":"s_work_hdnk_69_50","chapterId":"ch_work_hdnk_69","text":"帝曰：善。其德化政令之動靜損益皆何如？岐伯曰：夫德化政令災變，不能相加也；勝負盛衰，不能相多也；往來小大，不能相過也；用之升降，不能相無也；各從其動而復之耳。","sortOrder":50},
  {"id":"s_work_hdnk_69_51","chapterId":"ch_work_hdnk_69","text":"帝曰：其病生何如？岐伯曰：德化者，氣之祥；政令者，氣之章；變易者，復之紀；災眚者，傷之始；氣相勝者和，不相勝者病；重感於邪則甚也。","sortOrder":51},
  {"id":"s_work_hdnk_69_52","chapterId":"ch_work_hdnk_69","text":"帝曰：善。所謂精光之論，大聖之業，宣明大道，通於無窮，究於無極也。餘聞之善言天者，必應於人，善言古者，必驗於今，善言氣者，必彰於物，善言應者，同天地之化，善言化言變者，通神明之理，非夫子孰能言至道歟。乃擇良兆而藏之靈室，每旦讀之，命曰氣交變，非齋戒不敢發，慎傳也。","sortOrder":52},
  {"id":"s_work_hdnk_70_1","chapterId":"ch_work_hdnk_70","text":"五常致大論篇第七十","sortOrder":1},
  {"id":"s_work_hdnk_70_2","chapterId":"ch_work_hdnk_70","text":"黃帝問曰：太虛寥廓，五運回薄，盛衰不同，損益相從，願聞平氣，何如而名，何如而紀也？岐伯對曰：昭乎哉問也；木曰敷和，火曰升明，土曰備化，金曰審平，水曰靜順。","sortOrder":2},
  {"id":"s_work_hdnk_70_3","chapterId":"ch_work_hdnk_70","text":"帝曰：其不及奈何？岐伯曰：木曰委和，火曰伏明，土曰卑監，金曰從革，水曰涸流。","sortOrder":3},
  {"id":"s_work_hdnk_70_4","chapterId":"ch_work_hdnk_70","text":"帝曰：太過何謂？岐伯曰：木曰發生，火曰赫曦，土曰敦阜，金曰堅成，水曰流衍。","sortOrder":4},
  {"id":"s_work_hdnk_70_5","chapterId":"ch_work_hdnk_70","text":"帝曰：三氣之紀，願聞其候。岐伯曰：悉乎哉問也！敷和之紀，木德周行，陽舒陰布，五化宣平。其氣端，其性隨，其用曲直，其化生榮，其類草木，其政發散，其候溫和，其令風，其臟肝，肝其畏清；其主目，其穀麻，其果李，其實核，其應春，其蟲毛，其畜犬，其色蒼；其養筋，其病裏急支滿，其味酸，其音角，其物中堅，其數八。","sortOrder":5},
  {"id":"s_work_hdnk_70_6","chapterId":"ch_work_hdnk_70","text":"升明之紀，正陽而治，德施周普，五化均衡。其氣高，其性速，其用燔灼，其化蕃茂，其類火，其政明曜，其候炎暑，其令熱，其臟心，心其畏寒，其主舌，其穀麥，其果杏，其實絡，其應夏，其蟲羽，其畜馬，其色赤；其養血，其病瞤瘈，其味苦，其音徵，其物脈，其數七。","sortOrder":6},
  {"id":"s_work_hdnk_70_7","chapterId":"ch_work_hdnk_70","text":"備化之紀，氣協天休，德流四政，五化齊修。其氣平，其性順，其用高下，其化豐滿，其類土，其政安靜，其候溽蒸，其令濕，其臟脾，脾其畏風；其主口，其穀稷，其果棗，其實肉，其應長夏，其蟲倮，其畜牛，其色黃，其養肉，其病否，其味甘，其音宮，其物膚，其數五。","sortOrder":7},
  {"id":"s_work_hdnk_70_8","chapterId":"ch_work_hdnk_70","text":"審平之紀，收而不爭，殺而無犯，五化宣明。其氣潔，其性剛，其用散落，其化堅斂，其類金，其政勁肅，其候清切，其令燥，其臟肺，肺其畏熱；其主鼻，其穀稻，其果桃，其實殼，其應秋，其蟲介，其畜雞，其色白；其養皮毛，其病咳，其味辛，其音商，其物外堅，其數九。","sortOrder":8},
  {"id":"s_work_hdnk_70_9","chapterId":"ch_work_hdnk_70","text":"靜順之紀，藏而勿害，治而善下，五化鹹整。其氣明，其性下，其用沃衍，其化凝堅，其類水，其政流演，其候凝肅，其令寒，其臟腎，腎其畏濕；其主二陰，其穀豆，其果栗，其實濡，其應冬，其蟲鱗，其畜彘，其色黑，其養骨髓，其病厥，其味鹹，其音羽，其物濡，其數六。","sortOrder":9},
  {"id":"s_work_hdnk_70_10","chapterId":"ch_work_hdnk_70","text":"故生而勿殺，長而勿罰，化而勿製，收而勿害，藏而勿抑，是謂平氣。","sortOrder":10},
  {"id":"s_work_hdnk_70_11","chapterId":"ch_work_hdnk_70","text":"委和之紀，是謂勝生，生氣不政，化氣乃揚，長氣自平，收令乃早，涼雨時降，風雲並興，草木晚榮，蒼乾雕落，物秀而實，膚肉內充。其氣斂，其用聚，其動繻淚拘緩，其發驚駭，其臟肝，其果棗李，其實核殼，其穀稷稻，其味辛酸，其色白蒼，其畜犬雞，其蟲毛介，其主霧露淒滄，其聲角商，其病搖動註恐，從金化也。少角與判商同，上角與正角同，上商與正商同。其病支廢癰腫瘡瘍，其甘蟲，邪傷肝也。上宮與正宮同。蕭飋肅殺，則炎赫沸騰，眚於三，所謂覆也，其主飛蠹蛆雉。乃為雷廷。","sortOrder":11},
  {"id":"s_work_hdnk_70_12","chapterId":"ch_work_hdnk_70","text":"伏明之紀，是為勝長。長氣不宣，藏氣反布，收氣自政，化令乃衡，寒清數舉，暑令乃薄，承化物生，生而不長，成實而稚，遇化已老，陽氣屈服，蟄蟲早藏。其氣鬱，其用暴，其動彰伏變易，其發痛，其臟心，其果栗桃，其實絡濡，其穀豆稻，其味苦鹹，其色玄丹，其畜馬彘，其蟲羽鱗，其主冰雪霜寒，其聲徵羽，其病昏惑悲忘。從水化也。少徵與少羽同，上商與正商同。邪傷心也。凝慘栗冽，則暴雨霖霪，眚於九，其主驟註，雷霆震驚，沈霒（音陰義同）淫雨。","sortOrder":12},
  {"id":"s_work_hdnk_70_13","chapterId":"ch_work_hdnk_70","text":"卑監之紀，是謂減化。化氣不令，生政獨彰，長氣整，雨乃愆，收氣平，風寒並興，草木榮美，秀而不實成而秕也。其氣散，其用靜定，其動瘍涌，分潰癰腫，其發濡滯，其臟脾，其果李栗，其實濡核，其穀豆麻，其味酸甘，其色蒼黃，其畜牛犬，其蟲倮毛，其主飄怒振發，其聲宮角，其病流滿否塞，從木化也。少宮與少角同，上宮與正宮同，上角與正角同，其病飧泄，邪傷脾也。振拉飄揚，則蒼乾散落，其眚四維，其主敗折，虎狼清氣乃用，生政乃辱。","sortOrder":13},
  {"id":"s_work_hdnk_70_14","chapterId":"ch_work_hdnk_70","text":"從革之紀，是為折收。收氣乃後，生氣乃揚，長化合德，火政乃宣，庶類以蕃。其氣揚，其用躁切，其動鏗禁瞀厥，其發咳喘，其臟肺，其果李杏，其實殼絡，其穀麻麥，其味苦辛，其色白丹，其畜雞羊，其蟲介羽，其主明曜炎爍，其聲商徵，其病嚏咳鼽衄，從火化也。少商與少徵同，上商與正商同，上角與正角同，邪傷肺也。炎光赫烈，則冰雪霜雹，眚於七，其主鱗伏彘鼠，歲氣早至，乃生大寒。","sortOrder":14},
  {"id":"s_work_hdnk_70_15","chapterId":"ch_work_hdnk_70","text":"涸流之紀，是為反陽，藏令不舉，化氣乃昌，長氣宣布，蟄蟲不藏，土潤水泉減，草木條茂，榮秀滿盛。其氣滯，其用滲泄，其動堅止其發燥槁，其臟腎，其果棗杏，其實濡肉，其穀黍稷，其味甘鹹，其色黅玄，其畜彘牛，其蟲鱗倮，其主埃鬱昏翳，其聲羽宮，其病痿厥堅下，從土化也。少羽與少宮同，上宮與正宮同，其病癃閎，邪傷腎也。埃昏驟雨，則振拉摧拔，眚於一，其主毛濕狐貉，變化不藏。","sortOrder":15},
  {"id":"s_work_hdnk_70_16","chapterId":"ch_work_hdnk_70","text":"故乘危而行，不速而至，暴瘧無德，災反及之，微者復微，甚者復甚，氣之常也。","sortOrder":16},
  {"id":"s_work_hdnk_70_17","chapterId":"ch_work_hdnk_70","text":"發生之紀，是為啟陳。土疏泄，蒼氣達，陽和布化，陰氣乃隨，生氣淳化，萬物以榮。其化生，其氣美，其政散，其令條舒，其動掉眩巔疾，其德鳴靡啟坼，其變振拉摧拔，其穀麻稻，其畜雞犬，其果李桃，其色青黃白，其味酸甘辛，其象春，其經足厥陰少陽，其臟肝脾，其蟲毛介，其物中堅外堅，其病怒。太角與上商同。上徵則其氣逆，其病吐利。不務其德，則收氣復，秋氣勁切，甚則肅殺，清氣大至，草木雕零，邪乃傷肝。","sortOrder":17},
  {"id":"s_work_hdnk_70_18","chapterId":"ch_work_hdnk_70","text":"赫曦之紀，是為蕃茂。陰氣內化，陽氣外榮，炎暑施化，物得以昌。其化長，其氣高，其政動，其令明顯，其動炎灼妄擾，其德喧暑鬱蒸，其變炎烈沸騰，其穀麥豆，其畜羊彘，其果杏栗，其色赤白玄，其味苦辛鹹，其象夏，其經手少陰太陽，手厥陰少陽，其臟心肺，其蟲羽鱗，其物脈濡，其病笑瘧瘡瘍血流狂妄目赤。上羽與正徵同。其收齊，其病痓，上徵而收氣後也。暴烈其政，藏氣乃復，時見凝慘，甚則雨水，霜雹、切寒、邪傷心也。","sortOrder":18},
  {"id":"s_work_hdnk_70_19","chapterId":"ch_work_hdnk_70","text":"敦阜之紀，是為廣化。厚德清靜，順長以盈，至陰內實，物化充成。煙埃朦鬱，見於厚土，大雨時行，濕氣乃用，燥政乃辟。其化圓，其氣豐，其政靜，其令周備，其動濡積並蓄，其德柔潤重淖，其變震驚，飄驟崩潰，其穀稷麻，其畜牛犬，其果棗李，其色黅玄蒼，其味甘鹹酸，其象長夏，其經足太陰陽明，其臟脾腎，其蟲倮毛，其物肌核，其病腹滿，四支不舉，大風迅至，邪傷脾也。","sortOrder":19},
  {"id":"s_work_hdnk_70_20","chapterId":"ch_work_hdnk_70","text":"堅成之紀，是為收引。天氣潔，地氣明，陽氣隨陰治化，燥行其政，物以司成，收氣繁布，化洽不終。其化成，其氣削，其政肅，其令銳切，其動暴折瘍疰，其德霧露蕭飋，其變肅殺雕零，其穀稻黍，其畜雞馬，其果桃杏，其色白青丹，其味辛酸苦，其象秋，其經手太陰陽明，其臟肺肝，其蟲介羽，其物殼絡，其病喘喝，胸凭仰息。上徵與正商同。其生齊，其病咳。政暴變，則名木不榮，柔脆焦首，長氣斯救，大火流炎，爍且至，蔓將槁，邪傷肺也。","sortOrder":20},
  {"id":"s_work_hdnk_70_21","chapterId":"ch_work_hdnk_70","text":"流衍之紀，是為封藏。寒司物化，天地嚴凝，藏政以布，長令不揚。其化凜，其氣堅，其政謐，其令流註，其動漂泄沃涌，其德凝慘寒雰，其變冰雪霜雹，其穀豆稷，其畜彘牛，其果栗棗，其色黑丹黅，其味鹹苦甘，其象冬其經足少陰太陽，其臟腎心，其蟲鱗倮，其物濡滿，其病脹。上羽而長氣不化也。政過則化氣大舉，而埃昏氣交，大雨時降，邪傷腎也。","sortOrder":21},
  {"id":"s_work_hdnk_70_22","chapterId":"ch_work_hdnk_70","text":"故曰：天恒其德，則所勝來復；政恒其理，則所勝同化，此之謂也。","sortOrder":22},
  {"id":"s_work_hdnk_70_23","chapterId":"ch_work_hdnk_70","text":"帝曰：天不足西北，左寒而右涼；地不滿東南，右熱而左溫，其故何也？岐伯曰：陰陽之氣，高下之理，太少之異也。東南方，陽也，陽者，其精降於下，故右熱而左溫。西北方，陰也。陰者，其精奉於上，故左寒而右涼。是以地有高下，氣有溫涼。高者氣寒，下者氣熱，故適寒涼者脹之，溫熱者瘡，下之則脹已，汗之則瘡已，此腠理開閉之常，太少之異耳。","sortOrder":23},
  {"id":"s_work_hdnk_70_24","chapterId":"ch_work_hdnk_70","text":"帝曰：其於壽夭，何如？岐伯曰：陰精所奉其人壽；陽精所降其人夭。","sortOrder":24},
  {"id":"s_work_hdnk_70_25","chapterId":"ch_work_hdnk_70","text":"帝曰：善。其病也，治之奈何？岐伯曰：西北之氣，散而寒之，東南之氣，收而溫之，所謂同病異治也。故曰氣寒氣涼，治以寒涼，行水漬之；氣溫氣熱，治以溫熱，強其內守，必同其氣，可使平也，假者反之。","sortOrder":25},
  {"id":"s_work_hdnk_70_26","chapterId":"ch_work_hdnk_70","text":"帝曰：善。一州之氣，生化壽夭不同，其故何也？岐伯曰：高下之理，地勢使然也。崇高則陰氣治之，污下則陽氣治之，陽勝者先天，陰勝者後天，此地理之常，生化之道也。","sortOrder":26},
  {"id":"s_work_hdnk_70_27","chapterId":"ch_work_hdnk_70","text":"帝曰：其有壽夭乎？岐伯曰：高者其氣壽，下者其氣夭，地之大小異也。小者小異，大者大異，故治病者，必明天道地理，陰陽更勝，氣之先後，人之壽夭，生化之期，乃可以知人之形氣矣。","sortOrder":27},
  {"id":"s_work_hdnk_70_28","chapterId":"ch_work_hdnk_70","text":"帝曰：善。其歲有不病，而藏氣不應不用者，何也？岐伯曰：天氣製之，氣有所從也。","sortOrder":28},
  {"id":"s_work_hdnk_70_29","chapterId":"ch_work_hdnk_70","text":"帝曰：願卒聞之。岐伯曰：少陽司天，火氣下臨，肺氣上從，白，起金用，草木眚，火見燔焠，革金且耗，大暑以行，咳嚏、鼽衄，鼻窒日瘍，寒熱胕腫。","sortOrder":29},
  {"id":"s_work_hdnk_70_30","chapterId":"ch_work_hdnk_70","text":"風行於地，塵沙飛揚，心痛胃脘痛，厥逆膈不通，其主暴速。","sortOrder":30},
  {"id":"s_work_hdnk_70_31","chapterId":"ch_work_hdnk_70","text":"陽明司天，燥氣下臨，肝氣上從，蒼起木用而立，土乃眚，淒滄數至，木伐草萎，脅痛目赤，掉振鼓栗，筋痿不能久立。","sortOrder":31},
  {"id":"s_work_hdnk_70_32","chapterId":"ch_work_hdnk_70","text":"暴熱至土乃暑，陽氣鬱發，小便變，寒熱如瘧，甚則心痛；火行於槁，流水不冰，蟄蟲乃見。","sortOrder":32},
  {"id":"s_work_hdnk_70_33","chapterId":"ch_work_hdnk_70","text":"太陽司天，寒氣下臨，心氣上從，而火且明。丹起，金乃眚，寒清時舉，勝則水冰，火氣高明，心熱煩，溢乾、善渴、鼽嚏、喜悲數欠，熱氣妄行，寒乃復，霜不時降，善忘，甚則心痛。","sortOrder":33},
  {"id":"s_work_hdnk_70_34","chapterId":"ch_work_hdnk_70","text":"土乃潤，水豐衍，寒客至，沈陰化，濕氣變物，水飲內稽，中滿不食，皮〈疒帬〉肉苛，筋脈不利，甚則胕腫，身後廱。","sortOrder":34},
  {"id":"s_work_hdnk_70_35","chapterId":"ch_work_hdnk_70","text":"厥陰司天，風氣下臨，脾氣上從，而上且隆，黃起，水乃眚，土用革。體重，肌肉萎，食減口爽，風行太虛，雲物搖動，目轉耳鳴。","sortOrder":35},
  {"id":"s_work_hdnk_70_36","chapterId":"ch_work_hdnk_70","text":"火縱其暴，地乃暑，大熱消爍，赤沃下，蟄蟲數見，流水不冰，其發機速。","sortOrder":36},
  {"id":"s_work_hdnk_70_37","chapterId":"ch_work_hdnk_70","text":"少陰司天，熱氣下臨，肺氣上從，白起，金用，草木眚。喘嘔、寒熱、嚏鼽、衄、鼻窒、大暑流行，甚則瘡瘍燔灼，金爍石流。","sortOrder":37},
  {"id":"s_work_hdnk_70_38","chapterId":"ch_work_hdnk_70","text":"地乃燥清，淒滄數至，脅痛、善太息，肅殺行，草木變。","sortOrder":38},
  {"id":"s_work_hdnk_70_39","chapterId":"ch_work_hdnk_70","text":"太陰司天，濕氣下臨，腎氣上從，黑起水變，埃冒雲雨，胸中不利，陰萎氣大衰，而不起不用，當其時，反腰脽痛，動轉不便也，厥逆。","sortOrder":39},
  {"id":"s_work_hdnk_70_40","chapterId":"ch_work_hdnk_70","text":"地乃藏陰，大寒且至，蟄蟲早附，心下痞痛，地烈冰堅，少腹痛，時害於食，乘金則止水增，味乃鹹，行水減也。","sortOrder":40},
  {"id":"s_work_hdnk_70_41","chapterId":"ch_work_hdnk_70","text":"帝曰：歲有胎孕不育，治之不全，何氣使然？岐伯曰：六氣五類，有相勝製也，同者盛之，異者衰之，此天地之道，生化之常也。故厥陰司天，毛蟲靜，羽蟲育，介蟲不成；左泉，毛蟲育，倮蟲耗，羽蟲不育。","sortOrder":41},
  {"id":"s_work_hdnk_70_42","chapterId":"ch_work_hdnk_70","text":"少陰司天，羽蟲靜，介蟲育，毛蟲不成；在泉，羽蟲育，介蟲耗不育。","sortOrder":42},
  {"id":"s_work_hdnk_70_43","chapterId":"ch_work_hdnk_70","text":"太陰司天，倮蟲靜，鱗蟲育，羽蟲不成；在泉，裸蟲育，鱗蟲不成。","sortOrder":43},
  {"id":"s_work_hdnk_70_44","chapterId":"ch_work_hdnk_70","text":"少陽司天，羽蟲靜，毛蟲育，倮蟲不成；在泉，羽蟲育，介蟲耗，毛蟲不育。","sortOrder":44},
  {"id":"s_work_hdnk_70_45","chapterId":"ch_work_hdnk_70","text":"陽明司天，介蟲靜，羽蟲育，介蟲不成；在泉，介蟲育，毛蟲耗，羽蟲不成。","sortOrder":45},
  {"id":"s_work_hdnk_70_46","chapterId":"ch_work_hdnk_70","text":"太陽司天，鱗蟲靜，倮蟲育；在泉，鱗蟲耗，倮蟲不育。","sortOrder":46},
  {"id":"s_work_hdnk_70_47","chapterId":"ch_work_hdnk_70","text":"諸乘所不成之運，則甚也。故氣主有所製，歲立有所生，地氣製己勝，天氣製勝己，天製色，地製形，五類衰盛，各隨其氣之所宜也。故有胎孕不育，治之不全，此氣之常也。","sortOrder":47},
  {"id":"s_work_hdnk_70_48","chapterId":"ch_work_hdnk_70","text":"所謂中根也，根於外者亦五，放生化之別，有五氣，五味，五色，五類，五宜也。","sortOrder":48},
  {"id":"s_work_hdnk_70_49","chapterId":"ch_work_hdnk_70","text":"帝曰：何謂也？岐伯曰：根於中者，命曰神機，神去則機息；根於外者，命曰氣立，氣止則化絕。故各有製，各有勝，各有生，各有成，故曰不知年之所加，氣之同異，不足以言生化，此之謂也。","sortOrder":49},
  {"id":"s_work_hdnk_70_50","chapterId":"ch_work_hdnk_70","text":"帝曰：氣始而生化，氣散而有形，氣布而繁育，氣終而象變，其致一也。然而五味所資，生化有薄厚，成熟有多少，終始不同，其故何也？岐伯曰：地氣製之也，非天不生，地不長也。","sortOrder":50},
  {"id":"s_work_hdnk_70_51","chapterId":"ch_work_hdnk_70","text":"帝曰：願聞其道。岐伯曰：寒熱燥濕不同其化也，故少陽在泉，寒毒不生，其味辛，其治苦酸，其穀蒼丹。","sortOrder":51},
  {"id":"s_work_hdnk_70_52","chapterId":"ch_work_hdnk_70","text":"陽明在泉，濕毒不生，其味酸，其氣濕，其治辛苦甘，其穀丹素。","sortOrder":52},
  {"id":"s_work_hdnk_70_53","chapterId":"ch_work_hdnk_70","text":"太陽在泉，熱毒不生，其味苦，其治淡鹹，其穀黅秬。","sortOrder":53},
  {"id":"s_work_hdnk_70_54","chapterId":"ch_work_hdnk_70","text":"厥陰在泉，清毒不生，其味甘，其治酸苦，其穀蒼赤，其氣專，其味正。","sortOrder":54},
  {"id":"s_work_hdnk_70_55","chapterId":"ch_work_hdnk_70","text":"少陰在泉，寒毒不生，其味辛，其治辛苦甘，其穀白丹。","sortOrder":55},
  {"id":"s_work_hdnk_70_56","chapterId":"ch_work_hdnk_70","text":"太陰在泉，燥毒不生，其味鹹，其氣熱，其治甘鹹，其穀黅秬。","sortOrder":56},
  {"id":"s_work_hdnk_70_57","chapterId":"ch_work_hdnk_70","text":"化淳則鹹守，氣專則辛化而俱知。","sortOrder":57},
  {"id":"s_work_hdnk_70_58","chapterId":"ch_work_hdnk_70","text":"故曰：補上下者從之，治上下者逆之，以所在寒熱盛衰而調之。","sortOrder":58},
  {"id":"s_work_hdnk_70_59","chapterId":"ch_work_hdnk_70","text":"故曰：上取下取，內取外取，以求其過；能毒者以厚藥，不勝毒者以薄藥，此之謂也。","sortOrder":59},
  {"id":"s_work_hdnk_70_60","chapterId":"ch_work_hdnk_70","text":"氣反者，病在上，取之下；病在下，取之上；病在中，傍取之。","sortOrder":60},
  {"id":"s_work_hdnk_70_61","chapterId":"ch_work_hdnk_70","text":"治熱以寒，溫而行之；治寒以熱，涼而行之；治溫以清，冷而行之；治清以溫，熱而行之。","sortOrder":61},
  {"id":"s_work_hdnk_70_62","chapterId":"ch_work_hdnk_70","text":"故消之削之，吐之下之，補之瀉之，久新同法。","sortOrder":62},
  {"id":"s_work_hdnk_70_63","chapterId":"ch_work_hdnk_70","text":"帝曰：病在中而不實不堅，且聚且散，奈何？岐伯曰：悉乎哉問也！無積者求其臟，虛則補之，藥以祛之，食以隨之，行水漬之，和其中外，可使畢已。","sortOrder":63},
  {"id":"s_work_hdnk_70_64","chapterId":"ch_work_hdnk_70","text":"帝曰：有毒無毒，服有約乎？岐伯曰：病有久新，方有大小，有毒無毒，固宜常製矣。大毒治病，十去其六，常毒治病，十去其七，小毒治病，十去其八，無毒治病，十去其九。穀肉果菜，食養盡之，無使過之，傷其正也。","sortOrder":64},
  {"id":"s_work_hdnk_70_65","chapterId":"ch_work_hdnk_70","text":"不盡，行復如法，必先歲氣，無伐天和，無盛盛，無虛虛，而遺人天殃，無致邪，無失正，絕人長病。","sortOrder":65},
  {"id":"s_work_hdnk_70_66","chapterId":"ch_work_hdnk_70","text":"帝曰：其久病者，有氣從不康，病去而瘠奈何？岐伯曰：昭乎哉！聖人之問也，化不可代，時不可違。夫經絡以通，血氣以從，復其不足，與眾齊同，養之和之，靜以待時，謹守其氣，無使傾移，其形乃彰，生氣以長，命曰聖王。故大要曰無代化，無違時，必養必和，待其來復，此之謂也。帝曰：善。","sortOrder":66},
  {"id":"s_work_hdnk_71_1","chapterId":"ch_work_hdnk_71","text":"六元正紀大論篇第七十一","sortOrder":1},
  {"id":"s_work_hdnk_71_2","chapterId":"ch_work_hdnk_71","text":"黃帝問曰：六化六變，勝復淫治，甘苦辛鹹酸淡先後，餘知之矣。夫五運之化，或從五氣，或逆天氣，或從天氣而逆地氣，或從地氣而逆天氣，或相得，或不相得，餘未能明其事，欲通天之紀，從地之理，和其運，調其化，使上下合德，無相奪倫，天地升降，不失其宜，五運宣行，勿乖其政，調之正味，從逆奈何？","sortOrder":2},
  {"id":"s_work_hdnk_71_3","chapterId":"ch_work_hdnk_71","text":"岐伯稽首再拜對曰：昭乎哉問也！此天地之綱紀，變化之淵源，非聖帝熟能窮其至理歟！臣雖不敏，請陳其道，令終不滅，久而不易。","sortOrder":3},
  {"id":"s_work_hdnk_71_4","chapterId":"ch_work_hdnk_71","text":"帝曰：願夫子推而次之，從其類序，分其部主，別其宗司，昭其氣數，明其正化，可得聞乎？","sortOrder":4},
  {"id":"s_work_hdnk_71_5","chapterId":"ch_work_hdnk_71","text":"岐伯曰：先立其年，以明其氣，金木水火土，運行之數；寒暑燥濕風火，臨御之化，則天道可見，民氣可調，陰陽卷舒，近而無惑，數之可數者，請遂言之。","sortOrder":5},
  {"id":"s_work_hdnk_71_6","chapterId":"ch_work_hdnk_71","text":"帝曰：太陽之政奈何？岐伯曰：辰戌之紀也。","sortOrder":6},
  {"id":"s_work_hdnk_71_7","chapterId":"ch_work_hdnk_71","text":"太陽、太角、太陰、壬辰、壬戌、其運風，其化鳴紊啟拆；其變振拉摧拔；其病眩掉目瞑。太角（初正）、少征、太宮、少商、太羽（終）。","sortOrder":7},
  {"id":"s_work_hdnk_71_8","chapterId":"ch_work_hdnk_71","text":"太陽、太徵、太陰、戊辰、戊戌同正徵，其運熱，其化喧暑鬱燠；其變炎烈沸騰；其病熱鬱。太徵、少宮、太商、少羽（終）、少角（初）。","sortOrder":8},
  {"id":"s_work_hdnk_71_9","chapterId":"ch_work_hdnk_71","text":"太陽、太宮、太陰、甲辰歲會（同天符）、甲戌歲會（同天符），其運陰埃，其化柔潤重澤；其變震驚飄驟；其病濕下重。太宮、少商、太羽（終）、太角（初），少征。","sortOrder":9},
  {"id":"s_work_hdnk_71_10","chapterId":"ch_work_hdnk_71","text":"太陽、太商、太陰、庚辰、庚戌，其運涼，其化霧露蕭飋；其變肅殺凋零；其病燥，背瞀胸滿。太商、少羽（終）、少角（初）、太徵、少宮。","sortOrder":10},
  {"id":"s_work_hdnk_71_11","chapterId":"ch_work_hdnk_71","text":"太陽、太羽、太陰、丙辰天符、丙戌天符，其運寒，其化凝慘栗冽；其變冰雪霜雹；其病大寒留於溪穀。太羽（終）、太角（初）、少徵、太宮、少商。","sortOrder":11},
  {"id":"s_work_hdnk_71_12","chapterId":"ch_work_hdnk_71","text":"凡此太陽司天之政，氣化運行先天，天氣肅、地氣靜。寒臨太虛，陽氣不令，水土合德，上應辰星鎮星。其穀玄黅，其政肅，其令徐。寒政大舉，澤無陽焰，則火發待時。少陽中治，時雨乃涯。止極雨散，還於太陰，雲朝北極，濕化乃布，澤流萬物。寒敷於上，雷動於下，寒濕之氣，持於氣交，民病寒濕發，肌肉萎，足萎不收，濡瀉血溢。","sortOrder":12},
  {"id":"s_work_hdnk_71_13","chapterId":"ch_work_hdnk_71","text":"初之氣，地氣遷，氣乃大溫，草乃早榮，民乃厲，溫病乃作，身熱、頭痛、嘔吐、肌腠瘡瘍。","sortOrder":13},
  {"id":"s_work_hdnk_71_14","chapterId":"ch_work_hdnk_71","text":"二之氣，大涼反至，民乃慘，草乃遇寒，火氣遂抑，民病氣鬱中滿，寒乃始。","sortOrder":14},
  {"id":"s_work_hdnk_71_15","chapterId":"ch_work_hdnk_71","text":"三之氣，天政布，寒氣行，雨乃降，民病寒，反熱中，癰疽註下，心熱瞀悶，不治者死。","sortOrder":15},
  {"id":"s_work_hdnk_71_16","chapterId":"ch_work_hdnk_71","text":"四之氣，風濕交爭，風化為雨，乃長、乃化、乃成、民病大熱少氣，肌肉萎、足萎、註下赤白。","sortOrder":16},
  {"id":"s_work_hdnk_71_17","chapterId":"ch_work_hdnk_71","text":"五之氣，陽復化，草乃長，乃化、乃成、民乃舒。","sortOrder":17},
  {"id":"s_work_hdnk_71_18","chapterId":"ch_work_hdnk_71","text":"終之氣，地氣正，濕令行。陰凝太虛，埃昏郊野，民乃慘悽，寒風以至，反者孕乃死。","sortOrder":18},
  {"id":"s_work_hdnk_71_19","chapterId":"ch_work_hdnk_71","text":"故歲宜苦以燥之溫之，必折其鬱氣，先資其化源，抑其運氣，扶其不勝，無使暴過而生其疾。食歲穀以全其真，避虛邪以安其正，適氣同異，多少製之。同寒濕者燥熱化，異寒濕者燥濕化，故同者多之，異者少之，用寒遠寒，用涼遠涼，用溫遠溫，用熱遠熱，食宜同法，有假者反常，反是者病，所謂時也。","sortOrder":19},
  {"id":"s_work_hdnk_71_20","chapterId":"ch_work_hdnk_71","text":"帝曰：善。陽明之政奈何？岐伯說：卯酉之紀也。","sortOrder":20},
  {"id":"s_work_hdnk_71_21","chapterId":"ch_work_hdnk_71","text":"陽明、少角、少陰，清熱勝復同，同正商，丁卯（歲會）、丁酉，其運風，清熱。少角（初正）、太徵、少宮、太商、少羽（終）。","sortOrder":21},
  {"id":"s_work_hdnk_71_22","chapterId":"ch_work_hdnk_71","text":"陽明、少徵、少陰、寒雨勝復同，同正商，癸卯（同歲會）、癸酉（同歲會），其運熱，寒雨。少徵、太宮、少商、太羽（終）、太角（初）。","sortOrder":22},
  {"id":"s_work_hdnk_71_23","chapterId":"ch_work_hdnk_71","text":"陽明、少宮、少陰，風涼勝復同，己卯、己酉、其運雨風涼。少宮、太商、少羽（終）、少角（初）、太徵。","sortOrder":23},
  {"id":"s_work_hdnk_71_24","chapterId":"ch_work_hdnk_71","text":"陽明、少商、少陰，風涼勝復同，同正商，乙卯天符、乙酉歲會，太一天符，其運涼，熱寒。少商、太羽（終）、太角（初）、少徵、太宮。","sortOrder":24},
  {"id":"s_work_hdnk_71_25","chapterId":"ch_work_hdnk_71","text":"陽明、少羽、少陰、雨風勝復同，辛卯少宮同，辛酉、辛卯、其運寒，雨風。少羽（終）、少角（初）、太徵、太宮、太商。","sortOrder":25},
  {"id":"s_work_hdnk_71_26","chapterId":"ch_work_hdnk_71","text":"凡此陽明司天之政，氣化運行後天。天氣急，地氣明，陽專其令，炎暑大行，物燥以堅，淳風乃治。風燥橫運，流於氣交，多陽少陰，雲趨雨府，濕化乃敷，燥極而澤。其穀白丹，問穀命太者。其耗白甲品羽。金火合德，上應太白熒惑。其政切，其令暴，蟄蟲乃見，流水不冰。民病咳、嗌塞，寒熱發暴，振慄癃悶，清先而勁，毛蟲乃死，熱後而暴，介蟲乃殃。其發躁，勝復之作，擾而大亂，清熱之氣，持於氣交。","sortOrder":26},
  {"id":"s_work_hdnk_71_27","chapterId":"ch_work_hdnk_71","text":"初之氣，地氣遷，陰始凝，氣始肅，水乃冰，寒雨化。其病中熱脹、面目浮腫、善眠、鼽衄、嚏欠、嘔、小便黃赤、甚則淋。","sortOrder":27},
  {"id":"s_work_hdnk_71_28","chapterId":"ch_work_hdnk_71","text":"二之氣，陽乃布、民乃舒，物乃生榮。厲大至，民善暴死。","sortOrder":28},
  {"id":"s_work_hdnk_71_29","chapterId":"ch_work_hdnk_71","text":"三之氣，天政布，涼乃行，燥熱交合，燥極而澤，民病寒熱。","sortOrder":29},
  {"id":"s_work_hdnk_71_30","chapterId":"ch_work_hdnk_71","text":"四之氣，寒雨降，病暴仆、振慄譫妄，少氣嗌乾，引飲，及為心痛，癰腫瘡瘍，瘧寒之疾，骨痿血便。","sortOrder":30},
  {"id":"s_work_hdnk_71_31","chapterId":"ch_work_hdnk_71","text":"五之氣，春令反行，草乃生榮，民氣和。","sortOrder":31},
  {"id":"s_work_hdnk_71_32","chapterId":"ch_work_hdnk_71","text":"終之氣，陽氣布，候反溫，蟄蟲來見，流水不冰。民乃康平，其病溫。","sortOrder":32},
  {"id":"s_work_hdnk_71_33","chapterId":"ch_work_hdnk_71","text":"故食歲穀以安其氣，食間穀以去其邪，歲宜以鹹，以苦，以辛、汗之、清之、散之。安其運氣，無使受邪，折其鬱氣，資其化源。以寒熱輕重少多其製，同熱者多天化，同清者多地化，用涼遠涼，用熱遠熱，用寒遠寒，用溫遠溫，食宜同法。有假者反之，此其道也，反是者亂天地之經，擾陰陽之紀也。","sortOrder":33},
  {"id":"s_work_hdnk_71_34","chapterId":"ch_work_hdnk_71","text":"帝曰：善。少陽之政奈何？岐伯曰：寅申之紀也。","sortOrder":34},
  {"id":"s_work_hdnk_71_35","chapterId":"ch_work_hdnk_71","text":"少陽、太角、厥陰、壬寅（同天符）、壬申（同天符）、其運風鼓，其化嗚紊啟拆，其變振拉摧拔，其病掉眩、支脅、驚駭。太角（初正）、少徵、太宮、少商、太羽（終）。","sortOrder":35},
  {"id":"s_work_hdnk_71_36","chapterId":"ch_work_hdnk_71","text":"少陽、太徵、厥陰、戊寅天符、戊申天符，其運暑，其化喧囂鬱懊，其變炎烈沸騰。其病上、熱鬱、血溢、血泄、心痛。太徵、少宮、太商、少羽（終）、少角（初）。","sortOrder":36},
  {"id":"s_work_hdnk_71_37","chapterId":"ch_work_hdnk_71","text":"少陽、太宮、厥陰、甲寅、甲申，其運陰雨，其化柔潤重澤，其變震驚飄驟。其病體重，腑腫、痞飲。太宮、少商、太羽（終）、太角（初）、少徵。","sortOrder":37},
  {"id":"s_work_hdnk_71_38","chapterId":"ch_work_hdnk_71","text":"少陽、太商、厥陰、庚寅、庚申同正商，其運涼，其化霧露清切、其變肅殺凋零。其病肩背胸中。太商、少羽（終）、少角（初）、太徵、少宮。","sortOrder":38},
  {"id":"s_work_hdnk_71_39","chapterId":"ch_work_hdnk_71","text":"少陽、太羽、厥陰、丙寅、丙申，其運寒肅，其化凝慘慄冽，其變冰雪霜雹，其病寒，浮腫。太羽（終）、太角（初）、少徵、太宮、少商。","sortOrder":39},
  {"id":"s_work_hdnk_71_40","chapterId":"ch_work_hdnk_71","text":"凡此少陽司天之政，氣化運行先天。天氣正，地氣擾，風乃暴舉，木偃沙飛，炎火乃流，陰行陽化，雨乃時應，火木同德，上應熒惑歲星。其穀丹蒼，其政嚴，其令擾。故風熱參布，雲物沸騰。太陰橫流，寒乃時至，涼雨並起。民病寒中，外發瘡瘍，內為泄滿，故經人遇之，和而不爭。往復之作，民病寒熱，瘧泄、聾瞑、嘔吐、上怫、腫色變。","sortOrder":40},
  {"id":"s_work_hdnk_71_41","chapterId":"ch_work_hdnk_71","text":"初之氣，地氣遷，風勝乃搖，寒乃去，候乃大溫，草木早榮。寒來不殺，溫病乃起，其病氣怫於上，血溢目赤，咳逆頭痛、血崩、脅滿、膚腠中瘡。","sortOrder":41},
  {"id":"s_work_hdnk_71_42","chapterId":"ch_work_hdnk_71","text":"二之氣，火反鬱，白埃四起，雲趨雨府，風不勝濕，雨乃零，民乃康。其病熱鬱於上，咳逆嘔吐，瘡發於中，胸嗌不利，頭痛身熱，昏憒膿瘡。","sortOrder":42},
  {"id":"s_work_hdnk_71_43","chapterId":"ch_work_hdnk_71","text":"三之氣，天政布，炎暑至，少陽臨上，雨乃涯。民病熱中，聾瞑、血溢、膿瘡、咳、嘔、鼽、衄、渴、嚏欠、喉痺、目赤、善暴死。","sortOrder":43},
  {"id":"s_work_hdnk_71_44","chapterId":"ch_work_hdnk_71","text":"四之氣，涼乃至，炎暑間化，白露降。民氣和平，其病滿，身重。","sortOrder":44},
  {"id":"s_work_hdnk_71_45","chapterId":"ch_work_hdnk_71","text":"五之氣，陽乃去，寒乃來，雨乃降，氣門乃閉，剛木早凋。民避寒邪，君子周密。","sortOrder":45},
  {"id":"s_work_hdnk_71_46","chapterId":"ch_work_hdnk_71","text":"終之氣，地氣正，風乃至，萬物反生，霧霧以行，其病關閉不禁，心痛，陽氣不藏而咳。","sortOrder":46},
  {"id":"s_work_hdnk_71_47","chapterId":"ch_work_hdnk_71","text":"抑其運氣，贊所不勝。必折其鬱氣，先取化源，暴過不生，苛疾不起，故歲宜鹹辛宜酸，滲之泄之，漬之發之，觀氣寒溫以調其過。同風熱者多寒化，異風熱者少寒化，用熱遠熱，用溫遠溫，用寒遠寒，用涼遠涼，食宜同法，此其道也。有假者反之，反是者病之階也。","sortOrder":47},
  {"id":"s_work_hdnk_71_48","chapterId":"ch_work_hdnk_71","text":"帝曰：善。太陰之政奈何？岐伯曰：丑未之紀也。","sortOrder":48},
  {"id":"s_work_hdnk_71_49","chapterId":"ch_work_hdnk_71","text":"太陰、少角、太陽，清熱勝復同，同正宮，丁丑、丁未、其運風、清熱。少角（初正）、太徵、少宮、太商、少羽（終）。","sortOrder":49},
  {"id":"s_work_hdnk_71_50","chapterId":"ch_work_hdnk_71","text":"太陰、少徵、太陽，寒雨勝復同，癸丑、癸未，其運熱、寒雨。少徵、太宮、少商、太羽（終）、太角。","sortOrder":50},
  {"id":"s_work_hdnk_71_51","chapterId":"ch_work_hdnk_71","text":"太陰、少宮、太陽，風清勝復同，同正宮，己丑太一天符、己未太一天符，其運雨、風清。少宮、太商、少羽（終）、少角、（初）、太徵。","sortOrder":51},
  {"id":"s_work_hdnk_71_52","chapterId":"ch_work_hdnk_71","text":"太陰、少商、太陽，熱寒勝復同，乙丑、乙未、其運涼、熱。少商、太羽（終）、太角（初）、少徵、太宮。","sortOrder":52},
  {"id":"s_work_hdnk_71_53","chapterId":"ch_work_hdnk_71","text":"凡此太陰司天之政，氣化運化運行後天。陰專其政，陽氣退避，大風時起，天氣下降，地氣上騰，原野昏霿、白埃四起，雲奔南極，寒雨數至，物成於差夏。民病寒濕腹滿，身〈月真〉憤、腑腫痞逆，寒厥拘急。濕寒合德，黃黑埃昏，流行氣交，上應鎮星辰星。其政肅，其令寂，其穀黔玄。故陰凝於上，寒積於下，寒水勝火則為冰雹；陽光不治，殺氣乃行。故有餘宜高，不及宜下，有餘宜晚，不及宜早。土之利氣之化也。民氣亦從之，間穀命其太也。","sortOrder":53},
  {"id":"s_work_hdnk_71_54","chapterId":"ch_work_hdnk_71","text":"初之氣，地氣遷，寒乃去，春氣正，風乃來，生布萬物以榮，民氣條舒，風濕相薄，雨乃後。民病血溢，筋絡拘強，關節不利，身重筋萎。","sortOrder":54},
  {"id":"s_work_hdnk_71_55","chapterId":"ch_work_hdnk_71","text":"二之氣，大火正，物承化，民乃和。其病溫厲大行，遠近鹹若，濕蒸相薄，雨乃時降。","sortOrder":55},
  {"id":"s_work_hdnk_71_56","chapterId":"ch_work_hdnk_71","text":"三之氣，天政布，濕氣降，地氣騰，雨乃時降，寒乃隨之，感於寒濕，則民病身重、腑腫、胸腹滿。","sortOrder":56},
  {"id":"s_work_hdnk_71_57","chapterId":"ch_work_hdnk_71","text":"四之氣，畏火臨、溽蒸化，地氣騰，天氣否隔，寒風曉暮，蒸熱相薄，草木凝煙，濕化不流，則白露陰布，以成秋令。民病腠理熱，血暴溢、瘧、心腹滿熱、臚脹、甚則腑腫。","sortOrder":57},
  {"id":"s_work_hdnk_71_58","chapterId":"ch_work_hdnk_71","text":"五之氣，慘令已行，寒露下，霜乃早降、草木黃落、寒氣及體，君子周密，民病皮腠。","sortOrder":58},
  {"id":"s_work_hdnk_71_59","chapterId":"ch_work_hdnk_71","text":"終之氣、寒大舉、濕大化、霜乃積、陰乃凝、水堅冰、陽光不治。感於寒，則病人關節禁固，腰脽痛，寒濕推於氣交而為疾也。","sortOrder":59},
  {"id":"s_work_hdnk_71_60","chapterId":"ch_work_hdnk_71","text":"必折其鬱氣，而取化源，益其歲氣，無使邪勝。食歲穀以全其真，食間穀以保其精。故歲宜以苦燥之溫之。甚者發之泄之，不發不泄，則濕氣外溢，肉潰皮折，而水血交流。必贊其陽火，令禦甚寒，從氣異同，少多其判也。同寒者以熱化，同濕者以燥化；異者少之，同者多之。用涼遠涼，用寒遠寒，用溫遠溫，用熱遠熱，食宜同法。假者反之，此其道也。反是者病也。","sortOrder":60},
  {"id":"s_work_hdnk_71_61","chapterId":"ch_work_hdnk_71","text":"帝曰：善。少陰之政奈何？岐伯曰：子午之紀也。","sortOrder":61},
  {"id":"s_work_hdnk_71_62","chapterId":"ch_work_hdnk_71","text":"少陰、大角、陽明、壬子、壬午、其運風鼓，其化嗚紊啟拆；其變振拉摧拔；其病支滿。太角（初正），少徵、太宮、少商、太羽（終）。","sortOrder":62},
  {"id":"s_work_hdnk_71_63","chapterId":"ch_work_hdnk_71","text":"太陰、太徵、陽陰、戊子天符，戊午太一天符，其運炎暑，其化喧曜鬱燠，其變炎烈沸騰，其病上熱，血溢。太徵、少宮、太商、少羽（終）、少角（初）。","sortOrder":63},
  {"id":"s_work_hdnk_71_64","chapterId":"ch_work_hdnk_71","text":"少陰、太宮、陽明、甲子、甲午、其運陰雨，其化柔潤時雨。其變震驚飄驟，其病中滿身重。太宮、少商、太羽（終）、太角（初）、少徵。","sortOrder":64},
  {"id":"s_work_hdnk_71_65","chapterId":"ch_work_hdnk_71","text":"少陰、太商、陽明、庚子（同天符）、庚午（同天符）、同正商，其運涼勁，其化霧露蕭飋；其變肅凋零。其病下清。太商、少羽（終）、少角（初）、太徵、少宮。","sortOrder":65},
  {"id":"s_work_hdnk_71_66","chapterId":"ch_work_hdnk_71","text":"少陰、太羽、陽明、丙子歲會、丙午、其運寒、其化凝慘慄冽；其變冰雪霜雹，其病寒下。太羽（終）、太角（初）、少徵、太宮、少商。","sortOrder":66},
  {"id":"s_work_hdnk_71_67","chapterId":"ch_work_hdnk_71","text":"凡此少陰司天之政，氣化運行先天，地氣肅，天氣明，寒交暑，熱加燥，雲馳雨府，濕化乃行，時雨乃降。金火合德，上應熒惑，太白。其政明，其令切，其穀丹白。水火寒熱持於氣交，而為病始也。熱病生於上，清病生於下，寒熱凌犯而爭於中，民病咳喘，血溢血泄，鼽嚏目赤，眥瘍，寒厥入胃，心痛、腰痛、腹大、嗌乾、腫上。","sortOrder":67},
  {"id":"s_work_hdnk_71_68","chapterId":"ch_work_hdnk_71","text":"初之氣、地氣遷、燥將去、寒乃始、蟄復藏水乃冰，霜復降，風乃至，陽氣鬱。民反周密，關節禁固，腰脽痛，炎暑將起，中外瘡瘍。","sortOrder":68},
  {"id":"s_work_hdnk_71_69","chapterId":"ch_work_hdnk_71","text":"二之氣，陽氣布，風乃行，春氣以正，萬物應榮，寒氣時至，民乃和。其病淋，目瞑目赤，氣鬱於上而熱。","sortOrder":69},
  {"id":"s_work_hdnk_71_70","chapterId":"ch_work_hdnk_71","text":"三之氣，天政布，大火行，庶類蕃鮮，寒氣時至。民病氣厥心痛，寒熱更作，咳喘目赤。","sortOrder":70},
  {"id":"s_work_hdnk_71_71","chapterId":"ch_work_hdnk_71","text":"四之氣，溽暑至，大雨時行，寒熱互至。民病寒熱，嗌乾、黃癉、鼽衄、飲發。","sortOrder":71},
  {"id":"s_work_hdnk_71_72","chapterId":"ch_work_hdnk_71","text":"五之氣，畏火臨，暑反至，陽乃化，萬物乃生，乃長榮，民乃康。其病溫。","sortOrder":72},
  {"id":"s_work_hdnk_71_73","chapterId":"ch_work_hdnk_71","text":"終之氣，燥令行，餘火內格，腫於上，咳喘，甚則血溢。寒氣數舉，則霿霧翳。病生皮腠，內含於脅，下連少腹而作寒中，地將易也。","sortOrder":73},
  {"id":"s_work_hdnk_71_74","chapterId":"ch_work_hdnk_71","text":"必抑其運氣，資其歲勝，折其鬱發，先取化源，無使暴過而生其病也。食歲穀以全真氣，食間穀以避虛邪，歲宜鹹以軟之，而調其上，甚則以苦發之；以酸收之，而安其下，甚則以苦泄之。適氣同異而多少之，同天氣者以寒清化；同地氣者以溫熱化。用熱遠熱，用涼遠涼，用溫遠溫，用寒遠寒，食宜同法。有假則反，此其道也，反是者病作矣。","sortOrder":74},
  {"id":"s_work_hdnk_71_75","chapterId":"ch_work_hdnk_71","text":"帝曰：善。厥陰之政奈何？岐伯曰：己亥之紀也。","sortOrder":75},
  {"id":"s_work_hdnk_71_76","chapterId":"ch_work_hdnk_71","text":"厥陰、少角、少陽，清熱勝復同，同正角，丁巳天符、丁亥天符，其運風，清熱。少角（初正）、太徵、少宮、太商、少羽（終）。","sortOrder":76},
  {"id":"s_work_hdnk_71_77","chapterId":"ch_work_hdnk_71","text":"厥陰、少徵、少陽、寒雨勝復同，癸巳（同歲會）、癸亥（同歲會），其運熱，寒雨。少徵、太宮、少商、太羽（終）、太角（初）。","sortOrder":77},
  {"id":"s_work_hdnk_71_78","chapterId":"ch_work_hdnk_71","text":"厥陰、少宮、少陽、風清勝復同，同正角，己巳，己亥，其運雨，風清。少宮、太商、少羽（終）、少角（初）、太徵。","sortOrder":78},
  {"id":"s_work_hdnk_71_79","chapterId":"ch_work_hdnk_71","text":"厥陰、少商、少陽、熱寒勝復同，同正角，乙巳、乙亥、其運涼，熱寒。少商、太羽（終）、太角（初）、少徵、太宮。","sortOrder":79},
  {"id":"s_work_hdnk_71_80","chapterId":"ch_work_hdnk_71","text":"厥陰、少羽、少陽、風雨勝復同，辛巳、辛亥、其運寒，雨風。少羽（終）、少角（初），太徵、少宮、太商。","sortOrder":80},
  {"id":"s_work_hdnk_71_81","chapterId":"ch_work_hdnk_71","text":"凡此厥陰司天之政，氣化運行後天，諾同正歲，氣化運行同天，天氣擾，地氣正，風生高遠，炎熱從之，雲趨雨府，濕化乃行，風火同德，上應歲星，熒惑。其政撓，其令速，其穀蒼丹，間穀言太者。其耗文角品羽。風燥火熱，勝復更作，蟄蟲來見，流水不冰，熱病行於下，風病行於上，風燥勝復，形於中。","sortOrder":81},
  {"id":"s_work_hdnk_71_82","chapterId":"ch_work_hdnk_71","text":"初之氣，寒始肅，殺氣方至，民病寒於右之下。","sortOrder":82},
  {"id":"s_work_hdnk_71_83","chapterId":"ch_work_hdnk_71","text":"二之氣，寒不去，華雪水冰，殺氣施化，霜乃降，名草上焦，寒雨數至。陽復化，民病熱於中。","sortOrder":83},
  {"id":"s_work_hdnk_71_84","chapterId":"ch_work_hdnk_71","text":"三之氣，天政布，風乃時舉。民病泣出，耳嗚掉眩。","sortOrder":84},
  {"id":"s_work_hdnk_71_85","chapterId":"ch_work_hdnk_71","text":"四之氣，溽暑濕熱相薄，爭於左之上。民病黃癉而為腑腫。","sortOrder":85},
  {"id":"s_work_hdnk_71_86","chapterId":"ch_work_hdnk_71","text":"五之氣，燥濕更勝，沈陰乃布，寒氣及體，風雨乃行。","sortOrder":86},
  {"id":"s_work_hdnk_71_87","chapterId":"ch_work_hdnk_71","text":"終之氣，畏火司令，陽乃大化，蟄蟲出現，流水不冰，地氣大發，草乃生，人乃舒。其病溫厲。","sortOrder":87},
  {"id":"s_work_hdnk_71_88","chapterId":"ch_work_hdnk_71","text":"必折其鬱氣，資其化源，贊其運氣，無使邪勝。歲宜以辛調上，以鹹調下，畏火之氣，無妄犯之。用溫遠溫，用熱遠熱，用涼遠涼，用寒遠寒，食宜同法。有假反常，此之道也。反是者病。","sortOrder":88},
  {"id":"s_work_hdnk_71_89","chapterId":"ch_work_hdnk_71","text":"帝曰：善。夫子言可謂悉矣，然何以明其應乎？岐伯曰：昭乎哉問也。夫六氣者，行有次，止有位，故常以正月朔日平旦視之，睹其位而知其所在矣。運有餘其致先，運不及其至後，此天之道，氣之常也。運非有餘，非不足，是謂正歲，其至當其時也。帝曰：勝復之氣，其常在也，災眚時至，候也奈何？岐伯曰：非氣化者，是謂災也。","sortOrder":89},
  {"id":"s_work_hdnk_71_90","chapterId":"ch_work_hdnk_71","text":"帝曰：天地之數，終始奈何？岐伯曰：悉乎哉問也。是明道也。數之始起於上，而終於下，歲半之前，天氣主之，歲半之後，地氣主之，上下交互，氣交主之，歲紀華矣。故曰位明，氣月可知乎，所謂氣也。","sortOrder":90},
  {"id":"s_work_hdnk_71_91","chapterId":"ch_work_hdnk_71","text":"帝曰：餘司其事，則而行之，不合其數何也？岐伯曰：氣用有多少，化洽有盛衰，衰盛多有，同其化也。帝曰：願聞同化何如？岐伯曰：風溫春化同，熱曛昏火夏化同，勝與復同，燥清煙露秋化同，雲雨昏瞑埃長夏化同，寒氣霜雪冰冬化同，此天地五運六氣之化，更用盛衰之常也。","sortOrder":91},
  {"id":"s_work_hdnk_71_92","chapterId":"ch_work_hdnk_71","text":"帝曰：五運行同天化者命曰天符，餘知之矣。願聞同地化者何謂也？岐伯曰：太過而同天化者三，不及而同天化者亦三；太過而同地化者三，不及而同地化者亦三。此凡二十四歲也。","sortOrder":92},
  {"id":"s_work_hdnk_71_93","chapterId":"ch_work_hdnk_71","text":"帝曰：願聞其所謂也？岐伯曰：甲辰甲戌太宮下加太陰，壬寅壬申太角下加厥陰，庚子庚午太商下加陽明，如是者三。","sortOrder":93},
  {"id":"s_work_hdnk_71_94","chapterId":"ch_work_hdnk_71","text":"癸巳癸亥少徵下加少陽，辛丑辛未少羽下加太陽，癸卯癸酉少徵下加少陰，如是者三。","sortOrder":94},
  {"id":"s_work_hdnk_71_95","chapterId":"ch_work_hdnk_71","text":"戊子戊午太徵上臨少陰，戊寅戊申太徵上臨少陽，丙辰丙戌太羽上臨太陽，如是者三。","sortOrder":95},
  {"id":"s_work_hdnk_71_96","chapterId":"ch_work_hdnk_71","text":"丁巳丁亥少角上臨厥陰，乙卯乙酉少商上臨陽明。己丑己未，少宮上臨太陰。如是者三，除此二十四歲，則不加不臨也。","sortOrder":96},
  {"id":"s_work_hdnk_71_97","chapterId":"ch_work_hdnk_71","text":"帝曰：加者何謂？岐伯曰：太過而加同天符，不及而加同歲會也。帝曰：臨者何謂？岐伯曰：太過不及，皆曰天符，而變行有多少，病形有微甚，生死有早晏耳！","sortOrder":97},
  {"id":"s_work_hdnk_71_98","chapterId":"ch_work_hdnk_71","text":"帝曰：夫子言用寒遠寒，用熱遠熱，餘未知其然也。願聞何謂遠？岐伯曰：熱無犯熱，寒無犯寒，從者和，逆者病，不可不敬畏而遠之，所謂時興六位也。","sortOrder":98},
  {"id":"s_work_hdnk_71_99","chapterId":"ch_work_hdnk_71","text":"帝曰：溫涼何如？岐伯曰：司氣以熱，用熱無犯，司氣以寒，用寒無犯，司氣以涼，用涼無犯，司氣以溫，用溫無犯。間氣同其主無犯，異其主則小犯之，是謂四畏，必謹察之。","sortOrder":99},
  {"id":"s_work_hdnk_71_100","chapterId":"ch_work_hdnk_71","text":"帝曰：善。其犯者何如？岐伯曰：天氣反時，則可依則，及勝其主則可犯，以平為期，而不可過，是謂邪氣反勝者。故曰：無失天信，無逆氣宜，無翼其勝，無贊其復，是謂至治。","sortOrder":100},
  {"id":"s_work_hdnk_71_101","chapterId":"ch_work_hdnk_71","text":"帝曰：善。五運氣行主歲之紀，其有常數乎？岐伯曰：臣請次之。","sortOrder":101},
  {"id":"s_work_hdnk_71_102","chapterId":"ch_work_hdnk_71","text":"甲子、甲午歲，上少陰火，中太宮土運，下陽明金。熱化二，雨化五，燥化四，所謂正化日也。其化上鹹寒，中苦熱，下酸熱，所謂藥食宜也。","sortOrder":102},
  {"id":"s_work_hdnk_71_103","chapterId":"ch_work_hdnk_71","text":"乙丑、乙未歲，上太陰土，中少商金運，下太陽水。熱化寒化勝復同，所謂邪氣化日也，災七宮。濕化五，清化四，寒化六，所謂正化日也。其化上苦熱，中酸和，下甘熱，所謂藥食宜也。","sortOrder":103},
  {"id":"s_work_hdnk_71_104","chapterId":"ch_work_hdnk_71","text":"丙寅、丙申歲，上少陽相火，中太羽水運，下厥陰木，火化二，寒化六，風化三，所謂正化日也，其化上鹹寒，中鹹溫，下辛溫，所謂藥食宜也。","sortOrder":104},
  {"id":"s_work_hdnk_71_105","chapterId":"ch_work_hdnk_71","text":"丁卯、丁酉歲，上陽明金，中少角木運，下少陰火。清化熱化勝復同，所謂邪氣化日也，災三宮，燥化九，風化三，熱化七，所謂正化日也。其化上苦，小溫，中辛和，下鹹寒，所謂藥食宜也。","sortOrder":105},
  {"id":"s_work_hdnk_71_106","chapterId":"ch_work_hdnk_71","text":"戊辰、戊戌歲，上太陽水，中太徵火運，下太陰土，寒化六，熱化七，濕化五，所謂正化日也。其化上苦溫，中甘和，下甘溫，所謂藥食宜也。","sortOrder":106},
  {"id":"s_work_hdnk_71_107","chapterId":"ch_work_hdnk_71","text":"己巳、己亥歲，上厥陰木，中少宮土運，下少陽相火，風化清化勝復同，所謂邪氣化日也，災五宮，風化三，濕化五，火化七，所謂正化日也。其化上辛涼，中甘和，下鹹寒，所謂藥食宜也。","sortOrder":107},
  {"id":"s_work_hdnk_71_108","chapterId":"ch_work_hdnk_71","text":"庚午、庚子歲，上少陰火，中太商金運，下陽明金，熱化七，清化九，燥化九，所謂正化日也。其化上鹹寒，中辛溫，下酸溫，所謂藥食宜也。","sortOrder":108},
  {"id":"s_work_hdnk_71_109","chapterId":"ch_work_hdnk_71","text":"辛未、辛丑歲，上太陰土，中少羽水運，下太陽水，雨化風化勝復同，所謂邪氣化日也。災一宮，雨化五，寒化一，所謂正化日也。其化上苦熱，中苦和，下苦熱，所謂藥食宜也。","sortOrder":109},
  {"id":"s_work_hdnk_71_110","chapterId":"ch_work_hdnk_71","text":"壬申、壬寅歲，上少陽相火，中太角木運，下厥陰木。火化二，風化八，所謂正化日也。其化上鹹寒，中酸和，下辛涼，所謂藥食宜也。","sortOrder":110},
  {"id":"s_work_hdnk_71_111","chapterId":"ch_work_hdnk_71","text":"癸酉、癸卯歲，上陽明金，中少徵火運，下少陰火。寒化雨化勝負同，所謂邪氣化日也。災九宮，燥化九，熱化二，所謂正化日也。其化上苦小溫，中鹹溫，下鹹寒，所謂藥食宜也。","sortOrder":111},
  {"id":"s_work_hdnk_71_112","chapterId":"ch_work_hdnk_71","text":"甲戌、甲辰歲，上太陽水，中太宮土運，下太陰土，寒化六，濕化五，正化日也。其化上苦熱，中苦溫，下苦溫，藥食宜也。","sortOrder":112},
  {"id":"s_work_hdnk_71_113","chapterId":"ch_work_hdnk_71","text":"乙亥、乙巳歲，上厥陰木，中少商金運，下少陽相火，熱化寒化勝負同，邪氣化日也。災七宮，風化八，清化四，火化二，正化度也。其化上辛涼，中酸和，下鹹寒，藥食宜也。","sortOrder":113},
  {"id":"s_work_hdnk_71_114","chapterId":"ch_work_hdnk_71","text":"丁丑、丁未歲，上太陰土，中少角木運，下太陽水，清化熱化勝負同，邪氣化度也。災三宮，雨化五，風化三，寒化一，正化度也。其化上苦溫，中辛溫，下甘熱，藥食宜也。","sortOrder":114},
  {"id":"s_work_hdnk_71_115","chapterId":"ch_work_hdnk_71","text":"戊寅、戊申歲，上少陽相火，中太徵火運，下厥陰木，火化七，風化三，正化度也。其化上鹹寒，中甘和下辛涼，藥食宜也。","sortOrder":115},
  {"id":"s_work_hdnk_71_116","chapterId":"ch_work_hdnk_71","text":"己卯、己酉歲，上陽明金，中少宮土運，下少陰火，風化清化勝負同，邪氣化度也。災五宮，清化九，雨化五，熱化七，正化度也。其化上苦小溫，中甘和，下鹹寒，藥食宜也。","sortOrder":116},
  {"id":"s_work_hdnk_71_117","chapterId":"ch_work_hdnk_71","text":"庚辰、庚戌歲，上太陽水，中太商金運，下太陰土，寒化一，清化九，雨化五，正化度也。其化上苦熱，中辛溫，下甘熱，藥食宜也。","sortOrder":117},
  {"id":"s_work_hdnk_71_118","chapterId":"ch_work_hdnk_71","text":"辛巳、辛亥歲，上厥陰木，中少羽水運，下少陽相火，雨化風化勝負同，邪氣化度也。災一宮，風化三，寒化一，火化七，正化度也。其化上辛涼，中苦和，下鹹寒，藥食宜也。","sortOrder":118},
  {"id":"s_work_hdnk_71_119","chapterId":"ch_work_hdnk_71","text":"壬午、壬子歲，上少陰火，中太角木運，下陽明金，熱化二，風化八，清化四，正化度也。其化上鹹寒，中酸涼，下酸溫，藥食宜也。","sortOrder":119},
  {"id":"s_work_hdnk_71_120","chapterId":"ch_work_hdnk_71","text":"癸未、癸丑歲，上太陰土，中少徵火運，下太陽水，寒化雨化勝負同，邪氣化度也。災九宮，雨化五，火化二，寒化一，正化度也。其化上苦溫，中鹹溫，下甘熱，藥食宜也。","sortOrder":120},
  {"id":"s_work_hdnk_71_121","chapterId":"ch_work_hdnk_71","text":"甲申、甲寅歲，上少陽相火，中太宮土運，下厥陰木，火化二，雨化五，風化八，正化度也。其化上鹹寒，中鹹和，下辛涼，藥食宜也。","sortOrder":121},
  {"id":"s_work_hdnk_71_122","chapterId":"ch_work_hdnk_71","text":"乙酉、乙卯歲，上陽明金，中少商金運，下少陰火，熱化寒化勝負同，邪氣化度也。災七宮，燥化四，清化四，熱化二，正化度也。其化上苦小溫，中苦和，下鹹寒，藥食宜也。","sortOrder":122},
  {"id":"s_work_hdnk_71_123","chapterId":"ch_work_hdnk_71","text":"丙戌、丙辰歲，上太陽水，中太羽水運，下太陰土，寒化六，雨化五，正化度也。其化上苦熱，中鹹溫，下甘熱，藥食宜也。","sortOrder":123},
  {"id":"s_work_hdnk_71_124","chapterId":"ch_work_hdnk_71","text":"丁亥、丁巳歲，上厥陰木，中少角木運，下少陽相火，清化熱化勝負同，邪氣化度也。災三宮，風化三，火化七，正化度也。其化上辛涼，中辛和，下鹹寒，藥食宜也。","sortOrder":124},
  {"id":"s_work_hdnk_71_125","chapterId":"ch_work_hdnk_71","text":"戊子、戊午歲，上少陰火，中太徵火運，下陽明金，熱化七，清化九，正化度也。其化上鹹寒，中甘寒，下酸溫，藥食宜也。","sortOrder":125},
  {"id":"s_work_hdnk_71_126","chapterId":"ch_work_hdnk_71","text":"己丑，己未歲，上太陰土，中少宮土運，下太陽水，風化清化勝負同，邪氣化度也。災五宮，雨化五，寒化一，正化度也。其化上苦熱，中甘和，下甘熱，藥食宜也。","sortOrder":126},
  {"id":"s_work_hdnk_71_127","chapterId":"ch_work_hdnk_71","text":"庚寅、庚申歲，上少陽相火，中太商金運，下厥陰木，火化七，清化九，風化三，正化度也。其化上鹹寒，中辛溫，下辛涼，藥食宜也。","sortOrder":127},
  {"id":"s_work_hdnk_71_128","chapterId":"ch_work_hdnk_71","text":"辛卯、辛酉歲，上陽明金，中少羽水運，下少陰火，雨化風化勝負同，邪氣化度也。災一宮，清化九，寒化一，熱化七，正化度也。其化上苦小溫，中苦和，下鹹寒，藥食宜也。","sortOrder":128},
  {"id":"s_work_hdnk_71_129","chapterId":"ch_work_hdnk_71","text":"壬辰、壬戌歲，上太陽水，中太角木運，下太陰土，寒化六，風化八，雨化五，正化度也。其化上苦溫，中酸和，下甘溫，藥食宜也。","sortOrder":129},
  {"id":"s_work_hdnk_71_130","chapterId":"ch_work_hdnk_71","text":"癸巳、癸亥，上厥陰木，中少徵火運，下少陽相火，寒化雨化勝負同，邪氣化度也。災九宮，風化八，火化二，正化度也。其化上辛涼，中鹹和，下鹹寒，藥食宜也。","sortOrder":130},
  {"id":"s_work_hdnk_71_131","chapterId":"ch_work_hdnk_71","text":"凡此定期之紀，勝復正化，皆有常數，不可不察，故知其要者，一言而終，不知其要，流散無窮，此之謂也。帝曰：善。五運之氣，亦復歲乎？岐伯曰：鬱極乃發，待時而作也。","sortOrder":131},
  {"id":"s_work_hdnk_71_132","chapterId":"ch_work_hdnk_71","text":"帝曰：請問其所謂也。岐伯曰：五常之氣，太過不及，其發異也。帝曰：願卒聞之。岐伯曰：太過者暴，不及者徐，暴者為病甚，徐者為病持。帝曰：太過不及其數何如？岐伯曰：太過者其數成，不及者其數生，土常以生也。","sortOrder":132},
  {"id":"s_work_hdnk_71_133","chapterId":"ch_work_hdnk_71","text":"帝曰：其發也何如？岐伯曰：土鬱之發，巖穀震驚，雷殷氣交，埃昏黃黑，化為白氣，飄驟高深，擊石飛空，洪水乃從，川流漫衍，田牧土駒。化氣乃敷，善為時雨，始生始長，始化始成。故民病心腹脹，脹嗚而為數後，甚則心痛脅〈月真〉，嘔吐霍亂，飲發註下，胕腫身重。雲奔雨府，霞擁朝陽，山澤埃昏，其乃發也。以其四氣，雲橫天山，浮遊生滅，怫之先兆。","sortOrder":133},
  {"id":"s_work_hdnk_71_134","chapterId":"ch_work_hdnk_71","text":"金鬱之發，天潔地明，風清氣切，大涼乃舉，草樹浮煙，燥氣以行，霿霧數起，殺氣來至，草木蒼乾，金乃有聲。故民病咳逆，心脅滿引少腹，善暴痛，不可反側，嗌乾面塵，色惡。山澤焦枯，土凝霜鹵，怫乃發也，其氣五。夜零白露，林莽聲淒，怫之兆也。","sortOrder":134},
  {"id":"s_work_hdnk_71_135","chapterId":"ch_work_hdnk_71","text":"水鬱之發，陽氣乃避，陰氣暴舉，大寒乃至，川澤嚴凝，寒氛結為霜雪，甚則黃黑昏翳，流行氣交，乃為霜殺，水乃見祥。故民病寒客心痛，腰脽痛，大關節不利，屈伸不便，善厥陰，痞堅，腹滿。陽光不治，空積沈陰，白埃昏瞑，而乃發也。其氣二火前後。太虛深玄，氣猶麻散，微見而隱，色黑微黃，怫之先兆也。","sortOrder":135},
  {"id":"s_work_hdnk_71_136","chapterId":"ch_work_hdnk_71","text":"木鬱之發，太虛埃昏，雲物以擾，大風乃至，屋發折木，木有變。故民病胃脘當心而痛，上支兩脅，膈咽不通，食飲不下，甚則耳嗚眩轉，目不識人，善暴僵仆。太虛蒼埃，天山一色，或氣濁色黃黑鬱若，橫雲不起雨，而乃發也。其氣無常。長川草偃，柔葉呈陰，松吟高山，虎嘯巖岫，怫之先兆也。","sortOrder":136},
  {"id":"s_work_hdnk_71_137","chapterId":"ch_work_hdnk_71","text":"火鬱之發，太虛腫翳，大明不彰，炎火行，大暑至，山澤燔燎，材木流津，廣廈騰煙，土浮霜鹵，止水乃減，蔓草焦黃，風行惑言，濕化乃後。故民病少氣，瘡瘍癰腫，脅腹胸背面首，四支〈月真〉憤，臚脹瘍痱，嘔逆瘈瘲，骨痛，節乃有動，註下溫瘧，腹中暴痛，血溢流註，精液乃少，目赤心熱，甚則瞀悶懊憹，善暴死。刻終大溫，汗濡玄府，其乃發也。其氣四。動復則靜，陽極反陰，濕令乃化乃成，華發水凝，山川冰雪，焰陽午澤，怫之先兆也。","sortOrder":137},
  {"id":"s_work_hdnk_71_138","chapterId":"ch_work_hdnk_71","text":"有怫之應而後報也，皆觀其極而乃發也。木發無時，水隨火也。謹候其時，病可與期，失時反歲，五氣不行，生化收藏，政無恆也。","sortOrder":138},
  {"id":"s_work_hdnk_71_139","chapterId":"ch_work_hdnk_71","text":"帝曰：水發而雹雪，土發而飄驟，木發而毀折，金發而清明，火發而曛昧何氣使然？岐伯曰：氣有多少，發有微甚。微者當其氣，甚者兼其下，徵其下氣，而見可知也。","sortOrder":139},
  {"id":"s_work_hdnk_71_140","chapterId":"ch_work_hdnk_71","text":"帝曰：善。五氣之發不當位者何也？岐伯曰：命其差。帝曰：差有數乎？岐伯曰：後皆三十度而有奇也。","sortOrder":140},
  {"id":"s_work_hdnk_71_141","chapterId":"ch_work_hdnk_71","text":"帝曰：氣至而先後者何？岐伯曰：遠太過則其至先，遠不及則其至後，此後之常也。帝曰：當時而至者何也？岐伯曰：非太過非不及，則至當時，非是者害也。","sortOrder":141},
  {"id":"s_work_hdnk_71_142","chapterId":"ch_work_hdnk_71","text":"帝曰：善。氣有非時而化者何也？岐伯曰：太過者當其時，不及者歸其己勝也。","sortOrder":142},
  {"id":"s_work_hdnk_71_143","chapterId":"ch_work_hdnk_71","text":"帝曰：四時之氣，至有早晏高下左右，其候何如？岐伯曰：行有逆順，至有遲速，故太過者化先天，不及者化後天。","sortOrder":143},
  {"id":"s_work_hdnk_71_144","chapterId":"ch_work_hdnk_71","text":"帝曰：願聞其行何謂也？岐伯曰：春氣西行，夏氣北行，秋氣東行，冬氣南行。故春氣始於下，秋氣始於上，夏氣始於中。冬氣始於標，春氣始於左，秋氣始於右，冬氣始於後，夏氣始於前，此四時正化之常。故至高之地，冬氣常在，至下之地，春氣常在。必謹察之。帝曰：善。","sortOrder":144},
  {"id":"s_work_hdnk_71_145","chapterId":"ch_work_hdnk_71","text":"黃帝問曰：五運六氣之應見，六化之正，六變之紀何如？岐伯對曰：夫六氣正紀，有化有變，有勝有負，有用有病，不同其候，帝欲何乎？帝曰：願盡聞之。","sortOrder":145},
  {"id":"s_work_hdnk_71_146","chapterId":"ch_work_hdnk_71","text":"岐伯曰：請遂言之。夫氣之所至也，厥陰所至為和平，少陰所至為暄，太陰所至為埃溽，少陽所至為炎暑，陽明所至為清勁，太陽所至為寒氛，時化之常也。厥陰所至為風府，為興啟；少陰所至為火府，為舒榮；太陰所至為雨府，為員盈；少陽所至為熱府，為行出；陽明所至為司殺府，為庚蒼；太陽所至為寒府，為歸藏；司化之常也。","sortOrder":146},
  {"id":"s_work_hdnk_71_147","chapterId":"ch_work_hdnk_71","text":"厥陰所至，為生為風搖；少陰所至，為榮為形見；太陰所至，為化為雲雨；少陽所至，為長為蕃鮮；陽明所至，為收為霧露；太陽所至，為藏為周密；氣化之常也。厥陰所至，為風生，終為肅；少陰所至，為熱生，中為寒；太陰所至，為濕生，終為註雨，少陽所至，為火生，終為蒸溽；陽明所至，為燥生，終為涼；太陽所至，為寒生，中為溫，德化之常也。","sortOrder":147},
  {"id":"s_work_hdnk_71_148","chapterId":"ch_work_hdnk_71","text":"厥陰所至為毛化，少陰所至為羽化，太陰所至為倮化，少陽所至為羽化，陽明所至為介化，太陽所至為鱗化，德化之常也？","sortOrder":148},
  {"id":"s_work_hdnk_71_149","chapterId":"ch_work_hdnk_71","text":"厥陰所至為生化，少陰所至為榮化，太陰所至為濡化，少陽所至為茂化，陽明所至為堅化，太陽所至為藏化，布政之常也。","sortOrder":149},
  {"id":"s_work_hdnk_71_150","chapterId":"ch_work_hdnk_71","text":"厥陰所至為飄怒太涼，少陰所至為太暄寒，太陰所至為雷霆驟註烈風，少陽所至為飄風燔燎霜凝，陽明所至為散落溫，太陽所至為寒雪冰雹白埃，氣變之常也。","sortOrder":150},
  {"id":"s_work_hdnk_71_151","chapterId":"ch_work_hdnk_71","text":"厥陰所至為撓動，為迎隨；少陰所至為高明焰，為曛；太陰所至為沈陰，為白埃，為晦瞑；少陽所至為光顯，為彤雲，為曛；陽明所至為煙埃，為霜，為勁切，為淒嗚；太陽所至為剛固，為堅芒，為立，令行之常也。","sortOrder":151},
  {"id":"s_work_hdnk_71_152","chapterId":"ch_work_hdnk_71","text":"厥陰所至為裏急，少陰所至為瘍眕身熱，太陰所至為積飲否隔，少陽所至為嚏嘔為瘡瘍，陽明所至為浮虛，太陽所至為屈伸不利，病之常也。","sortOrder":152},
  {"id":"s_work_hdnk_71_153","chapterId":"ch_work_hdnk_71","text":"厥陰所至為支痛，少陰所至為驚惑，惡寒戰慄，譫妄，太陰所至為積滿，少陽所至驚躁，瞀昧暴病，陽明所至為鼽尻陰股膝髀腨胻足病，太陽所至為腰痛，病之常也。","sortOrder":153},
  {"id":"s_work_hdnk_71_154","chapterId":"ch_work_hdnk_71","text":"厥陰所至為緛戾，少陰所至為悲妄衄衊，太陰所至為中滿霍亂吐下，少陽所至為喉痺耳嗚嘔涌，陽明所至皴揭，太陽所至為寢汗痙，病之常也。","sortOrder":154},
  {"id":"s_work_hdnk_71_155","chapterId":"ch_work_hdnk_71","text":"厥陰所至為脅痛、嘔泄，少陰所至為語笑，太陰所至為重胕腫，少陽所至為暴註，瞤瘈，暴死，陽明所至為鼽嚏，太陽所至為流泄，禁止，病之常也。","sortOrder":155},
  {"id":"s_work_hdnk_71_156","chapterId":"ch_work_hdnk_71","text":"凡此十二變者，報德以德，報化以化，報政以政，報令以令，氣高則高，氣下則下，氣後則後，氣前則前，氣中則中，氣外則外，位之常也。故風勝則動，熱勝則腫，燥熱則乾，寒勝則浮，濕勝則濡泄，甚則水閉胕腫，隨氣所在，以言其變耳。","sortOrder":156},
  {"id":"s_work_hdnk_71_157","chapterId":"ch_work_hdnk_71","text":"帝曰：願聞其用也。岐伯曰：夫六氣之用，各歸不勝而為化，故太陰雨化，施於太陽；太陽寒化，施於少陰，少陰熱化，施於陽明；陽明燥化，施於厥陰；厥陰風化，施於太陰，各命其所在以徵之也。","sortOrder":157},
  {"id":"s_work_hdnk_71_158","chapterId":"ch_work_hdnk_71","text":"帝曰：自得其位何如？岐伯曰：自得其位常化也。帝曰：願聞所在也。岐伯曰：命其位而方月可知也。帝曰：六位之氣盈虛何如？岐伯曰：太少異也。太者之至徐而常，少者暴而亡。","sortOrder":158},
  {"id":"s_work_hdnk_71_159","chapterId":"ch_work_hdnk_71","text":"帝曰：天地之氣盈虛何如？岐伯曰：天氣不足，地氣隨之；地氣不足，天氣從之，運居其中而常先也。惡所不勝，歸所同和，隨運歸從，而生其病也。故上勝則天氣降而下，下勝則地氣遷而上。多少而差其分，微者小差，甚者大差，甚則位易氣交，易則大變生而病作矣。大要曰：甚紀五分，微紀七分，其差可見，此之謂也。","sortOrder":159},
  {"id":"s_work_hdnk_71_160","chapterId":"ch_work_hdnk_71","text":"帝曰：善。論言熱無犯熱，寒無犯寒，餘欲不遠寒不遠熱奈何？岐伯曰：悉乎哉問也。發表而不遠熱，攻裏不遠寒。帝曰：不發不攻，而犯寒犯熱何如？岐伯曰：寒熱內賊，其病益甚。","sortOrder":160},
  {"id":"s_work_hdnk_71_161","chapterId":"ch_work_hdnk_71","text":"帝曰：願聞無病者何如？岐伯曰：無者生之，有者甚之。帝曰：生者何如？岐伯曰：不遠熱則熱至，不遠寒則寒至，寒至則堅否，腹滿、痛急、下利之病生矣。熱至則身熱，吐下霍亂，癰疽瘡瘍、瞀鬱、註下、瞤瘈、腫脹、嘔、鼽衄、頭痛、骨節變、肉痛、血溢、血泄、淋閟之病作矣。","sortOrder":161},
  {"id":"s_work_hdnk_71_162","chapterId":"ch_work_hdnk_71","text":"帝曰：治之奈何？岐伯曰：時必順之，犯者治以勝也。","sortOrder":162},
  {"id":"s_work_hdnk_71_163","chapterId":"ch_work_hdnk_71","text":"黃帝問曰：婦人重身，毒之何如？岐伯曰：有故無損，亦無殞也。帝曰：願聞其故何謂也？岐伯曰：大積大聚，其可犯也，哀其太半而止，過者死。","sortOrder":163},
  {"id":"s_work_hdnk_71_164","chapterId":"ch_work_hdnk_71","text":"帝曰：善。鬱之甚者，治之奈何？岐伯曰：木鬱達之，火鬱發之，土鬱奪之，金鬱泄之，水鬱折之，然調其氣。過者折之，以其畏也，所謂瀉之。帝曰：假者何如？岐伯曰：有假其氣，則無禁也。所謂主氣不足，客氣勝也。","sortOrder":164},
  {"id":"s_work_hdnk_71_165","chapterId":"ch_work_hdnk_71","text":"帝曰：至哉。聖人之道，天地大化，運行之節，臨御之紀，陰陽之政，寒暑之令，非夫子孰能通之，請藏之靈蘭之室，署曰六元正紀，非齋戒不敢示，慎傳也。","sortOrder":165},
  {"id":"s_work_hdnk_72_1","chapterId":"ch_work_hdnk_72","text":"至真要大論篇第七十四","sortOrder":1},
  {"id":"s_work_hdnk_72_2","chapterId":"ch_work_hdnk_72","text":"黃帝問曰：五氣交合，盈虛更作，餘知之矣。六氣分治，司天地者，其至何如？岐伯再拜對曰：明乎哉問也。天地之大紀，人神之通應也。","sortOrder":2},
  {"id":"s_work_hdnk_72_3","chapterId":"ch_work_hdnk_72","text":"帝曰：願聞上合昭昭，下合冥冥奈何？岐伯曰：此道之所主，工之所疑也。","sortOrder":3},
  {"id":"s_work_hdnk_72_4","chapterId":"ch_work_hdnk_72","text":"帝曰：願聞其道也。岐伯曰：厥陰司天，其化以風；少陰司天，其化以熱；太陰司天，其化以濕；少陽司天，其化以火；陽明司天，其化以燥；太陽司天，其化以寒，以所臨臟位，命其病者也。","sortOrder":4},
  {"id":"s_work_hdnk_72_5","chapterId":"ch_work_hdnk_72","text":"帝曰：地化奈何？岐伯曰：司天同候，間氣皆然。","sortOrder":5},
  {"id":"s_work_hdnk_72_6","chapterId":"ch_work_hdnk_72","text":"帝曰：間氣何謂？岐伯曰：司左右者是謂間氣也。","sortOrder":6},
  {"id":"s_work_hdnk_72_7","chapterId":"ch_work_hdnk_72","text":"帝曰：何以異之？岐伯曰：主歲者紀歲，間氣者紀步也。","sortOrder":7},
  {"id":"s_work_hdnk_72_8","chapterId":"ch_work_hdnk_72","text":"帝曰：善。歲主奈何？岐伯曰：厥陰司天為風化，在泉為酸化，司氣為蒼化，間氣為動化。","sortOrder":8},
  {"id":"s_work_hdnk_72_9","chapterId":"ch_work_hdnk_72","text":"少陰司天為熱化，在泉為苦化，不司氣化，居氣為灼化。","sortOrder":9},
  {"id":"s_work_hdnk_72_10","chapterId":"ch_work_hdnk_72","text":"太陰司天為濕化，在泉為甘化，司氣為黅化，間氣為柔化。","sortOrder":10},
  {"id":"s_work_hdnk_72_11","chapterId":"ch_work_hdnk_72","text":"少陽司天為火化，在泉為苦化，司氣為丹化，間氣為明化。","sortOrder":11},
  {"id":"s_work_hdnk_72_12","chapterId":"ch_work_hdnk_72","text":"陽明司天為燥化，在泉為辛化，司氣為素化，間氣為清化。","sortOrder":12},
  {"id":"s_work_hdnk_72_13","chapterId":"ch_work_hdnk_72","text":"太陽司天為寒化，在泉為鹹化，司氣為玄化，間氣為藏化。","sortOrder":13},
  {"id":"s_work_hdnk_72_14","chapterId":"ch_work_hdnk_72","text":"故治病者，必明六化分治，五味五色所生，五藏所宜，乃可以言盈虛病生之緒也。","sortOrder":14},
  {"id":"s_work_hdnk_72_15","chapterId":"ch_work_hdnk_72","text":"帝曰：厥陰在泉，而酸化先，餘知之矣。風化之行也何如？岐伯曰：風行於地，所謂本也，餘氣同法。本乎天者，天之氣也；本乎地者，地之氣也。天地合氣，六節分而萬物化生矣。故曰：謹候氣宜，無失病機，此之謂也。","sortOrder":15},
  {"id":"s_work_hdnk_72_16","chapterId":"ch_work_hdnk_72","text":"帝曰：其主病何如？岐伯曰：司歲備物，則無遺主矣。","sortOrder":16},
  {"id":"s_work_hdnk_72_17","chapterId":"ch_work_hdnk_72","text":"帝曰：先歲物何也？岐伯曰：天地之專精也。","sortOrder":17},
  {"id":"s_work_hdnk_72_18","chapterId":"ch_work_hdnk_72","text":"帝曰：司氣者何如？岐伯曰：司氣者主歲同然，有餘不足也。","sortOrder":18},
  {"id":"s_work_hdnk_72_19","chapterId":"ch_work_hdnk_72","text":"帝曰：非司歲物何謂也？岐伯曰：散也，故質同而昇等也。氣味有薄厚，性用有躁靜，治保有多少，力化有淺深，此之謂也。","sortOrder":19},
  {"id":"s_work_hdnk_72_20","chapterId":"ch_work_hdnk_72","text":"帝曰：歲主臟害何謂？岐伯曰：以所不勝命之，則其要也。","sortOrder":20},
  {"id":"s_work_hdnk_72_21","chapterId":"ch_work_hdnk_72","text":"帝曰：治之奈何？岐伯曰：上淫於下，所勝平之；外淫於內，所勝治之。","sortOrder":21},
  {"id":"s_work_hdnk_72_22","chapterId":"ch_work_hdnk_72","text":"帝曰：善。平氣何如？岐伯曰：謹察陰陽所在而調之，以平為期。正者正治，反者反治。","sortOrder":22},
  {"id":"s_work_hdnk_72_23","chapterId":"ch_work_hdnk_72","text":"帝曰：夫子言察陰陽所在而調之，論言人迎與寸口相應，若引繩，小大齊等，命曰平。陰之所在寸口，何如？岐伯曰：視歲南北可知之矣。帝曰：願卒聞之。岐伯曰：北政之歲，少陰在泉，則寸口不應；厥陰在泉，則右不應；太陰在泉，則左不應；南政之歲，少陰司天，則寸口不應；厥陰司天，則右不應；太陰司天，則左不應；諸不應者反其診則見矣。","sortOrder":23},
  {"id":"s_work_hdnk_72_24","chapterId":"ch_work_hdnk_72","text":"帝曰：尺候何如？岐伯曰：北政之歲，三陰在下，則寸不應，三陰在上，則尺不應。南政之歲，三陰在天，則寸不應，三陰在泉，則尺不應，左右同。故曰知其要者，一言而終，不知其要，流散無窮，此之謂也。","sortOrder":24},
  {"id":"s_work_hdnk_72_25","chapterId":"ch_work_hdnk_72","text":"帝曰：善。天地之氣，內淫而病何如？岐伯曰：歲厥陰在泉，風淫所勝，則地氣不明，平野昧，草乃早秀。民病洒洒振寒，善伸數欠，心痛支滿，兩脅裏急，飲食不下，膈咽不通，食則嘔，腹脹善噫，得後與氣，則快然如衰，身體皆重。","sortOrder":25},
  {"id":"s_work_hdnk_72_26","chapterId":"ch_work_hdnk_72","text":"歲少陰在泉，熱淫所勝，則焰浮川澤，陰處反明。民病腹中常嗚，氣上沖胸、喘、不能久立，寒熱皮膚痛、目瞑齒痛、〈出頁〉腫、惡寒發熱如瘧，少腹中痛、腹大、蟄蟲不藏。","sortOrder":26},
  {"id":"s_work_hdnk_72_27","chapterId":"ch_work_hdnk_72","text":"歲太陰在泉，草乃早榮，濕淫所勝，則埃昏巖穀，黃反見黑，至陰之交。民病飲積心痛，耳聾，渾渾焞焞，溢腫喉痺，陰病血見，少腹痛腫，不得小便，病沖頭痛，目似脫，項似拔，腰似折，髀不可以回，膕如結，腨如別。","sortOrder":27},
  {"id":"s_work_hdnk_72_28","chapterId":"ch_work_hdnk_72","text":"歲少陽在泉，火淫所勝，則焰明郊野，寒熱更至。民病註泄赤白，少腹痛，溺赤，甚則血便，少陰同候。","sortOrder":28},
  {"id":"s_work_hdnk_72_29","chapterId":"ch_work_hdnk_72","text":"歲陽明在泉，燥淫所勝，則霧霧清瞑。民病喜嘔，嘔有苦，善太息，心脅痛，不能反側，甚則嗌幹，面塵，身無膏澤，足外反熱。","sortOrder":29},
  {"id":"s_work_hdnk_72_30","chapterId":"ch_work_hdnk_72","text":"歲太陽在泉，寒淫所勝，則凝肅慘栗。民病少腹控睪引腰脊，上沖心痛，血見嗌痛，頷腫。","sortOrder":30},
  {"id":"s_work_hdnk_72_31","chapterId":"ch_work_hdnk_72","text":"帝曰：善。治之奈何？岐伯曰：諸氣在泉，風淫於內，治以辛涼，佐以苦；以甘緩之，以辛散之；熱淫於內，治以鹹寒，佐以甘苦，以酸收之，以苦發之；濕淫於內，治以苦熱，佐以酸淡，以苦燥之，以淡泄之，火淫於內，治以鹹冷，佐以苦辛，以酸收之，以苦發之；燥淫於內，治以苦溫，佐以甘辛，以苦下之；寒淫於內，治以甘熱，佐以苦辛，以鹹瀉之，以辛潤之，以苦堅之。","sortOrder":31},
  {"id":"s_work_hdnk_72_32","chapterId":"ch_work_hdnk_72","text":"帝曰：善。天氣之變何如？岐伯曰：厥陰司天，風淫所勝，則太虛埃昏，雲物以擾，寒生春氣，流水不冰。民病胃脘當心而痛，上肢兩脅，膈咽不通，飲食不下，舌本強，食則嘔，冷泄腹脹，溏泄瘕水閉，蟄蟲不去病本於脾。沖陽絕，死不治。","sortOrder":32},
  {"id":"s_work_hdnk_72_33","chapterId":"ch_work_hdnk_72","text":"少陰司天，熱淫所勝，怫熱至，火行其政。民病胸中煩熱，溢幹、右胠滿、皮膚痛，寒熱咳喘，大雨且至、唾血血泄、鼽衄、嚏嘔、溺色變，甚則瘡瘍胕腫、肩背臂臑及缺盆中痛，心痛肺〈月真〉，腹大滿，膨膨而喘咳，病本於肺，尺澤絕，死不治。","sortOrder":33},
  {"id":"s_work_hdnk_72_34","chapterId":"ch_work_hdnk_72","text":"太陰司天，濕淫所勝，則沉陰且布，雨變枯槁，胕腫骨痛，陰痺。陰痺者，按之不得，腰脊頭項痛、時眩、大便難，陰氣不用，饑不欲食，咳唾則有血，心如懸。病本於腎，太溪絕，死不治。","sortOrder":34},
  {"id":"s_work_hdnk_72_35","chapterId":"ch_work_hdnk_72","text":"少陽司天，火淫所勝，則溫氣流行，金政不平。民病頭痛，發熱惡寒而瘧，熱上皮膚痛，色變黃赤，傳而為水，身面胕腫、腹滿仰息、泄註赤白、瘡瘍、咳唾血、煩心，胸中熱，甚則鼽衄，病本於肺。天府絕，死不治。","sortOrder":35},
  {"id":"s_work_hdnk_72_36","chapterId":"ch_work_hdnk_72","text":"陽明司天，燥淫所勝，則木乃晚榮，草乃晚生，筋骨內變。民病左胠脅痛，寒清於中，感而瘧，大涼革候，咳、腹中嗚，註泄鶩溏，名木斂生，菀於下，草焦上首，心脅暴痛，不可反側，嗌幹面塵腰痛，丈夫〈疒頽〉疝，婦人少腹痛，目昧眥，瘍瘡痤癰，蟄蟲來見，病本於肝。太沖絕，死不治。","sortOrder":36},
  {"id":"s_work_hdnk_72_37","chapterId":"ch_work_hdnk_72","text":"太陽司天，寒淫所勝，則寒氣反至，水且冰，血變於中，發為癰瘍。民病厥心痛，嘔血、血泄、鼽衄，善悲，時眩仆。運火炎烈，雨暴乃雹。胸腹滿、手熱肘攣，掖腫、心淡淡大動，胸脅胃脘不安、面赤目黃、善噫嗌幹，甚則色炲，渴而欲飲，病本於心。神門絕，死不治。","sortOrder":37},
  {"id":"s_work_hdnk_72_38","chapterId":"ch_work_hdnk_72","text":"所謂動氣，知其臟也。","sortOrder":38},
  {"id":"s_work_hdnk_72_39","chapterId":"ch_work_hdnk_72","text":"帝曰：善。治之奈何？岐伯曰：司天之氣，風淫所勝，平以辛涼，佐以苦甘，以甘緩之，以酸瀉之。熱淫所勝，平以鹹寒，佐以苦甘，以酸收之。濕淫所勝，平以苦熱，佐以酸辛，以苦燥之，以淡泄之。濕上甚而熱，治以苦溫，佐以甘辛，以汗為故而止。火淫所勝，平以酸冷，佐以苦甘，以酸收之，以苦發之，以酸復之。熱淫同。燥淫所勝，平以苦濕，佐以酸辛，以苦下之。寒淫所勝，平以辛熱，佐以甘苦，以鹹瀉之。","sortOrder":39},
  {"id":"s_work_hdnk_72_40","chapterId":"ch_work_hdnk_72","text":"帝曰：善。邪氣反勝，治之奈何？岐伯曰：風司於地，清反勝之，治以酸溫，佐以苦甘，以辛平之。熱司於地，寒反勝之，治以甘熱，佐以苦辛，以鹹平之。濕司於地，熱反勝之，治以苦冷，佐以鹹甘以苦平之。。火司於地，寒反勝之，治以甘熱，佐以苦辛，以鹹平之。燥司於地，熱反勝之，治以平寒，佐以苦甘，以酸平之，以和為利。寒司於地，熱反勝之，治以鹹冷，佐以甘辛，以苦平之。","sortOrder":40},
  {"id":"s_work_hdnk_72_41","chapterId":"ch_work_hdnk_72","text":"帝曰：其司天邪勝何如？岐伯曰：風化於天，清反勝之，治以酸溫，佐以甘苦。熱化於天，寒反勝之，治以甘溫，佐以苦酸辛。濕化於天，熱反勝之，治以苦寒，佐以苦酸。火化於天，寒反勝之，治以甘熱，佐以苦辛。燥化於天，熱反勝之，治以辛寒，佐以苦甘。寒化於天，熱反勝之，治以鹹冷，佐以苦辛。","sortOrder":41},
  {"id":"s_work_hdnk_72_42","chapterId":"ch_work_hdnk_72","text":"帝曰：六氣相勝奈何？岐伯曰：厥陰之勝，耳嗚頭眩，憒憒欲吐，胃膈如寒。大風數舉，倮蟲不滋。胠脅氣併，化而為熱，小便黃赤，胃脘當心而痛，上肢兩脅，腸嗚飧泄，少腹痛，註下赤白，甚則嘔吐，膈咽不通。","sortOrder":42},
  {"id":"s_work_hdnk_72_43","chapterId":"ch_work_hdnk_72","text":"少陰之勝，心下熱，善饑，齊下反動，氣遊三焦。炎暑至，木乃津，草乃萎。嘔逆躁煩、腹滿痛、溏泄，傳為赤沃。","sortOrder":43},
  {"id":"s_work_hdnk_72_44","chapterId":"ch_work_hdnk_72","text":"太陰之勝，火氣內鬱，瘡瘍於中，流散於外，病在胠脅，甚則心痛，熱格，頭痛、喉痺、項強。獨勝則濕氣內鬱，寒迫下焦，痛留頂，互引眉間，胃滿。雨數至，燥化乃見。少腹滿，腰脽重強，內不便，善註泄，足下溫，頭重，足脛胕腫，飲發於中，胕腫於上。","sortOrder":44},
  {"id":"s_work_hdnk_72_45","chapterId":"ch_work_hdnk_72","text":"少陽之勝，熱客於胃，煩心、心痛、目赤，欲嘔、嘔酸、善饑、耳痛、溺赤、善驚、譫妄。暴熱消爍，草萎水涸，介蟲乃屈。少腹痛，下沃赤白。","sortOrder":45},
  {"id":"s_work_hdnk_72_46","chapterId":"ch_work_hdnk_72","text":"陽明之勝，清發於中，左胠脅痛、溏泄、內為嗌塞、外發〈疒頽〉疝。大涼肅殺，華英改容，毛蟲乃殃。胸中不便，嗌塞而咳。","sortOrder":46},
  {"id":"s_work_hdnk_72_47","chapterId":"ch_work_hdnk_72","text":"太陽之勝，凝慄且至，非時水冰，羽乃後化。痔瘧發，寒厥入胃則內生心痛，陰中乃瘍，隱曲不利，互引陰股，筋肉拘苛，血脈凝泣，絡滿色變，或為血泄，皮膚否腫，腹滿食減，熱反上行，頭項囪頂腦戶中痛，目如脫；寒入下焦，傳為濡瀉。","sortOrder":47},
  {"id":"s_work_hdnk_72_48","chapterId":"ch_work_hdnk_72","text":"帝曰：治之奈何？岐伯曰：厥陰之勝，治以甘清，佐以苦辛，以酸瀉之。少陰之勝，治以辛寒，佐以苦鹹，以甘瀉之，太陰之勝，治以鹹熱，佐以辛甘，以苦瀉之。少陽之勝，治以辛寒，佐以甘鹹，以甘瀉之。陽明之勝，治以酸溫，佐以辛甘，以苦泄之。太陽之勝，治以甘熱，佐以辛酸，以鹹瀉之。","sortOrder":48},
  {"id":"s_work_hdnk_72_49","chapterId":"ch_work_hdnk_72","text":"帝曰：六氣之復何如？岐伯曰：悉乎哉問也。厥陰之復，少腹堅滿，裏急暴痛。偃木飛沙，倮蟲不榮。厥心痛，汗發嘔吐，飲食不入，入而復出，筋骨掉眩清厥，甚則入脾，食痺而吐。沖陽絕，死不治。","sortOrder":49},
  {"id":"s_work_hdnk_72_50","chapterId":"ch_work_hdnk_72","text":"少陰之復，懊熱內作，煩燥鼽嚏，少腹絞痛，火見燔〈火苪〉，嗌燥分註時止，氣動於左，上行於右，咳、皮膚痛、暴喑、心痛、鬱冒不知人，乃洒淅惡寒振栗，譫妄，寒已而熱，渴而欲飲，少氣骨痿，隔腸不便，外為浮腫，噦噫。赤氣後化，流水不冰，熱氣大行，介蟲不復。病痱胗瘡瘍、癰疽痤痔，甚則入，肺，咳而鼻淵。天府絕，死不治。","sortOrder":50},
  {"id":"s_work_hdnk_72_51","chapterId":"ch_work_hdnk_72","text":"太陰之復，濕度乃舉，體重中滿，食飲不化，陰氣上厥，胸中不便，飲發於中，咳喘有聲。大雨時行，鱗見於陸，頭頂痛重，而掉瘈尤甚，嘔而密默，唾吐清液，甚則入腎竅，瀉無度。太溪絕，死不治。","sortOrder":51},
  {"id":"s_work_hdnk_72_52","chapterId":"ch_work_hdnk_72","text":"少陽之復，大熱將至，枯燥燔熱，介蟲乃耗。驚瘈咳衄，心熱煩燥，便數憎風，厥氣上行，面如浮埃，目乃瞤瘈；火氣內發，上為口糜、嘔逆、血溢、血泄，發而為瘧，惡寒鼓栗，寒極反熱，溢絡焦槁，渴引水漿，色變黃赤，少氣脈萎，化而為水，傳為胕腫，甚則入肺，咳而血泄。尺澤絕，死不治。","sortOrder":52},
  {"id":"s_work_hdnk_72_53","chapterId":"ch_work_hdnk_72","text":"陽明之復，清氣大舉，森木蒼乾，毛蟲乃厲。病生胠脅，氣歸於左，善太息，甚則心痛，否滿腹脹而泄，嘔苦咳噦煩心，病在膈中，頭痛，甚則入肝，驚駭筋攣。太沖絕，死不治。","sortOrder":53},
  {"id":"s_work_hdnk_72_54","chapterId":"ch_work_hdnk_72","text":"太陽之復，厥氣上行，水凝雨冰，羽蟲乃死。心胃生寒，胸膈不利，心痛否滿，頭痛善悲，時眩仆食減，腰脽反痛，屈伸不便，地裂冰堅，陽光不治，少腹控睪，引腰脊，上沖心，唾出清水，及為噦噫，甚則入心，善忘善悲。神門絕，死不治。","sortOrder":54},
  {"id":"s_work_hdnk_72_55","chapterId":"ch_work_hdnk_72","text":"帝曰：善。治之奈何？岐伯曰：厥陰之復，治以酸寒，佐以甘辛，以酸瀉之，以甘緩之。","sortOrder":55},
  {"id":"s_work_hdnk_72_56","chapterId":"ch_work_hdnk_72","text":"少陰之復，治以鹹寒，佐以苦辛，以甘瀉之，以酸收之，辛苦發之，以鹹軟之。","sortOrder":56},
  {"id":"s_work_hdnk_72_57","chapterId":"ch_work_hdnk_72","text":"太陰之復，治以苦熱，佐以酸辛，以苦瀉之，燥之、泄之。","sortOrder":57},
  {"id":"s_work_hdnk_72_58","chapterId":"ch_work_hdnk_72","text":"少陽之復，治以鹹冷，佐以苦辛，以鹹軟之，以酸收之，辛苦發之；發不遠熱，無犯溫涼。少陰同法。","sortOrder":58},
  {"id":"s_work_hdnk_72_59","chapterId":"ch_work_hdnk_72","text":"陽明之復，治以辛溫，佐以苦甘，以苦泄之，以苦下之，以酸補之。","sortOrder":59},
  {"id":"s_work_hdnk_72_60","chapterId":"ch_work_hdnk_72","text":"太陽之復，治以鹹熱，佐以甘辛，以苦堅之。","sortOrder":60},
  {"id":"s_work_hdnk_72_61","chapterId":"ch_work_hdnk_72","text":"治諸勝復，寒者熱之，熱者寒之，溫者清之，清者溫之，散者收之，抑者散之，燥者潤之，急者緩之，堅者軟之，脆者堅之，衰者補之，強者瀉之，各安其氣，必清必靜，則病氣衰去，歸其所宗，此治之大體也。","sortOrder":61},
  {"id":"s_work_hdnk_72_62","chapterId":"ch_work_hdnk_72","text":"帝曰：善。氣之上下何謂也？岐伯曰：身半以上其氣三矣，天之分也，天氣主之；身半以下，其氣三矣，地之分也，地氣主之。以名命氣，以氣命處，而言其病半，所謂天樞也。","sortOrder":62},
  {"id":"s_work_hdnk_72_63","chapterId":"ch_work_hdnk_72","text":"故上勝而下俱病者，以地名之；下勝而上俱病者，以天名之。所謂勝至，報氣屈伏而未發也。復至則不以天地異名，皆如復氣為法也。","sortOrder":63},
  {"id":"s_work_hdnk_72_64","chapterId":"ch_work_hdnk_72","text":"帝曰：勝復之動，時有常乎？氣有必乎？岐伯曰：時有常位，而氣無必也。帝曰：願聞其道也。岐伯曰：初氣終三氣，天氣主之，勝之常也；四氣盡終氣，地氣主之，復之常也。有勝則復，無勝則否。","sortOrder":64},
  {"id":"s_work_hdnk_72_65","chapterId":"ch_work_hdnk_72","text":"帝曰：善。復已而勝何如？岐伯曰：勝至而復，無常數也，衰乃止耳。復已而勝，不復則害，此傷生也。","sortOrder":65},
  {"id":"s_work_hdnk_72_66","chapterId":"ch_work_hdnk_72","text":"帝曰：復而反病何也？岐伯曰：居非其位，不相得也。大復其勝，則主勝之，故反病也，所謂火燥熱也。","sortOrder":66},
  {"id":"s_work_hdnk_72_67","chapterId":"ch_work_hdnk_72","text":"帝曰：治之何如？岐伯曰：夫氣之勝也，微者隨之，甚者製之；氣之復也，和者平之，暴者奪之。皆隨勝氣，安其屈伏，無問其數，以平為期，此其道也。","sortOrder":67},
  {"id":"s_work_hdnk_72_68","chapterId":"ch_work_hdnk_72","text":"帝曰：善。客主之勝復奈何？岐伯曰：客主之氣，勝而無負也。帝曰：其逆從何如？岐伯曰：主勝逆，客勝從，天之道也。","sortOrder":68},
  {"id":"s_work_hdnk_72_69","chapterId":"ch_work_hdnk_72","text":"帝曰：其生病何如？岐伯曰：厥陰司天，客勝則耳嗚掉眩，甚則咳，主勝則胸脅痛，舌難以言。","sortOrder":69},
  {"id":"s_work_hdnk_72_70","chapterId":"ch_work_hdnk_72","text":"少陰司天，客勝則鼽、嚏、頸項強、肩背瞀熱、頭痛、少氣，發熱、耳聾、目瞑，甚則胕腫、血溢、瘡瘍、咳喘。主勝則心熱煩躁，甚則脅痛支滿。","sortOrder":70},
  {"id":"s_work_hdnk_72_71","chapterId":"ch_work_hdnk_72","text":"太陰司天，客勝則首面胕腫，呼吸氣喘。主勝則胸腹滿，食已而瞀。","sortOrder":71},
  {"id":"s_work_hdnk_72_72","chapterId":"ch_work_hdnk_72","text":"少陽司天，客勝則丹胗外發，及為丹熛、瘡瘍、嘔逆、喉痺、頭痛、溢腫、耳聾、血溢、內為瘈瘲。主勝則胸滿、咳、仰息，甚而有血，手熱。","sortOrder":72},
  {"id":"s_work_hdnk_72_73","chapterId":"ch_work_hdnk_72","text":"陽明司天，清復內餘，則咳、衄、嗌塞、心鬲中熱，咳不止，而白血出者死。","sortOrder":73},
  {"id":"s_work_hdnk_72_74","chapterId":"ch_work_hdnk_72","text":"太陽司天，客勝則胸中不利，出清涕，感寒則咳，主勝則喉嗌中鳴。","sortOrder":74},
  {"id":"s_work_hdnk_72_75","chapterId":"ch_work_hdnk_72","text":"厥陰在泉，客勝則大關節不利，內為痙強拘瘈，外為不便；主勝則筋骨繇併，腰腹時痛。","sortOrder":75},
  {"id":"s_work_hdnk_72_76","chapterId":"ch_work_hdnk_72","text":"少陰在泉，客勝則腰痛、尻、股、膝、髀、腨、胻、足痛，瞀熱以酸，胕腫不能久立，溲便變。主勝則厥氣上行，心痛發熱，鬲中，眾痺皆作，發於胠脅，魄汗不藏，四逆而起。","sortOrder":76},
  {"id":"s_work_hdnk_72_77","chapterId":"ch_work_hdnk_72","text":"太陰在泉，客勝則足痿下重，便溲不時；濕客下焦，發而濡瀉及為腫隱曲之疾。主勝則寒氣逆滿，食飲不下，甚則為疝。","sortOrder":77},
  {"id":"s_work_hdnk_72_78","chapterId":"ch_work_hdnk_72","text":"少陽在泉，客勝則腰腹痛而反惡寒，甚則下白溺白；主勝則熱反上行，而客於心，心痛發熱，格中而嘔，少陰同候。","sortOrder":78},
  {"id":"s_work_hdnk_72_79","chapterId":"ch_work_hdnk_72","text":"陽明在泉，客勝則清氣動下，少腹堅滿，而數便瀉。主勝則腰重腹痛，少腹生寒，下為鶩溏，則寒厥於腸，上沖胸中，甚則喘，不能久立。","sortOrder":79},
  {"id":"s_work_hdnk_72_80","chapterId":"ch_work_hdnk_72","text":"太陽在泉，寒復內餘，則腰尻痛，屈伸不利，股脛足膝中痛。","sortOrder":80},
  {"id":"s_work_hdnk_72_81","chapterId":"ch_work_hdnk_72","text":"帝曰：善。治之奈何？岐伯曰：高者抑之，下者舉之，有餘折之，不足補之，佐以所利，和以所宜，必安其主客，適其寒溫，同者逆之，異者從之。","sortOrder":81},
  {"id":"s_work_hdnk_72_82","chapterId":"ch_work_hdnk_72","text":"帝曰：治寒以熱，治熱以寒，氣相得者逆之，不相得者從之，餘以知之矣。其於正味何如？岐伯曰：木位之主，其瀉以酸，其補以辛；火位之主，其瀉以甘，其補以鹹；土位之主，其瀉以苦，其補以甘；金味之主，其補以酸；水位之主，其瀉以鹹，其補以苦。","sortOrder":82},
  {"id":"s_work_hdnk_72_83","chapterId":"ch_work_hdnk_72","text":"厥陰之客，以辛補之，以酸瀉之，以甘緩之，少陰之客，以鹹補之，以甘瀉之，以鹹收之；太陰之客，以甘補之，以苦瀉之，以甘緩之。少陽之客，以鹹補之，以甘瀉之，以鹹軟之。陽明之客，以酸補之，以辛瀉之，以苦泄之；太陽之客，以苦補之，以鹹瀉之，以苦堅之，以辛潤之，開發腠理，致津液通氣也。","sortOrder":83},
  {"id":"s_work_hdnk_72_84","chapterId":"ch_work_hdnk_72","text":"帝曰：善。願聞陰陽之三也。何謂？岐伯曰：氣有多少異用也。","sortOrder":84},
  {"id":"s_work_hdnk_72_85","chapterId":"ch_work_hdnk_72","text":"帝曰：陽明何謂也？岐伯曰：兩陽合明也。","sortOrder":85},
  {"id":"s_work_hdnk_72_86","chapterId":"ch_work_hdnk_72","text":"帝曰：厥陰何也？岐伯曰：兩陰交盡也。","sortOrder":86},
  {"id":"s_work_hdnk_72_87","chapterId":"ch_work_hdnk_72","text":"帝曰：氣有多少，病有盛衰，治有緩急，方有大小，願聞其約奈何？岐伯曰：氣有高下，病有遠近，證有中外，治有輕重，適其至所為故也。","sortOrder":87},
  {"id":"s_work_hdnk_72_88","chapterId":"ch_work_hdnk_72","text":"大要也，君一臣二，奇之製也；君二臣四，偶之製也；君二臣三，奇之製也；君二臣六，偶之製也。","sortOrder":88},
  {"id":"s_work_hdnk_72_89","chapterId":"ch_work_hdnk_72","text":"故曰：近者奇之，遠者偶之；汗者不以奇，下者不以偶；補上治上製以緩，補下治下製以急；急則氣味厚，緩則氣味薄，適其至所，此之謂也。","sortOrder":89},
  {"id":"s_work_hdnk_72_90","chapterId":"ch_work_hdnk_72","text":"病所遠而中道氣味之者，貪而過之，無越其製度也。是故平氣之道，近而奇偶，製小其服也；遠而奇偶，製大其服也；大則數少，小則數多，多則九之，少則二之。","sortOrder":90},
  {"id":"s_work_hdnk_72_91","chapterId":"ch_work_hdnk_72","text":"奇之不去則偶之，是謂重方；偶之不去則反佐以取之，所謂寒熱溫涼反從其病也。","sortOrder":91},
  {"id":"s_work_hdnk_72_92","chapterId":"ch_work_hdnk_72","text":"帝曰：善。病生於本，餘知之矣。生於標者，治之奈何？岐伯曰：病反其本，得標之病，治反其本，得標之方。","sortOrder":92},
  {"id":"s_work_hdnk_72_93","chapterId":"ch_work_hdnk_72","text":"帝曰：善。六氣之勝，何以候之？岐伯曰：乘其至也；清氣大來，燥之勝也，風木受邪，肝病生焉；熱氣大來，火之勝也，金燥受邪，肺病生焉；寒氣大來，水之勝也，火熱受邪，心病生焉；濕氣大來，土之勝也，寒水受邪，腎病生焉；風氣大來，木之勝也，土濕受邪脾病生焉。所謂感邪而生病也。乘年之虛，則邪甚也。失時之和亦邪甚也。遇月之空，亦邪甚也。重感於邪，則病危矣。有勝之氣，其來必復也。","sortOrder":93},
  {"id":"s_work_hdnk_72_94","chapterId":"ch_work_hdnk_72","text":"帝曰：其脈至何如？岐伯曰：厥陰之至其脈絃，少陰之至其脈鉤，太陰之至其脈沉，少陽之至大而浮，陽明之至短而澀，太陽之至大而長。至而和則平，至而甚則病，至而反者病，至而不至者病，未至而至者病。陰陽易者危。","sortOrder":94},
  {"id":"s_work_hdnk_72_95","chapterId":"ch_work_hdnk_72","text":"帝曰：六氣標本所從不同奈何？岐伯曰：氣有從本者，有從標本者，有不從標本者也。帝曰：願卒聞之。岐伯曰：少陽太陰從本，少陰太陽從本從標，陽明厥陰不從標本，從乎中也。故從本者化生於本，從標本者有標本之化，從中者以中氣為化也。","sortOrder":95},
  {"id":"s_work_hdnk_72_96","chapterId":"ch_work_hdnk_72","text":"帝曰：脈從而病反者，其診何如？岐伯曰：脈至而從，按之不鼓，諸陽皆然。帝曰：諸陰之反，其脈何如？岐伯曰：脈至而從，按之鼓甚而盛也。","sortOrder":96},
  {"id":"s_work_hdnk_72_97","chapterId":"ch_work_hdnk_72","text":"是故百病之起有生於本者，有生於標者，有生於中氣者，有取本而得者，有取標而得者，有取中氣而得者，有取標本而得者，有逆取而得者，有從取而得者。逆，正順也，若順，逆也。","sortOrder":97},
  {"id":"s_work_hdnk_72_98","chapterId":"ch_work_hdnk_72","text":"故曰：知標與本，用之不殆，明知逆順，正行無問，此之謂也。不知是者，不足以言診，足以亂經。故大要曰：粗工嘻嘻，以為可知，言熱末已，寒病復始，同氣異形，迷診亂經，此之謂也。","sortOrder":98},
  {"id":"s_work_hdnk_72_99","chapterId":"ch_work_hdnk_72","text":"夫標本之道要而博，小而大，可以言一而知百病之害，言標與本，易而無損，察本與標，氣可令調，明知勝復，為萬民式，天之道畢矣。","sortOrder":99},
  {"id":"s_work_hdnk_72_100","chapterId":"ch_work_hdnk_72","text":"帝曰：勝復之變，早晏何如？岐伯曰：夫所勝者勝至已病，病已慍慍而復已萌也。夫所復者，勝盡而起，得位而甚，勝有微甚，復有少多，勝和而和，勝虛而虛，天之常也。","sortOrder":100},
  {"id":"s_work_hdnk_72_101","chapterId":"ch_work_hdnk_72","text":"帝曰：勝復之作，動不當位，或後時而至，其故何也？岐伯曰：夫氣之生與其化衰盛異也。寒暑溫涼盛衰之用，其在四維，故陽之動始於溫，盛於暑；陰之動始於清，盛於寒；春夏秋冬各差其分。故大要曰：彼春之暖；為夏之暑；彼秋之忿，為冬之怒。謹按四維，斥候皆歸，其終可見，其始可知，此之謂也。","sortOrder":101},
  {"id":"s_work_hdnk_72_102","chapterId":"ch_work_hdnk_72","text":"帝曰：差有數乎？岐伯曰：又凡三十度也。","sortOrder":102},
  {"id":"s_work_hdnk_72_103","chapterId":"ch_work_hdnk_72","text":"帝曰：其脈應皆何如？岐伯曰：差同正法，待時而去也。脈要曰：春不沉，夏不絃，冬不澀，秋不數，是謂四塞。沉甚曰病，絃甚曰病，澀甚曰病，數甚曰病，參見曰病，復見曰病，未去而去曰病，去而不去曰病，反者死。故曰氣之相守司也，如權衡之不得相失也。夫陰陽之氣清淨，則生化治，動則苛疾起，此之謂也。","sortOrder":103},
  {"id":"s_work_hdnk_72_104","chapterId":"ch_work_hdnk_72","text":"帝曰：幽明何如？岐伯曰：兩陰交盡故曰幽，兩陽合明故曰明。幽明之配，寒暑之異也。帝曰：分至何如？岐伯曰：氣至之謂至，氣分之謂分。至則氣同，分則氣異，所謂天地之正紀也。","sortOrder":104},
  {"id":"s_work_hdnk_72_105","chapterId":"ch_work_hdnk_72","text":"帝曰：夫子言春秋氣始於前，冬夏氣始於後，餘已知之矣。然六氣往復，主歲不常也，其補瀉奈何？岐伯曰：上下所主，隨其攸利，正其味，則其要也。左右同法。大要曰：少陽之主，先甘後鹹；陽明之主，先辛後酸；太陽之主，先鹹後苦；厥陰之主，先酸後辛；少陰之主，先甘後鹹；太陰之主，先苦後甘。佐以所利，資以所生，是謂得氣。","sortOrder":105},
  {"id":"s_work_hdnk_72_106","chapterId":"ch_work_hdnk_72","text":"帝曰：善。夫百病之生也，皆生於風寒暑濕燥火，以之化之變也。經言盛者瀉之，虛則補之，餘錫以方士，而方士用之尚未能十全，餘欲令要道必行，桴鼓相應，猶拔刺雪汗，工巧神聖，可得聞乎？岐伯曰：審察病機，無失氣宜，此之謂也。","sortOrder":106},
  {"id":"s_work_hdnk_72_107","chapterId":"ch_work_hdnk_72","text":"帝曰：願聞病機何如？岐伯曰：諸風掉眩，皆屬於肝；諸寒收引，皆屬於腎；諸氣膹鬱，皆屬於肺；諸濕腫滿，皆屬於脾；諸熱瞀瘈，皆屬於火；諸痛癢瘡，皆屬於心；諸厥固泄，皆屬於下；諸痿喘嘔，皆屬於上，諸禁鼓栗。如喪神守，皆屬於火；諸痙項強，皆屬於濕；諸逆沖上，皆屬於火；諸脹腹大，皆屬於熱；諸燥狂越，皆屬於火；諸暴強直，皆屬於風；諸病有聲，鼓之如鼓，皆屬於熱；諸病胕腫，疼酸驚駭，皆屬於火；諸轉反戾，水液渾濁，皆屬於熱；諸病水液，澄徹清冷，皆屬於寒，諸嘔吐酸，暴註下迫，皆屬於熱。","sortOrder":107},
  {"id":"s_work_hdnk_72_108","chapterId":"ch_work_hdnk_72","text":"故大要曰：謹守病機，各司其屬，有者求之，無者求之，盛者責之，虛者責之，必先五勝，疏其血氣，令其調達，而致和平，此之謂也。","sortOrder":108},
  {"id":"s_work_hdnk_72_109","chapterId":"ch_work_hdnk_72","text":"帝曰：善。五味陰陽之用何如？岐伯曰：辛甘發散為陽，酸苦涌泄為陰，鹹味涌泄為陰，淡味滲泄為陽。六者或收或散，或緩或急，或燥或潤或軟或堅，以所利而行之，調其氣使其平也。","sortOrder":109},
  {"id":"s_work_hdnk_72_110","chapterId":"ch_work_hdnk_72","text":"帝曰：非調氣而得者，治之奈何？有毒無毒，何先何後，願聞其道。岐伯曰：有毒無毒，所治為主，適大小為製也。","sortOrder":110},
  {"id":"s_work_hdnk_72_111","chapterId":"ch_work_hdnk_72","text":"帝曰：請言其製？岐伯曰：君一臣二，製之小也；君一臣三佐五，製之中也，君一臣三佐九，製之大也。","sortOrder":111},
  {"id":"s_work_hdnk_72_112","chapterId":"ch_work_hdnk_72","text":"寒者熱之，熱者寒之，微者逆之，甚者從之，堅者削之，客者除之，勞者溫之，結者散之，留者攻之，燥者濡之，急者緩之，散者收之，損者溫之，逸者行之，驚者平之，上之下之，摩之浴之，薄之劫之，開之發之，適事為故。","sortOrder":112},
  {"id":"s_work_hdnk_72_113","chapterId":"ch_work_hdnk_72","text":"帝曰：何謂逆從？岐伯曰：逆者正治，從者反治，從少從多，觀其事也。","sortOrder":113},
  {"id":"s_work_hdnk_72_114","chapterId":"ch_work_hdnk_72","text":"帝曰：反治何謂？岐伯曰：熱因寒用，寒因熱用，塞因塞用，通因通用，必伏其所主，而先其所因，其始則同，其終則異，可使破積，可使潰堅，可使氣和，可使必已。","sortOrder":114},
  {"id":"s_work_hdnk_72_115","chapterId":"ch_work_hdnk_72","text":"帝曰：善。氣調而得者何如？岐伯曰：逆之從之，逆而從之，從而逆之，疏氣令調，則其道也。","sortOrder":115},
  {"id":"s_work_hdnk_72_116","chapterId":"ch_work_hdnk_72","text":"帝曰：善。病之中外何如？岐伯曰：從內之外者，調其內，從外之內者，治其外；從內之外而盛於外者，先調其內而後治其外，從外之內而盛於內者，先治其外而後調其內；中外不相及，則治主病。","sortOrder":116},
  {"id":"s_work_hdnk_72_117","chapterId":"ch_work_hdnk_72","text":"帝曰：善。火熱復，惡寒發熱，有如瘧狀，或一日發，或間數日發，其故何也？岐伯曰：勝復之氣，會遇之時，有多少也。陰氣多而陽氣少，則其發日遠；陽氣多而陰氣少，則其發日近。此勝復相薄，盛衰之節，瘧亦同法。","sortOrder":117},
  {"id":"s_work_hdnk_72_118","chapterId":"ch_work_hdnk_72","text":"帝曰：論言治寒以熱，治熱以寒，而方士不能廢繩墨而更其道也。有病熱者寒之而熱，有病寒者熱之而寒，二者皆在，新病復起，奈何治？岐伯曰：諸寒之而熱者，取之陰；熱之而寒者，取之陽；所謂求其屬也。","sortOrder":118},
  {"id":"s_work_hdnk_72_119","chapterId":"ch_work_hdnk_72","text":"帝曰：善。服寒而反熱，服熱而反寒，其故何也？岐伯曰：治其王氣是以反也。","sortOrder":119},
  {"id":"s_work_hdnk_72_120","chapterId":"ch_work_hdnk_72","text":"帝曰：不治王而然者何也？岐伯曰：悉乎哉問也。不治五味屬也。夫五味入胃，各歸所喜，攻酸先入肝，苦先入心，甘先入脾，辛先入肺，鹹先入腎，久而增氣，物化之常也。氣增而久，夭之由也。","sortOrder":120},
  {"id":"s_work_hdnk_72_121","chapterId":"ch_work_hdnk_72","text":"帝曰：善。方製君臣，何謂也？岐伯曰：主病之謂君，佐君之謂臣，應臣之謂使，非上下三品之謂也。","sortOrder":121},
  {"id":"s_work_hdnk_72_122","chapterId":"ch_work_hdnk_72","text":"帝曰：三品何謂？岐伯曰：所以明善惡之殊貫也。","sortOrder":122},
  {"id":"s_work_hdnk_72_123","chapterId":"ch_work_hdnk_72","text":"帝曰：善。病之中外何如？岐伯曰：調氣之方，必別陰陽，定其中外，各守其鄉。內者內治，外者外治，微者調之，其次平之，盛者奪之，汗者下之，寒熱溫涼，衰之以屬，隨其攸利，謹道如法，萬舉萬全，氣血正平，長有天命。帝曰：善。","sortOrder":123},
  {"id":"s_work_hdnk_73_1","chapterId":"ch_work_hdnk_73","text":"著至教論篇第七十五","sortOrder":1},
  {"id":"s_work_hdnk_73_2","chapterId":"ch_work_hdnk_73","text":"黃帝坐明堂召雷公而問之曰：子知醫之道乎？雷公對曰：誦而頗能解，解而未能別，別而未能明，明而未能彰，足以治群僚，不足至侯王。願得受樹天之度，四時陰陽合之，別星辰與日月光，以彰經衡，後世益明，上通神農，著至教，疑於二皇。","sortOrder":2},
  {"id":"s_work_hdnk_73_3","chapterId":"ch_work_hdnk_73","text":"帝曰：善。無失之，此皆陰陽表裏，上下雌雄相輸應也。而道上知天文，下知地理，中知人事，可以長久，以教眾庶，亦不疑殆，醫道論篇，可傳後世，可以為寶。","sortOrder":3},
  {"id":"s_work_hdnk_73_4","chapterId":"ch_work_hdnk_73","text":"雷公曰：請受道諷誦用解。帝曰：子不聞陰陽傳乎？曰：不知。曰：夫三陽天為業。上下無常，合而病至，偏害陰陽。","sortOrder":4},
  {"id":"s_work_hdnk_73_5","chapterId":"ch_work_hdnk_73","text":"雷公曰：三陽莫當，請聞其解。帝曰：三陽獨至者，是三陽並至，並至如風雨，上為巔疾，下為漏病。外無期，內無正，不中經紀，診無上下以書別。","sortOrder":5},
  {"id":"s_work_hdnk_73_6","chapterId":"ch_work_hdnk_73","text":"雷公曰：臣治疏愈，說意而已。帝曰：三陽者至陽也，積並則為驚，病起疾風，至如礔礰，九竅皆塞，陽氣滂溢，乾嗌喉塞。並於陰則上下無常，薄為腸澼，此謂三陽直心，坐不得起臥者，便身全三陽之病。","sortOrder":6},
  {"id":"s_work_hdnk_73_7","chapterId":"ch_work_hdnk_73","text":"且以知天下，何以別陰陽，應四時，合之五行。","sortOrder":7},
  {"id":"s_work_hdnk_73_8","chapterId":"ch_work_hdnk_73","text":"雷公曰：陽言不別，陰言不理，請起受解，以為至道。","sortOrder":8},
  {"id":"s_work_hdnk_73_9","chapterId":"ch_work_hdnk_73","text":"帝曰：子若受傳，不知合至道以惑師教，語子至道之要。病傷五臟，筋骨以消，子言不明不別，是世主學盡矣。腎且絕，惋惋日暮，從容不出，人事不殷。","sortOrder":9},
  {"id":"s_work_hdnk_74_1","chapterId":"ch_work_hdnk_74","text":"示從容論第七十六","sortOrder":1},
  {"id":"s_work_hdnk_74_2","chapterId":"ch_work_hdnk_74","text":"黃帝燕坐，召雷公而問之曰：汝受術誦書者，若能覽觀雜學，及於比類，通合道理，為餘言子所長，五臟六腑，膽胃大小腸，脾胞膀胱，腦髓涕唾，哭泣悲哀，水所從行，此皆人之所生，治之過失，子務明之，可以十全，即不能知，為世所怨。","sortOrder":2},
  {"id":"s_work_hdnk_74_3","chapterId":"ch_work_hdnk_74","text":"雷公曰：臣請誦脈經上下篇，甚眾多矣。別異比類，猶未能以十全，又安足以明之？","sortOrder":3},
  {"id":"s_work_hdnk_74_4","chapterId":"ch_work_hdnk_74","text":"帝曰：子別試通五臟之過，六腑之所不和，針石之敗，毒藥所宜，湯液滋味，具言其狀，悉言以對，請問不知。","sortOrder":4},
  {"id":"s_work_hdnk_74_5","chapterId":"ch_work_hdnk_74","text":"雷公曰：肝虛、腎虛、脾虛皆令人體重煩冤，當投毒藥，刺灸砭石湯液，或已或不已，願聞其解。","sortOrder":5},
  {"id":"s_work_hdnk_74_6","chapterId":"ch_work_hdnk_74","text":"帝曰：公何年之長，而問之少，餘真問以自謬也。","sortOrder":6},
  {"id":"s_work_hdnk_74_7","chapterId":"ch_work_hdnk_74","text":"吾問子窈冥，子言上下篇以對，何也？","sortOrder":7},
  {"id":"s_work_hdnk_74_8","chapterId":"ch_work_hdnk_74","text":"夫脾虛浮似肺，腎小浮似脾，肝急沉散似腎，此皆工之所時亂也，然從客得之。","sortOrder":8},
  {"id":"s_work_hdnk_74_9","chapterId":"ch_work_hdnk_74","text":"若夫三臟土木水參居，此童子之所知，問之何也？","sortOrder":9},
  {"id":"s_work_hdnk_74_10","chapterId":"ch_work_hdnk_74","text":"雷公曰：於此有人，頭痛、筋攣、骨重，怯然少氣，噦、噫、腹滿、時驚不嗜臥，此何臟之發也？脈浮而絃，切之石堅，不知其解，復問所以三臟者，以知其比類也。","sortOrder":10},
  {"id":"s_work_hdnk_74_11","chapterId":"ch_work_hdnk_74","text":"帝曰：夫從容之謂也，夫年長則求之於腑，年少則求之於經，年壯則求之於臟。今子所言，皆失八風菀熱，五臟消爍，傳邪相受。夫浮而絃者，是腎不足也；沉而石者，是腎氣內著也；怯然少氣者，是水道不行，形氣消索也。咳嗽煩冤者，是腎氣之逆也。一人之氣，病在一臟也。若言三臟俱行，不在法也。","sortOrder":11},
  {"id":"s_work_hdnk_74_12","chapterId":"ch_work_hdnk_74","text":"雷公曰：於此有人，四肢解墮，喘咳血泄，而愚診之以為傷肺，切脈浮大而緊，愚不敢治。粗工下砭石，病愈，多出血，血止身輕，此何物也？帝曰：子所能治，知亦眾多，與此病失矣。譬以鴻飛、亦沖於天。","sortOrder":12},
  {"id":"s_work_hdnk_74_13","chapterId":"ch_work_hdnk_74","text":"夫經人之治病，循法守度，援物比類，化之冥冥，循上及下，何必守聖。","sortOrder":13},
  {"id":"s_work_hdnk_74_14","chapterId":"ch_work_hdnk_74","text":"今夫脈浮大虛者，是脾氣之外絕，去胃外歸陽明也。","sortOrder":14},
  {"id":"s_work_hdnk_74_15","chapterId":"ch_work_hdnk_74","text":"夫二火不勝三水，是以脈亂而無常也。","sortOrder":15},
  {"id":"s_work_hdnk_74_16","chapterId":"ch_work_hdnk_74","text":"四支解墮，此脾精之不行也。喘咳者，是水氣並陽明也。血泄者，脈急血無所行也。若夫以為傷肺者，由失以狂也。不引比類，是知不明也。","sortOrder":16},
  {"id":"s_work_hdnk_74_17","chapterId":"ch_work_hdnk_74","text":"夫傷肺者，脾氣不守，胃氣不清，經氣不為使，真臟壞決，經脈傍絕，五臟漏泄，不衄則嘔，此二者不相類也。","sortOrder":17},
  {"id":"s_work_hdnk_74_18","chapterId":"ch_work_hdnk_74","text":"譬如天之無形，地之無理，白與黑相去遠矣。","sortOrder":18},
  {"id":"s_work_hdnk_74_19","chapterId":"ch_work_hdnk_74","text":"是失我過矣，以子知之，故不告子，明引比類從容，是以名曰診輕，是謂至道也。","sortOrder":19},
  {"id":"s_work_hdnk_75_1","chapterId":"ch_work_hdnk_75","text":"疏五過論篇第七十七","sortOrder":1},
  {"id":"s_work_hdnk_75_2","chapterId":"ch_work_hdnk_75","text":"黃帝曰：嗚呼遠哉！閔閔乎若視深淵，若迎浮雲，視深淵尚可測，迎浮雲莫知其際，聖人之術，為萬民式，論裁志意，必有法則，循經守數，按循醫事，為萬民副。故事有五過四德，汝知之乎？","sortOrder":2},
  {"id":"s_work_hdnk_75_3","chapterId":"ch_work_hdnk_75","text":"雷公避席再拜曰：臣年幼小，蒙愚以惑，不聞五過與四德，比類形名，虛引其經，心無所對。","sortOrder":3},
  {"id":"s_work_hdnk_75_4","chapterId":"ch_work_hdnk_75","text":"帝曰：凡未診病者，必問嘗貴後賤，雖不中邪，病從內生，名曰脫營。嘗富後貪，名曰失精，五氣留連，病有所並。醫工診之，不在臟腑，不變軀形，診之而疑，不知病名，身體日減，氣虛無精，病深無氣，洒洒然時驚。病深者，以其外耗於衛，內奪於榮。良工所失，不知病情，此亦治之一過也。","sortOrder":4},
  {"id":"s_work_hdnk_75_5","chapterId":"ch_work_hdnk_75","text":"凡欲診病者，必問飲食居處，暴樂暴苦，始樂後苦，皆傷精氣。精氣竭絕，形體毀沮。暴怒傷陰，暴喜傷陽。厥氣上行，滿脈去形。愚醫治之，不知補瀉，不知病情，精華日脫，邪氣乃並，此治之二過也。","sortOrder":5},
  {"id":"s_work_hdnk_75_6","chapterId":"ch_work_hdnk_75","text":"善為脈者，必以比類、奇恒，從容知之，為工而不知道，此診之不足貴，此治之三過也。","sortOrder":6},
  {"id":"s_work_hdnk_75_7","chapterId":"ch_work_hdnk_75","text":"診有三常，必問貴賤，封君敗傷，及欲侯王？故貴脫勢，雖不中邪，精神內傷，身必敗亡。","sortOrder":7},
  {"id":"s_work_hdnk_75_8","chapterId":"ch_work_hdnk_75","text":"始富後貧，雖不傷邪，皮焦筋屈，痿躄為攣，醫不能嚴，不能動神，外為柔弱，亂至失常，病不能移，則醫事不行，此治之四過也。","sortOrder":8},
  {"id":"s_work_hdnk_75_9","chapterId":"ch_work_hdnk_75","text":"凡診者，必知終始，有知餘緒，切脈問名，當合男女。","sortOrder":9},
  {"id":"s_work_hdnk_75_10","chapterId":"ch_work_hdnk_75","text":"離絕菀結，憂恐喜怒，五臟空虛，血氣離守，工不能知，何術之語。","sortOrder":10},
  {"id":"s_work_hdnk_75_11","chapterId":"ch_work_hdnk_75","text":"嘗富大傷，斬筋絕脈，身體復行，令澤不息，故傷敗結，留薄歸陽，膿積寒熱。粗工治之，亟刺陰陽，身體解散，四支轉筋，死日有期，醫不能明，不問所發，惟言死日，亦為粗心，此治之五過也。","sortOrder":11},
  {"id":"s_work_hdnk_75_12","chapterId":"ch_work_hdnk_75","text":"凡此五者，皆受術不通，人事不明也。","sortOrder":12},
  {"id":"s_work_hdnk_75_13","chapterId":"ch_work_hdnk_75","text":"故曰：聖人之治病也，必知天地陰陽，四時經紀，五臟六腑，雌雄表裏。刺灸砭石，毒藥所主，從容人事，以明經道，貴賤貪富，各異品理，問年少長勇懼之理審於分部，知病本始，八正九候，診必副矣。","sortOrder":13},
  {"id":"s_work_hdnk_75_14","chapterId":"ch_work_hdnk_75","text":"治病之道，氣內為寶，循求其理，求之不得，過在表裏。","sortOrder":14},
  {"id":"s_work_hdnk_75_15","chapterId":"ch_work_hdnk_75","text":"守數據治，無失俞理，能行此術，終身不殆。","sortOrder":15},
  {"id":"s_work_hdnk_75_16","chapterId":"ch_work_hdnk_75","text":"不知俞理，五臟菀熱，癰發六腑。診病不審，是謂失常，謹守此治，與經相明。","sortOrder":16},
  {"id":"s_work_hdnk_75_17","chapterId":"ch_work_hdnk_75","text":"上經下經，揆度陰陽，奇恆五中，決以明堂，審於始終，可以橫行。","sortOrder":17},
  {"id":"s_work_hdnk_76_1","chapterId":"ch_work_hdnk_76","text":"徵四失論篇第七十八","sortOrder":1},
  {"id":"s_work_hdnk_76_2","chapterId":"ch_work_hdnk_76","text":"黃帝在明堂，雷公侍坐。黃帝曰：夫子所通書，受事眾多矣。試言得失之意，所以得之，所以失之。雷公對曰：循經受業，皆言十全，其時有過失者，請聞其事解也。","sortOrder":2},
  {"id":"s_work_hdnk_76_3","chapterId":"ch_work_hdnk_76","text":"帝曰：子年少，智未及邪，將言以雜合耶。夫經脈十二、絡脈三百六十五，此皆人之所明知，工之所循用也。所以不十全者。精神不專，志意不理，外內相失，故時疑殆。","sortOrder":3},
  {"id":"s_work_hdnk_76_4","chapterId":"ch_work_hdnk_76","text":"診不知陰陽逆從之理，此治之一失矣。","sortOrder":4},
  {"id":"s_work_hdnk_76_5","chapterId":"ch_work_hdnk_76","text":"受師不卒，妄作雜術，謬言為道，更名自功，妄用砭石、後遺身咎，此治之二失也。","sortOrder":5},
  {"id":"s_work_hdnk_76_6","chapterId":"ch_work_hdnk_76","text":"不適貧富貴賤之居，坐之薄厚，形之寒溫，不適飲食之宜，不別人之勇怯，不知比類，足以自亂，不足以自明，此治之三失也。","sortOrder":6},
  {"id":"s_work_hdnk_76_7","chapterId":"ch_work_hdnk_76","text":"診病不問其始，憂患飲食之失節，起居之過度，或傷於毒，不先言此，卒持寸口，何病能中，妄言作名，為粗所窮，此治之四失也。","sortOrder":7},
  {"id":"s_work_hdnk_76_8","chapterId":"ch_work_hdnk_76","text":"是以世人之語者，馳千里之外，不明尺寸之論，診無人事，治數之道，從容之葆。","sortOrder":8},
  {"id":"s_work_hdnk_76_9","chapterId":"ch_work_hdnk_76","text":"坐持寸口，診不中五脈，百病所起，始以自怨，遺師其咎，是故治不能循理，棄術於市，妄治時愈，愚心自得。","sortOrder":9},
  {"id":"s_work_hdnk_76_10","chapterId":"ch_work_hdnk_76","text":"嗚呼，窈窈冥冥，孰知其道。道之大者，擬於天地，配於四海，汝不知道之諭，受以明為晦。","sortOrder":10},
  {"id":"s_work_hdnk_77_1","chapterId":"ch_work_hdnk_77","text":"陰陽類論篇第七十九","sortOrder":1},
  {"id":"s_work_hdnk_77_2","chapterId":"ch_work_hdnk_77","text":"孟春始至，黃帝燕坐臨觀八極，正八風之氣，而問雷公曰：陰陽之類，經脈之道，五中所主，何臟最貴。雷公對曰：春甲乙青，中主肝，治七十二日，是脈之主時，臣以其臟最貴。","sortOrder":2},
  {"id":"s_work_hdnk_77_3","chapterId":"ch_work_hdnk_77","text":"帝曰：卻念上下經，陰陽從容，子所言貴，最其下也。","sortOrder":3},
  {"id":"s_work_hdnk_77_4","chapterId":"ch_work_hdnk_77","text":"雷公至齋七日，旦復侍坐。帝曰：三陽為經，二陽為維，一陽為遊部，此知五臟終始。三陽為表，二陰為裏，一陰至絕，作朔晦，卻具合以正其理。","sortOrder":4},
  {"id":"s_work_hdnk_77_5","chapterId":"ch_work_hdnk_77","text":"雷公曰：受業未能明？帝曰：所謂三陽者，太陽為經。三陽脈至手太陰，絃浮而不沈，決以度，察以心，合之陰陽之論。所謂二陽者陽明也，至手太陰，絃而沈急不鼓，炅至以病皆死。一陽者少陽也，至手太陰上連人迎，絃急懸不絕，此少陽之病也，專陰則死。","sortOrder":5},
  {"id":"s_work_hdnk_77_6","chapterId":"ch_work_hdnk_77","text":"三陰者，六經之所主也。交於太陰、伏鼓不浮，上空志心。二陰至肺，其氣歸膀胱，外連脾胃。一陰獨至，經絕氣浮，不鼓，鉤而滑。此六脈者，乍陰乍陽，交屬相並，繆通五臟，合於陰陽。先至為主，後至為客。","sortOrder":6},
  {"id":"s_work_hdnk_77_7","chapterId":"ch_work_hdnk_77","text":"雷公曰：臣悉盡意，受傳經脈，頌得從容之道以合從容，不知陰陽，不知雌雄？帝曰：三陽為父，二陽為衛，一陽為紀；三陰為母，二陰為雌，一陰為獨使。","sortOrder":7},
  {"id":"s_work_hdnk_77_8","chapterId":"ch_work_hdnk_77","text":"二陽一陰，陽明主病，不勝一陰，軟而動，九竅皆沈。","sortOrder":8},
  {"id":"s_work_hdnk_77_9","chapterId":"ch_work_hdnk_77","text":"三陽一陰，太陽脈勝，一陰不為止，內亂五臟，外為驚駭。","sortOrder":9},
  {"id":"s_work_hdnk_77_10","chapterId":"ch_work_hdnk_77","text":"二陰二陽病在肺，少陰脈沈，勝肺傷脾，外傷四支。","sortOrder":10},
  {"id":"s_work_hdnk_77_11","chapterId":"ch_work_hdnk_77","text":"二陰二陽皆交至，病在腎，罵詈妄行，巔疾為狂。","sortOrder":11},
  {"id":"s_work_hdnk_77_12","chapterId":"ch_work_hdnk_77","text":"二陰一陽，病出於腎。陰氣客遊於心脘，下空竅堤，閉塞不通，四肢別離。","sortOrder":12},
  {"id":"s_work_hdnk_77_13","chapterId":"ch_work_hdnk_77","text":"一陰一陽代絕，此陰氣至心，上下無常，出入不知，喉咽於燥，病在土脾。","sortOrder":13},
  {"id":"s_work_hdnk_77_14","chapterId":"ch_work_hdnk_77","text":"二陽三陰，至陰皆在，陰不過陽，陽氣不能止陰，陰陽並絕，浮為血瘦，沈為膿附。陰陽皆壯，下至陰陽，上合昭昭，下合冥冥，診決死生之期，遂含歲首。","sortOrder":14},
  {"id":"s_work_hdnk_77_15","chapterId":"ch_work_hdnk_77","text":"雷公曰：請問短期，黃帝不應。雷公復問，黃帝曰：在經論中。雷公曰：請問短期？黃帝曰：冬三月之病，病合於陽者，至春正月，脈有死證，皆歸出春。","sortOrder":15},
  {"id":"s_work_hdnk_77_16","chapterId":"ch_work_hdnk_77","text":"冬三月之病，在理已盡，草與柳葉皆殺，春陰陽皆，絕期在孟春。","sortOrder":16},
  {"id":"s_work_hdnk_77_17","chapterId":"ch_work_hdnk_77","text":"春三月之病曰陽殺，陰陽皆絕，期在草乾。","sortOrder":17},
  {"id":"s_work_hdnk_77_18","chapterId":"ch_work_hdnk_77","text":"夏三月之病，至陰不過十日，陰陽交，期在溓水。","sortOrder":18},
  {"id":"s_work_hdnk_77_19","chapterId":"ch_work_hdnk_77","text":"秋三月之病，三陽俱起，不治自己。陰陽交合者，立不能坐，坐不能起。三陽獨至，期在石水。二陰獨至，期在盛水。","sortOrder":19},
  {"id":"s_work_hdnk_78_1","chapterId":"ch_work_hdnk_78","text":"方盛衰論篇第八十","sortOrder":1},
  {"id":"s_work_hdnk_78_2","chapterId":"ch_work_hdnk_78","text":"雷公請問氣之多少，何者為逆，何者為從？黃帝答曰：陽從左，陰從右，老從上，少從下，是以春夏歸陽為生，歸秋冬為死，反之則歸秋冬為生，是以氣多少，逆皆為厥。","sortOrder":2},
  {"id":"s_work_hdnk_78_3","chapterId":"ch_work_hdnk_78","text":"問曰：有餘者厥耶？答曰：一上不下，寒厥到膝，少者秋冬死，老者秋冬生，氣上不下，頭痛巔疾，求陽不得，求陰不審，五部隔無徵，若居曠野，若伏空室，綿綿乎屬，不滿日。","sortOrder":3},
  {"id":"s_work_hdnk_78_4","chapterId":"ch_work_hdnk_78","text":"是以少氣之厥，令人妄夢，其極至迷。三陽絕，三陰微，是為少氣。","sortOrder":4},
  {"id":"s_work_hdnk_78_5","chapterId":"ch_work_hdnk_78","text":"是以肺氣虛則使人夢見白物，見人斬血借借。得其時則夢見兵戰。","sortOrder":5},
  {"id":"s_work_hdnk_78_6","chapterId":"ch_work_hdnk_78","text":"胃氣虛，則使人夢見舟船溺人，得其時則夢伏水中，若有畏恐。","sortOrder":6},
  {"id":"s_work_hdnk_78_7","chapterId":"ch_work_hdnk_78","text":"肝氣虛，則夢見蘭香生草，得其時則夢伏樹下不敢起。","sortOrder":7},
  {"id":"s_work_hdnk_78_8","chapterId":"ch_work_hdnk_78","text":"心氣虛，則夢救火陽物，得其時則夢燔灼。","sortOrder":8},
  {"id":"s_work_hdnk_78_9","chapterId":"ch_work_hdnk_78","text":"脾氣虛，則夢飲食不足，得其時則夢築垣蓋屋。","sortOrder":9},
  {"id":"s_work_hdnk_78_10","chapterId":"ch_work_hdnk_78","text":"此皆五臟氣虛，陽氣有餘，陰氣不足，合之五診，調之陰陽，以在經脈。","sortOrder":10},
  {"id":"s_work_hdnk_78_11","chapterId":"ch_work_hdnk_78","text":"診有十度，度人、脈度、臟度、肉度、筋度、俞度。陰陽氣盡，人病自具。脈動無常，散陰頗陽，脈脫不具，於無常行，診必上下，度民君卿，受師不卒，使術不明，不察逆從，是為妄行，持雌失雄，棄陰附陽，不知並合，診故不明，傳之後世，反論自章。","sortOrder":11},
  {"id":"s_work_hdnk_78_12","chapterId":"ch_work_hdnk_78","text":"至陰虛，天氣絕；至陽盛，地氣不足。陰陽並交，至人之所行。陰陽並交者，陽氣先至，陰氣後至。","sortOrder":12},
  {"id":"s_work_hdnk_78_13","chapterId":"ch_work_hdnk_78","text":"是以經人持診之道，先後陰陽而持之，奇恒之勢，乃六十首，診合微之事，追陰陽之變，章五中之情，其中之論，聖虛實之要，定五度之事，知此乃足以診。","sortOrder":13},
  {"id":"s_work_hdnk_78_14","chapterId":"ch_work_hdnk_78","text":"是以切陰不得陽，診消亡；得陽不得陰，守學不湛。知左不知右，知右不知左，知上不知下，知先不知後，故治不久。知丑知善，知病知不病，知高知下，知坐知起，知行知止，用之有紀，診道乃具，萬世不殆。","sortOrder":14},
  {"id":"s_work_hdnk_78_15","chapterId":"ch_work_hdnk_78","text":"起所有餘，知所不足，度事上下，脈事因格。是以形弱氣虛死，形氣有餘，脈氣不足死；脈氣有餘，形氣不足生。","sortOrder":15},
  {"id":"s_work_hdnk_78_16","chapterId":"ch_work_hdnk_78","text":"是以診有大方，坐起有常，出入有行，以轉神明，必清必淨，上觀下觀，司八正邪，別五中部，按脈動靜，循尺滑澀寒溫之意，視其大小，合之病能，逆從以得，復知病名，診可十全，不失人情，故診之或視息視意，故不失條理，道甚明察，故能長久。不知此道，失經絕理，亡言妄期，此謂失道。","sortOrder":16},
  {"id":"s_work_hdnk_79_1","chapterId":"ch_work_hdnk_79","text":"解精微論篇第八十一","sortOrder":1},
  {"id":"s_work_hdnk_79_2","chapterId":"ch_work_hdnk_79","text":"黃帝在明堂，雷公請曰：臣授業傳之行教，以經論從容，形法、陰陽、刺灸、湯液所滋，行治有腎不肖，未必能十全。若先言悲哀喜怒，燥濕寒暑，陰陽婦女，請問其所以然者。卑賤富貴，人之形體，所從群下，通使臨事以適道術，謹聞命矣。請問有毚愚仆漏之問，不在經者，欲聞其狀。帝曰：大矣。","sortOrder":2},
  {"id":"s_work_hdnk_79_3","chapterId":"ch_work_hdnk_79","text":"公請問哭泣而淚不出者，若出而少涕，其故何也？帝曰：在經有也。","sortOrder":3},
  {"id":"s_work_hdnk_79_4","chapterId":"ch_work_hdnk_79","text":"復問不知水所從生，涕所從出也。帝曰：若問此者，無益於治也。工之所知，道之所生也。夫心者，五臟之專精也，目者其竅也，華色者其榮也。是以人有德也，則氣和於目，有亡憂，知於色。","sortOrder":4},
  {"id":"s_work_hdnk_79_5","chapterId":"ch_work_hdnk_79","text":"是以悲哀則泣下，泣下水所由生，水宗者，積水也，積水者，至陰也。至陰者，腎之精也，宗精之水所以不出者，是精持之也，輔之裹之。故水不行也。夫水之精為志，火之精為神，水火相感，神志俱悲，是以目之水生也。故諺曰：心悲名曰志悲，志與心精共湊於目也。","sortOrder":5},
  {"id":"s_work_hdnk_79_6","chapterId":"ch_work_hdnk_79","text":"是以俱悲則神氣傳於心，精上不傳於志，而志獨悲，故泣出也。泣涕者，腦也，腦者陰也。髓者，骨之充也。故腦滲為涕。","sortOrder":6},
  {"id":"s_work_hdnk_79_7","chapterId":"ch_work_hdnk_79","text":"志者骨之主也。是以水流而涕從之者，其行類也，夫涕之與泣者，譬如人之兄弟，急則俱死，生則俱生，其志以早悲，是以涕泣俱出而橫行也。夫人涕泣俱出而相從者，所屬之類也。","sortOrder":7},
  {"id":"s_work_hdnk_79_8","chapterId":"ch_work_hdnk_79","text":"雷公曰：大矣。請問人哭泣而淚不出者，若出而少，涕不從之何也？帝曰：夫泣不出者，哭不悲也，不泣者，神不慈也，神不慈，則志不悲，陰陽相持，泣安能獨來。","sortOrder":8},
  {"id":"s_work_hdnk_79_9","chapterId":"ch_work_hdnk_79","text":"夫志悲者惋，惋則沖陰，沖陰則志去目，志去則神不守精，精神去目，涕泣出也。且子獨不誦不念夫經言乎？厥則目無所見。夫人厥則陽氣並於上，陰氣並於下，陽並於上則火獨光也；陰並於下則足寒，足寒則脹也。夫一水不勝五火，故目眥盲。","sortOrder":9},
  {"id":"s_work_hdnk_79_10","chapterId":"ch_work_hdnk_79","text":"是以沖風，泣下而不止。夫風之中目也，陽氣內守於精。是火氣燔目，故見風則泣下也。有以比之，夫火疾風生，乃能雨，此之類也。","sortOrder":10},
  {"id":"s_work_hdnk_80_1","chapterId":"ch_work_hdnk_80","text":"九鍼十二原第一","sortOrder":1},
  {"id":"s_work_hdnk_80_2","chapterId":"ch_work_hdnk_80","text":"黃帝問於岐伯曰：餘子萬民，養百姓而收其租稅；餘哀其不給而屬有疾病。餘欲勿使被毒藥，無用砭石，欲以微針通其經脈，調其血氣，榮其逆順出入之會。令可傳於後世，必明為之法，令終而不滅，久而不絕，易用難忘，為之經紀，異其章，別其表裏，為之終始。令各有形，先立針經。願聞其情。","sortOrder":2},
  {"id":"s_work_hdnk_80_3","chapterId":"ch_work_hdnk_80","text":"岐伯答曰：臣請推而次之，令有綱紀，始於一，終於九焉。請言其道！小針之要，易陳而難入。粗守形，上守神。神乎神，客在門。未赭其疾，惡知其原？刺之微在速遲。粗守關，上守機，機之動，不離其空。空中之機，清靜而微。其來不可逢，其往不可追。知機之道者，不可掛以發。不知機道，扣之不發。知其往來，要與之期。粗之闇乎，妙哉，工獨有之。往者為逆，來者為順，明知逆順，正行無問。迎而奪之，惡得無虛？追而濟之，惡得無實？迎之隨之，以意和之，針道畢矣。","sortOrder":3},
  {"id":"s_work_hdnk_80_4","chapterId":"ch_work_hdnk_80","text":"凡用針者，虛則實之，滿則泄之，宛陳則除之，邪勝則虛之。大要曰：徐而疾則實，疾而徐則虛。言實與虛，若有若無。察後與先。若存若亡。為虛與實，若得若失。","sortOrder":4},
  {"id":"s_work_hdnk_80_5","chapterId":"ch_work_hdnk_80","text":"虛實之要，九針最妙，補瀉之時，以針為之。瀉曰，必持內之，放而出之，排陽得針，邪氣得泄。按而引針，是謂內溫，血不得散，氣不得出也。補曰，隨之隨之，意若妄之。若行若按，如蚊虻止，如留如還，去如絃絕，令左屬右，其氣故止，外門已閉，中氣乃實，必無留血，急取誅之。","sortOrder":5},
  {"id":"s_work_hdnk_80_6","chapterId":"ch_work_hdnk_80","text":"持針之道，堅者為寶。正指直刺，無針左右。神在秋毫，屬意病者。審視血脈者，刺之無殆。方刺之時，必在懸陽，及與兩衛。神屬勿去，知病存亡。血脈者在俞橫居，視之獨澄，切之獨堅。","sortOrder":6},
  {"id":"s_work_hdnk_80_7","chapterId":"ch_work_hdnk_80","text":"九針之名，各不同形。一曰鑱針，長一寸六分；二曰員針，長一寸六分；三曰提針，長三寸半；四曰鋒針，長一寸六分；五曰鈹針，長四寸，廣二分半；六曰員利針，長一寸六分；七曰毫針，長三寸六分；八曰長針，長七寸；九曰大針，長四寸。鑱針者，頭大末銳，去瀉陽氣；員針者，針如卵形，揩摩分間，不得傷肌肉者，以瀉分氣；提針者，鋒如黍粟之銳，主按脈勿陷，以致其氣；鋒針者，刃三隅以發痼疾，鈹針者，末如劍鋒，以取大膿；員利針者，大如釐，且員且銳，中身微大，以取暴氣；毫針者，尖如蚊虻喙，靜以徐往，微以久留之而養，以取痛痺；長針者，鋒利身薄，可以取遠痺；大針者，尖如梃，其鋒微員，以瀉機關之水也。九針畢矣。","sortOrder":7},
  {"id":"s_work_hdnk_80_8","chapterId":"ch_work_hdnk_80","text":"夫氣之在脈也，邪氣在上，濁氣在中，清氣在下。故針陷脈則邪氣出，針中脈則濁氣出，針太深則邪氣反沉、病益。故曰：皮肉筋脈，各有所處。病各有所宜。各不同形，各以任其所宜，無實無虛。損不足而益有餘，是謂甚病。病益甚，取五脈者死，取三脈者恇；奪陰者死，奪陽者狂，針害畢矣。","sortOrder":8},
  {"id":"s_work_hdnk_80_9","chapterId":"ch_work_hdnk_80","text":"刺之而氣不至，無問其數。刺之而氣至，乃去之，勿復針。針各有所宜，各不同形，各任其所，為刺之要。氣至而有效，效之信，若風之吹雲，明乎若見蒼天，刺之道畢矣。","sortOrder":9},
  {"id":"s_work_hdnk_80_10","chapterId":"ch_work_hdnk_80","text":"黃帝曰：願聞五臟六腑所出之處。岐伯曰：五臟五俞，五五二十五俞，六腑六俞，六六三十六俞，經脈十二，絡脈十五，凡二十七氣，以上下。所出為井，所溜為滎，所註為俞，所行為經，所入為合，二十七氣所行，皆在五俞也。","sortOrder":10},
  {"id":"s_work_hdnk_80_11","chapterId":"ch_work_hdnk_80","text":"節之交，三百六十五會，知其要者，一言而終，不知其要，流散無窮。所言節者，神氣之所遊行出入也。非皮肉筋骨也。","sortOrder":11},
  {"id":"s_work_hdnk_80_12","chapterId":"ch_work_hdnk_80","text":"觀其色，察其目，知其散復。一其形，聽其動靜，知其邪正，右主推之，左持而御之，氣至而去之。","sortOrder":12},
  {"id":"s_work_hdnk_80_13","chapterId":"ch_work_hdnk_80","text":"凡將用針，必先診脈，視氣之劇易，乃可以治也。五臟之氣，已絕於內，而用針者反實其外，是謂重竭。重竭必死，其死也靜。治之者輒反其氣，取腋與膺。五臟之氣，已絕於外，而用針者反實其內，是謂逆厥。逆厥則必死，其死也躁。治之者反取四末。","sortOrder":13},
  {"id":"s_work_hdnk_80_14","chapterId":"ch_work_hdnk_80","text":"刺之害中而不去，則精泄；害中而去，則致氣。精泄則病益甚而恇，致氣則生為癰瘍。","sortOrder":14},
  {"id":"s_work_hdnk_80_15","chapterId":"ch_work_hdnk_80","text":"五臟有六腑，六腑有十二原，十二原出於四關，四關主治五臟。五臟有疾，當取之十二原。十二原者，五臟之所以稟三百六十五節氣味也。五臟有疾也，應出十二原。十二原各有所出。明知其原，睹其應，而知五臟之害矣。陽中之少陰，肺也，其原出於太淵，太淵二。陽中之太陽，心也，其原出於大陵，大陵二。陰中之少陽，肝也，其原出於太沖，太沖二。陰中之至陰，脾也，其原出於太白，太白二。陰中之太陰，腎也，其原出於太溪，太溪二。膏之原，出於鳩尾，鳩尾一。肓之原，出於脖胦，脖胦一。凡此十二原者，主治五臟六腑之有疾者也。","sortOrder":15},
  {"id":"s_work_hdnk_80_16","chapterId":"ch_work_hdnk_80","text":"脹取三陽，飧泄取三陰。","sortOrder":16},
  {"id":"s_work_hdnk_80_17","chapterId":"ch_work_hdnk_80","text":"稟今夫五臟之有疾也，譬猶刺也，猶污也，猶結也，猶閉也。刺雖久猶可拔也，污雖久猶可雪也，結雖久猶可解也，閉雖久猶可決也。或言久疾之不可取者，非其說也。夫善用針者，取其疾也，猶拔刺也，猶雪污也，猶解結也，猶決閉也。疾雖久，猶可畢也。言不可治者，未得其術也。","sortOrder":17},
  {"id":"s_work_hdnk_80_18","chapterId":"ch_work_hdnk_80","text":"刺諸熱者，如以手探湯；刺寒清者，如人不欲行。陰有陽疾者，取之下陵三里，正往無殆，氣下乃止，不下復始也。疾高而內者，取之陰之陵泉；疾高而外者，取之陽之陵泉也。","sortOrder":18},
  {"id":"s_work_hdnk_81_1","chapterId":"ch_work_hdnk_81","text":"本輸第二","sortOrder":1},
  {"id":"s_work_hdnk_81_2","chapterId":"ch_work_hdnk_81","text":"黃帝問於岐伯曰：凡刺之道，必通十二經絡之所終始，絡脈之所別處，五俞之所留，六腑之所與合，四時之所出入，五臟之所溜處，闊數之度，淺深之狀，高下所至。願聞其解。","sortOrder":2},
  {"id":"s_work_hdnk_81_3","chapterId":"ch_work_hdnk_81","text":"岐伯曰：請言其次也。肺出於少商，少商者，手大指端內側也，為井木；溜於魚際，魚際者，手魚也，為滎；註於太淵，太淵魚後一寸陷者中也，為俞；行於經渠，經渠寸口中也，動而不居為經；入於尺澤，尺澤肘中之動脈也，為合。手太陰經也。","sortOrder":3},
  {"id":"s_work_hdnk_81_4","chapterId":"ch_work_hdnk_81","text":"心出於中沖，中沖，手中指之端也，為井木；流於勞宮，勞宮掌中中指本節之內間也，為滎；註於大陵，大陵掌後兩骨之間方下者也，為俞；行於間使，間使之道，兩筋之間，三寸之中也，有過則至，無過則止，為經；入於曲澤，曲澤，肘內廉下陷者之中也，屈而得之，為合。手少陰也。","sortOrder":4},
  {"id":"s_work_hdnk_81_5","chapterId":"ch_work_hdnk_81","text":"肝出於大敦，大敦者，足大趾之端，及三毛之中也，為井木；溜於行間，行間足大趾間也，為滎；註於太沖，太沖行間上二寸陷者之中也，為俞；行於中封，中封內踝之前一寸半，陷者之中，使逆則宛，使和則通，搖足而得之，為經；入於曲泉，曲泉輔骨之下，大筋之上也，屈膝而得之，為合。足厥陰也。","sortOrder":5},
  {"id":"s_work_hdnk_81_6","chapterId":"ch_work_hdnk_81","text":"脾出於隱白，隱白者，足大趾之端內側也，為井木；溜於大都，大都本節之後下陷者之中也，為滎；註於太白，太白腕骨之下也，為俞；行於商丘，商丘內踝之下陷者之中也，為經；入於陰之陵泉，陰之陵泉，輔骨之下陷者之中也，伸而得之，為合。足太陰也。","sortOrder":6},
  {"id":"s_work_hdnk_81_7","chapterId":"ch_work_hdnk_81","text":"腎出於湧泉，湧泉者足心也，為井木；溜於然穀，然穀，然骨之下者也，為滎；註於太溪，太溪內踝之後跟骨之上陷中者也，為俞；行於復溜，復溜，上內踝二寸，動而不休，為經；入於陰穀，陰穀，輔骨之後，大筋之下，小筋之上也，按之應手，屈膝而得之，為合。足少陰經也。","sortOrder":7},
  {"id":"s_work_hdnk_81_8","chapterId":"ch_work_hdnk_81","text":"膀胱出於至陰，至陰者，足小趾之端也，為井金；溜於通穀，通穀，本節之前外側也，為滎；註於束骨，束骨，本節之後陷者中也，為俞；過於京骨，京骨，足外側大骨之下，為原；行於崑侖，崑侖，在外踝之後，跟骨之上，為經；入於委中，委中，膕中央，為合，委而取之。足太陽也。","sortOrder":8},
  {"id":"s_work_hdnk_81_9","chapterId":"ch_work_hdnk_81","text":"膽出於竅陰，竅陰者，足小趾次趾之端也，為井金；溜於俠溪，俠溪，足小趾次趾之間也，為滎；註於臨泣，臨泣，上行一寸半，陷者中也，為俞；過於丘墟，丘墟，外踝之前下陷者中也，為原。行於陽輔，陽輔外踝之上輔骨之前及絕骨之端也，為經；入於陽之陵泉，陽之陵泉，在膝外陷者中也，為合，伸而得之。足少陽也。","sortOrder":9},
  {"id":"s_work_hdnk_81_10","chapterId":"ch_work_hdnk_81","text":"胃出於厲兌，厲兌者，足大趾內次趾之端也，為井金；溜於內庭，內庭，次趾外間也，為滎；註於陷穀，陷穀者，上中指內間上行二寸陷者中也，為俞；過於沖陽，沖陽，足跗上五寸陷者中也，為原，搖足而得之；行於解溪，解溪，上沖陽一寸半陷者中也，為經；入於下陵，下陵，膝下三寸胻骨外三里也，為合；復下三里三寸，為巨虛上廉，復下上廉三寸，為巨虛下廉也；大腸屬上，小腸屬下，足陽明胃脈也。大腸小腸，皆屬於胃，是足陽明也。","sortOrder":10},
  {"id":"s_work_hdnk_81_11","chapterId":"ch_work_hdnk_81","text":"三焦者，上合手少陽，出於關沖，關沖者，手小指次指之端也，為井金；溜於液門，液門，小指次指之間也，為滎；註於中渚，中渚，本節之後陷者中也，為俞；過於陽池，陽池，在腕上陷者之中也，為原；行於支溝，支溝，上腕三寸兩骨之間陷者中也，為經；入於天井，天井，在肘外大骨之上陷者中也，為合，屈肘而得之；三焦下腧在於足大趾之前，少陽之後，出於膕中外廉，名曰委陽，是太陽絡也，手少陽經也。三焦者，足少陽太陰之所將太陽之別也，上踝五寸，別入貫腨腸，出於委陽，並太陽之正，入絡膀胱，約下焦，實則閉癃，虛則遺溺，遺溺則補之，閉癃則瀉之。","sortOrder":11},
  {"id":"s_work_hdnk_81_12","chapterId":"ch_work_hdnk_81","text":"手太陽小腸者，上合手太陽，出於少澤，少澤，小指之端也，為井金；溜於前穀，前穀，在手外廉本節前陷者中也，為滎；註於後溪，後溪者，在手外側本節之後也，為俞；過於腕骨，腕骨，在手外側腕骨之前，為原；行於陽穀，陽穀，在銳骨之下陷者中也，為經；入於小海，小海，在肘內大骨之外，去端半寸，陷者中也，伸臂而得之，為合。手太陽經也。","sortOrder":12},
  {"id":"s_work_hdnk_81_13","chapterId":"ch_work_hdnk_81","text":"大腸上合手陽明，出於商陽，商陽，大指次指之端也，為井金；溜於本節之前二間，為滎；註於本節之後三間，為俞；過於合穀，合穀，在大指岐骨之間，為原；行於陽溪，陽溪，在兩筋間陷者中也，為經；入於曲池，在肘外輔骨陷者中，屈臂而得之，為合。手陽明也。","sortOrder":13},
  {"id":"s_work_hdnk_81_14","chapterId":"ch_work_hdnk_81","text":"是謂五臟六腑之俞，五五二十五俞，六六三十六俞也。六腑皆出足之三陽，上合於手者也。","sortOrder":14},
  {"id":"s_work_hdnk_81_15","chapterId":"ch_work_hdnk_81","text":"缺盆之中，任脈也，名曰天突。一次，任脈側之動脈足陽明也，名曰人迎；二次脈，手陽明也，名曰扶突；三次脈，手太陽也，名曰天窗；四次脈，足少陽也，名曰天容；五次脈，手少陽也，名曰天牖；六次脈，足太陽也，名曰天柱；七次脈，頸中央之脈，督脈也，名曰風府。腋內動脈手太陰也，名曰天府。腋下三寸手心主也，名曰天池。","sortOrder":15},
  {"id":"s_work_hdnk_81_16","chapterId":"ch_work_hdnk_81","text":"刺上關者，呿不能欠。刺下關者，欠不能呿。刺犢鼻者，屈不能伸。刺兩關者，伸不能屈。","sortOrder":16},
  {"id":"s_work_hdnk_81_17","chapterId":"ch_work_hdnk_81","text":"足陽明，俠喉之動脈也，其俞在膺中。手陽明，次在其俞外，不至曲頰一寸。手太陽當曲頰。足少陽在耳下曲頰之後。手少陽出耳後上加完骨之上。足太陽俠項大筋之中，髮際。","sortOrder":17},
  {"id":"s_work_hdnk_81_18","chapterId":"ch_work_hdnk_81","text":"陰尺動脈，在五裏，五俞之禁也。","sortOrder":18},
  {"id":"s_work_hdnk_81_19","chapterId":"ch_work_hdnk_81","text":"肺合大腸，大腸者，傳道之腑。心合小腸，小腸者，受盛之腑。肝合膽，膽者中精之腑。脾合胃，胃者五穀之腑。腎合膀胱，膀胱者津液之腑也。少陽屬腎，腎上連肺，故將兩臟。三焦者，中瀆之腑也，水道出焉，屬膀胱，是孤之腑也，是六腑之所與合者。","sortOrder":19},
  {"id":"s_work_hdnk_81_20","chapterId":"ch_work_hdnk_81","text":"春取絡脈諸滎大經分肉之間，甚者深取之，間者淺取之。夏取諸俞孫絡肌肉皮膚之上。秋取諸合，餘如春法。冬取諸井諸俞之分，欲深而留之。此四時之序，氣之所處，病之所舍，臟之所宜。轉筋者，立而取之，可令遂已。痿厥者，張而刺之，可令立快也。","sortOrder":20},
  {"id":"s_work_hdnk_82_1","chapterId":"ch_work_hdnk_82","text":"小鍼解第三","sortOrder":1},
  {"id":"s_work_hdnk_82_2","chapterId":"ch_work_hdnk_82","text":"所謂易陳者，易言也。難入者，難著於人也。粗守形者，守刺法也。上守神者，守人之血氣有餘不足可補瀉也。神客者，正邪共會也。神者，正氣也，客者邪氣也。在門者，邪循正氣之所出入也。未睹其疾者，先知邪正何經之疾也。惡知其原者，先知何經之病所取之處也。","sortOrder":2},
  {"id":"s_work_hdnk_82_3","chapterId":"ch_work_hdnk_82","text":"刺之微在數遲者，徐疾之意也。粗守關者，守四支而不知血氣正邪之往來也。上守機者，知守氣也。機之動不離其空中者，知氣之虛實，用針之徐疾也。空中之機，清靜以微者，針以得氣，密意守氣勿失也。其來不可逢者，氣盛不可補也。其往不可追者，氣虛不可瀉也。不可掛以發者，言氣易失也。扣之不發者，言不知補瀉之意也。血氣已盡而氣不下也。","sortOrder":3},
  {"id":"s_work_hdnk_82_4","chapterId":"ch_work_hdnk_82","text":"知其往來者，知氣之逆順盛虛也。要與之期者，知氣之可取之時也。粗之闇者，冥冥不知氣之微密也。妙哉！工獨有之者，盡知針意也。往者為逆者，言氣之虛而小，小者逆也。來者為順者，言形氣之平，平者順也。明知逆順正行無問者，言知所取之處也。迎而奪之者，瀉也；追而濟之者，補也。","sortOrder":4},
  {"id":"s_work_hdnk_82_5","chapterId":"ch_work_hdnk_82","text":"所謂虛則實之者，氣口虛而當補之也。滿則泄之者，氣口盛而當瀉之也。宛陳則除之者，去血脈也。邪勝則虛之者，言諸經有盛者，皆瀉其邪也。徐而疾則實者，言徐內而疾出也。疾而徐則虛者，言疾內而徐出也。言實與虛若有若無者，言實者有氣，虛者無氣也。察後與先若亡若存者，言氣之虛實，補瀉之先後也，察其氣之已下與常存也。為虛為實，若得若失者，言補者佖然若有得也，瀉則恍然若有失也。","sortOrder":5},
  {"id":"s_work_hdnk_82_6","chapterId":"ch_work_hdnk_82","text":"夫氣之在脈也，邪氣在上者，言邪氣之中人也高，故邪氣在上也。濁氣在中者，言水穀皆入於胃，其精氣上註於肺，濁溜於腸胃，言寒溫不適，飲食不節，而病生於腸胃，故命曰濁氣在中也。清氣在下者，言清濕地氣之中人也，必從足始，故曰清氣在下也。針陷脈，則邪氣出者取之上，針中脈則濁氣出者，取之陽明合也。針太深則邪氣反沉者，言淺浮之病，不欲深刺也。深則邪氣從之入，故曰反沉也。皮肉筋脈各有所處者，言經絡各有所主也。取五脈者死，言病在中氣不足，但用針盡大瀉其諸陰之脈也。取三陽之脈者，唯言盡瀉三陽之氣，令病人恇然不復也。奪陰者死，言取尺之五裏五往者也。奪陽者狂，正言也。","sortOrder":6},
  {"id":"s_work_hdnk_82_7","chapterId":"ch_work_hdnk_82","text":"睹其色，察其目，知其散復，一其形，聽其動靜者，言上工知相五色於目。有知調尺寸小大緩急滑澀以言所病也。知其邪正者，知論虛邪與正邪之風也。右主推之，左持而御之者，言持針而出入也。氣至而去之者，言補瀉氣調而去之也。調氣在於終始一者，持心也。節之交三百六十五會者，絡脈之滲灌諸節者也。","sortOrder":7},
  {"id":"s_work_hdnk_82_8","chapterId":"ch_work_hdnk_82","text":"所謂五臟之氣，已絕於內者，脈口氣內絕不至，反取其外之病處，與陽經之合，有留針以致陽氣，陽氣至則內重竭，重竭則死矣。其死也，無氣以動，故靜。所謂五臟之氣，已絕於外者，脈口氣外絕不至，反取其四末之輸，有留針以致其陰氣，陰氣至則陽氣反入，入則逆，逆則死矣。其死也，陰氣有餘，故躁。","sortOrder":8},
  {"id":"s_work_hdnk_82_9","chapterId":"ch_work_hdnk_82","text":"所以察其目者，五臟使五色循明。循明則聲章。聲章者，則言聲與平生異也。","sortOrder":9},
  {"id":"s_work_hdnk_83_1","chapterId":"ch_work_hdnk_83","text":"邪氣藏府病形第四","sortOrder":1},
  {"id":"s_work_hdnk_83_2","chapterId":"ch_work_hdnk_83","text":"黃帝問於岐伯曰：邪氣之中人也奈何？岐伯答曰：邪氣之中人高也。","sortOrder":2},
  {"id":"s_work_hdnk_83_3","chapterId":"ch_work_hdnk_83","text":"黃帝曰：高下有度乎？岐伯曰：身半以上者，邪中之也。身半已下者，濕中之也。故曰：邪之中人也。無有常，中於陰則溜於腑，中於陽則溜於經。","sortOrder":3},
  {"id":"s_work_hdnk_83_4","chapterId":"ch_work_hdnk_83","text":"黃帝曰：陰之與陽也，異名同類，上下相會，經絡之相貫，如環無端。邪之中人，或中於陰，或中於陽，上下左右，無有恆常，其故何也？","sortOrder":4},
  {"id":"s_work_hdnk_83_5","chapterId":"ch_work_hdnk_83","text":"岐伯曰：諸陽之會，皆在於面。中人也，方乘虛時及新用力，若飲食汗出，腠理開而中於邪。中於面，則下陽明。中於項，則下太陽。中於頰，則下少陽。其中於膺背兩脅，亦中其經。","sortOrder":5},
  {"id":"s_work_hdnk_83_6","chapterId":"ch_work_hdnk_83","text":"黃帝曰：其中於陰，奈何？岐伯答曰：中於陰者，常從臂胻始。夫臂與胻，其陰皮薄，其肉淖澤，故俱受於風，獨傷其陰。","sortOrder":6},
  {"id":"s_work_hdnk_83_7","chapterId":"ch_work_hdnk_83","text":"黃帝曰：此故傷其藏乎？岐伯答曰：身之中於風也，不必動藏。故邪入於陰經，則其藏氣實，邪氣入而不能客，故還之於腑。故中陽則溜於經，中陰則溜於府。","sortOrder":7},
  {"id":"s_work_hdnk_83_8","chapterId":"ch_work_hdnk_83","text":"黃帝曰：邪之中人臟奈何？岐伯曰：愁憂恐懼則傷心。形寒寒飲則傷肺，以其兩寒相感，中外皆傷，故氣逆而上行。有所墮墜，惡血留內；若有所大怒，氣上而不下，積於脅下，則傷肝。有所擊仆，若醉入房，汗出當風，則傷脾。有所用力舉重，若入房過度，汗出浴水，則傷腎。","sortOrder":8},
  {"id":"s_work_hdnk_83_9","chapterId":"ch_work_hdnk_83","text":"黃帝曰：五臟之中風，奈何？岐伯曰：陰陽俱感，邪乃得往。黃帝曰：善哉。","sortOrder":9},
  {"id":"s_work_hdnk_83_10","chapterId":"ch_work_hdnk_83","text":"黃帝問於岐伯曰：首面與身形也，屬骨連筋，同血合於氣耳。天寒則裂地凌冰，其卒寒，或手足懈惰，然而其面不衣，何也？岐伯答曰：十二經脈，三百六十五絡，其血氣皆上於面而走空竅。其精陽氣上走於目而為睛。其別氣走於耳而為聽。其宗氣上出於鼻而為臭。其濁氣出於胃，走唇舌而為味。其氣之津液，皆上熏於面，而皮又厚，其肉堅，故天氣甚寒，不能勝之也。","sortOrder":10},
  {"id":"s_work_hdnk_83_11","chapterId":"ch_work_hdnk_83","text":"黃帝曰：邪之中人，其病形何如？岐伯曰：虛邪之中身也，洒淅動形。正邪之中人也，微，先見於色，不知於身，若有若無，若亡若存，有形無形，莫知其情。黃帝曰：善哉。","sortOrder":11},
  {"id":"s_work_hdnk_83_12","chapterId":"ch_work_hdnk_83","text":"黃帝問於岐伯曰：餘聞之，見其色，知其病，命曰明。按其脈，知其病，命曰神。問其病，知其處，命曰工。餘願聞見而知之，按而得之，問而極之，為之奈何？","sortOrder":12},
  {"id":"s_work_hdnk_83_13","chapterId":"ch_work_hdnk_83","text":"岐伯答曰：夫色脈與尺之相應也，如桴鼓影響之相應也，不得相失也，此亦本末根葉之出候也，故根死則葉枯矣。色脈形肉，不得相失也。故知一則為工，知二則為神，知三則神且明矣。","sortOrder":13},
  {"id":"s_work_hdnk_83_14","chapterId":"ch_work_hdnk_83","text":"黃帝曰：願卒聞之。岐伯答曰：色青者，其脈絃也，赤者，其脈鉤也，黃者，其脈代也，白者，其脈毛，黑者，其脈石。見其色而不得其脈，反得其相勝之脈，則死矣；得其相生之脈，則病已矣。","sortOrder":14},
  {"id":"s_work_hdnk_83_15","chapterId":"ch_work_hdnk_83","text":"黃帝問於岐伯曰：五臟之所生，變化之病形何如？","sortOrder":15},
  {"id":"s_work_hdnk_83_16","chapterId":"ch_work_hdnk_83","text":"岐伯答曰：先定其五色五脈之應，其病乃可別也。","sortOrder":16},
  {"id":"s_work_hdnk_83_17","chapterId":"ch_work_hdnk_83","text":"黃帝曰：色脈已定，別之奈何？","sortOrder":17},
  {"id":"s_work_hdnk_83_18","chapterId":"ch_work_hdnk_83","text":"岐伯說：調其脈之緩、急、小、大、滑、澀，而病變定矣。","sortOrder":18},
  {"id":"s_work_hdnk_83_19","chapterId":"ch_work_hdnk_83","text":"黃帝曰：調之奈何？岐伯答曰：脈急者，尺之皮膚亦急；脈緩者，尺之膚亦緩；脈小者，尺之皮膚亦減而少氣；脈大者，尺之皮膚亦賁而起；脈滑者，尺之皮膚亦滑；脈澀者，尺之皮膚亦澀。凡此變者，有微有甚。故善調尺者，不待於寸，善調脈者，不待於色。能參合而行之者，可以為上工，上工十全九。行二者，為中工，中工十全七。行一者，為下工，下工十全六。","sortOrder":19},
  {"id":"s_work_hdnk_83_20","chapterId":"ch_work_hdnk_83","text":"黃帝曰：請問脈之緩、急，小、大，滑、澀之病形何如？","sortOrder":20},
  {"id":"s_work_hdnk_83_21","chapterId":"ch_work_hdnk_83","text":"岐伯曰：臣請言五藏之病變也。心脈急甚者為瘈瘲；徵急，為心痛引背，食不下。緩甚，為狂笑；微緩，為伏梁，在心下，上下行，時唾血。大甚，為喉吤；微大，為心痺引背，善淚出。小甚為善噦；微小為消病。滑甚為善渴；微滑為心疝，引臍，小腹鳴。澀為為瘖；微澀為血溢，維厥耳鳴，顛疾。","sortOrder":21},
  {"id":"s_work_hdnk_83_22","chapterId":"ch_work_hdnk_83","text":"肺脈急甚，為癲疾；微急，為肺寒熱，怠惰，咳唾血，引腰背胸，若鼻息肉不通。緩甚，為多汗；微緩，為痿，痿，偏風，頭以下汗出不可止。大甚，為脛腫；微大，為肺痺，引胸背，起惡見日光。小甚，為泄；微小，為消痺。滑甚，為息賁上氣；微滑，為上下出血。澀甚，為嘔血；微澀，為鼠瘻，在頸支腋之間，下不勝其上，其應善痠矣。","sortOrder":22},
  {"id":"s_work_hdnk_83_23","chapterId":"ch_work_hdnk_83","text":"肝脈急甚者為惡言；微急為肥氣在脅下，若復杯。緩甚為善嘔，微緩為水瘕痺也。大甚為內癰，善嘔衄；微大為肝痺，陰縮，咳引小腹。小甚為多飲；微小為消癉。滑甚為〈疒貴〉疝；微滑為遺溺。澀甚為溢飲；微澀為瘈攣筋痺。","sortOrder":23},
  {"id":"s_work_hdnk_83_24","chapterId":"ch_work_hdnk_83","text":"脾脈急甚為瘈瘲；微急為膈中，食飲入而還出，後沃沫。緩甚為痿厥；微緩為風痿，四肢不用，心慧然若無病。大甚為擊仆；微大為疝氣，腹裏大膿血在腸胃之外。小甚為寒熱；微小為消癉。滑甚為〈疒貴〉癃；微滑為蟲毒蛕蝎腹熱。澀甚為腸〈疒貴〉；微澀為內〈疒貴〉，多下膿血。","sortOrder":24},
  {"id":"s_work_hdnk_83_25","chapterId":"ch_work_hdnk_83","text":"腎脈急甚為骨癲疾；微急為沉厥奔豚，足不收，不得前後。緩甚為折脊；微緩為洞，洞者，食不化，下嗌逐出。大甚為陰痿；微大為石水，起臍已下至小腹睡睡然，上至胃脘，死不治。小甚為洞泄；微小為消癉。滑甚為癃〈疒貴〉；微滑為骨痿，坐不能起，起則目無所見。澀甚為大癰；微澀為不月，沉痔。","sortOrder":25},
  {"id":"s_work_hdnk_83_26","chapterId":"ch_work_hdnk_83","text":"黃帝曰：病之六變者，刺之奈何？岐伯曰：諸急者多寒；緩者多熱；大者多氣少血；小者血氣皆少；滑者陽氣盛，微有熱；澀者多血、少氣，微有寒。是故刺急者，深內而久留之；刺緩者，淺內而疾發針，以去其熱；刺大者，微瀉其氣，無出其血；刺滑者，疾發針而淺內之，以瀉其陽氣而去其熱；刺澀者，必中其脈，隨其逆順而久留之，必先按而循之，已發針，已按其疝，無令其血出，以和其脈；諸小者，陰陽形氣俱不足，勿取以針而調以甘藥也。","sortOrder":26},
  {"id":"s_work_hdnk_83_27","chapterId":"ch_work_hdnk_83","text":"黃帝曰：餘聞五臟六府之氣，滎、俞所入為合，令何道從入，入安連過，願聞其故。岐伯答曰：此陽脈之別入於內，屬於府者也。","sortOrder":27},
  {"id":"s_work_hdnk_83_28","chapterId":"ch_work_hdnk_83","text":"黃帝曰：滎俞與合，各有名乎？岐伯曰：滎俞治外經，合治內府。","sortOrder":28},
  {"id":"s_work_hdnk_83_29","chapterId":"ch_work_hdnk_83","text":"黃帝曰：治內府奈何？岐伯曰：取之於合。","sortOrder":29},
  {"id":"s_work_hdnk_83_30","chapterId":"ch_work_hdnk_83","text":"黃帝曰：合各有名乎？岐伯答曰：胃合於三里，大腸合入於巨虛上廉，小腸合入於巨虛下廉，三焦合入於委陽，膀胱合入於委中央，膽合入於陽陵泉。","sortOrder":30},
  {"id":"s_work_hdnk_83_31","chapterId":"ch_work_hdnk_83","text":"黃帝曰：取之奈何？岐伯答曰：取之三里者，低跗取之；巨虛者，舉足取之；委陽者，屈伸而索之；委中者，屈而取之；陽陵泉者，正豎膝予之齊下，至委陽之陽取之；取諸外經者，揄申而從之。","sortOrder":31},
  {"id":"s_work_hdnk_83_32","chapterId":"ch_work_hdnk_83","text":"黃帝曰：願聞六府之病。岐伯答曰：面熱者足陽明病，魚絡血者手陽明病，兩跗之上脈豎陷者，足陽明病，此胃脈也。","sortOrder":32},
  {"id":"s_work_hdnk_83_33","chapterId":"ch_work_hdnk_83","text":"大腸病者，腸中切痛，而鳴濯濯。冬日重感於寒即泄，當臍而痛，不能久立，與胃同候，取巨虛上廉。","sortOrder":33},
  {"id":"s_work_hdnk_83_34","chapterId":"ch_work_hdnk_83","text":"胃病者，腹〈月真〉脹，胃脘當心而痛，上肢兩脅，膈咽不通，食飲不下，取之三里也。","sortOrder":34},
  {"id":"s_work_hdnk_83_35","chapterId":"ch_work_hdnk_83","text":"小腸病者，小腹痛，腰脊控睪而痛，時窘之後，當耳前熱，若寒甚，若獨肩上熱甚，及手小指次指之間熱，若脈陷者，此其候也。手太陽病也，取之巨虛下廉。","sortOrder":35},
  {"id":"s_work_hdnk_83_36","chapterId":"ch_work_hdnk_83","text":"三焦病者，腹氣滿，小腹尤堅，不得小便，窘急，溢則水留，即為脹。候在足太陽之外大絡，大絡在太陽少陽之間，亦見於脈，取委陽。","sortOrder":36},
  {"id":"s_work_hdnk_83_37","chapterId":"ch_work_hdnk_83","text":"膀胱病者，小腹偏腫而痛，以手按之，即欲小便而不得，肩上熱，若脈陷，及足小趾外廉及脛踝後皆熱，若脈陷，取委中央。","sortOrder":37},
  {"id":"s_work_hdnk_83_38","chapterId":"ch_work_hdnk_83","text":"膽病者，善太息，口苦，嘔宿汁，心下淡淡，恐人將捕之，嗌中吤吤然數唾。在足少陽之本末，亦視其脈之陷下者灸之；其寒熱者取陽陵泉。","sortOrder":38},
  {"id":"s_work_hdnk_83_39","chapterId":"ch_work_hdnk_83","text":"黃帝曰：刺之有道乎？岐伯答曰：刺此者，必中氣穴，無中肉節。中氣穴，則針遊於巷；中肉節，即皮膚痛；補瀉反，則病益篤。中筋則筋緩，邪氣不出，與其真相搏亂而不去，反還內著。用針不審，以順為逆也。","sortOrder":39},
  {"id":"s_work_hdnk_84_1","chapterId":"ch_work_hdnk_84","text":"根結第五","sortOrder":1},
  {"id":"s_work_hdnk_84_2","chapterId":"ch_work_hdnk_84","text":"岐伯曰：天地相感，寒暖相移，陰陽之道，孰少孰多，陰道偶，陽道奇。發於春夏，陰氣少，陽氣多，陰陽不調，何補何瀉。發於秋冬，陽氣少，陰氣多；陰氣盛而陽氣衰，故莖葉枯槁，濕雨下歸，陰陽相移，何瀉何補。奇邪離經，不可勝數，不知根結，五臟六腑，折關敗樞，開閤而走，陰陽大失，不可復取。九針之玄，要在終始；故能知終始，一言而畢，不知終始，針道鹹絕。","sortOrder":2},
  {"id":"s_work_hdnk_84_3","chapterId":"ch_work_hdnk_84","text":"太陽根於至陰，結於命門。命門者，目也。陽明根於厲兌，結於顙大。顙大者，鉗耳也。少陽根於竅陰，結於窗籠。窗籠者，耳中也。太陽為開，陽明為閤，少陽為樞，故開折，則肉節瀆而暴病起矣。故暴病者，取之太陽，視有餘不足。瀆者，皮肉宛膲而弱也。閤折，則氣無所止息而痿疾起矣。故痿疾者，取之陽明，視有餘不足。無所止息者，真氣稽留，邪氣居之也。樞折，即骨繇而不安於地。故骨繇者，取之少陽，視有餘不足。骨繇者，節緩而不收也。所謂骨繇者，搖故也。當竊其本也。","sortOrder":3},
  {"id":"s_work_hdnk_84_4","chapterId":"ch_work_hdnk_84","text":"太陰根於隱白，結於太倉。少陰根於湧泉，結於廉泉。厥陰根於大敦，結於玉英，絡於膻中。太陰為閤，少陽為樞。故開折，則倉廩無所輸，膈洞。膈洞者，取之太陰，視有餘不足，故開折者，氣不足而生病也。閤折，即氣絕而喜悲。悲者取之厥陰，視有餘不足。樞折，則脈有所結而不通。不通者，取之少陰，視有餘不足，有結者，皆取之不足。","sortOrder":4},
  {"id":"s_work_hdnk_84_5","chapterId":"ch_work_hdnk_84","text":"足太陽根於至陰，溜於京骨，註於崑侖，入於天柱、飛揚也。足少陽根於竅陰，溜於丘墟，註於陽輔，入於天容、光明也。足陽明根於厲兌，溜於沖陽，註於下陵，入於人迎，豐隆也。手太陽根於少澤，溜於陽穀，註於小海，入於天窗，支正也。少陽根於關沖，溜於陽池，註於支溝，入於天牖、外關也。手陽明根於商陽，溜於合穀，註於陽谿，入於扶突、偏歷也。此所謂十二經者，盛絡皆當取之。","sortOrder":5},
  {"id":"s_work_hdnk_84_6","chapterId":"ch_work_hdnk_84","text":"一日一夜五十營，以營五臟之精，不應數者，名曰狂生。所謂五十營者，五臟皆受氣，持其脈口，數其至也。五十動而不一代者，五臟皆受氣。四十動一代者，一臟無氣。三十動一代者，二臟無氣。二十動一代者，三臟無氣。十動一代者，四臟無氣。不滿十動一代者，五臟無氣。予之短期，要在終始。所謂五十動而不一代者，以為常也。以知五臟之期，予之短期者，乍數乍疏也。","sortOrder":6},
  {"id":"s_work_hdnk_84_7","chapterId":"ch_work_hdnk_84","text":"黃帝曰：逆順五體者，言人骨節之大小，肉之堅脆，皮之厚薄，血之清濁，氣之滑澀，脈之長短，血之多少，經絡之數，餘已知之矣，此皆布衣匹夫之士也。夫王公大人，血食之君，身體柔脆，肌肉軟弱，血氣慓悍滑利，其刺之徐疾淺深多少，可得同之乎。岐伯答曰：膏梁菽藿之味，何可同也？氣滑即出疾，其氣澀則出遲，氣悍則針小而入淺，氣澀則針大而入深，深則欲留，淺則欲疾。以此觀之，刺布衣者，深以留之，刺大人者，微以徐之，此皆因氣慓悍滑利也。","sortOrder":7},
  {"id":"s_work_hdnk_84_8","chapterId":"ch_work_hdnk_84","text":"黃帝曰：形氣之逆順奈何？岐伯曰：形氣不足，病氣有餘，是邪勝也，急瀉之；形氣有餘，病氣不足，急補之；形氣不足，病氣不足，此陰陽氣俱不足也，不可刺之，刺之則重不足。重不足則陰陽俱竭，血氣皆盡，五臟空虛，筋骨髓枯，老者絕滅，壯者不復矣。形氣有餘，病氣有餘，此謂陰陽俱有餘也。急瀉其邪，調其虛實。故曰：有餘者瀉之，不足者補之，此之謂也。","sortOrder":8},
  {"id":"s_work_hdnk_84_9","chapterId":"ch_work_hdnk_84","text":"故曰：刺不知逆順，真邪相搏。滿而補之，則陰陽四溢，腸胃充郭，肝肺內〈月真〉，陰陽相錯。虛而瀉之，則經脈空虛，血氣竭枯，腸胃〈亻聶〉辟，皮膚薄著，毛腠夭膲，予之死期。","sortOrder":9},
  {"id":"s_work_hdnk_84_10","chapterId":"ch_work_hdnk_84","text":"故曰：用針之要，在於知調陰與陽。調陰與陽，精氣乃光，合形與氣，使神內藏。故曰：上工平氣，中工亂脈，下工絕氣危生。故曰：下工不可不慎也，必審五藏變化之病，五脈之應，經絡之實虛，皮之柔麤，而後取之也。","sortOrder":10},
  {"id":"s_work_hdnk_85_1","chapterId":"ch_work_hdnk_85","text":"壽夭剛柔第六","sortOrder":1},
  {"id":"s_work_hdnk_85_2","chapterId":"ch_work_hdnk_85","text":"黃帝問於少師曰：餘聞人之生也，有剛有柔，有弱有強，有短有長，有陰有陽，願聞其方。","sortOrder":2},
  {"id":"s_work_hdnk_85_3","chapterId":"ch_work_hdnk_85","text":"少師答曰：陰中有陰，陽中有陽，審知陰陽，刺之有方。得病所始，刺之有理。謹度病端，與時相應。內合於五臟六腑，外合於筋骨皮膚。是故內有陰陽，外亦有陰陽。在內者，五臟為陰，六腑為陽，在外者，筋骨為陰，皮膚為陽。故曰，病在陰之陰者，刺陰之滎俞，病在陽之陽者，刺陽之合，病在陽之陰者，刺陰之經，病在陰之陽者，刺絡脈。故曰，病在陽者名曰風，病在陰者名曰痺，陰陽俱病名曰風痺。病有形而不痛者，陽之類也；無形而痛者，陰之類也。無形而痛者，其陽完而陰傷之也。急治其陰，無攻其陽。有形而不痛者，其陰完而陽傷之也。急治其陽，無攻其陰。陰陽俱動，乍有形，乍無形，加以煩心，命曰陰勝其陽。此謂不表不裏，其形不久。","sortOrder":3},
  {"id":"s_work_hdnk_85_4","chapterId":"ch_work_hdnk_85","text":"黃帝問於伯高曰：餘聞形氣之病先後，外內之應奈何？伯高答曰：風寒傷形，憂恐忿怒傷氣；氣傷臟，乃病臟，寒傷形，乃應形；風傷筋脈，筋脈乃應。此形氣外內之相應也。","sortOrder":4},
  {"id":"s_work_hdnk_85_5","chapterId":"ch_work_hdnk_85","text":"黃帝曰：刺之奈何？伯高答曰：病九日者，三刺而已；病一月者，十刺而已；多少遠近，以此衰之。久痺不去身者，視其血絡，盡出其血。","sortOrder":5},
  {"id":"s_work_hdnk_85_6","chapterId":"ch_work_hdnk_85","text":"黃帝曰：外內之病，難易之治奈何？伯高答曰：形先病而未入臟者，刺之半其日。臟先病而形乃應者，刺之倍其日。此月內難易之應也。","sortOrder":6},
  {"id":"s_work_hdnk_85_7","chapterId":"ch_work_hdnk_85","text":"黃帝問於伯高曰：餘聞形有緩急，氣有盛衰，骨有大小，肉有堅脆，皮有厚薄，其以立壽夭奈何？伯高答曰：形與氣相任則壽，不相任則夭。皮與肉相果則壽，不相果則夭，血氣經絡勝形則壽，不勝形則夭。","sortOrder":7},
  {"id":"s_work_hdnk_85_8","chapterId":"ch_work_hdnk_85","text":"黃帝曰：何謂形之緩急？伯高答曰：形充而皮膚緩者則壽，形充而皮膚急者則夭，形充而脈堅大者順也，形充而脈小以弱者氣衰，衰則危矣。若形充而顴不起者骨小，骨小則夭矣。形充而大肉胭堅而有分者肉堅，肉堅則壽矣；形充而大肉無分理不堅者肉脆，肉脆則夭矣。此天之生命，所以立形定氣而視壽夭者，必明乎此立形定氣，而後以臨病人，決生死。","sortOrder":8},
  {"id":"s_work_hdnk_85_9","chapterId":"ch_work_hdnk_85","text":"黃帝曰：餘聞壽夭，無以度之。伯高答曰：牆基卑，高不及其地者，不滿三十而死。其有因加疾者，不及二十而死也。","sortOrder":9},
  {"id":"s_work_hdnk_85_10","chapterId":"ch_work_hdnk_85","text":"黃帝曰：形氣之相勝，以立壽夭奈何？伯高答曰：平人而氣勝形者壽；病而形肉脫，氣勝形者死，形勝氣者危矣。","sortOrder":10},
  {"id":"s_work_hdnk_85_11","chapterId":"ch_work_hdnk_85","text":"黃帝曰：餘聞刺有三變，何謂三變？伯高答曰：有刺營者，有刺衛者，有刺寒痺之留經者。","sortOrder":11},
  {"id":"s_work_hdnk_85_12","chapterId":"ch_work_hdnk_85","text":"黃帝曰：刺三變者奈何？伯高答曰：刺營者出血，刺衛者出氣，刺寒痺者內熱。","sortOrder":12},
  {"id":"s_work_hdnk_85_13","chapterId":"ch_work_hdnk_85","text":"黃帝曰：營衛寒痺之為病奈何？伯高答曰：營之生病也，寒熱少氣，血上下行。衛之生病也，氣痛時來時去，怫愾賁響，風寒客於腸胃之中。寒痺之為病也，留而不去，時痛而皮不仁。","sortOrder":13},
  {"id":"s_work_hdnk_85_14","chapterId":"ch_work_hdnk_85","text":"黃帝曰：刺寒痺內熱奈何？伯高答曰：刺布衣者，以火焠之；刺大人者，以藥熨之。","sortOrder":14},
  {"id":"s_work_hdnk_85_15","chapterId":"ch_work_hdnk_85","text":"黃帝曰：藥熨奈何？伯高答曰：用淳酒二十斤，蜀椒一斤，幹薑一斤，桂心一斤，凡四種，皆嚼咀，漬酒中，用綿絮一斤，細白布四丈，並內酒中，置酒馬矢熅中，封涂封，勿使泄。五日五夜，出綿絮曝乾之，幹復潰，以盡其汁。每漬必晬其日，乃出乾。乾，並用滓與綿絮，復布為復巾，長六七尺，為六七巾，則用之生桑炭炙巾，以熨寒痺所刺之處，令熱入至於病所，寒復炙巾以熨之，三十遍而止。汗出以巾拭身，亦三十遍而止。起步內中，無見風。每刺必熨，如此病已矣。","sortOrder":15},
  {"id":"s_work_hdnk_86_1","chapterId":"ch_work_hdnk_86","text":"官鍼第七","sortOrder":1},
  {"id":"s_work_hdnk_86_2","chapterId":"ch_work_hdnk_86","text":"凡刺之要，官針最妙。九針之宜，各有所為，長、短、大、小，各有所施也。不得其用，病弗能移。疾淺針深，內傷良肉，皮膚為癰；病深針淺，病氣不瀉，支為大膿。病小針大，氣瀉太甚，疾必為害；病大針小，氣不泄瀉，亦復為敗。失針之宜。大者瀉，小者不移。已言其過，請言其所施。","sortOrder":2},
  {"id":"s_work_hdnk_86_3","chapterId":"ch_work_hdnk_86","text":"病在皮膚無常處者，取以鑱針於病所，膚白勿取。病在分肉間，取以圓針於病所。病在經絡痼痺者，取以鋒針。病在脈，氣少，當補之者，取以鍉針於井滎分俞。病為大膿者，取以鈹針。病痺氣暴發者，取以圓利針。病痺氣痛而不去者，取以毫針。病在中者，取以長針。病水腫不能通關節者，取以大針。病在五臟固居者，取以鋒針，瀉於井滎分俞，取以四時。","sortOrder":3},
  {"id":"s_work_hdnk_86_4","chapterId":"ch_work_hdnk_86","text":"凡刺有九，以應九變。一曰俞刺，俞刺者，刺諸經滎俞臟俞也；二曰遠道刺，遠道刺者，病在上，取之下，刺腑俞也；三曰經刺，經刺者，刺大經之結絡經分也；四曰絡刺，絡刺者，刺小絡之血脈也；五曰分刺，分刺者，刺分肉之間也；六曰大瀉刺，大瀉刺者，刺大膿以鈹針也；七曰毛刺，毛刺者，刺浮痺皮膚也；八曰巨刺，巨刺者，左取右，右取左；九曰焠刺，焠刺者，刺燔針則取痺也。","sortOrder":4},
  {"id":"s_work_hdnk_86_5","chapterId":"ch_work_hdnk_86","text":"凡刺有十二節，以應十二經。一曰偶刺，偶刺者，以手直心若背，直痛所，一刺前，一刺後，以治心痺。刺此者，傍針之也。二曰報刺，報刺者，刺痛無常處也。上下行者，直內無拔針，以左手隨病所按之，乃出針，復刺之也。三曰恢刺，恢刺者，直刺傍之，舉之前後，恢筋急，以治筋痺也。四曰齊刺，齊刺者，直入一，傍入二，以治寒氣小深者；或曰三刺，三刺者，治痺氣小深者也。五曰揚刺，揚刺者，正內一，傍內四，而浮之，以治寒氣之搏大者也。六曰直針刺，直針刺者，引皮乃刺之，以治寒氣之淺者也。七曰輸針，輸刺者，直入直出，稀發針而深之，以治氣盛而熱者也。八曰短刺，短刺者，刺骨痺，稍搖而深之，致針骨所，以上下摩骨也。九曰浮刺，浮刺者，傍入而浮之，以治肌急而寒者也。十曰陰刺，陰刺者，左右率刺之，以治寒厥；中寒厥，足踝後少陰也。十一曰傍針刺，傍針刺者，直刺傍刺各一，以治留痺久居者也。十二曰贊刺，贊刺者，直入直出，數發針而淺之，出血是謂治癰腫也。","sortOrder":5},
  {"id":"s_work_hdnk_86_6","chapterId":"ch_work_hdnk_86","text":"脈之所居，深不見者，刺之微內針而久留之，以致其空脈氣也。脈淺者，勿刺，按絕其脈乃刺之，無令精出，獨出其邪氣耳。","sortOrder":6},
  {"id":"s_work_hdnk_86_7","chapterId":"ch_work_hdnk_86","text":"所謂三刺，則穀氣出者。先淺刺絕皮，以出陽邪，再刺則陰邪出者，少益深絕皮，致肌肉，未入分肉間也；已入分肉之間，則穀氣出。故刺法曰：始刺淺之，以逐邪氣，而來血氣，後刺深之，以致陰氣之邪，最後刺極深之，以下穀氣。此之謂也。","sortOrder":7},
  {"id":"s_work_hdnk_86_8","chapterId":"ch_work_hdnk_86","text":"故用針者，不知年之所加，氣之盛衰，虛實之所起，不可以為工也。","sortOrder":8},
  {"id":"s_work_hdnk_86_9","chapterId":"ch_work_hdnk_86","text":"凡刺有五，以應五臟，一曰半刺，半刺者，淺內而疾發針，無針傷肉，如拔毛狀，以取皮氣，此肺之應也。","sortOrder":9},
  {"id":"s_work_hdnk_86_10","chapterId":"ch_work_hdnk_86","text":"二曰豹文刺，豹文刺者，左右前後針之，中脈為故，以取經絡之血者，此心之應也。","sortOrder":10},
  {"id":"s_work_hdnk_86_11","chapterId":"ch_work_hdnk_86","text":"三曰關刺，關刺者，直刺左右盡筋上，以取筋痺，慎無出血，此肝之應也；或曰淵刺；一曰豈刺。","sortOrder":11},
  {"id":"s_work_hdnk_86_12","chapterId":"ch_work_hdnk_86","text":"四曰合穀刺，合穀刺者，左右雞足，針於分肉之間，以取肌痺，此脾之應也。","sortOrder":12},
  {"id":"s_work_hdnk_86_13","chapterId":"ch_work_hdnk_86","text":"五曰輸刺，輸刺者，直入直出，深內之至骨，以取骨痺，此腎之應也。","sortOrder":13},
  {"id":"s_work_hdnk_87_1","chapterId":"ch_work_hdnk_87","text":"本神第八","sortOrder":1},
  {"id":"s_work_hdnk_87_2","chapterId":"ch_work_hdnk_87","text":"黃帝問於岐伯曰：凡刺之法，先必本於神。血、脈、營、氣、精神，此五臟之所藏也。至其淫泆離臟則精失、魂魄飛揚、志意恍亂、智慮去身者，何因而然乎？天之罪與？人之過乎？何謂德、氣、生、精、神、魂、魄、心、意、志、思、智、慮？請問其故。","sortOrder":2},
  {"id":"s_work_hdnk_87_3","chapterId":"ch_work_hdnk_87","text":"岐伯答曰：天之在我者德也，地之在我者氣也。德流氣薄而生者也。故生之來謂之精；兩精相搏謂之神；隨神往來者謂之魂；並精而出入者謂之魄；所以任物者謂之心；心有所憶謂之意；意之所存謂之志；因志而存變謂之思；因思而遠慕謂之慮；因慮而處物謂之智。","sortOrder":3},
  {"id":"s_work_hdnk_87_4","chapterId":"ch_work_hdnk_87","text":"故智者之養生也，必順四時而適寒暑，和喜怒而安居處，節陰陽而調剛柔。如是，則僻邪不至，長生久視。","sortOrder":4},
  {"id":"s_work_hdnk_87_5","chapterId":"ch_work_hdnk_87","text":"是故怵惕思慮者則傷神，神傷則恐懼流淫而不止。因悲哀動中者，竭絕而失生。喜樂者，神憚散而不藏。愁憂者，氣閉塞而不行。盛怒者，迷惑而不治。恐懼者，神蕩憚而不收。","sortOrder":5},
  {"id":"s_work_hdnk_87_6","chapterId":"ch_work_hdnk_87","text":"心，怵惕思慮則傷神，神傷則恐懼自失。破〈月困〉脫肉，毛悴色夭死於冬。","sortOrder":6},
  {"id":"s_work_hdnk_87_7","chapterId":"ch_work_hdnk_87","text":"脾愁憂而不解則傷意，意傷則悗亂，四肢不舉，毛悴色夭死於春。","sortOrder":7},
  {"id":"s_work_hdnk_87_8","chapterId":"ch_work_hdnk_87","text":"肝悲哀動中則傷魂，魂傷則狂忘不精，不精則不正，當人陰縮而攣筋，兩脅骨不舉，毛悴色夭死於秋。","sortOrder":8},
  {"id":"s_work_hdnk_87_9","chapterId":"ch_work_hdnk_87","text":"肺喜樂無極則傷魄，魄傷則狂，狂者意不存人，皮革焦，毛悴色夭死於夏。","sortOrder":9},
  {"id":"s_work_hdnk_87_10","chapterId":"ch_work_hdnk_87","text":"腎盛怒而不止則傷志，志傷則喜忘其前言，腰脊不可以俛仰屈伸，毛悴色夭死於季夏。","sortOrder":10},
  {"id":"s_work_hdnk_87_11","chapterId":"ch_work_hdnk_87","text":"恐懼而不解則傷精，精傷則骨痠痿厥，精時自下。是故五臟主藏精者也，不可傷，傷則失守而陰虛；陰虛則無氣，無氣則死矣。","sortOrder":11},
  {"id":"s_work_hdnk_87_12","chapterId":"ch_work_hdnk_87","text":"是故用針者，察觀病人之態，以知精、神、魂、魄之存亡，得失之意，五者以傷，針不可以治之也。","sortOrder":12},
  {"id":"s_work_hdnk_87_13","chapterId":"ch_work_hdnk_87","text":"肝藏血，血舍魂，肝氣虛則恐，實則怒。","sortOrder":13},
  {"id":"s_work_hdnk_87_14","chapterId":"ch_work_hdnk_87","text":"脾藏營，營舍意，脾氣虛則四肢不用，五臟不安，實則腹脹經溲不利。","sortOrder":14},
  {"id":"s_work_hdnk_87_15","chapterId":"ch_work_hdnk_87","text":"心藏脈，脈舍神，心氣虛則悲，實則笑不休。","sortOrder":15},
  {"id":"s_work_hdnk_87_16","chapterId":"ch_work_hdnk_87","text":"肺藏氣，氣舍魄，肺氣虛，則鼻塞不利少氣，實則喘喝胸盈仰息。","sortOrder":16},
  {"id":"s_work_hdnk_87_17","chapterId":"ch_work_hdnk_87","text":"腎藏精，精舍志，腎氣虛則厥，實則脹。五臟不安。必審五臟之病形，以知其氣之虛實，謹而調之也。","sortOrder":17},
  {"id":"s_work_hdnk_88_1","chapterId":"ch_work_hdnk_88","text":"終始第九","sortOrder":1},
  {"id":"s_work_hdnk_88_2","chapterId":"ch_work_hdnk_88","text":"凡刺之道，畢於終始，明知終始，五臟為紀，陰陽定矣。陰者主臟，陽者主腑，陽受氣於四末，陰受氣於五臟，故瀉者迎之，補者隨之，知迎知隨，氣可令和，和氣之方，必通陰陽。五臟為陰，六腑為陽，傳之後世，以血為盟。敬之者昌，慢之者亡。無道行私，必得夭殃。","sortOrder":2},
  {"id":"s_work_hdnk_88_3","chapterId":"ch_work_hdnk_88","text":"謹奉天道，請言終始。終始者，經脈為紀。持其脈口人迎，以知陰陽有餘不足，平與不平，天道畢矣。所謂平人者不病，不病者，脈口人迎應四時也，上下相應而俱往來也，六經之脈不結動也，本末之寒溫之相守司也。形肉血氣必相稱也，是謂平人。少氣者，脈口人迎俱少，而不稱尺寸也。如是者，則陰陽俱不足，補陽則陰竭，瀉陰則陽脫。如是者，可將以甘藥，不可飲以至劑，如此者弗灸。不巳者因而瀉之，則五臟氣壞矣。","sortOrder":3},
  {"id":"s_work_hdnk_88_4","chapterId":"ch_work_hdnk_88","text":"人迎一盛，病在足少陽，一盛而躁，病在手少陽。人迎二盛，病在足太陽，二盛而躁，病在手太陽，人迎三盛，病在足陽明，三盛而躁，病在手陽明。人迎四盛，且大且數，名曰溢陽，溢陽為外格。","sortOrder":4},
  {"id":"s_work_hdnk_88_5","chapterId":"ch_work_hdnk_88","text":"脈口一盛，病在足厥陰；厥陰一盛而躁，在手心主。脈口二盛，病在足少陰；二盛而躁，在手少陰。脈口三盛，病在足太陰；三盛而躁，在手太陰。脈口四盛，且大且數者，名曰溢陰。溢陰為內關，內關不通，死不治。人迎與太陰脈口俱盛四倍以上，名曰關格。關格者，與之短期。","sortOrder":5},
  {"id":"s_work_hdnk_88_6","chapterId":"ch_work_hdnk_88","text":"人迎一盛，瀉足少陽而補足厥陰，二瀉一補，日一取之，必切而驗之，疏取之，上氣和乃止。人迎二盛，瀉足太陽補足少陰，二瀉一補，二日一取之，必切而驗之，疏取之，上氣和乃止。人迎三盛，瀉足陽明而補足太陰，二瀉一補，日二取之，必切而驗之，疏取之，上氣和乃止。","sortOrder":6},
  {"id":"s_work_hdnk_88_7","chapterId":"ch_work_hdnk_88","text":"脈口一盛，瀉足厥陰而補足少陽，二補一瀉，日一取之，必切而驗之，疏而取，上氣和乃止。脈口二盛，瀉足少陰而補足太陽，二補一瀉，二日一取之，必切而驗之，疏取之，上氣和乃止。脈口三盛，瀉足太陰而補足陽明，二補一瀉，日二取之，必切而驗之，疏而取之，上氣和乃止。所以日二取之者，太、陽主胃，大富於穀氣，故可日二取之也。","sortOrder":7},
  {"id":"s_work_hdnk_88_8","chapterId":"ch_work_hdnk_88","text":"人迎與脈口俱盛三倍以上，命曰陰陽俱溢，如是者不開，則血脈閉塞，氣無所行，流淫於中，五臟內傷。如此者，因而灸之，則變易而為他病矣。","sortOrder":8},
  {"id":"s_work_hdnk_88_9","chapterId":"ch_work_hdnk_88","text":"凡刺之道，氣調而止，補陰瀉陽，音氣益彰，耳目聰明。反此者，血氣不行。","sortOrder":9},
  {"id":"s_work_hdnk_88_10","chapterId":"ch_work_hdnk_88","text":"所謂氣至而有效者，瀉則益虛，虛者，脈大如其故而不堅也；堅如其故者，適雖言故，病未去也。補則益實，實者，脈大如其故而益堅也；夫如其故而不堅者，適雖言快，病未去也。故補則實、瀉則虛，痛雖不隨針，病必衰去。必先通十二經脈之所生病，而後可得傳於終始矣。故陰陽不相移，虛實不相傾，取之其經。","sortOrder":10},
  {"id":"s_work_hdnk_88_11","chapterId":"ch_work_hdnk_88","text":"凡刺之屬，三刺至穀氣，邪僻妄合，陰陽易居，逆順相反，沉浮異處，四時不得，稽留淫泆須針而去。故一刺則陽邪出，再刺則陰邪出，三刺則穀氣至，穀氣至而止。所謂穀氣至者，已補而實，已瀉而虛，故以知穀氣至也。邪氣獨去者，陰與陽未能調而病知愈也。故曰：補則實，瀉則虛，痛雖不隨針，病必衰去矣。","sortOrder":11},
  {"id":"s_work_hdnk_88_12","chapterId":"ch_work_hdnk_88","text":"陰盛而陽虛，先補其陽，後瀉其陰而和之。陰虛而陽盛，先補其陰，後瀉其陽而和之。","sortOrder":12},
  {"id":"s_work_hdnk_88_13","chapterId":"ch_work_hdnk_88","text":"三脈動於足大趾之間，必審其實虛，虛而瀉之，是謂重虛。重虛病益甚。凡刺此者，以指按之，脈動而實且疾者疾瀉之，虛而徐者則補之。反此者，病益甚。其動也，陽明在上，厥陰在中，少陰在下。","sortOrder":13},
  {"id":"s_work_hdnk_88_14","chapterId":"ch_work_hdnk_88","text":"膺俞中膺，背俞中背，肩膊虛者，取之上。","sortOrder":14},
  {"id":"s_work_hdnk_88_15","chapterId":"ch_work_hdnk_88","text":"重舌，刺舌柱以鈹針也。","sortOrder":15},
  {"id":"s_work_hdnk_88_16","chapterId":"ch_work_hdnk_88","text":"手屈而不伸者，其病在筋，伸而不屈者，其病在骨，在骨守骨，在筋守筋。","sortOrder":16},
  {"id":"s_work_hdnk_88_17","chapterId":"ch_work_hdnk_88","text":"補須一方實，深取之，稀按其痏，以極出其邪氣。一方虛，淺刺之，以養其脈，疾按其痏，無使邪氣得入。邪氣來也緊而疾，穀氣來也徐而和。脈實者深刺之，以泄其氣；脈虛者，淺刺之，使精氣無瀉出，以養其脈，獨出其邪氣。","sortOrder":17},
  {"id":"s_work_hdnk_88_18","chapterId":"ch_work_hdnk_88","text":"刺諸痛者，其脈皆實。","sortOrder":18},
  {"id":"s_work_hdnk_88_19","chapterId":"ch_work_hdnk_88","text":"故曰：從腰以上者，手太陰陽明皆主之；從腰以下者，足太陰陽明皆主之。","sortOrder":19},
  {"id":"s_work_hdnk_88_20","chapterId":"ch_work_hdnk_88","text":"病在上者下取之；病在下者高取之；病在頭者取之足；病在腰者取之膕。","sortOrder":20},
  {"id":"s_work_hdnk_88_21","chapterId":"ch_work_hdnk_88","text":"病生於頭者，頭重；生於手者，臂重；生於足者，足重。治病者，先刺其病所從生者也。","sortOrder":21},
  {"id":"s_work_hdnk_88_22","chapterId":"ch_work_hdnk_88","text":"春氣在毛，夏氣在皮膚，秋氣在分肉，冬氣在筋骨。刺此病者，各以其時為齊。故刺肥人者，以秋冬之齊，刺瘦人者，以春夏之齊。","sortOrder":22},
  {"id":"s_work_hdnk_88_23","chapterId":"ch_work_hdnk_88","text":"病痛者，陰也，痛而以手按之不得者，陰也，深刺之。病在上者，陽也。病在下者，陰也。癢者，陽也，淺刺之。","sortOrder":23},
  {"id":"s_work_hdnk_88_24","chapterId":"ch_work_hdnk_88","text":"病先起陰者，先治其陰，而後治其陽；病先起陽者，先治其陽，而後治其陰。","sortOrder":24},
  {"id":"s_work_hdnk_88_25","chapterId":"ch_work_hdnk_88","text":"刺熱厥者，留針反為寒；刺寒厥者，留針反為熱。刺熱厥者，二陰一陽；刺寒厥者，二陽一陰。所謂二陰者，二刺陰也；一陽者，一刺陽也。","sortOrder":25},
  {"id":"s_work_hdnk_88_26","chapterId":"ch_work_hdnk_88","text":"久病者，邪氣入深。刺此病者，深內而久留之，間日而復刺之，必先調其左右，去其血脈，刺道畢矣。","sortOrder":26},
  {"id":"s_work_hdnk_88_27","chapterId":"ch_work_hdnk_88","text":"凡刺之法，必察其形氣。形肉未脫，少氣而脈又躁，躁厥者，必為繆刺之，散氣可收，聚氣可布。","sortOrder":27},
  {"id":"s_work_hdnk_88_28","chapterId":"ch_work_hdnk_88","text":"深居靜處，占神往來，閉戶塞牖，魂魄不散，專意一神，精氣之分，毋聞人聲，以收其精，必一其神，令志在針。","sortOrder":28},
  {"id":"s_work_hdnk_88_29","chapterId":"ch_work_hdnk_88","text":"淺而留之，微而浮之，以移其神，氣至乃休。","sortOrder":29},
  {"id":"s_work_hdnk_88_30","chapterId":"ch_work_hdnk_88","text":"男內女外，堅拒勿出，謹守勿內，是謂得氣。","sortOrder":30},
  {"id":"s_work_hdnk_88_31","chapterId":"ch_work_hdnk_88","text":"凡刺之禁：新內勿刺，新刺勿內；已醉勿刺，已刺勿醉；新怒勿刺，已刺勿怒；新勞勿刺，已刺勿勞；已飽勿刺，已刺勿飽；已飢勿刺，已刺勿飢；已渴勿刺，已刺勿渴；大驚大恐，必定其氣乃刺之。乘車來者，臥而休之，如食頃乃刺之。出行來者，坐而休之，如行千里頃乃刺之。凡此十二禁者，其脈亂氣散，逆其營衛，經氣不次，因而刺之，則陽病入於陰，陰病出為陽，則邪氣復生。粗工勿察，是謂伐身，形體淫亂，乃消腦髓，津液不化，脫其五味，是謂失氣也。","sortOrder":31},
  {"id":"s_work_hdnk_88_32","chapterId":"ch_work_hdnk_88","text":"太陽之脈，其終也。戴眼，反折，瘈瘲，其色白，絕皮乃絕汗，絕汗則終矣。","sortOrder":32},
  {"id":"s_work_hdnk_88_33","chapterId":"ch_work_hdnk_88","text":"少陽終者，耳聾，百節盡縱，目系絕，目系絕，一日半則死矣。其死也，色青白，乃死。","sortOrder":33},
  {"id":"s_work_hdnk_88_34","chapterId":"ch_work_hdnk_88","text":"陽明終者，口目動作，喜驚、妄言、色黃；其上下之經盛而不行，則終矣。","sortOrder":34},
  {"id":"s_work_hdnk_88_35","chapterId":"ch_work_hdnk_88","text":"少陰終者，面黑，齒長而垢，腹脹閉塞，上下不通而終矣。","sortOrder":35},
  {"id":"s_work_hdnk_88_36","chapterId":"ch_work_hdnk_88","text":"厥陰終者，中熱溢幹，喜溺，心煩，甚則舌卷，卵上縮而終矣。","sortOrder":36},
  {"id":"s_work_hdnk_88_37","chapterId":"ch_work_hdnk_88","text":"太陰終者，腹脹閉，不得息，氣噫，善嘔，嘔則逆，逆則面赤，不逆則上下不通，上下不通則面黑，皮毛憔而終矣。","sortOrder":37},
  {"id":"s_work_hdnk_89_1","chapterId":"ch_work_hdnk_89","text":"經脈第十","sortOrder":1},
  {"id":"s_work_hdnk_89_2","chapterId":"ch_work_hdnk_89","text":"雷公問於黃帝曰：「禁脈」之言，凡刺之理，經脈為始，營其所行，製其度量，內次五藏，外別六府，願盡聞其道。","sortOrder":2},
  {"id":"s_work_hdnk_89_3","chapterId":"ch_work_hdnk_89","text":"黃帝曰：人始生，先成精，精成而腦髓生，骨為幹，脈為營，筋為剛，肉為牆，皮膚堅而毛髮長，穀入於胃，脈道以通，血氣乃行。","sortOrder":3},
  {"id":"s_work_hdnk_89_4","chapterId":"ch_work_hdnk_89","text":"雷公曰：願卒聞經脈之始也。黃帝曰：經脈者，所以能決死生、處百病、調虛實，不可不通。","sortOrder":4},
  {"id":"s_work_hdnk_89_5","chapterId":"ch_work_hdnk_89","text":"肺手太陰之脈，起於中焦，下絡大腸，還循胃口，上膈屬肺，從肺系橫出腋下，下循臑內，行少陰心主之前，下肘中，循臂內上骨下廉，入寸口，上魚，循魚際，出大指之端；其支者，從腕後直出次指內廉出其端。","sortOrder":5},
  {"id":"s_work_hdnk_89_6","chapterId":"ch_work_hdnk_89","text":"是動則病肺脹滿，膨脹而喘咳，缺盆中痛，甚則交兩手而瞀，此為臂厥。是主肺所生病者，咳上氣，喘渴，煩心，胸滿，臑臂內前廉痛厥，掌中熱。氣盛有餘，則肩背痛，風寒汗出中風，小便數而欠。氣虛則肩背痛，寒，少氣不足以息，溺色變。為此諸病，盛則瀉之，虛則補之，熱則疾之，寒則留之，陷下則灸之，不盛不虛，以經取之。盛者，寸口大三倍於人迎，虛者，則寸口反小於人迎也。","sortOrder":6},
  {"id":"s_work_hdnk_89_7","chapterId":"ch_work_hdnk_89","text":"大腸手陽明之脈，起於大指次指之端，循指上廉，出合穀兩骨之間，上入兩筋之中，循臂上廉，入肘外廉，上臑外前廉，上肩，出髃骨之前廉，上出於柱骨之會上，下入缺盆，絡肺，下膈，屬大腸。其支者，從缺盆上頸，貫頰，入下齒中，還出挾口，交人中，左之右，右之左，上挾鼻孔。","sortOrder":7},
  {"id":"s_work_hdnk_89_8","chapterId":"ch_work_hdnk_89","text":"是動則病齒痛，頸腫。是主津液所生病者，目黃，口乾，鼽衄，喉痺，肩前臑痛，大指次指痛不用，氣有餘則當脈所過者熱腫；虛則寒慄不復。為此諸病，盛則瀉之，虛則補之，熱則疾之，寒則留之，陷下則灸之，不盛不虛，以經取之。盛者，人迎大三倍於寸口；虛者，人迎反小於寸口也。","sortOrder":8},
  {"id":"s_work_hdnk_89_9","chapterId":"ch_work_hdnk_89","text":"胃足陽明之脈，起於鼻之交頞中，旁納太陽之脈，下循鼻外，入上齒中，還出挾口環唇，下交承漿，卻循頤後下廉，出大迎，循頰車，上耳前，過客主人，循髮際，至額顱；其支者，從大迎前下人迎，循喉嚨，入缺盆，下膈，屬胃，絡脾；其直者，從缺盆下乳內廉，下挾臍，入氣沖中；其支者，起於胃口，下循腹裏，下至氣沖中而合，以下髀關，抵伏兔，下膝臏中，下循脛外廉，下足跗，入中指內間；其支者，下廉三寸而別下入中趾外間；其支者，別跗上，入大趾間出其端。","sortOrder":9},
  {"id":"s_work_hdnk_89_10","chapterId":"ch_work_hdnk_89","text":"是動則病洒洒振寒，善呻，數欠，顏黑，病至則惡人與火，聞木聲則惕然而驚，心欲動，獨閉戶塞牖而處。甚則欲上高而歌，棄衣而走，賁嚮腹脹，是為骭厥。是主血所生病者，狂瘧溫淫，汗出，鼽衄，口喎，唇胗，頸腫，喉痺，大腹水腫，膝臏腫痛，循膺乳、氣沖、股、伏兔、骭外廉、足跗上皆痛，中趾不用，氣盛則身以前皆熱，其有餘於胃，則消穀善飢，溺色黃；氣不足則身以前皆寒慄，胃中寒則脹滿。為此諸病，盛則瀉之，虛則補之，熱則疾之，寒則留之，陷下則灸之，不盛不虛，以經取之。盛者，人迎大三倍於寸口，虛者，人迎反小於寸口也。","sortOrder":10},
  {"id":"s_work_hdnk_89_11","chapterId":"ch_work_hdnk_89","text":"脾足太陰之脈，起於大趾之端，循趾內側白肉際，過核骨後，上內踝前廉，上踹內，循脛骨後，交出厥陰之前，上膝股內前廉，入腹，屬脾，絡胃，上膈，挾咽，連吞本，散舌下；其支者，復從胃，別上膈、註心中。","sortOrder":11},
  {"id":"s_work_hdnk_89_12","chapterId":"ch_work_hdnk_89","text":"是動則病舌本強，食則嘔，胃脘痛，腹脹，善噫，得後與氣，則快然如衰，身體皆重。是主脾所生病者，舌本痛，體不能動搖，食不下，煩心，心下急痛，溏瘕泄，水閉，黃疸，不能臥，強立，股膝內腫厥，足大趾不用。為此諸病，盛則瀉之，虛則補之，熱則疾之，寒則留之，陷下則灸之，不盛不虛，以經取之。盛者，寸口大三倍於人迎，虛者，寸口反小於人迎。","sortOrder":12},
  {"id":"s_work_hdnk_89_13","chapterId":"ch_work_hdnk_89","text":"心手少陰之脈，起於心中，出屬心系，下膈，絡小腸；其支者，從心系，上挾咽，系目系；其直者，復從心系卻上肺，下出腋下，下循臑內後廉，行太陰心主之後，下肘內，循臂內後廉，抵掌後銳骨之端，入掌內後廉，循小指之內，出其端。","sortOrder":13},
  {"id":"s_work_hdnk_89_14","chapterId":"ch_work_hdnk_89","text":"是動則病嗌幹，心痛，渴而欲飲，是為臂厥。是主心所生病者，目黃，脅痛，臑臂內後廉痛厥，掌中熱痛。為此諸病，盛則瀉之，虛則補之，熱則疾之，寒則留之，陷下則灸之，不盛不虛，以經取之。盛者，寸口大再倍於人迎，虛者，寸口反小於人迎也。","sortOrder":14},
  {"id":"s_work_hdnk_89_15","chapterId":"ch_work_hdnk_89","text":"小腸手太陽之脈，起於小指之端，循手外側，上腕，出踝中，直上循臂骨下廉，出肘內側兩筋之間，上循臑外後廉，出肩解，繞肩胛，交肩上，入缺盆，絡心，循咽，下膈，抵胃，屬小腸；其支者，從缺盆循頸上頰，至目銳眥，卻入耳中；其支者，別頰上〈出頁〉，抵鼻，至目內眥，斜絡於顴。","sortOrder":15},
  {"id":"s_work_hdnk_89_16","chapterId":"ch_work_hdnk_89","text":"是動則病嗌痛，頷腫，不可以顧，肩似拔，臑似折。是主液所生病者，耳聾、目黃，頰腫，頸、頷、肩、臑、肘、臂外後廉痛。為此諸病，盛則瀉之，虛則補之，熱則疾之，寒則留之，陷下則灸之，不盛不虛，以經取之。盛者，人迎大再倍於寸口，虛者，人迎反小於寸口也。","sortOrder":16},
  {"id":"s_work_hdnk_89_17","chapterId":"ch_work_hdnk_89","text":"膀胱足太陽之脈，起於目內眥，上額，交巔；其支者，從巔至耳上角；其直者，從巔入絡腦，還出別下項，循肩髆內，挾脊，抵腰中，入循膂，絡腎，屬膀胱；其支者，從腰中下挾脊，貫臀，入膕中；其支者，從髆內左右，別下，貫胛，挾脊內，過髀樞，循髀外，從後廉，下合膕中，以下貫踹（湍）內，出外踝之後，循京骨，至小趾外側。","sortOrder":17},
  {"id":"s_work_hdnk_89_18","chapterId":"ch_work_hdnk_89","text":"是動則病沖頭痛，目似脫，項如拔，脊痛，腰似折，髀不可以曲，膕如結，踹（湍）如裂，是為踝厥。是主筋所生病者，痔、瘧、狂、癲疾、頭顖項痛，目黃、淚出，鼽衄，項、背、腰、尻、膕踹（湍）、腳皆痛，小趾不用。為此諸病，盛則瀉之，虛則補之，熱則疾之，寒則留之，陷下則灸之，不盛不虛，以經取之。盛者，人迎大再倍於寸口，虛者，人迎反小於寸口也。","sortOrder":18},
  {"id":"s_work_hdnk_89_19","chapterId":"ch_work_hdnk_89","text":"腎足少陰之脈，起於小趾之下，邪走足心，出於然穀之下，循內踝之後，別入跟中，以上踹（湍）內，出膕內廉，上股內後廉，貫脊，屬腎，絡膀胱；其直者，從腎上貫肝膈，入肺中，循喉嚨，挾舌本；其支者，從肺出絡心，註胸中。","sortOrder":19},
  {"id":"s_work_hdnk_89_20","chapterId":"ch_work_hdnk_89","text":"是動則病飢不欲食，面如漆柴，咳唾則有血，喝喝而喘，坐而欲起，目〈流，氵改目〉〈流，氵改目〉如無所見，心如懸若飢狀。氣不足則善恐，心惕惕如人將捕之，是為骨厥。是主腎所生病者，口熱，舌乾，咽腫，上氣，嗌乾及痛，煩心，心痛，黃疸，腸澼，脊股內後廉痛，痿厥，嗜臥，足下熱而痛。為此諸病，盛則瀉之，虛則補之，熱則疾之，寒則留之，陷下則灸之，不盛不虛，以經取之。灸則強食生肉，緩帶披發，大杖重履而步。盛者，寸口大再倍於人迎，虛者，寸口反小於人迎也。","sortOrder":20},
  {"id":"s_work_hdnk_89_21","chapterId":"ch_work_hdnk_89","text":"心主手厥陰心包絡之脈，起於胸中，出屬心包絡，下膈，歷絡三焦；其支者，循胸出脅，下腋三寸，上抵腋下，循臑內，行太陰、少陰之間，入肘中，下臂，行兩筋之間，入掌中，循中指，出其端；其支者，別掌中，循小指次指，出其端。","sortOrder":21},
  {"id":"s_work_hdnk_89_22","chapterId":"ch_work_hdnk_89","text":"是動則病手心熱，臂肘攣急，腋腫，甚則胸脅支滿，心中憺憺大動，面赤，目黃，喜笑不休。是主脈所生病者，煩心，心痛，掌中熱。為此諸病，盛則瀉之，虛則補之，熱則疾之，寒則留之，陷下則灸之，不盛不虛，以經取之。盛者，寸口大一倍於人迎，虛者，寸口反小於人迎也。","sortOrder":22},
  {"id":"s_work_hdnk_89_23","chapterId":"ch_work_hdnk_89","text":"三焦手少陽之脈，起於小指次指之端，上出兩指之間，循手表腕，出臂外兩骨之間，上貫肘，循臑外，上肩，而交出足少陽之後，入缺盆，布膻中，散落心包，下膈，循屬三焦；其支者，從膻中上出缺盆，上項系耳後，直上出耳上角，以屈下頰至〈出頁〉，其支者，從耳後入耳中，出走耳前，過客主人前，交頰，至目銳眥。","sortOrder":23},
  {"id":"s_work_hdnk_89_24","chapterId":"ch_work_hdnk_89","text":"是動則病耳聾渾渾焞焞，嗌腫，喉痺。是主氣所生病者，汗出，目銳眥痛，頰痛，耳後、肩、臑、肘、臂外皆痛，小指次指不用。為此諸病，盛則瀉之，虛則補之，熱則疾之，寒則留之，陷下則灸之，不盛不虛，以經取之。盛者，人迎大一倍於寸口，虛者，人迎反小於寸口也。","sortOrder":24},
  {"id":"s_work_hdnk_89_25","chapterId":"ch_work_hdnk_89","text":"膽足少陽之脈，起於目銳眥，上抵頭角下耳後，循頸行手少陽之前，至肩上卻交出手少陽之後，入缺盆；其支者，從耳後入耳中，出走耳前，至目銳眥後；其支者，別銳眥，下大迎，合於手少陽，抵於〈出頁〉下，加頰車，下頸，合缺盆，以下胸中，貫膈，絡肝，屬膽，循脅裏，出氣沖，繞毛際，橫入髀厭中；其直者，從缺盆下腋，循胸，過季脅下合髀厭中，以下循髀陽，出膝外廉，下外輔骨之前，直下抵絕骨之端，下出外踝之前，循足跗上，入小趾次趾之間；其支者，別跗上，入大指之間，循大指歧骨內，出其端，還貫爪甲，出三毛。","sortOrder":25},
  {"id":"s_work_hdnk_89_26","chapterId":"ch_work_hdnk_89","text":"是動則病口苦，善太息，心脅痛，不能轉側，甚則面微有塵，體無膏澤，足外反熱，是為陽厥。是主骨所生病者，頭痛，頷痛，目銳眥痛，缺盆中腫痛，腋下腫，馬刀俠癭，汗出振寒，瘧，胸、脅、肋、髀、膝外至脛、絕骨、外踝前及諸節皆痛，小趾次趾不用。為此諸病，盛則瀉之，虛則補之，熱則疾之，寒則留之，陷下則灸之，不盛不虛，以經取之。盛者，人迎大一倍於寸口，虛者，人迎反小於寸口也。","sortOrder":26},
  {"id":"s_work_hdnk_89_27","chapterId":"ch_work_hdnk_89","text":"肝足厥陰之脈，起於大趾叢毛之際，上循足跗上廉，去內踝一寸，上踝八寸，交出太陰之後，上膕內廉，循股陰，入毛中，過陰器，抵小腹，挾胃，屬肝，絡膽，上貫膈，布脅肋，循喉嚨之後，上入頏顙，連目系，上出額，與督脈會於巔；其支者，從目系下頰裏，環唇內；其支者，復從肝，別貫膈，上註肺。","sortOrder":27},
  {"id":"s_work_hdnk_89_28","chapterId":"ch_work_hdnk_89","text":"是動則病腰痛不可以俛仰，丈夫〈疒貴〉疝，婦人少腹腫，甚則嗌乾，面塵，脫色。是主肝所生病者，胸滿，嘔逆，飧泄，狐疝，遺溺，閉癃。為此諸病，盛則瀉之，虛則補之，熱則疾之，寒則留之，陷下則灸之，不盛不虛，以經取之。盛者，寸口大一倍於人迎，虛者，寸口反小於人迎也。","sortOrder":28},
  {"id":"s_work_hdnk_89_29","chapterId":"ch_work_hdnk_89","text":"手太陰氣絕，則皮毛焦。太陰者，行氣溫於皮毛者也。故氣不榮，則皮毛焦；皮毛焦，則津液去皮節；津液去皮節者，則爪枯毛折；毛折者，則毛先死。兩篤丁死，火勝金也。","sortOrder":29},
  {"id":"s_work_hdnk_89_30","chapterId":"ch_work_hdnk_89","text":"手少陰氣絕，則脈不通；脈不通，則血不流；血不流，則髮色不澤，故其面黑如漆柴者，血先死。壬篤癸死，水勝火也。","sortOrder":30},
  {"id":"s_work_hdnk_89_31","chapterId":"ch_work_hdnk_89","text":"足太陰氣絕者，則脈不榮肌肉。唇舌者，肌肉之本也。脈不榮，則肌肉軟；肌肉軟，則舌萎人中滿；人中滿，則唇反；唇反者，肉先死。甲篤乙死，木勝土也。","sortOrder":31},
  {"id":"s_work_hdnk_89_32","chapterId":"ch_work_hdnk_89","text":"足少陰氣絕，則骨枯。少陰者，冬脈也，伏行而濡骨髓者也，故骨不濡，則肉不能著也；骨肉不相親，則肉軟卻；肉軟卻，故齒長而垢，發無澤；發無澤者，骨先死。戊篤己死，土勝水也。","sortOrder":32},
  {"id":"s_work_hdnk_89_33","chapterId":"ch_work_hdnk_89","text":"足厥陰氣絕，則筋絕。厥陰者，肝脈也，肝者，筋之合也，筋者，聚於陰氣，而脈絡於舌本也。故脈弗榮，則筋急；筋急則引舌與卵，故唇青舌卷卵縮，則筋先死。庚篤辛死，金勝木也。","sortOrder":33},
  {"id":"s_work_hdnk_89_34","chapterId":"ch_work_hdnk_89","text":"五陰氣俱絕，則目系轉，轉則目運；目運者，為志先死；志先死，則遠一日半死矣。六陽氣絕，則陰與陽相離，離則腠理發泄，絕汗乃出，故旦占夕死，夕占旦死。","sortOrder":34},
  {"id":"s_work_hdnk_89_35","chapterId":"ch_work_hdnk_89","text":"經脈十二者，伏行分肉之間，深而不見；其常見者，足太陰過於外踝之上，無所隱故也。諸脈之浮而常見者，皆絡脈也。六經絡，手陽明少陽之大絡，起於五指間，上合肘中。飲酒者，衛氣先行皮膚，先充絡脈，絡脈先盛。故衛氣已平，營氣乃滿，而經脈大盛。脈之卒然動者，皆邪氣居之，留於本末，不動則熱，不堅則陷且空，不與眾同，是以知其何脈之動也。","sortOrder":35},
  {"id":"s_work_hdnk_89_36","chapterId":"ch_work_hdnk_89","text":"雷公曰：何以知經脈之與絡脈異也？黃帝曰：經脈者，常不可見也，其虛實也，以氣口知之。脈之見者，皆絡脈也。","sortOrder":36},
  {"id":"s_work_hdnk_89_37","chapterId":"ch_work_hdnk_89","text":"雷公曰：細子無以明其然也。黃帝曰：諸絡脈皆不能經大節之間，必行絕道而出入，復合於皮中，其會皆見於外。故諸刺絡脈者，必刺其結上甚血者。雖無結，急取之，以瀉其邪而出其血。留之發為痹也。凡診絡脈，脈色青，則寒，且痛；赤則有熱。胃中寒，手魚之絡多青矣；胃中有熱，魚際絡赤。其暴黑者，留久痹也。其有赤、有黑、有青者，寒熱氣也。其青短者，少氣也。凡刺寒熱者，皆多血絡，必間日而一取之，血盡而止，乃調其虛實。其小而短者，少氣，甚者，瀉之則悶，悶甚則仆，不得言，悶則急坐之也。","sortOrder":37},
  {"id":"s_work_hdnk_89_38","chapterId":"ch_work_hdnk_89","text":"手太陰之別，名曰列缺。起於腕上分間，併太陰之經，直入掌中，散入於魚際。其病實則手銳掌熱；虛則欠〈去欠〉，小便遺數。取之去腕寸半。別走陽明也。","sortOrder":38},
  {"id":"s_work_hdnk_89_39","chapterId":"ch_work_hdnk_89","text":"手少陰之別，名曰通裏。去腕一寸半，別而上行，循經入於心中，系舌本，屬目系。其實則支膈，虛則不能言。取之掌後一寸，別走太陽也。","sortOrder":39},
  {"id":"s_work_hdnk_89_40","chapterId":"ch_work_hdnk_89","text":"手心主之別，名曰內關。去腕二寸，出於兩筋之間，循經以上，系於心包絡。心系實則心痛，虛則為頭強。取之兩筋間也。","sortOrder":40},
  {"id":"s_work_hdnk_89_41","chapterId":"ch_work_hdnk_89","text":"手太陽之別，名曰支正。上腕五寸，內註少陰；其別者，上走肘，絡肩髃。實則節弛肘廢；虛則生肬，小者如指痂疥。取之所別也。","sortOrder":41},
  {"id":"s_work_hdnk_89_42","chapterId":"ch_work_hdnk_89","text":"手陽明之別，名曰偏歷。去腕三寸，別入太陰；其別者，上循臂，乘肩髃，上曲頰傷齒；其別者，入耳，合於宗脈。實則齲聾；虛則齒寒痹隔。取之所別也。","sortOrder":42},
  {"id":"s_work_hdnk_89_43","chapterId":"ch_work_hdnk_89","text":"手少陽之別，名曰外關。去腕二寸，外繞臂，註胸中，合心主。病實則肘攣，虛則不收。取之所別也。","sortOrder":43},
  {"id":"s_work_hdnk_89_44","chapterId":"ch_work_hdnk_89","text":"足太陽之別，名曰飛揚。去踝七寸，別走少陰。實則鼽窒，頭背痛；虛則鼽衄。取之所別也。","sortOrder":44},
  {"id":"s_work_hdnk_89_45","chapterId":"ch_work_hdnk_89","text":"足少陽之別，名曰光明，去踝五寸，別走厥陰，下絡足跗。實則厥，虛則痿躄，坐不能起。取之所別也。","sortOrder":45},
  {"id":"s_work_hdnk_89_46","chapterId":"ch_work_hdnk_89","text":"足陽明之別，名曰豐隆。去踝八寸。別走太陰；其別者，循脛骨外廉，上絡頭項，合諸經之氣，下絡喉嗌。其病氣逆則喉痹瘁瘖。實則狂巔，虛則足不收，脛枯。取之所別也。","sortOrder":46},
  {"id":"s_work_hdnk_89_47","chapterId":"ch_work_hdnk_89","text":"足太陰之別，名曰公孫。去本節之後一寸，別走陽明；其別者，入絡腸胃，厥氣上逆則霍亂，實則腸中切痛；虛則鼓脹。取之所別也。","sortOrder":47},
  {"id":"s_work_hdnk_89_48","chapterId":"ch_work_hdnk_89","text":"足少陰之別，名曰大鍾。當踝後繞跟，別走太陽；其別者，併經上走於心包下，外貫腰脊。其病氣逆則煩悶，實則閉癃，虛則腰痛。取之所別者也。","sortOrder":48},
  {"id":"s_work_hdnk_89_49","chapterId":"ch_work_hdnk_89","text":"足厥陰之別，名曰蠡溝。去內踝五寸，別走少陽；其別者，經脛上睪，結於莖。其病氣逆則睪腫卒疝。實則挺長，虛則暴癢。取之所別也。","sortOrder":49},
  {"id":"s_work_hdnk_89_50","chapterId":"ch_work_hdnk_89","text":"任脈之別，名曰尾翳。下鳩尾，散於腹。實則腹皮痛，虛則痒搔。取之所別也。","sortOrder":50},
  {"id":"s_work_hdnk_89_51","chapterId":"ch_work_hdnk_89","text":"督脈之別，名曰長強。挾膂上項，散頭上，下當肩胛左右，別走太陽，入貫膂。實則脊強，虛則頭重，高搖之，挾脊之有過者。取之所別也。","sortOrder":51},
  {"id":"s_work_hdnk_89_52","chapterId":"ch_work_hdnk_89","text":"脾之大絡，名曰大包。出淵腋下三寸，布胸脅。實則身盡痛，虛則百節盡皆縱。此脈若罷絡之血者，皆取之脾之大絡脈也。","sortOrder":52},
  {"id":"s_work_hdnk_89_53","chapterId":"ch_work_hdnk_89","text":"凡此十五絡者，實則必見，虛則必下。視之不見，求之上下。人經不同，絡脈亦所別也。","sortOrder":53},
  {"id":"s_work_hdnk_90_1","chapterId":"ch_work_hdnk_90","text":"經別第十一","sortOrder":1},
  {"id":"s_work_hdnk_90_2","chapterId":"ch_work_hdnk_90","text":"黃帝問於岐伯曰：餘聞人之合於天地道也，內有五臟，以應五音、五色、五時、五味、五位也；外有六腑，以應六律。六律建陰陽諸經而合之十二月、十二辰、十二節、十二經水、十二時、十二經脈者，此五臟六腑之所以應天道。夫十二經脈者，人之所以生，病之所以成，人之所以治，病之所以起，學之所始，工之所止也。粗之所易，上之所難也。請問其離合，出入奈何？岐伯稽首再拜曰：明乎哉問也！此粗之所過，上之所息也，請卒言之。","sortOrder":2},
  {"id":"s_work_hdnk_90_3","chapterId":"ch_work_hdnk_90","text":"足太陽之正，別入於膕中，其一道下尻五寸，別入於肛，屬於膀胱，散之腎，循膂，當心入散；直者，從膂上出於項，復屬於太陽，此為一經也。足少陰之正，至膕中，別走太陽而合，上至腎，當十四椎出屬帶脈；直者，系舌本，復出於項，合於太陽，此為一合。成以諸陰之別，皆為正也。","sortOrder":3},
  {"id":"s_work_hdnk_90_4","chapterId":"ch_work_hdnk_90","text":"足少陽之正，繞髀入毛際，合於厥陰，別者入季脅之間，循胸裏屬膽，散之上肝，貫心以上挾咽，出頤頜中，散於面，系目系，合少陽於外眥也。足厥陰之正，別跗上，上至毛際，合於少陽，與別俱行，此為二合也。","sortOrder":4},
  {"id":"s_work_hdnk_90_5","chapterId":"ch_work_hdnk_90","text":"足陽明之正，上至脾，入於腹裏屬胃，散之脾，上通於心，上循咽出於口，上頞〈出頁〉，還系目系，合於陽明也。足太陰之正，上至髀，合於陽明，與別俱行，上結於咽，貫舌中，此為三合也。","sortOrder":5},
  {"id":"s_work_hdnk_90_6","chapterId":"ch_work_hdnk_90","text":"手太陽之正，指地，別於肩解，入腋走心，系小腸也。手少陰之正，別入於淵腋兩筋之間，屬於心，上走喉嚨，出於面，合目內眥，此為四合也。","sortOrder":6},
  {"id":"s_work_hdnk_90_7","chapterId":"ch_work_hdnk_90","text":"手少陽之正，指天，別於巔，入缺盆，下走三焦，散於胸中也。手心主之正，別下淵腋三寸，入胸中，別屬三焦，出循喉嚨，出耳後，合少陽完骨之下，此為五合也。","sortOrder":7},
  {"id":"s_work_hdnk_90_8","chapterId":"ch_work_hdnk_90","text":"手陽明之正，從手循膺乳，別於肩髃，入柱骨，下走大腸，屬於肺，上循喉嚨，出缺盆，合於陽明也。手太陰之正，別入淵腋少陰之前，入走肺，散之大陽（腸），上出缺盆，循喉嚨，復合陽明，此六合也。","sortOrder":8},
  {"id":"s_work_hdnk_91_1","chapterId":"ch_work_hdnk_91","text":"經水第十二","sortOrder":1},
  {"id":"s_work_hdnk_91_2","chapterId":"ch_work_hdnk_91","text":"黃帝問於岐伯曰：經脈十二者，外合於十二經水，而內屬於五臟六腑。夫十二經水者，其有大小、深淺、廣狹、遠近各不同；五臟六腑之高下、大小、受穀之多少亦不等，相應奈何？夫經水者，受水而行之；五臟者，合神氣魂魄而藏之；六腑者，受穀而行之，受氣而揚之；經脈者，受血而營之。合而以治，奈何？刺之深淺，灸之壯數，可得聞乎？","sortOrder":2},
  {"id":"s_work_hdnk_91_3","chapterId":"ch_work_hdnk_91","text":"岐伯答曰：善哉問也！天至高不可度，地至廣不可量，此之謂也。且夫人生於天地之間，六合之內，此天之高，地之廣也，非人力之所能度量而至也。若夫八尺之士，皮肉在此，外可度量切循而得之，其死可解剖而視之。其藏之堅脆，腑之大小，穀之多少，脈之長短，血之清濁，氣之多少，十二經之多血少氣，與其少血多氣，與其皆多血氣，與其皆少血氣，皆有大數。其治以針艾，各調其經氣，固其常有合乎。","sortOrder":3},
  {"id":"s_work_hdnk_91_4","chapterId":"ch_work_hdnk_91","text":"黃帝曰：餘聞之，快於耳不解於心，願卒聞之。岐伯答曰：此人之所以參天地而應陰陽也，不可不察。足太陽外合清水，內屬於膀胱，而通水道焉。足少陽外合於渭水，內屬於膽。足陽明外合於海水，內屬於胃。足太陰外合於湖水，內屬於脾。足少陰外合於汝水，內屬於腎。足厥陰外合於澠水，內屬於肝。手太陽外合於淮水，內屬於小腸，而水道出焉。手少陽外合於漯水，內屬於三焦。手陽明外合於江水，內屬於大腸。手太陰外合於河水，內屬於肺。手少陰外合濟水，內屬於心。手心主外合於漳水，內屬於心包。凡此五臟六腑十二經水者，外有源泉，而內有所稟，此皆內外相貫，如環無端，人經亦然。故天為陽，地為陰，腰以上為天，腰以下為地。故海以北者為陰，湖以北者為陰中之陰；漳以南者為陽，河以北至漳者為陽中之陰；漯以南至江者，為陽中之太陽，此一隅之陰陽也，所以人與天地相參也。","sortOrder":4},
  {"id":"s_work_hdnk_91_5","chapterId":"ch_work_hdnk_91","text":"黃帝曰：夫經水之應經脈也，其遠近淺深，水血之多少，各不同，合而以刺之奈何？岐伯答曰：足陽明，五臟六腑之海也，其脈大，血多氣盛，熱壯，刺此者不深勿散，不留不瀉也。足陽明刺深六分，留十呼。足太陽深五分，留七呼。足少陽深四分，留五呼。足太陰深三分，留四呼。足少陰深二分，留三呼。足厥陰深一分，留二呼。手之陰陽，其受氣之道近，其氣之來疾，其刺深者，皆無過二分，其留，皆無過一呼。其少長、大小、肥瘦，以心擦之，命曰法天之常，灸之亦然。灸而過此者，得惡火則骨枯脈澀，刺而過此者，則脫氣。","sortOrder":5},
  {"id":"s_work_hdnk_91_6","chapterId":"ch_work_hdnk_91","text":"黃帝曰：夫經脈之大小，血之多少，膚之厚薄，肉之堅脆及膕之大小，可為量度乎？岐伯答曰：其可為度量者，取其中度也。不甚脫肉，而血氣不衰也。若夫度之人，消瘦而形肉脫者，惡可以度量刺乎。審、切、循、捫、按，視其寒溫盛衰而調之，是謂因適而為之真也。","sortOrder":6},
  {"id":"s_work_hdnk_92_1","chapterId":"ch_work_hdnk_92","text":"經筋第十三","sortOrder":1},
  {"id":"s_work_hdnk_92_2","chapterId":"ch_work_hdnk_92","text":"足太陽之筋，起於足小趾，上結於踝，邪上結於膝，其下循足外側，結於踵，上循跟，結於膕；其別者，結於踹外，上膕中內廉，與膕中併上結於臀，上挾脊上項；其支者，別入結於舌本；其直者，結於枕骨，上頭，下顏，結於鼻；其支者，為目上網，下結於頄；其支者，從腋後外廉結於肩髃；其支者，入腋下，上出缺盆，上結於完骨；其支者，出缺盆，邪上出於頄。其病小趾支跟腫痛，膕攣，脊反折，項筋急，肩不舉，腋支缺盆中紐痛，不可左右搖。治在燔針劫刺，以知為數，以痛為輸，名曰仲春痹也。","sortOrder":2},
  {"id":"s_work_hdnk_92_3","chapterId":"ch_work_hdnk_92","text":"足少陽之筋，起於小指次指，上結外踝，上循脛外廉，結於膝外廉；其支者，別起外輔骨，上走髀，前者結於伏兔之上，後者，結於尻；其直者，上乘沙季脅，上走腋前廉，繫於膺乳，結於缺盆；直者，上出腋，貫缺盆，出太陽之前，循耳後，上額角，交巔上，下走頷，上結於頄；支者，結於目眥為外維。其病小指次指支轉筋，引膝外轉筋，膝不可屈伸，膕筋急，前引髀，後引尻，即上乘〈月少〉季脅痛，上引缺盆、膺乳、頸維筋急。從左之右，右目不開，上過右角，併蹻脈而行，左絡於右，故傷左角，右足不用，命曰維筋相交。治在燔針劫刺，以知為數，以痛為輸，名曰孟春痹也。","sortOrder":3},
  {"id":"s_work_hdnk_92_4","chapterId":"ch_work_hdnk_92","text":"足陽明之筋，起於中三指，結於跗上，邪外上加於輔骨，上結於膝外廉，直上結於髀樞，上循脅屬脊；其直者，上循骭，結於膝；其支者，結於外輔骨，合少陽；其直者，上循伏兔，上結於髀，聚於陰器，上腹而布，至缺盆而結，上頸，上挾口，合於頄，下結於鼻，上合於太陽。太陽為目上網，陽明為目下網；其支者，從頰結於耳前。其病足中指支脛轉筋，腳跳堅，伏兔轉筋，髀前踵，〈疒貴〉疝，腹筋急，引缺盆及頰，卒口僻；急者，目不合，熱則筋縱，目不開，頰筋有寒，則急，引頰移口，有熱則筋弛縱，緩不勝收，故僻。治之以馬膏，膏其急者；以白酒和桂，以塗其緩者，以桑鉤鉤之，即以生桑炭置之坎中，高下以坐等。以膏熨急頰，且飲美酒，敢美炙肉，不飲酒者，自強也，為之三拊而已。治在燔針劫刺，以知為數，以痛為輸，名曰季春痹也。","sortOrder":4},
  {"id":"s_work_hdnk_92_5","chapterId":"ch_work_hdnk_92","text":"足太陰之筋，起於大指之端內側，上結於內踝；其直者，絡於膝內輔骨，上循陰股，結於髀，聚於陰器，上腹結於臍，循腹裏，結於肋，散於胸中；其內者，著於脊。其病足大指支內踝痛，轉筋痛，膝內輔骨痛，陰股引髀而痛，陰器紐痛，上引臍兩脅痛，引膺中脊內痛。治在燔針劫刺，以知為數，以痛為輸，命曰孟秋痹也。","sortOrder":5},
  {"id":"s_work_hdnk_92_6","chapterId":"ch_work_hdnk_92","text":"足少陰之筋，起於小指之下，併足太陰之筋，邪走內踝之下，結於踵，與太陽之筋合，而上結於內輔之下，併太陰之筋，而上循陰股，結於陰器，循脊內挾膂上至項，結於枕骨，與足太陽之筋合。其病足下轉筋，及所過而結者皆痛及轉筋。病在此者，主癎瘈及痙，在外者不能挽，在內者不能仰。故陽病者，腰反折不能俛，陰病者，不能仰。治在燔針劫刺，以知為數，以痛為輸。在內者熨引飲藥，此筋折紐，紐發數甚者死不治，名曰仲秋痹也。","sortOrder":6},
  {"id":"s_work_hdnk_92_7","chapterId":"ch_work_hdnk_92","text":"足厥陰之筋，起於大指之上，上結於內踝之前，上循脛，上結內輔之下，上循陰股，結於陰器，絡諸筋。其病足大指支內踝之前痛，內輔痛，陰股痛轉筋，陰器不用，傷於內則不起，傷於寒則陰縮入，傷於熱則縱挺不收，治在行水清陰氣；其病轉筋者，治在燔針劫刺，以知為數，以痛為輸，命曰季秋痹也。","sortOrder":7},
  {"id":"s_work_hdnk_92_8","chapterId":"ch_work_hdnk_92","text":"手太陽之筋，起於小指之上，結於腕，上循臂內廉，結於肘內銳骨之後，彈之應小指之上，入結於腋下；其支者，後走腋後廉，上繞肩胛，循頸出走太陽之前，結於耳後完骨；其支者，入耳中；直者，出耳上，下結於頷，上屬目外眥。其病小指支肘內銳骨後廉痛，循臂陰，入腋下，腋下痛，腋後廉痛，繞肩胛引頸而痛，應耳中鳴痛引頷，目瞑良久乃得視，頸筋急，則為筋瘻頸腫，寒熱在頸者。治在燔針劫刺之，以知為數，以痛為輸。其為腫者，復而銳之。本支者，上曲牙，循耳前屬目外眥，上頷結於角，其痛當所過者支轉筋。治在燔鍼劫刺，以知為數，以痛為輸，名曰仲夏痹也。","sortOrder":8},
  {"id":"s_work_hdnk_92_9","chapterId":"ch_work_hdnk_92","text":"手少陽之筋，起於小指次指之端，結於腕，中循臂，結於肘，上繞臑外廉、上肩、走頸，合手太陽；其支者，當曲頰入繫舌本；其支者，上曲牙，循耳前，屬目外眥，上乘頷，結於角。其病當所過者，即支轉筋，舌卷。治在燔針劫刺，以知為數，以痛為輸，名曰季夏痹也。","sortOrder":9},
  {"id":"s_work_hdnk_92_10","chapterId":"ch_work_hdnk_92","text":"手陽明之筋，起於大指次指之端，結於腕，上循臂，上結於肘外，上臑，結於髃；其支者，繞肩胛，挾脊；直者，從肩髃上頸；其支者，上頰，結於頄；直者，上出手太陽之前，上左角，絡頭，下右頷。其病當所過者，支痛及轉筋，肩不舉，頸不可左右視。治在燔針劫刺，以知為數，以痛為輸，名曰孟夏痹也。","sortOrder":10},
  {"id":"s_work_hdnk_92_11","chapterId":"ch_work_hdnk_92","text":"手太陰之筋，起於大指之上，循指上行，結於魚後，行寸口外側，上循臂，結肘中，上臑內廉，入腋下，出缺盆，結肩前髃，上結缺盆，下結胸裏，散貫賁，合賁下抵季脅。其病當所過者，支轉筋，痛甚成息賁，脅急吐血。治在燔針劫刺，以知為數，以痛為輸。名曰仲冬痹也。","sortOrder":11},
  {"id":"s_work_hdnk_92_12","chapterId":"ch_work_hdnk_92","text":"手心主之筋，起於中指，與太陰之筋並行，結於肘內廉，上臂陰，結腋下，下散前後挾脅；其支者，入腋，散胸中，結於臂。其病當所過者，支轉筋前及胸痛息賁。治在燔針劫刺，以知為數，以痛為輸，名曰孟冬痹也。","sortOrder":12},
  {"id":"s_work_hdnk_92_13","chapterId":"ch_work_hdnk_92","text":"手太陰之筋，起於小指之內側，結於銳骨，上結肘內廉，上入腋，交太陰，挾乳裏，結於胸中，循臂下繫於臍。其病內急心承伏梁，下為肘網。其病當所過者，支轉筋，筋痛。治在燔針劫刺，以知為數，以痛為輸。其成伏梁唾血膿者，死不治。經筋之病，寒則反折筋急，熱則筋弛縱不收，陰痿不用。陽急則反折，陰急則俛不伸。焠刺者，刺寒急也，熱則筋縱不收，無用燔針，名曰季冬痹也。","sortOrder":13},
  {"id":"s_work_hdnk_92_14","chapterId":"ch_work_hdnk_92","text":"足之陽明，手之太陽，筋急則口目為僻，眥急不能卒視，治皆如右方也。","sortOrder":14},
  {"id":"s_work_hdnk_93_1","chapterId":"ch_work_hdnk_93","text":"骨度第十四","sortOrder":1},
  {"id":"s_work_hdnk_93_2","chapterId":"ch_work_hdnk_93","text":"黃帝問於伯高曰：脈度言經脈之長短，何以立之？伯高曰：先度其骨節之大小、廣狹、長短，而脈度定矣。","sortOrder":2},
  {"id":"s_work_hdnk_93_3","chapterId":"ch_work_hdnk_93","text":"黃帝曰：願聞眾人之度。人長七尺五寸者，其骨節之大小長短各幾何？伯高曰：頭之大骨圍，二尺六寸，胸圍四尺五寸。腰圍四尺二寸。髮所覆者顱至項，尺二寸。髮以下至頤，長一尺，君子終折。","sortOrder":3},
  {"id":"s_work_hdnk_93_4","chapterId":"ch_work_hdnk_93","text":"結喉以下至缺盆中，長四寸。缺盆以下至〈骨曷〉〈骨虧〉，長九寸，過則肺大，不滿則肺小。〈骨曷〉〈骨虧〉以下至天樞，長八寸，過則胃大，不及則胃小。天樞以下至橫骨，長六寸半，過則迴腸廣長，不滿則狹短。橫骨，長六寸半。橫骨上廉以下至內輔之上廉，長一尺八寸。內輔之上廉以下至下廉，長三寸半。內輔下廉，下至內踝，長一尺三寸。內踝以下至地，長三寸。膝膕以下至附屬，長一尺六寸。附屬以下至地，長三寸。故骨圍大則太過，小則不及。","sortOrder":4},
  {"id":"s_work_hdnk_93_5","chapterId":"ch_work_hdnk_93","text":"角以下至柱骨，長一尺。行腋中不見者，長四寸。腋以下至季脅，長一尺二寸。季脅以下至髀樞，長六寸，髀樞以下至膝中，長一尺九寸。膝以下至外踝，長一尺六寸。外踝以下至京骨，長三寸。京骨以下至地，長一寸。","sortOrder":5},
  {"id":"s_work_hdnk_93_6","chapterId":"ch_work_hdnk_93","text":"耳後當完骨者，廣九寸。耳前當耳門者，廣一尺三寸。兩顴之間，相去七寸。兩乳之間，廣九寸半。兩髀之間，廣六寸半。","sortOrder":6},
  {"id":"s_work_hdnk_93_7","chapterId":"ch_work_hdnk_93","text":"足長一尺二寸，廣四寸半。肩至肘，長一尺七寸；肘至腕，長一尺二寸半。腕至中指本節，長四寸。本節至其末，長四寸半。","sortOrder":7},
  {"id":"s_work_hdnk_93_8","chapterId":"ch_work_hdnk_93","text":"項髮以下至背骨，長二寸半，膂骨以下至尾骶，二十一節，長三尺，上節長一寸四分分之一，奇分在下，故上七節至於膂骨，九寸八分分之七。此眾人骨之度也，所以立經脈之長短也。是故視其經脈之在於身也，其見浮而堅，其見明而大者，多血，細而沉者，多氣也。","sortOrder":8},
  {"id":"s_work_hdnk_94_1","chapterId":"ch_work_hdnk_94","text":"五十營第十五","sortOrder":1},
  {"id":"s_work_hdnk_94_2","chapterId":"ch_work_hdnk_94","text":"黃帝曰：餘願聞五十營奈何？岐伯答曰：天周二十八宿，宿三十六分；人氣行一周，千八分，日行二十八宿。人經脈上下左右前後二十八脈，周身十六丈二尺，以應二十八宿，漏水下百刻，以分晝夜。故人一呼脈再動，氣行三寸，呼吸定息，氣行六寸；十息，氣行六尺，日行二分。二百七十息，氣行十六丈二尺，氣行交通於中，一周於身，下水二刻，日行二十五分。五百四十息，氣行再周於身，下水四刻，日行四十分。二千七百息，氣行十周於身，下水二十刻，日行五宿二十分。一萬三千五百息，氣行五十營於身，水下百刻，日行二十八宿，漏水皆盡脈終矣。所謂交通者，並行一數也。故五十營備，得盡天地之壽矣，凡行八百一十丈也。","sortOrder":2},
  {"id":"s_work_hdnk_95_1","chapterId":"ch_work_hdnk_95","text":"營氣第十六","sortOrder":1},
  {"id":"s_work_hdnk_95_2","chapterId":"ch_work_hdnk_95","text":"黃帝曰：營氣之道，內穀為寶。穀入於胃，乃傳之肺，流溢於中，布散於外，精專者，行於經隧，常營無已，終而復始，是謂天地之紀。故氣從太陰出註手陽明，上行註足陽明，下行至跗上，註大指間，與太陰合；上行抵髀，從脾註心中；循手少陰，出腋中臂，註小指，合手太陽；上行乘腋，出〈出頁〉內，註目內眥，上巔，下項，合足太陽；循脊，下尻，下行註小指之端，循足心，註足少陰；上行註腎，從腎註心外，散於胸中；循心主脈，出腋，下臂，出兩筋之間，入掌中，出中指之端，還註小指次指之端，合手少陽；上行註膻中，散於三焦，從三焦註膽，出脅，註足少陽；下行至跗上，復從跗註大指間，合足厥陰，上行至肝，從肝上註肺，上循喉嚨，入頏顙之竅，究於畜門。其支別者，上額，循巔，下項中，循脊入骶，是督脈也；絡陰器，上過毛中，入臍中，上循腹裏，入缺盆，下註肺中，復出太陰。此營氣之所行也，逆順之常也。","sortOrder":2},
  {"id":"s_work_hdnk_96_1","chapterId":"ch_work_hdnk_96","text":"脈度第十七","sortOrder":1},
  {"id":"s_work_hdnk_96_2","chapterId":"ch_work_hdnk_96","text":"黃帝曰：願聞脈度。岐伯答曰：手之六陽，從手至頭，長五尺，五六三丈。手之六陰，從手至胸中，三尺五寸，三六一丈八尺，五六三尺，合二丈一尺。足之六陽，從足上至頭，八尺，六八四丈八尺。足之六陰，從足至胸中，六尺五寸，六六三丈六尺，五六三尺合三丈九尺。蹻脈從足至目，七尺五寸，二七一丈四尺，二五一尺，合一丈五尺。督脈、任脈，各四尺五寸，二四八尺，二五一尺，合九尺。凡都合一十六丈二尺，此氣之大經隧也。","sortOrder":2},
  {"id":"s_work_hdnk_96_3","chapterId":"ch_work_hdnk_96","text":"經脈為裏，支而橫者為絡，絡之別者為孫，盛而血者疾誅之，盛者瀉之，虛者飲藥以補之。五藏常內閱於上七竅也。故肺氣通於鼻，肺和則鼻能知臭香矣；心氣通於舌，心和則舌能知五味矣；肝氣通於目，肝和則目能辨五色矣；脾氣通於口，脾和則口能知五穀矣；腎氣通於耳，腎和則耳能聞五音矣。五臟不和，則七竅不通；六腑不合則留為癰。故邪在腑則陽脈不和，陽脈不和則氣留之，氣留之則陽氣盛矣。陽氣太盛，則陰不利，陰脈不利則血留之，血留之則陰氣盛矣。陰氣太盛則陽氣不能榮也，故曰關。陽氣太盛，則陰氣弗能榮也，故曰格。陰陽俱盛，不得相榮，故曰關格。關格者，不得盡期而死也。","sortOrder":3},
  {"id":"s_work_hdnk_96_4","chapterId":"ch_work_hdnk_96","text":"黃帝曰：蹻脈安起安止，何氣榮水？岐伯答曰：蹻脈者，少陰之別，起於然骨之後。上內踝之上，直上循陰股，入陰，上循胸裏，入缺盆，上出人迎之前，入頄，屬目內眥，合於太陽，陽蹻而上行，氣併相還，則為濡，目氣不榮，則目不合。","sortOrder":4},
  {"id":"s_work_hdnk_96_5","chapterId":"ch_work_hdnk_96","text":"黃帝曰：氣獨行五臟，不榮六腑，何也？岐伯答曰：氣之不得無行也，如水之流，如日月之行不休，故陰脈榮其臟，陽脈榮其腑，如環之無端，莫知其紀，終而復始，其流溢之氣，內溉臟腑，外濡腠理。","sortOrder":5},
  {"id":"s_work_hdnk_96_6","chapterId":"ch_work_hdnk_96","text":"黃帝曰：蹻脈有陰陽，何脈當其數？岐伯曰：男子數其陽，女子數其陰，當數者為陰，其不當數者為絡也。","sortOrder":6},
  {"id":"s_work_hdnk_97_1","chapterId":"ch_work_hdnk_97","text":"營衛生會第十八","sortOrder":1},
  {"id":"s_work_hdnk_97_2","chapterId":"ch_work_hdnk_97","text":"黃帝問於岐伯曰：人焉受氣？陰陽焉會？何氣為營？何氣為衛？營安從生？衛於焉會？老壯不同氣，陰陽異位，願聞其會。岐伯答曰：人受氣於穀，穀入於胃，以傳與肺，五臟六腑，皆以受氣，其清者為營，濁者為衛，營在脈中，衛在脈外，營週不休，五十度而復大會，陰陽相貫，如環無端，衛氣行於陰二十五度，行於陽二十五度，分為晝夜，故氣至陽而起，至陰而止。故曰日中而陽隴，為重陽，夜半而陰隴為重陰，故太陰主內，太陽主外，各行二十五度分為晝夜。夜半為陰隴，夜半後而為陽衰，平且陰盡而陽受氣矣。日中而陽隴，日西而陽衰，日入陽盡而陰受氣矣。夜半而大會，萬民皆臥，命曰合陰，平旦陰盡而陽受氣，如是無己，與天地同紀。","sortOrder":2},
  {"id":"s_work_hdnk_97_3","chapterId":"ch_work_hdnk_97","text":"黃帝曰：老人之不夜瞑者，何氣使然？少壯之人，不晝瞑者，何氣使然？岐伯答曰：壯者之氣血盛，其肌肉滑，氣道通，營衛之行不失其常，故晝精而夜瞑。老者之氣血衰，其肌肉枯，氣道澀，五臟之氣相博，其營氣衰少而衛氣內伐，故晝不精，夜不瞑。","sortOrder":3},
  {"id":"s_work_hdnk_97_4","chapterId":"ch_work_hdnk_97","text":"黃帝曰：願聞營衛之所行，皆何道從來？岐伯答曰：營出中焦，衛出下焦。黃帝曰：願聞三焦之所出。岐伯答曰：上焦出於胃上口，並咽以上，貫膈，而布胸中，走腋，循太陰之分而行，還至陽明，上至舌，下足陽明，常與營俱行於陽二十五度，行於陰亦二十五度一周也。故五十度而復大會於手太陰矣。","sortOrder":4},
  {"id":"s_work_hdnk_97_5","chapterId":"ch_work_hdnk_97","text":"黃帝曰：人有熱，飲食下胃，其氣未定，汗則出，或出於面，或出於背，或出於身半，其不循衛氣之道而出，何也？岐伯曰：此外傷於風，內開腠理，毛蒸理泄，衛氣走之，固不得循其道，此氣慓悍滑疾，見開而出，故不得從其道，故命曰漏泄。","sortOrder":5},
  {"id":"s_work_hdnk_97_6","chapterId":"ch_work_hdnk_97","text":"黃帝曰：願聞中焦之所出。岐伯答曰：中焦亦並胃中，出上焦之後，此所受氣者，泌糟粕，蒸津液，化其精微，上註於肺脈乃化而為血，以奉生身，莫貴於此，故獨得行於經隧，命曰營氣。","sortOrder":6},
  {"id":"s_work_hdnk_97_7","chapterId":"ch_work_hdnk_97","text":"黃帝曰：夫血之與氣，異名同類。何謂也？岐伯答曰：營衛者，精氣也，血者，神氣也，故血之與氣，異名同類焉。故奪血者無汗，奪汗者無血，故人生有兩死而無兩生。","sortOrder":7},
  {"id":"s_work_hdnk_97_8","chapterId":"ch_work_hdnk_97","text":"黃帝曰：願聞下焦之所出。岐伯答曰：下焦者，別回腸，註於膀胱，而滲入焉；故水穀者，常併居於胃中，成糟粕，而俱下於大腸而成下焦，滲而俱下。濟泌別汁，循下焦而滲入膀胱焉。","sortOrder":8},
  {"id":"s_work_hdnk_97_9","chapterId":"ch_work_hdnk_97","text":"黃帝曰：人飲酒，酒亦入胃，穀未熟，而小便獨先下，何也？岐伯答曰：酒者，熟穀之液也。其氣悍以清，故後穀而入，先穀而液出焉。黃帝曰：善。餘聞上焦如霧，中焦如漚，下焦如瀆，此之謂也。","sortOrder":9},
  {"id":"s_work_hdnk_98_1","chapterId":"ch_work_hdnk_98","text":"四時氣第十九","sortOrder":1},
  {"id":"s_work_hdnk_98_2","chapterId":"ch_work_hdnk_98","text":"黃帝問於岐伯曰：夫四時之氣，各不同形，百病之起，皆有所生，灸刺之道，何者為定？岐伯答曰：四時之氣，各有所在，灸刺之道，得氣穴為定。故春取經、血脈、分肉之間，甚者，深刺之，間者，淺刺之；夏取盛經孫絡，取分間絕皮膚；秋取經俞。邪在腑，取之合；冬取井滎，必深以留之。","sortOrder":2},
  {"id":"s_work_hdnk_98_3","chapterId":"ch_work_hdnk_98","text":"溫瘧汗不出，為五十九痏，風〈疒水〉膚脹，為五十痏。取皮膚之血者，盡取之。飧泄補三陰之上，補陰陵泉，皆久留之，熱行乃止。","sortOrder":3},
  {"id":"s_work_hdnk_98_4","chapterId":"ch_work_hdnk_98","text":"轉筋於陽，治其陽；轉筋於陰，治其陰。皆卒刺之。徒〈疒水〉先取環穀下三寸，以鈹針針之，已刺而筩之，而內之，入而復之，以盡其〈疒水〉，必堅。來緩則煩悗，來急則安靜，間日一刺之，〈疒水〉盡乃止。飲閉藥，方刺之時徒飲之，方飲無食，方食無飲，無食他食，百三十五日。","sortOrder":4},
  {"id":"s_work_hdnk_98_5","chapterId":"ch_work_hdnk_98","text":"著痹不去，久寒不已，卒取其三里。骨為幹。腸中不便，取三里，盛瀉之，虛補之。癘風者，素刺其腫上。已刺，以銳針針其處，按出其惡氣，腫盡乃止。常食方食，無食他食。","sortOrder":5},
  {"id":"s_work_hdnk_98_6","chapterId":"ch_work_hdnk_98","text":"腹中常鳴，氣上衝胸，喘不能久立。邪在大腸，刺肓之原，巨虛上廉、三里。小腹控睪，引腰脊，上衝心。邪在小腸者，連睪系，屬於脊，貫肝肺，絡心系。氣盛則厥逆，上衝腸胃，燻肝，散於肓，結於臍，故取之肓原以散之，刺太陰以予之，取厥陰以下之，取巨虛下廉以去之，按其所過之經以調之。","sortOrder":6},
  {"id":"s_work_hdnk_98_7","chapterId":"ch_work_hdnk_98","text":"善嘔，嘔有苦，長太息，心中憺憺，恐人將捕之；邪在膽，逆在胃，膽液泄，則口苦，胃氣逆，則嘔苦，故曰嘔膽。取三里以下。胃氣逆，則刺少陽血絡，以閉膽逆，卻調其虛實，以去其邪。","sortOrder":7},
  {"id":"s_work_hdnk_98_8","chapterId":"ch_work_hdnk_98","text":"飲食不下，膈塞不通，邪在胃脘，在上脘，則刺抑而下之，在下脘，則散而去之。小腹痛腫，不得小便，邪在三焦，約取之太陽大絡，視其絡脈與厥陰小絡結而血者，腫上及胃脘，取三里。","sortOrder":8},
  {"id":"s_work_hdnk_98_9","chapterId":"ch_work_hdnk_98","text":"睹其色，察其以，知其散復者，視其目色，以知病之存亡也。一其形，聽其動靜者，持氣口人迎以視其脈，堅且盛且滑者，病日進，脈軟者，病將下，諸經實者，病三日已。氣口候陰，人迎候陽也。","sortOrder":9},
  {"id":"s_work_hdnk_99_1","chapterId":"ch_work_hdnk_99","text":"五邪第二十","sortOrder":1},
  {"id":"s_work_hdnk_99_2","chapterId":"ch_work_hdnk_99","text":"邪在肺，則病皮膚痛，寒熱，上氣喘，汗出，欬動肩背。取之膺中外喻，背三節五臟之傍，以手疾按之，快然，乃刺之。取之缺盆中以越之。","sortOrder":2},
  {"id":"s_work_hdnk_99_3","chapterId":"ch_work_hdnk_99","text":"邪在肝，則兩脅中痛，寒中，惡血在內，行善掣節，時腳腫。取之行間，以引脅下，補三里以溫胃中，取血脈以散惡血；取耳間青脈，以去其掣。","sortOrder":3},
  {"id":"s_work_hdnk_99_4","chapterId":"ch_work_hdnk_99","text":"邪在脾胃，則病肌肉痛，陽氣有餘，陰氣不足，則熱中善飢；陽氣不足，陰氣有餘，則寒中腸鳴、腹痛；陰陽俱有餘，若俱不足，則有寒有熱，皆調於三里。","sortOrder":4},
  {"id":"s_work_hdnk_99_5","chapterId":"ch_work_hdnk_99","text":"邪在腎，則病骨痛，陰痹。陰痹者，按之而不得，腹脹，腰痛，大便難，肩背頸項痛，時眩。取之湧泉、崑崙。視有血者，盡取之。","sortOrder":5},
  {"id":"s_work_hdnk_99_6","chapterId":"ch_work_hdnk_99","text":"邪在心，則病心痛，喜悲時眩仆；視有餘不足而調之其輸也。","sortOrder":6},
  {"id":"s_work_hdnk_100_1","chapterId":"ch_work_hdnk_100","text":"寒熱病第二十一","sortOrder":1},
  {"id":"s_work_hdnk_100_2","chapterId":"ch_work_hdnk_100","text":"皮寒熱者，不可附席，毛髮焦，鼻槁臘。不得汗，取三陽之絡，以補手太陰。肌寒熱者，肌痛，毛髮焦而唇槁臘。不得汗，取三陽於下，以去其血者，補足太陰，以出其汗。","sortOrder":2},
  {"id":"s_work_hdnk_100_3","chapterId":"ch_work_hdnk_100","text":"骨寒熱者，病無所安，汗註不休。齒未槁，取其少陰於陰股之絡；齒已槁，死不治。骨厥亦然。骨痹，舉節不用而痛，汗註、煩心。取三陰之經，補之。","sortOrder":3},
  {"id":"s_work_hdnk_100_4","chapterId":"ch_work_hdnk_100","text":"身有所傷，血出多及中風寒，若有所墮墜，四肢懈惰不收，名曰體惰。取其小腹臍下三結交。三結交者，陽明太陰也，臍下三寸關元也。厥痹者，厥氣上及腹。取陰陽之絡，視主病也，瀉陽補陰經也。","sortOrder":4},
  {"id":"s_work_hdnk_100_5","chapterId":"ch_work_hdnk_100","text":"頸側之動脈人迎。人迎，足陽明也，在嬰筋之前。嬰筋之後，手陽明也，名曰扶突。次脈，足少陽脈也，名曰天牖。次脈，足太陽也，名曰天柱。腋下動脈，臂太陰也，名曰天府。","sortOrder":5},
  {"id":"s_work_hdnk_100_6","chapterId":"ch_work_hdnk_100","text":"陽迎頭痛，胸滿不得息，取之人迎。暴瘖氣鞭，取扶突與舌本出血。暴襲氣蒙，耳目不明，取天牖。暴攣癎眩，足不任身，取天柱。暴痹內逆，肝肺相搏，血溢鼻口，取天府。此為天牖五部。","sortOrder":6},
  {"id":"s_work_hdnk_100_7","chapterId":"ch_work_hdnk_100","text":"臂陽明，有入頄遍齒者，名曰大迎。下齒齲，取之臂。惡寒補之，不惡寒瀉之。足太陽有入頄遍齒者，名曰角孫。上齒齲，取之在鼻與頄前。方病之時，其脈盛，盛則瀉之，虛則補之。一曰取之出鼻外。","sortOrder":7},
  {"id":"s_work_hdnk_100_8","chapterId":"ch_work_hdnk_100","text":"足陽明有挾鼻入於面者，名曰懸顱。屬口，對入繫目本，視有過者取之。損有餘，益不足，反者益其。足太陽有通項入於腦者，正屬目本，名曰眼系。頭目苦痛，取之在項中兩筋間。入腦乃別陰蹻、陽蹻，陰陽相交，陽入陰，陰出陽，交於目銳眥，陽氣盛則瞋目，陰氣盛則瞑目。","sortOrder":8},
  {"id":"s_work_hdnk_100_9","chapterId":"ch_work_hdnk_100","text":"熱厥取足太陰、少陽，皆留之；寒厥取足陽明、少陰於足，皆留之。舌縱涎下，煩悗，取足少陰。振寒洒洒鼓頷，不得汗出，腹脹煩悗，取手太陰，刺虛者，刺其去也；刺實者，刺其來也。","sortOrder":9},
  {"id":"s_work_hdnk_100_10","chapterId":"ch_work_hdnk_100","text":"春取絡脈，夏取分腠，秋取氣口，冬取經輸。凡此四時，各以時為齊。絡脈治皮膚，分腠治肌肉，氣口治筋脈，經輸治骨髓。五臟，身有五部：伏兔一；腓二，腓者腨也；背三，五臟之輸四；項五。此五部有癰疽者死。","sortOrder":10},
  {"id":"s_work_hdnk_100_11","chapterId":"ch_work_hdnk_100","text":"病始手臂者，先取手陽明、太陰而汗出；病始頭首者，先取項太陽而汗出；病始足脛者，先取足陽明而汗出。臂太陰可汗出，足陽明可汗出，故取陰而汗出甚者，止之於陽，取陽而汗出甚者，止之於陰。","sortOrder":11},
  {"id":"s_work_hdnk_100_12","chapterId":"ch_work_hdnk_100","text":"凡刺之害，中而不去則精泄；不中而去則致氣。精泄則病甚而慪，致氣則生為癰疽也。","sortOrder":12},
  {"id":"s_work_hdnk_101_1","chapterId":"ch_work_hdnk_101","text":"癩狂病第二十二","sortOrder":1},
  {"id":"s_work_hdnk_101_2","chapterId":"ch_work_hdnk_101","text":"目眥外決於面者，為銳眥；在內近鼻者，為內眥；上為外眥，下為內眥。","sortOrder":2},
  {"id":"s_work_hdnk_101_3","chapterId":"ch_work_hdnk_101","text":"癲疾始生，先不樂，頭重痛，視舉目赤，甚作極，已而煩心。候之於顏。取手太陽、陽明、太陰，血變為止。","sortOrder":3},
  {"id":"s_work_hdnk_101_4","chapterId":"ch_work_hdnk_101","text":"癲疾始作，而引口啼呼喘悸者，候之手陽明、太陽。左強者，攻其右；右強者，攻其左，血變為止。癲疾始作，先反僵，因而脊痛，候之足太陽、陽明、太陰、手太陽，血變為止。","sortOrder":4},
  {"id":"s_work_hdnk_101_5","chapterId":"ch_work_hdnk_101","text":"治癲疾者，常與之居，察其所當取之處。病至，視之有過者瀉之，置其血於瓠壺之中，至其發時，血獨動矣，不動，灸窮骨二十壯。窮骨者，骶骨也。","sortOrder":5},
  {"id":"s_work_hdnk_101_6","chapterId":"ch_work_hdnk_101","text":"骨癲疾者，顑、齒諸腧、分肉皆滿而骨居，汗出、煩悗，嘔多沃沫，氣下泄，不治。","sortOrder":6},
  {"id":"s_work_hdnk_101_7","chapterId":"ch_work_hdnk_101","text":"筋癲疾者，身倦攣急大，刺項大經之大杼脈，嘔多沃沫，氣下泄，不治。","sortOrder":7},
  {"id":"s_work_hdnk_101_8","chapterId":"ch_work_hdnk_101","text":"脈癲疾者，暴仆，四肢之脈皆脹而縱，脈滿，盡刺之出血，不滿，灸之項太陽，灸帶脈於腰相去三寸，諸分肉本輸。嘔吐沃沫，氣下泄，不治。癲疾者，疾發如狂者，死不治。","sortOrder":8},
  {"id":"s_work_hdnk_101_9","chapterId":"ch_work_hdnk_101","text":"狂始生，先自悲也，喜忘、苦怒、善恐者得之憂飢，治之取手太陽、陽明，血變而止，及取足太陰、陽明。狂始發，少臥不飢，自高賢也，自辯智也，自尊貴也，善罵詈，日夜不休，治之取手陽明太陽太陰舌下少陰，視之盛者，皆取之，不盛，釋之也。","sortOrder":9},
  {"id":"s_work_hdnk_101_10","chapterId":"ch_work_hdnk_101","text":"狂言，驚，善笑，好歌樂，妄行不休者，得之大恐，治之取手陽明太陽太陰。狂，目妄見，耳妄聞，善呼者，少氣之所生也；治之取手太陽太陰陽明，足太陰頭兩顑。","sortOrder":10},
  {"id":"s_work_hdnk_101_11","chapterId":"ch_work_hdnk_101","text":"狂者多食，善見鬼神，善笑而不發於外者，得之有所大喜，治之取足太陰太陽陽明，後取手太陰太陽陽明。狂而新發，未應如此者，先取曲泉左右動脈，及盛者見血，有頃已，不已，以法取之，灸骨骶二十壯。","sortOrder":11},
  {"id":"s_work_hdnk_101_12","chapterId":"ch_work_hdnk_101","text":"風逆，暴四肢腫，身漯漯，唏然時寒，飢則煩，飽則善變，取手太表裏，足少陰陽明之徑，肉清取滎，骨清取井、經也。","sortOrder":12},
  {"id":"s_work_hdnk_101_13","chapterId":"ch_work_hdnk_101","text":"厥逆為病也，足暴清，胸若將裂，腸若將以刀切之，煩而不能食，脈大小皆澀，暖取足少陰，清取足陽明，清則補之，溫則瀉之。厥逆腹脹滿，腸鳴，胸滿不得息，取之下胸二脅，咳而動手者，與背輸，以手按之，立快者是也。","sortOrder":13},
  {"id":"s_work_hdnk_101_14","chapterId":"ch_work_hdnk_101","text":"內閉不得溲，刺足少陰太陽，與抵上以長針。氣逆，則取其太陰、陽明、厥陰，甚取少陰、陽明，動者之經也。","sortOrder":14},
  {"id":"s_work_hdnk_101_15","chapterId":"ch_work_hdnk_101","text":"少氣，身漯漯也，言吸吸也，骨痠體重，懈惰不能動，補足少陰。短氣息短，不屬，動作氣索，補足少陰，去血絡也。","sortOrder":15},
  {"id":"s_work_hdnk_102_1","chapterId":"ch_work_hdnk_102","text":"熱病第二十三","sortOrder":1},
  {"id":"s_work_hdnk_102_2","chapterId":"ch_work_hdnk_102","text":"偏枯，身偏不用而痛，言不變，志不亂，病在分腠之間，巨針取之，益其不足，損其有餘，乃可復也。","sortOrder":2},
  {"id":"s_work_hdnk_102_3","chapterId":"ch_work_hdnk_102","text":"痱之為病也，身無痛者，四肢不收；智亂不甚，其言微知，可治；甚則不能言，不可治也。病先起於陽，復入於陰者，先取其陽，後取其陰，浮而取之。","sortOrder":3},
  {"id":"s_work_hdnk_102_4","chapterId":"ch_work_hdnk_102","text":"熱病三日，而氣口靜、人迎躁者，取之諸陽，五十九刺，以瀉其熱，而出其汗，實其陰，以補其不足者。身熱甚，陰陽皆靜者，勿刺也；其可刺者，急取之，不汗出則泄。所謂勿刺者，有死徵也。","sortOrder":4},
  {"id":"s_work_hdnk_102_5","chapterId":"ch_work_hdnk_102","text":"熱病七日八日，脈口動，喘而短者，急刺之，汗且自出，淺刺手大指間。","sortOrder":5},
  {"id":"s_work_hdnk_102_6","chapterId":"ch_work_hdnk_102","text":"熱病七日八日，脈微小，病者溲血，口中乾，一日半而死。脈代者，一日死。","sortOrder":6},
  {"id":"s_work_hdnk_102_7","chapterId":"ch_work_hdnk_102","text":"熱病已得汗出，而脈尚躁，喘且復熱，勿刺膚，喘甚者死。","sortOrder":7},
  {"id":"s_work_hdnk_102_8","chapterId":"ch_work_hdnk_102","text":"熱病七日八日，脈不躁，躁不散改，後看中有汗；三日不汗，四日死。未曾汗者，勿腠刺之。","sortOrder":8},
  {"id":"s_work_hdnk_102_9","chapterId":"ch_work_hdnk_102","text":"熱病先膚痛，窒鼻充面，取之皮，以第一針，五十九，苛軫鼻，索皮於肺，不得，索之火，火者，心也。","sortOrder":9},
  {"id":"s_work_hdnk_102_10","chapterId":"ch_work_hdnk_102","text":"熱病先身澀倚而熱，煩俛，乾唇口溢，取之皮，以第一針，五十九；膚脹口乾，寒汗出，索脈於心，不得，索之水，水者，腎也。","sortOrder":10},
  {"id":"s_work_hdnk_102_11","chapterId":"ch_work_hdnk_102","text":"熱病溢乾多飲，善驚，臥不能起，取之膚肉，以第六針，五十九，目眥青，索肉於脾，不得，索之水，木者，肝也。","sortOrder":11},
  {"id":"s_work_hdnk_102_12","chapterId":"ch_work_hdnk_102","text":"熱病面青，腦痛，手足躁，取之筋間，以第四針於四逆；筋躄目浸，索筋於肝，不得，索之金，金者，肺也。","sortOrder":12},
  {"id":"s_work_hdnk_102_13","chapterId":"ch_work_hdnk_102","text":"熱病數驚，瘈瘲而狂，取之脈，以第四針，急瀉有餘者，癲疾毛發去，索血於心，不得，索之水，水者，腎也。","sortOrder":13},
  {"id":"s_work_hdnk_102_14","chapterId":"ch_work_hdnk_102","text":"熱病身重骨痛，耳聾而好瞑，取之骨，以第四針，五十九，刺骨；病不食，齧齒耳青，索骨於腎，不得，索之土，土者，脾也。","sortOrder":14},
  {"id":"s_work_hdnk_102_15","chapterId":"ch_work_hdnk_102","text":"熱病不知所痛，耳聾，不能自收，口乾，陽熱甚，陰頗有寒者，熱在髓，死不可治。","sortOrder":15},
  {"id":"s_work_hdnk_102_16","chapterId":"ch_work_hdnk_102","text":"熱病頭痛，顳顬，目〈疒挈〉脈痛，善衄，厥熱病也，取之以第三針，視有餘不足，寒熱痔。","sortOrder":16},
  {"id":"s_work_hdnk_102_17","chapterId":"ch_work_hdnk_102","text":"熱病，體重，腸中熱，取之以第四針，於其俞，及下諸趾間，索氣於胃胳（應作絡）得氣也。","sortOrder":17},
  {"id":"s_work_hdnk_102_18","chapterId":"ch_work_hdnk_102","text":"熱病挾臍急痛，胸脅滿，取之涌泉與陰陵泉，取以第四針，針嗌里。","sortOrder":18},
  {"id":"s_work_hdnk_102_19","chapterId":"ch_work_hdnk_102","text":"熱病，而汗且出，及脈順可汗者，取之魚際、太淵、大都、太白。瀉之則熱去，補之則汗出，汗出大甚，取內踝上橫脈以止之。","sortOrder":19},
  {"id":"s_work_hdnk_102_20","chapterId":"ch_work_hdnk_102","text":"熱病已得汗而脈尚躁盛，此陰脈之極也，死；其得汗而脈靜者，生。","sortOrder":20},
  {"id":"s_work_hdnk_102_21","chapterId":"ch_work_hdnk_102","text":"熱病者，脈尚盛躁而不得汗者，此陽脈之極也，死；脈盛躁得汗靜者，生。","sortOrder":21},
  {"id":"s_work_hdnk_102_22","chapterId":"ch_work_hdnk_102","text":"熱病不可刺者有九：一曰：汗不出，大顴發赤穢者死；二曰：泄而腹滿甚者死；三曰：目不明，熱不已者死；四曰：老人嬰兒熱而腹滿者死；五曰：汗不出嘔下血者死；六曰：舌本爛，熱不已者死；七曰：咳而衄，汗不出，出不至足者死；八曰：髓熱者死；九曰：熱而痙者死。腰折，病病，齒噤也。凡此九者，不可刺也。","sortOrder":22},
  {"id":"s_work_hdnk_102_23","chapterId":"ch_work_hdnk_102","text":"所謂五十九刺者，兩手外內側各三，凡十二痏。五指間各一，凡八痏，足亦如是。頭入髮一寸旁三分各三，凡六痏。更入髮三寸邊五，凡十痏。耳前後口下者各一，項中一，凡六痏。巔上一，聰會一，髮際一，廉泉一，風池二，天柱二。","sortOrder":23},
  {"id":"s_work_hdnk_102_24","chapterId":"ch_work_hdnk_102","text":"氣滿胸中喘息，取足太陰大趾之端，去爪甲如薤葉，寒則留之，熱則疾之，氣下乃止。","sortOrder":24},
  {"id":"s_work_hdnk_102_25","chapterId":"ch_work_hdnk_102","text":"心疝暴痛，取足太陰厥陰，盡刺去其血絡。","sortOrder":25},
  {"id":"s_work_hdnk_102_26","chapterId":"ch_work_hdnk_102","text":"喉痺舌卷，口中乾，煩心，心痛，臂內廉痛，不可及頭，取手小指次指爪甲下，去端如韭葉。","sortOrder":26},
  {"id":"s_work_hdnk_102_27","chapterId":"ch_work_hdnk_102","text":"目中赤痛，從內眥始，取之陰蹻。","sortOrder":27},
  {"id":"s_work_hdnk_102_28","chapterId":"ch_work_hdnk_102","text":"風痙身反折，先取足太陽及膕中及血絡出血，中有寒，取三里。","sortOrder":28},
  {"id":"s_work_hdnk_102_29","chapterId":"ch_work_hdnk_102","text":"癃，取之陰蹻及三毛上及血絡出血。","sortOrder":29},
  {"id":"s_work_hdnk_102_30","chapterId":"ch_work_hdnk_102","text":"男子如蠱，女子如怚，身體腰脊如解，不欲飲食，先取涌泉見血，視跗上盛者，盡見血也。","sortOrder":30},
  {"id":"s_work_hdnk_103_1","chapterId":"ch_work_hdnk_103","text":"厥病第二十四","sortOrder":1},
  {"id":"s_work_hdnk_103_2","chapterId":"ch_work_hdnk_103","text":"厥頭痛，面若腫起而煩心，取之足陽明太陰。厥頭痛，頭脈痛，心悲，善泣，視頭動脈反盛者，刺盡去血，後調足厥陰。","sortOrder":2},
  {"id":"s_work_hdnk_103_3","chapterId":"ch_work_hdnk_103","text":"厥頭痛，貞貞頭重而痛，寫頭上五行，行五，先取手少陰，後取足少陰。厥頭痛，意善忘，按之不得，取頭面左右動脈，後取足太陰。","sortOrder":3},
  {"id":"s_work_hdnk_103_4","chapterId":"ch_work_hdnk_103","text":"厥頭痛，項先痛，腰脊為應，先取天柱，後取足太陽。厥頭痛，頭痛甚，耳前後脈湧有熱，瀉出其血，後取足少陽。","sortOrder":4},
  {"id":"s_work_hdnk_103_5","chapterId":"ch_work_hdnk_103","text":"真頭痛，頭痛甚，腦盡痛，手足寒至節，死不治。","sortOrder":5},
  {"id":"s_work_hdnk_103_6","chapterId":"ch_work_hdnk_103","text":"頭痛不可取於腧者，有所擊墮，惡血在於內，若肉傷，痛未已，可則刺，不可遠取也。頭痛不可刺者，大痺為惡，日作者，可令少愈，不可已。頭半寒痛，先取手少陽陽明，後取足少陽陽明。","sortOrder":6},
  {"id":"s_work_hdnk_103_7","chapterId":"ch_work_hdnk_103","text":"厥心痛，與背相控，善瘈，如從後觸其心，傴僂者，腎心痛也，先取京骨、崑崙，發狂不已，取然穀。厥心痛，腹脹胸滿，心尤痛甚，胃心痛也，取之大都、大白。","sortOrder":7},
  {"id":"s_work_hdnk_103_8","chapterId":"ch_work_hdnk_103","text":"厥心痛，痛如以錐針刺其心，心痛甚者，脾心痛也，取之然穀、太谿。","sortOrder":8},
  {"id":"s_work_hdnk_103_9","chapterId":"ch_work_hdnk_103","text":"厥心痛，色蒼蒼如死狀，終日不得太息，肝心痛也，取之行間、太衝。","sortOrder":9},
  {"id":"s_work_hdnk_103_10","chapterId":"ch_work_hdnk_103","text":"厥心痛，臥若徒居，心痛間，動作，痛益甚，色不變，肺心痛也，取之魚際、太淵。","sortOrder":10},
  {"id":"s_work_hdnk_103_11","chapterId":"ch_work_hdnk_103","text":"真心痛，手足清至節，心痛甚，日發夕死，夕發旦死。心痛不可刺者，中有盛聚，不可取於腧。","sortOrder":11},
  {"id":"s_work_hdnk_103_12","chapterId":"ch_work_hdnk_103","text":"腸中有蟲瘕及蛟蛕，皆不可取以小鍼；心腸痛，憹作痛，腫聚，往來上下行，痛有休止，腹熱喜渴涎出者，是蛟蛕也。以手聚按而堅持之，無令得移，以大針刺之，久持之，蟲不動，乃出針也。恐腹濃痛，形中上者。","sortOrder":12},
  {"id":"s_work_hdnk_103_13","chapterId":"ch_work_hdnk_103","text":"耳聾無聞，取耳中；耳鳴，取耳前動脈；耳痛不可刺者，耳中有膿，若有乾聆聊，耳無聞也；耳聾取手小指次指爪甲上與肉交者，先取手，後取足；耳鳴取手中指爪甲上，左取右，右取左，先取手，後取足。","sortOrder":13},
  {"id":"s_work_hdnk_103_14","chapterId":"ch_work_hdnk_103","text":"足髀不可舉，側而取之，在樞合中，以員利針，大針不可刺。病註下血，取曲泉。","sortOrder":14},
  {"id":"s_work_hdnk_103_15","chapterId":"ch_work_hdnk_103","text":"風痺淫礫，病不可已者，足如履冰，時如入湯中，股脛淫礫，煩心頭痛，時嘔時悗，眩已汗出，久則目眩，悲以喜恐，短氣，不樂，不出三年死也。","sortOrder":15},
  {"id":"s_work_hdnk_104_1","chapterId":"ch_work_hdnk_104","text":"病本第二十五","sortOrder":1},
  {"id":"s_work_hdnk_104_2","chapterId":"ch_work_hdnk_104","text":"先病而後逆者，治其本；先逆而後病者，治其本；先寒而後生病者，治其本；先病而後生寒者，治其本；先熱而後生病者，治其本。","sortOrder":2},
  {"id":"s_work_hdnk_104_3","chapterId":"ch_work_hdnk_104","text":"先泄而後生他病者，治其本，必且調之，乃治其他病。先病而後中滿者，治其標；先病後泄者，治其本；先中滿而後煩心者，治其本。","sortOrder":3},
  {"id":"s_work_hdnk_104_4","chapterId":"ch_work_hdnk_104","text":"有客氣，有同氣。大小便不利治其標，大小便利，治其本。","sortOrder":4},
  {"id":"s_work_hdnk_104_5","chapterId":"ch_work_hdnk_104","text":"病發而有餘，本而標之，先治其本，後治其標；病發而不足，標而本之，先治其標，後治其本，謹詳察間甚，以意調之，間者並行，甚為獨行；先小大便不利而後生他病者，治其本也。","sortOrder":5},
  {"id":"s_work_hdnk_105_1","chapterId":"ch_work_hdnk_105","text":"雜病第二十六","sortOrder":1},
  {"id":"s_work_hdnk_105_2","chapterId":"ch_work_hdnk_105","text":"厥挾脊而痛者，至頂，頭沉沉然，目〈流，氵改目〉〈流，氵改目〉然，腰脊強。取足太陽膕中血絡。","sortOrder":2},
  {"id":"s_work_hdnk_105_3","chapterId":"ch_work_hdnk_105","text":"厥胸滿面腫，唇漯漯然，暴言難，甚則不能言，取足陽明。","sortOrder":3},
  {"id":"s_work_hdnk_105_4","chapterId":"ch_work_hdnk_105","text":"厥氣走喉而不能言，手足清，大便不利，取足少陰。","sortOrder":4},
  {"id":"s_work_hdnk_105_5","chapterId":"ch_work_hdnk_105","text":"厥而腹嚮嚮然，多寒氣，腹中穀穀，便溲難，取足太陰。","sortOrder":5},
  {"id":"s_work_hdnk_105_6","chapterId":"ch_work_hdnk_105","text":"嗌乾，口中熱如膠，取足少陰。","sortOrder":6},
  {"id":"s_work_hdnk_105_7","chapterId":"ch_work_hdnk_105","text":"膝中痛，取犢鼻，以員利針，發而間之。針大如氂，刺膝無疑。","sortOrder":7},
  {"id":"s_work_hdnk_105_8","chapterId":"ch_work_hdnk_105","text":"喉痺不能言，取足陽明；能言，取手陽明。","sortOrder":8},
  {"id":"s_work_hdnk_105_9","chapterId":"ch_work_hdnk_105","text":"瘧不渴，間日而作，取足陽明；渴而日作，取手陽明。","sortOrder":9},
  {"id":"s_work_hdnk_105_10","chapterId":"ch_work_hdnk_105","text":"齒痛，不惡清飲，取足陽明；惡清飲，取手陽明。","sortOrder":10},
  {"id":"s_work_hdnk_105_11","chapterId":"ch_work_hdnk_105","text":"聾而不痛者，取足少陽；聾而痛者，取手陽明。","sortOrder":11},
  {"id":"s_work_hdnk_105_12","chapterId":"ch_work_hdnk_105","text":"衄而不止，衄血流，取足太陽；衄血，取手太陽。不已，刺宛骨下；不已，刺膕中出血。","sortOrder":12},
  {"id":"s_work_hdnk_105_13","chapterId":"ch_work_hdnk_105","text":"腰痛，痛上寒，取足太陽陽明；痛上熱，取足厥陰；不可以俛仰，取足少陽。中熱而喘，取足少陰膕中血絡。","sortOrder":13},
  {"id":"s_work_hdnk_105_14","chapterId":"ch_work_hdnk_105","text":"喜怒而不欲食，言益小，刺足太陰；怒而多言，刺足少陽。","sortOrder":14},
  {"id":"s_work_hdnk_105_15","chapterId":"ch_work_hdnk_105","text":"顑痛，刺手陽明與顑之盛脈出血。","sortOrder":15},
  {"id":"s_work_hdnk_105_16","chapterId":"ch_work_hdnk_105","text":"項痛不可俛仰，刺足太陽；不可以顧，刺手太陽也。","sortOrder":16},
  {"id":"s_work_hdnk_105_17","chapterId":"ch_work_hdnk_105","text":"小腹滿大，上走胃，至心，淅淅身時寒熱，小便不利，取足厥陰。","sortOrder":17},
  {"id":"s_work_hdnk_105_18","chapterId":"ch_work_hdnk_105","text":"腹滿，大便不利，腹大，亦上走胸嗌，喘息喝喝然，取足少陰。","sortOrder":18},
  {"id":"s_work_hdnk_105_19","chapterId":"ch_work_hdnk_105","text":"腹滿食不化，腹嚮嚮然，不能大便，取足太陰。","sortOrder":19},
  {"id":"s_work_hdnk_105_20","chapterId":"ch_work_hdnk_105","text":"心痛引腰脊，欲嘔，取足少陰。","sortOrder":20},
  {"id":"s_work_hdnk_105_21","chapterId":"ch_work_hdnk_105","text":"心痛，腹脹，牆牆然，大便不利，取足太陰。","sortOrder":21},
  {"id":"s_work_hdnk_105_22","chapterId":"ch_work_hdnk_105","text":"心痛，引背不得息，刺足少陰；不已，取手少陽。","sortOrder":22},
  {"id":"s_work_hdnk_105_23","chapterId":"ch_work_hdnk_105","text":"心痛引小腹滿，上下無常處，便溲難，刺足厥陰。","sortOrder":23},
  {"id":"s_work_hdnk_105_24","chapterId":"ch_work_hdnk_105","text":"心痛，但短氣不足以息，刺手太陰。","sortOrder":24},
  {"id":"s_work_hdnk_105_25","chapterId":"ch_work_hdnk_105","text":"心痛，當九節刺之，按，已刺按之，立已；不已，上下求之，得之立已。","sortOrder":25},
  {"id":"s_work_hdnk_105_26","chapterId":"ch_work_hdnk_105","text":"顑痛，刺足陽明曲周動脈，見血，立已；不已，按人迎於經，立已。","sortOrder":26},
  {"id":"s_work_hdnk_105_27","chapterId":"ch_work_hdnk_105","text":"氣逆上，刺膺中陷者，與下胸動脈。","sortOrder":27},
  {"id":"s_work_hdnk_105_28","chapterId":"ch_work_hdnk_105","text":"腹痛，刺臍左右動脈，已刺按之，立已；不已，刺氣街，已刺按之，立已。","sortOrder":28},
  {"id":"s_work_hdnk_105_29","chapterId":"ch_work_hdnk_105","text":"痿厥為四末束悗，乃疾解之，日二；不仁者，十日而知，無休，病已止。","sortOrder":29},
  {"id":"s_work_hdnk_105_30","chapterId":"ch_work_hdnk_105","text":"歲以草刺鼻，嚏，嚏而已；無息，而疾迎引之，立已；大驚之，亦可已。","sortOrder":30},
  {"id":"s_work_hdnk_106_1","chapterId":"ch_work_hdnk_106","text":"周痺第二十七","sortOrder":1},
  {"id":"s_work_hdnk_106_2","chapterId":"ch_work_hdnk_106","text":"黃帝問於岐伯曰：周痺之在身也，上下移徒隨脈，其上下左右相應，間不容空，願聞此痛，在血脈之中邪？將在分肉之間乎？何以致是？其痛之移也，間不及下針，其慉痛之時，不及定治，而痛已止矣。何道使然？願聞其故？岐伯答曰：此眾痺也，非周痺也。","sortOrder":2},
  {"id":"s_work_hdnk_106_3","chapterId":"ch_work_hdnk_106","text":"黃帝曰：願聞眾痺。岐伯對曰：此各在其處，更發更止，更居更起，以右應左，以左應右，非能周也。更發更休也。黃帝曰：善。刺之奈何？岐伯對曰：刺此者，痛雖已止，必刺其處，勿令復起。","sortOrder":3},
  {"id":"s_work_hdnk_106_4","chapterId":"ch_work_hdnk_106","text":"帝曰：善。願聞周痺何如？岐伯對曰：周痺者，在於血脈之中，隨脈以上，隨脈以下，不能左右，各當其所。黃帝曰：刺之奈何？岐伯對曰：痛從上下者，先刺其下以過之，後刺其上以脫之。痛從下上者，先刺其上以過之，後刺其下以脫之。","sortOrder":4},
  {"id":"s_work_hdnk_106_5","chapterId":"ch_work_hdnk_106","text":"黃帝曰：善。此痛安生？何因而有名？岐伯對曰：風寒濕氣，客於外分肉之間，迫切而為沫，沫得寒則聚，聚則排分肉而分裂也，分裂則痛，痛則神歸之，神歸之則熱，熱則痛解，痛解則厥，厥則他痺發，發則如是。帝曰：善。餘已得其意矣。此內不在臟，而外未發於皮，獨居分肉之間，真氣不能周，故名曰周痺。故刺痺者，必先切循其下之六經，視其虛實，及大絡之血結而不通，及虛而脈陷空者而調之，熨而通之。其瘈堅轉引而行之。黃帝曰：善。餘已得其意矣，亦得其事也。九者經巽之理，十二經脈陰陽之病也。","sortOrder":5},
  {"id":"s_work_hdnk_107_1","chapterId":"ch_work_hdnk_107","text":"口問第二十八","sortOrder":1},
  {"id":"s_work_hdnk_107_2","chapterId":"ch_work_hdnk_107","text":"黃帝閒居，辟左右而問於岐伯曰：餘已聞九針之經，論陰陽逆順，六經已畢，願得口問。岐伯避席再拜曰：善乎哉問也，此先師之所口傳也。黃帝曰：願聞口傳。岐伯答曰：夫百病之始生也，皆生於風雨寒暑，陰陽喜怒，飲食居處，大驚卒恐。則血氣分離，陰陽破敗，經絡厥絕，脈道不通，陰陽相逆，衛氣稽留，經脈虛空，血氣不次，乃失其常。論不在經者，請道其方。","sortOrder":2},
  {"id":"s_work_hdnk_107_3","chapterId":"ch_work_hdnk_107","text":"黃帝曰：人之欠者，何氣使然？岐伯答曰：衛氣晝日行於陽，夜半則行於陰，陰者主夜，夜者臥；陽者主上，陰者主下；故陰氣積於下，陽氣未盡，陽引而上，陰引而下，陰陽相引，故數欠。陽氣盡，陰氣盛，則目瞑；陰氣盡而陽氣盛，則寤矣。瀉足少陰，補足太陽。","sortOrder":3},
  {"id":"s_work_hdnk_107_4","chapterId":"ch_work_hdnk_107","text":"黃帝曰：人之噦者，何氣使然？岐伯曰：穀入於胃，胃氣上註於肺。今有故寒氣與新穀氣，俱還入於胃，新故相亂，真邪相攻，氣並相逆，復出於胃，故為噦。補手太陰，瀉足少陰。","sortOrder":4},
  {"id":"s_work_hdnk_107_5","chapterId":"ch_work_hdnk_107","text":"黃帝曰：人之唏者，何氣使然？岐伯曰：此陰氣盛而陽氣虛，陰氣疾而陽氣徐，陰氣盛而陽氣絕，故為唏。補足太陽，瀉足少陰。","sortOrder":5},
  {"id":"s_work_hdnk_107_6","chapterId":"ch_work_hdnk_107","text":"黃帝曰：人之振寒者，何氣使然？岐伯曰：寒氣客於皮膚，陰氣盛，陽氣虛，故為振寒寒慄，補諸陽。","sortOrder":6},
  {"id":"s_work_hdnk_107_7","chapterId":"ch_work_hdnk_107","text":"黃帝曰：人之噫者，何氣使然？岐伯曰：寒氣客於胃，厥逆從下上散，復出於胃，故為噫。補足太陰陽明，一曰補眉本也。","sortOrder":7},
  {"id":"s_work_hdnk_107_8","chapterId":"ch_work_hdnk_107","text":"黃帝曰：人之嚏者，何氣使然？岐伯曰：陽氣和利，滿於心，出於鼻，故為嚏。補足太陽榮眉本，一曰眉上也。","sortOrder":8},
  {"id":"s_work_hdnk_107_9","chapterId":"ch_work_hdnk_107","text":"黃帝曰：人之嚲者，何氣使然？岐伯曰：胃不實則諸脈虛；諸脈虛則筋脈懈惰；筋脈懈惰則行陰用力，氣不能復，故為嚲。因其所在，補分肉間。","sortOrder":9},
  {"id":"s_work_hdnk_107_10","chapterId":"ch_work_hdnk_107","text":"黃帝曰：人之哀而泣涕出者，何氣使然？岐伯曰：心者，五臟六腑之主也；目者，宗脈之所聚也，上液之道也；口鼻者，氣之門戶也。故悲哀愁憂則心動，心動則五臟六腑皆搖，搖則宗脈感，宗脈感則液道開，液道開，故泣涕出焉。液者，所以灌精濡空竅者也，故上液之道開則泣，泣不止則液竭；液竭則精不灌，精不灌則目無所見矣，故命曰奪精。補天柱經俠頸。","sortOrder":10},
  {"id":"s_work_hdnk_107_11","chapterId":"ch_work_hdnk_107","text":"黃帝曰：人之太息者，何氣使然？岐伯曰：憂思則心系急，心系急則氣道約，約則不利，故太息以伸出之，補手少陰心主，足少陽留之也。","sortOrder":11},
  {"id":"s_work_hdnk_107_12","chapterId":"ch_work_hdnk_107","text":"黃帝曰：人之涎下者，何氣使然？岐伯曰：飲食者，皆入於胃，胃中有熱則蟲動，蟲動則胃緩，胃緩則廉泉開，故涎下，補足少陰。","sortOrder":12},
  {"id":"s_work_hdnk_107_13","chapterId":"ch_work_hdnk_107","text":"黃帝曰：人之耳中鳴者，何氣使然？岐伯曰：耳者，宗脈之所聚也，故胃中空則宗脈虛，虛則下溜，脈有所竭者，故耳鳴，補客主人，手大指爪甲上與肉交者也。","sortOrder":13},
  {"id":"s_work_hdnk_107_14","chapterId":"ch_work_hdnk_107","text":"黃帝曰：人之自嚙舌者，何氣使然？岐伯曰：此厥逆走上，脈氣輩至也。少陰氣至則嚙舌，少陽氣至則嚙頰，陽明氣至則嚙唇矣。視主病者，則補之。","sortOrder":14},
  {"id":"s_work_hdnk_107_15","chapterId":"ch_work_hdnk_107","text":"凡此十二邪者，皆奇邪之走空竅者也。故邪之所在，皆為不足。故上氣不足，腦為之不滿，耳為之苦鳴，頭為之苦傾，目為之眩。中氣不足，溲便為之變，腸為之苦鳴。下氣不足，則乃為痿厥心悗。補足外踝下留之。","sortOrder":15},
  {"id":"s_work_hdnk_107_16","chapterId":"ch_work_hdnk_107","text":"黃帝曰：治之奈何？岐伯曰：腎主為欠，取足少陰；肺主為噦，取手太陰、足少陰；唏者，陰與陽絕，故補足太陽，瀉足少陰；振寒者，補諸陽；噫者，補足太陰陽明；嚏者，補足太陽眉本；嚲，因其所在，補分肉間；泣出補天柱經俠頸，俠頸者，頭中分也；太息，補手少陰、心主、足少陽，留之；涎下補足少陰；耳鳴補客主人，手大指爪甲上與肉交者；自嚙舌，視主病者，則補之。目眩頭傾，補足外踝下留之；痿厥心悗，刺足大趾間上二寸，留之，一曰足外踝下留之。","sortOrder":16},
  {"id":"s_work_hdnk_108_1","chapterId":"ch_work_hdnk_108","text":"師傳第二十九","sortOrder":1},
  {"id":"s_work_hdnk_108_2","chapterId":"ch_work_hdnk_108","text":"黃帝曰：餘聞先師，有所心藏，弗著於方，餘願聞而藏之，則而行之，上以治民，下以治身，使百姓無病，上下和親，德澤下流，子孫無優，傳於後世，無有終時，可得聞乎？岐伯曰：遠乎哉問也。夫治民與自治，治彼與治此，治小與治大，治國與治家，未有逆而能治之也，夫惟順而已矣。順者，非獨陰陽脈，論氣之逆順也，百姓人民皆欲順其志也。","sortOrder":2},
  {"id":"s_work_hdnk_108_3","chapterId":"ch_work_hdnk_108","text":"黃帝曰：順之奈何？岐伯曰：入國問俗，入家問諱，上堂問禮，臨病人問所便。","sortOrder":3},
  {"id":"s_work_hdnk_108_4","chapterId":"ch_work_hdnk_108","text":"黃帝曰：便病人奈何？岐伯曰：夫中熱消癉，則便寒；寒中之屬，則便熱。胃中熱則消穀，令人懸心善飢。臍以上皮熱，腸中熱，則出黃如糜。臍以下皮寒，胃中寒，則腹脹；腸中寒，則腸鳴飧泄。胃中寒，腸中熱，則脹而且泄，胃中熱，腸中寒，則疾飲，小腹痛脹。","sortOrder":4},
  {"id":"s_work_hdnk_108_5","chapterId":"ch_work_hdnk_108","text":"黃帝曰：胃欲寒飲，腸欲熱飲，兩者相逆，便之奈何？且夫王公大人，血食之君，驕恣從欲輕人，而無能禁之，禁之則逆其志，順之則加其病，便之奈何？治之何先？岐伯曰：人之情，莫不惡死而喜生，告之以其敗，語之以其善，導之以其所便，開之以其所苦，雖有無道之人，惡有不聽者乎？","sortOrder":5},
  {"id":"s_work_hdnk_108_6","chapterId":"ch_work_hdnk_108","text":"黃帝曰：治之奈何？岐伯曰：春夏先治其標，後治其本；秋冬先治其本，後治其標。","sortOrder":6},
  {"id":"s_work_hdnk_108_7","chapterId":"ch_work_hdnk_108","text":"黃帝曰：便其相逆者奈何？岐伯曰：便此者，食飲衣服，亦欲適寒溫，寒無淒愴，暑無出汗。食飲者，熱無灼灼，寒無滄滄。寒溫中適，故氣將持，乃不致邪僻也。","sortOrder":7},
  {"id":"s_work_hdnk_108_8","chapterId":"ch_work_hdnk_108","text":"黃帝曰：本藏以身形肢節〈月困〉肉，候五臟六腑之大小焉。今夫王公大人，臨朝即位之君，而問焉，誰可捫循之，而後答乎？岐伯曰：身形肢節者，藏府之蓋也，非面部之閱也。","sortOrder":8},
  {"id":"s_work_hdnk_108_9","chapterId":"ch_work_hdnk_108","text":"黃帝曰：五藏之氣，閱於面者，餘已知之矣，以肢節知而閱之，奈何？岐伯曰：五藏六府者，肺為之蓋，巨肩陷咽，候見其外。黃帝曰：善。","sortOrder":9},
  {"id":"s_work_hdnk_108_10","chapterId":"ch_work_hdnk_108","text":"岐伯曰：五藏六府，心為之主，缺盆為之道，骷骨有餘以候〈骨曷〉〈骨虧〉。黃帝曰：善。","sortOrder":10},
  {"id":"s_work_hdnk_108_11","chapterId":"ch_work_hdnk_108","text":"岐伯曰：肝者，主為將，使之候外，欲知堅固，視目小大。黃帝曰：善。","sortOrder":11},
  {"id":"s_work_hdnk_108_12","chapterId":"ch_work_hdnk_108","text":"岐伯曰：脾者，主為衛，使之迎糧，視唇舌好惡，以知吉凶。黃帝曰：善。","sortOrder":12},
  {"id":"s_work_hdnk_108_13","chapterId":"ch_work_hdnk_108","text":"岐伯曰：腎者，主為外，使之遠聽，視耳好惡，以知其性。黃帝曰：善。願聞六府之候。","sortOrder":13},
  {"id":"s_work_hdnk_108_14","chapterId":"ch_work_hdnk_108","text":"岐伯曰：六府者，胃為之海，龐骸、大頸、張胸，五穀乃容。鼻隧以長，以候大腸。唇厚、人中長，以候小腸。目下果大，其膽乃橫。鼻孔在外，膀胱漏泄。鼻柱中央起，三焦乃約，此所以候六府者也。上下三等，藏安且良矣。","sortOrder":14},
  {"id":"s_work_hdnk_109_1","chapterId":"ch_work_hdnk_109","text":"決氣第三十","sortOrder":1},
  {"id":"s_work_hdnk_109_2","chapterId":"ch_work_hdnk_109","text":"黃帝曰：餘聞人有精、氣、津、液、血、脈，餘意以為一氣耳，今乃辨為六名，餘不知其所以然。岐伯曰：兩神相搏，合而成形，常先身生，是謂精。何謂氣？岐伯曰：上焦開發，宣五穀味，熏膚、充身、澤毛，若霧露之溉，是謂氣。何謂津？岐伯曰：腠理發泄，汗出溱溱，是謂津。何謂液？岐伯曰：穀入氣滿，淖澤註於骨，骨屬屈伸，泄澤補益腦髓，皮膚潤澤，是謂液。何謂血？岐伯曰：中焦受氣，取汁變化而赤，是謂血。何謂脈？岐伯曰：壅遏營氣，令無所避，是謂脈。","sortOrder":2},
  {"id":"s_work_hdnk_109_3","chapterId":"ch_work_hdnk_109","text":"黃帝曰：六氣有，有餘不足，氣之多少，腦髓之虛實，血脈之清濁，何以知之？岐伯曰：精脫者，耳聾；氣脫者，目不明；津脫者，腠理開，汗大泄；液脫者，骨屬屈伸不利，色夭，腦髓消，脛痺，耳數鳴；血脫者，色白，夭然不澤，其脈空虛，此其候也。","sortOrder":3},
  {"id":"s_work_hdnk_109_4","chapterId":"ch_work_hdnk_109","text":"黃帝曰：六氣者，貴賤何如？岐伯曰：六氣者，各有部主也，其貴賤善惡，可為常主，然五穀與胃為大海也。","sortOrder":4},
  {"id":"s_work_hdnk_110_1","chapterId":"ch_work_hdnk_110","text":"腸胃第三十一","sortOrder":1},
  {"id":"s_work_hdnk_110_2","chapterId":"ch_work_hdnk_110","text":"黃帝問於伯高曰：餘願聞六府傳穀者，腸胃之大小長短，受穀之多少奈何？伯高曰：請盡言之，穀所從出入淺深遠近長短之度：唇至齒長九分，口廣二寸半；齒以後至會厭，深三寸半，大容五合；舌重十兩，長七寸，廣二寸半；咽門重十兩，廣一寸半。至胃長一尺六寸，胃紆曲屈，伸之，長二尺六寸，大一尺五寸，徑五寸，大容三斗五升。小腸後附脊，左環回日迭積，其註於回腸者，外附於臍上。回運環十六曲，大二寸半，徑八分分之少半，長三丈三尺。回腸當臍左環，回周葉積而下，回運還反十六曲，大四寸，徑一寸寸之少半，長二丈一尺。廣腸傳脊，以受回腸，左環葉脊上下，辟大八寸，徑二寸寸之大半，長二尺八寸。腸胃所入至所出，長六丈四寸四分，回曲環反，三十二曲也。","sortOrder":2},
  {"id":"s_work_hdnk_111_1","chapterId":"ch_work_hdnk_111","text":"平人絕穀第三十二","sortOrder":1},
  {"id":"s_work_hdnk_111_2","chapterId":"ch_work_hdnk_111","text":"黃帝曰：願聞人之不食，七日而死，何也？伯高曰：臣請言其故。","sortOrder":2},
  {"id":"s_work_hdnk_111_3","chapterId":"ch_work_hdnk_111","text":"胃大一尺五寸，徑五寸，長二尺六寸，橫屈受水穀三斗五升，其中之穀，常留二斗，水一斗五升而滿，上焦泄氣，出其精微，慓悍滑疾，下焦下溉諸腸。","sortOrder":3},
  {"id":"s_work_hdnk_111_4","chapterId":"ch_work_hdnk_111","text":"小腸大二寸半，徑八分分之少半，長三丈二尺，受穀二斗四升，水六升三合合之大半。","sortOrder":4},
  {"id":"s_work_hdnk_111_5","chapterId":"ch_work_hdnk_111","text":"回腸大四寸，徑一寸寸之少半，長二丈一尺，受穀一斗，水七升半。","sortOrder":5},
  {"id":"s_work_hdnk_111_6","chapterId":"ch_work_hdnk_111","text":"廣腸大八寸，徑二寸寸之大半，長二尺八寸，受穀九升三合八分合之一。","sortOrder":6},
  {"id":"s_work_hdnk_111_7","chapterId":"ch_work_hdnk_111","text":"腸胃之長，凡五丈八尺四寸，受水穀九斗二升一合合之大半，此腸胃所受水穀之數也。平人則不然，胃滿則腸虛，腸滿則胃虛，更虛更滿，故氣得上下，五臟安定，血脈和利，精神乃居，故神者，水穀之精氣也。故腸胃之中，當留穀二斗，水一斗五升；故平人日再後，後二升半，一日中五升，七日五七三斗五升，而留水穀盡矣；故平人不食飲七日而死者，小穀精氣津液皆盡故也。","sortOrder":7},
  {"id":"s_work_hdnk_112_1","chapterId":"ch_work_hdnk_112","text":"海論第三十三","sortOrder":1},
  {"id":"s_work_hdnk_112_2","chapterId":"ch_work_hdnk_112","text":"黃帝問於岐伯曰：餘聞刺法於夫子，夫子之所言，不離於營衛血氣。夫十二經脈者，內屬於腑臟，外絡於肢節，夫子乃合之於四海乎。岐伯答曰：人亦有四海，十二經水。經水者，皆註於海，海有東西南北，命曰四海。黃帝曰：以人應之奈何？岐伯曰：人有髓海，有血海，有氣海，有水穀之海，凡此四者，以應四海也。","sortOrder":2},
  {"id":"s_work_hdnk_112_3","chapterId":"ch_work_hdnk_112","text":"黃帝曰：遠乎者，夫子之合人天地四海也，願聞應之奈何？岐伯曰：必先明知陰陽表滎腧所在，四海定矣。","sortOrder":3},
  {"id":"s_work_hdnk_112_4","chapterId":"ch_work_hdnk_112","text":"黃帝曰：定之奈何？岐伯曰：胃者水穀之海，其輸上在氣街（衝），下至三里；衝脈者，為十二經之海，其輸上在於大杼，下出於巨虛之上下廉；膻中者，為氣之海，其輸上在於柱骨之上下，前在於人迎，腦為髓之海，其輸上在於其蓋，下在風府。","sortOrder":4},
  {"id":"s_work_hdnk_112_5","chapterId":"ch_work_hdnk_112","text":"黃帝曰：凡此四海者，何利何害？何生何敗？岐伯曰：得順者生，得逆者敗；知調者利，不知調者害。","sortOrder":5},
  {"id":"s_work_hdnk_112_6","chapterId":"ch_work_hdnk_112","text":"黃帝曰：四海之逆順奈何？岐伯曰：氣海有餘者，氣滿胸中，悗息面赤；氣海不足，則氣少不足以言。血海有餘，則常想其身大，怫然不知其所病；血海不足，亦常想其身小，狹然不知其所病。水穀之海有餘，則腹滿；水穀之海不足，則飢不受穀食。髓海有餘，則輕勁多力，自過其度；髓海不足，則腦轉耳鳴，脛痠眩冒，目無所見，懈怠安臥。","sortOrder":6},
  {"id":"s_work_hdnk_112_7","chapterId":"ch_work_hdnk_112","text":"黃帝曰：餘已聞逆順，調之奈何？岐伯曰：審守其俞，而調其虛實，無犯其害，順者得復，逆者必敗。黃帝曰：善。","sortOrder":7},
  {"id":"s_work_hdnk_113_1","chapterId":"ch_work_hdnk_113","text":"五亂第三十四","sortOrder":1},
  {"id":"s_work_hdnk_113_2","chapterId":"ch_work_hdnk_113","text":"黃帝曰：經脈十二者，別為五行，分為四時，何失而亂？何得而治？岐伯曰：五行有序，四時有分，相順則治，相逆則亂。","sortOrder":2},
  {"id":"s_work_hdnk_113_3","chapterId":"ch_work_hdnk_113","text":"黃帝曰：何謂相順？岐伯曰：經脈十二者，以應十二月。十二月者，分為四時。四時者，春秋冬夏，其氣各異，營衛相隨，陰陽已知，清濁不相幹，如是則順之而治。","sortOrder":3},
  {"id":"s_work_hdnk_113_4","chapterId":"ch_work_hdnk_113","text":"黃帝曰：何為逆而亂，岐伯曰：清氣在陰，濁氣在陽，營氣順脈，衛氣逆行，清濁相幹，亂於胸中，是謂大悗。故氣亂於心，則煩心密嘿，俛首靜伏；亂於肺，則俛仰喘喝，接手以呼；亂於腸胃，是為霍亂；亂於臂脛，則為四厥；亂於頭，則為厥逆，頭重眩仆。","sortOrder":4},
  {"id":"s_work_hdnk_113_5","chapterId":"ch_work_hdnk_113","text":"黃帝曰：五亂者，刺之有道乎？岐伯曰：有道以來，有道以去，審知其道，是謂身寶。黃帝曰：善。願聞其道。岐伯曰：氣在於心者，取之手少陰心主之俞；氣在於肺者，取之手太陰滎，足少陰俞，氣在於腸胃者，取之足太陰陽明，不下者，取之三里，氣在於頭者，取之天柱大杼，不知，取足太陽滎俞；氣在於臂足，取之先去血脈，後取其陽明少陽之滎俞。","sortOrder":5},
  {"id":"s_work_hdnk_113_6","chapterId":"ch_work_hdnk_113","text":"黃帝曰：補瀉奈何？岐伯曰：徐入徐出，謂之導氣。補瀉無形，謂之同精。是非有餘不足也，亂氣之相逆也。黃帝曰：允乎哉道，明乎哉論，請著之玉版，命曰治亂也。","sortOrder":6},
  {"id":"s_work_hdnk_114_1","chapterId":"ch_work_hdnk_114","text":"脹論第三十五","sortOrder":1},
  {"id":"s_work_hdnk_114_2","chapterId":"ch_work_hdnk_114","text":"黃帝曰：脈之應於寸口，如何而脹？岐伯曰：其脈大堅以澀者，脹也。黃帝曰：何以知藏府之脹也。岐伯曰：陰為藏，陽為府。","sortOrder":2},
  {"id":"s_work_hdnk_114_3","chapterId":"ch_work_hdnk_114","text":"黃帝曰：夫氣之令人脹也，在於血脈之中耶，臟腑之內乎？岐伯曰：三者皆存焉，然非脹之舍也。黃帝曰：願聞脹之舍。岐伯曰：夫脹者，皆在於臟腑之外，排臟腑而郭胸脅，脹皮膚，故命曰脹。","sortOrder":3},
  {"id":"s_work_hdnk_114_4","chapterId":"ch_work_hdnk_114","text":"黃帝曰：臟腑之在胸脅腹里之內也，若匣匱之藏禁器也，名有次舍，異名而同處，一域之中，其氣各異，願聞其故。黃帝曰：未解其意，再問。岐伯曰：夫胸腹，臟腑之郭也。膻中者，心主之宮城也；胃者，太倉也；咽喉、小腸者，傳送也；胃之五竅者，閭里門戶也；廉泉、玉英者，津液之道也。故五臟六腑者，各有畔界，其病各有形狀。營氣循脈，衛氣逆為脈脹；衛氣並脈循分為膚脹。三里而瀉，近者一下，遠者三下，無問虛實，工在疾瀉。","sortOrder":4},
  {"id":"s_work_hdnk_114_5","chapterId":"ch_work_hdnk_114","text":"黃帝曰：願聞脹形。岐伯曰：夫心脹者煩心短氣，臥不安；肺脹者，虛滿而喘咳；肝脹者，脅下滿而痛引小腹；脾脹者，善穢，四肢煩俛，體重不能勝衣，臥不安；腎脹者，腹滿引背央央然，腰髀痛。六府脹，胃脹者，腹滿，胃脘痛，鼻聞焦臭，妨於食，大便難；大腸脹者，腸鳴而痛濯濯，冬日重感於寒，則餐泄不化；小腸脹者，少腹慎脹，引腰而痛；膀胱脹者，少腹而氣癃；三焦脹者，氣滿於皮膚中，輕輕然而不堅；膽脹者，脅下痛脹，口中苦，善太息。","sortOrder":5},
  {"id":"s_work_hdnk_114_6","chapterId":"ch_work_hdnk_114","text":"凡此諸脹者，其道在一，明知逆順，針數不失，瀉虛補實，神去其室，致邪失正，真不可定，麤之所敗，謂之天命；補虛瀉實，神歸其室，久塞其空，謂之良工。","sortOrder":6},
  {"id":"s_work_hdnk_114_7","chapterId":"ch_work_hdnk_114","text":"黃帝曰：脹者焉生？何因而有？岐伯曰：衛氣之在身也，常然並脈，循分肉，行有逆順，陰陽相隨，乃得天和，五臟更始，四時循序，五穀乃化。然後厥氣在下，營衛留止，寒氣逆上，真邪相攻，兩氣相搏，乃合為脹也。黃帝曰：善。何以解惑？岐伯曰：合之於真，三合而得。帝曰：善。","sortOrder":7},
  {"id":"s_work_hdnk_114_8","chapterId":"ch_work_hdnk_114","text":"黃帝問於岐伯曰：脹論言無問虛實，工在疾瀉，近者一下，遠者三下，今有其三而不下者，其過焉在？岐伯對曰：此言陷於肉肓，而中氣穴者也。不中氣穴，則氣內閉，針不陷肓，則氣不行，上越中肉，則衛氣相亂，陰陽相逐。其於脹也，當瀉不瀉，氣故不下，三而不下，必更其道，氣下乃止，不下復始，可以萬全，烏有殆者乎？其於脹也，必審其彌，當瀉則瀉，當補則補，如鼓應桴，惡有不下者乎？","sortOrder":8},
  {"id":"s_work_hdnk_115_1","chapterId":"ch_work_hdnk_115","text":"五癃津液別第三十六","sortOrder":1},
  {"id":"s_work_hdnk_115_2","chapterId":"ch_work_hdnk_115","text":"黃帝問於岐伯曰：水穀入於口，輸於腸胃，其液別為五，天寒衣薄，則為溺與氣，天熱衣厚則為汗，悲哀氣並則為泣，中熱胃緩則為唾。邪氣內逆，則氣為之閉塞而不行，不行則為水脹，餘知其然也，不知其何由生？願聞其道。","sortOrder":2},
  {"id":"s_work_hdnk_115_3","chapterId":"ch_work_hdnk_115","text":"岐伯曰：水穀皆入於口，其味有五，各註其海。津液各走其道，故三焦出氣，以溫肌肉，充皮膚，為其津，其流而不行者為液。","sortOrder":3},
  {"id":"s_work_hdnk_115_4","chapterId":"ch_work_hdnk_115","text":"天暑衣厚則腠理開，故汗出，寒留於分肉之間，聚沫則為痛。","sortOrder":4},
  {"id":"s_work_hdnk_115_5","chapterId":"ch_work_hdnk_115","text":"天寒則腠理閉，氣濕不行，水下留於膀胱，則為溺與氣。","sortOrder":5},
  {"id":"s_work_hdnk_115_6","chapterId":"ch_work_hdnk_115","text":"五臟六腑，心為之主，耳為之聽，目為之候，肺為之相，肝為之將，脾為之衛，腎為之主外。故五臟六腑之津液，盡上滲於目，心悲氣並，則心系急。心系急則肺舉，肺舉則液上溢。夫心系與肺，不能常舉，乍上乍下，故欬而泣出矣。","sortOrder":6},
  {"id":"s_work_hdnk_115_7","chapterId":"ch_work_hdnk_115","text":"中熱則胃中消穀，消穀則蟲上下作。腸胃充郭，故胃緩，胃緩則氣逆，故唾出。","sortOrder":7},
  {"id":"s_work_hdnk_115_8","chapterId":"ch_work_hdnk_115","text":"五穀之津液，和合而為膏者，內滲入於骨空，補益腦髓，而下流於陰股。","sortOrder":8},
  {"id":"s_work_hdnk_115_9","chapterId":"ch_work_hdnk_115","text":"陰陽不和，則使液溢而下流於陰，髓液皆減而下，下過度則虛，虛，故腰背痛而脛痠。","sortOrder":9},
  {"id":"s_work_hdnk_115_10","chapterId":"ch_work_hdnk_115","text":"陰陽氣道不通，四海閉塞，三焦不瀉，津液不化，水穀並行腸胃之中，別於回腸，留於下焦，不得滲膀胱，則下焦脹，水溢則為水脹，此津液五別之逆順也。","sortOrder":10},
  {"id":"s_work_hdnk_116_1","chapterId":"ch_work_hdnk_116","text":"五閱五使第三十七","sortOrder":1},
  {"id":"s_work_hdnk_116_2","chapterId":"ch_work_hdnk_116","text":"黃帝問於岐伯曰：餘聞刺有五官五閱，以觀五氣。五氣者，五臟之使也，五時之副也。願聞其五使當安出？岐伯曰：五官者，五臟之閱也。黃帝曰：願聞其所出，令可為常。岐伯曰：脈出於氣口，色見於明堂，五色更出，以應五時，各如其常，經氣入臟，必當治理。","sortOrder":2},
  {"id":"s_work_hdnk_116_3","chapterId":"ch_work_hdnk_116","text":"帝曰：善。五色獨決於明堂乎？岐伯曰：五官已辨，闕庭必張，乃立明堂，明堂廣大，蕃蔽見外，方壁高基，引垂居外，五色乃治，平搏廣大，壽中百歲，見此者，刺之必已，如是之人者，血氣有餘，肌肉堅致，故可苦以針。","sortOrder":3},
  {"id":"s_work_hdnk_116_4","chapterId":"ch_work_hdnk_116","text":"黃帝曰：願聞五官。岐伯曰：鼻者，肺之官也；目者，肝之官也；口唇者，脾之官也；舌者，心之官也；耳者，腎之官也。","sortOrder":4},
  {"id":"s_work_hdnk_116_5","chapterId":"ch_work_hdnk_116","text":"黃帝曰：以官何候？岐伯曰：以候五臟。故肺病者，喘息鼻張；肝病者，眥青；脾病者，唇黃；心病者，舌捲短，顴赤；腎病者，顴與顏黑。","sortOrder":5},
  {"id":"s_work_hdnk_116_6","chapterId":"ch_work_hdnk_116","text":"黃帝曰：五脈安出，五色安見，其常色殆者如何？岐伯曰：五官不辨，闕庭不張，小其明堂，蕃蔽不見，又埤其牆，牆下無基，垂角去外。如是者，雖平常殆，況加疾哉。","sortOrder":6},
  {"id":"s_work_hdnk_116_7","chapterId":"ch_work_hdnk_116","text":"黃帝曰：五色之見於明堂，以觀五臟之氣，左右高下，各有形乎？岐伯曰：臟腑之在中也，各以次舍，左右上下，各如其度也。","sortOrder":7},
  {"id":"s_work_hdnk_117_1","chapterId":"ch_work_hdnk_117","text":"逆順肥瘦第三十八","sortOrder":1},
  {"id":"s_work_hdnk_117_2","chapterId":"ch_work_hdnk_117","text":"黃帝問於岐伯曰：餘聞針道於夫子，眾多畢悉矣。夫子之道，應若失，而據未有堅然者也。夫子之問學熟乎，將審察於物而心生之乎？岐伯曰：人之為道者，上合於天，下合於地，中合於人事，必有明法，以起度數，法式檢押，乃後可傳焉。故匠人不能釋尺寸而意短長，廢繩墨而起平水也，工人不能置規而為圓，去矩而為方。知用此者，固自然之物，易用之教，逆順之常也。","sortOrder":2},
  {"id":"s_work_hdnk_117_3","chapterId":"ch_work_hdnk_117","text":"黃帝曰：願聞自然奈何？岐伯曰：臨深決水，不用功力，而水可竭也。循拙決沖，而經可通也。此言氣之滑澀，血水清濁，行之逆順也。","sortOrder":3},
  {"id":"s_work_hdnk_117_4","chapterId":"ch_work_hdnk_117","text":"黃帝曰：願聞人之白黑肥瘦小長，各有數乎？岐伯曰：年質壯大，血氣充盈，膚革堅固，因加以邪，刺此者，深而留之，此肥人也。廣肩腋項，肉薄厚皮而黑色，唇臨臨然，其血黑以濁，其氣澀以遲。其為人也，貪於取與，刺此者，深而留之，多益其數也。","sortOrder":4},
  {"id":"s_work_hdnk_117_5","chapterId":"ch_work_hdnk_117","text":"黃帝曰：刺瘦人奈何？岐伯曰：瘦人者，皮薄色少，肉廉廉然，薄唇輕言，其血清氣滑，易脫於氣，易損於血，刺此者，淺而疾之。","sortOrder":5},
  {"id":"s_work_hdnk_117_6","chapterId":"ch_work_hdnk_117","text":"黃帝曰：刺常人奈何？岐伯曰：視其白黑，各為調之，其端正敦厚者，其血氣和調，刺此者，無失常數也。","sortOrder":6},
  {"id":"s_work_hdnk_117_7","chapterId":"ch_work_hdnk_117","text":"黃帝曰：刺壯士真骨者，奈何？岐伯曰：刺壯士真骨，堅肉緩節，監監然，此人重則氣澀血濁，刺此者，深而留之，多益其數；勁則氣滑血清，刺此者，淺而疾之。","sortOrder":7},
  {"id":"s_work_hdnk_117_8","chapterId":"ch_work_hdnk_117","text":"黃帝曰：刺嬰兒奈何？岐伯曰：嬰兒者，其肉脆，血少氣弱，刺此者，以豪刺，淺刺而疾拔針，日再可也。","sortOrder":8},
  {"id":"s_work_hdnk_117_9","chapterId":"ch_work_hdnk_117","text":"黃帝曰：臨深決水，奈何？岐伯曰：血清氣濁（滑），疾瀉之則氣竭焉。黃帝曰：循拙決沖，奈何？岐伯曰：血濁氣澀，疾瀉之，則經可通也。","sortOrder":9},
  {"id":"s_work_hdnk_117_10","chapterId":"ch_work_hdnk_117","text":"黃帝曰：脈行之逆順，奈何？岐伯曰：手之三陰，從臟走手；手之三陽，從手走頭；足之三陽，從頭走足；足之三陰，從足走腹。","sortOrder":10},
  {"id":"s_work_hdnk_117_11","chapterId":"ch_work_hdnk_117","text":"黃帝曰：少陰之脈獨下行，何也？岐伯曰：不然，夫沖脈者，五臟六腑之海也，五臟六腑皆稟焉。其上者，出於頏顙，滲諸陽，灌諸精；其下者，註少陰之大絡，出於氣街，循陰股內廉入膕中，伏行骭骨內，下至內踝之後屬而別。其下者，並於少陰之經，滲三陰；其前者，伏行出跗屬，下循跗，入大趾間，滲諸絡而溫肌肉。故別絡結則附上不動，不動則厥，厥則寒矣。黃帝曰：何以明之？岐伯曰：以言導之，切而驗之，其非必動，然後仍可明逆順之行也。黃帝曰：窘乎哉！聖人之為道也。明於日月，微於毫釐，其非夫子，孰能道之也。","sortOrder":11},
  {"id":"s_work_hdnk_118_1","chapterId":"ch_work_hdnk_118","text":"血絡論第三十九","sortOrder":1},
  {"id":"s_work_hdnk_118_2","chapterId":"ch_work_hdnk_118","text":"黃帝曰：願聞其奇邪而不在經者。岐伯曰：血絡是也。","sortOrder":2},
  {"id":"s_work_hdnk_118_3","chapterId":"ch_work_hdnk_118","text":"黃帝曰：刺血絡而仆者，何也？血出而射者，何也？血少黑而濁者，何也？血出清而半為汁者，何也？拔針而腫者，何也？血出若多若少而面色蒼蒼者，何也？拔針而面色不變而煩悗者，何也？多出血而不動搖者，何也？願聞其故。","sortOrder":3},
  {"id":"s_work_hdnk_118_4","chapterId":"ch_work_hdnk_118","text":"岐伯曰：脈氣盛而血虛者，刺之則脫氣，脫氣則仆。","sortOrder":4},
  {"id":"s_work_hdnk_118_5","chapterId":"ch_work_hdnk_118","text":"血氣俱盛而陰氣多者，其血滑，刺之則射；陽氣蓄積，久留而不瀉者，其血黑以濁，故不能射。","sortOrder":5},
  {"id":"s_work_hdnk_118_6","chapterId":"ch_work_hdnk_118","text":"新飲而液滲於絡，而未合和於血也，故血出而汁別焉；其不新飲者，身中有水，久則為腫。","sortOrder":6},
  {"id":"s_work_hdnk_118_7","chapterId":"ch_work_hdnk_118","text":"陰氣積於陽，其氣因於絡，故刺之血未出而氣先行，故腫。","sortOrder":7},
  {"id":"s_work_hdnk_118_8","chapterId":"ch_work_hdnk_118","text":"陰陽之氣，其新相得而未和合，因而瀉之，則陰陽俱脫，表裏相離，故脫色而蒼蒼然。","sortOrder":8},
  {"id":"s_work_hdnk_118_9","chapterId":"ch_work_hdnk_118","text":"刺之血出多，色不變而煩悗者，刺絡而虛經，虛經之屬於陰者，陰脫，故煩悗。","sortOrder":9},
  {"id":"s_work_hdnk_118_10","chapterId":"ch_work_hdnk_118","text":"陰陽相得而合為痺者，此為內溢於經，外註於絡。如是者，陰陽俱有餘，雖多出血而弗能虛也。","sortOrder":10},
  {"id":"s_work_hdnk_118_11","chapterId":"ch_work_hdnk_118","text":"黃帝曰：相之奈何？岐伯曰：血脈者，盛堅橫以赤，上下無常處，小者如針，大者如筋，則而瀉之萬全也，故無失數矣。失數而反，各如其度。","sortOrder":11},
  {"id":"s_work_hdnk_118_12","chapterId":"ch_work_hdnk_118","text":"黃帝曰：針入而肉著者，何也？岐伯曰：熱氣因於針，則針熱，熱則內著於針，故堅焉。","sortOrder":12},
  {"id":"s_work_hdnk_119_1","chapterId":"ch_work_hdnk_119","text":"陰陽清濁第四十","sortOrder":1},
  {"id":"s_work_hdnk_119_2","chapterId":"ch_work_hdnk_119","text":"黃帝曰：餘聞十二經脈，以應十二經水者，其五色各異，清濁不同，人之血氣若一，應之奈何？岐伯曰：人之血氣，苟能若一，則天下為一矣，惡有亂者乎？黃帝曰：餘問一人，非問天下之眾。岐伯曰：夫一人者，亦有亂氣，天下之象，亦有亂人，其合為一耳。","sortOrder":2},
  {"id":"s_work_hdnk_119_3","chapterId":"ch_work_hdnk_119","text":"黃帝曰：願聞人氣之清濁。岐伯曰：受穀者濁，受氣者清。清者註陰，濁者註陽。濁而清者，上出於咽，清而濁者，則下行。清濁相幹，命曰亂氣。","sortOrder":3},
  {"id":"s_work_hdnk_119_4","chapterId":"ch_work_hdnk_119","text":"黃帝曰：夫陰清而陽濁，濁者有清，清者有濁，清濁別之奈何？岐伯曰：氣之大別，清者上註於肺，濁者下走於胃。胃之清氣，上出於口；肺之濁氣，下註於經，內積於海。","sortOrder":4},
  {"id":"s_work_hdnk_119_5","chapterId":"ch_work_hdnk_119","text":"黃帝曰：諸陽皆濁，何陽濁甚乎？岐伯曰：手太陽獨受陽之濁，手太陰獨受陰之清；其清者上走空竅，其濁者下行諸經。諸陰皆清，足太陰獨受其濁。","sortOrder":5},
  {"id":"s_work_hdnk_119_6","chapterId":"ch_work_hdnk_119","text":"黃帝曰：治之奈何？岐伯曰：清者其氣滑，濁者其氣澀，此氣之常也。故刺陰者，深而留之；刺陽者，淺而疾之；清濁相幹者，以數調之也。","sortOrder":6},
  {"id":"s_work_hdnk_120_1","chapterId":"ch_work_hdnk_120","text":"陰陽繫日月第四十一","sortOrder":1},
  {"id":"s_work_hdnk_120_2","chapterId":"ch_work_hdnk_120","text":"黃帝曰：餘聞天為陽，地為陰，日為陽，月為陰，其合之於人，奈何？岐伯曰：腰以上為天，腰以下為地，故天為陽，地為陰，故足之十二經脈，以應為十二月，月生於水，故在下者為陰；手之十指，以應十日，日主火，故在上者為陽。","sortOrder":2},
  {"id":"s_work_hdnk_120_3","chapterId":"ch_work_hdnk_120","text":"黃帝曰：合之於脈，奈何？岐伯曰：寅者，正月之生陽也，主左足之少陽；未者，六月，主右足之少陽。卯者，二月，主左足之太陽；午者，五月，主右足之太陽。辰者，三月，主左足之陽明；巳者，四月，主右足之陽明。此兩陽合於前，故曰陽明。申者，七月之生陰也，主右足之少陰；丑者，十二月，主左足之少陰；酉者，八月，主右足之太陰；子者，十一月，主左足之太陰；戌者，九月，主右足之厥陰；亥者，十月，主左足之厥陰；此兩陰交盡，故曰厥陽。","sortOrder":3},
  {"id":"s_work_hdnk_120_4","chapterId":"ch_work_hdnk_120","text":"甲主左手之少陽；己主右手之少陽；乙主左手之太陽，戊主右手之太陽；丙主左手之陽明，丁主右手之陽明，此兩火併合，故為陽明。庚主右手之少陰，癸主左手之少陰，辛主右手之太陰，壬主左手之太陰。","sortOrder":4},
  {"id":"s_work_hdnk_120_5","chapterId":"ch_work_hdnk_120","text":"故足之陽者，陰中之少陽也；足之陰者，陰中之太陰也。手之陽者，陽中之太陽也；手之陰者，陽中之少陰也。腰以上者為陽，腰以下者為陰。","sortOrder":5},
  {"id":"s_work_hdnk_120_6","chapterId":"ch_work_hdnk_120","text":"其於五臟也，心為陽中之太陽，肺為陰中之少陰，肝為陰中少陽，脾為陰中之至陰，腎為陰中之太陰。","sortOrder":6},
  {"id":"s_work_hdnk_120_7","chapterId":"ch_work_hdnk_120","text":"黃帝曰：以治之奈何？岐伯曰：正月二月三月，人氣在左，無刺左足之陽；四月五月六月，人氣在右，無刺右足之陽，七月八月九月，人氣在右，無刺右足之陰，十月十一月十二月，人氣在左，無刺左足之陰。","sortOrder":7},
  {"id":"s_work_hdnk_120_8","chapterId":"ch_work_hdnk_120","text":"黃帝曰：五行以東方為甲乙木主春。春者，蒼色，主肝，肝者，足厥陰也。今乃以甲為左手之少陽，不合於數，何也？岐伯曰：此天地之陰陽也，非四時五行之以次行也。且夫陰陽者，有名而無形，故數之可十，離之可百，散之可千，推之可萬，此之謂也。","sortOrder":8},
  {"id":"s_work_hdnk_121_1","chapterId":"ch_work_hdnk_121","text":"病傳第四十二","sortOrder":1},
  {"id":"s_work_hdnk_121_2","chapterId":"ch_work_hdnk_121","text":"黃帝曰：餘受九針於夫子，而私覽於諸方，或有導引行氣，喬摩、灸、熨、刺、〈火苪〉、飲藥之一者，可獨守耶，將盡行之乎？岐伯曰：諸方者，眾人之方也，非一人之所盡行也。","sortOrder":2},
  {"id":"s_work_hdnk_121_3","chapterId":"ch_work_hdnk_121","text":"黃帝曰：此乃所謂守一勿失，萬物畢者也。今餘已聞陰陽之要，虛實之理，傾移之過，可治之屬，願聞病之變化，淫傳絕敗而不可治者，可得聞乎？岐伯曰：要乎哉問也，昭乎其如日醒，窘乎其如夜瞑，能被而服之，神與俱成，畢將服之，神自得之，生神之理，可著於竹帛，不可傳於子孫。","sortOrder":3},
  {"id":"s_work_hdnk_121_4","chapterId":"ch_work_hdnk_121","text":"黃帝曰：何謂日醒？岐伯曰：明於陰陽，如惑之解，如醉之醒。黃帝曰：何謂夜瞑？岐伯曰：瘖乎其無聲，漠乎其無形，折毛發理，正氣橫傾，淫邪泮衍，血脈傳溜，大氣入臟，腹痛下淫，可以致死，不可以致生。","sortOrder":4},
  {"id":"s_work_hdnk_121_5","chapterId":"ch_work_hdnk_121","text":"黃帝曰：大氣入臟，奈何？岐伯曰：病先發於心，一日而之肺，三日而之肝，五日而之脾，三日不已，死。冬夜半，夏日中。","sortOrder":5},
  {"id":"s_work_hdnk_121_6","chapterId":"ch_work_hdnk_121","text":"病先發於肺，三日而之肝，一日而之脾，五日而之胃，十日不已，死。冬日入，夏日出。","sortOrder":6},
  {"id":"s_work_hdnk_121_7","chapterId":"ch_work_hdnk_121","text":"病先發於肝，三日而之脾，五日而之胃，三日而之腎，三日不已，死。冬日入，夏蚤食。","sortOrder":7},
  {"id":"s_work_hdnk_121_8","chapterId":"ch_work_hdnk_121","text":"病先發於脾，一日而之胃，二日而之腎，三日而之膂膀胱，十日不已，死。冬人定，夏晏食。","sortOrder":8},
  {"id":"s_work_hdnk_121_9","chapterId":"ch_work_hdnk_121","text":"病先發於胃，五日而之腎，三日而之膂膀胱，五日而上之心，二日不已，死，冬夜半，夏日昳。","sortOrder":9},
  {"id":"s_work_hdnk_121_10","chapterId":"ch_work_hdnk_121","text":"病先發於腎，三日而之膂膀胱，三日而上之心，三日而之小腸，三日不已，死。冬大晨，夏晏晡。","sortOrder":10},
  {"id":"s_work_hdnk_121_11","chapterId":"ch_work_hdnk_121","text":"病先發於膀胱，五日而之腎，一日而之小腸，一日而之心，二日不已，死。冬雞鳴，夏下晡。","sortOrder":11},
  {"id":"s_work_hdnk_121_12","chapterId":"ch_work_hdnk_121","text":"諸病以次相傳，如是者，皆有死期，不可刺也；間一臟及二、三、四臟者，乃可刺也。","sortOrder":12},
  {"id":"s_work_hdnk_122_1","chapterId":"ch_work_hdnk_122","text":"淫邪發夢第四十三","sortOrder":1},
  {"id":"s_work_hdnk_122_2","chapterId":"ch_work_hdnk_122","text":"黃帝曰：願聞淫邪泮衍，奈何？岐伯曰：正邪從外襲內，而未有定舍，反淫於臟，不得定處，與營衛俱行，而與魂魄飛揚，使人臥不得安而喜夢；氣淫於腑，則有餘於外，不足於內；氣淫於臟，則有餘於內，不足於外。","sortOrder":2},
  {"id":"s_work_hdnk_122_3","chapterId":"ch_work_hdnk_122","text":"黃帝曰：有餘不足，有形乎？岐伯曰：陰氣盛，則夢涉大水而恐懼；陽氣盛，則夢大火而燔〈火苪〉；陰陽俱盛，則夢相殺。上盛則夢飛，下盛則夢墮；甚飢則夢取，甚飽則夢予；肝氣盛，則夢怒，肺氣盛，則夢恐懼、哭泣、飛揚；心氣盛，則夢善笑恐畏；脾氣盛，則夢歌、身體重不舉；腎氣盛，則夢腰脊兩解不屬。凡此十二盛者，至而瀉之，立已。","sortOrder":3},
  {"id":"s_work_hdnk_122_4","chapterId":"ch_work_hdnk_122","text":"厥氣客於心，則夢見丘山煙火；客於肺，則夢飛揚，見金鐵之奇物；客於肝，則夢山林樹木；客於脾，則夢見丘陵大澤，壞屋風雨；客於腎，則夢臨淵，沒居水中；客於膀胱，則夢遊行；客於胃，則夢飲食；客於大腸，則夢田野；客於小腸，則夢聚邑沖衢；客於膽，則夢鬥訟自刳；客於陰器，則夢接內；客於項，則夢斬首；客於脛，則夢行走而不能前，及居深地窌苑中；客於股肱，則夢禮節拜起；客於胞〈月直〉，則夢溲便。凡此十五不足者，至而補之立已也。","sortOrder":4},
  {"id":"s_work_hdnk_123_1","chapterId":"ch_work_hdnk_123","text":"順氣一日分為四時第四十四","sortOrder":1},
  {"id":"s_work_hdnk_123_2","chapterId":"ch_work_hdnk_123","text":"黃帝曰：夫百病之所始生者，必起於燥溫寒暑風雨陰陽喜怒飲食居處，氣合而有形，得臟而有名，餘知其然也。夫百病者，多以旦慧晝安，夕加夜甚，何也？岐伯曰：四時之氣使然。","sortOrder":2},
  {"id":"s_work_hdnk_123_3","chapterId":"ch_work_hdnk_123","text":"黃帝曰：願聞四時之氣。岐伯曰：春生，夏長，秋收，冬藏，是氣之常也，人亦應之，以一日分為四時，朝則為春，日中為夏，日入為秋，夜半為冬。朝則人氣始生，病氣衰，故旦慧；日中人氣長，長則勝邪，故安；夕則人氣始衰，邪氣始生，故加；夜半人氣入臟，邪氣獨居於身，故甚也。","sortOrder":3},
  {"id":"s_work_hdnk_123_4","chapterId":"ch_work_hdnk_123","text":"黃帝曰：有時有反者何也？岐伯曰：是不應四時之氣，臟獨主其病者，是必以臟氣之所不勝時者甚，以其所勝時者起也。黃帝曰：治之奈何？岐伯曰：順天之時，而病可與期。順者為工，逆者為麤。","sortOrder":4},
  {"id":"s_work_hdnk_123_5","chapterId":"ch_work_hdnk_123","text":"黃帝曰：善，餘聞刺有五變，以主五輸。願聞其數。岐伯曰：人有五臟，五臟有五變。五變有五輸，故五五二十五輸，以應五時。","sortOrder":5},
  {"id":"s_work_hdnk_123_6","chapterId":"ch_work_hdnk_123","text":"黃帝曰：願聞五變。岐伯曰：肝為牡藏，其色青，其時春，其音角，其味酸，其日甲乙；心為牡藏，其色赤，其時夏，其日丙丁，其音徵，其味苦；脾為牝藏，其色黃，其時長夏，其日戊己，其音宮，其味甘；肺為牝藏，其色白，其音商，其時徵，其日庚辛，其味辛；腎為牝藏，其色黑，其時冬，其日壬癸，其音羽，其味鹹。是為五變。","sortOrder":6},
  {"id":"s_work_hdnk_123_7","chapterId":"ch_work_hdnk_123","text":"黃帝曰：以主五輸奈何？藏主冬，冬刺井；色主春，春刺滎；時主夏，夏刺輸；音主長夏，長夏刺經；味主秋，秋刺合。是謂五變，以主五輸。","sortOrder":7},
  {"id":"s_work_hdnk_123_8","chapterId":"ch_work_hdnk_123","text":"黃帝曰：諸原安和，以致五輸。岐伯曰：原獨不應五時，以經合之，以應其數，故六六三十六輸。","sortOrder":8},
  {"id":"s_work_hdnk_123_9","chapterId":"ch_work_hdnk_123","text":"黃帝曰：何謂藏主冬，時主夏，音主長夏，味主秋，色主春。願聞其故。岐伯曰：病在藏者，取之井；病變於色者，取之滎；病時間時甚者，取之輸；病變於音者，取之經；經滿而血者，病在胃；及以飲食不節得病者，取之於合，故命曰味主合。是謂五變也。","sortOrder":9},
  {"id":"s_work_hdnk_124_1","chapterId":"ch_work_hdnk_124","text":"外揣第四十五","sortOrder":1},
  {"id":"s_work_hdnk_124_2","chapterId":"ch_work_hdnk_124","text":"餘聞九針九篇，餘親受其調，頗得其意。夫九針者，始於一而終於九，然未得其要道也。夫九針者，小之則無內，大之則無外，深不可為下，高不可為蓋，恍惚無竅，流溢無極，佘知其合於天道人事四時之變也，然餘願雜之毫毛，渾束為一，可乎？岐伯曰：明乎哉問也，非獨針道焉，夫治國亦然。","sortOrder":2},
  {"id":"s_work_hdnk_124_3","chapterId":"ch_work_hdnk_124","text":"黃帝曰：餘願聞針道，非國事也。岐伯曰：夫治國者，夫惟道焉，非道，何可小大深淺，雜合而為一乎。","sortOrder":3},
  {"id":"s_work_hdnk_124_4","chapterId":"ch_work_hdnk_124","text":"黃帝曰：願卒聞之。岐伯曰：日與月焉，水與鏡焉，鼓與響焉。夫日月之明，不失其影，水鏡之察，不失其形，鼓響之應，不後其聲，動搖則應和，盡得其情。","sortOrder":4},
  {"id":"s_work_hdnk_124_5","chapterId":"ch_work_hdnk_124","text":"黃帝曰：窘乎哉！昭昭之明不可蔽，其不可蔽，不失陰陽也。合而察之，切而驗之，見而得之，若清水明鏡之不失其形也。五音不彰，五色不明，五臟波蕩，若是則內外相襲，若鼓之應桴，響之應聲，影之似形。故遠者，司外揣內，近者，司內揣外，是謂陰陽之極，天地之蓋，請藏之靈蘭之室，弗敢使泄也。","sortOrder":5},
  {"id":"s_work_hdnk_125_1","chapterId":"ch_work_hdnk_125","text":"五變第四十六","sortOrder":1},
  {"id":"s_work_hdnk_125_2","chapterId":"ch_work_hdnk_125","text":"黃帝問於少俞曰：餘聞百疾之始期也，必生於風雨寒暑，循毫毛而入腠理，或復還，或留止，或為風腫汗出，或為消癉，或為寒熱，或為留痺，或為積聚。奇邪淫溢，不可勝數，願聞其故。夫同時得病，或病此，或病彼，意者天之為人生風乎，何其異也？少俞曰：夫天之生風者，非以私百姓也，其行公平正直，犯者得之，避者得無殆，非求人而人自犯之。","sortOrder":2},
  {"id":"s_work_hdnk_125_3","chapterId":"ch_work_hdnk_125","text":"黃帝曰：一時遇風，同時得病，其病各異，願聞其故。少俞曰：善乎其問！請論以比匠人。匠人磨斧斤，礪刀削斷材木。木之陰陽，尚有堅脆，堅者不入，脆者皮弛，至其交節，而缺斤斧焉。夫一木之中，堅脆不同，堅者則剛，脆者易傷，況其材木之不同，皮之厚薄，汁之多少，而各異耶。夫木之蚤花先生葉者，遇春霜烈風，則花落而葉萎；久曝大旱，則脆木薄皮者，枝條汁少而葉萎；久陰淫雨，則薄皮多汁者，皮漉而淺；卒風暴起，則剛脆之木，根搖而葉落。凡此五者，各有所傷，況於人乎！","sortOrder":3},
  {"id":"s_work_hdnk_125_4","chapterId":"ch_work_hdnk_125","text":"黃帝曰：以人應木，奈何？少俞答曰：木之所傷也，皆傷其枝。枝之剛脆而堅，未成傷也。人之有常病也，亦因其骨節皮膚腠理之不堅固者，邪之所舍也，故常為病也。","sortOrder":4},
  {"id":"s_work_hdnk_125_5","chapterId":"ch_work_hdnk_125","text":"黃帝曰：人之善病風厥漉汗者，何以候之？少俞答曰：內不堅，腠理疏，則善病風。黃帝曰：何以候肉之不堅也？少俞答曰：膕肉不堅，而無分理。理者麤理，麤理而皮不致者，腠理疏。此言其渾然者。","sortOrder":5},
  {"id":"s_work_hdnk_125_6","chapterId":"ch_work_hdnk_125","text":"黃帝曰：人之善病消癉者，何以候之？少俞答曰：五臟皆柔弱者，善病消癉。黃帝曰：何以知五臟之柔弱也？少俞答曰：夫柔弱者，必有剛強，剛強多怒，柔者易傷也。黃帝曰：何以候柔弱之與剛強？少俞答曰：此人薄皮膚，而目堅固以深者，長沖直腸，其心剛，剛則多怒，怒則氣上逆，胸中蓄積，血氣逆留，髖皮充肌，血脈不行，轉而為熱，熱則消肌膚，故為消癉。此言其人暴剛而肌肉弱者也。","sortOrder":6},
  {"id":"s_work_hdnk_125_7","chapterId":"ch_work_hdnk_125","text":"黃帝曰：人之善病寒熱者，何以候之？少俞答曰：小骨弱肉者，善病寒熱。黃帝曰：何以候骨之小大，肉之堅脆，色之不一也？少俞答曰：顴骨者，骨之本也。顴大則骨大，顴小則骨小。皮膚薄而其肉無〈月困〉，其臂懦懦然，其地色殆然，不與其天同色，污然獨異，此其候也。然後臂薄者，其髓不滿，故善病寒熱也。","sortOrder":7},
  {"id":"s_work_hdnk_125_8","chapterId":"ch_work_hdnk_125","text":"黃帝曰：何以候人之善病痺者？少俞答曰：麤理而肉不堅者，善病痺。黃帝曰：痺之高下有處乎？少俞答曰：欲知其高下者，各視其部。","sortOrder":8},
  {"id":"s_work_hdnk_125_9","chapterId":"ch_work_hdnk_125","text":"黃帝曰：人之善病腸中積聚者，何以候之？少俞答曰：皮膚薄而不澤，肉不堅而淖澤。如此，則腸胃惡，惡則邪氣留止，積聚乃傷脾胃之間，寒溫不次，邪氣稍至。蓄積留止，大聚乃起。","sortOrder":9},
  {"id":"s_work_hdnk_125_10","chapterId":"ch_work_hdnk_125","text":"黃帝曰：餘聞病形，已知之矣！願聞其時。少俞答曰：先立其年，以知其時。時高則起，時下則殆，雖不陷下，當年有沖道，其病必起，是謂因形而生病，五變之紀也。","sortOrder":10},
  {"id":"s_work_hdnk_126_1","chapterId":"ch_work_hdnk_126","text":"本藏第四十七","sortOrder":1},
  {"id":"s_work_hdnk_126_2","chapterId":"ch_work_hdnk_126","text":"黃帝問於岐伯曰：人之血氣精神者，所以奉生而周於性命者也；經脈者，所以行血氣而營陰陽、濡筋骨，利關節者也；衛氣者，所以溫分肉，充皮膚，肥腠理，司開闔者也；志意者，所以御精神，收魂魄，適寒溫，和喜怒者也。是故血和則經脈流行，營復陰陽，筋骨勁強，關節清利矣；衛氣和則分肉解利，皮膚調柔，腠理致密矣；志意和則精神專直，魂魄不散，悔怒不起，五臟不受邪矣；寒溫和則六腑化穀，風痺不作，經脈通利，肢節得安矣，此人之常平也。五臟者，所以藏精神血氣魂魄者也；六腑者，所以化水穀而行津液者也。此人之所以具受於天也，無愚智賢不肖，無以相倚也。然有其獨盡天壽，而無邪僻之病，百年不衰，雖犯風雨卒寒大暑，猶有弗能害也；有其不離屏蔽室內，無怵惕之恐，然猶不免於病，何也？願聞其故。","sortOrder":2},
  {"id":"s_work_hdnk_126_3","chapterId":"ch_work_hdnk_126","text":"岐伯對曰：窘乎哉問也。五臟者，所以參天地，副陰陽，而運四時，化五節者也；五臟者，固有小大、高下、堅脆、端正、偏傾者，六腑亦有小大、長短、厚薄、結直、緩急。凡此二十五者，各不同，或善或惡，或吉或凶，請言其方。","sortOrder":3},
  {"id":"s_work_hdnk_126_4","chapterId":"ch_work_hdnk_126","text":"心小則安，邪弗能傷，易傷以憂；心大則憂，不能傷，易傷於邪。心高則滿於肺中，悗而善忘，難開以言；心下，則藏外，易傷於寒，易恐以言。心堅，則藏安守固；心脆則善病消癉熱中。心端正，則和利難傷；心偏傾則操持不一，無守司也。","sortOrder":4},
  {"id":"s_work_hdnk_126_5","chapterId":"ch_work_hdnk_126","text":"肺小，則少飲，不病喘喝；肺大則多飲，善病胸痺、喉痺、逆氣。肺高，則上氣，肩息咳；肺下則居賁迫肺，善脅下痛。肺堅則不病，咳上氣；肺脆，則苦病消痺易傷。肺端正，則和利難傷；肺偏傾，則胸偏痛也。","sortOrder":5},
  {"id":"s_work_hdnk_126_6","chapterId":"ch_work_hdnk_126","text":"肺小則臟安，無脅下之病；肝大則逼胃迫咽，迫咽則苦膈中，且脅下痛。肝高，則上支賁切，脅挽為息賁；肝下則逼胃脅下空，脅下空則易受邪。肝堅則藏安難傷；肝脆則善病消痺，易傷。肝端正，則和利難傷；肝偏傾，則脅下痛也。","sortOrder":6},
  {"id":"s_work_hdnk_126_7","chapterId":"ch_work_hdnk_126","text":"脾小，則臟安，難傷於邪也；脾大，則苦湊〈月少〉而痛，不能疾行。脾高，則〈月少〉引季脅而痛；脾下則下歸於大腸，下加於大腸，則臟苦受邪。脾堅，則臟安難傷；脾脆，則善病消痺易傷。脾端正，則和利難傷；脾偏傾，則善滿善脹也。","sortOrder":7},
  {"id":"s_work_hdnk_126_8","chapterId":"ch_work_hdnk_126","text":"腎小，則臟安難傷；腎大，則善病腰痛，不可以俛仰，易傷以邪。腎高，則苦背膂痛，不可以俛仰；腎下則腰尻痛，不可以俛仰，為狐疝。腎堅，則不病腰背痛；腎脆，則善病消癉，易傷。腎端正，則和利難傷；腎偏傾，則苦腰尻痛也。凡此二十五變者，人之所苦常病。","sortOrder":8},
  {"id":"s_work_hdnk_126_9","chapterId":"ch_work_hdnk_126","text":"黃帝曰：何以知其然也？岐伯曰：赤色小理者，心小；麤理者，心大。無〈骨曷〉〈骨虧〉者，心高；〈骨曷〉〈骨虧〉小、短、舉者，心下。〈骨曷〉〈骨虧〉長者，心下堅；〈骨曷〉〈骨虧〉弱小以薄者，心脆。〈骨曷〉〈骨虧〉直下不舉者，心端正；〈骨曷〉〈骨虧〉倚一方者，心偏傾也。","sortOrder":9},
  {"id":"s_work_hdnk_126_10","chapterId":"ch_work_hdnk_126","text":"白色小理者，肺小；麤理者，肺大。巨肩反膺陷喉者，肺高；合腋張脅者，肺下。好肩背厚者，肺堅；肩背薄者，肺脆。背膺厚者，肺端正；脅偏疏者，肺偏傾也。","sortOrder":10},
  {"id":"s_work_hdnk_126_11","chapterId":"ch_work_hdnk_126","text":"青色小理者，肝小；麤理者，肝大。廣胸反骹者，肝高；合脅兔骹者，肝下。胸脅好者，肝堅；脅骨弱者，肝脆。膺腹好相得者，肝端正；脅骨偏舉者，肝偏傾也。","sortOrder":11},
  {"id":"s_work_hdnk_126_12","chapterId":"ch_work_hdnk_126","text":"黃色小理者，脾小；麤理者，脾大。揭唇者，脾高；唇下縱者，脾下。唇堅者，脾堅；唇大而不堅者，脾脆。唇上下好者，脾端正；唇偏舉者，脾偏傾也。","sortOrder":12},
  {"id":"s_work_hdnk_126_13","chapterId":"ch_work_hdnk_126","text":"黑色小理者，腎小；麤理者，腎大。高耳者，腎高；耳後陷者，腎下。耳堅者，腎堅；耳薄而不堅者，腎脆。耳好前居牙車者，腎端正；耳偏高者，腎偏傾也。凡此諸變者，持則安，減則病也。","sortOrder":13},
  {"id":"s_work_hdnk_126_14","chapterId":"ch_work_hdnk_126","text":"帝曰：善。然非餘之所問也，願聞人之有不可病者，至盡天壽，雖有深擾大恐，怵惕之志，猶不能減也，甚寒大熱，不能傷也；其有不離屏蔽室內，又無怵惕之恐，然不免於病者，何也？願聞其故。岐伯曰：五臟六腑，邪之舍也，請言其故。五臟皆小者，少病，苦憔心，大愁擾；五臟皆大者，緩於事，難使以擾。五臟皆高者，好高舉措；五臟皆下者，好出人下。五臟皆堅者，無病；五臟皆脆者，不離於病。五臟皆端正者，和利得人心；五臟皆偏傾者，邪心而善盜，不可以為人平，反復言語也。","sortOrder":14},
  {"id":"s_work_hdnk_126_15","chapterId":"ch_work_hdnk_126","text":"黃帝曰：願聞六腑之應。岐伯答曰：肺合大腸，大腸者，皮其應；心合小腸，小腸者，脈其應；肝合膽，膽者，筋其應；脾合胃，胃者，肉其應；腎合三焦膀胱，三焦膀胱者，腠理毫毛其應。","sortOrder":15},
  {"id":"s_work_hdnk_126_16","chapterId":"ch_work_hdnk_126","text":"黃帝曰：應之奈何？岐伯曰：肺應皮。皮厚者，大腸厚，皮薄者，大腸薄；皮緩，腹裏大者，大腸大而長；皮急者，大腸急而短；皮滑者，大腸直；皮肉不相離者，大腸結。","sortOrder":16},
  {"id":"s_work_hdnk_126_17","chapterId":"ch_work_hdnk_126","text":"心應脈，皮厚者，脈厚，脈厚者，小腸厚；皮薄者，脈薄，脈薄者，小腸薄；皮緩者，脈緩，脈緩者，小腸大而長；皮薄而脈沖小者，小腸小而短。諸陽經脈皆多紆屈者，小腸結。","sortOrder":17},
  {"id":"s_work_hdnk_126_18","chapterId":"ch_work_hdnk_126","text":"脾應肉，肉〈月困〉堅大者，胃厚；肉〈月困〉么者，胃薄。肉〈月困〉小而么者，胃不堅；肉膕不稱身者，胃下，胃下者，下管約不利。肉脾不堅者，胃緩；肉〈月困〉無小裏累者，胃急。肉〈月困〉多少裏累者，胃結，胃結者，上管約不利也。","sortOrder":18},
  {"id":"s_work_hdnk_126_19","chapterId":"ch_work_hdnk_126","text":"肝應爪，爪厚色黃者，膽厚；爪薄色紅者，膽薄；爪堅色青者，膽急；爪濡色赤者，膽緩；爪直色白無約者，膽直；爪惡色黑多紋者，膽結也。","sortOrder":19},
  {"id":"s_work_hdnk_126_20","chapterId":"ch_work_hdnk_126","text":"腎應骨，密理厚皮者，三焦膀胱厚；麤理薄皮者，三焦膀胱薄。疏腠理者，三焦膀胱緩；皮急而無毫毛者，三焦膀胱急。毫毛美而麤者，三焦膀胱直，稀毫毛者，三焦膀胱結也。","sortOrder":20},
  {"id":"s_work_hdnk_126_21","chapterId":"ch_work_hdnk_126","text":"黃帝曰：厚薄美惡，皆有形，願聞其所病。岐伯答曰：視其外應，以知其內藏，則知所病矣。","sortOrder":21},
  {"id":"s_work_hdnk_127_1","chapterId":"ch_work_hdnk_127","text":"禁服第四十八","sortOrder":1},
  {"id":"s_work_hdnk_127_2","chapterId":"ch_work_hdnk_127","text":"雷公問於黃帝曰：細子得受，通於九針六十篇，旦暮勤服之，近者編絕，久者簡垢，然尚諷誦弗置，未盡解於意矣。「外揣」言渾束為一，未知所謂也。夫大則無外，小則無內，大小無極，高下無度，束之奈何？士之才力，或有厚薄，智慮褊淺，不能博大深奧，自強於學若細子。細子恐其散於後世，絕於子孫，敢問約之奈何？黃帝曰：善乎哉問也。此先師之所禁，坐私傳之也，割臂歃血之盟也，子若欲得之，何不齋乎。","sortOrder":2},
  {"id":"s_work_hdnk_127_3","chapterId":"ch_work_hdnk_127","text":"雷公再拜而起曰：請聞命於是也，乃齋宿三日而請曰：敢問今日正陽，細子願以受盟。黃帝乃與俱入齋室，割臂歃血，黃帝親祝曰：今日正陽，歃血傳方，有敢背此言者，反受其殃。雷公再拜曰：細子受之。黃帝乃左握其手，右授之書曰：慎之慎之，吾為子言之，凡刺之理，經脈為始，營其所行，知其度量，內刺五臟，外刺六腑，審察衛氣，為百病母，調其虛實，虛實乃止，瀉其血絡，血盡不殆矣。","sortOrder":3},
  {"id":"s_work_hdnk_127_4","chapterId":"ch_work_hdnk_127","text":"雷公曰：此皆細子之所以通，未知其所約也。黃帝曰：夫約方者，猶約囊也，囊滿而弗約，則輸泄，方成弗約，則神與弗俱。雷公曰：願為下材者，勿滿而約之。黃帝曰：未滿而知約之以為工，不可以為天下師。","sortOrder":4},
  {"id":"s_work_hdnk_127_5","chapterId":"ch_work_hdnk_127","text":"雷公曰：願聞為工。黃帝曰：寸口主中，人迎主外，兩者相應，俱往俱來，若引繩大小齊等。春夏人迎微大，秋冬寸口微大，如是者，名曰平人。","sortOrder":5},
  {"id":"s_work_hdnk_127_6","chapterId":"ch_work_hdnk_127","text":"人迎大一倍於寸口，病在足少陽，一倍而躁，在手少陽。人迎二倍，病在足太陽，二倍而躁，病在手太陽。人迎三倍，病在足陽明，三倍而躁，病在手陽明。盛則為熱，虛則為寒，緊則為痛痺，代則乍甚乍間。盛則瀉之，虛則補之，緊痛則取之分肉，代則取血絡，且飲藥，陷下則灸之，不盛不虛，以經取之，名曰經刺。人迎四倍者，且大且數，名曰溢陽，溢陽為外格，死不治。必審按其本末，察其寒熱，以驗其臟腑之病。","sortOrder":6},
  {"id":"s_work_hdnk_127_7","chapterId":"ch_work_hdnk_127","text":"寸口大於人迎一倍，病在足厥陰，一倍而躁，在手心主。寸口二倍，病在足少陰，二倍而躁，在手少陰。寸口三倍，病在足太陰，三倍而躁，在手太陰。盛則脹滿，寒中，食不化，虛則熱中、出糜、少氣、溺色變，緊則痛痺，代則乍痛乍止。盛則瀉之，虛則補之，緊則先刺而後灸之，代則取血絡，而後調之，陷下則徒灸之，陷下者，脈血結於中，中有著血，血寒，故宜灸之，不盛不虛，以經取之。寸口四倍者，名曰內關，內關者，且大且數，死不治。必審察其本末之寒溫，以驗其臟腑之病。","sortOrder":7},
  {"id":"s_work_hdnk_127_8","chapterId":"ch_work_hdnk_127","text":"通其營輸，乃可傳於大數。大數曰：盛則徒瀉之，虛則徒補之，緊則灸刺，且飲藥，陷下則徒灸之，不盛不虛，以經取之。所謂經治者，飲藥，亦曰灸刺，脈急則引，脈大以弱，則欲安靜，用力無勞也。","sortOrder":8},
  {"id":"s_work_hdnk_128_1","chapterId":"ch_work_hdnk_128","text":"五色第四十九","sortOrder":1},
  {"id":"s_work_hdnk_128_2","chapterId":"ch_work_hdnk_128","text":"雷公問於黃帝曰：五色獨決於明堂乎？小子未知其所謂也。黃帝曰：明堂者，鼻也；闕者，眉間也；庭者，顏也；蕃者，頰側也；蔽者，耳門也。其間欲方大，去之十步，皆見於外，如是者壽，必中百歲。","sortOrder":2},
  {"id":"s_work_hdnk_128_3","chapterId":"ch_work_hdnk_128","text":"雷公曰：五言之辨，奈何？黃帝曰：明堂骨高以起，平以直，五臟次於中央，六腑挾其兩側，首面上於闕庭，王宮在於下極，五臟安於胸中，真色以致，病色不見，明堂潤澤以清，五官惡得無辨乎？","sortOrder":3},
  {"id":"s_work_hdnk_128_4","chapterId":"ch_work_hdnk_128","text":"雷公曰：其不辨者，可得聞乎？黃帝曰：五色之見也，各出其色部。部骨陷者，必不免於病矣。其色部乘襲者，雖病甚，不死矣。","sortOrder":4},
  {"id":"s_work_hdnk_128_5","chapterId":"ch_work_hdnk_128","text":"雷公曰：官五色奈何？黃帝曰：青黑為痛，黃赤為熱，白為寒，是謂五官。","sortOrder":5},
  {"id":"s_work_hdnk_128_6","chapterId":"ch_work_hdnk_128","text":"雷公曰：病之益甚，與其方衰，如何？黃帝曰：外內皆在焉。切其脈口，滑小緊以沉者，病益甚，在中；人迎氣大緊以浮者，其病益甚，在外。其脈口浮滑者，病日進；人迎沉而滑者，病日損。其脈口滑以沉者，病日進，在內；其人迎脈滑盛以浮者，其病日進，在外。脈之浮沉及人迎與寸口氣小大等者，病難已；病之在藏，沉而大者，易已，小為逆；病在府，浮而大者，其病易已。人迎盛堅者，傷於寒，氣口盛堅者，傷於食。","sortOrder":6},
  {"id":"s_work_hdnk_128_7","chapterId":"ch_work_hdnk_128","text":"雷公曰：以色言食之間甚，奈何？黃帝曰：其色麤以明，沉夭者為甚，其色上行者，病益甚；其色下行，如雲徹散者，病方已。五色各有臟部，有外部有內部也。色從外部走內部者，其病從外走內；其色從內走外者，其病從內走外。病生於內者，先治其陰，後治其陽，反者益甚。其病生於陽者，先治其外，後治其內，反者益甚。其脈滑大，以代而長者，病從外來，目有所見，志有所惡，此陽氣之並也，可變而已。","sortOrder":7},
  {"id":"s_work_hdnk_128_8","chapterId":"ch_work_hdnk_128","text":"雷公曰：小子聞風者，百病之始也；厥逆者，寒濕之起也，別之奈何？黃帝曰：常候闕中，薄澤為風，沖濁為痺。在地為厥。此其常也；各以其色言其病。","sortOrder":8},
  {"id":"s_work_hdnk_128_9","chapterId":"ch_work_hdnk_128","text":"雷公曰：人不病卒死，何以知之？黃帝曰：大氣入於臟腑者，不病而卒死矣。雷公曰：病小愈而卒死者，何以知之？黃帝曰：赤色出兩顴，大如拇指者，病雖小愈，必卒死。黑色出於庭，大如拇指，必不病而卒死。","sortOrder":9},
  {"id":"s_work_hdnk_128_10","chapterId":"ch_work_hdnk_128","text":"雷公再拜曰：善哉！其死有期乎？黃帝曰：察色以言其時。雷公曰：善乎！願卒聞之。黃帝曰：庭者，首面也；闕上者，咽喉也；闕中者，肺也；下極者，心也；直下者，肝也；肝左者，膽也；下者，脾也；方上者，胃也；中央者，大腸也；挾大腸者，腎也；當腎者，臍也；面王以上者，小腸也，面王以下者，膀胱子處也；顴者，肩也；顴後者，臂也；臂下者，手也；目內眥上者，膺乳也；挾繩而上者，背也；循牙車以下者，股也；中央者，膝也；膝以下者，脛也；當脛以下者，足也；巨分者，股裏也；巨屈者，膝臏也。此五臟六腑肢節之部也，各有部分。有部分，用陰和陽，用陽和陰，當明部分，萬舉萬當。能別左右，是謂大道；男女異位，故曰陰陽。審察澤夭，謂之良工。","sortOrder":10},
  {"id":"s_work_hdnk_128_11","chapterId":"ch_work_hdnk_128","text":"沉濁為內，浮澤為外。黃赤為風，青黑為痛，白為寒，黃而膏潤為膿，赤甚者為血痛，甚為攣，寒甚為皮不仁。五色各見其部，察其浮沉，以知淺深；察其澤夭，以觀成敗；察其散搏，以知遠近；視色上下，以知病處；積神於心，以知往今。故相氣不微，不知是非，屬意勿去，乃知新故。色明不麤，沉天為甚，不明不澤，其病不甚。其色散，駒駒然，未有聚；其病散而氣痛，聚未成也。","sortOrder":11},
  {"id":"s_work_hdnk_128_12","chapterId":"ch_work_hdnk_128","text":"腎乘心，心先病，腎為應，色皆如是。","sortOrder":12},
  {"id":"s_work_hdnk_128_13","chapterId":"ch_work_hdnk_128","text":"男子色在於面王，為小腹痛；下為卵痛；其圜直為莖痛，高為本，下為首，狐疝〈疒貴〉陰之屬也。女子在於面王，為膀胱子處之病，散為痛，搏為聚，方員左右，各如其色形。其隨而下至胝，為淫，有潤如膏狀，為暴食不潔。","sortOrder":13},
  {"id":"s_work_hdnk_128_14","chapterId":"ch_work_hdnk_128","text":"左為左，右為右。其色有邪，聚散而不端，面色所指者也。色者，青黑赤白黃，皆端滿有別鄉。別鄉赤者，其色赤，大如榆莢，在面王為不日。其色上銳，首空上向，下銳下向，在左右如法。以五色命臟，青為肝，赤為心，白為肺，黃為脾，黑為腎。肝合筋，心合脈，肺合皮，脾合肉，腎合骨也。","sortOrder":14},
  {"id":"s_work_hdnk_129_1","chapterId":"ch_work_hdnk_129","text":"論勇第五十","sortOrder":1},
  {"id":"s_work_hdnk_129_2","chapterId":"ch_work_hdnk_129","text":"黃帝問於少俞曰：有人於此，併行併立，其年之長少等也，衣之厚薄均也，卒然遇烈風暴雨，或病或不病，或皆病，或皆不病，其故何也？少俞曰：帝問何急？黃帝曰：願盡聞之。少俞曰：春青風夏陽風，秋涼風，冬寒風。凡此四時之風者，其所病各不同形。","sortOrder":2},
  {"id":"s_work_hdnk_129_3","chapterId":"ch_work_hdnk_129","text":"黃帝曰：四時之風，病人如何？少俞曰：黃色薄皮弱肉者，不勝春之虛風；白色薄皮弱肉者，不勝夏之虛風；青色薄皮弱肉，不勝秋之虛風；赤色薄皮弱肉，不勝冬之虛風也。黃帝曰：黑色不病乎？少俞曰：黑色而皮厚肉堅，固不傷於四時之風；其皮薄而肉不堅，色不一者，長夏至而有虛風者，病矣。其皮厚而肌肉堅者，長夏至而有虛風，不病矣。其皮厚而肌肉堅者，必重感於寒，外內皆然，乃病。黃帝曰：善。","sortOrder":3},
  {"id":"s_work_hdnk_129_4","chapterId":"ch_work_hdnk_129","text":"黃帝曰：夫人之忍痛與不忍痛，非勇怯之分也。夫勇士之不忍痛者，見難則前，見痛則止；夫怯士之忍痛者，聞難則恐，遇痛不動。夫勇士之忍痛者，見難不恐，遇痛不動；夫怯士之不忍痛者，見難與痛，目轉面盻，恐不能言，失氣，驚，顏色變化，乍死乍生。餘見其然也，不知其何由，願聞其故。少俞曰：夫忍痛與不忍痛者，皮膚之薄厚，肌肉之堅脆，緩急之分也，非勇怯之謂也。","sortOrder":4},
  {"id":"s_work_hdnk_129_5","chapterId":"ch_work_hdnk_129","text":"黃帝曰：願聞勇怯之所由然。少俞曰：勇士者，目深以固，長沖直揚，三焦理橫，其心端直，其肝大以堅，其膽滿以傍，怒則氣盛而胸張，肝舉而膽橫，眥裂而目揚，毛起而面蒼，此勇士之由然者也。","sortOrder":5},
  {"id":"s_work_hdnk_129_6","chapterId":"ch_work_hdnk_129","text":"黃帝曰：願聞怯士之所由然。少俞曰：怯士者，目大而不減，陰陽相失，其焦理，縱〈骨曷〉〈骨虧〉短而小，肝系緩，其膽不滿而縱，腸胃挺，脅下空，雖方大怒，氣不能滿其胸，肝肺雖舉，氣衰復下，故不能久怒，此怯士之所由然者也。","sortOrder":6},
  {"id":"s_work_hdnk_129_7","chapterId":"ch_work_hdnk_129","text":"黃帝曰：怯士之得酒，怒不避勇士者，何臟使然？少俞曰：酒者，水穀之精，熟穀之液也，其氣慓悍，其入於胃中，則胃脹，氣上逆，滿於胸中，肝浮膽橫，當是之時，固比於勇士，氣衰則悔。與勇士同類，不知避之，名曰酒悖也。","sortOrder":7},
  {"id":"s_work_hdnk_130_1","chapterId":"ch_work_hdnk_130","text":"背腧第五十一","sortOrder":1},
  {"id":"s_work_hdnk_130_2","chapterId":"ch_work_hdnk_130","text":"黃帝問於岐伯曰：願聞五臟之腧，出於背者。岐伯曰：背中大腧，在杼骨之端，肺腧在三焦之間，心腧在五焦之間，膈腧在七焦之間，肝腧在九焦之間，脾腧在十一焦之間，腎腧在十四焦之間。皆挾脊相去三寸所，則欲得而驗之，按其處，應在中而痛解，乃其輸也。灸之則可刺之則不可。氣盛則瀉之，虛則補之。以火補者，毋吹其火，須自滅也；以火瀉之，疾吹其火，傳其艾，須其火滅也。","sortOrder":2},
  {"id":"s_work_hdnk_131_1","chapterId":"ch_work_hdnk_131","text":"衛氣第五十二","sortOrder":1},
  {"id":"s_work_hdnk_131_2","chapterId":"ch_work_hdnk_131","text":"黃帝曰：五臟者，所以藏精神魂魄者也；六腑者，所以受水穀而行化物者也。其氣內幹五臟，而外絡肢節。其浮氣之不循經者，為衛氣；其精氣之行於經者，為營氣。陰陽相隨，外內相貫，如環之無端。亭亭淳淳乎，孰能竊之。然其分別陰陽，皆有標本虛實所離之處。能別陰陽十二經者，知病之所生；候虛實之所在者，能得病之高下；知六腑之氣街者，能知解結契紹於門戶；能知虛石之堅軟者，知補瀉之所在；能知六經標本者，可以無惑於天下。","sortOrder":2},
  {"id":"s_work_hdnk_131_3","chapterId":"ch_work_hdnk_131","text":"岐伯曰：博哉！聖帝之論。臣請盡意悉言之。足太陽之本，在限以上五寸中，標在兩絡命門。命門者，目也。足少陽之本，在竅陰之間，標在窗籠之前。窗籠者，耳也。足少陰之本，在內踝下上三寸中，標在背輸與舌下兩脈也。足厥陰之本，在行間上五寸所，標在背腧也。足陽明之本，在厲兌，標在人迎，頰挾頏顙也。足太陰之本，在中封前上四寸之中，標在背腧與舌本也。","sortOrder":3},
  {"id":"s_work_hdnk_131_4","chapterId":"ch_work_hdnk_131","text":"手太陽之本，在外踝之後，標在命門之上一寸也。手少陽之本，在小指次指之間上二寸，標在耳後上角下外眥也。手陽明之本，在肘骨中，上至別陽，標在顏下合鉗上也。手太陰之本，在寸口之中，標在腋內動也。手少陰之本，在銳骨之端，標在背腧也。手心主之本，在掌後兩筋之間二寸中，標在腋下下三寸也。","sortOrder":4},
  {"id":"s_work_hdnk_131_5","chapterId":"ch_work_hdnk_131","text":"凡候此者，下虛則厥，下盛則熱；上虛則眩，上盛則熱痛。故石者，絕而止之，虛者，引而起之。","sortOrder":5},
  {"id":"s_work_hdnk_131_6","chapterId":"ch_work_hdnk_131","text":"請言氣街，胸氣有街，腹氣有街，頭氣有街，脛氣有街。故氣在頭者，止之於腦；氣在胸者，止之膺與背腧；氣在腹者，止之背腧，與沖脈於臍左右之動脈者；氣在脛者，止之於氣街，與承山踝上以下。取此者，用毫針，必先按而在久應於手，乃刺而予之。所治者，頭痛眩，腹痛中滿暴脹，及有新。痛可移者，易已也；積不痛，難已也。","sortOrder":6},
  {"id":"s_work_hdnk_132_1","chapterId":"ch_work_hdnk_132","text":"論痛第五十三","sortOrder":1},
  {"id":"s_work_hdnk_132_2","chapterId":"ch_work_hdnk_132","text":"黃帝問於少俞曰：筋骨之強弱，肌肉之堅脆，皮膚之厚薄，腠理之疏密，各不同，其於針石火〈火苪〉之痛何如？腸胃之厚薄堅脆亦不等，其於毒藥何如？願盡聞之。少俞曰：人之骨強、筋弱、肉緩、皮膚厚者，耐痛，其於針石之痛火〈火苪〉亦然。","sortOrder":2},
  {"id":"s_work_hdnk_132_3","chapterId":"ch_work_hdnk_132","text":"黃帝曰：其耐火煤者，何以知之？少俞答曰：加以黑色而美骨者，耐火〈火苪〉。黃帝曰：其不耐針石之痛者，何以知之？少俞曰：堅肉薄皮者，不耐針石之痛，於火〈火苪〉亦然。","sortOrder":3},
  {"id":"s_work_hdnk_132_4","chapterId":"ch_work_hdnk_132","text":"黃帝曰：人之病，或同時而傷，或易已，或難已，其故何如？少俞曰：同時而傷，其身多熱者，易已；多寒者，難已。","sortOrder":4},
  {"id":"s_work_hdnk_132_5","chapterId":"ch_work_hdnk_132","text":"黃帝曰：人之勝毒，何以知之？少俞曰：胃厚、色黑、大骨及肥骨者，皆勝毒；故其瘦而薄胃者，皆不勝毒也。","sortOrder":5},
  {"id":"s_work_hdnk_133_1","chapterId":"ch_work_hdnk_133","text":"天年第五十四","sortOrder":1},
  {"id":"s_work_hdnk_133_2","chapterId":"ch_work_hdnk_133","text":"黃帝問於岐伯曰：願聞人之始生，何氣築為基，何立而為楯，何失而死，何得而生？岐伯曰：以母為基，以父為楯；失神者死，得神者生也。","sortOrder":2},
  {"id":"s_work_hdnk_133_3","chapterId":"ch_work_hdnk_133","text":"黃帝曰：何者為神？岐伯曰：血氣已和，營衛已通，五臟已成，神氣舍心，魂魄畢具，乃成為人。","sortOrder":3},
  {"id":"s_work_hdnk_133_4","chapterId":"ch_work_hdnk_133","text":"黃帝曰：人之壽夭各不同，或夭壽，或卒死，或病久，願聞其道。岐伯曰：五臟堅固，血脈和調，肌肉解利，皮膚致密，營衛之行，不失其常，呼吸微徐，氣以度行，六腑化穀，津液布揚，各如其常，故能長久。","sortOrder":4},
  {"id":"s_work_hdnk_133_5","chapterId":"ch_work_hdnk_133","text":"黃帝曰：人之壽百歲而死，何以致之？岐伯曰：使道隧以長，基牆高以方，通調營衛，三部三里起，骨高肉滿，百歲乃得終。","sortOrder":5},
  {"id":"s_work_hdnk_133_6","chapterId":"ch_work_hdnk_133","text":"黃帝曰：其氣之盛衰，以至其死，可得聞乎？岐伯曰：人生十歲，五臟始定，血氣已通，其氣在下，故好走；二十歲，血氣始盛肌肉方長，故好趨；三十歲，五臟大定，肌肉堅固，血脈盛滿，故好步；四十歲，五臟六腑十二經脈，皆大盛以平定，腠理始疏，滎貨頹落，髮頗斑白，平盛不搖，故好坐；五十歲，肝氣始衰，肝葉始薄，膽汁始減，目始不明；六十歲，心氣始衰，若憂悲，血氣懈惰，故好臥；七十歲，脾氣虛，皮膚枯；八十歲，肺氣衰，魄離，故言善誤；九十歲，腎氣焦，四臟經脈空虛；百歲，五臟皆虛，神氣皆去，形骸獨居而終矣。","sortOrder":6},
  {"id":"s_work_hdnk_133_7","chapterId":"ch_work_hdnk_133","text":"黃帝曰：其不能終壽而死者，何如？岐伯曰：其五臟皆不堅，使道不長，空外以張，喘息暴疾；又卑基牆薄，脈少血，其肉不石，數中風寒，血氣虛，脈不通，真邪相攻，亂而相引，故中壽而盡也。","sortOrder":7},
  {"id":"s_work_hdnk_134_1","chapterId":"ch_work_hdnk_134","text":"逆順第五十五","sortOrder":1},
  {"id":"s_work_hdnk_134_2","chapterId":"ch_work_hdnk_134","text":"黃帝問於伯高曰：餘聞氣有逆順，脈有盛衰，刺有大約，可得聞乎？伯高曰：氣之逆順者，所以應天地陰陽四時五行也；脈之盛衰者，所以候血氣之虛實有餘不足；刺之大約者，必明知病之可刺，與其未可刺，與其已不可刺也。","sortOrder":2},
  {"id":"s_work_hdnk_134_3","chapterId":"ch_work_hdnk_134","text":"黃帝曰：候之奈何？伯高曰：兵法曰無迎逢逢之氣，無擊堂堂之陣。刺法曰：無刺熇熇之熱，無刺漉漉之汗，無刺渾渾之脈，無刺病與脈相逆者。","sortOrder":3},
  {"id":"s_work_hdnk_134_4","chapterId":"ch_work_hdnk_134","text":"黃帝曰：候其可刺奈何？伯高曰：上工，刺其未生者也；其次，刺其未盛者也；其次，刺其已衰者也。下工，刺其方襲者也；與其形之盛者也；與其病之與脈相逆者也。故曰：方其盛也，勿敢毀傷，刺其已衰，事必大昌。故曰：上工治未病，不治已病，此之謂也。","sortOrder":4},
  {"id":"s_work_hdnk_135_1","chapterId":"ch_work_hdnk_135","text":"五味第五十六","sortOrder":1},
  {"id":"s_work_hdnk_135_2","chapterId":"ch_work_hdnk_135","text":"黃帝曰：願聞穀氣有五味，其入五臟，分別奈何？伯高曰：胃者，五臟六腑之海也，水穀皆入於胃，五臟六腑，皆稟氣於胃。五味各走其所喜，穀味酸，先走肝，穀味苦，先走心，穀味甘，先走脾，穀味辛，先走肺，穀味鹹，先走腎。穀氣津液已行，營衛大通，乃化糟粕，以次傳下。","sortOrder":2},
  {"id":"s_work_hdnk_135_3","chapterId":"ch_work_hdnk_135","text":"黃帝曰：營衛之行奈何？伯高曰：穀始入於胃，其精微者，先出於胃之兩焦，以溉五臟，別出兩行，營衛之道。其大氣之搏而不行者，積於胸中，命曰氣海，出於肺，循咽喉，故呼則出，吸則入。天地之精氣，其大數常出三入一，故穀不入，半日則氣衰，一日則氣少矣。","sortOrder":3},
  {"id":"s_work_hdnk_135_4","chapterId":"ch_work_hdnk_135","text":"黃帝曰：穀之五味，可得聞乎？伯高曰：請盡言之。五穀：糠米甘，麻酸，大豆鹹，麥苦，黃黍辛。五果：棗甘，李酸，栗鹹，杏苦，桃辛。五畜：牛甘，犬酸，豬鹹，羊苦，雞辛。五菜：葵甘，韭酸，藿鹹，薤苦，蔥辛。","sortOrder":4},
  {"id":"s_work_hdnk_135_5","chapterId":"ch_work_hdnk_135","text":"五色：黃色宜甘，青色宜酸，黑色宜鹹，赤色宜苦，白色宜辛。凡此五者，各有所宜。五宜所言五色者，脾病者，宜食糠米飯，牛肉棗葵；心病者，宜食麥羊肉杏薤；腎病者，宜食大豆黃卷豬肉栗藿；肝病者，宜食麻犬肉李韭；肺病者，宜食黃黍雞肉桃蔥。","sortOrder":5},
  {"id":"s_work_hdnk_135_6","chapterId":"ch_work_hdnk_135","text":"五禁：肝病禁辛，心病禁鹹，脾病禁酸，腎病禁甘，肺病禁苦。","sortOrder":6},
  {"id":"s_work_hdnk_135_7","chapterId":"ch_work_hdnk_135","text":"肝色青，宜食甘，糠米飯、牛肉、棗、葵皆甘。心色赤，宜食酸，犬肉、麻、李、韭皆酸。脾黃色，宜食鹹，大豆、豬肉、栗、藿皆鹹。肺白色，宜食苦，麥、羊肉、杏、薤皆苦。腎色黑，宜食辛，黃黍、雞肉、桃、蔥皆辛。","sortOrder":7},
  {"id":"s_work_hdnk_136_1","chapterId":"ch_work_hdnk_136","text":"水脹第五十七","sortOrder":1},
  {"id":"s_work_hdnk_136_2","chapterId":"ch_work_hdnk_136","text":"黃帝問於岐伯曰：水與膚脹、鼓脹、腸覃、石瘕、石水，何以別之？岐伯曰：水始起也，目窠上微腫，如新臥起之狀，其頸脈動，時咳，陰股間寒，足脛腫，腹乃大，其水已成矣。以手按其腹，隨手而起，如裹水之狀，此其候也。","sortOrder":2},
  {"id":"s_work_hdnk_136_3","chapterId":"ch_work_hdnk_136","text":"黃帝曰：膚脹何以候之？岐伯曰：膚脹者，寒氣客於皮膚之間，鼕鼕然不堅，腹大，身盡腫，皮厚，按其腹，窅而不起，腹色不變，此其候也。","sortOrder":3},
  {"id":"s_work_hdnk_136_4","chapterId":"ch_work_hdnk_136","text":"鼓脹何如？岐伯曰：腹脹身皆大，大與膚脹等也，色蒼黃，腹筋起，此其候也。","sortOrder":4},
  {"id":"s_work_hdnk_136_5","chapterId":"ch_work_hdnk_136","text":"腸覃何如？岐伯曰：寒氣客於腸外，與衛氣相搏，氣不得榮，因有所繫，癖而內著，惡氣乃起，瘜肉乃生。其始生也，大如雞卵，稍以益大，至其成，如懷子之狀，久者離歲，按之則堅，推之則移，月事以時下，此其候也。","sortOrder":5},
  {"id":"s_work_hdnk_136_6","chapterId":"ch_work_hdnk_136","text":"石瘕何如？岐伯曰：石瘕生於胞中，寒氣客於子門，子門閉塞，氣不得通，惡血當瀉不瀉，衄以留止，日以益大，狀如懷子，月事不以時下，皆生於女子，可導而下。","sortOrder":6},
  {"id":"s_work_hdnk_136_7","chapterId":"ch_work_hdnk_136","text":"黃帝曰：膚脹鼓脹，可刺邪？岐伯曰：先瀉其脹之血絡，後調其經，刺去其血血絡也。","sortOrder":7},
  {"id":"s_work_hdnk_137_1","chapterId":"ch_work_hdnk_137","text":"賊風第五十八","sortOrder":1},
  {"id":"s_work_hdnk_137_2","chapterId":"ch_work_hdnk_137","text":"黃帝曰：夫子言賊風邪氣傷人也，令人病焉，今有其不離屏蔽，不出室穴之中，卒然病者，非不離賊風邪氣，其故何也？岐伯曰：此皆嘗有所傷於濕氣，藏於血脈之中，分肉之間，久留而不去。若有所墮墜，惡血在內而不去，卒然喜怒不節，飲食不適，寒溫不時，腠理閉而不通。其開而遇風寒，則血氣凝結，與故邪相襲，則為寒痺。其有熱則汗出，汗出則受風，雖不遇賊風邪氣，必有因加而發焉。","sortOrder":2},
  {"id":"s_work_hdnk_137_3","chapterId":"ch_work_hdnk_137","text":"黃帝曰：今夫子之所言者，皆病人之所自知也。其毋所遇邪氣，又毋怵惕之所志，卒然而病者，其故何也？唯有因鬼神之事乎？岐伯曰：此亦有故邪留而未發，因而志有所惡，及有所慕，血氣內亂，兩氣相搏。其所從來者微，視之不見，聽而不聞，故似鬼神。","sortOrder":3},
  {"id":"s_work_hdnk_137_4","chapterId":"ch_work_hdnk_137","text":"黃帝曰：其祝而已者，其故何也？岐伯曰：先巫者，因知百病之勝，先知其病之所從生者，可祝而已也。","sortOrder":4},
  {"id":"s_work_hdnk_138_1","chapterId":"ch_work_hdnk_138","text":"衛氣失常第五十九","sortOrder":1},
  {"id":"s_work_hdnk_138_2","chapterId":"ch_work_hdnk_138","text":"黃帝曰：衛氣之留於腹中，搐積不行，菀蘊不得常所，使人支脅胃中滿，喘呼逆息者，何以去之？伯高曰：其氣積於胸中者，上取之，積於腹中者，下取之，上下皆滿者，旁取之。","sortOrder":2},
  {"id":"s_work_hdnk_138_3","chapterId":"ch_work_hdnk_138","text":"黃帝曰：取之奈何？伯高對曰：積於上，瀉人迎、天突、喉中；積於下者，瀉三里與氣街；上下皆滿者，上下取之，與季脅之下一寸；重者，雞足取之。診視其脈大而絃急，及絕不至者，及腹皮急甚者，不可刺也。黃帝曰：善。","sortOrder":3},
  {"id":"s_work_hdnk_138_4","chapterId":"ch_work_hdnk_138","text":"黃帝問於伯高曰：何以知皮肉氣血筋骨之病也？伯高曰：色起兩眉薄澤者，病在皮；唇色青黃赤白黑者，病在肌肉；營氣濡然者，病在血氣；目色青黃赤白黑者，病在筋；耳焦枯受塵垢，病在骨。","sortOrder":4},
  {"id":"s_work_hdnk_138_5","chapterId":"ch_work_hdnk_138","text":"黃帝曰：病形何如，取之奈何？伯高曰：夫百病變化，不可勝數，然皮有部，肉有桂，血氣有輸，骨有屬。黃帝曰：願聞其故。伯高曰：皮之部，輸於四末；肉之柱，有臂脛諸陽分肉之間，與足少陰分間；血氣之輸，輸於諸絡，氣血留居，則盛而起，筋部無陰無陽，無左無右，候病所在；骨之屬者，骨空之所以受益而益腦者也。","sortOrder":5},
  {"id":"s_work_hdnk_138_6","chapterId":"ch_work_hdnk_138","text":"黃帝曰：取之奈何？伯高曰：夫病變化，浮沉深淺，不可勝究，各在其處，病間者淺之，甚者深之，間者小之，甚者眾之，隨變而調氣，故曰上工。","sortOrder":6},
  {"id":"s_work_hdnk_138_7","chapterId":"ch_work_hdnk_138","text":"黃帝問於伯高曰：人之肥瘦大小溫寒，有老壯少小，別之奈何？伯高對曰：人年五十已上為老，二十已上為壯，十八已上為少，六歲已上為小。","sortOrder":7},
  {"id":"s_work_hdnk_138_8","chapterId":"ch_work_hdnk_138","text":"黃帝曰：何以度知其肥瘦？伯高曰：人有肥、有膏、有肉。黃帝曰：別此奈何？伯高曰：膕肉堅，皮滿者，肥。膕肉不堅，皮緩者，膏。皮肉不相離者，肉。","sortOrder":8},
  {"id":"s_work_hdnk_138_9","chapterId":"ch_work_hdnk_138","text":"黃帝曰：身之寒溫何如？伯高：膏者，其肉淖而粗理者，身寒，細理者，身熱。脂者，其肉堅，細理者熱，粗理者寒。","sortOrder":9},
  {"id":"s_work_hdnk_138_10","chapterId":"ch_work_hdnk_138","text":"黃帝曰：其肥瘦大小奈何？伯高曰：膏者，多氣而皮縱緩，故能縱腹垂腴。肉者，身體容大。脂者，其身收小。","sortOrder":10},
  {"id":"s_work_hdnk_138_11","chapterId":"ch_work_hdnk_138","text":"黃帝曰：三者之氣血多少何如？伯高曰：膏者，多氣，多氣者，熱，熱者耐寒。肉者，多血則充形，充形則平。脂者，其血清，氣滑少，故不能大。此別於眾人者也。","sortOrder":11},
  {"id":"s_work_hdnk_138_12","chapterId":"ch_work_hdnk_138","text":"黃帝曰：眾人奈何？伯高曰：眾人皮肉脂膏，不能相加也，血與氣，不能相多，故其形不小不大，各自稱其身，命曰眾人。","sortOrder":12},
  {"id":"s_work_hdnk_138_13","chapterId":"ch_work_hdnk_138","text":"黃帝曰：善。治之奈何？伯高曰：必先別其三形，血之多少，氣之清濁，而後調之，治無失常經。是故膏人縱腹垂腴，肉人者，上下容大，脂人者，雖脂不能大者。","sortOrder":13},
  {"id":"s_work_hdnk_139_1","chapterId":"ch_work_hdnk_139","text":"玉版第六十","sortOrder":1},
  {"id":"s_work_hdnk_139_2","chapterId":"ch_work_hdnk_139","text":"黃帝曰：餘以小針為細物也，夫子乃言上合之於天，下合之於地，中合之於人，餘以為過針之意矣，願聞其故。岐伯曰：何物大於天乎？夫大於針者，惟五兵者焉，死之備也，非生之具。且夫人者，天地之鎮也，其不可不參乎？夫治民者，亦唯針焉。夫針之與五兵，其孰小乎？","sortOrder":2},
  {"id":"s_work_hdnk_139_3","chapterId":"ch_work_hdnk_139","text":"黃帝曰：病之生時，有喜怒不測，飲食不節，陰氣不足，陽氣有餘，營氣不行，乃發為癰疽。陰陽不通，兩熱相搏，乃化為濃，小針能取之乎？岐伯曰：聖人不能使化者為之，邪不可留也。故兩軍相當，旗幟相望，白刃陳於中野者，此非一日之謀也。能使其民令行，禁止士卒無白刃之難者，非一日之教也，須臾之得也。夫至使身被癰疽之病，膿血之聚者，不亦離道遠乎？夫癰疽之生，膿血之成也，不從天下，不從地出，積微之所生也，故聖人自治於未有形也，愚者遭其已成也。","sortOrder":3},
  {"id":"s_work_hdnk_139_4","chapterId":"ch_work_hdnk_139","text":"黃帝曰：其已形，不予遭，膿已成，不予見；為之奈何？岐伯曰：膿已成，十死一生，故聖人弗使已成，而明為良方，著之竹帛，使能者踵而傳之後世，無有終時者，為其不予遭也。","sortOrder":4},
  {"id":"s_work_hdnk_139_5","chapterId":"ch_work_hdnk_139","text":"黃帝曰：其已有膿血而後遭乎？不導之以小針治乎？岐伯曰：以小治小者，其功小，以大治大者，多害，故其已成膿血者，其唯砭石鈹鋒之所取也。","sortOrder":5},
  {"id":"s_work_hdnk_139_6","chapterId":"ch_work_hdnk_139","text":"黃帝曰：多害者其不可全乎？岐伯曰：其在逆順焉。黃帝曰：願聞逆順。岐伯曰：以為傷者，其白眼青，黑眼小，是一逆也；內藥而嘔者，是二逆也；腹痛渴甚，是三逆也；肩項中不便，是四逆也；音嘶色脫，是五逆也。除此五者，為順矣。","sortOrder":6},
  {"id":"s_work_hdnk_139_7","chapterId":"ch_work_hdnk_139","text":"黃帝曰：諸病皆有逆順，可得聞乎？岐伯曰：腹脹、身熱、脈大，是一逆也；腹鳴而滿，四肢清泄，其脈大，是二逆也；衄而不止，脈大，是三逆也；咳而溲血脫形，其脈小勁，是四逆也；咳脫形，身熱，脈小以疾，是謂五逆也。如是者，不過十五日而死矣。","sortOrder":7},
  {"id":"s_work_hdnk_139_8","chapterId":"ch_work_hdnk_139","text":"其腹大脹，四末清，脫形，泄甚，是一逆也；腹脹便血，其脈大，時絕，是二逆也；咳溲血，形肉脫，脈搏，是三逆也；嘔血，胸滿引背，脈小而疾，是四逆也；咳嘔，腹脹且飧泄，其脈絕，是五逆也。如是者，不及一時而死矣。工不察此者而刺之，是謂逆治。","sortOrder":8},
  {"id":"s_work_hdnk_139_9","chapterId":"ch_work_hdnk_139","text":"黃帝曰：夫子之言針甚駿，以配天地，上數天文，下度地紀，內別五臟，外次六腑，經脈二十八會，盡有周紀。能殺生人，不能起死者，子能反之乎？岐伯曰：能殺生人，不能起死者也。黃帝曰：餘聞之，則為不仁，然願聞其道，弗行於人。岐伯曰：是明道也，其必然也，其如刀劍之可以殺人，如飲酒使人醉也，雖勿診，猶可知矣。","sortOrder":9},
  {"id":"s_work_hdnk_139_10","chapterId":"ch_work_hdnk_139","text":"黃帝曰：願卒聞之。岐伯曰：人之所受氣者，穀也。穀之所註者，胃也。胃者，水穀氣血之海也。海之所行雲氣者，天下也。胃之所出氣血者，經隧也。而隧者，五臟六腑之大絡也，迎而奪之而已矣。","sortOrder":10},
  {"id":"s_work_hdnk_139_11","chapterId":"ch_work_hdnk_139","text":"黃帝曰：上下有數乎？岐伯曰：迎之五里，中道而止，五至而已，五往而臟之氣盡矣，故五五二十五，而竭其輸矣，此所謂奪其天氣者也，非能絕其命而傾其壽者也。黃帝曰：願卒聞之。岐伯曰：闚門而刺之者，死於家中；入門而刺之者，死於堂上。黃帝曰：善乎方，明哉道，請著之玉版，以為重寶，傳之後世，以為刺禁，令民勿敢犯也。","sortOrder":11},
  {"id":"s_work_hdnk_140_1","chapterId":"ch_work_hdnk_140","text":"五禁第六十一","sortOrder":1},
  {"id":"s_work_hdnk_140_2","chapterId":"ch_work_hdnk_140","text":"黃帝問於岐伯曰：餘聞刺有五禁，何謂五禁？岐伯曰：禁其不可刺也。黃帝曰：餘聞刺有五奪。岐伯曰：無瀉其不可奪者也。黃帝曰：餘聞刺有五過。岐伯曰：補瀉無過其度。黃帝曰：餘聞刺有五逆。岐伯曰：病與脈相逆，命曰五逆。黃帝曰：餘聞刺有九宜。岐伯曰：明知九針之論，是謂九誼。","sortOrder":2},
  {"id":"s_work_hdnk_140_3","chapterId":"ch_work_hdnk_140","text":"黃帝曰：何謂五禁，願聞其不可刺之時。岐伯曰：甲乙日自乘，無刺實，無發蒙於耳內。丙丁日自乘，無振埃於肩喉廉泉。戊己日自乘四季，無刺腹，去爪瀉水。庚辛日自乘，無刺關節於股膝。壬癸日自乘，無刺足脛，是謂五禁。","sortOrder":3},
  {"id":"s_work_hdnk_140_4","chapterId":"ch_work_hdnk_140","text":"黃帝曰：何謂五奪？岐伯曰：形肉已奪，是一奪也；大奪血之後，是二奪也；大汗出之後，是三奪也；大泄之後，是四奪也；新產及大血之後，是五奪也。此皆不可瀉。","sortOrder":4},
  {"id":"s_work_hdnk_140_5","chapterId":"ch_work_hdnk_140","text":"黃帝曰：何謂五逆？岐伯曰：熱病脈靜，汗已出，脈盛躁，是一逆也；病泄，脈洪大，是二逆也；著痺不移〈月困〉肉破，身熱，脈偏絕，是三逆也；淫而奪形、身熱，色夭然白，乃後下血衄，血衄篤重，是謂四逆也；寒熱奪形，脈堅搏，是謂五逆也。","sortOrder":5},
  {"id":"s_work_hdnk_141_1","chapterId":"ch_work_hdnk_141","text":"動輸第六十二","sortOrder":1},
  {"id":"s_work_hdnk_141_2","chapterId":"ch_work_hdnk_141","text":"黃帝曰：經脈十二，而手太陰、足少陰、陽明，獨動不休，何也？岐伯曰：是明胃脈也。胃為五臟六腑之海，其清氣上註於肺，肺氣從太陰而行之，其行也，以息往來，故人一呼，脈再動，一吸脈亦再動，呼吸不已，故動而不止。","sortOrder":2},
  {"id":"s_work_hdnk_141_3","chapterId":"ch_work_hdnk_141","text":"黃帝曰：氣之過於寸口也，上十焉息，下八焉伏，何道從還？不知其極。","sortOrder":3},
  {"id":"s_work_hdnk_141_4","chapterId":"ch_work_hdnk_141","text":"岐伯曰：氣之離臟也，卒然如弓弩之發，如水之下岸，上於魚以及衰，其餘氣衰散以逆上，故其行微。","sortOrder":4},
  {"id":"s_work_hdnk_141_5","chapterId":"ch_work_hdnk_141","text":"黃帝曰：足之陽明，何因而動？岐伯曰：胃氣上註於肺，其悍氣上沖頭者，循咽，上走空竅，循眼系，入絡腦，出顑，下客主人，循牙車，合陽明，併下人迎，此胃氣別走於陽明者也。故陰陽上下，其動也若一。故陽病而陽脈小者，為逆；陰病而陰脈大者，為逆。故陰陽俱靜俱動，若引繩相傾者病。","sortOrder":5},
  {"id":"s_work_hdnk_141_6","chapterId":"ch_work_hdnk_141","text":"黃帝曰：足少陰何因而動？岐伯曰：沖脈者，十二經之海也，與少陰之大絡，起於腎下，出於氣街，循陰股內廉，邪入膕中，循脛骨內廉，併少陰之經，下入內踝之後。入足下，其別者，邪入踝，出屬附上，入大指之間，註諸絡，以溫足脛，此脈之常動者也。","sortOrder":6},
  {"id":"s_work_hdnk_141_7","chapterId":"ch_work_hdnk_141","text":"黃帝曰：營衛之行也，上下相貫，如環之無端，今有其卒然遇邪風，及逢大寒，手足懈惰，其脈陰陽之道，相輸之會，行相失也，氣何由還？岐伯曰：夫四末陰陽之會者，此氣之尤絡也；四街者，氣之徑路也。故絡絕則徑通，四末解則氣從合，相輸如環。黃帝曰：善。此所謂如環無端，莫知其紀，終而復始，此之謂也。","sortOrder":7},
  {"id":"s_work_hdnk_142_1","chapterId":"ch_work_hdnk_142","text":"五味論第六十三","sortOrder":1},
  {"id":"s_work_hdnk_142_2","chapterId":"ch_work_hdnk_142","text":"黃帝問於少俞曰：五味入於口也，各有所走，各有所病，酸走筋，多食之，令人癃；鹹走血，多食之，令人渴；辛走氣，多食之，令人洞心；苦走骨，多食之，令人變嘔；甘走肉，多食之，令人挽心。餘知其然也，不知其何由？願聞其故。少俞答曰：酸入於胃，其氣澀以收，上之兩焦，弗能出入也，不出即留於胃中，胃中和溫，則下註膀胱，膀胱之胞薄以懦，得酸則縮綣，約而不通，水道不行，故癃。陰者，積筋之所終也，故酸入而走筋矣。","sortOrder":2},
  {"id":"s_work_hdnk_142_3","chapterId":"ch_work_hdnk_142","text":"黃帝曰：鹹走血，多食之，令人渴，何也？少俞曰：鹹入於胃；其氣上走中焦，註於脈，則血氣走之，血與鹹相得，則凝，凝則胃中汁註之，註之則胃中竭，竭則咽路焦，故舌本幹而善渴。血脈者，中焦之道也，故鹹入而走血矣。","sortOrder":3},
  {"id":"s_work_hdnk_142_4","chapterId":"ch_work_hdnk_142","text":"黃帝曰：辛走氣，多食之，令人洞心，何也？少俞曰：辛入於胃，其氣走於上焦，上焦者，受氣而營諸陽者也，薑韭之氣熏之，營衛之氣，不時受之，久留心下，故洞心。辛與氣俱行，故辛入而與汗俱出。","sortOrder":4},
  {"id":"s_work_hdnk_142_5","chapterId":"ch_work_hdnk_142","text":"黃帝曰：「苦走骨，多食之，令人變嘔，何也？」少俞曰：苦入於胃，五穀之氣，皆不能勝苦，苦入下脘，三焦之道，皆閉而不通，故變嘔。齒者，骨之所終也，故苦入而走骨，故入而復出，知其走骨也。","sortOrder":5},
  {"id":"s_work_hdnk_142_6","chapterId":"ch_work_hdnk_142","text":"黃帝曰：甘走肉，多食之。令人悗心，何也？少俞曰：甘入於胃，其氣弱小，不能上至於上焦，而與穀留於胃中者，令人柔潤者也，胃柔則緩，緩則蟲動，蟲動則令人悗心。其氣外通於肉，故甘走肉。","sortOrder":6},
  {"id":"s_work_hdnk_143_1","chapterId":"ch_work_hdnk_143","text":"陰陽二十五人第六十四","sortOrder":1},
  {"id":"s_work_hdnk_143_2","chapterId":"ch_work_hdnk_143","text":"黃帝曰：餘聞陰陽之人何如？伯高曰：天地之間，六合之內，不離於五，人亦應之。故五五二十五人之政，而陰陽之人不與焉。其態又不合於眾者五，餘已知之矣。願聞二十五人之形，血氣之所生，別而以候，從外知內，何如？岐伯曰：「悉乎哉問也，此先師之秘也，雖伯高猶不能明之也。黃帝避席遵循而卻曰：餘聞之得其人弗教，是謂重失，得而泄之，天將厭之，餘願得而明之，金櫃藏之，不敢揚之。岐伯曰：先立五形金木水火土，別其五色，異其五形之人，而二十五人具矣。黃帝曰：願卒聞之。岐伯曰：慎之慎之，臣請言之。","sortOrder":2},
  {"id":"s_work_hdnk_143_3","chapterId":"ch_work_hdnk_143","text":"木形之人，比於上角似於蒼帝，其為人蒼色，小頭，長面大肩背直身小，手足好。有才，勞心少力多憂，勞於事，能春夏不能秋冬感而病生。足厥陰，佗佗然，大角之人比於左足少陽，少陽之上遺遺然。左角之人比於右足少陽，少陽之下隨隨然。鈦角之人，比於右足少陽，少陽之上推推然。判角之人比於左足少陽，少陽之下枯枯然。","sortOrder":3},
  {"id":"s_work_hdnk_143_4","chapterId":"ch_work_hdnk_143","text":"火形之人，比於上徵，似於赤帝。其為人赤色廣〈月引〉脫面小頭，好肩背，髀腹小手足，行安地疾心，行搖肩背肉滿。有氣輕財少信多慮，見事明好顏，急心不壽暴死。能春夏不能秋冬，秋冬感而病生，手少陰核核然。質徵之人，比於左手太陽，太陽之上，肌肌然，少徵之人比於右手太陽，太陽之下〈巾臽〉〈巾臽〉然，右徵之人比於右手太陽，太陽之上鮫鮫然。質判之人，比於左手太陽，太陽之下支支頤頤然。","sortOrder":4},
  {"id":"s_work_hdnk_143_5","chapterId":"ch_work_hdnk_143","text":"形於之人，比於上宮，似於上古黃帝，其為人黃色圓面、大頭、美肩背、大腹、美股脛、小手足、多肉、上下相稱行安地，舉足浮。安心，好利人不喜權勢，善附人也。能秋冬不能春夏，春夏感而病生，足太陰，敦敦然。大宮之人比於左足陽明，陽明之上婉婉然。加宮之人，比於左足陽明，陽明之下坎坎然。少宮之人，比於右足陽明，陽明之上，樞樞然。左宮之人，比於右足陽明，陽明之下，兀兀然。","sortOrder":5},
  {"id":"s_work_hdnk_143_6","chapterId":"ch_work_hdnk_143","text":"金形之人比於上商，似於白帝，其為人方面白色、小頭、小肩背小腹、小手足如骨發踵外，骨輕。身清廉，急心靜悍，善為吏，能秋冬，不能春夏，春夏感而病生。手太陰敦敦然，釱商之人比於左手陽明，陽明之上，廉廉然。右商之人，比於左手陽明，陽明之下脫脫然。左商之人比於右手陽明，陽明之上監監然。少商之人，比於右手陽明，陽明之下，嚴嚴然。","sortOrder":6},
  {"id":"s_work_hdnk_143_7","chapterId":"ch_work_hdnk_143","text":"水形之人，比於上羽，似於黑帝，其為人，黑色面不平，大頭廉頤，小肩大腹動手足，發行搖身下尻長，背延延然。不敬畏善欺紹人，戮死。能秋冬不能春夏，春夏感而病生。足少陰汗汗然。大羽之人，比於右足太陽，太陽之上，頰頰然。少羽之人，比於左足太陽，太陽之下潔潔然。桎之為人，比於左足太陽，太陽之上安安然。是故五形之人二十五變者，眾之所以相欺者是也。","sortOrder":7},
  {"id":"s_work_hdnk_143_8","chapterId":"ch_work_hdnk_143","text":"黃帝曰：得其形，不得其色何如？岐伯曰：形勝色，色勝形者，至其勝時年加，感則病行，失則憂矣。形色相得者，富貴大樂。黃帝曰：其形色相當勝之時，年加可知乎？岐伯曰：凡年忌下上之人，大忌常加七歲，十六歲、二十五歲、三十四歲、四十三歲、五十二歲、六十一歲皆人之大忌，不可不自安也，感則病行，失則憂矣，當此之時，無為姦事，是謂年忌。","sortOrder":8},
  {"id":"s_work_hdnk_143_9","chapterId":"ch_work_hdnk_143","text":"黃帝曰：夫子之言脈之上下，血氣之候似知形氣，奈何？岐伯曰：足陽明之上血氣盛則髯美長，血少氣多則髯短，故氣少血多則髯少，血氣皆少則無髯。兩吻多畫，足陽明之下血氣盛則下毛美長至胸，血多氣少則下毛美短至臍，行則善高舉足，足趾少肉足善寒，血少氣多則肉而善瘃，血氣皆少則無毛有則稀、枯悴，善痿厥，足痺。","sortOrder":9},
  {"id":"s_work_hdnk_143_10","chapterId":"ch_work_hdnk_143","text":"足少陽之上，氣血盛則通髯美長，血多氣少則通髯美短，血少氣多則少髯，血氣皆少則無鬚，感於寒濕則善痺。骨痛爪枯也。足少陽之下，血氣盛則脛毛美長，外踝肥；血多氣少則脛毛美短，外踝皮堅而厚，血少氣多則胻毛少，外踝皮薄而軟，血氣皆少則無毛，外踝瘦無肉。","sortOrder":10},
  {"id":"s_work_hdnk_143_11","chapterId":"ch_work_hdnk_143","text":"足太陽之上，血氣盛則美眉，眉有毫毛血多氣少則惡眉，面多少理，血少氣多則面多肉，血氣和則美色，足太陽之下，血氣盛則肉滿，踵堅，氣少血多則瘦，跟空，血氣皆少則善轉筋，踵下痛。","sortOrder":11},
  {"id":"s_work_hdnk_143_12","chapterId":"ch_work_hdnk_143","text":"手陽明之上，血氣盛則髭美。血少氣多則髭惡，血氣皆少則無髭。手陽明之下血氣盛則腋下毛美，手魚肉以溫，氣血皆少則手瘦以寒。","sortOrder":12},
  {"id":"s_work_hdnk_143_13","chapterId":"ch_work_hdnk_143","text":"手少陰之上，血氣盛則眉美以長，耳色美，血氣皆少則耳焦惡色。手少陽之下，血氣盛則手卷多肉以溫，血氣皆少則寒以瘦，氣少血多則瘦以多脈。","sortOrder":13},
  {"id":"s_work_hdnk_143_14","chapterId":"ch_work_hdnk_143","text":"手太陽之上，血氣盛則多鬚，面多肉以平，血氣皆少則面瘦惡色。手太陽之下，血氣盛則掌肉充滿，血氣皆少則掌瘦以寒。","sortOrder":14},
  {"id":"s_work_hdnk_143_15","chapterId":"ch_work_hdnk_143","text":"黃帝曰：二十五人者，刺之有約乎？岐伯曰：美眉者，足太陽之脈，氣血多，惡眉者，血氣少，其肥而澤者，血氣有餘，肥而不澤者，氣有餘，血不足，瘦而無澤者，氣血俱不足，審察其形氣有餘不足而調之，可以知逆順矣。","sortOrder":15},
  {"id":"s_work_hdnk_143_16","chapterId":"ch_work_hdnk_143","text":"黃帝曰：刺其諸陰陽奈何？岐伯曰：按其寸口人迎，以調陰陽，切循其經絡之凝澀，結而不通者，此於身皆為痛痺，甚則不行，故凝澀，凝澀者，致氣以溫之血和乃止。其結絡者，脈結血不和，決之乃行，故曰：氣有餘於上者，導而下之，氣不足於上者，推而休之，其稽留不至者，因而迎之，必明於經隧，乃能持之，寒與熱爭者，導而行之，其宛陳血不結者，則而予之，必先明知二十五人則血氣之所在，左右上下，刺約畢也。","sortOrder":16},
  {"id":"s_work_hdnk_144_1","chapterId":"ch_work_hdnk_144","text":"五音五味第六十五","sortOrder":1},
  {"id":"s_work_hdnk_144_2","chapterId":"ch_work_hdnk_144","text":"右徵與少徵，調右手太陽二，左商與左徵，調左手陽明上。少徵與大宮，調左手陽明上，右角與大角，調右手少陽下。大徵與少徵，調左手太陽上，眾羽與少羽，調右足太陽下，少商與右商調右手太陽下，桎羽與眾羽，調右足太陽下，少宮與大宮，調右足陽明下，判角與少角，調右足少陽下，釱商與上商，調右足陽明下，釱商與上角，調左足太陽下。","sortOrder":2},
  {"id":"s_work_hdnk_144_3","chapterId":"ch_work_hdnk_144","text":"上徵與右徵同穀麥、畜羊、果杏，手少陰藏心，色赤味苦，時夏。上羽與大羽，同穀大豆，畜彘，果栗，足少陰藏腎，色黑味鹹，時冬。上宮與大宮同穀稷，畜牛，果棗，足太陰藏脾，色黃味甘，時季夏。上商與右商同穀黍，畜雞，果桃，手太陰藏肺，色白味辛，時秋。上角與大角，同穀麻、畜犬、果李，足厥陰藏肝，色青味酸，時春。","sortOrder":3},
  {"id":"s_work_hdnk_144_4","chapterId":"ch_work_hdnk_144","text":"大宮與上角，同右足陽明上，左角與大角，同左足陽明上，少羽與大羽同右足太陽下，左商與右商，同左手陽明上，加宮與大宮同左足少陽上，質判與大宮，同左手太陽下，判角與大角同左足少陽下，大羽與大角，同右足太陽上，大角與大宮同右足少陽上，右徵、少徵、質徵、上徵、判徵、右角、釱角、上角、大角、判角。右商、少商、釱商、上商、左商。少宮、上宮、大宮、加宮、左角宮。眾羽、桎羽、上羽、大羽、少羽。","sortOrder":4},
  {"id":"s_work_hdnk_144_5","chapterId":"ch_work_hdnk_144","text":"黃帝曰：婦人無鬚者，無血氣乎？岐伯曰：沖脈任脈皆起於胞中，上循背裏，為經絡之海，其浮而外者，循腹右上行，會於咽喉，別而絡唇口，血氣盛則充膚熱肉，血獨盛者澹滲皮膚，生毫毛。今婦人之生有餘於氣，不足於血以其數脫血也，沖任之脈，不榮口唇，故鬚不生焉。","sortOrder":5},
  {"id":"s_work_hdnk_144_6","chapterId":"ch_work_hdnk_144","text":"黃帝曰：士人有傷於陰，陰氣絕而不起，陰不用，然其鬚不去，其故何也？宦者獨去何也？願聞其故。岐伯曰：宦者去其宗筋，傷其沖脈，血瀉不復，皮膚內結，唇口內榮故鬚不生。","sortOrder":6},
  {"id":"s_work_hdnk_144_7","chapterId":"ch_work_hdnk_144","text":"黃帝曰：其有天宦者，未嘗被傷，不脫於血，然其鬚不生其故何也？岐伯曰：此天之所不足也，其任沖不盛、宗筋不成，有氣無血，唇口不榮，故鬚不生。","sortOrder":7},
  {"id":"s_work_hdnk_144_8","chapterId":"ch_work_hdnk_144","text":"黃帝曰：善乎哉！聖人之通萬物也，若日月之光影，音聲鼓響，聞其聲而知其形，其非夫子，孰能明萬物之精。是故聖人，視其顏色黃赤者，多熱氣，青白者少熱氣，黑色者多血少氣，美眉者，太陽多血；通髯極須者，少陽多血，美鬚者陽明多血，此其時然也。","sortOrder":8},
  {"id":"s_work_hdnk_144_9","chapterId":"ch_work_hdnk_144","text":"夫人之常數，太陽常多血少氣，少陽常多氣少血，陽明常多血多氣，厥陰常多氣少血，少陰常多血少氣，太陰常多血少氣，此天之常數也。","sortOrder":9},
  {"id":"s_work_hdnk_145_1","chapterId":"ch_work_hdnk_145","text":"百病始生第六十六","sortOrder":1},
  {"id":"s_work_hdnk_145_2","chapterId":"ch_work_hdnk_145","text":"黃帝問於岐伯曰：夫百病之始生也，皆於風雨寒暑，清濕喜怒，喜怒不節則傷臟，風雨則傷上，清濕則傷下。三部之氣所傷異類，願聞其會，岐伯曰：三部之氣各不同或起於陰或起於陽請言其方，喜怒不節則傷臟，臟傷則病起於陰也，清濕襲虛，則病起於下，風雨襲虛，則病起於上，是謂三部，至於其淫泆，不可勝數。","sortOrder":2},
  {"id":"s_work_hdnk_145_3","chapterId":"ch_work_hdnk_145","text":"黃帝曰：餘固不能數，故問先師願卒聞其道，岐伯曰：風雨寒熱不得虛，邪不能獨傷人。卒然逢疾風暴雨而不病者，蓋無虛，故邪不能獨傷人。此必因虛邪之風，與其身形，兩虛相得，乃客其形。兩實相逢，眾人肉堅，其中於虛邪也因於天時，與其身形，參以虛實，大病乃成，氣有定舍，因處為名，上下中外，分為三員。","sortOrder":3},
  {"id":"s_work_hdnk_145_4","chapterId":"ch_work_hdnk_145","text":"是故虛邪之中人也，始於皮膚，皮膚緩則腠理開，開則邪從毛發入，入則抵深，深則毛髮立，毛髮立則淅然，故皮膚痛。留而不去，則傳舍於絡脈，在絡之時，痛於肌肉，故痛之時息，大經代去，留而不去，傳舍於經，在經之時，洒淅喜驚。留而不去，傳舍於俞，在俞之時，六經不通四肢，則肢節痛，腰脊乃強，留而不去，傳舍於伏沖之脈，在伏沖之時體重身痛，留而不去，傳舍於腸胃，在腸腎之時，賁響腹脹，多寒則腸鳴飧泄，食不化，多熱則溏出糜。留而不去，傳舍於腸胃之外，募原之間，留著於脈，稽留而不去，息而成積，或著孫脈，或著絡脈，或著經脈，或著俞脈，或著於伏沖之脈，或著於膂筋，或著於腸胃之募原，上連於緩筋，邪氣淫泆，不可勝論。","sortOrder":4},
  {"id":"s_work_hdnk_145_5","chapterId":"ch_work_hdnk_145","text":"黃帝曰：願盡聞其所由然。岐伯曰：其著孫絡之脈而成積者，其積往來上下，臂小孫絡之居也，浮而緩，不能句積而止之，故往來移行腸胃之間，水湊滲註灌，濯濯有音，有寒則〈月真〉，〈月真〉滿雷引，故時切痛，其著於陽明之經則挾臍而居，飽食則益大，飢則益小。其著於緩筋也，似陽明之積，飽食則痛，飢則安。其著於腸胃之募原也，痛而外連於緩筋，飽食則安，飢則痛。其著於伏沖之脈者，揣之應手而動，發手則熱氣下於兩股，如湯沃之狀。其著於膂筋，在腸後者飢則積見，飽則積不見，按之不得。其著於輸之脈者，閉塞不通，津液不下，孔竅幹壅，此邪氣之從外入內，從上下也。","sortOrder":5},
  {"id":"s_work_hdnk_145_6","chapterId":"ch_work_hdnk_145","text":"黃帝曰：積之始生，至其已成，奈何？岐伯曰：積之始生，得寒乃生，厥乃成積也，黃帝曰：其成積奈何？岐伯曰：厥氣生足悗，悗生脛寒，脛寒則血脈凝澀，血脈凝澀則寒氣上入於腸胃，入於腸胃則〈月真〉脹，〈月真〉脹則腸外之汁沫迫聚不得散，日以成積。卒然多食飲，則腸滿，起居不節，用力過度，則絡脈傷，陽絡傷則血外溢，血外溢則衄血，陰絡傷則血內溢，血內溢則後血。腸胃之絡傷則血溢於腸外，腸外有寒，汁沫與血相搏，則併合凝聚不得散，而積成矣。卒然中外於寒，若內傷於憂怒，則氣上逆，氣上逆則六俞不通，溫氣不行，凝血蘊裏而不散，津液澀滲，著而不去，而積皆成矣。","sortOrder":6},
  {"id":"s_work_hdnk_145_7","chapterId":"ch_work_hdnk_145","text":"黃帝曰：其生於陰者，奈何？岐伯曰：憂思傷心，重寒傷肺，忿怒傷肝，醉以入房，汗出當風傷脾，用力過度，若入房汗出洛，則傷腎，此內外三部之所生病者也。","sortOrder":7},
  {"id":"s_work_hdnk_145_8","chapterId":"ch_work_hdnk_145","text":"黃帝曰：善治之奈何？岐伯答曰：察其所痛，以知其應，有餘不足，當補則補，當瀉則瀉，毋逆天時，是謂至治。","sortOrder":8},
  {"id":"s_work_hdnk_146_1","chapterId":"ch_work_hdnk_146","text":"行鍼第六十七","sortOrder":1},
  {"id":"s_work_hdnk_146_2","chapterId":"ch_work_hdnk_146","text":"黃帝問於岐伯曰：餘聞九針於夫子，而行之於百姓，百姓之血氣，各不同形，或神動而氣先針行；或氣與針相逢；或針已出，氣獨行；或數刺乃知；或發針而氣逆；或數刺病益劇。凡此六者，各不同形，願聞其方。","sortOrder":2},
  {"id":"s_work_hdnk_146_3","chapterId":"ch_work_hdnk_146","text":"岐伯曰：重陽之人，其神易動，其氣易往也。黃帝曰：何謂重陽之人？岐伯曰：重陽之人，熇熇高高，言語善疾，舉足善高，心肺之臟氣有餘，陽氣滑盛而揚，故神動而氣先行。","sortOrder":3},
  {"id":"s_work_hdnk_146_4","chapterId":"ch_work_hdnk_146","text":"黃帝曰：重陽之人而神不先行者，何也？岐伯曰：此人頗有陰者也。黃帝曰：何以知其頗有陰者也。岐伯曰：多陽者，多喜；多陰者，多怒，數怒者，易解，故曰頗有陰。其陰陽之離合難，故其神不能先行也。","sortOrder":4},
  {"id":"s_work_hdnk_146_5","chapterId":"ch_work_hdnk_146","text":"黃帝曰：其氣與針相逢，奈何？岐伯曰：陰陽和調，而血氣淖澤滑利，故針入而氣出，疾而相逢也。","sortOrder":5},
  {"id":"s_work_hdnk_146_6","chapterId":"ch_work_hdnk_146","text":"黃帝曰：針已出而氣獨行者，何氣使然？岐伯曰：其陰氣多而陽氣少，陰氣沉而陽氣浮者內藏，故針已出，氣乃隨其後，故獨行也。","sortOrder":6},
  {"id":"s_work_hdnk_146_7","chapterId":"ch_work_hdnk_146","text":"黃帝曰：數刺乃知，何氣使然？岐伯曰：此人之多陰而少陽，其氣沉而氣往難，故數刺乃知也。","sortOrder":7},
  {"id":"s_work_hdnk_146_8","chapterId":"ch_work_hdnk_146","text":"黃帝曰：針入而氣逆者，何氣使然？岐伯曰：其氣逆與其數刺病益甚者，非陰陽之氣，浮沉之勢也。此皆麤之所敗，工之所失，其形氣無過焉。","sortOrder":8},
  {"id":"s_work_hdnk_147_1","chapterId":"ch_work_hdnk_147","text":"上膈第六十八","sortOrder":1},
  {"id":"s_work_hdnk_147_2","chapterId":"ch_work_hdnk_147","text":"黃帝曰：氣為上膈者，食飲入而還出，餘已知之矣。蟲為下膈。下膈者，食焠時乃出，餘未得其意，願卒聞之。岐伯曰：喜怒不適，食飲不節，寒溫不時，則寒汁流於腸中。流於腸中則蟲寒，蟲寒則積聚，守於下管，則腸胃充郭，衛氣不營，邪氣居之。人食則蟲上食，蟲上食則下管虛，下管虛則邪氣勝之，積聚以留，留則癰成，癰成則下管約。其癰在管內者，即而痛深，其癰在外者，則癰外而痛浮，癰上皮熱。","sortOrder":2},
  {"id":"s_work_hdnk_147_3","chapterId":"ch_work_hdnk_147","text":"黃帝曰：刺之奈何？岐伯曰：微按其癰，視氣所行，先淺刺其傍，稍內益深，逐而刺之，毋過三行，察其沈浮，以為深淺。已刺必熨，令熱入中，日使熱內，邪氣益衰，大癰乃潰。伍以參禁，以除其內，恬憺無為，乃能行氣，後以鹹苦，化穀乃下矣。","sortOrder":3},
  {"id":"s_work_hdnk_148_1","chapterId":"ch_work_hdnk_148","text":"憂恚無言第六十九","sortOrder":1},
  {"id":"s_work_hdnk_148_2","chapterId":"ch_work_hdnk_148","text":"黃帝問於少師曰：人之卒然憂恚，而言無音者，何道之塞？何氣出行？使音不彰？願聞其方。少師答曰：咽喉者，水穀之道也。喉嚨者，氣之所以上下者也。會厭者，聲音之戶也。口唇者，聲音之扇也。舌者，聲音之機也。懸壅垂者，聲音之關者。頏顙者，分氣之所泄也。橫骨者，神氣所使主發舌者也。故人之鼻洞涕出不收者，頏顙不開，分氣失也。是故厭小而疾薄，則發氣疾，其開闔利，其出氣易，其厭大而厚，則開闔難，其氣出遲，故重言也。人卒然無音者，寒氣客於厭，則厭不能發，發不能下，至其開闔不致，故無音。","sortOrder":2},
  {"id":"s_work_hdnk_148_3","chapterId":"ch_work_hdnk_148","text":"黃帝曰：刺之奈何？岐伯曰：足之少陰，上係於舌，絡於橫骨，終於會厭。兩瀉其血脈，濁氣乃避。會厭之脈，上絡任脈，取之天突，其厭乃發也。","sortOrder":3},
  {"id":"s_work_hdnk_149_1","chapterId":"ch_work_hdnk_149","text":"寒熱第七十","sortOrder":1},
  {"id":"s_work_hdnk_149_2","chapterId":"ch_work_hdnk_149","text":"黃帝問於岐伯曰：寒熱瘰癧在於頸腋者，皆何氣使生？岐伯曰：此皆鼠瘻寒熱之毒氣也，留於脈而不去者也。","sortOrder":2},
  {"id":"s_work_hdnk_149_3","chapterId":"ch_work_hdnk_149","text":"黃帝曰：去之奈何？岐伯曰：鼠瘻之本，皆在於臟，其末上出於頸腋之間，其浮於脈中，而未內著於肌肉，而外為膿血者，易去也。","sortOrder":3},
  {"id":"s_work_hdnk_149_4","chapterId":"ch_work_hdnk_149","text":"黃帝曰：去之奈何？岐伯曰：請從其本引其末，可使衰去，而絕其寒熱。審按其道以予之，徐往徐來以去之，其小如麥者，一刺知，三刺而已。","sortOrder":4},
  {"id":"s_work_hdnk_149_5","chapterId":"ch_work_hdnk_149","text":"黃帝曰：決其生死奈何？岐伯曰：反其目視之，其中有赤脈，上下貫瞳子，見一脈，一歲死；見一脈半，一歲半死；見二脈，二歲死；見二脈半，二歲半死；見三脈，三歲而死。見赤脈不下貫瞳子，可治也。","sortOrder":5},
  {"id":"s_work_hdnk_150_1","chapterId":"ch_work_hdnk_150","text":"邪客第七十一","sortOrder":1},
  {"id":"s_work_hdnk_150_2","chapterId":"ch_work_hdnk_150","text":"黃帝問於伯高曰：夫邪氣之客人也，或令人目不瞑不臥出者，何氣使然？伯高曰：五穀入於胃也，其糟粕津液宗氣，分為三隧。故宗氣積於胸中，出於喉嚨，以貫心脈，而行呼吸焉。營氣者，泌其津液，註之於脈，化以為血，以榮四末，內註五臟六腑，以應刻數焉。節氣者，出其悍氣之慓疾，而先行於四末分肉皮膚之間，而不休者也。晝日行於陽，夜行於陰，常從足少陰之分間，行五臟六腑，今厥氣客於五臟六腑，則衛氣獨衛其外，行於陽，不得入於陰。行於陽則陽氣盛，陽氣盛則陽橋陷，不得入於陰，陰虛，故目不瞑。","sortOrder":2},
  {"id":"s_work_hdnk_150_3","chapterId":"ch_work_hdnk_150","text":"黃帝曰：善。治之奈何？伯高曰：補其不足，瀉其有餘，調其虛實，以通其道，而去其邪。飲以半夏湯一劑，陰陽已通，其臥立至。黃帝曰：善。此所謂決瀆壅塞，經絡大通，陰陽和得者也。願聞其方。伯高曰：其湯方以流水千里以外者八升，揚之萬遍，取其清五升，煮之，炊以葦薪火，沸置秫米一升，治半夏五合，徐炊，令竭為一升半，去其滓，飲汁一小杯，日三稍益，以知為度，故其病新發者，復杯則臥，汗出則已矣。久者，三飲而已也。","sortOrder":3},
  {"id":"s_work_hdnk_150_4","chapterId":"ch_work_hdnk_150","text":"黃帝問於伯高曰：願聞人之肢節以應天地奈何？伯高答曰：天圓地方，人頭圓足方以應之。天有日月，人有兩目；地有九州，人有九竅；天有風雨，人有喜怒；天有雷電，人有聲音；天有四時，人有四肢；天有五音，人有五臟；天有六律，人有六腑；天有冬夏，人有寒熱；天有十曰，人有手十指；辰有十二，人有足十指，莖垂以應之，女子不足二節，以抱人形；天有陰陽，人有夫妻；歲有三百六十五日，人有三百六十五節；地有高山，人有肩膝；地有深穀，人有腋膕；地有十二經水，人有十二經脈；地有泉脈，人有衛氣；地有草蓂，人有毫毛；天有晝夜，人有臥起；天有列星，人有牙齒；地有小山，人有小節；地有山石，人有高骨；地有林木，人有募筋；地有聚邑，人有膕肉；歲有十二月，人有十二節；地有四時不生草，人有無子。此人與天地相應者也。","sortOrder":4},
  {"id":"s_work_hdnk_150_5","chapterId":"ch_work_hdnk_150","text":"黃帝問於岐伯曰：餘願聞持針之數，內針之理，縱舍之意，扞皮開腠理，奈何？脈之屈折，出入之處，焉至而出，焉至而止，焉至而徐，焉至而疾，焉至而入，六腑之輸於身者，餘願盡聞其方。岐伯曰：帝之所問，針道畢矣。","sortOrder":5},
  {"id":"s_work_hdnk_150_6","chapterId":"ch_work_hdnk_150","text":"黃帝曰：願卒聞之。岐伯曰：手太陰之脈，出於大指之端，內屈，循白肉際，至本節之後太淵，留以澹，外屈，上於本節下，內屈，與陰諸絡會於魚際，數脈並註，其氣滑利，伏行壅骨之下，外屈，出於寸口而行，上至於肘內廉，入於大筋之下，內屈，上行臑陰，入腋下，內屈，走肺。此順行逆數之屈折也。心主之脈，出於中指之端，內屈，循中指內廉以上，留於掌中，伏行兩骨之間，外屈，出兩筋之間，上至肘內廉，入於小筋之下，留兩骨之會，上入於胸中，內絡於心脈。","sortOrder":6},
  {"id":"s_work_hdnk_150_7","chapterId":"ch_work_hdnk_150","text":"黃帝曰：手太陰之脈，獨無俞，何也？岐伯曰：少陰，心脈也。心者，五臟六腑之大主也，精神之所舍也，其臟堅固，邪弗能容也。容之則心傷，心傷則神去，神去則死矣。故諸邪之在於心者，皆在於心之包絡。包絡者，心主之脈也，故獨無俞焉。","sortOrder":7},
  {"id":"s_work_hdnk_150_8","chapterId":"ch_work_hdnk_150","text":"黃帝曰：少陰獨無俞者，不病乎？岐伯曰：其外經病而藏不病，故獨取其經於掌後銳骨之端。其餘脈出入屈折，其行之徐疾，皆如手少陰心主之脈行也。故本俞者，皆因其氣之虛實疾徐以取之，是謂因沖而瀉，因衰而補，如是者，邪氣得去，真氣堅固，是謂因天之序。","sortOrder":8},
  {"id":"s_work_hdnk_150_9","chapterId":"ch_work_hdnk_150","text":"黃帝曰：持針縱舍奈何？岐伯曰：必先明知十二經脈之本末，皮膚之寒熱，脈之盛衰滑澀。其脈滑而盛者，病日進；虛而細者，久以持；大以澀者，為痛痺。陰陽如一者，病難治。其本末尚熱者，病尚在；其熱以衰者，其病亦去矣。持其尺，察其肉之堅脆，大小滑澀，寒溫燥濕。因視目之五色，以知五臟，而決死生。視其血脈，察其色，以知其寒熱痛痺。","sortOrder":9},
  {"id":"s_work_hdnk_150_10","chapterId":"ch_work_hdnk_150","text":"黃帝曰：持針縱舍，餘未得其意也。岐伯曰：持針之道，欲端以正，安以靜。先知虛實而行疾徐。左手執骨，右手循之。無與肉果。瀉欲端以正，補必閉膚。輔針導氣，邪得淫泆，真氣得居。","sortOrder":10},
  {"id":"s_work_hdnk_150_11","chapterId":"ch_work_hdnk_150","text":"黃帝曰：扞皮開腠理奈何？岐伯曰：因其分肉，左別其膚，微內而徐端之，適神不散，邪氣得去。","sortOrder":11},
  {"id":"s_work_hdnk_150_12","chapterId":"ch_work_hdnk_150","text":"黃帝問於岐伯曰：人有八虛，各何以候？岐伯答曰：以候五臟。黃帝曰：候之奈何？岐伯曰：肺心有邪，其氣留於兩肘；肝有邪，其氣流於兩腋；脾有邪，其氣留於兩髀；腎有邪，其氣留於兩膕。凡此八虛者，皆機關之室，真氣之所過，血絡之所遊。邪氣惡血，固不得住留。住留則傷筋絡骨節；機關不得屈伸，故痀攣也。","sortOrder":12},
  {"id":"s_work_hdnk_151_1","chapterId":"ch_work_hdnk_151","text":"通天第七十二","sortOrder":1},
  {"id":"s_work_hdnk_151_2","chapterId":"ch_work_hdnk_151","text":"黃帝問於少師曰：餘嘗聞人有陰陽，何謂陰人？何謂陽人？少師曰：天地之間，六合之內，不離於五，人亦應之，非徒一陰一陽而已也，而略言耳，口弗能遍明也。黃帝曰：願略聞其意，有賢人聖人，心能備而行之乎？少師曰：蓋有太陰之人，少陰之人，太陽之人，少陽之人，陰陽和平之人。凡五人者，其態不同，其筋骨氣血各不等。","sortOrder":2},
  {"id":"s_work_hdnk_151_3","chapterId":"ch_work_hdnk_151","text":"黃帝曰：其不等者，可得聞乎？少師曰：太陰之人，貪而不仁，下齊湛湛，好內而惡出，心和而不發，不務於時，動而後之，此太陰之人也。","sortOrder":3},
  {"id":"s_work_hdnk_151_4","chapterId":"ch_work_hdnk_151","text":"少陰之人，小貪而賊心，見人有亡，常若有得，好傷好害，見人有榮，乃反慍怒，心疾而無恩，此少陰之人也。","sortOrder":4},
  {"id":"s_work_hdnk_151_5","chapterId":"ch_work_hdnk_151","text":"太陽之人，居處於於，好言大事，無能而虛說，志發乎四野，舉措不顧是非，為事如常自用，事雖敗，而常無悔，此太陽之人也。","sortOrder":5},
  {"id":"s_work_hdnk_151_6","chapterId":"ch_work_hdnk_151","text":"少陽之人，諟諦好自責，有小小官，則高自宜，好為外交，而不內附，此少陽之人也。","sortOrder":6},
  {"id":"s_work_hdnk_151_7","chapterId":"ch_work_hdnk_151","text":"陰陽和平之人，居處安靜，無為懼懼，無為欣欣，婉然從物，或與不爭，與時變化，尊則謙謙，譚而不治，是謂至治。","sortOrder":7},
  {"id":"s_work_hdnk_151_8","chapterId":"ch_work_hdnk_151","text":"古之善用針艾者，視人五態，乃治之。盛者瀉之，虛者補之。","sortOrder":8},
  {"id":"s_work_hdnk_151_9","chapterId":"ch_work_hdnk_151","text":"黃帝曰：治人之五態奈何？少師曰：太陰之人，多陰而無陽，其陰血濁，其衛氣澀，陰陽不和，緩筋而厚皮，不之疾瀉，不能移之。","sortOrder":9},
  {"id":"s_work_hdnk_151_10","chapterId":"ch_work_hdnk_151","text":"少陰之人，多陰少陽，小胃而大腸，六腑不調，其陽明脈小，而太陽脈大，必審調之，其血易脫，其氣易敗也。","sortOrder":10},
  {"id":"s_work_hdnk_151_11","chapterId":"ch_work_hdnk_151","text":"太陽之人，多陽而少陰，必謹調之，無脫其陰，而瀉其陽。陽重脫者易狂，陰陽皆脫者，暴死，不知人也。","sortOrder":11},
  {"id":"s_work_hdnk_151_12","chapterId":"ch_work_hdnk_151","text":"少陽之人，多陽少陰，經小而絡大，血在中而氣外，實陰而虛陽。獨瀉其絡脈，則強氣脫而疾，中氣不足，病不起也。","sortOrder":12},
  {"id":"s_work_hdnk_151_13","chapterId":"ch_work_hdnk_151","text":"陰陽和平之人，其陰陽之氣和，血脈調，謹診其陰陽，視其邪正，安容儀，審有餘不足，盛則瀉之，虛則補之，不盛不虛，以經取之，此所以調陰陽，別五態之人者也。","sortOrder":13},
  {"id":"s_work_hdnk_151_14","chapterId":"ch_work_hdnk_151","text":"黃帝曰：夫五態之人者，相與毋故，卒然新會，未知其行也，何以別之？少師答曰：眾人之屬，不知五態之人者，故五五二十五人，而五態之人不與焉。五態之人，尤不合於眾者也。黃帝曰：別五態之人，奈何？少師曰：太陰之人，其狀黮黮然黑色，念然下意，臨臨然長大，膕然未僂，此太陰之人也。","sortOrder":14},
  {"id":"s_work_hdnk_151_15","chapterId":"ch_work_hdnk_151","text":"少陰之人，其狀清然竊然，固以陰賊，立而躁嶮，行而似伏，此少陰之人也。","sortOrder":15},
  {"id":"s_work_hdnk_151_16","chapterId":"ch_work_hdnk_151","text":"太陽之人，其狀軒軒儲儲，反身折膕，此太陽之人也。","sortOrder":16},
  {"id":"s_work_hdnk_151_17","chapterId":"ch_work_hdnk_151","text":"少陽之人，其狀立則好仰，行則好搖，其兩臂兩肘，則常出於背，此少陽之人也。","sortOrder":17},
  {"id":"s_work_hdnk_151_18","chapterId":"ch_work_hdnk_151","text":"陰陽和平之人，其狀委委然，隨隨然，顒顒然，愉愉然，〈目旋〉〈目旋〉然，豆豆然，眾人皆曰君子，此陰陽和平之人也。","sortOrder":18},
  {"id":"s_work_hdnk_152_1","chapterId":"ch_work_hdnk_152","text":"官能第七十三","sortOrder":1},
  {"id":"s_work_hdnk_152_2","chapterId":"ch_work_hdnk_152","text":"黃帝問於岐伯曰：餘聞九針於夫子，眾多矣不可勝數，餘推而論之，以為一紀。餘司誦之，子聽其理，非則語餘，請正其道，令可久傳後世無患，得其人乃傳，非其人勿言。岐伯稽首再拜曰：請聽聖王之道。","sortOrder":2},
  {"id":"s_work_hdnk_152_3","chapterId":"ch_work_hdnk_152","text":"黃帝曰：用針之理，必知形氣之所在，左右上下，陰陽表裏，血氣多少，行之逆順，出入之合，謀伐有過。知解結，知補虛瀉實，上下氣門，明通於四海。審其所在，寒熱淋露以輸異處，審於調氣，明於經隧，左右肢絡，盡知其會。寒與熱爭，能合而調之，虛與實鄰，知決而通之，左右不調，把而行之，明於逆順，乃知可治，陰陽不奇，故知起時。審於本末，察其寒熱，得邪所在，萬刺不殆。知官九針，刺道畢矣。","sortOrder":3},
  {"id":"s_work_hdnk_152_4","chapterId":"ch_work_hdnk_152","text":"明於五俞徐疾所在，屈伸出入，皆有條理。言陰與陽，合於五行，五臟六腑，亦有所藏，四時八風，盡有陰陽。各得其位，合於明堂，各處色部，五臟六腑。察其所痛，左右上下，知其寒溫，何經所在。審皮膚之寒溫滑澀，知其所苦，膈有上下，知其氣所在。先得其道，稀而疏之，稍深以留，故能徐入之。大熱在上，推而下之；從上下者，引而去之；視前痛者，常先取之。大寒在外，留而補之；入於中者，從合瀉之。針所不為，灸之所宜。上氣不足，推而揚之；下氣不足，積而從之；陰陽皆虛，火自當之。厥而寒甚，骨廉陷下，寒過於膝，下陵三里。陰絡所過，得之留止，寒入於中，推而行之；經陷下者，火則當之；結絡堅緊，火所治之。不知所苦，兩蹻之下，男陰女陽，良工所禁，針論畢矣。","sortOrder":4},
  {"id":"s_work_hdnk_152_5","chapterId":"ch_work_hdnk_152","text":"用針之服，必有法則，上視天光，下司八正，以辟奇邪，而觀百姓，審於虛實，無犯其邪。是得天之靈，遇歲之虛，救而不勝，反受其殃，故曰必知天忌，乃言針意。","sortOrder":5},
  {"id":"s_work_hdnk_152_6","chapterId":"ch_work_hdnk_152","text":"法於往古，驗於來今，觀於窈冥，通於無窮。麤之所不見，良工之所貴。莫知其形，若神髣彿。","sortOrder":6},
  {"id":"s_work_hdnk_152_7","chapterId":"ch_work_hdnk_152","text":"邪氣之中人也，洒淅動形；正邪之中人也，微先見於色，不知於其身，若有若無，若亡若存，有形無形，莫知其情。是故上工之取氣，乃救其萌芽；下工守其已成，因敗其形。","sortOrder":7},
  {"id":"s_work_hdnk_152_8","chapterId":"ch_work_hdnk_152","text":"是故工之用針也，知氣之所在，而守其門戶，明於調氣，補瀉所在，徐疾之意，所取之處。瀉必用員，切而轉之，其氣乃行，疾而徐出，邪氣乃出，伸而迎之，遙大其穴，氣出乃疾。補必用方，外引其皮，令當其門，左引其樞，右推其膚，微旋而徐推之，必端以正，安以靜，堅心無解，欲微以留，氣下而疾出之，推其皮，蓋其外門，真氣乃存。用針之要，無忘其神。","sortOrder":8},
  {"id":"s_work_hdnk_152_9","chapterId":"ch_work_hdnk_152","text":"雷公問於黃帝曰：針論曰：得其人乃傳，非其人勿言，何以知其可傳？黃帝曰：各得其人，任之其能，故能明其事。雷公曰：願聞官能奈何？黃帝曰：明目者，可使視色；聰耳者，可使聽音；捷疾辭語者，可使傳論；語徐而安靜，手巧而心審諦者，可使行針艾，理血氣而調諸逆順，察陰陽而兼諸方。緩節柔筋而心和調者，可使導引行氣；疾毒言語輕人者，可使唾癰呪病；爪苦手毒，為事善傷者，可使按積抑痺。各得其能，方乃可行，其名乃彰。不得其人，其功不成，其師無名。故曰：得其人乃言，非其人勿傳，此之謂也。手毒者，可使試按龜，置龜於器下，而按其上，五十日而死矣，手甘者，復生如故也。","sortOrder":9},
  {"id":"s_work_hdnk_153_1","chapterId":"ch_work_hdnk_153","text":"論疾診尺第七十四","sortOrder":1},
  {"id":"s_work_hdnk_153_2","chapterId":"ch_work_hdnk_153","text":"黃帝問岐伯曰：餘欲無視色持脈，獨調其尺，以言其病，從外知內，為之奈何？岐伯曰：審其尺之緩急小大滑澀，肉之堅脆，而病形定矣。","sortOrder":2},
  {"id":"s_work_hdnk_153_3","chapterId":"ch_work_hdnk_153","text":"視人之目窠上微癰，如新臥起狀，其頸脈動，時咳，按其手足上，窅而不起者，風水膚脹也。","sortOrder":3},
  {"id":"s_work_hdnk_153_4","chapterId":"ch_work_hdnk_153","text":"尺膚滑，其淖澤者，風也。尺肉弱者，解併，安臥脫肉者，寒熱，不治。尺膚滑而澤脂者，風也。尺膚澀者，風痺也。尺膚麤如枯魚之鱗者，水泆飲也。尺膚熱甚，脈盛躁者，病溫也，其脈甚而滑者，病且出也。尺膚寒，其脈小者，泄、少氣。尺膚炬然，先熱後寒者，寒熱也；尺膚先寒，久大之而熱者，亦寒熱也。","sortOrder":4},
  {"id":"s_work_hdnk_153_5","chapterId":"ch_work_hdnk_153","text":"肘所獨熱者，腰以上熱；手所獨熱者，腰以下熱。肘前獨熱者，膺前熱；肘後獨熱者，肩背熱。臂中獨熱者，腰腹熱；肘後麤以下三四寸熱者，腸中有蟲。掌中熱者，腹中熱；掌中寒者，腹中寒。魚上白肉有青血脈者，胃中有寒。","sortOrder":5},
  {"id":"s_work_hdnk_153_6","chapterId":"ch_work_hdnk_153","text":"尺炬然熱，人迎大者，當本血；尺堅大，脈小甚，少氣，免有加，立死。","sortOrder":6},
  {"id":"s_work_hdnk_153_7","chapterId":"ch_work_hdnk_153","text":"目赤色者病在心，白在肺，青在肝，黃在脾，黑在腎。黃色不可名者，病在胸中。","sortOrder":7},
  {"id":"s_work_hdnk_153_8","chapterId":"ch_work_hdnk_153","text":"診目痛，赤脈從上下者，太陽病；從下上者，陽明病；從外走內者，少陽病。","sortOrder":8},
  {"id":"s_work_hdnk_153_9","chapterId":"ch_work_hdnk_153","text":"診寒熱，赤脈上下至瞳子，見一脈一歲死；見一脈半，一歲半死；見二脈，二歲死；見二脈半，二歲半死；見三脈，三歲死。","sortOrder":9},
  {"id":"s_work_hdnk_153_10","chapterId":"ch_work_hdnk_153","text":"診齲齒痛，按其陽之來，有過者獨熱，在左左熱，在右右熱，在上上熱，在下下熱。","sortOrder":10},
  {"id":"s_work_hdnk_153_11","chapterId":"ch_work_hdnk_153","text":"診血脈者，多赤多熱，多青多痛，多黑為久痺，多赤、多黑、多青皆見者，寒熱。","sortOrder":11},
  {"id":"s_work_hdnk_153_12","chapterId":"ch_work_hdnk_153","text":"身痛而色微黃，齒垢黃，爪甲上黃，黃疸也。安臥小便黃赤，脈小而澀者不嗜食。","sortOrder":12},
  {"id":"s_work_hdnk_153_13","chapterId":"ch_work_hdnk_153","text":"人病，其寸口之脈，與人迎之脈小大等，及其浮沉等者，病難已也。","sortOrder":13},
  {"id":"s_work_hdnk_153_14","chapterId":"ch_work_hdnk_153","text":"女子手少陰脈動甚者妊子。","sortOrder":14},
  {"id":"s_work_hdnk_153_15","chapterId":"ch_work_hdnk_153","text":"嬰兒病，其頭毛皆逆上者必死。耳間青脈起者掣痛。大便赤瓣飧泄，脈小者，手足寒，難已；飧泄，脈小，手足溫，泄易也。","sortOrder":15},
  {"id":"s_work_hdnk_153_16","chapterId":"ch_work_hdnk_153","text":"四時之變，寒暑之勝，重陰必陽，重陽必陰；故陰主寒，陽主熱，故寒甚則熱，熱甚則寒，故曰寒生熱，熱生寒，此陰陽之變也。","sortOrder":16},
  {"id":"s_work_hdnk_153_17","chapterId":"ch_work_hdnk_153","text":"故曰：冬傷於寒，春生病熱；春傷於風，夏生飧泄腸僻，夏傷於暑，秋生瘧；秋傷於濕，冬生咳嗽。是謂四時之序也。","sortOrder":17},
  {"id":"s_work_hdnk_154_1","chapterId":"ch_work_hdnk_154","text":"刺節真邪第七十五","sortOrder":1},
  {"id":"s_work_hdnk_154_2","chapterId":"ch_work_hdnk_154","text":"黃帝問於岐伯曰：餘聞刺有五衛，奈何？岐伯曰：固有五衛，一曰振埃，二曰發蒙，三曰去爪，四曰徹衣，五曰解惑。黃帝曰：夫子言五衛，餘未知其意。岐伯曰：振埃者，刺外經去陽病也；發蒙者，刺腑俞，去腑病也；去爪者，刺關節肢絡也；徹衣者，盡刺諸陽之奇俞也；解惑者，盡知調陰陽，補瀉有餘不足，相傾移也。","sortOrder":2},
  {"id":"s_work_hdnk_154_3","chapterId":"ch_work_hdnk_154","text":"黃帝曰：刺衛言振埃，夫子乃言刺外經，去陽病，餘不知其所謂也。願卒聞之。岐伯曰：振埃者，陽氣大逆，上滿於胸中，憤瞋肩息，大氣逆上，喘喝坐伏，病惡埃煙，飼不得息，請言振埃，尚疾於振埃。黃帝曰：善。取之何如？岐伯曰：取之天容。黃帝曰：其咳上氣窮拙胸痛者，取之奈何？岐伯曰：取之廉泉。黃帝曰：取之有數乎？岐伯曰：取天容者，無過一里，取廉泉者，血變而止。帝曰：善哉。","sortOrder":3},
  {"id":"s_work_hdnk_154_4","chapterId":"ch_work_hdnk_154","text":"黃帝曰：刺衛言發蒙，餘不得其意。夫發蒙者，耳無所聞，目無所見，夫子乃言刺腑俞，去腑病，何輸使然，願聞其故。岐伯曰：妙乎哉問也。此刺之大約，針之極也，神明之類也，口說書卷，猶不能及也，請言發蒙耳，尚疾於發蒙也。黃帝曰：善。願卒聞之。岐伯曰：刺此者，必於日中，刺其聽宮，中其眸子，聲聞於耳，此其輸也。黃帝曰：善。何謂聲聞於耳？岐伯曰：刺邪以手堅按其兩鼻竅，而疾偃其聲，必應於針也。黃帝曰：善。此所謂弗見為之，而無目視，見而取之，神明相得者也。","sortOrder":4},
  {"id":"s_work_hdnk_154_5","chapterId":"ch_work_hdnk_154","text":"黃帝曰：刺衛言去爪，夫子乃言刺關節肢絡，願卒聞之。岐伯曰：腰脊者，身之大關節也；肢脛者，人之管以趨翔也；莖垂者，身中之機，陰精之候，津液之道也。故飲食不節，喜怒不時，津液內溢，乃下留於睪，血道不通，日大不休，俛仰不便，趨翔不能。此病榮然有水，不上不下，鈹石所取，形不可匿，常不得蔽，故命曰去爪。帝曰：善。","sortOrder":5},
  {"id":"s_work_hdnk_154_6","chapterId":"ch_work_hdnk_154","text":"黃帝曰：刺衛言徹衣，夫子乃言盡刺諸陽之奇俞，未有常處也。願卒聞之。岐伯曰：是陽氣有餘，而陰氣不足，陰氣不足則內熱，陽氣有餘則外熱，內熱相搏，熱於懷炭，外畏綿帛近，不可近身，又不可近席。腠理閉塞，則汗不出，舌焦唇槁，臘幹益燥，飲食不讓美惡。黃帝曰：善。取之奈何？岐伯曰：取之於其天府大杼三痕，又刺中膂，以去其熱，補足手太陰，以去其汗，熱去汗稀，疾於徹衣。黃帝曰：善。","sortOrder":6},
  {"id":"s_work_hdnk_154_7","chapterId":"ch_work_hdnk_154","text":"黃帝曰：刺衛言解惑，夫子乃言盡知調陰陽，補瀉有餘不足，相傾移也，惑何以解之？岐伯曰：大風在身，血脈偏虛，虛者不足，實者有餘，輕重不得，傾側宛伏，不知東西，不知南北，乍上乍下，乍反乍復，顛倒無常，甚於迷惑。黃帝曰：善。取之奈何？岐伯曰：瀉其有餘，補其不足，陰陽平復，用針若此，疾於解惑。黃帝曰：善。請藏之靈蘭之室，不敢妄出也。","sortOrder":7},
  {"id":"s_work_hdnk_154_8","chapterId":"ch_work_hdnk_154","text":"黃帝曰：餘聞刺有五邪，何謂五邪？岐伯曰：病有持癰者，有容大者，有狹小者，有熱者，有寒者，是謂五邪。黃帝曰：刺五邪奈何？岐伯曰：凡刺五邪之方，不過五章，癉熱消滅，腫聚散亡，寒痺益溫，小者益陽；大者必去，請道其方。","sortOrder":8},
  {"id":"s_work_hdnk_154_9","chapterId":"ch_work_hdnk_154","text":"凡刺癰邪，無迎隴，易俗移性。不得膿，脆道更行，去其鄉，不安處所乃散亡，諸陰陽過癰者，取之其輸瀉之。","sortOrder":9},
  {"id":"s_work_hdnk_154_10","chapterId":"ch_work_hdnk_154","text":"凡刺大邪，日以小，泄奪其有餘，乃益虛。剽其通，針其邪，肌肉親視之，毋有反其真，刺諸陽分肉間。","sortOrder":10},
  {"id":"s_work_hdnk_154_11","chapterId":"ch_work_hdnk_154","text":"凡刺小邪，日以大，補其不足，乃無害。視其所在，迎之界，遠近盡至，其不得外侵而行之，乃自費，刺分肉間。","sortOrder":11},
  {"id":"s_work_hdnk_154_12","chapterId":"ch_work_hdnk_154","text":"凡刺熱邪，越而蒼，出遊不歸，乃無病。為開通，辟門戶，使邪得出，病乃已。","sortOrder":12},
  {"id":"s_work_hdnk_154_13","chapterId":"ch_work_hdnk_154","text":"凡刺寒邪，日以溫，徐往徐來，致其神。門戶已閉，氣不分，虛實得調，其氣存也。","sortOrder":13},
  {"id":"s_work_hdnk_154_14","chapterId":"ch_work_hdnk_154","text":"黃帝曰：官針奈何？岐伯曰：刺癰者，用鈹針；刺大者，用鋒針；刺小者，用員利針；刺熱者，用纔針；刺寒者，用毫針也。","sortOrder":14},
  {"id":"s_work_hdnk_154_15","chapterId":"ch_work_hdnk_154","text":"請言解論，與天地相應，與四時相副，人參天地，故可為解。下有漸洳，上生葦蒲，此所以知形氣之多少也。陰陽者，寒暑也，熱則滋雨而在上，根莖少汁，人氣在外，皮膚緩，腠理開，血氣減，汗大泄，皮淖澤。寒則地凍水冰，人氣在中，皮膚致，腠理閉，汗不出，血氣強，肉堅澀。當是之時，善行水者，不能往冰，善穿地者，不能擊凍，善用針者，亦不能取四厥，血脈凝結，堅搏不往來者，亦未可即柔。故行水者，必待天溫，冰釋凍解，而水可行，地可穿也。人脈猶是也。治厥者，必先熨調和其經，掌與腋，肘與腳，項與脊以調之，火氣已通，血脈乃行。然後視其病，脈淖澤者，刺而平之；堅緊者，破而散之，氣下乃止，此所謂以解結者也。","sortOrder":15},
  {"id":"s_work_hdnk_154_16","chapterId":"ch_work_hdnk_154","text":"用針之類，在於調氣，氣積於胃，以通營衛，各行其道。宗氣留於海，其下者，註於氣街，其上者，走於息道。故厥在於足，宗氣不下，脈中之血，凝而留止，弗之火調，弗能取之。","sortOrder":16},
  {"id":"s_work_hdnk_154_17","chapterId":"ch_work_hdnk_154","text":"用針者，必先察其經絡之實虛，切而循之，按而彈之，視其應動者，乃後取之而下之。六經調者，謂之不病，雖病，謂之自已也。一經上實下虛而不通者，此必有橫絡盛加於大經，令之不通，視而瀉之，此所謂解結也。","sortOrder":17},
  {"id":"s_work_hdnk_154_18","chapterId":"ch_work_hdnk_154","text":"上寒下熱，先刺其項太陽，久留之，已刺則熨項與肩胛，令熱下合乃止，此所謂推而上之者也。上熱下寒，視其虛脈而陷之於經絡者，取之，氣下乃止，此所謂引而下之者也。","sortOrder":18},
  {"id":"s_work_hdnk_154_19","chapterId":"ch_work_hdnk_154","text":"大熱遍身，狂而妄見妄聞妄言，視足陽明及大絡取之，虛者補之，血而實者瀉之。因其偃臥，居其頭前，以兩手四指挾按頸動脈，久持之，卷而切，推下至缺盆中，而復止如前，熱去乃止，此所謂推而散之者也。","sortOrder":19},
  {"id":"s_work_hdnk_154_20","chapterId":"ch_work_hdnk_154","text":"黃帝曰：有一脈生數十病者，或痛，或癰，或熱，或寒，或癢，或痺，或不仁，變化無窮，其故何也？岐伯曰：此皆邪氣之所生也。黃帝曰：餘聞氣者，有真氣，有正氣，有邪氣。何謂真氣？岐伯曰：真氣者，所受於天，與穀氣併而充身也。正氣者，正風也，從一方來，非實風，又非虛風也。邪氣者，虛風之賊傷人也，其中人也深，不能自去。正風者，其中人也淺，合而自去，其氣來柔弱，不能勝真氣，故自去。","sortOrder":20},
  {"id":"s_work_hdnk_154_21","chapterId":"ch_work_hdnk_154","text":"虛邪之中人也，洒晰動形，起毫毛而發腠理。其入深，內搏於骨，則為骨痺；搏於筋，則為筋攣；搏於脈中，則為血閉，不通則為癰。搏於肉，與衛氣相搏，陽勝者，則為熱，陰勝者，則為寒。寒則真氣去，去則虛，虛則寒搏於皮膚之間。其氣外發，腠理開，毫毛搖，氣往來行，則為癢。留而不去，則痺。衛氣不行，則為不仁。","sortOrder":21},
  {"id":"s_work_hdnk_154_22","chapterId":"ch_work_hdnk_154","text":"虛邪偏容於身半，其入深，內居榮衛，榮衛稍衰，則真氣去，邪氣獨留，發為偏枯。其邪氣淺者，脈偏痛。","sortOrder":22},
  {"id":"s_work_hdnk_154_23","chapterId":"ch_work_hdnk_154","text":"虛邪之入於身也深，寒與熱相搏，久留而內著，寒勝其熱，則骨疼肉枯；熱勝其寒，則爛肉腐肌為膿，內傷骨，內傷骨為骨蝕。有所疾前筋，筋屈不得伸，邪氣居其間而不反，發為筋溜。有所結，氣歸之，衛氣留之，不得反，津液久留，合而為腸溜。久者，數歲乃成，以手按之柔，已有所結，氣歸之，津液留之，邪氣中之，凝結日以易甚，連以聚居，為昔瘤。以手按之堅，有所結，深中骨，氣因於骨，骨與氣併，日以益大，則為骨疽。有所結，中於肉，宗氣歸之，邪留而不去，有熱則化而為膿，無熱則為肉疽。凡此數氣者，其發無常處，而有常名也。","sortOrder":23},
  {"id":"s_work_hdnk_155_1","chapterId":"ch_work_hdnk_155","text":"衛氣行第七十六","sortOrder":1},
  {"id":"s_work_hdnk_155_2","chapterId":"ch_work_hdnk_155","text":"黃帝問於岐伯曰：願聞衛氣之行，出入之合，何如？岐伯曰：歲有十二月，日有十二辰，子午為經，卯酉為緯。天周二十八宿，而一面七星，四七二十八星。房昴為緯，虛張為經。是故房至畢為陽，昴至心為陰。陽主晝，陰主夜。故衛氣之行，一日一夜五十周於身，晝日行於陽二十五周，夜行於陰二十五周，周於五藏。","sortOrder":2},
  {"id":"s_work_hdnk_155_3","chapterId":"ch_work_hdnk_155","text":"是故平旦陰盡，陽氣出於目，目張則氣上行於頭，循項下足太陽，循背下至小趾之端。其散者，別於目銳眥，下手太陽，下至手小指之間外側。其散者，別於目銳眥，下足少陽，註小趾次趾之間。以上循手少陽之分側，下至小指之間。別者以上至耳前，合於頷脈，註足陽明以下行，至跗上，入五趾之間。其散者，從耳下下手陽明，入大指之間，入掌中。其至於足也，入足心，出內踝，下行陰分，復合於目，故為一周。","sortOrder":3},
  {"id":"s_work_hdnk_155_4","chapterId":"ch_work_hdnk_155","text":"是故日行一舍，人氣行一周與十分身之八；日行二舍，人氣行三周於身與十分身之六；日行三舍，人氣行於身五周與十分身之四；日行四舍，人氣行於身七周與十分身之二；日行五舍，人氣行於身九周；日行六舍，人氣行於身十周與十分身之八；日行七舍，人氣行於身十二周在身與十分身之六；日行十四舍，人氣二十五周於身有奇分與十分身之二，陽盡於陰，陰受氣矣。其始入於陰，常從足少陰註於腎，腎註於心，心註於肺，肺註於肝，肝註於脾，脾復註於腎為周。是故夜行一舍，人氣行於陰藏一周與十分藏之八，亦如陽行之二十五周，而復合於目。陰陽一日一夜，合有奇分十分身之四，與十分藏之二，是故人之所以臥起之時，有早晏者，奇分不盡故也。","sortOrder":4},
  {"id":"s_work_hdnk_155_5","chapterId":"ch_work_hdnk_155","text":"黃帝曰：衛氣之在於身也，上下往來不以期，候氣而刺之，奈何？伯高曰：分有多少，日有長短，春秋冬夏，各有分理，然後常以平旦為紀，以夜盡為始。是故一日一夜，水下百刻，二十五刻者，半日之度也，常如是毋已，日入而止，隨日之長短，各以為紀而刺之。謹候其時，病可與期，失時反候者，百病不治。故曰：刺實者，刺其來也，刺虛者，刺其去也。此言氣存亡之時，以候虛實而刺之，是故謹候氣之所在而刺之，是謂逢時。在於三陽，必候其氣在於陽而刺之，病在於三陰，必候其氣在陰分而刺之。","sortOrder":5},
  {"id":"s_work_hdnk_155_6","chapterId":"ch_work_hdnk_155","text":"水下一刻，人氣在太陽；水下二刻，人氣在少陽；水下三刻，人氣在陽明；水下四刻，人氣在陰分。水下五刻，人氣在太陽；水下六刻，人氣在少陽；水下七刻，人氣在陽明；水下八刻，人氣在陰分。水下九刻，人氣在太陽；水下十刻，人氣在少陽；水下十一刻，人氣在陽明；水下十二刻，人氣在陰分。水下十三刻，人氣在太陽；水下十四刻，人氣在少陽；水下十五刻，人氣在陽明；水下十六刻，人氣在陰分。水下十七刻，人氣在太陽；水下十八刻，人氣在少陽；水下十九刻，人氣在陽明；水下二十刻，人氣在陰分。水下二十一刻，人氣在太陽；水下二十二刻，人氣在少陽；水下二十三刻，人氣在陽明；水下二十四刻，人氣在陰分。水下二十五刻，人氣在太陽，此半日之度也。從房至畢一十四舍水下五十刻，日行半度，回行一舍，水下三刻與七分刻之四。大要曰：常以日之加於宿上也，人氣在太陽，是故日行一舍，人氣行三陽行與陰分，常如是無已，天與地同紀，紛紛紛紛，終而復始，一日一夜水下百刻而盡矣。","sortOrder":6},
  {"id":"s_work_hdnk_156_1","chapterId":"ch_work_hdnk_156","text":"九宮八風第七十七","sortOrder":1},
  {"id":"s_work_hdnk_156_2","chapterId":"ch_work_hdnk_156","text":"太一常以冬至之日，居葉蟄之宮四十六日，明日居天留四十六日，明日居倉門四十六日，明日居陰洛四十五日，明日居天宮四十六日，明日居玄委四十六日，明日居倉果四十六日，明日居新洛四十五日，明日復居葉蟄之宮，曰冬至矣。","sortOrder":2},
  {"id":"s_work_hdnk_156_3","chapterId":"ch_work_hdnk_156","text":"太一日遊，以冬至之日，居葉蟄之宮，數所在日，從一處至九日，復返於一。常如是無已，終而復始。","sortOrder":3},
  {"id":"s_work_hdnk_156_4","chapterId":"ch_work_hdnk_156","text":"太一移日，天必應之以風雨，以其日風雨則吉，歲美民安少病矣。先之則多雨，後之則多汗。太一在冬至之日有變，占在君；太一在春分之日有變，占在相；太一在中宮之日有變，占在吏；太一在秋分之日有變，占在將；太一在夏至之日有變，占在百姓。所謂有變者，太一居五宮之日，病風折樹木，揚沙石，各以其所主，占貴賤。因視風所從來而占之，風從其所居之鄉來為實風，主生，長養萬物；從其沖後來為虛風，傷人者也，主殺，主害者。謹候虛風而避之，故聖人日避虛邪之道，如避矢石然，邪弗能害，此之謂也。","sortOrder":4},
  {"id":"s_work_hdnk_156_5","chapterId":"ch_work_hdnk_156","text":"是故太一入徙立於中宮，乃朝八風，以占吉凶也。風從南方來，名曰大弱風，其傷人也，內舍於心，外在於脈，氣主熱。風從西南方來，名曰謀風，其傷人也，內舍於脾，外在於肌，其氣主為弱。風從西方來，名曰剛風，其傷人也，內舍於肺，外在於皮膚，其氣主為燥。風從西北方來，名曰折風，其傷人也，內舍於小腸，外在於手太陽脈，脈絕則溢，脈閉則結不通，善暴死。風從北方來，名曰大剛風，其傷人也，內舍於腎，外在於骨與肩背之膂筋，其氣主為寒也。風從東北方來，名曰凶風，其傷人也，內舍於大腸，外在於兩脅腋骨下及肢節。風從東方來，名曰嬰兀風，其傷人也，內舍於肝，外在於筋紐，其氣主為身濕。風從東南方來，名曰弱風，其傷人也，內舍於胃，外在肌肉，其氣主體重。此八風皆從其虛之鄉來，乃能病人。三虛相搏，則為暴病卒死。兩實一虛，病則為淋露寒熱。犯其兩濕之地，則為痿。故聖人避風，如避矢石焉。其有三虛而偏中於邪風，則為仆偏枯矣。","sortOrder":5},
  {"id":"s_work_hdnk_157_1","chapterId":"ch_work_hdnk_157","text":"九鍼論第七十八","sortOrder":1},
  {"id":"s_work_hdnk_157_2","chapterId":"ch_work_hdnk_157","text":"黃帝曰：餘聞九針於夫子，眾多博大矣，餘猶不能寤，敢問九針焉生，何因而有名？岐伯曰：九針者，天地之大數也，始於一而終於九。故曰：一以法天，二以法地，三以法人，四以法時，五以法音，六以法律，七以法星，八以法風，九以法野。","sortOrder":2},
  {"id":"s_work_hdnk_157_3","chapterId":"ch_work_hdnk_157","text":"黃帝曰：以針應九之數，奈何？岐伯曰：夫聖人之起天地之數也，一而九之，故以立九野。九而九之，九九八十一，以起黃鍾數焉，以針應數也。","sortOrder":3},
  {"id":"s_work_hdnk_157_4","chapterId":"ch_work_hdnk_157","text":"一者，天也。天者，陽也。五藏之應天者肺，肺者，五藏六府之蓋也，皮者，肺之合也，人之陽也。故為之治針，必以大其頭而銳其末，令無得深入而陽氣出。","sortOrder":4},
  {"id":"s_work_hdnk_157_5","chapterId":"ch_work_hdnk_157","text":"二者，地也。人之所以應土者，肉也。故為之治針，必筩其身而員其末，令無得傷肉分，傷則氣得竭。","sortOrder":5},
  {"id":"s_work_hdnk_157_6","chapterId":"ch_work_hdnk_157","text":"三者，人也。人之所以成生者，血脈也。故為之治針，必大其身而員其末，令可以按脈物陷，以致其氣，令邪氣獨出。","sortOrder":6},
  {"id":"s_work_hdnk_157_7","chapterId":"ch_work_hdnk_157","text":"四者，時也。時者，四時八風之客於經絡之中，為瘤病者也。故為之治針，必筩其身而鋒其末，令可以瀉熱出血，而痼病竭。","sortOrder":7},
  {"id":"s_work_hdnk_157_8","chapterId":"ch_work_hdnk_157","text":"五者，音也。音者，冬夏之分，分於子午，陰與陽別，寒與熱爭，兩氣相搏，合為癰膿者也。故為之治針，必令其末如劍鋒，可以取大膿。","sortOrder":8},
  {"id":"s_work_hdnk_157_9","chapterId":"ch_work_hdnk_157","text":"六者，律也。律者，調陰陽四時而合十二經脈，虛邪客於經絡而為暴痺者也。故為之治針，必令尖如釐，且員其銳，中身微大，以取暴氣。","sortOrder":9},
  {"id":"s_work_hdnk_157_10","chapterId":"ch_work_hdnk_157","text":"七者，星也。星者，人之七竅，邪之所客於經，而為痛痺，合於經絡者也。故為之治針，令尖如蚊虻喙，靜以徐往，微以久留，正氣因之，真邪俱往，出針而養者也。","sortOrder":10},
  {"id":"s_work_hdnk_157_11","chapterId":"ch_work_hdnk_157","text":"八者，風也。風者，人之股肱八節也。八正之虛風，八風傷人，內舍於骨解腰脊節腠理之間為深痺也。故為之治針，必長其身，鋒其末，可以取深邪遠痺。","sortOrder":11},
  {"id":"s_work_hdnk_157_12","chapterId":"ch_work_hdnk_157","text":"九者，野也。野者，人之節解皮膚之間也。淫邪流溢於身，如風水之狀，而留不能過於機關大節者也。故為之治針，令尖如挺，其鋒微員，以取大氣之不能過於關節者也。","sortOrder":12},
  {"id":"s_work_hdnk_157_13","chapterId":"ch_work_hdnk_157","text":"黃帝曰：針之長短有數乎？岐伯曰：一曰鐵針者，取法於巾針，去末寸半，卒銳之，長一寸六分，主熱在頭身也。二曰員針，取法於絮針，其身而卵其鋒，長一寸六分，主治分間氣。三曰提針，取法於黍粟之銳，長三寸半，主按脈取氣，令邪出。四曰鋒針，取法於絮針，其身，鋒其末，長一寸六分，主癰熱出血。五曰鈹針，取法於劍鋒，廣二分半，長四寸，主大癰膿，兩熱爭者也。六曰員利針，取法於釐針，微大其末，反小其身，令可深內也，長一寸六分。主取癰痺者也。七曰毫針，取註於毫毛，長一寸六分，主寒熱痛痺在絡者也。八曰長針，取法於綦針，長七寸，主取深邪遠痺者也。九曰大針，取法於鋒針，其鋒微員，長四寸，主取大氣不出關節者也。針形畢矣，此九針大小長短法也。","sortOrder":13},
  {"id":"s_work_hdnk_157_14","chapterId":"ch_work_hdnk_157","text":"黃帝曰：願聞身形，應九野，奈何？岐伯曰：請言身形之應九野也，左足應立春，其日戊寅己丑。左脅應春分，其日乙卯。左手應立夏，其日戊辰己巳。膺喉首頭應夏至，其日丙午。右手應立秋，其中戊申己末。右脅應秋分，其日辛酉。右足應立冬，其日戊戌己亥。腰尻下竅應冬至，其日壬子。六腑下三臟應中州，其大禁，大禁太一所在之日，及諸戊己。凡此九者，善候八正所在之處。所主左右上下身體有癰腫者，欲治之，無以其所直之日潰治之，是謂天忌日也。","sortOrder":14},
  {"id":"s_work_hdnk_157_15","chapterId":"ch_work_hdnk_157","text":"形東志苦，病生於脈，治之於灸刺。形苦志東，病生於筋，治之以熨引。形東志東，病生於肉，治之以針石。形苦志苦，病生於咽喝，治之以甘藥。形數驚恐，筋脈不通，病生於不仁，治之以按摩謬藥。是謂形。","sortOrder":15},
  {"id":"s_work_hdnk_157_16","chapterId":"ch_work_hdnk_157","text":"五臟氣，心主噫，肺主咳，肝主語，脾主吞，腎主欠。","sortOrder":16},
  {"id":"s_work_hdnk_157_17","chapterId":"ch_work_hdnk_157","text":"六腑氣，膽為怒，胃為氣逆穢，大腸小腸為泄，膀胱不約為遺溺，下焦溢為水。","sortOrder":17},
  {"id":"s_work_hdnk_157_18","chapterId":"ch_work_hdnk_157","text":"五味：酸入肝，辛入肺，苦入心，甘入脾，鹹入腎，淡入胃，是謂五味。","sortOrder":18},
  {"id":"s_work_hdnk_157_19","chapterId":"ch_work_hdnk_157","text":"五併：精氣併肝則憂，併心則喜，併肺則悲，併腎則恐，併脾則畏，是謂五精之氣，併於臟也。","sortOrder":19},
  {"id":"s_work_hdnk_157_20","chapterId":"ch_work_hdnk_157","text":"五惡：肝惡風，心惡熱，肺惡寒，腎惡燥，脾惡濕，此五臟氣所惡也。","sortOrder":20},
  {"id":"s_work_hdnk_157_21","chapterId":"ch_work_hdnk_157","text":"五液：心主汗，肝主泣，肺主涕，腎主唾，脾主液，此五液所出也。","sortOrder":21},
  {"id":"s_work_hdnk_157_22","chapterId":"ch_work_hdnk_157","text":"五勞：久視傷血，久臥傷氣，久坐傷肉，久立傷骨，久行傷筋，此五久勞所病也。","sortOrder":22},
  {"id":"s_work_hdnk_157_23","chapterId":"ch_work_hdnk_157","text":"五走：酸走筋，辛走氣，苦走血，鹹走骨，甘走肉，是謂五走也。","sortOrder":23},
  {"id":"s_work_hdnk_157_24","chapterId":"ch_work_hdnk_157","text":"五裁：病在筋，無食酸；病在氣，無食辛；病在骨，無食鹹；病在血，無食苦；病在肉，無食甘。口嗜而欲食之，不可多也，必自裁也，命曰五裁。","sortOrder":24},
  {"id":"s_work_hdnk_157_25","chapterId":"ch_work_hdnk_157","text":"五發：陰病發於骨，陽病發於血，陰病發於肉，陽病發於冬，陰病發於夏。","sortOrder":25},
  {"id":"s_work_hdnk_157_26","chapterId":"ch_work_hdnk_157","text":"五邪：邪入於陽，則為狂；邪入於陰，則為血癉；邪入於陽，轉則為癲疾；邪入於陰，轉則為瘖；陽入於陰，病靜；陰出之於陽，病喜怒。","sortOrder":26},
  {"id":"s_work_hdnk_157_27","chapterId":"ch_work_hdnk_157","text":"五藏：心藏神，肺藏魄，肝藏魂，脾藏意，腎藏精志也。","sortOrder":27},
  {"id":"s_work_hdnk_157_28","chapterId":"ch_work_hdnk_157","text":"五主：心主脈，肺主皮，肝主筋，脾主肌，腎主骨。","sortOrder":28},
  {"id":"s_work_hdnk_157_29","chapterId":"ch_work_hdnk_157","text":"陽明多血多氣，太陽多血少氣，少陽多氣少血，太陰多血少氣，厥陰多血少氣，少陰多氣少血。故曰刺陽明出血氣，刺太陽出血惡氣，刺少陽出氣惡血，刺太陰出血惡氣，刺厥陰出血惡氣，刺少陰出氣惡血也。","sortOrder":29},
  {"id":"s_work_hdnk_157_30","chapterId":"ch_work_hdnk_157","text":"足陽明太陰為裏表，少陽厥陰為表裏，太陽少陰為表裏，是謂足之陰陽也。手陽明太陰為表裏，少陽心主為表裏，太陽少陰為表裏，是謂手之陰陽也。","sortOrder":30},
  {"id":"s_work_hdnk_158_1","chapterId":"ch_work_hdnk_158","text":"歲露論第七十九","sortOrder":1},
  {"id":"s_work_hdnk_158_2","chapterId":"ch_work_hdnk_158","text":"黃帝問於岐伯曰：經言夏日傷暑，秋病瘧，瘧之發以時，其故何也？岐伯對曰：邪客於風府，病循膂而下，衛氣一日一夜，常大會於風府，其明日日下一節，故其日作晏，此其先客於脊背也。故每至於風府則腠理開，腠理開則邪氣入，邪氣入則病作，此所以日作尚晏也。衛氣之行風府，日下一節，二十一日下至尾底，二十二日入脊內，註於伏沖之脈，其行九日，出於缺盆之中，其氣上行，故其病稍益至。其內搏於五臟，橫連募原，其道遠，其氣深，其行遲，不能日作，故次日乃蓄積而作焉。","sortOrder":2},
  {"id":"s_work_hdnk_158_3","chapterId":"ch_work_hdnk_158","text":"黃帝曰：衛氣每至於風府，腠理乃發，發則邪入焉。其衛氣日下一節，則不當風府，奈何？岐伯曰：風府無常，衛氣之所應，必開其腠理，氣之所舍節，則其府也。","sortOrder":3},
  {"id":"s_work_hdnk_158_4","chapterId":"ch_work_hdnk_158","text":"黃帝曰：善。夫風之與瘧也，相與同類，而風常在，而瘧特以時休，何也？岐伯曰：風氣留其處，瘧氣隨經絡，沉以內搏，故衛氣應，乃作也。帝曰：善。","sortOrder":4},
  {"id":"s_work_hdnk_158_5","chapterId":"ch_work_hdnk_158","text":"黃帝問於少師曰：餘聞四時八風之中人也，故有寒暑，寒則皮膚急而腠理閉；暑則皮膚緩而腠理開。賊風邪氣，因得以入乎？將必須八正虛邪，乃能傷人乎？少師答曰：不然。賊風邪氣之中人也，不得以時，然必因其開也，其入深，其內極病，其病人也，卒暴。因其閉也，其入淺以留，其病也，徐以遲。","sortOrder":5},
  {"id":"s_work_hdnk_158_6","chapterId":"ch_work_hdnk_158","text":"黃帝曰：有寒溫和適，腠理不開，然有卒病者，其故何也？少師答曰：帝弗知邪入乎。雖平居其腠理開閉緩急，其故常有時也。黃帝曰：可得聞乎？少師曰：人與天地相參也，與日月相應也。故月滿則海水西盛，人血氣積，肌肉充，皮膚致，毛髮堅，腠理郗，煙垢著，當是之時，雖遇賊風，其入淺不深。至其月郭空，則海水東盛，人氣血虛，其衛氣去，形獨居，肌肉減，皮膚縱，腠理開，毛髮殘，膠理薄，煙垢落，當是之時，遇賊風則其入深，其病人也，卒暴。","sortOrder":6},
  {"id":"s_work_hdnk_158_7","chapterId":"ch_work_hdnk_158","text":"黃帝曰：其有卒然暴死暴病者，何也？少師答曰：三虛者，其死暴疾也；得三實者邪不能傷人也。黃帝曰：願聞三虛。少師曰：乘年之衰，逢月之空，失時之和，因為賊風所傷，是謂三虛。故論不知三虛，工反為麤。帝曰：願聞三實。少師曰：逢年之盛，遇月之滿，得時之和，雖有賊風邪氣，不能危之也。黃帝曰：善乎哉論！明乎哉道！請藏之金匱，命曰三實。然，此一夫之論也。","sortOrder":7},
  {"id":"s_work_hdnk_158_8","chapterId":"ch_work_hdnk_158","text":"黃帝曰：願聞歲之所以皆同病者，何因而然？少師曰：此八正之候也。黃帝曰：候之奈何？少師曰：候此者，常以冬至之日，太一立於葉蟄之宮，其至也，天必應之以風雨者矣。風雨從南方來者，為虛風，賊傷人者也。其以夜半至也，萬民皆臥而弗犯也，故其歲民少病。其以晝至者，萬民懈惰而皆中於虛風，故萬民多病。虛邪入客於骨而不發於外，至其立春，陽氣大發，腠理開，因立春之日，風從西方來，萬民又皆中於虛風，此兩邪相搏，經氣結代者矣。故諸逢其風而遇其雨者，命曰遇歲露焉，因歲之和，而少賊風者，民少病而少死。歲多賊風邪氣，寒溫不和，則民多病而死矣。","sortOrder":8},
  {"id":"s_work_hdnk_158_9","chapterId":"ch_work_hdnk_158","text":"黃帝曰：虛邪之風，其所傷貴賤何如，候之奈何？少師答曰：正月朔日，太一居天留之宮，其日西北風，不雨，人多死矣。正月朔日，平旦北風，春，民多死。正月朔日，平旦北風行，民病多者，十有三也。正月朔日，日中北風，夏，民多死。正月朔日，夕時北風，秋，民多死。終日北風，大病死者十有六。正月朔日，風從南方來，命曰旱鄉；從西方來，命曰白骨，將國有殃，人多死亡。正月朔日，風從東方來，發屋，揚沙石，國有大災也。正月朔日，風從東南方行，春有死亡。正月朔日，天和溫不風糶賤，民不病；天寒而風，糶貴，民多病。此所謂候歲之風，殘傷人者也。二月丑不風，民多心腹病；三月戌不溫，民多寒熱；四月已不暑，民多癉病；十月申不寒，民多暴死。諸所謂風者，皆發屋，折樹木，揚沙石起毫毛，發腠理者也。","sortOrder":9},
  {"id":"s_work_hdnk_159_1","chapterId":"ch_work_hdnk_159","text":"大惑論第八十","sortOrder":1},
  {"id":"s_work_hdnk_159_2","chapterId":"ch_work_hdnk_159","text":"黃帝問於岐伯曰：餘嘗上於清冷之台，中階而顧，匍匐而前，則惑。餘私異之，竊內怪之，獨瞑獨視，安心定氣，久而不解。獨博獨眩，披髮長跪，俛而視之，後久之不已也。卒然自上，何氣使然？岐伯對曰：五臟六腑之精氣，皆上註於目而為之精。精之窠為眼，骨之精為瞳子，筋之精為黑眼，血之精為絡，其窠氣之精為白眼，肌肉之精為約束，裹擷筋骨血氣之精，而與脈併為系。上屬於腦，後出於項中。故邪中於項，因逢其身之虛，其入深，則隨眼系以入於腦。入於腦則腦轉，腦轉則引目系急。目系急則目眩以轉矣。邪其精，其精所中不相比也，則精散。精散則視歧，視歧見兩物。目者，五臟六腑之精也，營衛魂魄之所常營也，神氣之所生也。故神勞則魂魄散，志意亂。是故瞳子黑眼法於陰，白眼赤脈法於陽也。故陰陽合傳而精明也。目者，心使也。心者，神之舍也，故神精亂而不轉。卒然見非常處精神魂魄，散不相得，故曰惑也。","sortOrder":2},
  {"id":"s_work_hdnk_159_3","chapterId":"ch_work_hdnk_159","text":"黃帝曰：餘疑其然。餘每之東苑，未曾不惑，去之則復，餘唯獨為東苑勞神乎？何其異也？岐伯曰：不然也。心有所喜，神有所惡，卒然相惑，則精氣亂，視誤，故惑，神移乃復。是故間者為迷，甚者為惑。","sortOrder":3},
  {"id":"s_work_hdnk_159_4","chapterId":"ch_work_hdnk_159","text":"黃帝曰：人之善忘者，何氣使然？岐伯曰：上氣不足，下氣有餘，腸胃實而心肺虛。虛則營衛留於下，久之不以時上，故善忘也。","sortOrder":4},
  {"id":"s_work_hdnk_159_5","chapterId":"ch_work_hdnk_159","text":"黃帝曰：人之善飢而不嗜食者，何氣使然？岐伯曰：精氣併於脾，熱氣留於胃，胃熱則消穀，穀消故善飢。胃氣逆上，則胃脘寒，故不嗜食也。","sortOrder":5},
  {"id":"s_work_hdnk_159_6","chapterId":"ch_work_hdnk_159","text":"黃帝曰：病而不得臥者，何氣使然？岐伯曰：衛氣不得入於陰，常留於陽。留於陽則陽氣滿，陽氣滿則陽蹻盛，不得入於陰則陰氣虛，故目不瞑矣。","sortOrder":6},
  {"id":"s_work_hdnk_159_7","chapterId":"ch_work_hdnk_159","text":"黃帝曰：病目而不得視者，何氣使然？岐伯曰：衛氣留於陰，不得行於陽，留於陰則陰氣盛，陰氣盛則陰蹻滿，不得入於陽則陽氣虛，故目閉也。","sortOrder":7},
  {"id":"s_work_hdnk_159_8","chapterId":"ch_work_hdnk_159","text":"黃帝曰：人之多臥者，何氣使然？岐伯曰：此人腸胃大而皮膚濕，而分肉不解焉。腸胃大則衛氣留久；皮膚濕則分肉不解，其行遲。夫衛氣者，晝日常行於陽，夜行於陰，故陽氣盡則臥，陰氣盡則寤。故腸胃大，則衛氣行留久；皮膚濕，分肉不解，則行遲。留於陰也久，其氣不清，則欲瞑，故多臥矣。其腸胃小，皮膚滑以緩，分肉解利，衛氣之留於陽也久，故少瞑焉。","sortOrder":8},
  {"id":"s_work_hdnk_159_9","chapterId":"ch_work_hdnk_159","text":"黃帝曰：其非常經也，卒然多臥者，何氣使然？岐伯曰：邪氣留於上焦，上焦閉而不通，已食若飲湯，衛氣留久於陰而不行，故卒然多臥焉。","sortOrder":9},
  {"id":"s_work_hdnk_159_10","chapterId":"ch_work_hdnk_159","text":"黃帝曰：善。治此諸邪，奈何？岐伯曰：先其臟腑，誅其小過，後調其氣，盛者瀉之，虛者補之，必先明知其形志之苦樂，定乃取之。","sortOrder":10},
  {"id":"s_work_hdnk_160_1","chapterId":"ch_work_hdnk_160","text":"癰疽第八十一","sortOrder":1},
  {"id":"s_work_hdnk_160_2","chapterId":"ch_work_hdnk_160","text":"黃帝曰：餘聞腸胃受穀，上焦出氣，以溫分肉，而養骨節，通腠理。中焦出氣如露，上註谿穀，而滲孫脈，津液和調，變化而赤為血。血和則孫脈先滿溢，乃註於絡脈，皆盈，乃註於經脈，陰陽已張，因息乃行。行有經紀，周有道理，與天合同，不得休止。切而調之，從虛去實，瀉則不足，疾則氣減，留則先後。從實去虛，補則有餘，血氣已調，形氣乃持。餘已知血氣之平與不平，未知癰疽之所從生，成敗之時，死生之期，有遠近，何以度之，可得聞乎？","sortOrder":2},
  {"id":"s_work_hdnk_160_3","chapterId":"ch_work_hdnk_160","text":"岐伯曰：經脈留行不止，與天同度，與地合紀。故天宿失度，日月薄蝕；地經失紀，水道流溢，草萓不成，五穀不殖；徑路不通，民不往來，巷聚邑居，則別離異處。血氣猶然，請言其故。夫血脈營衛，周流不休，上應星宿，下應經數。寒邪客於經絡之中，則血泣，血泣則不通，不通則衛氣歸之，不得復反，故癰腫。寒氣化為熱，熱勝則腐肉，肉腐則為膿。膿不瀉則爛筋，筋爛則傷骨，骨傷則髓消，不當骨空，不得泄瀉，血枯空虛，則筋骨肌肉不相榮，經脈敗漏，熏於五臟，藏傷故死矣。","sortOrder":3},
  {"id":"s_work_hdnk_160_4","chapterId":"ch_work_hdnk_160","text":"黃帝曰：願盡聞癰疽之形，與忌曰名。岐伯曰：癰發於嗌中，名曰猛疽。猛疽不治，化為膿，膿不瀉，塞咽，半日死。其化為膿者，瀉則合豕膏，冷食，三日而已。","sortOrder":4},
  {"id":"s_work_hdnk_160_5","chapterId":"ch_work_hdnk_160","text":"發於頸，名曰夭疽。其癰大以赤黑，不急治，則熱氣下入淵腋，前傷任脈，內熏肝肺。熏肝肺，十餘日而死矣。","sortOrder":5},
  {"id":"s_work_hdnk_160_6","chapterId":"ch_work_hdnk_160","text":"陽留大發，消腦留項，名曰腦爍。其色不樂，項痛而如刺以針。煩心者，死不可治。","sortOrder":6},
  {"id":"s_work_hdnk_160_7","chapterId":"ch_work_hdnk_160","text":"發於肩及臑，名曰疵癰。其狀赤黑，急治之，此令人汗出至足，不害五臟。癰發四五日，逞〈火苪〉之。","sortOrder":7},
  {"id":"s_work_hdnk_160_8","chapterId":"ch_work_hdnk_160","text":"發於腋下赤堅者，名曰米疽。治之以砭石，欲細而長，疏砭之，塗以豕膏，六日已，勿裹之。其癰堅而不潰者，為馬刀挾癭，急治之。","sortOrder":8},
  {"id":"s_work_hdnk_160_9","chapterId":"ch_work_hdnk_160","text":"發於胸，名曰井疽。其狀如大豆，三四日起，不早治，下入腹，不治，七日死矣。","sortOrder":9},
  {"id":"s_work_hdnk_160_10","chapterId":"ch_work_hdnk_160","text":"發於膺，名曰甘疽。色青，其狀如穀實{艹〈舌瓜〉}{艹〈婁瓜〉}，常苦寒熱，急治之，去其寒熱，十歲死，死後出膿。","sortOrder":10},
  {"id":"s_work_hdnk_160_11","chapterId":"ch_work_hdnk_160","text":"發於脅，名曰敗疵。敗疵者，女子之病也，灸之，其病大癰膿，治之，其中乃有生肉，大如赤小豆，坐陵翹草根各一升，以水一斗六升煮之，竭為取三升，則強飲厚衣，坐於釜上，令汗出至足已。","sortOrder":11},
  {"id":"s_work_hdnk_160_12","chapterId":"ch_work_hdnk_160","text":"發於股脛，名曰股脛疽。其狀不甚變，而癰膿搏骨，不急治，三十日死矣。","sortOrder":12},
  {"id":"s_work_hdnk_160_13","chapterId":"ch_work_hdnk_160","text":"發於尻，名曰銳疽。其狀赤堅大，急治之，不治，三十日死矣。","sortOrder":13},
  {"id":"s_work_hdnk_160_14","chapterId":"ch_work_hdnk_160","text":"發於股陰，名曰赤施。不急治，六十日死。在兩股之內，不治，十日而當死。","sortOrder":14},
  {"id":"s_work_hdnk_160_15","chapterId":"ch_work_hdnk_160","text":"發於膝，名曰疵癰。其狀大，癰色不變，寒熱，如堅石，勿石，石之者死，須其柔，乃石之者，生。","sortOrder":15},
  {"id":"s_work_hdnk_160_16","chapterId":"ch_work_hdnk_160","text":"諸癰疽之發於節而相應者，不可治也。發於陽者，百日死；發於陰者，三十日死。","sortOrder":16},
  {"id":"s_work_hdnk_160_17","chapterId":"ch_work_hdnk_160","text":"發於脛，名曰兔嚙，其狀赤至骨，急治之，不治害人也。","sortOrder":17},
  {"id":"s_work_hdnk_160_18","chapterId":"ch_work_hdnk_160","text":"發於內踝，名曰走緩。其狀癰也，色不變，數石其輸，而止其寒熱，不死。","sortOrder":18},
  {"id":"s_work_hdnk_160_19","chapterId":"ch_work_hdnk_160","text":"發於足上下，名曰四淫。其狀大癰，急治之，百日死。","sortOrder":19},
  {"id":"s_work_hdnk_160_20","chapterId":"ch_work_hdnk_160","text":"發於足傍，名曰厲癰。其狀不大，初如小指，發，急治之，去其黑者；不消輒益，不治，百日死。","sortOrder":20},
  {"id":"s_work_hdnk_160_21","chapterId":"ch_work_hdnk_160","text":"發於足趾，名脫癰。其狀赤黑，死不治；不赤黑，不死。不衰，急斬之，不則死矣。","sortOrder":21},
  {"id":"s_work_hdnk_160_22","chapterId":"ch_work_hdnk_160","text":"黃帝曰：夫子言癰疽，何以別之？岐伯曰：營衛稽留於經脈之中，則血泣而不行，不行則衛氣從之而不通，壅遏而不得行，故熱。大熱不止，熱勝，則肉腐，肉腐則為膿。然不能陷，骨髓不為焦枯，五臟不為傷，故命曰癰。","sortOrder":22},
  {"id":"s_work_hdnk_160_23","chapterId":"ch_work_hdnk_160","text":"黃帝曰：何謂疽？岐伯曰：熱氣淳盛，下陷肌膚，筋髓枯，內連五臟，血氣竭，當其癰下，筋骨良肉皆無餘，故命曰疽。疽者，上之皮夭以堅，上如牛領之皮。癰者，其皮上薄以澤。此其候也。","sortOrder":23},
];

